local VERSION = "1.0.0"
-- the label users see (menu, watermark, site). VERSION stays the build number: update ordering compares it
local PUBLIC_VERSION = "1.0.0"
-- Max has its own public number (site/maxine.lua MAX_VERSION says the same); a Max copy shows this one
local MAX_PUBLIC_VERSION = "1.0.0"
local RIVALS_GAME_ID = 6035872082

-- getfenv / version / gcinfo are the only routes to what the next few spots need (this script's own
-- environment, the engine build string, the GC byte counter) and none of them has a non-deprecated
-- equivalent, so they are resolved through _G instead of calling the deprecated globals by name
local GETFENV: any = rawget(_G, "getfenv")
local GCINFO: any = rawget(_G, "gcinfo")
local VERSION_FN: any = rawget(_G, "version")
local function gcKb(): number
	if type(GCINFO) == "function" then
		return GCINFO()
	end
	local cg = rawget(_G, "collectgarbage")
	if type(cg) == "function" then
		return cg("count")
	end
	return 0
end

-- executor globals live on getgenv(), not _G
-- executor environment first (getgenv), the script env second, the shared _G last: a game script
-- can plant names in _G, it cannot reach the executor's environment
local function waveGlobal(name: string): any
	local gg = rawget(_G, "getgenv")
	if type(gg) ~= "function" then
		local okG, fromFenv = pcall(function()
			return (GETFENV(0) :: any).getgenv
		end)
		if okG and type(fromFenv) == "function" then
			gg = fromFenv
		end
	end
	if type(gg) == "function" then
		local ok, env = pcall(gg)
		if ok and type(env) == "table" and env[name] ~= nil then
			return env[name]
		end
	end
	local ok, fromEnv = pcall(function()
		return (GETFENV(0) :: any)[name]
	end)
	if ok and fromEnv ~= nil then
		return fromEnv
	end
	local v = rawget(_G, name)
	if v ~= nil then
		return v
	end
	return nil
end

-- every ScreenGui this script owns; the boot sweep and the unloader use the same list
local OUR_GUI_NAMES = { Centerra = true, CenterraHUD = true, CenterraESP = true, CenterraIntro = true, CenterraOpener = true }

local getgenvFn = waveGlobal("getgenv")
local function genv(): any
	if type(getgenvFn) == "function" then
		local ok, env = pcall(getgenvFn)
		if ok and type(env) == "table" then
			return env
		end
	end
	return _G
end

do
	local g = genv()
	-- Every new execution replaces the running instance (old one is unloaded below). The only thing
	-- deduplicated is the hop double-fire: AutoExecute and queueonteleport both start the same script
	-- within a couple of seconds of a server hop — neither is a manual open.
	local auto = g.VoltMCP_AutoExec == true or g.CenterraTeleportLoad == true
	-- a copy the site served carries the edition marker (set just above this file): it is the loader's
	-- intended load and is never skipped as a hop double-fire — skipping it is how a Max licence that an
	-- autoexec copy beat to the new server stayed Normal
	local served = g.CenterraEdition ~= nil
	-- a bare copy started automatically (autoexec, the hop reload) for a user whose last load was Max hands
	-- over to the site loader in hop mode (saved key, Max), so Max comes back as Max after a teleport or a
	-- rejoin instead of a bare Normal copy taking its place. A manual inject is never redirected.
		end
	-- init can legitimately take a minute (module waits, data wait): a second automatic start
	-- inside that window is the hop double-fire, not a new load
	if g.CenterraLoadingSince and os.clock() - g.CenterraLoadingSince < 120 and auto and not g.CenterraManualInject and not served then
		warn("[centerra] another instance is loading right now — skipping this one")
		return
	end
	if g.CenterraLoadedAt and os.clock() - g.CenterraLoadedAt < 3 and auto and not g.CenterraManualInject and not served then
		warn(("[centerra] loaded %.1fs ago by the hop loader — skipping duplicate load"):format(os.clock() - g.CenterraLoadedAt))
		return
	end
	g.CenterraManualInject = nil
	g.CenterraTeleportLoad = nil
	g.CenterraLoadingSince = os.clock()
	-- close the old one: its own unloader first, then anything it may have left behind
	for _, key in ipairs({ "CenterraUnload", "RivalsUnload" }) do
		if type(g[key]) == "function" then
			pcall(g[key])
		end
	end
	if type(g.VoltMCP_Unloaders) == "table" and type(g.VoltMCP_Unloaders.centerra) == "function" then
		pcall(g.VoltMCP_Unloaders.centerra)
	end
	pcall(function()
		local pg = game:GetService("Players").LocalPlayer:FindFirstChild("PlayerGui")
		local function sweep(parent: Instance?)
			if not parent then
				return
			end
			for _, ch in ipairs(parent:GetChildren()) do
				if OUR_GUI_NAMES[ch.Name] then
					pcall(ch.Destroy, ch)
				end
			end
		end
		sweep(pg)
		pcall(function()
			sweep(game:GetService("CoreGui"))
		end)
		pcall(function()
			local getHui = waveGlobal("gethui") or waveGlobal("get_hidden_gui")
			if type(getHui) == "function" then
				sweep(getHui())
			end
		end)
		pcall(function()
			game:GetService("ContextActionService"):UnbindAction("CenterraMenu")
		end)
		local blur = game:GetService("Lighting"):FindFirstChild("CenterraBlur")
		if blur then
			blur:Destroy()
		end
		local rs = game:GetService("RunService")
		for _, nm in ipairs({ "centerra_camPin", "centerra_thirdPerson", "centerra_bodyYaw", "centerra_aaBody" }) do
			pcall(rs.UnbindFromRenderStep, rs, nm)
		end
		local ws = game:GetService("Workspace")
		for _, nm in ipairs({ "CenterraSelfTest", "CenterraT14Dummy", "CenterraTestTargets", "CenterraTestHitboxes" }) do
			local leftover = ws:FindFirstChild(nm)
			if leftover then
				leftover:Destroy()
			end
		end
	end)
	g.VoltMCP_Unloaders = g.VoltMCP_Unloaders or {}
end

