-- executor namespaces (Synapse-style `syn.*`, Fluxus `fluxus.*`) hold some of the same functions;
-- built inside a closure so the main chunk stays well under Luau's 200-local register cap
local EXEC = (function()
	local synNs = waveGlobal("syn")
	local fluxNs = waveGlobal("fluxus")
	local krnlNs = waveGlobal("krnl")
	local httpNs = waveGlobal("http")
	local function nsFn(ns: any, key: string): any
		return if type(ns) == "table" and type(ns[key]) == "function" then ns[key] else nil
	end
	-- v0.9 compat: the aliases Solara / Xeno / Swift / Velocity / Delta / AWP / Zenith / Seliware / Codex /
	-- Madium / Opiumware / Nexomia ship besides the common names (every feature still gates on EXEC.caps)
	return {
	queueonteleport = waveGlobal("queueonteleport") or waveGlobal("queue_on_teleport") or nsFn(synNs, "queue_on_teleport") or nsFn(fluxNs, "queue_on_teleport") or nsFn(krnlNs, "queue_on_teleport"),
	hookfunction = waveGlobal("hookfunction") or waveGlobal("hookfunc") or waveGlobal("replaceclosure") or waveGlobal("detour_function") or waveGlobal("replacefunction") or nsFn(krnlNs, "hookfunction"),
	hookmetamethod = waveGlobal("hookmetamethod") or waveGlobal("hook_metamethod"),
	getnamecallmethod = waveGlobal("getnamecallmethod") or waveGlobal("get_namecall_method"),
	setnamecallmethod = waveGlobal("setnamecallmethod") or waveGlobal("set_namecall_method"),
	getcallingscript = waveGlobal("getcallingscript") or waveGlobal("get_calling_script") or waveGlobal("getscriptcaller"),
	Drawing = waveGlobal("Drawing"),
	readfile = waveGlobal("readfile") or waveGlobal("read_file"),
	writefile = waveGlobal("writefile") or waveGlobal("write_file"),
	appendfile = waveGlobal("appendfile") or waveGlobal("append_file"),
	isfile = waveGlobal("isfile") or waveGlobal("is_file"),
	delfile = waveGlobal("delfile") or waveGlobal("deletefile") or waveGlobal("delete_file"),
	makefolder = waveGlobal("makefolder") or waveGlobal("createfolder") or waveGlobal("make_folder"),
	request = waveGlobal("request") or waveGlobal("http_request") or waveGlobal("httprequest") or nsFn(synNs, "request") or nsFn(fluxNs, "request") or nsFn(krnlNs, "request") or nsFn(httpNs, "request"),
	setclipboard = waveGlobal("setclipboard") or waveGlobal("toclipboard") or waveGlobal("setrbxclipboard") or waveGlobal("writeclipboard") or nsFn(synNs, "write_clipboard"),
	getclipboard = waveGlobal("getclipboard") or waveGlobal("readclipboard"),
	mouse1press = waveGlobal("mouse1press"),
	mouse1release = waveGlobal("mouse1release"),
	mouse2press = waveGlobal("mouse2press"),
	mouse2release = waveGlobal("mouse2release"),
	keypress = waveGlobal("keypress"),
	keyrelease = waveGlobal("keyrelease"),
	ismoduleloaded = waveGlobal("ismoduleloaded") or waveGlobal("is_module_loaded"),
	getloadedmodules = waveGlobal("getloadedmodules") or waveGlobal("get_loaded_modules"),
	trampoline_call = waveGlobal("trampoline_call"),
	identifyexecutor = waveGlobal("identifyexecutor") or waveGlobal("getexecutorname") or waveGlobal("whatexecutor"),
	getrawmetatable = waveGlobal("getrawmetatable") or waveGlobal("get_raw_metatable"),
	setreadonly = waveGlobal("setreadonly") or waveGlobal("make_writeable") or waveGlobal("makewriteable"),
	newcclosure = waveGlobal("newcclosure") or waveGlobal("new_cclosure"),
	syn = synNs,
	}
end)()

-- hookmetamethod shim: any executor with getrawmetatable can swap the __namecall slot itself.
-- Returns the previous function like the real thing so Hooks.installNamecall does not care.
if type(EXEC.hookmetamethod) ~= "function" and type(EXEC.getrawmetatable) == "function" then
	EXEC.hookmetamethod = function(obj: any, method: string, fn: any): any
		local mt = EXEC.getrawmetatable(obj)
		if type(mt) ~= "table" then
			error("hookmetamethod shim: no metatable")
		end
		local old = rawget(mt, method)
		if type(old) ~= "function" then
			error("hookmetamethod shim: no " .. tostring(method))
		end
		if type(EXEC.setreadonly) == "function" then
			pcall(EXEC.setreadonly, mt, false)
		end
		-- a non-yieldable newcclosure here freezes the client: InvokeServer yields through __namecall
		-- and the executor reports "cannot resume dead coroutine". Plain closure when that wrapper can't yield.
		local hookFn = fn
		if EXEC.ncYields ~= false and type(EXEC.newcclosure) == "function" then
			hookFn = EXEC.newcclosure(fn)
		end
		rawset(mt, method, hookFn)
		if type(EXEC.setreadonly) == "function" then
			pcall(EXEC.setreadonly, mt, true)
		end
		return old
	end
	EXEC.hookmetamethodShim = true
end

-- Volt has no ismoduleloaded; membership in getloadedmodules() is the same fact
if type(EXEC.ismoduleloaded) ~= "function" and type(EXEC.getloadedmodules) == "function" then
	-- keyed by the module instance AND by its full name (see below), so the key type is not just Instance
	local cache: { [any]: boolean } = {}
	local cacheAt = 0
	EXEC.ismoduleloaded = function(inst: Instance): boolean
		if os.clock() - cacheAt > 0.2 then
			cache = {}
			cacheAt = os.clock()
			local ok, list = pcall(EXEC.getloadedmodules)
			if ok and type(list) == "table" then
				for _, m in ipairs(list) do
					cache[m] = true
					-- some executors hand back a different instance than the one in PlayerScripts;
					-- identity compare then stays false forever and inject aborts
					if typeof(m) == "Instance" then
						local okN, full = pcall(m.GetFullName, m)
						if okN and type(full) == "string" then
							cache[full] = true
						end
					end
				end
			end
		end
		if cache[inst] == true then
			return true
		end
		local okN, full = pcall(inst.GetFullName, inst)
		return okN and cache[full] == true
	end
end

local EXECUTOR_NAME = "unknown"
pcall(function()
	if type(EXEC.identifyexecutor) == "function" then
		EXECUTOR_NAME = tostring((EXEC.identifyexecutor()))
	end
end)
-- Volt / Wave capability table (both are supported; features gate on capabilities, never on names)
EXEC.name = EXECUTOR_NAME
EXEC.isVolt = string.lower(EXECUTOR_NAME) == "volt"
EXEC.isWave = string.lower(EXECUTOR_NAME) == "wave"
-- Volt's newcclosure yields, so hookmetamethod is safe there. Other executors often wrap __namecall in a
-- newcclosure that cannot yield: the first RemoteFunction:InvokeServer then freezes the client
-- ("cannot resume dead coroutine"). Do not probe this by actually yielding — that probe itself crashes
-- some executors during inject. Non-Volt namecall stays a plain Lua closure.
EXEC.ncYields = EXEC.isVolt or type(EXEC.newcclosure) ~= "function"
EXEC.raknet = waveGlobal("raknet")
-- v5.3 assets: fonts / icon font / glow sprites load from the workspace through a content URL
EXEC.getcustomasset = waveGlobal("getcustomasset") or waveGlobal("getsynasset") or waveGlobal("get_custom_asset")
EXEC.isfolder = waveGlobal("isfolder") or waveGlobal("is_folder")
EXEC.listfiles = waveGlobal("listfiles") or waveGlobal("list_files")
EXEC.delfolder = waveGlobal("delfolder") or waveGlobal("del_folder") or waveGlobal("deletefolder")
EXEC.hookfunction = EXEC.hookfunction or waveGlobal("hook_function")
EXEC.isfunctionhooked = waveGlobal("isfunctionhooked")
-- no file API at all (some free executors): an in-memory workspace, so configs, the layout and assets still
-- work for the session (nothing survives a rejoin) instead of every save erroring
if type(EXEC.readfile) ~= "function" and type(EXEC.writefile) ~= "function" then
	local mem: { [string]: string } = {}
	local dirs: { [string]: boolean } = {}
	EXEC.readfile = function(p: string): string
		return mem[p] or error("no file " .. tostring(p))
	end
	EXEC.writefile = function(p: string, data: string)
		mem[p] = tostring(data)
	end
	EXEC.appendfile = function(p: string, data: string)
		mem[p] = (mem[p] or "") .. tostring(data)
	end
	EXEC.isfile = function(p: string): boolean
		return mem[p] ~= nil
	end
	EXEC.delfile = function(p: string)
		mem[p] = nil
	end
	EXEC.makefolder = function(p: string)
		dirs[p] = true
	end
	EXEC.isfolder = function(p: string): boolean
		return dirs[p] == true
	end
	EXEC.listfiles = function(p: string): { string }
		local out = {}
		local prefix = tostring(p):gsub("/$", "") .. "/"
		for k in pairs(mem) do
			if k:sub(1, #prefix) == prefix and not k:sub(#prefix + 1):find("/") then
				table.insert(out, k)
			end
		end
		return out
	end
	EXEC.memoryFiles = true
end
EXEC.restorefunction = waveGlobal("restorefunction") or waveGlobal("restorefunc")
EXEC.getrendersteppedlist = waveGlobal("getrendersteppedlist")
-- thread identity control (v5.2: resolved here so EXEC.caps.identity exists from the start — it
-- used to be filled in by §4, after the compat report had already read it)
EXEC.setIdentity = waveGlobal("setthreadidentity") or waveGlobal("setidentity") or waveGlobal("set_thread_identity") or waveGlobal("setthreadcontext")
	or (type(EXEC.syn) == "table" and EXEC.syn.set_thread_identity) or nil
EXEC.getIdentity = waveGlobal("getthreadidentity") or waveGlobal("getidentity") or waveGlobal("get_thread_identity") or waveGlobal("getthreadcontext")
	or (type(EXEC.syn) == "table" and EXEC.syn.get_thread_identity) or nil
EXEC.caps = {
	hooks = type(EXEC.hookfunction) == "function",
	namecall = type(EXEC.hookmetamethod) == "function" and type(EXEC.getnamecallmethod) == "function",
	drawing = EXEC.Drawing ~= nil,
	files = type(EXEC.readfile) == "function" and type(EXEC.writefile) == "function",
	moduleLoaded = type(EXEC.ismoduleloaded) == "function",
	trampoline = type(EXEC.trampoline_call) == "function",
	mouse = type(EXEC.mouse1press) == "function",
	raknet = type(EXEC.raknet) == "table",
	teleportQueue = type(EXEC.queueonteleport) == "function",
	callingScript = type(EXEC.getcallingscript) == "function",
	identity = type(EXEC.setIdentity) == "function",
	request = type(EXEC.request) == "function",
}
-- what this executor cannot do and what that costs, in one place (log at load, Settings → Info)
function EXEC.report(): { string }
	local out = {}
	if not EXEC.caps.hooks then
		table.insert(out, "hookfunction missing → silent aim, skins and every hook are OFF (aimbot / ESP only)")
	end
	if not EXEC.caps.namecall then
		table.insert(out, "hookmetamethod/getnamecallmethod missing → no raycast redirect, remote spy, anti-aim replication rewrite or unowned-skin equip swallow")
	end
	if EXEC.hookmetamethodShim then
		table.insert(out, "hookmetamethod emulated through getrawmetatable")
	end
	if EXEC.ncYields == false then
		table.insert(out, "newcclosure cannot yield → namecall hook is a plain Lua closure (stops the \"cannot resume dead coroutine\" freeze)")
	end
	if not EXEC.caps.drawing then
		table.insert(out, "Drawing missing → ESP, radar, FOV circles and hit markers use the Smooth (GUI) renderer instead")
	end
	if not EXEC.caps.files then
		table.insert(out, "file API missing → settings and skin picks are not saved between sessions")
	end
	if EXEC.memoryFiles then
		table.insert(out, "in-memory files only (no on-disk API) → settings, configs and skins reset when you rejoin")
	end
	if not EXEC.caps.moduleLoaded then
		table.insert(out, "getloadedmodules missing → game modules are required lazily (first use may be delayed)")
	end
	if not EXEC.caps.trampoline then
		table.insert(out, "trampoline_call missing → game calls use the identity drop (fine on most executors)")
	end
	if not EXEC.caps.identity and not EXEC.caps.trampoline then
		table.insert(out, "no thread-identity control → some game calls may fail (\"non-RobloxScript module\") and remotes we fire ourselves may be dropped")
	end
	if not EXEC.caps.teleportQueue then
		table.insert(out, "queue_on_teleport missing → reload the script by hand after every server hop")
	end
	if not EXEC.caps.callingScript then
		table.insert(out, "getcallingscript missing → shot-code detection trusts the trigger window / mouse button only (silent layers act on every long cast while you fire)")
	end
	if not EXEC.caps.request then
		table.insert(out, "request missing → update checks and hop reloads fall back to game:HttpGet (cache-busted per call)")
	end
	if EXEC.caps.files and type(EXEC.listfiles) ~= "function" then
		table.insert(out, "listfiles missing → the config list only shows configs made in this session")
	end
	return out
end

-- everything centerra keeps on disk lives under one workspace folder
local DATA = {
	dir = "centerra",
	-- key = "centerra/key.txt", reserved for KeySlot (nothing reads or writes it yet)
	configs = "centerra/configs",
	state = "centerra/state.json",
	log = "centerra/centerra.log",
	shots = "centerra/shots.json",
	decompiled = "centerra/decompiled",
	intro = "centerra/intro.stamp",
	unloaded = "centerra/unloaded",
	cache = "centerra/cache.lua",
}
-- makefolder for every level of a path; safe to call on every write
function EXEC.mkdirs(path: string)
	if type(EXEC.makefolder) ~= "function" then
		return
	end
	local acc = ""
	for part in string.gmatch(path, "[^/]+") do
		acc = if acc == "" then part else acc .. "/" .. part
		local exists = type(EXEC.isfolder) == "function" and select(2, pcall(EXEC.isfolder, acc)) == true
		if not exists then
			pcall(EXEC.makefolder, acc)
		end
	end
end

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UIS = game:GetService("UserInputService")
local TweenService = game:GetService("TweenService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local HttpService = game:GetService("HttpService")
local Lighting = game:GetService("Lighting")
local GuiService = game:GetService("GuiService")
local Stats = game:GetService("Stats")
local LP: Player = Players.LocalPlayer

local function traceback(err: any): string
	local ok, tb = pcall(debug.traceback, tostring(err), 2)
	return if ok and type(tb) == "string" then tb else tostring(err)
end

-- structured log ring buffer shared with the F9 terminal and the MCP (getgenv().CenterraLogs)
local LOG_MAX = 4000 -- one whole duel (shots, body hand-overs, skip reasons) fits in the ring
local logBuffer: { any } = (function()
	local env = genv()
	env.CenterraLogs = env.CenterraLogs or {}
	return env.CenterraLogs
end)()
local logListeners: { (any) -> () } = {}
local LOG_FILE = DATA.log
local logFilePending: { string } = {}
local logFlushScheduled = false
local logFileBytes = 0
local logFileSeeded = false
local LOG_FILE_MAX = 1024 * 1024 -- truncate the on-disk log to its last 256 KB once it grows past ~1 MB
local function flushLogFile()
	logFlushScheduled = false
	if #logFilePending == 0 then
		return
	end
	local chunk = table.concat(logFilePending)
	table.clear(logFilePending)
	pcall(function()
		local exists = type(EXEC.isfile) == "function" and EXEC.isfile(LOG_FILE)
		if exists and type(EXEC.appendfile) == "function" then
			if not logFileSeeded and type(EXEC.readfile) == "function" then
				logFileSeeded = true
				local okS, cur = pcall(EXEC.readfile, LOG_FILE)
				if okS and type(cur) == "string" then
					logFileBytes = #cur
				end
			end
			EXEC.appendfile(LOG_FILE, chunk)
			logFileBytes += #chunk
			-- rotate rarely (once per ~1 MB): keeps appendfile from growing the log without bound
			if logFileBytes > LOG_FILE_MAX and type(EXEC.readfile) == "function" then
				local okR, all = pcall(EXEC.readfile, LOG_FILE)
				if okR and type(all) == "string" and #all > 256 * 1024 then
					local tail = all:sub(-256 * 1024)
					EXEC.writefile(LOG_FILE, tail)
					logFileBytes = #tail
				end
			end
			return
		end
		EXEC.mkdirs(DATA.dir)
		-- no appendfile: keep the tail of the existing log instead of overwriting it with one flush
		if exists and type(EXEC.readfile) == "function" then
			local okR, old = pcall(EXEC.readfile, LOG_FILE)
			if okR and type(old) == "string" then
				if #old > 512 * 1024 then
					old = old:sub(-256 * 1024)
				end
				chunk = old .. chunk
			end
		end
		EXEC.writefile(LOG_FILE, chunk)
	end)
end

-- ring buffers are trimmed in batches: table.remove(t, 1) shifts the whole array on every line
local function trimRing(t: { any }, max: number)
	local n = #t
	if n <= max + math.max(32, max // 4) then
		return
	end
	local excess = n - max
	table.move(t, excess + 1, n, 1)
	for i = n, max + 1, -1 do
		t[i] = nil
	end
end

local function log(level: string, ...: any)
	local parts = {}
	for i = 1, select("#", ...) do
		parts[i] = tostring(select(i, ...))
	end
	local text = table.concat(parts, " ")
	local entry = { t = os.clock(), level = level, text = text }
	table.insert(logBuffer, entry)
	trimRing(logBuffer, LOG_MAX)
	local msg = ("[centerra][%s] %s"):format(level, text)
	if level == "ERROR" or level == "WARN" then
		warn(msg)
	elseif level ~= "DEBUG" then
		print(msg)
	else
		local st0 = genv().CenterraState
		if st0 and st0.cfg and st0.cfg.debugConsole then
			print(msg)
		end
	end
	for _, fn in ipairs(logListeners) do
		pcall(fn, entry)
	end
	local st = genv().CenterraState
	local toFile = not (st and st.cfg and st.cfg.logToFile == false)
	if toFile and type(EXEC.writefile) == "function" then
		-- batched: file I/O never runs on the frame that produced the line (rapid fire logs a lot)
		table.insert(logFilePending, ("[%s][%s] %s\n"):format(os.date("%H:%M:%S"), level, text))
		trimRing(logFilePending, LOG_MAX) -- a busy half second must not lose lines before the flush
		if not logFlushScheduled then
			logFlushScheduled = true
			task.delay(0.5, flushLogFile)
		end
	end
end

-- toast when the HUD exists, Roblox notification otherwise
local function notify(text: string, duration: number?, kind: string?)
	local st = genv().CenterraState
	if st and type(st.toast) == "function" then
		if pcall(st.toast, text, duration or 3, kind or "info") then
			return
		end
	end
	pcall(function()
		game:GetService("StarterGui"):SetCore("SendNotification", { Title = "centerra", Text = text, Duration = duration or 4 })
	end)
end

local function reportError(stage: string, err: any)
	local s = tostring(err)
	-- err from an xpcall(fn, traceback) handler already carries a stack; don't wrap it a second time
	if not string.find(s, "stack traceback:", 1, true) then
		s = traceback(s)
	end
	log("ERROR", stage .. ":", s)
	notify(stage .. " failed — see console", 8, "error")
end

local function runStep(name: string, fn: () -> ())
	local ok, err = xpcall(fn, traceback)
	if not ok then
		reportError(name, err)
		error("[centerra] " .. name, 0)
	end
	log("INFO", name, "ok")
end

local function safeEnum(enumObj: any, name: any): any
	if type(name) ~= "string" then
		return nil
	end
	local ok, item = pcall(function()
		return enumObj[name]
	end)
	return if ok then item else nil
end

local function clamp(v: any, lo: number, hi: number, default: number): number
	if type(v) ~= "number" or v ~= v then
		return default
	end
	return math.clamp(v, lo, hi)
end

local function rgb(t: any, fallback: Color3?): Color3
	if type(t) == "table" and type(t[1]) == "number" then
		return Color3.fromRGB(t[1], t[2] or 255, t[3] or 255)
	end
	return fallback or Color3.new(1, 1, 1)
end

local function deepClone(v: any): any
	if type(v) ~= "table" then
		return v
	end
	local out = {}
	for k, x in pairs(v) do
		out[k] = deepClone(x)
	end
	return out
end

-- auto-reinject after a server hop: the new Lua state is empty and readfile is sandboxed, so
-- the payload fetches fresh source from the VoltMCP daemon with readfile fallbacks.
-- Started by the centerra loader (genv().CenterraLicense set) there is no daemon on the user's PC:
-- the add-on queues the site loader instead, so the daemon payload, offline cache fetch and update
-- polls below are skipped (they only failed, and the localhost HttpGet could stall for a long time).
if type(EXEC.queueonteleport) == "function" and not genv().CenterraTeleportQueued and type(genv().CenterraLicense) ~= "table" then
	genv().CenterraTeleportQueued = true
	pcall(EXEC.queueonteleport, [[
		task.spawn(function()
			repeat task.wait() until game:IsLoaded()
			task.wait(4)
			if getgenv().VoltMCP_AutoExec or getgenv().CenterraUnload then return end
			-- the user unloaded on purpose: the marker survives the hop, genv does not
			if isfile and isfile("centerra/unloaded") then return end
			local src
			local url = "http://127.0.0.1:8866/lua/centerra"
			local req = request or http_request or (syn and syn.request)
			if req then
				pcall(function() src = req({ Url = url, Method = "GET" }).Body end)
			end
			if type(src) ~= "string" or #src < 1000 then
				-- HttpGet caches per URL for the session: a unique query keeps this copy fresh
				pcall(function() src = game:HttpGet(url .. "?t=" .. tostring(os.time())) end)
			end
			if type(src) ~= "string" or #src < 1000 then
				src = nil
				for _, p in ipairs({ "volt-mcp/cache/centerra.lua", "centerra/cache.lua" }) do
					if isfile and isfile(p) then src = readfile(p) break end
				end
			end
			if type(src) == "string" then
				local f, err = loadstring(src, "centerra")
				getgenv().CenterraTeleportLoad = true
				if f then f() else warn("[centerra] auto-reinject compile error: " .. tostring(err)) end
			else
				warn("[centerra] auto-reinject: could not fetch source (is the VoltMCP daemon running?)")
			end
		end)
	]])
end

-- offline copy inside the executor workspace for the fallback above. request() reads the daemon
-- fresh every time; game:HttpGet caches per URL for the whole session and kept writing the first
-- source it ever saw.
if EXEC.writefile then
	pcall(function()
		if type(EXEC.delfile) == "function" and type(EXEC.isfile) == "function" and EXEC.isfile(DATA.unloaded) then
			EXEC.delfile(DATA.unloaded)
		end
	end)
	task.spawn(function()
		if type(genv().CenterraLicense) == "table" then
			return
		end
		pcall(function()
			local src
			local url = "http://127.0.0.1:8866/lua/centerra"
			if type(EXEC.request) == "function" then
				pcall(function()
					local res = EXEC.request({ Url = url, Method = "GET" })
					src = if type(res) == "table" then res.Body else nil
				end)
			end
			if type(src) ~= "string" or #src <= 1000 then
				pcall(function() src = game:HttpGet(url .. "?t=" .. tostring(os.time())) end)
			end
			-- a truncated fetch (daemon restarting, half a file) must never replace a good offline copy
			if type(src) == "string" and #src > 1000 and src:find("CenterraInit", 1, true) and src:find("\nlocal VERSION", 1, true) then
				EXEC.mkdirs(DATA.dir)
				EXEC.writefile(DATA.cache, src)
			end
		end)
	end)
end

