	voidSpamUnder = true, -- the way back lands 6 st under the silent lock inside the floor (autokill Under's spot), not on your spot
	voidSpamUnderRange = 400, -- flat studs from your spot to the lock; farther → your spot
	-- every enemy warped far out for a while: stay out, and now and then show yourself on the map for less time than
	-- any round needs to reach you, so they come out to fight
	voidSpamBait = true,
	voidSpamBaitSpot = "In the floor", -- In the floor (under your spot, behind the slab's face; your spot when it is thin) | Your spot
	voidSpamBaitSec = 0.25, -- s on the map per bait
	voidSpamBaitEvery = 2, -- s between baits (±30 %)
	voidSpamAutoOff = 0, -- s: voidspam switches itself off after this long (0 = never)
	voidSpamHud = true, -- the voidspam timer panel on screen
	-- counters
	counterVoid = true, -- void spammers: keep the lock through the dip, wait over the spot they left, fire the frame they surface
	counterTeleport = true, -- teleporters: prefer them for the moment right after a jump (they are still settling)
	shieldAware = true, -- Riot Shield parts count as cover: origins / hitboxes behind a shield are never chosen
	antiFlash = false, -- drop the Flashbang blind effect client-side
	magicHopOnShot = true, -- jitter hop right after every shot on slow guns (the settle runs inside the cooldown)
	targetPreferVisible = true, -- the lock ranks enemies the server can see from our origin first (a hidden lock is a held trigger)
	autoShootSpam = true, -- automatics: StartShooting every frame like the game's held LMB (exact cooldown edge), not our pulse loop
	-- bounds (OutOfBoundsPart volumes) + noclip
	oobBlock = false, -- IsOutOfBounds → nil + swallow the OutOfBounds remote: the client never reports us out of bounds
	oobMargin = 0.6, -- seconds kept in reserve when a relocation uses a volume's warn+kill budget
	boundsGuard = true, -- relocations refuse destinations a volume would kill (even with the block on)
	safeMaxHeight = 26, -- studs: no relocation rests higher than this above the ground (under the spot or the target)
	noclip = false,
	noclipFloat = true, -- no gravity while noclipping: Space / Ctrl move up / down
	noclipSpeed = 40,
	noclipFollowCamera = false, -- W flies where the camera looks
