	-- origin planner (shared by magic bullet, autokill, backstab, peek)
	originMaxDist = 14, -- preferred shooting distance (studs): inside every gun's spread-immune range
	originInsideWalls = true, -- an origin inside the part that hides the target (the server ray starts inside it and ignores it) — noclip only
	originBelowMap = true, -- follow targets under the map (void hiders), never into a kill volume
	originStick = true, -- keep the last origin while it still works (no flicker)
	originPreferCover = true, -- noclip: prefer an origin INSIDE a wall near the target — our ray exits the part, theirs hits its face
	-- trigger
	autoShootEchoGate = false, -- first shot on a lock waits for the server to echo our rotation (off: the server's ray follows the aim sent WITH the shot)
	autoShootLeadMaxMs = 120, -- never wait longer than this for the echo (the wait is min(this, ping/2 + 40 ms) unless flick AA)
	preAim = true, -- hold the target-facing rotation on the channel before line of sight so the first shot needs no lead
	preAimRange = 140, -- the aim stream starts at the lock, so the first shot never waits
	quantAware = true, -- the server fires along a 1.4° quantised rotation: aim where that lands, body when the head is smaller than a step
	-- anti-aim
