-- clamps for everything the server validates or that can wedge the character
local function sanitize(cfg: any)
	-- v0.9: an untouched old default follows the new one (the 40-stud melee ragebot range left most of
	-- a map out of reach)
	if (tonumber(cfg.cfgRev) or 0) < 9 then
		if cfg.meleeRageRange == 40 then
			cfg.meleeRageRange = 80
		end
		cfg.cfgRev = 9
	end
	-- v1.3.1: an untouched 3 s autokill run follows the new 6 s default (approach + first sync ate most of 3 s)
	if (tonumber(cfg.cfgRev) or 0) < 10 then
		if cfg.autokillDuration == 3 then
			cfg.autokillDuration = 6
		end
		cfg.cfgRev = 10
	end
	-- wide ranges on purpose: the safe band is shown in the UI, the choice is the user's
	cfg.rapidFireMult = clamp(cfg.rapidFireMult, 0.01, 1, 0.5)
	cfg.leadMs = clamp(cfg.leadMs, 0, 400, 100)
	cfg.leadLearnedMs = clamp(cfg.leadLearnedMs, -1, 400, -1)
	if cfg.leadMode ~= "Off" and cfg.leadMode ~= "Auto" and cfg.leadMode ~= "Manual" then
		cfg.leadMode = "Auto"
	end
	if type(cfg.rapidFloor) ~= "table" then
		cfg.rapidFloor = {}
	end
	for k, v in pairs(cfg.rapidFloor) do
		cfg.rapidFloor[k] = if type(k) == "string" then clamp(v, 0.3, 1, 0.5) else nil
	end
	-- v6.3 server-safe floors (the per-drop learner / range calibration); rapidFloor above is the old
	-- 3-of-10 learner's data, kept so old configs load, no longer read
	if type(cfg.rapidFloorSafe) ~= "table" then
		cfg.rapidFloorSafe = {}
	end
	for k, v in pairs(cfg.rapidFloorSafe) do
		local f = if type(k) == "string" then clamp(v, 0.3, 1, 0.7) else nil
		-- a floor at the gun's own cadence is what lag taught the 6.6 first-drop learner (Assault Rifle,
		-- Spray at ×1.00): start that gun over from its class default
		cfg.rapidFloorSafe[k] = if f and f < 0.98 then f else nil
	end
	cfg.speedMult = clamp(cfg.speedMult, 1, 10, 1.25)
	cfg.fastEquipMult = clamp(cfg.fastEquipMult, 0.01, 1, 0.3)
	cfg.fastAimMult = clamp(cfg.fastAimMult, 1, 30, 2)
	cfg.autokillMaxSpeed = clamp(cfg.autokillMaxSpeed, 20, 600, 45)
	cfg.reloadMult = clamp(cfg.reloadMult, 0, 1, 0)
	cfg.reloadEarly = clamp(cfg.reloadEarly, 0, 90, 0)
	cfg.hudScale = clamp(cfg.hudScale, 0.7, 1.6, 1)
	cfg.magicHeight = clamp(cfg.magicHeight, 5, 150, 30)
	cfg.magicJitterRadius = clamp(cfg.magicJitterRadius, 0.5, 20, 3.5)
	cfg.magicJitterHz = clamp(cfg.magicJitterHz, 1, 40, 4)
	cfg.magicWiggle = clamp(cfg.magicWiggle, 0, 4, 1)
	cfg.aimSmooth = clamp(cfg.aimSmooth, 1, 40, 4)
	cfg.aimStrength = clamp(cfg.aimStrength, 5, 100, 100)
	cfg.aimHumanize = clamp(cfg.aimHumanize, 0, 3, 0)
	cfg.legitTriggerMaxDist = clamp(cfg.legitTriggerMaxDist, 10, 1000, 400)
	cfg.aimFov = clamp(cfg.aimFov, 20, 1000, 140)
	cfg.silentFov = clamp(cfg.silentFov, 20, 1500, 160)
	cfg.targetSwitchMs = clamp(cfg.targetSwitchMs, 0, 2000, 300)
	cfg.espGhostSec = clamp(cfg.espGhostSec, 1, 30, 6)
	cfg.autoShootChance = clamp(cfg.autoShootChance, 10, 100, 100)
	cfg.autoShootMinHitChance = clamp(cfg.autoShootMinHitChance, 0, 100, 0)
	cfg.autoShootStopLeadMs = clamp(cfg.autoShootStopLeadMs, 30, 400, 90)
	cfg.autoShootLeadMs = clamp(cfg.autoShootLeadMs, 0, 300, 0)
	cfg.oobMargin = clamp(cfg.oobMargin, 0.1, 10, 0.6)
	cfg.noclipSpeed = clamp(cfg.noclipSpeed, 8, 300, 40)
	cfg.originMaxDist = clamp(cfg.originMaxDist, 2, 120, 14)
	cfg.autoShootLeadMaxMs = clamp(cfg.autoShootLeadMaxMs, 60, 1500, 120)
	cfg.preAimRange = clamp(cfg.preAimRange, 10, 400, 140)
	cfg.rapidMeleeMult = clamp(cfg.rapidMeleeMult, 0.01, 1, 0.3)
	cfg.rapidMeleeServer = clamp(cfg.rapidMeleeServer, 0.1, 1, 0.3)
	if type(cfg.rapidFloorMelee) ~= "table" then
		cfg.rapidFloorMelee = {}
	end
	if cfg.spreadMode ~= "Auto" and cfg.spreadMode ~= "Claim" and cfg.spreadMode ~= "Real aim" then
		cfg.spreadMode = "Auto"
	end
	if cfg.deviceSpoof ~= "Real" and cfg.deviceSpoof ~= "Mobile" and cfg.deviceSpoof ~= "Controller" and cfg.deviceSpoof ~= "VR" then
		cfg.deviceSpoof = "Real"
	end
	if type(cfg.spreadLearned) ~= "table" then
		cfg.spreadLearned = {}
	end
	for k, v in pairs(cfg.spreadLearned) do
		if type(k) ~= "string" or (v ~= "real" and v ~= "claim") then
			cfg.spreadLearned[k] = nil
		end
	end
	for k, v in pairs(cfg.rapidFloorMelee) do
		cfg.rapidFloorMelee[k] = if type(k) == "string" then clamp(v, 0.1, 1, 0.5) else nil
	end
	if cfg.aaSpinDir ~= 1 and cfg.aaSpinDir ~= -1 then
		cfg.aaSpinDir = 1
	end
	if cfg.aaBodyMode ~= "Same" and cfg.aaBodyMode ~= "Real" and cfg.aaBodyMode ~= "Opposite" then
		cfg.aaBodyMode = "Same"
	end
	-- the one No spread switch drives its halves wherever the value came from (menu, config, import)
	cfg.noSpreadStraighten, cfg.spreadClaimAim, cfg.spreadStillShot = cfg.noSpread == true, cfg.noSpread == true, cfg.noSpread == true
	-- rapid fire always learns the server's limit: the raw-slider mode only ever produced client-only
	-- shots and mag drains
	cfg.rapidAdaptive = true
	-- the rage features (magic / autokill / melee ragebot / defense / backstab / peek) always hold
	-- with collisions off — the user's noclip / fly toggles are for walking around
	cfg.noclipRage = true
	-- 6.4.1: "One circle" is retired — it hid the aimbot's circle. Aimbot and silent aim each keep their own
	cfg.fovLinked = false
	cfg.silentWallbangDist = clamp(cfg.silentWallbangDist, 1, 25, 4)
	cfg.antiUnderDist = clamp(cfg.antiUnderDist, 3, 14, 8)
	cfg.safeMaxHeight = clamp(cfg.safeMaxHeight, 8, 150, 26)
	cfg.defenseMinCooldown = clamp(cfg.defenseMinCooldown, 0.1, 3, 0.15)
	cfg.defenseMaxHide = clamp(cfg.defenseMaxHide, 0.5, 20, 3)
	cfg.defenseHopHz = clamp(cfg.defenseHopHz, 1, 20, 3)
	if cfg.defenseMode ~= "Auto" and cfg.defenseMode ~= "Sky" and cfg.defenseMode ~= "Void" then
		cfg.defenseMode = "Auto" -- a saved "Wall" too: hides are void only since 6.1.7
	end
	if cfg.voidSpamMode ~= "Timer" and cfg.voidSpamMode ~= "Gun ready" and cfg.voidSpamMode ~= "Stay hidden" then
		cfg.voidSpamMode = "Timer"
	end
	cfg.voidSpamDist = clamp(cfg.voidSpamDist, 10000, 90000, 30000)
	cfg.voidSpamHide = clamp(cfg.voidSpamHide, 0.1, 30, 1.5)
	cfg.voidSpamBack = clamp(cfg.voidSpamBack, 0.05, 10, 0.4)
	cfg.voidSpamAutoOff = clamp(cfg.voidSpamAutoOff, 0, 600, 0)
	cfg.voidSpamUnderRange = clamp(cfg.voidSpamUnderRange, 50, 1000, 400)
	cfg.voidSpamBaitSec = clamp(cfg.voidSpamBaitSec, 0.1, 1, 0.25)
	cfg.voidSpamBaitEvery = clamp(cfg.voidSpamBaitEvery, 0.5, 10, 2)
	if cfg.voidSpamBaitSpot ~= "In the floor" and cfg.voidSpamBaitSpot ~= "Your spot" then
		cfg.voidSpamBaitSpot = "In the floor"
	end
	cfg.autoShootAdsRelease = clamp(cfg.autoShootAdsRelease, 0, 3, 0.4)
	if cfg.autoShootStopMode ~= "Off" and cfg.autoShootStopMode ~= "Per shot" and cfg.autoShootStopMode ~= "While firing" and cfg.autoShootStopMode ~= "Whenever locked" then
		cfg.autoShootStopMode = "Off"
	end
	if cfg.autoShootAimMode ~= "Off" and cfg.autoShootAimMode ~= "ADS" and cfg.autoShootAimMode ~= "Camera" and cfg.autoShootAimMode ~= "ADS + Camera" then
		cfg.autoShootAimMode = "Off"
	end
	cfg.autoShootStop = cfg.autoShootStopMode ~= "Off"
	cfg.autoShootAim = cfg.autoShootAimMode ~= "Off"
	cfg.silentSettleMs = clamp(cfg.silentSettleMs, 0, 400, 100)
	cfg.aimReactionMs = clamp(cfg.aimReactionMs, 0, 500, 140)
	if type(cfg.keySlot) ~= "string" then
		cfg.keySlot = ""
	end
	cfg.keySlot = string.sub(cfg.keySlot, 1, 128)
	cfg.legitTriggerDelayMs = clamp(cfg.legitTriggerDelayMs, 0, 500, 90)
	cfg.legitTriggerChance = clamp(cfg.legitTriggerChance, 5, 100, 100)
	if cfg.legitTriggerMode ~= "Always" and cfg.legitTriggerMode ~= "Hold key" then
		cfg.legitTriggerMode = "Always"
	end
	if cfg.legitTriggerHitbox ~= "Any" and cfg.legitTriggerHitbox ~= "Head" and cfg.legitTriggerHitbox ~= "Body" then
		cfg.legitTriggerHitbox = "Any"
	end
	if type(cfg.legitTriggerKey) ~= "string" or cfg.legitTriggerKey == "" then
		cfg.legitTriggerKey = "MouseButton2"
	end
	cfg.fovLinked = cfg.fovLinked ~= false
	cfg.silentHitChance = clamp(cfg.silentHitChance, 0, 100, 100)
	cfg.autokillRadius = clamp(cfg.autokillRadius, 1, 20, 4)
	cfg.autokillHeight = clamp(cfg.autokillHeight, 0, 20, 2.5)
	cfg.autokillOrbitSpeed = clamp(cfg.autokillOrbitSpeed, 1, 120, 12)
	-- 61 = the slider's "until dead" notch; a config saved with the old Until-they-die switch lands on it
	if cfg.autokillUntilDead == true and (tonumber(cfg.autokillDuration) or 0) < 61 then
		cfg.autokillDuration = 61
	end
	cfg.autokillDuration = clamp(cfg.autokillDuration, 1, 61, 6)
	cfg.autokillUntilDead = cfg.autokillDuration >= 61
	cfg.autokillAbortHp = clamp(cfg.autokillAbortHp, 0, 80, 35)
	cfg.autokillAutoRange = clamp(cfg.autokillAutoRange, 10, 1000, 400)
	cfg.autokillCooldown = clamp(cfg.autokillCooldown, 0, 10, 0.5)
	cfg.voidBurst = clamp(cfg.voidBurst, 0.1, 20, 0.8)
	cfg.voidRest = clamp(cfg.voidRest, 0.1, 15, 1.2)
	cfg.autoShootDelay = clamp(cfg.autoShootDelay, 0.05, 1, 0.12)
	cfg.autoPeekDistance = clamp(cfg.autoPeekDistance, 1, 60, 10)
	cfg.aaSpeed = clamp(cfg.aaSpeed, 1, 120, 10)
	cfg.aaSwitchMs = clamp(cfg.aaSwitchMs, 50, 2000, 350)
	cfg.aaJitterDeg = clamp(cfg.aaJitterDeg, 10, 180, 70)
	cfg.espTextSize = clamp(cfg.espTextSize, 8, 32, 13)
	cfg.espLineWidth = clamp(cfg.espLineWidth, 1, 6, 1)
	if cfg.espRenderer ~= "Auto" and cfg.espRenderer ~= "Drawing" and cfg.espRenderer ~= "Anti-aliased" then
		cfg.espRenderer = "Auto"
	end
	cfg.espMaxDistance = clamp(cfg.espMaxDistance, 100, 10000, 2000)
	cfg.espChamsFill = clamp(cfg.espChamsFill, 0, 1, 0.8)
	cfg.espChamsOutline = clamp(cfg.espChamsOutline, 0, 1, 0)
	cfg.espBoxFillAlpha = clamp(cfg.espBoxFillAlpha, 0.3, 0.98, 0.85)
	cfg.radarSize = clamp(cfg.radarSize, 80, 500, 160)
	cfg.radarRange = clamp(cfg.radarRange, 50, 2000, 150)
	cfg.fov = clamp(cfg.fov, 60, 120, 90)
	cfg.autoRejoinDelay = clamp(cfg.autoRejoinDelay, 1, 30, 5)
	cfg.brightness = clamp(cfg.brightness, 0, 10, 2)
	cfg.nightLevel = clamp(cfg.nightLevel, 0, 100, 40)
	cfg.nightHandsGlow = clamp(cfg.nightHandsGlow, 0, 100, 60)
	cfg.tpDist = clamp(cfg.tpDist, 1, 30, 6)
	cfg.tpUp = clamp(cfg.tpUp, 0, 12, 1.5)
	cfg.tpSide = clamp(cfg.tpSide, 0, 10, 1.5)
	if cfg.tpShoulder ~= "Right" and cfg.tpShoulder ~= "Left" and cfg.tpShoulder ~= "Center" then
		cfg.tpShoulder = "Right"
	end
	cfg.timeOfDay = clamp(cfg.timeOfDay, 0, 24, 14)
	cfg.stickyAim = cfg.stickyAim == true
	cfg.utilHealBelow = clamp(cfg.utilHealBelow, 10, 90, 40)
	cfg.hideHands = cfg.hideHands == true
	cfg.menuBlurSize = clamp(cfg.menuBlurSize, 4, 30, DEFAULTS.menuBlurSize)
	if cfg.uiMode ~= "Simple" and cfg.uiMode ~= "Advanced" then
		cfg.uiMode = DEFAULTS.uiMode
	end
	-- enum-like keys: an invalid saved value used to fall through every branch (an unknown
	-- espBoxStyle drew no box at all)
	for key, allowed in pairs({
		targetPriority = { "Crosshair", "Closest", "LowestHP", "Threat" },
		aaMode = { "Auto", "Spin", "Jitter", "Backwards", "Sideways", "Away", "Fake", "Random" },
		aaPitch = { "Down", "Up", "Zero", "Jitter", "Real" },
		espBoxStyle = { "Corner", "Full", "3D" },
		espTracerFrom = { "Bottom", "Center", "Mouse" },
		-- Max looks (Max only) are valid theme values too: the integrity pass ran sanitize and reset them to
		-- Neon purple every 60 s, logging an error and popping a toast (theme Max Cute→Neon purple). For Max the
		-- real store is cfg.maxTheme; applyTheme falls back to purple on Normal, so listing them here is safe.
		theme = { "Obsidian", "Neon purple", "Max", "Max Cute", "Max Pride", "Max Trans", "Max Femboy", "Max Xmas", "Max Matcha", "Ice", "Rose", "Mint", "Gold", "Mono", "Custom" },
		espHpMode = { "When damaged", "Always", "Never" },
		worldShadows = { "Default", "On", "Off" },
		worldWeather = { "Off", "Snow", "Rain", "Embers", "Dust" },
		skyboxPreset = { "Off", "Sunset", "Nebula", "Arctic" },
		crosshairStyle = { "Classic", "Dot", "Circle", "Cross" },
		killEffect = { "Off", "Ring", "Burst", "Blood" },
		vmMaterial = { "ForceField", "Neon", "Glass", "SmoothPlastic" },
		selfMaterial = { "ForceField", "Neon", "Glass", "SmoothPlastic" },
	}) do
		local v = cfg[key]
		local ok = false
		for _, a in ipairs(allowed) do
			if v == a then
				ok = true
				break
			end
		end
		if not ok then
			cfg[key] = DEFAULTS[key]
		end
	end
	if cfg.autokillMode ~= "Origin" and cfg.autokillMode ~= "Orbit" and cfg.autokillMode ~= "Void" and cfg.autokillMode ~= "Snap" and cfg.autokillMode ~= "Under" and cfg.autokillMode ~= "High" then
		cfg.autokillMode = "Origin"
	end
	if cfg.autokillMove ~= "Hop" and cfg.autokillMove ~= "Orbit" and cfg.autokillMove ~= "Auto" and cfg.autokillMove ~= "Hold" then
		cfg.autokillMove = "Auto"
	end
	cfg.autokillSnapHold = clamp(cfg.autokillSnapHold, 0.1, 5, 0.6)
	-- one positioning mode drives the three relocation switches (a bind flips the mode, not a switch)
	if cfg.ragePosition ~= "None" and cfg.ragePosition ~= "Magic bullet" and cfg.ragePosition ~= "Autokill" and cfg.ragePosition ~= "Peek" then
		cfg.ragePosition = "Magic bullet"
	end
	cfg.rageEnabled = cfg.rageEnabled ~= false
	-- every positioning mode aims through silent aim: the menu's Enable turned it on, but a keybind or a loaded
	-- config left rage on with silent aim off, and it never fired
	if cfg.rageEnabled and cfg.ragePosition ~= "None" then
		cfg.silentAim = true
	end
	cfg.magicBullet = cfg.ragePosition == "Magic bullet"
	cfg.autokillAuto = cfg.ragePosition == "Autokill"
	cfg.autoPeek = cfg.ragePosition == "Peek"
	if cfg.autokillAuto then
		cfg.autokill = true
	end
	cfg.autokillHopMs = clamp(cfg.autokillHopMs, 120, 600, 220)
	cfg.bodyAimHoldMs = clamp(cfg.bodyAimHoldMs, 0, 1000, 30)
	cfg.meleeReachSlack = clamp(cfg.meleeReachSlack, 0, 4, 1)
	cfg.targetMaxDistance = clamp(cfg.targetMaxDistance, 50, 5000, 400)
	cfg.autoBackstabRange = clamp(cfg.autoBackstabRange, 4, 150, 25)
	cfg.meleeRageRange = clamp(cfg.meleeRageRange, 6, 250, 80)
	cfg.meleeStandoff = clamp(cfg.meleeStandoff, 1, 12, 3)
	cfg.meleeSettlePad = clamp(cfg.meleeSettlePad, 0, 200, 30)
	cfg.meleeHeavyHold = clamp(cfg.meleeHeavyHold, 0.05, 0.5, 0.12)
	if cfg.meleeMode ~= "Auto" and not ({ ["Heavy crit"] = true, ["Close spam"] = true, Ability = true, ["Walk-in"] = true })[cfg.meleeMode] then
		cfg.meleeMode = "Auto"
	end
	if cfg.meleeHeavyPolicy ~= "Heavy then light" and cfg.meleeHeavyPolicy ~= "Heavy only" and cfg.meleeHeavyPolicy ~= "Light only" then
		cfg.meleeHeavyPolicy = "Heavy then light"
	end
	if cfg.meleeLookSource ~= "Auto" and cfg.meleeLookSource ~= "Camera" and cfg.meleeLookSource ~= "Body" and cfg.meleeLookSource ~= "Smoothed" then
		cfg.meleeLookSource = "Auto"
	end
	if type(cfg.meleeOverrides) ~= "table" then
		cfg.meleeOverrides = {}
	end
	for k, v in pairs(cfg.meleeOverrides) do
		if type(k) ~= "string" or not ({ ["Heavy crit"] = true, ["Close spam"] = true, Ability = true, ["Walk-in"] = true })[v] then
			cfg.meleeOverrides[k] = nil
		end
	end
	cfg.uiGlow = clamp(cfg.uiGlow, 0, 100, 45)
	cfg.themeFx = cfg.themeFx ~= false
	cfg.worldMotionBlurScale = clamp(cfg.worldMotionBlurScale, 0.2, 3, 1)
	cfg.stretchedResScale = clamp(cfg.stretchedResScale, 0.6, 1, 0.88)
	cfg.crosshairSize = clamp(cfg.crosshairSize, 0.5, 2.5, 1)
	cfg.railGlass = clamp(cfg.railGlass, 0, 40, 14)
	cfg.espArrowMax = clamp(cfg.espArrowMax, 1, 16, 5)
	cfg.espArrowRadius = clamp(cfg.espArrowRadius, 50, 800, 220)
	cfg.autoBlockRange = clamp(cfg.autoBlockRange, 10, 200, 45)
	cfg.autoBlockAngle = clamp(cfg.autoBlockAngle, 5, 180, 25)
	cfg.espHealth = cfg.espHpMode ~= "Never"
	cfg.previewHp = clamp(cfg.previewHp, 1, 100, 72)
	cfg.gradeBrightness = clamp(cfg.gradeBrightness, -0.3, 0.3, 0)
	cfg.gradeContrast = clamp(cfg.gradeContrast, -0.5, 1, 0.1)
	cfg.gradeSaturation = clamp(cfg.gradeSaturation, -1, 1, 0.15)
	cfg.bloomIntensity = clamp(cfg.bloomIntensity, 0, 3, 0.8)
	cfg.bloomSize = clamp(cfg.bloomSize, 0, 56, 24)
	cfg.bloomThreshold = clamp(cfg.bloomThreshold, 0, 3, 1.2)
	cfg.sunRaysIntensity = clamp(cfg.sunRaysIntensity, 0, 1, 0.12)
	cfg.sunRaysSpread = clamp(cfg.sunRaysSpread, 0, 1, 0.6)
	cfg.dofFocus = clamp(cfg.dofFocus, 5, 200, 40)
	cfg.dofBlur = clamp(cfg.dofBlur, 0, 1, 0.35)
	cfg.atmosDensity = clamp(cfg.atmosDensity, 0, 1, 0.3)
	cfg.atmosHaze = clamp(cfg.atmosHaze, 0, 10, 1.2)
	cfg.atmosGlare = clamp(cfg.atmosGlare, 0, 10, 0.3)
	cfg.worldExposure = clamp(cfg.worldExposure, -2, 2, 0)
	cfg.weatherDensity = clamp(cfg.weatherDensity, 5, 100, 50)
	cfg.shotTracerLife = clamp(cfg.shotTracerLife, 0.15, 2, 0.6)
	cfg.vmAlpha = clamp(cfg.vmAlpha, 0, 0.9, 0)
	cfg.antiMeleeDodgeCd = clamp(cfg.antiMeleeDodgeCd, 0.3, 6, 1.5)
	cfg.antiMeleeMargin = clamp(cfg.antiMeleeMargin, 0, 12, 3)
	cfg.aaSendHz = clamp(cfg.aaSendHz, 1, 60, 12)
	-- "Direct" (item:StartShooting) is client-side only — the server never accepts it
	if cfg.fireMethod ~= "Auto" and cfg.fireMethod ~= "Game" and cfg.fireMethod ~= "VIM" and cfg.fireMethod ~= "Executor" then
		cfg.fireMethod = "Auto"
	end
	cfg.autoShootReactionMs = clamp(cfg.autoShootReactionMs, 0, 200, 0)
	-- the shot carries hitbox + offset and the server resolves it on its own part position — a
	-- rewound aim lands short of a moving target, so Auto only learns (display)
	if cfg.backtrackMode ~= "Off" and cfg.backtrackMode ~= "Auto" then
		cfg.backtrackMode = "Off"
	end
	cfg.unsafeFakeLagChokeMs = clamp(cfg.unsafeFakeLagChokeMs, 50, 400, 180)
	cfg.unsafeFakeLagEveryMs = clamp(cfg.unsafeFakeLagEveryMs, 200, 3000, 600)
	cfg.unsafePingBoostMs = clamp(cfg.unsafePingBoostMs, 20, 400, 150)
	if cfg.unsafeAccepted ~= true then
		-- nothing in unsafe mode survives a config load without the explicit acceptance
		cfg.unsafeMode = false
	end
	if type(cfg.binds) ~= "table" then
		cfg.binds = {}
	end
	for k, b in pairs(cfg.binds) do
		if type(b) ~= "table" or type(k) ~= "string" then
			cfg.binds[k] = nil
		else
			b.key = if type(b.key) == "string" then b.key else ""
			if b.mode ~= "Toggle" and b.mode ~= "Hold" and b.mode ~= "Always" and b.mode ~= "Never" then
				b.mode = "Toggle"
			end
		end
	end
	if type(cfg.voidHeights) ~= "table" then
		cfg.voidHeights = {}
	end
	if type(cfg.voidDepths) ~= "table" then
		cfg.voidDepths = {}
	end
	if type(cfg.voidFatal) ~= "table" then
		cfg.voidFatal = {}
	end
	-- menu sizes are whole-pixel layouts, one of four steps (never a fractional UIScale)
	do
		local want = tonumber(cfg.menuScale) or 1
		local best, bestD = 1, math.huge
		for _, v in ipairs({ 0.9, 1, 1.1, 1.25 }) do
			if math.abs(v - want) < bestD then
				best, bestD = v, math.abs(v - want)
			end
		end
		cfg.menuScale = best
	end
	if type(cfg.menuKey) ~= "string" or cfg.menuKey == "" or cfg.menuKey == "None" or safeEnum(Enum.KeyCode, cfg.menuKey) == nil then
		cfg.menuKey = "RightShift"
	end
	for _, pair in ipairs({ { "aimHitboxes", "aimPrefer" }, { "silentHitboxes", "silentPrefer" } }) do
		local setKey, prefKey = pair[1], pair[2]
		if type(cfg[setKey]) ~= "table" then
			cfg[setKey] = deepClone(DEFAULTS[setKey])
		end
		local any = false
		for _, hb in ipairs({ "Head", "Body", "Arms", "Legs" }) do
			cfg[setKey][hb] = cfg[setKey][hb] == true
			any = any or cfg[setKey][hb]
		end
		if not any then
			cfg[setKey].Head = true
		end
		if cfg[prefKey] ~= "Head" and cfg[prefKey] ~= "Body" and cfg[prefKey] ~= "Arms" and cfg[prefKey] ~= "Legs" then
			cfg[prefKey] = "Head"
		end
		if not cfg[setKey][cfg[prefKey]] then
			cfg[setKey][cfg[prefKey]] = true
		end
	end
	if type(cfg.hudPos) ~= "table" then
		cfg.hudPos = {}
	end
	for k, p in pairs(cfg.hudPos) do
		if type(k) ~= "string" or type(p) ~= "table" or type(p.x) ~= "number" or type(p.y) ~= "number" or p.x ~= p.x or p.y ~= p.y then
			cfg.hudPos[k] = nil
		else
			p.x = math.clamp(p.x, 0, 1)
			p.y = math.clamp(p.y, 0, 1)
		end
	end
	-- local skin equips: weapon -> { Skin?, Wrap?, WrapInverted? } with string names only
	if type(cfg.skinEquips) ~= "table" then
		cfg.skinEquips = {}
	end
	for weapon, eq in pairs(cfg.skinEquips) do
		if type(weapon) ~= "string" or type(eq) ~= "table" then
			cfg.skinEquips[weapon] = nil
		else
			eq.Skin = if type(eq.Skin) == "string" and eq.Skin ~= "" then eq.Skin else nil
			eq.Wrap = if type(eq.Wrap) == "string" and eq.Wrap ~= "" then eq.Wrap else nil
			eq.WrapInverted = if eq.WrapInverted == true then true else nil
			if eq.Skin == nil and eq.Wrap == nil then
				cfg.skinEquips[weapon] = nil
			end
		end
	end
	if type(cfg.skinWeapon) ~= "string" then
		cfg.skinWeapon = ""
	end
	for _, key in ipairs({ "colEsp", "colEspVisible", "colText", "colHp", "colTracer", "colChamsFill", "colChamsOutline", "colAccent", "colAccent2", "skyColor" }) do
		local c = cfg[key]
		if type(c) ~= "table" or type(c[1]) ~= "number" or type(c[2]) ~= "number" or type(c[3]) ~= "number" then
			cfg[key] = deepClone(DEFAULTS[key])
		else
			for i = 1, 3 do
				c[i] = math.clamp(math.floor(c[i] + 0.5), 0, 255)
			end
		end
	end
end

local function defaultConfig(): any
	return deepClone(DEFAULTS)
end

local function readJsonFile(path: string): any
	if not (EXEC.isfile and EXEC.readfile) then
		return nil
	end
	local ok, raw = pcall(function()
		if EXEC.isfile(path) then
			return EXEC.readfile(path)
		end
		return nil
	end)
	if ok and type(raw) == "string" and #raw > 1 then
		local ok2, data = pcall(HttpService.JSONDecode, HttpService, raw)
		if ok2 and type(data) == "table" then
			return data
		end
	end
	return nil
end

-- Configs: named setting files, one JSON per config in centerra/configs. The live settings autosave to
-- centerra/state.json with the active config's name, so a reinject keeps every change; a config file
-- only changes when you save into it.
local Configs = {
	dir = DATA.configs, -- where config files live (a test points it at a temporary folder)
	active = "", -- the config the live settings came from / were last saved to ("" = none)
	startup = "", -- loaded on every start instead of the autosaved state ("" = off)
	sigSaved = "", -- signature of the active config as it is on disk
	gen = 0, -- bumps on every saveConfig; isDirty recomputes once per generation
	dirtyGen = -1,
	dirty = false,
	known = {}, -- names written this session (the list when the executor has no listfiles)
	-- learned data and window layout belong to this install and never travel in a config file
	-- learned data, window layout AND per-device preferences stay with this install: they never travel in a
	-- shared/imported/cloud config (loading a friend's config used to flip Weak-PC mode, the menu key, etc.)
	LOCAL = { rapidFloor = true, rapidFloorSafe = true, rapidFloorMelee = true, leadLearnedMs = true, voidHeights = true, voidDepths = true, voidFatal = true, placeVersions = true, hudPos = true, debugModuleIdx = true, skinWeapon = true, previewHp = true, spreadLearned = true, keySlot = true, maxTheme = true, lowSpec = true, menuBlur = true, menuBlurSize = true, menuScale = true, hudScale = true, menuKey = true, espRenderer = true, fireMethod = true, uiMode = true, logToFile = true, debugConsole = true, autoUpdate = true },
}
-- known keys with the right type copy over; unknown or mistyped keys are ignored
function Configs.merge(data: any, into: any, skipLocal: boolean?)
	if type(data) ~= "table" then
		return
	end
	for k, v in pairs(data) do
		if DEFAULTS[k] ~= nil and type(v) == type(DEFAULTS[k]) and not (skipLocal and Configs.LOCAL[k]) then
			into[k] = if type(v) == "table" then deepClone(v) else v
		end
	end
	-- a saved switch that says off beats the positioning mode it belongs to: sanitize re-derives the
	-- switches from the mode, which turned a saved magicBullet = false back on at load
	local pos = into.ragePosition
	if (pos == "Magic bullet" and data.magicBullet == false) or (pos == "Autokill" and data.autokillAuto == false) or (pos == "Peek" and data.autoPeek == false) then
		into.ragePosition = "None"
	end
end
-- file-safe name: letters, digits, space, - _ . and at most 32 characters
function Configs.clean(name: any): string?
	if type(name) ~= "string" then
		return nil
	end
	local s = string.gsub(name, "[^%w %-_%.]", "")
	s = string.gsub(s, "^[%s%.]+", "")
	s = string.gsub(s, "%s+$", "")
	s = string.sub(s, 1, 32)
	-- Windows reserves these device names (any case): a config named one of them silently fails to write
	local reserved = { con = true, prn = true, aux = true, nul = true, com1 = true, com2 = true, com3 = true, com4 = true, com5 = true, com6 = true, com7 = true, com8 = true, com9 = true, lpt1 = true, lpt2 = true, lpt3 = true, lpt4 = true, lpt5 = true, lpt6 = true, lpt7 = true, lpt8 = true, lpt9 = true }
	if reserved[string.lower(s)] then
		s = s .. "_"
	end
	return if s ~= "" then s else nil
end
function Configs.path(name: string): string
	return Configs.dir .. "/" .. name .. ".json"
end
function Configs.exists(name: string): boolean
	return type(EXEC.isfile) == "function" and select(2, pcall(EXEC.isfile, Configs.path(name))) == true
end
function Configs.read(name: string): any
	local data = readJsonFile(Configs.path(name))
	if not (type(data) == "table" and type(data.cfg) == "table") then
		return nil
	end
	if Configs.isLegit(name) then
		Configs.lockLegit(data.cfg)
	end
	return data
end
-- rage = the Ragebot is enabled and a positioning mode is picked. Either one off idles everything that
-- moves the body: magic, autokill, peek, defense and voidspam, melee rage, backstab and the anti-melee
-- dodge. Enable off leaves ragePosition alone, so turning it back on restores the mode.
function Configs.rageOn(c: any): boolean
	return c.rageEnabled ~= false and c.ragePosition ~= nil and c.ragePosition ~= "None"
end
-- the first switch that is on yet does nothing while silent aim is off (nil = nothing to warn about).
-- The load warning and the HUD line both read this one answer.
function Configs.silentDependent(c: any): string?
	if c.silentAim then
		return nil
	end
	if not Configs.rageOn(c) then
		return nil
	end
	return if c.magicBullet then "magic bullet" elseif c.autokill then "autokill" else nil
end
function Configs.warnOnLoad(c: any): boolean
	return Configs.silentDependent(c) ~= nil
end
function Configs.hudWarning(c: any): string?
	local dep = Configs.silentDependent(c)
	return if dep then ("Silent aim is off, so %s won't work"):format(dep) else nil
end
-- the legit profile: camera aim only. configs/legit.json is rewritten with it once when it arms rage,
-- and the LEGIT_LOCK keys are forced every time a config named "legit" is read, loaded or saved, so
-- it can never teleport or silent-aim again. noRecoil, aim tuning, theme and binds stay the user's.
Configs.LEGIT = {
	aimbot = true, aimFov = 90, aimSmooth = 6, aimReactionMs = 140, legitTrigger = false,
	rageEnabled = false, ragePosition = "None", magicBullet = false, autokill = false, autokillAuto = false, autoPeek = false,
	defenseHide = false, defenseVoidSpam = false, voidSpam = false, meleeRage = false, autoBackstab = false,
	antiMeleeDodge = false, silentAim = false, autoShoot = false, noSpread = false, rapidFire = false, noRecoil = false,
}
Configs.LEGIT_LOCK = { "rageEnabled", "ragePosition", "magicBullet", "autokill", "autokillAuto", "autoPeek", "defenseHide", "defenseVoidSpam", "voidSpam", "meleeRage", "autoBackstab", "antiMeleeDodge", "silentAim", "autoShoot", "noSpread", "rapidFire" }
function Configs.isLegit(name: any): boolean
	return type(name) == "string" and string.lower(name) == "legit"
end
-- returns how many locked keys had to change
function Configs.lockLegit(c: any): number
	local n = 0
	for _, k in ipairs(Configs.LEGIT_LOCK) do
		if c[k] ~= Configs.LEGIT[k] then
			c[k] = Configs.LEGIT[k]
			n += 1
		end
	end
	return n
end
-- order-independent text of every config key (sorted keys at every level), for the unsaved dot
function Configs.canon(v: any, out: { string }, depth: number)
	if type(v) ~= "table" then
		table.insert(out, tostring(v))
		return
	end
	if depth > 8 then
		return
	end
	local keys = {}
	for k in pairs(v) do
		table.insert(keys, k)
	end
	table.sort(keys, function(a, b)
		return tostring(a) < tostring(b)
	end)
	table.insert(out, "{")
	for _, k in ipairs(keys) do
		table.insert(out, tostring(k))
		table.insert(out, "=")
		Configs.canon(v[k], out, depth + 1)
		table.insert(out, ";")
	end
	table.insert(out, "}")
end
function Configs.signature(src: any): string
	local view = {}
	for k, v in pairs(src) do
		if DEFAULTS[k] ~= nil and not Configs.LOCAL[k] then
			view[k] = v
		end
	end
	local out = {}
	Configs.canon(view, out, 0)
	return table.concat(out)
end
-- a config file as the live settings would hold it (defaults + file + sanitize)
function Configs.materialize(data: any): any
	local fresh = defaultConfig()
	Configs.merge(data, fresh, true)
	sanitize(fresh)
	return fresh
end

-- dotted numeric version compare (a < b), so a future "6.10.0" is not read as older than "6.4"
local function verLt(a: any, b: any): boolean
	local function parts(s: any): { number }
		local t = {}
		for n in string.gmatch(tostring(s), "%d+") do
			t[#t + 1] = tonumber(n) or 0
		end
		return t
	end
	local pa, pb = parts(a), parts(b)
	for i = 1, math.max(#pa, #pb) do
		local x, y = pa[i] or 0, pb[i] or 0
		if x ~= y then
			return x < y
		end
	end
	return false
end

local cfg = (function()
	local c = defaultConfig()
	local st = readJsonFile(DATA.state)
	local hadState = type(EXEC.isfile) == "function" and EXEC.isfile(DATA.state) == true
	if st == nil and hadState then
		-- the file exists but did not parse (crash mid-write, a hand edit, a BOM): keep a copy instead of
		-- silently overwriting the user's settings with defaults on the first save below
		pcall(function()
			local raw = type(EXEC.readfile) == "function" and EXEC.readfile(DATA.state) or nil
			if type(raw) == "string" and #raw > 0 and type(EXEC.writefile) == "function" then
				EXEC.writefile(DATA.state .. ".bak", raw)
			end
		end)
		log("WARN", "state.json was unreadable — kept a copy at state.json.bak, starting from defaults")
	end
	Configs.firstRun = st == nil and not hadState
	if type(st) == "table" then
		Configs.merge(st.cfg, c)
		Configs.active = Configs.clean(st.config) or ""
		Configs.startup = Configs.clean(st.startup) or ""
		-- before 6.4 the per-gun tracker also learned from unguided (silent aim off) misses
		if verLt(st.version or "0", "6.4") then
			c.spreadLearned = {}
		end
	end
	sanitize(c)
	local startData = if Configs.startup ~= "" then Configs.read(Configs.startup) else nil
	if startData then
		local fresh = Configs.materialize(startData.cfg)
		for k in pairs(Configs.LOCAL) do
			fresh[k] = c[k]
		end
		c = fresh
		Configs.active = Configs.startup
	end
	if Configs.active ~= "" then
		local activeData = if startData and Configs.active == Configs.startup then startData else Configs.read(Configs.active)
		if activeData then
			Configs.sigSaved = Configs.signature(Configs.materialize(activeData.cfg))
		else
			Configs.active = ""
		end
	end
	-- the autosave is the user's live state and comes back exactly as they left it, legit active or not:
	-- forcing the legit lock here turned silent aim off on every reinject (the lobby auto-update included)
	Configs.legitForced = 0
	return c
end)()
genv().CenterraCfg = cfg

-- first v6 start: v5 and older kept their data in the workspace root and WaveMCP/
if Configs.firstRun and type(EXEC.isfile) == "function" and type(EXEC.delfile) == "function" then
	for _, p in ipairs({ "centerra_cfg.json", "WaveMCP/centerra.log", "WaveMCP/shots.json", "WaveMCP/intro.stamp", "WaveMCP/autoload.json", "WaveMCP/centerra.lua", "WaveMCP/centerra_unloaded" }) do
		pcall(function()
			if EXEC.isfile(p) then
				EXEC.delfile(p)
			end
		end)
	end
	pcall(function()
		if type(EXEC.delfolder) == "function" and type(EXEC.isfolder) == "function" and EXEC.isfolder("WaveMCP/decompiled") then
			EXEC.delfolder("WaveMCP/decompiled")
		end
	end)
end

local saveFailLoggedAt = 0
local function saveConfig()
	Configs.gen += 1
	if not EXEC.writefile then
		return
	end
	local ok, err = pcall(function()
		EXEC.mkdirs(DATA.dir)
		EXEC.writefile(DATA.state, HttpService:JSONEncode({ version = VERSION, config = Configs.active, startup = Configs.startup, cfg = cfg }))
	end)
	if not ok and os.clock() - saveFailLoggedAt > 10 then
		-- a silent save failure used to lose every later change without a trace; route it through log()
		-- (F9 terminal + telemetry) and a toast, not a bare warn() that nothing else sees
		saveFailLoggedAt = os.clock()
		log("ERROR", "settings save failed:", tostring(err))
		notify("Couldn't save settings — check disk space / permissions", 6, "error")
	end
end
-- coalesced save for hot paths (render loop, shot hooks, per-slot skin persistence): one
-- JSON encode + writefile per frame at most, never on the frame that asked for it
local saveSoonPending = false
local function saveConfigSoon()
	if saveSoonPending then
		return
	end
	saveSoonPending = true
	-- next frame, not the end of this one: keeps the JSON encode + writefile off the frame that asked
	-- (a shot verdict, a server hop) where it shows up as a hitch
	task.delay(0, function()
		saveSoonPending = false
		saveConfig()
	end)
end
saveConfig() -- the state file exists from the first start on
EXEC.mkdirs(DATA.configs)

function Configs.isDirty(): boolean
	if Configs.active == "" then
		return false
	end
	if Configs.dirtyGen ~= Configs.gen then
		Configs.dirtyGen = Configs.gen
		Configs.dirty = Configs.signature(cfg) ~= Configs.sigSaved
	end
	return Configs.dirty
end
-- the live settings minus what stays with this install
function Configs.snapshot(): any
	local out = {}
	for k, v in pairs(cfg) do
		if DEFAULTS[k] ~= nil and not Configs.LOCAL[k] then
			out[k] = deepClone(v)
		end
	end
	return out
end
-- replace the live settings with a config's (learned data and window layout stay)
function Configs.apply(data: any)
	for k, v in pairs(Configs.materialize(data)) do
		if not Configs.LOCAL[k] then
			cfg[k] = v
		end
	end
end
-- merge only the keys a partial config actually contains, leaving every other setting untouched. apply()
-- rebuilds from defaults (right for "Load config", where the file holds every key); patch() is for a
-- shared/cloud config that carries a subset — it must never reset the settings it does not mention.
function Configs.patch(data: any)
	if type(data) ~= "table" then
		return
	end
	-- accept an export wrapper { centerra=, name=, cfg= } as well as a bare settings table
	local src = if type(data.cfg) == "table" then data.cfg else data
	Configs.merge(src, cfg, true) -- known keys, right type, skips LOCAL and the ragePosition-off rule
	sanitize(cfg)
	Configs.gen += 1
end
function Configs.write(name: string, data: any): boolean
	if type(EXEC.writefile) ~= "function" then
		return false
	end
	EXEC.mkdirs(Configs.dir)
	local ok = pcall(EXEC.writefile, Configs.path(name), HttpService:JSONEncode(data))
	if ok then
		Configs.known[name] = true
	end
	return ok
end
-- every config on disk (sorted); without listfiles only the ones written this session
function Configs.list(): { string }
	local names, seen = {}, {}
	local function add(nm: string?)
		if nm and nm ~= "" and not seen[nm] then
			seen[nm] = true
			table.insert(names, nm)
		end
	end
	if type(EXEC.listfiles) == "function" then
		local ok, files = pcall(EXEC.listfiles, Configs.dir)
		if ok and type(files) == "table" then
			for _, f in ipairs(files) do
				add(string.match(tostring(f), "([^/\\]+)%.json$"))
			end
		end
	end
	for nm in pairs(Configs.known) do
		if Configs.exists(nm) then
			add(nm)
		end
	end
	table.sort(names, function(a, b)
		return string.lower(a) < string.lower(b)
	end)
	return names
end
function Configs.freeName(base: string): string
	if not Configs.exists(base) then
		return base
	end
	for i = 2, 999 do
		local nm = ("%s %d"):format(string.sub(base, 1, 27), i)
		if not Configs.exists(nm) then
			return nm
		end
	end
	-- everything up to 999 is taken: fall back to a timestamped name so we never overwrite an existing one
	return ("%s %d"):format(string.sub(base, 1, 20), os.time() % 100000)
end
-- save the live settings into a config (a new name creates it) and make it the active one
function Configs.save(name: string?): (boolean, string)
	local nm = Configs.clean(name or Configs.active)
	if not nm then
		return false, "Give the config a name first"
	end
	local prev = Configs.read(nm)
	local snap = Configs.snapshot()
	-- a config named "legit" never stores rage / silent-aim switches. Strip them from the SAVED COPY only —
	-- mutating the live cfg here is what turned a user's silent aim off the moment they pressed Save.
	local stripped = 0
	if Configs.isLegit(nm) then
		for _, k in ipairs(Configs.LEGIT_LOCK) do
			if snap[k] ~= nil and snap[k] ~= Configs.LEGIT[k] then
				snap[k] = Configs.LEGIT[k]
				stripped += 1
			end
		end
	end
	local ok = Configs.write(nm, { centerra = VERSION, name = nm, created = prev and prev.created or os.time(), saved = os.time(), cfg = snap })
	if not ok then
		return false, "Could not write " .. Configs.path(nm)
	end
	Configs.active = nm
	-- a normal save wrote exactly the live settings; a stripped legit save's disk copy differs, so the
	-- unsaved dot compares against what is really on disk
	Configs.sigSaved = if stripped > 0 then Configs.signature(Configs.materialize(snap)) else Configs.signature(cfg)
	saveConfig()
	if stripped > 0 then
		log("INFO", ("[legit:lock] saved legit without %d rage/aim switch(es); your live settings are untouched"):format(stripped))
		return true, nm
	end
	log("INFO", "config saved:", nm)
	return true, nm
end
function Configs.load(name: string): (boolean, string)
	local data = Configs.read(name)
	if not data then
		return false, "That config is gone or unreadable"
	end
	Configs.apply(data.cfg)
	Configs.active = name
	Configs.known[name] = true
	Configs.sigSaved = Configs.signature(cfg)
	saveConfig()
	log("INFO", "config loaded:", name)
	return true, name
end
function Configs.create(name: string?): (boolean, string)
	local nm = Configs.clean(name)
	if not nm then
		return false, "Give the config a name first"
	end
	if Configs.exists(nm) then
		return false, "A config called " .. nm .. " already exists"
	end
	return Configs.save(nm)
end
function Configs.rename(old: string, new: string?): (boolean, string)
	local nm = Configs.clean(new)
	if not nm then
		return false, "Give the config a name first"
	end
	if nm == old then
		return true, nm
	end
	if Configs.exists(nm) then
		return false, "A config called " .. nm .. " already exists"
	end
	local data = Configs.read(old)
	if not data then
		return false, "That config is gone or unreadable"
	end
	data.name = nm
	if not Configs.write(nm, data) then
		return false, "Could not write " .. Configs.path(nm)
	end
	if type(EXEC.delfile) == "function" then
		pcall(EXEC.delfile, Configs.path(old))
	end
	Configs.known[old] = nil
	if Configs.active == old then
		Configs.active = nm
	end
	if Configs.startup == old then
		Configs.startup = nm
	end
	saveConfig()
	return true, nm
end
function Configs.duplicate(name: string): (boolean, string)
	local data = Configs.read(name)
	if not data then
		return false, "That config is gone or unreadable"
	end
	local nm = Configs.freeName(string.sub(name, 1, 27) .. " copy")
	data.name, data.created, data.saved = nm, os.time(), os.time()
	if not Configs.write(nm, data) then
		return false, "Could not write " .. Configs.path(nm)
	end
	return true, nm
end
function Configs.delete(name: string): (boolean, string)
	if type(EXEC.delfile) ~= "function" then
		return false, "This executor can't delete files"
	end
	local ok = pcall(EXEC.delfile, Configs.path(name))
	Configs.known[name] = nil
	if Configs.active == name then
		Configs.active = ""
	end
	if Configs.startup == name then
		Configs.startup = ""
	end
	saveConfig()
	return ok, name
end
function Configs.setStartup(name: string)
	Configs.startup = name
	saveConfig()
end
-- a config (or the live settings when name is nil) as JSON on the clipboard
function Configs.export(name: string?): boolean
	if not EXEC.setclipboard then
		return false
	end
	local payload
	if name and name ~= "" then
		local data = Configs.read(name)
		payload = data and { centerra = VERSION, name = name, cfg = data.cfg }
	else
		payload = { centerra = VERSION, name = if Configs.active ~= "" then Configs.active else "Shared", cfg = Configs.snapshot() }
	end
	return payload ~= nil and pcall(EXEC.setclipboard, HttpService:JSONEncode(payload)) == true
end
-- clipboard → a new config file; never overwrites (a taken name gets a number)
function Configs.import(): (boolean, string)
	if not EXEC.getclipboard then
		return false, "No clipboard on this executor"
	end
	local ok, text = pcall(EXEC.getclipboard)
	if not ok or type(text) ~= "string" or text == "" then
		return false, "The clipboard is empty"
	end
	local ok2, data = pcall(HttpService.JSONDecode, HttpService, text)
	if not ok2 or type(data) ~= "table" or type(data.cfg) ~= "table" then
		return false, "The clipboard has no centerra config"
	end
	local nm = Configs.freeName(Configs.clean(data.name) or "Imported")
	local clean = Configs.materialize(data.cfg)
	for k in pairs(Configs.LOCAL) do
		clean[k] = nil
	end
	if not Configs.write(nm, { centerra = VERSION, name = nm, created = os.time(), saved = os.time(), imported = true, cfg = clean }) then
		return false, "Could not write " .. Configs.path(nm)
	end
	return true, nm
end
-- every setting back to its default (learned data and window layout stay)
function Configs.reset()
	Configs.apply(DEFAULTS)
	saveConfig()
end
-- a legit.json saved by v6.0 armed magic, hide and melee rage: rewrite it once with the legit profile
-- (theme, binds and every other key stay as they were)
do
	local raw = readJsonFile(Configs.path("legit"))
	if type(raw) == "table" and type(raw.cfg) == "table" then
		local drift = Configs.lockLegit(raw.cfg)
		if drift > 0 then
			for k, v in pairs(Configs.LEGIT) do
				raw.cfg[k] = v
			end
			raw.saved, raw.centerra = os.time(), VERSION
			if Configs.write("legit", raw) then
				log("INFO", ("[legit:repaired] configs/legit.json had %d rage switch(es) on; rewritten with the legit profile"):format(drift))
			end
		end
	end
end

-------------------------------------------------------------------------------
-- §3 state — one table on getgenv(); permanent hooks read live state through it
-------------------------------------------------------------------------------
-- hook ABI generation: hooks installed by an earlier inject of this Lua state keep running (they
-- cannot be removed) and read live logic through S.h / S.cfg. Any earlier state that carries a
-- hooks table is the same ABI (v3 onwards) and is REUSED — a fresh S here would install every hook
-- again on top of the dormant layer (one more pass-through frame per hooked call per re-inject,
-- including __namecall). Only a v2 state (no hooks table) is abandoned.
local HOOK_ABI = 3
local S: any
do
	local prev = genv().CenterraState
	if type(prev) == "table" and type(prev.hooks) == "table" and type(prev.hooks.installed) == "table" and (tonumber(prev.hooks.abi) or HOOK_ABI) == HOOK_ABI then
		S = prev -- same generation: reuse so hooks installed earlier keep reading live state
		-- one frame with the state dead: every extension loop of the copy before (the Max module, which only
		-- checks S.alive and the table) sees it and stops — they used to stack, one per reload
		S.alive = false
		pcall(task.wait)
	else
		if type(prev) == "table" then
			prev.alive = false -- legacy hook closures go dormant for good
			-- and give the game functions back: hook() never stacks a second detour on a function, so a new
			-- state would otherwise inherit dormant detours (camera layer dead until the next server)
			if type(EXEC.restorefunction) == "function" and type(prev.hookedFns) == "table" then
				for fn in pairs(prev.hookedFns) do
					pcall(EXEC.restorefunction, fn)
				end
			end
		end
		S = {}
	end
	genv().CenterraState = S
end
S.version = VERSION
S.publicVersion = PUBLIC_VERSION
-- bumps on every load: an extension belongs to the load it started under (S itself is reused)
S.loadGen = (tonumber(S.loadGen) or 0) + 1
-- the edition the site served this copy as (its marker line runs before this file). Max's own features live in
-- the Max module (site/maxine.lua, appended only for Max licences); it plugs in through S.ext, rebuilt every load
S.edition = if genv().CenterraEdition == "max" then "max" else "normal"
-- served by the site this load (the marker line precedes every served copy, Normal or Max); a bare re-inject
-- over a licensed session has no marker but finds that session's CenterraLicense still in getgenv
S.served = genv().CenterraEdition ~= nil
-- the marker is consumed: left behind, any later copy without the Max module (a bare re-inject) still
-- called itself MAX — blue, badge, "MAX" in the watermark — with no Max tab
pcall(function()
	genv().CenterraEdition = nil
end)
-- the version the user reads (watermark, user card, intro, toasts): Max counts its own releases
S.shownVersion = if S.edition == "max" then MAX_PUBLIC_VERSION else PUBLIC_VERSION
-- subs / sections: an extension's own sub-tabs and groups inside the base pages (S.ext.addSub / addSection, §12)
S.ext = { tabs = {}, subs = {}, sections = {}, espBadge = nil, espFlags = nil }
S.notify = notify -- extensions (the Max module) toast through the HUD like everything else
S.executor = EXECUTOR_NAME
S.cfg = cfg
S.alive = true
S.loadClock = os.clock() -- when this load started; the anti-piracy grace + heartbeat check read it
S.menuOpen = false
S.firing = false
S.aimHeld = false
S.silentTarget = nil
S.silentTargetModel = nil
S.silentFighter = nil
S.targetVisible = false
S.magicReady = false
S.teleported = false
-- v5.0.3: every body/camera owner flag is per-inject. A carried `pinCF` / `defenseHiding` /
-- `autoEngaged` from an instance that was unloaded mid-hold froze the camera in the air for the whole
-- next session (the new instance's owners start idle and never clear what they never set).
S.pinCF = nil
S.fovShown = 0 -- the camera FOV offset we last gave the game (it glides; unload puts 0 back)
S.defenseHiding = false
S.autoEngaged = false
S.preAiming = false
S.syncWaiting = false
S.engagedUntil = nil
S.magicBlockedUntil = nil
S.lastTeleportAt = nil
S.oobSuppressed = 0
pcall(function()
	game:GetService("RunService"):UnbindFromRenderStep("centerra_camPin") -- a stale pin from the previous instance
end)
S.h = {} -- live hook logic, refreshed on every inject (hooks call S.h.<fn> at call time)
S.hooks = S.hooks or { v = 0, installed = {} }
S.hooks.abi = HOOK_ABI
S.hooks.installed = S.hooks.installed or {}
S.hookedFns = S.hookedFns or setmetatable({}, { __mode = "k" }) -- per function object: never hook twice in one state
S.hookOrig = S.hookOrig or {} -- originals of hooked game functions (carried: installers early-return on a re-inject)
S.deepClone = deepClone -- hooks read helpers through the state (a captured per-inject local goes stale)
S.log = log
-- lets the centerra add-on (and other tooling) receive log entries { t, level, text } without reaching
-- into locals. Returns a remover. Listeners are called in pcall, so a bad one cannot break logging.
S.addLogListener = function(fn: any)
	if type(fn) ~= "function" then
		return function() end
	end
	table.insert(logListeners, fn)
	return function()
		local i = table.find(logListeners, fn)
		if i then
			table.remove(logListeners, i)
		end
	end
end
S.statOriginals = S.statOriginals or {} -- persistent first-touch snapshot of ItemLibrary values
S.itemInfoOriginals = S.itemInfoOriginals or setmetatable({}, { __mode = "k" }) -- per-item private Info copies
S.localEquips = S.localEquips or {}
S.shotStats = { redirected = 0, hitTarget = 0, hitOther = 0, miss = 0, confirmed = 0, dropped = 0, immune = 0 }
S.roundBase = nil
S.dmgDealt, S.dmgExpected = 0, 0
S.autokill = { state = "idle", hits = 0 }
S.saveConfig = saveConfig
S.configs = Configs
S.ui = { tabs = {}, subTabs = {}, controls = {}, toggles = {} }
S.bindActions = {}
S.pendingHits = {}
S.killFeedSeen = setmetatable({}, { __mode = "k" }) -- destroyed models must not pile up (one per kill, per session)
S.hpSeen = setmetatable({}, { __mode = "k" }) -- last health per enemy model (damage numbers)
-- stores of original values we must put back (x-ray, no textures, chams, noclip, hides). They used weak keys, but
-- a live part's Lua handle can be collected while the part stays in the game: its entry vanished and the part
-- was never restored (walls stayed invisible). Strong tables; S.keepPrune drops only parts that left the game.
S.keepStores = {}
function S.keep(): any
	local t = {}
	table.insert(S.keepStores, t)
	return t
end
function S.keepPrune()
	for _, t in ipairs(S.keepStores) do
		for k in pairs(t) do
			if typeof(k) == "Instance" and not k:IsDescendantOf(game) then
				t[k] = nil
			end
		end
	end
end
local keepGen = {}
S.keepGen = keepGen
task.spawn(function()
	while S.alive and S.keepGen == keepGen do
		task.wait(15)
		pcall(S.keepPrune)
	end
end)
S.killList = {} -- recent kills for the HUD kill list, newest first
S.errCounts = {}
S.rayTrace = false -- probes flip this to record every shot-code raycast into S.rayTraceBuf
S.rayTraceBuf = {}

-- rate-limited error reporter for hooks and hot paths (one line per source every 5 s, counted)
local errLastAt: { [string]: number } = {}
S.hookErr = function(source: string, err: any)
	local now = os.clock()
	S.errCounts[source] = (S.errCounts[source] or 0) + 1
	if now - (errLastAt[source] or 0) < 5 then
		return
	end
	errLastAt[source] = now
	log("ERROR", ("%s (x%d): %s"):format(source, S.errCounts[source], tostring(err)))
end

-------------------------------------------------------------------------------
-- main
-------------------------------------------------------------------------------
-- key system slot, inert: no UI, no network, no HWID, no key file read. A later update replaces
-- KeySlot.allow (and may start honouring its answer) without touching anything below it.
local KeySlot = { enabled = false, key = "", status = "unused" }
function KeySlot.allow(): boolean
	return true
end
S.keySlot = KeySlot
genv().CenterraInit = function()
	KeySlot.allow() -- asked once; the answer is not used yet
	if game.GameId ~= RIVALS_GAME_ID then
		log("WARN", "not RIVALS (GameId " .. tostring(game.GameId) .. ") — centerra not started")
		notify("centerra: this isn't RIVALS, staying idle")
		return
	end

	-----------------------------------------------------------------------------
	-- §4 game adapters
	-----------------------------------------------------------------------------
	local Game: any = {}
	local PlayerDataController: any
	local CosmeticLibrary: any
	local FighterController: any
	local CameraController: any
	local EnumLibrary: any
	local ItemLibrary: any = nil
	-- inject generation: a newer inject bumps the shared counter, and this init aborts at its next
	-- checkpoint instead of finishing a minute later on top of the new instance (the old double
	-- inject left two render loops sharing one state)
	Game.initGen = (tonumber(genv().CenterraInitGen) or 0) + 1
	genv().CenterraInitGen = Game.initGen
	function Game.superseded(): boolean
		return genv().CenterraInitGen ~= Game.initGen
	end
	function Game.checkpoint(where: string)
		if Game.superseded() then
			error("superseded by a newer inject during " .. where, 0)
		end
	end

	-- never require a module the game hasn't loaded yet: requiring first can leave the game
	-- with a broken cached copy (no UI, default movement)
	local function waitGameLoaded(inst: Instance?, timeout: number): ModuleScript
		if inst == nil then
			error("game module never appeared (WaitForChild timed out)")
		end
		if not inst:IsA("ModuleScript") then
			error("expected ModuleScript: " .. inst:GetFullName())
		end
		local t0 = os.clock()
		local guard = 0
		while os.clock() - t0 < timeout and guard < 1000 do
			guard += 1
			if type(EXEC.ismoduleloaded) ~= "function" then
				break
			end
			local ok, loaded = pcall(EXEC.ismoduleloaded, inst)
			if ok and loaded then
				break
			end
			task.wait(0.25)
		end
		if type(EXEC.ismoduleloaded) == "function" then
			local ok, loaded = pcall(EXEC.ismoduleloaded, inst)
			if not (ok and loaded) then
				-- refusing here is why inject dies on executors whose module list never matches.
				-- requiring a not-yet-loaded module can upset the game; hanging forever is worse.
				log("WARN", "requiring " .. inst.Name .. " without ismoduleloaded confirming it")
			end
		end
		return inst :: ModuleScript
	end

	-- v5.2: what a RIVALS update may rename without taking the whole script down. Only
	-- FighterController + CameraController are load-critical (every combat feature reads them); the
	-- data / cosmetic / enum libraries are optional — missing, they become inert stubs and only the
	-- skins / inventory features switch off. A critical module that is not where it used to be is
	-- looked up by the fields its table exposes among the modules the game has already loaded
	-- (requiring a loaded module is safe — it is the cached table).
	Game.missing = {}
	Game.renamed = {}
	function Game.moduleBySignature(container: Instance, fields: { string }): (any, Instance?)
		if type(EXEC.getloadedmodules) ~= "function" then
			return nil, nil
		end
		local ok, list = pcall(EXEC.getloadedmodules)
		if not (ok and type(list) == "table") then
			return nil, nil
		end
		for i, m in ipairs(list) do
			if i > 1200 then
				break
			end
			if typeof(m) == "Instance" and m:IsA("ModuleScript") and m:IsDescendantOf(container) then
				local okR, tbl = pcall(require, m)
				if okR and type(tbl) == "table" then
					local all = true
					for _, name in ipairs(fields) do
						local okI, v = pcall(function()
							return tbl[name]
						end)
						if not (okI and (type(v) == "function" or type(v) == "table")) then
							all = false
							break
						end
					end
					if all then
						return tbl, m
					end
				end
			end
		end
		return nil, nil
	end
	runStep("load modules", function()
		local PS = LP:WaitForChild("PlayerScripts", 60)
		local Controllers = PS and PS:WaitForChild("Controllers", 60)
		local Modules = ReplicatedStorage:WaitForChild("Modules", 60)
		if not (Controllers and Modules) then
			error("game scripts never appeared (PlayerScripts / Controllers / Modules)")
		end
		local function load(container: Instance, name: string, critical: boolean, fields: { string }): any
			local inst = container:FindFirstChild(name) or container:WaitForChild(name, if critical then 45 else 12)
			if inst and inst:IsA("ModuleScript") then
				return require(waitGameLoaded(inst, 20))
			end
			local tbl, found = Game.moduleBySignature(container, fields)
			if tbl then
				Game.renamed[name] = if found then found.Name else "?"
				log("WARN", ("adapt: %s is not under %s any more — using %s (matched by %s)"):format(name, container.Name, Game.renamed[name], table.concat(fields, "/")))
				return tbl
			end
			if critical then
				error(("game module %s is missing (renamed by a RIVALS update?) — nothing matched %s"):format(name, table.concat(fields, "/")))
			end
			Game.missing[name] = true
			log("WARN", ("adapt: optional module %s missing — the features that read it are off"):format(name))
			return nil
		end
		PlayerDataController = load(Controllers, "PlayerDataController", false, { "Get", "WaitUntilLoaded" })
		FighterController = load(Controllers, "FighterController", true, { "GetFighter", "Objects" })
		CameraController = load(Controllers, "CameraController", true, { "GetCameraCFrame", "SetRotation" })
		CosmeticLibrary = load(Modules, "CosmeticLibrary", false, { "Cosmetics" })
		EnumLibrary = load(Modules, "EnumLibrary", false, { "ToEnum" })
		Game.checkpoint("module wait")
		-- inert stubs: every later `Library.Field` read stays safe, the dependent features see "nothing"
		if type(PlayerDataController) ~= "table" then
			PlayerDataController = { _stub = true, CurrentData = nil, WaitUntilLoaded = function() end, Get = function()
				return nil
			end }
		end
		if type(CosmeticLibrary) ~= "table" then
			CosmeticLibrary = { _stub = true, Cosmetics = {} }
		end
		if type(EnumLibrary) ~= "table" then
			EnumLibrary = { _stub = true, ToEnum = function()
				error("EnumLibrary missing")
			end }
		end
		-- WaitUntilLoaded can sit forever on a slow or odd executor and the inject never finishes
		local dataReady = false
		task.spawn(function()
			pcall(function()
				PlayerDataController:WaitUntilLoaded()
			end)
			dataReady = true
		end)
		local dataT0 = os.clock()
		local dataGuard = 0
		while not dataReady and os.clock() - dataT0 < 12 and dataGuard < 200 do
			dataGuard += 1
			task.wait(0.2)
		end
		if not dataReady then
			log("WARN", "PlayerDataController still loading — continuing")
		end
		Game.checkpoint("data wait")
		pcall(function()
			local il = Modules:FindFirstChild("ItemLibrary")
			if il then
				ItemLibrary = require(waitGameLoaded(il, 10))
			end
		end)
		pcall(function()
			local pg = LP:FindFirstChild("PlayerGui") or LP:WaitForChild("PlayerGui", 15)
			if pg then
				pg:WaitForChild("MainGui", 10)
			end
		end)
		task.wait(0.25)
	end)
	Game.PDC = PlayerDataController
	Game.Cosmetics = CosmeticLibrary
	Game.FC = FighterController
	Game.CC = CameraController
	Game.Enums = EnumLibrary
	Game.ItemLibrary = ItemLibrary
	S.itemLibrary = ItemLibrary
	S.pdc = PlayerDataController

	local function dataKey(name: string): any
		local ok, v = pcall(function()
			return EnumLibrary:ToEnum(name)
		end)
		return if ok and v ~= nil then v else name
	end
	Game.KEY_COS = dataKey("CosmeticInventory")

	local connections: { RBXScriptConnection } = {}
	local function track(conn: RBXScriptConnection): RBXScriptConnection
		table.insert(connections, conn)
		-- per-life connections (hum.Died every respawn) disconnect with their instance but stayed in this
		-- list for the whole session; drop the dead ones once it grows
		if #connections > 150 then
			for i = #connections, 1, -1 do
				local c = connections[i]
				if typeof(c) == "RBXScriptConnection" and not c.Connected then
					table.remove(connections, i)
				end
			end
		end
		return conn
	end
	Game.track = track
	Game.connections = connections

	function Game.guiCandidates(): { Instance }
		local list: { Instance } = {}
		local pg = LP:FindFirstChild("PlayerGui") or LP:FindFirstChildOfClass("PlayerGui")
		if pg then
			table.insert(list, pg)
		end
		local getHui = waveGlobal("gethui") or waveGlobal("get_hidden_gui")
		if type(getHui) == "function" then
			local ok, hui = pcall(getHui)
			if ok and typeof(hui) == "Instance" then
				table.insert(list, hui)
			end
		end
		local okC, cg = pcall(game.GetService, game, "CoreGui")
		if okC and typeof(cg) == "Instance" then
			table.insert(list, cg)
		end
		return list
	end
	function Game.guiParent(): Instance
		-- PlayerGui first (Wave's gethui locks instances after parenting). Never WaitForChild with no
		-- timeout: an early inject used to hang here forever and the menu never appeared.
		if Game._guiParent and Game._guiParent.Parent ~= nil then
			return Game._guiParent
		end
		local list = Game.guiCandidates()
		for _, p in ipairs(list) do
			if p:IsA("PlayerGui") then
				Game._guiParent = p
				return p
			end
		end
		if list[1] then
			Game._guiParent = list[1]
			return list[1]
		end
		local ok, waited = pcall(function()
			return LP:WaitForChild("PlayerGui", 5)
		end)
		if ok and typeof(waited) == "Instance" then
			Game._guiParent = waited
			return waited
		end
		error("PlayerGui never appeared")
	end
	function Game.parentGui(gui: Instance): boolean
		local protect = waveGlobal("protectgui") or waveGlobal("protect_gui")
		if type(protect) ~= "function" and type(EXEC.syn) == "table" then
			protect = EXEC.syn.protect_gui or EXEC.syn.protectgui
		end
		if type(protect) == "function" then
			pcall(protect, gui)
		end
		local function tryParent(p: Instance): boolean
			pcall(function()
				gui.Parent = nil
			end)
			local ok = pcall(function()
				gui.Parent = p
			end)
			if ok and gui.Parent == p then
				Game._guiParent = p
				return true
			end
			return false
		end
		if Game._guiParent and Game._guiParent.Parent ~= nil and tryParent(Game._guiParent) then
			return true
		end
		for _, p in ipairs(Game.guiCandidates()) do
			if tryParent(p) then
				return true
			end
		end
		return false
	end

	S.game = Game
	-- Call game code as the game: our thread runs at identity 8, and a game routine that lazily
	-- `require`s from inside such a call fails with "Cannot require a non-RobloxScript module from a
	-- RobloxScript" (and leaves that feature half-initialised). Drop to identity 2 around the call.
	-- (identity functions live on EXEC since v5.2 — resolved in §1 with the other executor globals)
	function Game.asGame(fn: any, ...: any): (boolean, ...any)
		if type(fn) ~= "function" then
			return false, "not a function"
		end
		local setIdentity = EXEC.setIdentity
		if type(setIdentity) ~= "function" then
			return pcall(fn, ...)
		end
		local prev = 8
		local getIdentity = EXEC.getIdentity
		if type(getIdentity) == "function" then
			local okI, id = pcall(getIdentity)
			if okI and type(id) == "number" then
				prev = id
			end
		end
		pcall(setIdentity, 2)
		-- every return value passes through without a table.pack / unpack per call (this runs on
		-- every aim frame and every camera step)
		return Game._restoreIdentity(prev, pcall(fn, ...))
	end
	function Game._restoreIdentity(prev: number, ...: any): ...any
		pcall(EXEC.setIdentity, prev)
		return ...
	end
	S.asGame = Game.asGame
	-- Call game code as MechanicsController: on Volt, trampoline_call runs `fn` with a real script
	-- context (getcallingscript() == MechanicsController) at identity 2, so game code that checks its
	-- caller — and our own caller-gated hooks — treat the call exactly like the game's own input path.
	-- Falls back to the identity drop above where trampoline_call does not exist (Wave).
	local mcScript: Instance? = nil
	function Game.asShotCode(fn: any, ...: any): (boolean, ...any)
		if type(fn) ~= "function" then
			return false, "not a function"
		end
		if EXEC.caps.trampoline then
			if not mcScript then
				local ps = LP:FindFirstChild("PlayerScripts")
				local ctrl = ps and ps:FindFirstChild("Controllers")
				mcScript = ctrl and ctrl:FindFirstChild("MechanicsController")
			end
			if mcScript then
				local n = select("#", ...)
				local args = { ... }
				local res = table.pack(pcall(EXEC.trampoline_call, fn, {}, { script = mcScript, identity = 2 }, table.unpack(args, 1, n)))
				-- pcall ok + trampoline ok → (true, true, results…): collapse to the pcall shape
				if res[1] == true then
					return table.unpack(res, 2, res.n)
				end
				return false, res[2]
			end
		end
		return Game.asGame(fn, ...)
	end
	S.asShotCode = Game.asShotCode
	-- require a game module only once the game itself has loaded it (see waitGameLoaded); nil otherwise
	function Game.requireIfLoaded(inst: Instance?): any
		if not (inst and inst:IsA("ModuleScript")) then
			return nil
		end
		-- no module-loaded oracle → no require: the rule is "never require what the game has not"
		if type(EXEC.ismoduleloaded) ~= "function" then
			return nil
		end
		local ok, loaded = pcall(EXEC.ismoduleloaded, inst)
		if not (ok and loaded) then
			return nil
		end
		local okR, mod = pcall(require, inst)
		return if okR then mod else nil
	end
	S.fighterHealth = function(f: any)
		return Game.fighterHealth(f)
	end
	-- resolved once per frame: 23 call sites, several of them per enemy per frame
	Game._lfFrame = -1
	Game._lf = nil
	function Game.localFighter(): any
		if Game._lfFrame == Game.frameId then
			return Game._lf
		end
		local ok, lf = pcall(function()
			return FighterController.LocalFighter or FighterController:GetFighter(LP)
		end)
		Game._lf = if ok then lf else nil
		Game._lfFrame = Game.frameId
		return Game._lf
	end

	function Game.fighterBody(fighter: any): (BasePart?, Model?)
		local ent = fighter and fighter.Entity
		if type(ent) ~= "table" then
			return nil, nil
		end
		local model = ent.Model
		local root = ent.RootPart or (model and (model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart))
		return root, model
	end

	function Game.fighterHead(fighter: any): BasePart?
		local ent = fighter and fighter.Entity
		if type(ent) ~= "table" then
			return nil
		end
		local model = ent.Model
		return ent.Head or (model and model:FindFirstChild("Head")) or ent.RootPart
	end

	-- Humanoid only: fighter:Get("Health") with a string key makes ReplicatedController throw.
	-- Memoised per frame: the lock, ESP bars, the kill feed and isDead all read it (a range bot costs two
	-- pcalls per read; 24 dummies made that ~30 reads a frame)
	Game.hpMemo, Game.hpMemoMax, Game.hpMemoFrame = setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" }), -1
	function Game.fighterHealth(fighter: any): (number?, number?)
		if fighter == nil then
			return nil, nil
		end
		if Game.hpMemoFrame ~= Game.frameId then
			Game.hpMemoFrame = Game.frameId
			table.clear(Game.hpMemo)
			table.clear(Game.hpMemoMax)
		end
		local hp = Game.hpMemo[fighter]
		if hp ~= nil then
			if hp == false then
				return nil, nil
			end
			return hp, Game.hpMemoMax[fighter]
		end
		local h, m = Game.readHealth(fighter)
		Game.hpMemo[fighter] = if h == nil then false else h
		Game.hpMemoMax[fighter] = m
		return h, m
	end
	function Game.readHealth(fighter: any): (number?, number?)
		local ent = fighter and fighter.Entity
		if type(ent) ~= "table" then
			return nil, nil
		end
		local hum = ent.Humanoid
		if hum and hum.MaxHealth > 0 then
			return hum.Health, hum.MaxHealth
		end
		local model = ent.Model
		hum = model and model:FindFirstChildOfClass("Humanoid")
		if hum and hum.MaxHealth > 0 then
			return hum.Health, hum.MaxHealth
		end
		-- bots without a Humanoid (range targets): the ClientEnemy object keeps the health
		local bot = fighter.Bot
		if type(bot) == "table" and type(bot.GetHealth) == "function" then
			local ok, hp = pcall(bot.GetHealth, bot)
			local okM, mx = pcall(bot.GetMaxHealth, bot)
			if ok and type(hp) == "number" then
				return hp, if okM and type(mx) == "number" and mx > 0 then mx else math.max(hp, 1)
			end
		end
		return nil, nil
	end

	function Game.fighterName(fighter: any): string
		local plr = fighter and fighter.Player
		if typeof(plr) == "Instance" then
			return plr.DisplayName or plr.Name
		end
		local _, model = Game.fighterBody(fighter)
		if fighter and fighter.IsBot then
			return (if model then model.Name else "Bot") .. " [BOT]"
		end
		return if model then model.Name else "Enemy"
	end

	-- RIVALS does not use Roblox Teams (LP.Team is nil in every mode — the old check never matched):
	-- the side is the fighter's replicated TeamID, a one-byte string ("\1", "\2"). Same non-empty
	-- id as the local fighter = teammate. Cached per fighter for 250 ms (Get is a call per fighter).
	Game.teamCache = setmetatable({}, { __mode = "k" })
	function Game.fighterTeam(fighter: any): string?
		if type(fighter) ~= "table" or fighter.IsBot then
			return nil
		end
		local c = Game.teamCache[fighter]
		local now = os.clock()
		if c and now - c.t < 0.25 then
			return c.id
		end
		local id: string? = nil
		if type(fighter.Get) == "function" then
			local ok, v = pcall(fighter.Get, fighter, "TeamID")
			if ok and type(v) == "string" and v ~= "" then
				id = v
			end
		end
		if id == nil then
			local data = rawget(fighter, "Data")
			if type(data) == "table" and type(data.TeamID) == "string" and data.TeamID ~= "" then
				id = data.TeamID
			end
		end
		Game.teamCache[fighter] = { t = now, id = id }
		-- remember the side per Player: the character fallback between rounds has no fighter data
		if id ~= nil and typeof(fighter.Player) == "Instance" then
			Game.teamByPlayer[fighter.Player] = id
		end
		return id
	end
	Game.teamByPlayer = setmetatable({}, { __mode = "k" })
	-- the lobby hub has no sides: every fighter there carries the same TeamID, so the team check hid every
	-- lobby player from the ESP ("ESP doesn't work" — tested in the lobby). Outside a duel in the hub place
	-- nobody is a teammate; Game.targets still keeps lobby players out of every aim / rage system.
	Game.hubFreeAt, Game.hubFree = -1, false
	function Game.hubNoTeams(): boolean
		local now = os.clock()
		if now - Game.hubFreeAt < 0.25 then
			return Game.hubFree
		end
		Game.hubFreeAt = now
		local A = Game.adapt
		local free = false
		if A and game.PlaceId == A.LOBBY_PLACE then
			local lf = Game.localFighter()
			local ok, inDuel = false, nil
			if lf and type(lf.Get) == "function" then
				ok, inDuel = pcall(lf.Get, lf, "IsInDuel")
			end
			free = not (ok and inDuel == true)
		end
		Game.hubFree = free
		return free
	end
	function Game.isTeammate(fighter: any): boolean
		if not cfg.teamCheck or type(fighter) ~= "table" or fighter.IsBot then
			return false
		end
		if Game.hubNoTeams() then
			return false
		end
		local lf = Game.localFighter()
		local mine = if lf and lf ~= fighter then Game.fighterTeam(lf) else nil
		if mine ~= nil and Game.fighterTeam(fighter) == mine then
			return true
		end
		local plr = fighter.Player
		return typeof(plr) == "Instance" and LP.Team ~= nil and plr.Team == LP.Team
	end
	S.isTeammate = Game.isTeammate

	-- spawn protection / invincibility: the entity's replicated IsInvincible flag (verified from
	-- ClientEntity._UpdateInvincibilityVisual). Shots into it register as IMMUNE and do nothing.
	Game.immuneMemo = setmetatable({}, { __mode = "k" })
	Game.immuneFrame = -1
	function Game.fighterImmune(fighter: any): boolean
		if type(fighter) ~= "table" then
			return false
		end
		-- one replicated Get per fighter per frame (target pick, lock, ESP tag, nearest all ask)
		if Game.immuneFrame ~= Game.frameId then
			Game.immuneFrame = Game.frameId
			table.clear(Game.immuneMemo)
		end
		local cached = Game.immuneMemo[fighter]
		if cached ~= nil then
			return cached
		end
		local v = Game._fighterImmune(fighter)
		Game.immuneMemo[fighter] = v
		return v
	end
	function Game._fighterImmune(fighter: any): boolean
		local ent = fighter.Entity
		local obj = if type(ent) == "table" and type(ent.Get) == "function" then ent else fighter.Bot
		if type(obj) == "table" and type(obj.Get) == "function" then
			local ok, v = pcall(obj.Get, obj, "IsInvincible")
			if ok and v == true then
				return true
			end
		end
		-- spawn protection is also a plain ForceField on the model (the shot log showed our sniper
		-- rounds landing on "HitboxHead (ForceField)" for 0 damage); cached per model for 100 ms
		local model = type(ent) == "table" and ent.Model or (type(fighter.Bot) == "table" and fighter.Bot.Model)
		if typeof(model) == "Instance" then
			local c = Game.ffCache[model]
			local now = os.clock()
			if not c or now - c.t > 0.1 then
				c = { t = now, ff = model:FindFirstChildOfClass("ForceField") ~= nil }
				Game.ffCache[model] = c
			end
			if c.ff then
				return true
			end
		end
		return false
	end
	Game.ffCache = setmetatable({}, { __mode = "k" })
	S.fighterImmune = Game.fighterImmune

	function Game.fighterValid(fighter: any): boolean
		if type(fighter) ~= "table" or fighter.IsLocalPlayer or fighter.Player == LP then
			return false
		end
		if Game.isTeammate(fighter) then
			return false
		end
		if type(fighter.IsAlive) == "function" then
			local ok, alive = pcall(fighter.IsAlive, fighter)
			if ok and alive == false then
				return false
			end
		end
		return Game.fighterBody(fighter) ~= nil
	end

	-- bots: EnemyController.Objects are the range dummies / NPC enemies (ClientEnemy: Model, RootPart,
	-- Humanoid, hitboxes, IsAlive/GetHealth). Wrapped once each into the fighter-like shape every
	-- system already understands ({ Entity = { Model, RootPart, Head, Humanoid } }).
	Game.EC = nil
	Game.botWrap = setmetatable({}, { __mode = "k" })
	Game.botKind = setmetatable({}, { __mode = "k" }) -- model → shootable like a character (decided once)
	Game.botList = {}
	Game.botScanAt = 0
	Game.BOT_RANGE = 250 -- studs; the range keeps ~200 targets alive, only the near ones matter
	Game.BOT_MAX = 24
	Game.rangeFolderAt = 0
	Game.rangeFolder = nil
	function Game.rangeEntities(): Instance?
		local now = os.clock()
		if now - Game.rangeFolderAt > 2 then
			Game.rangeFolderAt = now
			Game.rangeFolder = workspace:FindFirstChild("ShootingRangeEntities")
		end
		return Game.rangeFolder
	end
	Game.ECRetryAt = 0
	function Game.enemyController(): any
		-- a miss is retried every 3 s: the controller is often required by the game only after
		-- the first round starts, and a permanent `false` killed bot targeting for the session
		if Game.EC == nil or (Game.EC == false and os.clock() - Game.ECRetryAt > 3) then
			Game.ECRetryAt = os.clock()
			local ps = LP:FindFirstChild("PlayerScripts")
			local ctrl = ps and ps:FindFirstChild("Controllers")
			Game.EC = Game.requireIfLoaded(ctrl and ctrl:FindFirstChild("EnemyController")) or false
		end
		return if type(Game.EC) == "table" then Game.EC else nil
	end
	-- rescanned at 5 Hz (the range's object list is ~200 long and IsAlive is a pcall per object); between
	-- scans the cached wrappers are reused — their parts are live instances and a dead one drops out below
	function Game.bots(out: { any })
		local now = os.clock()
		if now - Game.botScanAt >= 0.2 then
			Game.botScanAt = now
			local EC = Game.enemyController()
			local objs = EC and rawget(EC, "Objects")
			local me = Game.myRoot()
			local found = {}
			if type(objs) == "table" and me then
				local myPos = me.Position
				local rangeFolder = Game.rangeEntities()
				local kinds = Game.botKind
				for _, obj in pairs(objs) do
					if type(obj) == "table" then
						local model = rawget(obj, "Model")
						local root = rawget(obj, "RootPart")
						local live = typeof(model) == "Instance" and typeof(root) == "Instance" and model.Parent ~= nil and root.Parent ~= nil
						-- distance first: the list holds every destructible on the map and only the near ones matter
						local d = if live then (root.Position - myPos).Magnitude else math.huge
						-- only things that are shot like a character. EnemyController also holds every
						-- destructible on a map — Explosive Barrels, WindowWide1/2 panes, the range's Button
						-- props — all with a HumanoidRootPart and "alive": a live match showed 18 of them as
						-- targets. Dummies live under ShootingRangeEntities (Target / Dummy); real NPCs carry
						-- a Humanoid. The verdict is kept per model: a barrel never becomes a dummy, and
						-- re-deciding hundreds of them at 5 Hz was the "scan" spike on slow executors.
						local shootable = false
						if d <= Game.BOT_RANGE then
							shootable = kinds[model]
							if shootable == nil then
								shootable = rawget(obj, "Humanoid") ~= nil or model.Name == "Target" or model.Name == "Dummy"
									or (rangeFolder ~= nil and model:IsDescendantOf(rangeFolder))
								kinds[model] = shootable
							end
						end
						if shootable then
							do
								local okA, alive = true, true
								if type(obj.IsAlive) == "function" then
									okA, alive = pcall(obj.IsAlive, obj)
								end
								if not okA or alive ~= false then
									local w = Game.botWrap[obj]
									if not w then
										w = {
											Bot = obj,
											IsBot = true,
											_fallback = true, -- no class hooks for bots
											Entity = { Model = model, RootPart = root, Head = model:FindFirstChild("Head") or root, Humanoid = rawget(obj, "Humanoid") },
											IsAlive = function()
												if type(obj.IsAlive) ~= "function" then
													return true
												end
												local ok, a = pcall(obj.IsAlive, obj)
												return not ok or a ~= false
											end,
										}
										Game.botWrap[obj] = w
									else
										w.Entity.Model, w.Entity.RootPart = model, root
										if not (w.Entity.Head and w.Entity.Head.Parent) then
											w.Entity.Head = model:FindFirstChild("Head") or root
										end
									end
									w._dist = d
									table.insert(found, w)
								end
							end
						end
					end
				end
				table.sort(found, function(a, b)
					return a._dist < b._dist
				end)
				local cap = if cfg.lowSpec then 12 else Game.BOT_MAX
				for i = #found, cap + 1, -1 do
					found[i] = nil
				end
			end
			Game.botList = found
		end
		for _, w in ipairs(Game.botList) do
			local ent = w.Entity
			if ent.Model.Parent ~= nil and ent.RootPart.Parent ~= nil then
				table.insert(out, w)
			end
		end
	end

	-- one scan per frame shared by every system (ESP, aim, autokill, katana, HUD)
	Game.frameId = 0
	Game.fallbackWrap = setmetatable({}, { __mode = "k" })
	Game.fallbackList = {}
	Game.fallbackScanAt = 0
	local enemyCache: { any } = {}
	local enemyCacheFrame = -1
	-- v5 perf: one reused output buffer — the list is frame-cached anyway, so a fresh table per frame
	-- was pure GC churn (double-buffered: consumers holding last frame's list keep a valid table)
	Game.scanBufA, Game.scanBufB = {}, {}
	local function scanEnemies(): { any }
		local out = if Game.scanBufA == Game.scanBufLast then Game.scanBufB else Game.scanBufA
		Game.scanBufLast = out
		table.clear(out)
		local okObjs, objs = pcall(function()
			return FighterController.Objects
		end)
		if okObjs and type(objs) == "table" then
			for _, fighter in pairs(objs) do
				if Game.fighterValid(fighter) then
					table.insert(out, fighter)
				end
			end
		end
		if #out == 0 then
			-- between rounds the fighter objects are gone: fall back to characters. The team check
			-- still applies through the last TeamID seen for that player (fighters carry it, characters
			-- do not) — this fallback used to lock the teammate's parked body from 8 000 studs away.
			-- The wrapper per Player is stable (a fresh table per frame defeated every fighter-keyed
			-- cache: sticky target, kill confirm, skin retries) and the 30-player scan runs at 10 Hz.
			local now = os.clock()
			if now - Game.fallbackScanAt >= 0.1 then
				Game.fallbackScanAt = now
				local list = Game.fallbackList
				table.clear(list)
				local lf = Game.localFighter()
				local myTeam = if lf then Game.fighterTeam(lf) or Game.teamByPlayer[LP] else Game.teamByPlayer[LP]
				for _, plr in ipairs(Players:GetPlayers()) do
					local char = plr.Character
					if plr ~= LP and char then
						local hrp = char:FindFirstChild("HumanoidRootPart")
						local hum = char:FindFirstChildOfClass("Humanoid")
						local mate = cfg.teamCheck and ((LP.Team ~= nil and plr.Team == LP.Team) or (myTeam ~= nil and Game.teamByPlayer[plr] == myTeam))
						if hrp and not mate then
							local w = Game.fallbackWrap[plr]
							if not w then
								w = { Player = plr, _fallback = true, Entity = {} }
								Game.fallbackWrap[plr] = w
							end
							local ent = w.Entity
							ent.Model, ent.RootPart, ent.Humanoid = char, hrp, hum
							if not (ent.Head and ent.Head.Parent == char) then
								ent.Head = char:FindFirstChild("Head")
							end
							table.insert(list, w)
						end
					end
				end
			end
			for _, w in ipairs(Game.fallbackList) do
				local ent = w.Entity
				local hum = ent.Humanoid
				if ent.RootPart.Parent ~= nil and not (hum ~= nil and hum.Health <= 0) then
					table.insert(out, w)
				end
			end
		end
		if cfg.targetBots then
			pcall(Game.bots, out)
		end
		return out
	end
	-- v5.2: the enemy models as a set — Bounds.isEnemyInstance walked the whole list with an
	-- IsDescendantOf per enemy for every ray hit / overlap part (O(enemies) inside the planner loops)
	Game.enemyModelSet = {}
	function Game.enemies(): { any }
		-- v6.5 the list changes on spawns and deaths, not per frame (positions are read live): a slow frame
		-- (perf tier 1 / 2) rebuilds it every 2nd / 3rd frame — the rescan was 12 ms of a 22 ms frame on Madium
		-- v6.7: every 2nd frame at tier 0 too (0.75 ms a frame with 24 range dummies); a death lingers one frame
		local tier = S.perfTier or 0
		local every = if tier >= 2 then 4 elseif tier >= 1 then 3 else 2
		if enemyCacheFrame >= 0 and Game.frameId - enemyCacheFrame < every then
			return enemyCache
		end
		enemyCache = scanEnemies()
		enemyCacheFrame = Game.frameId
		local set = Game.enemyModelSet
		table.clear(set)
		for _, f in ipairs(enemyCache) do
			local ent = f.Entity
			local m = type(ent) == "table" and ent.Model
			if m then
				set[m] = true
			end
		end
		return enemyCache
	end
	-- who may be targeted (aimbot, silent lock, autokill, melee / defense helpers): everyone, except
	-- in the lobby hub, where no player can be damaged — there only range bots count (user rule: no
	-- targeting in the lobby, only in the range and in duels). ESP, radar and the HUD keep the full list.
	-- The returned hub table is reused: read it this frame, never keep it.
	Game.hubTargets = {}
	function Game.targets(list: { any }?): { any }
		local all = list or Game.enemies()
		local A = Game.adapt
		if not (A and game.PlaceId == A.LOBBY_PLACE) then
			return all
		end
		local out = Game.hubTargets
		table.clear(out)
		-- a private / custom duel runs in the hub place: its other duelers are real targets. Lobby players
		-- (IsInDuel false) and players in other arenas (not in our duel) never are.
		local lf = Game.localFighter()
		local okD, mine = false, nil
		if lf and type(lf.Get) == "function" then
			okD, mine = pcall(lf.Get, lf, "IsInDuel")
		end
		local duel = if okD and mine == true then Game.myDuel() else nil
		for _, f in ipairs(all) do
			if f.IsBot then
				table.insert(out, f)
			elseif okD and mine == true and type(f.Get) == "function" then
				local okF, theirs = pcall(f.Get, f, "IsInDuel")
				if okF and theirs == true then
					local member = true
					if duel and typeof(f.Player) == "Instance" then
						local okM, d = pcall(duel.GetDueler, duel, f.Player)
						member = not okM or d ~= nil
					end
					if member then
						table.insert(out, f)
					end
				end
			end
		end
		return out
	end
	-- our duel object (DuelController:GetDuel(LocalPlayer)); nil when the controller is not loaded
	Game.duelAtMy, Game.duelMy = -1, nil
	function Game.myDuel(): any
		local now = os.clock()
		if now - Game.duelAtMy < 0.5 then
			return Game.duelMy
		end
		Game.duelAtMy = now
		local d = nil
		pcall(function()
			local ps = LP:FindFirstChild("PlayerScripts")
			local ctrl = ps and ps:FindFirstChild("Controllers")
			local DC = Game.requireIfLoaded(ctrl and ctrl:FindFirstChild("DuelController"))
			if type(DC) == "table" and type(DC.GetDuel) == "function" then
				d = DC:GetDuel(LP)
			end
		end)
		Game.duelMy = d
		return d
	end
	-- a live duel: not the hub, the local fighter's IsInDuel, and not a match waiting room. The last one
	-- is the game's own test (CameraController points the camera at the map's spectate part or the
	-- WaitingRoomSpectate part while the duel subject has no LocalDueler). Cached 0.25 s; the IsInDuel
	-- data signal clears the cache (Combat.updateDuelGate). S.gateOverride (self-test, hub tests) = live.
	Game.duelAt = -1
	Game.duelLiveNow = false
	function Game.duelLive(): boolean
		if S.gateOverride then
			return true
		end
		local now = os.clock()
		if now - Game.duelAt < 0.25 then
			return Game.duelLiveNow
		end
		Game.duelAt = now
		-- no PlaceId test: private-server / custom duels load their arena into the hub place itself
		-- (2026-09-24 log: six rounds on 17625359962 with everything paused), and the shooting range is in
		-- the hub too. The fighter's own IsInDuel / IsInShootingRange flags decide, on every place.
		local live = false
		local lf = Game.localFighter()
		local inDuel, inRange = false, false
		if lf and type(lf.Get) == "function" then
			local okD, d = pcall(lf.Get, lf, "IsInDuel")
			local okR, r = pcall(lf.Get, lf, "IsInShootingRange")
			inDuel, inRange = okD and d == true, okR and r == true
		end
		Game.inRange = inRange
		live = inDuel or inRange
		if inDuel and not inRange then
			local ok, waiting = pcall(function()
				local subj = CameraController and CameraController._current_duel_subject
				return type(subj) == "table" and subj.LocalDueler == nil
			end)
			if ok and waiting then
				live = false
			end
		end
		Game.duelLiveNow = live
		return live
	end
	-- every non-visual feature waits until Combat.updateDuelGate sees a live duel (hooks read this flag)
	S.featuresPaused = true

	-- hitbox groups → candidate part names (R6 and R15 rigs); first one that exists wins
	-- RIVALS hit-tests dedicated parts (verified from the shot whitelist): <model>.HitboxHead /
	-- HitboxBody (+ *Small variants). They are larger than the visual parts, so they come first.
	local HITBOX_PARTS = {
		Head = { "HitboxHead", "Head" },
		Body = { "HitboxBody", "HumanoidRootPart", "UpperTorso", "Torso", "LowerTorso" },
		Arms = { "RightUpperArm", "LeftUpperArm", "Right Arm", "Left Arm", "RightLowerArm", "LeftLowerArm" },
		Legs = { "RightUpperLeg", "LeftUpperLeg", "Right Leg", "Left Leg", "RightLowerLeg", "LeftLowerLeg" },
	}
	local HITBOX_ORDER = { "Head", "Body", "Arms", "Legs" }
	-- resolved parts are cached per model + group (weak keys): this is asked several times per enemy
	-- per frame (lock, aimbot, LOS, ESP, situation) and each ask used to be 2–6 FindFirstChild calls.
	-- The first-choice part (HitboxHead / HitboxBody …) is trusted while it is still parented to the
	-- model. A lower-ranked pick (the visual Head, an R6 arm) or a miss is re-scanned every 0.5 s, because
	-- character models fill in over several frames: the hitbox parts often arrive after the visual ones
	-- and a cache that never re-checked would keep aiming at the smaller visual head for that life.
	Game.hitboxCache = setmetatable({}, { __mode = "k" })
	function Game.hitboxPart(fighter: any, group: string): BasePart?
		local ent = fighter and fighter.Entity
		if type(ent) ~= "table" then
			return nil
		end
		local model = ent.Model
		if model then
			local byGroup = Game.hitboxCache[model]
			if not byGroup then
				byGroup = {}
				Game.hitboxCache[model] = byGroup
			end
			local c = byGroup[group]
			local now = os.clock()
			if c then
				if c.part and c.part.Parent == model and (c.best or now - c.t < 0.5) then
					return c.part
				end
				if c.part == nil and now - c.t < 0.5 then
					return if group == "Head" then ent.Head elseif group == "Body" then ent.RootPart else nil
				end
			end
			local found: BasePart? = nil
			local best = false
			for i, name in ipairs(HITBOX_PARTS[group] or {}) do
				local p = model:FindFirstChild(name)
				if p and p:IsA("BasePart") then
					found = p
					best = i == 1
					break
				end
			end
			-- v5.2: a hitbox part the list does not know (renamed by an update, a *Small variant left
			-- alone) still beats the visual part: one child scan, repeated every 0.5 s like any non-best pick
			if not best and (group == "Head" or group == "Body") then
				local word = if group == "Head" then "head" else "body"
				for _, ch in ipairs(model:GetChildren()) do
					if ch:IsA("BasePart") then
						local ln = string.lower(ch.Name)
						if ln:find("hitbox", 1, true) and ln:find(word, 1, true) then
							found = ch
							break
						end
					end
				end
			end
			byGroup[group] = { part = found, t = now, best = best }
			if found then
				return found
			end
		end
		if group == "Head" then
			return ent.Head
		elseif group == "Body" then
			return ent.RootPart
		end
		return nil
	end
	-- pick the part to aim at from an enabled set + preference; with visibility, the preferred part
	-- wins when it has a clear line, otherwise the first enabled part that does, else the preferred.
	-- Hysteresis: the preferred hitbox must stay blocked for cfg.bodyAimHoldMs before the pick moves
	-- to another one (a teammate crossing, a railing, one frame of a doorway — no body-aim flicker).
	-- While that hold runs, S.headBlockedHold is true (auto shoot waits instead of firing into cover).
	-- keyed by model, then by the preferred group: aim (aimPrefer) and silent (silentPrefer) ask
	-- about the same model in one frame and used to clear each other's hold
	Game.blockedSince = setmetatable({}, { __mode = "k" })
	function Game.blockedAt(model: any, prefer: string): number?
		local bs = model and Game.blockedSince[model]
		return if bs then bs[prefer] else nil
	end
	function Game.pickHitbox(fighter: any, set: any, prefer: string, needVisible: boolean, from: Vector3?): BasePart?
		local _, model = Game.fighterBody(fighter)
		local pref = Game.hitboxPart(fighter, prefer)
		if pref and (not needVisible or Game.rayVisible(model, pref, from)) then
			local bs = model and Game.blockedSince[model]
			if bs then
				bs[prefer] = nil
			end
			return pref
		end
		if needVisible then
			if pref and model then
				local bs = Game.blockedSince[model]
				if not bs then
					bs = {}
					Game.blockedSince[model] = bs
				end
				local since = bs[prefer]
				if not since then
					since = os.clock()
					bs[prefer] = since
				end
				if os.clock() - since < cfg.bodyAimHoldMs / 1000 then
					return pref -- keep the head for a moment; the caller sees it as blocked (Game.headHold)
				end
			end
			for _, g in ipairs(HITBOX_ORDER) do
				if g ~= prefer and set[g] then
					local p = Game.hitboxPart(fighter, g)
					if p and Game.rayVisible(model, p, from) then
						return p
					end
				end
			end
		end
		if pref then
			return pref
		end
		for _, g in ipairs(HITBOX_ORDER) do
			if set[g] then
				local p = Game.hitboxPart(fighter, g)
				if p then
					return p
				end
			end
		end
		return (Game.fighterBody(fighter))
	end
	-- true while the preferred hitbox of this model is blocked but the fallback hold has not expired
	function Game.headHold(model: any, prefer: string?): boolean
		local since = Game.blockedAt(model, prefer or cfg.silentPrefer)
		return since ~= nil and os.clock() - since < cfg.bodyAimHoldMs / 1000
	end
	function Game.aimPart(fighter: any, kind: string?): BasePart?
		if kind == "silent" then
			return Game.pickHitbox(fighter, cfg.silentHitboxes, cfg.silentPrefer, cfg.silentVisibleHitbox)
		end
		return Game.pickHitbox(fighter, cfg.aimHitboxes, cfg.aimPrefer, cfg.aimVisibleHitbox)
	end

	-- item.IsEquipped is unreliable → also ask IsActive()
	function Game.itemActive(item: any): boolean
		if type(item) ~= "table" then
			return false
		end
		if item.IsEquipped == true then
			return true
		end
		if type(item.IsActive) == "function" then
			local ok, v = pcall(item.IsActive, item)
			return ok and v == true
		end
		return false
	end

	-- the held weapon. Several items can report active at once (quick-melee knife next to the gun),
	-- so among the active ones the main item wins, then a gun, then whatever came first.
	function Game.activeItem(fighter: any): any
		if type(fighter) ~= "table" or type(fighter.Items) ~= "table" then
			return nil
		end
		local first, main, gun = nil, nil, nil
		for _, item in pairs(fighter.Items) do
			if Game.itemActive(item) then
				first = first or item
				if type(item.IsMainItem) == "function" then
					local ok, isMain = pcall(item.IsMainItem, item)
					if ok and isMain == true and not main then
						main = item
					end
				end
				if not gun and type(item.Info) == "table" and item.Info.Type == "Gun" then
					gun = item
				end
			end
		end
		return main or gun or first
	end

	-- the blade a fighter holds right now (nil = gun / shield / nothing). A Riot Shield is a Melee item
	-- with an AttackReach too, but it absorbs, it does not stab. An enemy with no EquippedItem replicated
	-- is still checked for a blade on their character (Game.heldMelee).
	Game.meleeScratch = {}
	function Game.fighterMeleeOut(fighter: any): any
		local it = Game.enemyEquipped(fighter)
		if type(it) == "table" and type(it.Info) == "table" then
			local p = Game.profileOf(it, Game.meleeScratch)
			return if p.melee and p.reach ~= nil then it else nil
		end
		return Game.heldMelee(fighter)
	end
	-- a blade model on the character whose name is a melee item in the library (0.5 s cache per model)
	Game.heldCache = setmetatable({}, { __mode = "k" })
	function Game.heldMelee(fighter: any): any
		local _, model = Game.fighterBody(fighter)
		if not model or type(ItemLibrary) ~= "table" or type(ItemLibrary.Items) ~= "table" then
			return nil
		end
		local now = os.clock()
		local c = Game.heldCache[model]
		if c and now - c.at < 0.5 then
			return c.item
		end
		local found = nil
		for _, ch in ipairs(model:GetChildren()) do
			if ch:IsA("Model") or ch:IsA("Tool") then
				local info = ItemLibrary.Items[ch.Name]
				if type(info) == "table" then
					local p = Game.profileOf({ Name = ch.Name, Info = info }, Game.meleeScratch)
					if p.melee and p.reach ~= nil then
						found = { Name = ch.Name, Info = info, FromModel = true }
						break
					end
				end
			end
		end
		Game.heldCache[model] = { at = now, item = found }
		return found
	end

	function Game.itemAmmo(item: any): (number?, number?, number?)
		if type(item) ~= "table" or type(item.GetAmmoVariables) ~= "function" then
			return nil, nil
		end
		-- GetAmmoVariables() answers the item's replicated Ammo / AmmoReserve (checked equal on a live
		-- gun) but allocates ~0.6 KB a call, every frame; the two data reads allocate nothing
		if type(item.Get) == "function" then
			local okA, ammo = pcall(item.Get, item, "Ammo")
			local okR, reserve = pcall(item.Get, item, "AmmoReserve")
			if okA and okR and type(ammo) == "number" and type(reserve) == "number" then
				local info = item.Info
				return ammo, type(info) == "table" and tonumber(info.MaxAmmo) or nil, reserve
			end
		end
		local ok, a, b = pcall(item.GetAmmoVariables, item)
		if ok and type(a) == "table" then
			return a.Ammo or a.CurrentAmmo or a.Current or a.ammo, a.MaxAmmo or a.Max or a.ClipSize or a.max
		end
		-- live client: GetAmmoVariables() returns (ammo, reserve, isReloading) as plain values
		if ok and type(a) == "number" then
			-- reserve is not the magazine size: when Info has no MaxAmmo the max is unknown (nil hides
			-- the HUD bar) instead of max(ammo, reserve)
			local info = item.Info
			local mx = type(info) == "table" and tonumber(info.MaxAmmo) or nil
			return a, mx, (if type(b) == "number" then b else nil)
		end
		local okG, v = pcall(function()
			return item:Get("Ammo")
		end)
		if okG and type(v) == "number" then
			local info = item.Info
			return v, type(info) == "table" and tonumber(info.MaxAmmo) or nil
		end
		return nil, nil
	end

	-- the local fighter's IsAlive / AreItemsLocked / GetHealth / GetMaxHealth each allocate ~1.5 KB a
	-- call inside the (VM-obfuscated) ClientFighter — ~6 KB a frame from Game.state alone, the largest
	-- steady GC churn in the loop (measured). They are read through one cache that the fighter's own
	-- signals mark stale (health, death, entity swap, the item lock), so every read after a change calls
	-- the real methods — as fresh as before; a 0.2 s refresh backs up any change without a signal.
	Game.vitals = { fighter = nil, at = -1, dirty = true, alive = false, locked = false, hp = nil, maxHp = nil, conns = {} }
	function Game.vitalsUnwatch()
		local c = Game.vitals
		for _, conn in ipairs(c.conns) do
			pcall(function()
				conn:Disconnect()
			end)
		end
		table.clear(c.conns)
		c.fighter = nil
	end
	Game.track({ Disconnect = Game.vitalsUnwatch } :: any)
	function Game.vitalsOf(lf: any): any
		local c = Game.vitals
		if c.fighter ~= lf then
			Game.vitalsUnwatch()
			c.fighter, c.dirty = lf, true
			local function stale()
				c.dirty = true
			end
			for _, name in ipairs({ "HealthChanged", "Died", "Eliminated", "EntityAdded", "EntityRemoved" }) do
				local sig = lf[name]
				if type(sig) == "table" and type(sig.Connect) == "function" then
					local ok, conn = pcall(sig.Connect, sig, stale)
					if ok and conn then
						table.insert(c.conns, conn)
					end
				end
			end
			pcall(function()
				table.insert(c.conns, lf:GetDataChangedSignal("ItemsLocked"):Connect(stale))
			end)
		end
		local now = os.clock()
		if c.dirty or now - c.at > 0.2 then
			c.dirty, c.at = false, now
			c.alive, c.locked, c.hp, c.maxHp = false, false, nil, nil
			if type(lf.IsAlive) == "function" then
				local okA, alive = pcall(lf.IsAlive, lf)
				c.alive = okA and alive == true
			end
			-- the round-start countdown: ClientFighter:Input drops every item input while the items are locked
			if type(lf.AreItemsLocked) == "function" then
				local okL, locked = pcall(lf.AreItemsLocked, lf)
				c.locked = okL and locked == true
			end
			if type(lf.GetHealth) == "function" and type(lf.GetMaxHealth) == "function" then
				local okH, hp = pcall(lf.GetHealth, lf)
				local okM, mx = pcall(lf.GetMaxHealth, lf)
				if okH and type(hp) == "number" then
					c.hp = hp
				end
				if okM and type(mx) == "number" then
					c.maxHp = mx
				end
			end
		end
		return c
	end

	-- what am I holding, ammo, hp, aiming, alive
	-- one table reused every frame (consumers read S.gameState fields, nobody keeps the table),
	-- no per-call closures; the held item comes from the per-frame weapon profile
	Game._state = { weapon = "—", alive = false, aiming = false }
	function Game.state(): any
		local st: any = Game._state
		st.weapon, st.alive, st.aiming, st.locked = "—", false, false, false
		st.hp, st.maxHp, st.item, st.ammo, st.maxAmmo, st.reserve = nil, nil, nil, nil, nil, nil
		local lf = Game.localFighter()
		if not lf then
			return st
		end
		local v = Game.vitalsOf(lf)
		st.alive, st.locked, st.hp, st.maxHp = v.alive, v.locked, v.hp, v.maxHp
		local item = Game.weaponProfile().item
		if item then
			st.weapon = tostring(item.Name)
			st.item = item
			if type(item.IsFullyAiming) == "function" then
				local okF, aiming = pcall(item.IsFullyAiming, item)
				st.aiming = okF and aiming == true
			end
			st.ammo, st.maxAmmo, st.reserve = Game.itemAmmo(item)
		end
		return st
	end

	function Game.myHealth(): (number?, number?)
		local lf = Game.localFighter()
		if not lf then
			return nil, nil
		end
		local v = Game.vitalsOf(lf)
		if v.hp ~= nil and v.maxHp ~= nil then
			return v.hp, v.maxHp
		end
		return nil, nil
	end

	-- what am I holding → how should rage behave. Memoised per frame: it was rebuilt 3–5 times a
	-- frame (target pick, auto shoot, auto block, backstab, state) and each rebuild walked every
	-- item with one or two pcalls.
	Game._prof = { melee = false, projectile = false, pellets = 1, name = "—", item = nil }
	Game._profFrame = -1
	-- one item → its class and the numbers the trigger, magic, origin and melee paths read. RIVALS item
	-- types are Gun, Melee, Throwable and Custom; a Riot Shield is a Melee item that absorbs damage
	-- (AbsorptionPercent / MaxAbsorption). Guns default to the rifle class; a Throwable or Custom item is
	-- a utility — never the melee path, never the gun silent path. Pure: tests pass fake items.
	function Game.profileOf(item: any, prof: any): any
		prof.melee, prof.projectile, prof.pellets, prof.name, prof.item = false, false, 1, "—", nil
		prof.gun, prof.shield, prof.utility, prof.crit, prof.scoped = false, false, false, false, false
		prof.class, prof.cooldown, prof.spamFlag, prof.burst, prof.reach, prof.type = "none", nil, nil, 1, nil, nil
		if type(item) ~= "table" then
			return prof
		end
		prof.name = tostring(item.Name)
		prof.item = item
		local info = item.Info
		if type(info) ~= "table" then
			return prof
		end
		local ty = info.Type
		prof.type = ty
		prof.projectile = info.IsProjectile == true
		prof.pellets = tonumber(info.ShootPellets) or 1
		prof.cooldown = tonumber(info.ShootCooldown) or tonumber(info.AttackCooldown)
		local ise = info.InputSpammingEnabled
		prof.spamFlag = if type(ise) == "table" then ise.StartShooting else nil
		prof.scoped = info.AimScopePercent ~= nil
		prof.burst = tonumber(info.BurstCount) or 1
		prof.reach = tonumber(info.AttackReach)
		-- the Flamethrower is a "Custom" item now (library survey) but fires like a hold gun; the Warper
		-- (Custom, a teleport tool) stays a utility — auto-firing it would throw us around the map
		if ty == "Gun" or (ty == "Custom" and prof.name == "Flamethrower") then
			prof.gun = true
			prof.class = if prof.name == "Flamethrower" then "flamethrower" elseif prof.projectile then "projectile" elseif prof.scoped then "sniper" elseif prof.burst > 1 then "burst" elseif prof.pellets > 1 then "shotgun" else "rifle"
		elseif ty == "Melee" and (info.AbsorptionPercent ~= nil or info.MaxAbsorption ~= nil or string.find(prof.name, "Shield", 1, true) ~= nil) then
			prof.shield = true
			prof.class = "shield"
		elseif ty == "Melee" then
			prof.melee = true
			local light = tonumber(info.AttackDamage) or tonumber(info.Damage) or 0
			prof.crit = prof.reach ~= nil and (tonumber(info.CriticalDamage) or 0) > light
			prof.class = if prof.crit then "crit melee" else "melee"
		else
			prof.utility = true
			prof.class = "utility"
		end
		return prof
	end
	Game.classSeen = {}
	function Game.weaponProfile(): any
		local prof = Game._prof
		if Game._profFrame == Game.frameId then
			return prof
		end
		Game._profFrame = Game.frameId
		Game.profileOf(Game.activeItem(Game.localFighter()), prof)
		-- once per weapon: what it is taken for (an unknown gun is a rifle, never melee)
		if prof.item and not Game.classSeen[prof.name] then
			Game.classSeen[prof.name] = true
			log("INFO", ("[weapon:class:%s] %s · type %s · cooldown %s · scope %s · burst %d · pellets %d · reach %s · spam %s"):format(prof.name, prof.class, tostring(prof.type), tostring(prof.cooldown), tostring(prof.scoped), prof.burst, prof.pellets, tostring(prof.reach), tostring(prof.spamFlag)))
		end
		return prof
	end

	-- Enemies expose their held item as `fighter.EquippedItem` (a ClientItem); only the LOCAL fighter
	-- uses the Items/IsMainItem path. Using activeItem() on an enemy returns nil — which silently
	-- disabled the whole katana detector. Read EquippedItem for enemies, fall back to activeItem.
	function Game.enemyEquipped(fighter: any): any
		if type(fighter) == "table" then
			local eq = fighter.EquippedItem
			if type(eq) == "table" and type(eq.Info) == "table" then
				return eq
			end
		end
		return Game.activeItem(fighter)
	end

	function Game.enemyHasKatanaOut(fighter: any): boolean
		local item = Game.enemyEquipped(fighter)
		if not item then
			return false
		end
		local nm = string.lower(tostring(item.Name or ""))
		local isMelee = type(item.Info) == "table" and item.Info.Type ~= "Gun"
		return isMelee and (nm:find("katana") ~= nil or nm:find("sword") ~= nil or nm:find("blade") ~= nil)
	end

	-- enemy look direction from their replicated rotation (falls back to the root part)
	function Game.enemyLook(fighter: any): Vector3?
		local root = Game.fighterBody(fighter)
		if not root then
			return nil
		end
		if type(fighter.GetCameraRotation) == "function" then
			local ok, rot = pcall(fighter.GetCameraRotation, fighter)
			if ok and typeof(rot) == "Vector2" then
				return CFrame.fromOrientation(rot.X, rot.Y, 0).LookVector
			end
		end
		return root.CFrame.LookVector
	end

	-- the physical character is what the server replicates (LP.Character == LocalFighter.Entity.Model)
	-- per frame: 21 call sites (bot scan, combat, ESP) each did FindFirstChild + IsA
	Game._rootFrame = -1
	Game._root = nil
	function Game.myRoot(): BasePart?
		if Game._rootFrame == Game.frameId and Game._root and Game._root.Parent ~= nil then
			return Game._root
		end
		local char = LP.Character
		local hrp = char and char:FindFirstChild("HumanoidRootPart")
		local root = if hrp and hrp:IsA("BasePart") then hrp else Game.fighterBody(Game.localFighter())
		Game._root = root
		Game._rootFrame = Game.frameId
		return root
	end
	-- 15240 → "15,240"
	function Game.studs(n: number): string
		local s = tostring(math.floor(math.max(n, 0) + 0.5))
		local guard = 0
		while guard < 6 do
			guard += 1
			local k
			s, k = string.gsub(s, "^(%d+)(%d%d%d)", "%1,%2")
			if k == 0 then
				break
			end
		end
		return s
	end

	function Game.w2s(pos: Vector3): Vector2?
		local cam = workspace.CurrentCamera
		if not cam then
			return nil
		end
		local v, on = cam:WorldToViewportPoint(pos)
		if not on or v.Z <= 0 then
			return nil
		end
		return Vector2.new(v.X, v.Y)
	end
	-- like w2s but for anything in FRONT of the camera, off-viewport included: box corners of a
	-- half-visible enemy still project (the box is clipped by the screen, not dropped)
	function Game.w2sFront(pos: Vector3): Vector2?
		local cam = workspace.CurrentCamera
		if not cam then
			return nil
		end
		local v = cam:WorldToViewportPoint(pos)
		if v.Z <= 0.05 then
			return nil
		end
		return Vector2.new(v.X, v.Y)
	end

	-- Line of sight the way the SERVER sees it. The game's shot ray is an Include cast over
	-- LocalFighter:GetRaycastWhitelist() (map Barriers/Extra, the range walls) plus the enemies'
	-- hitboxes — so that is exactly what may block us. The old Exclude cast from the render camera
	-- counted our own viewmodel, other players' bodies, glass and decoration as cover and, in third
	-- person, started behind our own back: the source of "body aim when the head is clearly open"
	-- and of server WALL results. The origin defaults to where the shot really leaves (head).
	local visParams = RaycastParams.new()
	visParams.FilterType = Enum.RaycastFilterType.Include
	visParams.IgnoreWater = true
	visParams.RespectCanCollide = false
	local visFallback = RaycastParams.new()
	visFallback.FilterType = Enum.RaycastFilterType.Exclude
	visFallback.IgnoreWater = true
	local losList: { Instance } = {}
	local losFrame = -1
	local losOk = false
	-- THE shot origin, one definition for the rotation stream, the echo gate, LOS and the planner: the
	-- position the shot payload carries in [\0].
	function Game.shotOriginPos(): Vector3?
		-- v5.0.4, duel-verified: the payload's [\0] (the server's shot origin, Gun._LocalTracers casts
		-- from it) is CameraController:GetCameraCFrame().Position = the character's camera anchor,
		-- RootPart + 1.75 st = the head + ~0.35 — NOT the rendered camera (third person had it 7000 st
		-- away). One origin for the stream, the echo, LOS and the planner.
		local head = S.myHeadPart
		if head and head.Parent then
			return head.Position + Vector3.new(0, 0.35, 0)
		end
		local root = S.myRootPart
		if root and root.Parent then
			return root.Position + Vector3.new(0, 1.75, 0)
		end
		local cam = workspace.CurrentCamera
		return cam and cam.CFrame.Position
	end
	-- v5.2 perf: the game builds GetRaycastWhitelist(true) by walking every entity's parts — measured
	-- 4.3 ms per call with the range's 200 targets, and it ran once EVERY frame (it was most of the
	-- frame budget: the "situation" / "esp" / "scan" steps only looked expensive because whichever
	-- ran first paid for it). The list only changes when an entity spawns / dies or the map changes,
	-- so it is reused for LOS_TTL seconds (twice that at perf tier ≥ 2) and rebuilt early when the
	-- enemy count or the local fighter object moves. A stale list only means a fighter who spawned
	-- inside the window is not cover for ≤ 250 ms; the target's own verdict never depends on it.
	Game.LOS_TTL = 0.25
	Game.losBuiltAt = -1
	Game.losBuiltCount = -1
	Game.losBuiltLf = nil
	Game.losRebuilds = 0
	function Game.losParams(): RaycastParams?
		if losFrame == Game.frameId then
			return if losOk then visParams else nil
		end
		losFrame = Game.frameId
		local lf = Game.localFighter()
		local now = os.clock()
		local ttl = if (S.perfTier or 0) >= 2 then Game.LOS_TTL * 2 else Game.LOS_TTL
		if losOk and lf == Game.losBuiltLf and #enemyCache == Game.losBuiltCount and now - Game.losBuiltAt < ttl then
			return visParams
		end
		losOk = false
		table.clear(losList)
		if lf and type(lf.GetRaycastWhitelist) == "function" then
			-- v5.0.4, duel-verified: the server's tracer (Gun._LocalTracers, decompiled) casts through
			-- GetRaycastWhitelist(true) — the map folders PLUS every entity's parts: breakable windows,
			-- other fighters' hitboxes. Without the flag a window between us and the target read as clear
			-- and the round went into the glass (WALL → WindowExtra.Part / Fence / Crate in the duel log)
			local ok, wl = pcall(lf.GetRaycastWhitelist, lf, true)
			if ok and type(wl) == "table" then
				for _, inst in ipairs(wl) do
					if typeof(inst) == "Instance" then
						table.insert(losList, inst)
					end
				end
			end
		end
		if #losList == 0 then
			return nil
		end
		for _, f in ipairs(enemyCache) do
			local _, m = Game.fighterBody(f)
			if m then
				table.insert(losList, m)
			end
		end
		visParams.FilterDescendantsInstances = losList
		losOk = true
		Game.losBuiltAt, Game.losBuiltCount, Game.losBuiltLf = now, #enemyCache, lf
		Game.losRebuilds += 1
		return visParams
	end
	-- one raycast per part per frame: the lock, the ESP visibility colour and the hitbox picker all
	-- ask about the same parts within the same frame (memo keyed on part, valid for the frame)
	Game.losMemo = {}
	Game.losMemoFrame = -1
	-- is `inst` (a raycast hit inside an enemy model) part of a Riot Shield? The shield's world model is
	-- a ViewModel welded into the character ("Riot Shield" / "Glorious Riot Shield" equipped,
	-- "UnequippedViewModel" on the back); ordinary hitboxes are direct children named Hitbox*/limbs.
	-- Cached per instance (weak keys): this runs inside the per-frame LOS ray.
	Game.shieldMemo = setmetatable({}, { __mode = "k" })
	-- every Riot Shield model name: the item and each of its skins. Skins without "Shield" in the name (Door,
	-- Sled, Masterpiece…) went unrecognised, so a shield with one of those skins read as an open line. Built
	-- from ItemLibrary.ViewModels (every viewmodel that plays the riotshield animations), once.
	Game.SHIELD_FALLBACK = { "Door", "Sled", "Masterpiece" }
	function Game.shieldNames(): { [string]: boolean }
		if Game.shieldSet then
			return Game.shieldSet
		end
		local set = {}
		for _, n in ipairs(Game.SHIELD_FALLBACK) do
			set[n] = true
		end
		pcall(function()
			for name, vm in pairs(ItemLibrary.ViewModels or {}) do
				local anims = type(vm) == "table" and vm.Animations
				if type(name) == "string" and type(anims) == "table" then
					for _, a in pairs(anims) do
						if type(a) == "string" and a:find("riotshield", 1, true) then
							set[name] = true
							break
						end
					end
				end
			end
		end)
		-- kept only once the library is loaded (an early ask would otherwise pin the fallback list for the session)
		if type(ItemLibrary) == "table" then
			Game.shieldSet = set
		end
		return set
	end
	function Game.isShieldPart(inst: Instance, model: Model?): boolean
		local m = Game.shieldMemo[inst]
		if m ~= nil then
			return m
		end
		local names = Game.shieldNames()
		local res = false
		local cur: Instance? = inst
		local depth = 0
		while cur and (cur :: any) ~= model and depth < 6 do
			local n = cur.Name
			if n:find("Shield", 1, true) or n == "UnequippedViewModel" or names[n] then
				res = true
				break
			end
			cur = cur.Parent
			depth += 1
		end
		Game.shieldMemo[inst] = res
		return res
	end
	function Game.rayVisible(model: Model?, part: BasePart?, from: Vector3?): boolean
		if not part then
			return false
		end
		local memo = from == nil
		if memo then
			if Game.losMemoFrame ~= Game.frameId then
				Game.losMemoFrame = Game.frameId
				table.clear(Game.losMemo)
			end
			local m = Game.losMemo[part]
			if m ~= nil then
				return m
			end
		end
		local origin = from or Game.shotOriginPos()
		if not origin then
			return false
		end
		local params = Game.losParams()
		local dir = part.Position - origin
		if params then
			local hit = workspace:Raycast(origin, dir, params)
			local vis = hit == nil or (model ~= nil and (hit.Instance == model or hit.Instance:IsDescendantOf(model)))
			-- v5.0.3 shield awareness: the Riot Shield (AbsorptionPercent 1, 500 HP) is a part welded into
			-- their model — held in front when equipped, on the BACK when not (`_riot_shield_back`). The
			-- server ray that lands on it is absorbed, so a ray that ends on a shield part is NOT a line to
			-- the hitbox: origins / hitboxes behind it are never chosen
			if vis and hit ~= nil and cfg.shieldAware and hit.Instance ~= part and Game.isShieldPart(hit.Instance, model) then
				vis = false
			end
			-- the memo is only valid for a verdict that knew the model: a model-less first ask
			-- stores "the target's own hitbox is cover" and every later ask that frame reuses it
			if memo and model ~= nil then
				Game.losMemo[part] = vis
			end
			return vis
		end
		-- no whitelist yet (fresh place): exclude ourselves and our viewmodels; the filter is built
		-- once per frame (it used to be rebuilt, viewmodel scan included, per enemy per raycast)
		if Game.fallbackFilterFrame ~= Game.frameId then
			Game.fallbackFilterFrame = Game.frameId
			local filter = Game.fallbackFilter
			table.clear(filter)
			if LP.Character then
				table.insert(filter, LP.Character)
			end
			for _, vm in ipairs(Game.viewmodelModels()) do
				table.insert(filter, vm)
			end
			visFallback.FilterDescendantsInstances = filter
		end
		local hit = workspace:Raycast(origin, dir, visFallback)
		local vis = hit == nil or (model ~= nil and (hit.Instance == model or hit.Instance:IsDescendantOf(model)))
		if memo and model ~= nil then
			Game.losMemo[part] = vis
		end
		return vis
	end
	Game.fallbackFilter = {}
	Game.fallbackFilterFrame = -1

	local pingCache, pingAt = 0, 0
	function Game.pingMs(): number
		local now = os.clock()
		if now - pingAt < 0.5 then
			return pingCache
		end
		pingAt = now
		local ok, v = pcall(function()
			return Stats.Network.ServerStatsItem["Data Ping"]:GetValue()
		end)
		if ok and type(v) == "number" and v > 0 then
			pingCache = math.floor(v)
			return pingCache
		end
		ok, v = pcall(function()
			return LP:GetNetworkPing() * 1000
		end)
		-- a failed read keeps the last good value (it used to drop to 0, which every timing then trusted)
		if ok and type(v) == "number" and v > 0 then
			pingCache = math.floor(v)
		end
		return pingCache
	end
	-- the ping players compare against: Roblox's own performance stat (what its overlay shows). "Data Ping"
	-- above reads ~35 ms higher (it includes the server's data processing) — right for timing, wrong for a
	-- readout. nil when nothing answers, so the HUD shows "—" instead of a fake 0.
	Game.dispPing, Game.dispPingAt = nil, -1
	function Game.displayPingMs(): number?
		local now = os.clock()
		if now - Game.dispPingAt < 0.2 then
			return Game.dispPing
		end
		Game.dispPingAt = now
		local ok, v = pcall(function()
			return Stats.PerformanceStats.Ping:GetValue()
		end)
		if not (ok and type(v) == "number" and v > 0 and v < 10000) then
			ok, v = pcall(function()
				return LP:GetNetworkPing() * 1000
			end)
		end
		if not (ok and type(v) == "number" and v > 0 and v < 10000) then
			local dp = Game.pingMs()
			v = if dp > 0 then dp else nil
		end
		Game.dispPing = if v then math.floor(v + 0.5) else nil
		return Game.dispPing
	end

	function Game.setCamRotation(cf: CFrame)
		local pitch, yaw = cf:ToOrientation()
		Game.asGame(CameraController.SetRotation, CameraController, Vector2.new(pitch, yaw))
	end

	function Game.remote(folder: string, name: string): Instance?
		local rem = ReplicatedStorage:FindFirstChild("Remotes")
		local f = rem and rem:FindFirstChild(folder)
		local r = f and f:FindFirstChild(name)
		if r then
			return r
		end
		-- v5.2: the folder moved / was renamed → the remote by name anywhere under Remotes
		local Adapt = Game.adapt
		return if Adapt then Adapt.findRemote(name) else nil
	end

	-----------------------------------------------------------------------------
	-- §4c adapt (v5.2) — survive RIVALS updates. One place that (1) knows every game contract this
	-- script relies on and can verify it on demand, (2) discovers renamed pieces where a heuristic
	-- exists (remotes anywhere under Remotes, controllers by their fields, hitboxes by name pattern,
	-- the game's own rotation encoder), (3) turns a broken contract into ONE disabled feature plus a
	-- plain-words note instead of a dead script, (4) notices a new RIVALS build (game.PlaceVersion)
	-- and re-verifies, and (5) asks the daemon for a newer centerra and reloads it in the lobby.
	-- Block-scoped like Bounds (200-register cap): S.adapt / Game.adapt.
	-----------------------------------------------------------------------------
	do
	local Adapt: any = { broken = {}, results = {}, pending = 0, n = 0, nBroken = 0, verifiedAt = 0, remoteScanAt = -10, remoteList = {} }
	S.adapt = Adapt
	Game.adapt = Adapt
	-- a contract failed: remembered, logged once per note, toasted once (the dependent feature is off)
	function Adapt.flag(name: string, note: string, quiet: boolean?)
		if Adapt.broken[name] == note then
			return
		end
		Adapt.broken[name] = note
		log("WARN", ("adapt: %s — %s"):format(name, note))
		if not quiet and S.cfg.adaptToasts ~= false then
			notify(("game update? %s: %s"):format(name, note), 7, "warn")
		end
	end
	function Adapt.clear(name: string)
		if Adapt.broken[name] ~= nil then
			Adapt.broken[name] = nil
			log("INFO", ("adapt: %s — ok again"):format(name))
		end
	end
	function Adapt.ok(name: string): boolean
		return Adapt.broken[name] == nil
	end
	function Adapt.brokenList(): { string }
		local out = {}
		for k, v in pairs(Adapt.broken) do
			table.insert(out, k .. ": " .. v)
		end
		table.sort(out)
		return out
	end
	-- a remote by name anywhere under ReplicatedStorage.Remotes (descendants cached 5 s; only asked
	-- while a fixed path misses, so the scan never runs on a healthy game)
	function Adapt.findRemote(name: string, className: string?): Instance?
		local now = os.clock()
		if now - Adapt.remoteScanAt > 5 then
			Adapt.remoteScanAt = now
			table.clear(Adapt.remoteList)
			local rem = ReplicatedStorage:FindFirstChild("Remotes")
			if rem then
				for i, d in ipairs(rem:GetDescendants()) do
					if i > 3000 then
						break
					end
					table.insert(Adapt.remoteList, d)
				end
			end
		end
		local lower = string.lower(name)
		local loose: Instance? = nil
		for _, d in ipairs(Adapt.remoteList) do
			if d.Parent ~= nil and (className == nil or d:IsA(className)) then
				if d.Name == name then
					return d
				end
				if loose == nil and string.lower(d.Name) == lower then
					loose = d
				end
			end
		end
		return loose
	end
	-- a method through a class table's __index chain (the RIVALS classes inherit a shared base)
	function Adapt.method(cls: any, name: string): any
		local t = cls
		local depth = 0
		while type(t) == "table" and depth < 6 do
			local v = rawget(t, name)
			if type(v) == "function" then
				return v
			end
			local mt = getmetatable(t)
			t = mt and mt.__index
			depth += 1
		end
		return nil
	end
	-- the game's own rotation encoder (ReplicatedStorage.Modules.Utility) — parity check + adoption
	-- (memoised: requireIfLoaded walks the whole loaded-module list, ~3 ms per miss)
	function Adapt.gameEncoder(): any
		if Adapt.U then
			return Adapt.U
		end
		local mods = ReplicatedStorage:FindFirstChild("Modules")
		local util = mods and mods:FindFirstChild("Utility")
		local U = Game.requireIfLoaded(util)
		if type(U) == "table" and type(U.EncodeCameraRotation) == "function" then
			Adapt.U = U
			return U
		end
		return nil
	end
	function Adapt.mechanics(): any
		if Adapt.MC then
			return Adapt.MC
		end
		local ps = LP:FindFirstChild("PlayerScripts")
		local ctrl = ps and ps:FindFirstChild("Controllers")
		local mc = Game.requireIfLoaded(ctrl and ctrl:FindFirstChild("MechanicsController"))
		if type(mc) == "table" then
			Adapt.MC = mc
		end
		return mc
	end
	-- the contracts. Each returns (state, note) with state: true ok · false broken · nil not
	-- checkable yet (no fighter / module not loaded) — those stay pending and are re-run by tick().
	Adapt.CONTRACTS = {
		{ "FighterController", "core", function()
			return type(FighterController) == "table" and (type(FighterController.GetFighter) == "function" or type(rawget(FighterController, "Objects")) == "table"), if Game.renamed.FighterController then "found as " .. Game.renamed.FighterController else "ok"
		end },
		{ "CameraController", "core", function()
			local need = { "GetCameraCFrame", "SetRotation", "SetThirdPersonOverride", "SetExternalFOVOffset", "Freeze" }
			local missing = {}
			for _, m in ipairs(need) do
				if type(CameraController) ~= "table" or type(CameraController[m]) ~= "function" then
					table.insert(missing, m)
				end
			end
			return #missing == 0, if #missing == 0 then (if Game.renamed.CameraController then "found as " .. Game.renamed.CameraController else "ok") else "missing " .. table.concat(missing, ", ") .. " → camera / third person / FOV features off"
		end },
		{ "PlayerDataController", "skins", function()
			return not (type(PlayerDataController) ~= "table" or PlayerDataController._stub), if PlayerDataController and PlayerDataController._stub then "missing → skins / inventory unlock off" else "ok"
		end },
		{ "CosmeticLibrary", "skins", function()
			return not (type(CosmeticLibrary) ~= "table" or CosmeticLibrary._stub), if CosmeticLibrary and CosmeticLibrary._stub then "missing → skins off" else "ok"
		end },
		{ "EnumLibrary", "skins", function()
			return not (type(EnumLibrary) ~= "table" or EnumLibrary._stub), if EnumLibrary and EnumLibrary._stub then "missing → data keys used as plain strings" else "ok"
		end },
		{ "ItemLibrary", "weapons", function()
			local items = type(ItemLibrary) == "table" and ItemLibrary.Items
			if type(items) ~= "table" then
				return false, "ItemLibrary.Items missing → weapon stats / rapid fire off"
			end
			local gun, melee = nil, nil
			for _, info in pairs(items) do
				if type(info) == "table" then
					if info.Type == "Gun" and gun == nil then
						gun = info
					elseif info.Type ~= "Gun" and info.AttackReach ~= nil and melee == nil then
						melee = info
					end
				end
			end
			local missing = {}
			if gun then
				for _, k in ipairs({ "ShootCooldown", "ShootSpread", "AimSpreadMultiplier", "MaxAmmo" }) do
					if gun[k] == nil then
						table.insert(missing, k)
					end
				end
			end
			if melee then
				for _, k in ipairs({ "AttackCooldown", "AttackReach" }) do
					if melee[k] == nil then
						table.insert(missing, k)
					end
				end
			end
			return #missing == 0, if #missing == 0 then "gun + melee stat keys present" else "stat keys renamed: " .. table.concat(missing, ", ")
		end },
		{ "fighter class", "silent", function()
			local lf = Game.localFighter()
			if type(lf) ~= "table" or lf._fallback then
				return nil, "no fighter yet"
			end
			local missing = {}
			for _, m in ipairs({ "GetCameraData", "GetMouseLocation", "GetCameraRotation", "Input", "GetRaycastWhitelist", "IsAlive", "GetHealth", "GetMaxHealth", "Get" }) do
				if type(lf[m]) ~= "function" then
					table.insert(missing, m)
				end
			end
			return #missing == 0, if #missing == 0 then "all 9 methods" else "missing " .. table.concat(missing, ", ") .. " → the silent layers that use them are off"
		end },
		{ "fighter data", "targeting", function()
			local lf = Game.localFighter()
			if type(lf) ~= "table" or lf._fallback or type(lf.Get) ~= "function" then
				return nil, "no fighter yet"
			end
			local okT, team = pcall(lf.Get, lf, "TeamID")
			local okR, rot = pcall(lf.Get, lf, "CameraRotation")
			local teamOk = okT and (team == nil or type(team) == "string")
			local rotOk = okR and (rot == nil or typeof(rot) == "Vector2")
			return teamOk and rotOk, if teamOk and rotOk then "TeamID / CameraRotation readable" else ("Get(%s) changed shape → team check / echo may be wrong"):format(if not teamOk then "TeamID" else "CameraRotation")
		end },
		{ "MechanicsController", "trigger", function()
			local mc = Adapt.mechanics()
			if type(mc) ~= "table" then
				return nil, "not loaded yet"
			end
			local missing = {}
			for _, m in ipairs({ "EquippedItemInput", "SimulateInputBegan" }) do
				if type(mc[m]) ~= "function" then
					table.insert(missing, m)
				end
			end
			return #missing == 0, if #missing == 0 then "game-level input present" else "missing " .. table.concat(missing, ", ") .. " → trigger falls back to VirtualInputManager"
		end },
		{ "Gun class", "trigger", function()
			-- a gun the local fighter holds: its metatable chain is the Gun class
			local lf = Game.localFighter()
			local gun: any = nil
			if type(lf) == "table" and type(lf.Items) == "table" then
				for _, it in pairs(lf.Items) do
					if type(it) == "table" and type(it.Info) == "table" and it.Info.Type == "Gun" then
						gun = it
						break
					end
				end
			end
			if type(gun) ~= "table" then
				return nil, "no gun in the loadout yet"
			end
			local missing = {}
			for _, m in ipairs({ "StartShooting", "IsFullyAiming", "_ShootEffect", "GetAmmoVariables" }) do
				if not Adapt.method(gun, m) then
					table.insert(missing, m)
				end
			end
			return #missing == 0, if #missing == 0 then "shot / claim / verdict methods present" else "missing " .. table.concat(missing, ", ") .. " → spread claim / shot verdicts off"
		end },
		{ "rotation remote", "anti-aim", function()
			local r = S.h and S.h.rotRemote
			if not r then
				return if os.clock() - Adapt.loadedAt > 60 then false else nil, "UpdateCameraRotation not found → rotation channel off"
			end
			return true, r.ClassName .. (if r:IsA("UnreliableRemoteEvent") then "" else " (was UnreliableRemoteEvent)")
		end },
		{ "OOB remote", "bounds", function()
			local r = S.h and S.h.oobRemote
			if not r then
				return if os.clock() - Adapt.loadedAt > 60 then false else nil, "OutOfBounds remote not found → OOB swallow off (hook guard still works)"
			end
			return true, "ok"
		end },
		{ "equip remote", "skins", function()
			if CosmeticLibrary and CosmeticLibrary._stub then
				return true, "n/a (no cosmetics)"
			end
			return (S.h and S.h.equipRemote) ~= nil, if S.h and S.h.equipRemote then "ok" else "Data/EquipCosmetic not found → unowned-skin equip pass-through"
		end },
		{ "rotation encoder", "anti-aim", function()
			local U = Adapt.gameEncoder()
			if not U then
				return nil, "Utility not loaded yet"
			end
			local mine = S.h and S.h.encodeRot
			if type(mine) ~= "function" then
				return nil, "encoder not built yet"
			end
			local bad = 0
			for _, v in ipairs({ Vector2.new(-0.5081, -4.7467), Vector2.new(0.3, 1.2), Vector2.new(-1.4, 6.1), Vector2.new(2.9, -0.02) }) do
				local ok, theirs = pcall(U.EncodeCameraRotation, U, v)
				if not ok or theirs ~= mine(v) then
					bad += 1
				end
			end
			if bad > 0 and not Adapt.encoderAdopted then
				-- adopt the game's encoder: the wire format changed, ours would send garbage
				Adapt.encoderAdopted = true
				S.h.encodeRot = function(rot: Vector2): string?
					if typeof(rot) ~= "Vector2" then
						return nil
					end
					local ok, enc = pcall(U.EncodeCameraRotation, U, rot)
					return if ok and type(enc) == "string" then enc else nil
				end
				return true, "wire format changed → using the game's own Utility:EncodeCameraRotation"
			end
			return true, if Adapt.encoderAdopted then "using the game's encoder" else "byte-identical to Utility:EncodeCameraRotation"
		end },
		{ "hitbox parts", "aim", function()
			local seen, named = 0, 0
			for _, f in ipairs(Game.enemies()) do
				if not f.IsBot and not f._fallback then
					local _, m = Game.fighterBody(f)
					if m then
						seen += 1
						if m:FindFirstChild("HitboxHead") or m:FindFirstChild("HitboxBody") then
							named += 1
						end
					end
				end
			end
			if seen == 0 then
				return nil, "no enemy fighters to inspect"
			end
			return named > 0, if named > 0 then ("HitboxHead / HitboxBody on %d of %d"):format(named, seen) else "no Hitbox* parts on any enemy → aiming at visual parts (Head / HumanoidRootPart)"
		end },
		{ "shot payload", "silent", function()
			local d = S.cdDbg
			if not d or (d.localZero or 0) == 0 then
				return nil, "no shot seen yet"
			end
			if d.shapeUnknown then
				return false, "camera-data shape unknown → silent layer 0 leaves shots untouched"
			end
			return true, if d.compressed then "compressed 6-number CFrames" else "plain CFrames"
		end },
		{ "shot verdicts", "learners", function()
			local sh = S.shots
			local st = type(sh) == "table" and type(sh.stats) == "table" and sh.stats or nil
			if not st then
				return nil, "recorder not built yet"
			end
			local answered = (st.hit or 0) + (st.near or 0) + (st.wall or 0) + (st.air or 0)
			local total = answered + (st.noReply or 0)
			if total < 8 then
				return nil, ("fewer than 8 gun shots this session (%d)"):format(total)
			end
			return answered > 0, if answered > 0 then ("%d of %d shots answered by the server"):format(answered, total) else "no _ShootEffect answer in 8+ shots → verdict shape changed? learners paused"
		end },
		{ "hooks", "core", function()
			local inst = S.hooks and S.hooks.installed or {}
			local missing = {}
			for _, k in ipairs({ "camera", "namecall" }) do
				if inst[k] ~= true then
					table.insert(missing, k)
				end
			end
			-- the lazy groups only count once their subject exists (a real local fighter / a gun in hand)
			local lf = Game.localFighter()
			if type(lf) == "table" and not lf._fallback then
				for _, k in ipairs({ "fighterLocal", "cameraData" }) do
					if inst[k] ~= true then
						table.insert(missing, k)
					end
				end
				local hasGun = false
				if type(lf.Items) == "table" then
					for _, it in pairs(lf.Items) do
						if type(it) == "table" and type(it.Info) == "table" and it.Info.Type == "Gun" then
							hasGun = true
							break
						end
					end
				end
				if hasGun and inst.gun ~= true then
					table.insert(missing, "gun")
				end
			end
			if #missing > 0 and os.clock() - Adapt.loadedAt < 30 then
				return nil, "installing"
			end
			return #missing == 0, if #missing == 0 then "core groups on" else "not installed: " .. table.concat(missing, ", ")
		end },
	}
	Adapt.loadedAt = os.clock()
	-- run every contract (pending ones stay pending); flags / clears the broken set; returns the summary
	function Adapt.verify(reason: string?): any
		local res = Adapt.results
		table.clear(res)
		local pending, broken = 0, 0
		for _, c in ipairs(Adapt.CONTRACTS) do
			local name, feature, fn = c[1], c[2], c[3]
			local ok, state, note = pcall(fn)
			if not ok then
				state, note = false, "check errored: " .. tostring(state):sub(1, 60)
			end
			if state == nil then
				pending += 1
			elseif state == false then
				broken += 1
				Adapt.flag(name, tostring(note or "broken"), feature == "skins" or feature == "learners")
			else
				Adapt.clear(name)
			end
			table.insert(res, { name = name, feature = feature, ok = state, note = tostring(note or "") })
		end
		Adapt.n, Adapt.nBroken, Adapt.pending, Adapt.verifiedAt = #Adapt.CONTRACTS, broken, pending, os.clock()
		-- one line per CHANGE of the picture (a periodic pass that found the same thing stays silent)
		local sig = broken .. "/" .. pending
		if sig ~= Adapt.lastSig or reason == "manual" or reason == "self-test" then
			Adapt.lastSig = sig
			if broken > 0 then
				log("WARN", ("adapt (%s): %d/%d contracts broken, %d pending — %s"):format(reason or "verify", broken, #Adapt.CONTRACTS, pending, table.concat(Adapt.brokenList(), "; ")))
			else
				log("INFO", ("adapt (%s): %d/%d contracts ok, %d pending"):format(reason or "verify", #Adapt.CONTRACTS - pending, #Adapt.CONTRACTS, pending))
			end
		end
		return { total = #Adapt.CONTRACTS, broken = broken, pending = pending, results = res }
	end
	-- a new RIVALS build since the last verified load → say so and re-verify
	function Adapt.checkBuild()
		local ok, pv = pcall(function()
			return game.PlaceVersion
		end)
		if not (ok and type(pv) == "number") then
			return
		end
		Adapt.build = pv
		-- every place (lobby, each match map) has its own version counter → remembered per place id
		if type(S.cfg.placeVersions) ~= "table" then
			S.cfg.placeVersions = {}
		end
		local key = tostring(game.PlaceId)
		local last = tonumber(S.cfg.placeVersions[key]) or 0
		if last ~= pv then
			if last > 0 then
				log("WARN", ("adapt: RIVALS build changed %d → %d (place %s) — re-verifying every game contract"):format(last, pv, key))
				notify(("RIVALS updated (build %d → %d) — centerra is re-checking the game"):format(last, pv), 6, "info")
				Adapt.buildChanged = true
			end
			S.cfg.placeVersions[key] = pv
			pcall(saveConfig)
		end
	end
	-- from the loop: pending contracts re-run every 5 s (the fighter, Gun, remotes appear late), the
	-- whole set every 60 s (cheap: table reads + a handful of pcalls)
	function Adapt.tick()
		local now = os.clock()
		if now - Adapt.verifiedAt >= (if Adapt.pending > 0 then 5 else 60) then
			Adapt.verify("periodic")
		end
	end
	-- self-update: the daemon serves this machine's centerra.lua fresh from disk; a newer VERSION there
	-- reloads here — in the lobby only (a match reload would drop the lock mid-fight; the hop loader
	-- fetches the newest source on the next server anyway). Yields: run from a task.
	Adapt.UPDATE_URLS = { "http://127.0.0.1:8866/lua/centerra" }
	function Adapt.versionNewer(a: string?, b: string?): boolean
		if type(a) ~= "string" or type(b) ~= "string" then
			return false
		end
		local pa, pb = {}, {}
		for n in a:gmatch("%d+") do
			table.insert(pa, tonumber(n))
		end
		for n in b:gmatch("%d+") do
			table.insert(pb, tonumber(n))
		end
		for i = 1, math.max(#pa, #pb) do
			local x, y = pa[i] or 0, pb[i] or 0
			if x ~= y then
				return x > y
			end
		end
		return false
	end
	function Adapt.fetchLatest(): (string?, string?)
		for _, url in ipairs(Adapt.UPDATE_URLS) do
			local src: any = nil
			if type(EXEC.request) == "function" then
				local ok, res = pcall(EXEC.request, { Url = url, Method = "GET" })
				if ok and type(res) == "table" and type(res.Body) == "string" then
					src = res.Body
				end
			end
			if type(src) ~= "string" or #src < 1000 then
				pcall(function()
					src = game:HttpGet(url .. "?t=" .. tostring(os.time()))
				end)
			end
			if type(src) == "string" and #src > 1000 and src:find("CenterraInit", 1, true) then
				return src, src:match('\nlocal VERSION%s*=%s*"([%d%.]+)"')
			end
		end
		return nil, nil
	end
	-- "safe to reload": anywhere but a live duel — RIVALS' root place (lobby + shooting range), a match
	-- waiting room, between duels. The same detector as the lobby gate (Game.duelLive).
	Adapt.LOBBY_PLACE = 17625359962
	function Adapt.inLobby(): boolean
		return not Game.duelLive()
	end
	function Adapt.checkUpdate(manual: boolean?)
		Adapt.lastUpdateCheck = os.clock()
		local src, v = Adapt.fetchLatest()
		if not src then
			if manual then
				notify("update check: the VoltMCP daemon did not answer (start-voltmcp.bat)", 4, "warn")
			end
			Adapt.daemonSeen = false
			return
		end
		Adapt.daemonSeen = true
		Adapt.latestVersion = v
		if v and Adapt.versionNewer(v, VERSION) then
			Adapt.pendingSrc, Adapt.pendingVersion = src, v
			if not Adapt.updateAnnounced or manual then
				Adapt.updateAnnounced = true
				notify(("centerra v%s is on the daemon (this is v%s) — %s"):format(v, VERSION, if S.cfg.autoUpdate then "it loads by itself in the lobby" else "Config → Updates → Reload the latest version"), 7, "info")
			end
		else
			Adapt.pendingSrc, Adapt.pendingVersion = nil, nil
			if manual then
				notify(if v then ("v%s is the latest on the daemon"):format(v) else "daemon source has no VERSION header", 3, "info")
			end
		end
	end
	-- run the pending (or freshly fetched) source: the new instance unloads this one first (§0)
	function Adapt.applyUpdate(src: string?): boolean
		src = src or Adapt.pendingSrc
		if type(src) ~= "string" then
			return false
		end
		local f, err = loadstring(src, "centerra")
		if type(f) ~= "function" then
			log("ERROR", "update: the fetched source does not compile: " .. tostring(err))
			Adapt.pendingSrc = nil
			return false
		end
		log("INFO", ("update: reloading centerra v%s over v%s"):format(tostring(Adapt.pendingVersion or "?"), VERSION))
		genv().CenterraManualInject = true
		Adapt.pendingSrc = nil
		task.spawn(f)
		return true
	end
	function Adapt.reloadLatest()
		task.spawn(function()
			local src, v = Adapt.fetchLatest()
			if not src then
				notify("reload: the VoltMCP daemon did not answer", 4, "warn")
				return
			end
			Adapt.pendingVersion = v or Adapt.pendingVersion
			Adapt.applyUpdate(src)
		end)
	end
	-- the loop's slow lane (every ~5 s): version poll every 5 min, auto-apply in the lobby when idle
	function Adapt.updateTick()
		if type(genv().CenterraLicense) == "table" then
			return -- licensed build: updates arrive through the centerra site (add-on notice + re-run)
		end
		local now = os.clock()
		if now - (Adapt.lastUpdateCheck or -1e9) > 300 and not Adapt.checking then
			Adapt.checking = true
			task.spawn(function()
				pcall(Adapt.checkUpdate, false)
				Adapt.checking = false
			end)
		end
		if Adapt.pendingSrc and S.cfg.autoUpdate and Adapt.inLobby() and not S.menuOpen and S.autokill.state == "idle" and not S.teleported and not S.lmbDown then
			Adapt.applyUpdate()
		end
	end
	end -- Adapt block

	-- our own viewmodel models. RIVALS does not parent them to the Camera: the held one lives in
	-- workspace.ViewModels.FirstPerson, third-person renders sit directly under workspace.ViewModels
	-- (named "<player> - <item> - <viewmodel>", other players' models share that folder).
	-- memoised per frame (third person, viewmodel hiding and the LOS fallback all ask in one frame)
	Game._vmFrame = -1
	Game._vmList = {}
	Game._vmPrefix = nil
	function Game.viewmodelModels(): { Instance }
		if Game._vmFrame == Game.frameId then
			return Game._vmList
		end
		Game._vmFrame = Game.frameId
		local out: { Instance } = Game._vmList
		table.clear(out)
		local prefix = Game._vmPrefix
		if not prefix then
			prefix = LP.Name .. " - "
			Game._vmPrefix = prefix
		end
		local root = workspace:FindFirstChild("ViewModels")
		if root then
			for _, m in ipairs(root:GetChildren()) do
				if m.Name == "FirstPerson" then
					for _, c in ipairs(m:GetChildren()) do
						table.insert(out, c)
					end
				elseif m.Name:sub(1, #prefix) == prefix then
					table.insert(out, m)
				end
			end
		end
		local cam = workspace.CurrentCamera
		if cam then
			for _, m in ipairs(cam:GetChildren()) do
				if m:IsA("Model") or m:IsA("BasePart") then
					table.insert(out, m)
				end
			end
		end
		return out
	end

	-- the weapon inside a viewmodel: ClientViewModel._Setup renames the item model to "ItemVisual" and
	-- parents it to the viewmodel; the arms (LeftArm / RightArm and the item pieces welded to them)
	-- live beside it
	function Game.viewmodelWeapon(vm: Instance): Instance?
		if not vm:IsA("Model") then
			return nil
		end
		local iv = vm:FindFirstChild("ItemVisual")
		return if iv and iv:IsA("Model") then iv else nil
	end

	-- cached descendant lists (BasePart / Decal / Texture) per model, refreshed every `maxAge`
	-- seconds: third person and viewmodel hiding walked GetDescendants() + 3 IsA per part per frame
	Game.partCache = setmetatable({}, { __mode = "k" })
	function Game.modelParts(m: Instance, maxAge: number?): { Instance }
		local c = Game.partCache[m]
		local now = os.clock()
		if c and now - c.at < (maxAge or 0.5) then
			return c.list
		end
		if not c then
			c = { at = 0, list = {} }
			Game.partCache[m] = c
		end
		local list = c.list
		table.clear(list)
		for _, d in ipairs(m:GetDescendants()) do
			if d:IsA("BasePart") or d:IsA("Decal") or d:IsA("Texture") then
				table.insert(list, d)
			end
		end
		c.at = now
		return list
	end

	-----------------------------------------------------------------------------
	-- §4b bounds (v5) — the game's own out-of-bounds model, read from its tags.
	-- OutOfBoundsMachine (decompiled): every 0.1 s the CLIENT tests RootPart.Position against parts
	-- tagged OutOfBoundsPart (minus OutOfBoundsSafePart), waits WarnDelay + KillDelay (attributes,
	-- defaults 1 + 4 s, -1 = never), then fires Remotes.Replication.Fighter.OutOfBounds itself.
	-- Volumes are finite boxes: beside or below them nothing kills until FallenPartsDestroyHeight.
	-- Every relocation asks Bounds before it rests anywhere; the HUD shows the budget countdown.
	-----------------------------------------------------------------------------
	-- block-scoped: CenterraInit sits at the 200-register cap, so the table lives on S.bounds / Game.bounds
	do
	local Bounds: any = { parts = {}, safe = {}, at = 0, n = 0, WARN_DEFAULT = 1, KILL_DEFAULT = 4 }
	S.bounds = Bounds
	Game.bounds = Bounds
	function Bounds.refresh(force: boolean?)
		local now = os.clock()
		if not force and now - Bounds.at < 2 then
			return
		end
		Bounds.at = now
		local CS = game:GetService("CollectionService")
		table.clear(Bounds.parts)
		table.clear(Bounds.safe)
		local ok, list = pcall(CS.GetTagged, CS, "OutOfBoundsPart")
		if ok and type(list) == "table" then
			for _, p in ipairs(list) do
				if p:IsA("BasePart") and p:IsDescendantOf(workspace) then
					table.insert(Bounds.parts, p)
				end
			end
		end
		local okS, safe = pcall(CS.GetTagged, CS, "OutOfBoundsSafePart")
		if okS and type(safe) == "table" then
			for _, p in ipairs(safe) do
				if p:IsA("BasePart") and p:IsDescendantOf(workspace) then
					table.insert(Bounds.safe, p)
				end
			end
		end
		-- v5.2: tags renamed by an update → one name scan per place (parts called OutOfBounds*), so the
		-- planner still refuses lethal spots. Once, budgeted; the lobby legitimately has none.
		if #Bounds.parts == 0 and not Bounds.nameScanned then
			Bounds.nameScanned = true
			pcall(function()
				local budget = 0
				for _, d in ipairs(workspace:GetDescendants()) do
					budget += 1
					if budget > 30000 then
						break
					end
					if d:IsA("BasePart") then
						local nm = d.Name
						if nm:find("OutOfBounds", 1, true) or nm:find("OutofBounds", 1, true) then
							if nm:find("Safe", 1, true) then
								table.insert(Bounds.safe, d)
							else
								table.insert(Bounds.parts, d)
							end
						end
					end
				end
				if #Bounds.parts > 0 then
					Bounds.byName = true
					log("WARN", ("adapt: OutOfBoundsPart tag empty — %d volume(s) found by part name instead"):format(#Bounds.parts))
				end
			end)
		end
		Bounds.n = #Bounds.parts
	end
	-- point-in-box in the part's own space (what Utility:IsWithinTaggedParts does for the game)
	function Bounds.inside(part: BasePart, pos: Vector3): boolean
		local rel = part.CFrame:PointToObjectSpace(pos)
		local h = part.Size * 0.5
		return math.abs(rel.X) <= h.X and math.abs(rel.Y) <= h.Y and math.abs(rel.Z) <= h.Z
	end
	-- seconds a fighter may stand in `part` before the client reports it (math.huge = warning only)
	function Bounds.budget(part: BasePart): number
		local w = part:GetAttribute("WarnDelay")
		local k = part:GetAttribute("KillDelay")
		w = if type(w) == "number" then w else Bounds.WARN_DEFAULT
		k = if type(k) == "number" then k else Bounds.KILL_DEFAULT
		if w == -1 or k == -1 then
			return math.huge
		end
		return w + k
	end
	-- the deadliest volume covering `pos`: { part, budget, lethal } or nil (free / safe part)
	function Bounds.check(pos: Vector3): any
		Bounds.refresh(false)
		if Bounds.n == 0 then
			return nil
		end
		for _, s in ipairs(Bounds.safe) do
			if s.Parent and Bounds.inside(s, pos) then
				return nil
			end
		end
		local best, bestBudget = nil, math.huge
		for _, p in ipairs(Bounds.parts) do
			if p.Parent and Bounds.inside(p, pos) then
				local b = Bounds.budget(p)
				if best == nil or b < bestBudget then
					best, bestBudget = p, b
				end
			end
		end
		if best then
			return { part = best, budget = bestBudget, lethal = bestBudget < math.huge }
		end
		return nil
	end
	-- may a relocation rest at `pos`? A lethal volume is never a resting place, OOB guard or not: the
	-- server runs the same volumes on its own (InstantKillOOB killed the probe at 0.6 s with every client
	-- report suppressed). Holds are continuous (magic re-pivots every frame for seconds), so a "fits the
	-- warn+kill budget" window only postponed the death it was meant to avoid. Only an instantaneous hop
	-- (holdSec ≤ 0.25 s, e.g. a backstab lunge) may borrow the budget.
	function Bounds.allows(pos: Vector3, holdSec: number?): (boolean, any)
		local st = S.cfg
		local c = Bounds.check(pos)
		if not c or not c.lethal then
			return true, c
		end
		if not st.boundsGuard then
			return true, c
		end
		if (holdSec or 1) <= 0.25 then
			return (holdSec or 0) + (st.oobMargin or 0.6) < c.budget, c
		end
		return false, c
	end
	-- lowest whitelisted map part = the map floor; enemies below it are void hiders
	Bounds.floorAt, Bounds.floorY = 0, nil
	function Bounds.mapFloorY(): number?
		local now = os.clock()
		if now - Bounds.floorAt < 5 and Bounds.floorY ~= nil then
			return Bounds.floorY
		end
		Bounds.floorAt = now
		local params = Game.losParams()
		local list = params and params.FilterDescendantsInstances
		local minY: number? = nil
		local budget = 0
		if type(list) == "table" then
			for _, inst in ipairs(list) do
				if typeof(inst) == "Instance" and not Bounds.isEnemyInstance(inst) then
					local parts = if inst:IsA("BasePart") then { inst } else Game.modelParts(inst, 5)
					for _, d in ipairs(parts) do
						budget += 1
						if budget > 4000 then
							break
						end
						if d:IsA("BasePart") and d.CanCollide then
							local y = d.Position.Y - d.Size.Y * 0.5
							if minY == nil or y < minY then
								minY = y
							end
						end
					end
				end
			end
		end
		Bounds.floorY = minY
		return minY
	end
	function Bounds.isEnemyInstance(inst: Instance): boolean
		-- v5.2: ancestor walk against the per-frame model set (was a full enemy scan per call)
		Game.enemies()
		local set = Game.enemyModelSet
		local cur: Instance? = inst
		local depth = 0
		while cur and depth < 8 do
			if set[cur] then
				return true
			end
			cur = cur.Parent
			depth += 1
		end
		return false
	end
	-- v5.0.3 void detection, map-agnostic: "under the map" = whitelisted geometry ABOVE the point and no
	-- ground UNDER it within 60 st. mapFloorY (the lowest whitelisted part) was a decorative part 5000 st
	-- down on some maps (the range: −1234), so nobody was ever "below the floor" — void hiders went
	-- untagged, unlocked and unplanned. Two rays per ask, cached per model for 0.25 s.
	Bounds.voidCache = setmetatable({}, { __mode = "k" })
	function Bounds.underMap(pos: Vector3, model: Model?): boolean
		local params = Game.losParams()
		if not params then
			return false
		end
		local down = workspace:Raycast(pos, Vector3.new(0, -60, 0), params)
		if down and not (model and down.Instance:IsDescendantOf(model)) and not Bounds.isEnemyInstance(down.Instance) then
			return false -- ground under them: a tunnel, a basement, the map
		end
		-- a void hider can be thousands of studs down (the map floor sits at Y ≈ 4000 on the duel maps,
		-- FallenPartsDestroyHeight at −1000): the ray up must reach the map from anywhere above that
		local up = workspace:Raycast(pos + Vector3.new(0, 2.5, 0), Vector3.new(0, 6000, 0), params)
		return up ~= nil and not (model and up.Instance:IsDescendantOf(model)) and not Bounds.isEnemyInstance(up.Instance)
	end
	function Bounds.isVoidFighter(f: any): boolean
		local root, model = Game.fighterBody(f)
		if not (root and model) then
			return false
		end
		local now = os.clock()
		local c = Bounds.voidCache[model]
		if c and now - c.t < 0.25 then
			return c.v
		end
		local v = Bounds.underMap(root.Position, model)
		Bounds.voidCache[model] = { v = v, t = now }
		return v
	end
	-- is `pos` inside solid map geometry? (a body-sized box against the shot whitelist, enemies excluded)
	Bounds.geoParams = OverlapParams.new()
	Bounds.geoParams.FilterType = Enum.RaycastFilterType.Include
	Bounds.geoParams.RespectCanCollide = false
	function Bounds.inGeometry(pos: Vector3, radius: number?): boolean
		local params = Game.losParams()
		if not params then
			return false
		end
		Bounds.geoParams.FilterDescendantsInstances = params.FilterDescendantsInstances
		local r = radius or 1
		local ok, parts = pcall(workspace.GetPartBoundsInBox, workspace, CFrame.new(pos), Vector3.new(r * 2, r * 2.4, r * 2), Bounds.geoParams)
		if not ok or type(parts) ~= "table" then
			return false
		end
		for _, p in ipairs(parts) do
			if not Bounds.isEnemyInstance(p) then
				return true
			end
		end
		return false
	end
	-- the part that hides `part` from `from` (the first whitelisted map part on the ray), nil = clear
	-- an enemy below us with their head or body inside solid map geometry: the "under" desync
	-- (teleport ~6 st under the target, fire, snap back). A legit player in a basement is not inside anything.
	Bounds.underCache = setmetatable({}, { __mode = "k" })
	function Bounds.underDesync(model: Model?): boolean
		if not model or S.cfg.antiUnder == false then
			return false
		end
		local now = os.clock()
		local c = Bounds.underCache[model]
		if c and now - c.t < 0.15 then
			return c.v
		end
		local v = false
		local me = Game.myRoot()
		local root = model:FindFirstChild("HumanoidRootPart")
		if me and root and root:IsA("BasePart") then
			local d = me.Position - root.Position
			if d.Y >= 1.5 and d.Y <= 40 and Vector3.new(d.X, 0, d.Z).Magnitude <= 32 then
				local head = model:FindFirstChild("Head")
				local hp = if head and head:IsA("BasePart") then head.Position else root.Position
				v = Bounds.inGeometry(hp, 0.5) or Bounds.inGeometry(root.Position, 0.7)
			end
		end
		if c then
			c.v, c.t = v, now
		else
			Bounds.underCache[model] = { v = v, t = now }
		end
		if v then
			Bounds.underSeenAt = now
		end
		return v
	end
	-- the under desync parks them inside the floor under whoever they target — us or anyone else. Every
	-- ray from above stops on the slab's top face, so the planners stand on that face and the lock starts
	-- the round inside it. Returns the face's Y over their head; nil when they are not inside anything or
	-- the face is too far up to push into (a thick wall, deep terrain).
	Bounds.buryCache = setmetatable({}, { __mode = "k" })
	function Bounds.buriedTop(model: Model?): number?
		if not model or S.cfg.antiUnder == false then
			return nil
		end
		local now = os.clock()
		local c = Bounds.buryCache[model]
		if c and now - c.t < 0.15 then
			return c.y
		end
		local y: number? = nil
		local root = model:FindFirstChild("HumanoidRootPart")
		local params = Game.losParams()
		if params and root and root:IsA("BasePart") then
			local head = model:FindFirstChild("Head")
			local hp = if head and head:IsA("BasePart") then head.Position else root.Position
			if Bounds.inGeometry(hp, 0.5) or Bounds.inGeometry(root.Position, 0.7) then
				-- walk down from above: a ray that starts inside a ceiling ignores it, so the last face over
				-- their head is the slab they sit in
				local char = LP.Character
				local from = hp + Vector3.new(0, 14, 0)
				for _ = 1, 4 do
					local hit = workspace:Raycast(from, Vector3.new(0, hp.Y - from.Y, 0), params)
					if not hit then
						break
					end
					local inst = hit.Instance
					if not (Bounds.isEnemyInstance(inst) or inst:IsDescendantOf(model) or (char and inst:IsDescendantOf(char))) then
						y = hit.Position.Y
					end
					from = hit.Position - Vector3.new(0, 0.05, 0)
				end
				if y and y - hp.Y > 7 then
					y = nil
				end
			end
		end
		if c then
			c.y, c.t = y, now
		else
			Bounds.buryCache[model] = { y = y, t = now }
		end
		return y
	end
	function Bounds.blocker(from: Vector3, model: Model?, part: BasePart): BasePart?
		local params = Game.losParams()
		if not params then
			return nil
		end
		local hit = workspace:Raycast(from, part.Position - from, params)
		if hit and not (model and (hit.Instance == model or hit.Instance:IsDescendantOf(model))) then
			return hit.Instance
		end
		if hit and hit.Instance ~= part and S.cfg.shieldAware and Game.isShieldPart(hit.Instance, model) then
			return hit.Instance -- their Riot Shield absorbs the ray: it is cover
		end
		return nil
	end
	-- the server's own view: a ray from `from` to `part` through the shot whitelist
	function Bounds.serverLos(from: Vector3, model: Model?, part: BasePart?): boolean
		return Game.rayVisible(model, part, from)
	end
	-- where we stand right now: { part, budget, lethal, since } or nil, refreshed by the loop at 10 Hz
	Bounds.here = nil
	Bounds.hereAt = 0
	function Bounds.tick()
		local now = os.clock()
		if now - Bounds.hereAt < 0.1 then
			return
		end
		Bounds.hereAt = now
		local root = S.myRootPart
		if not (root and root.Parent) then
			Bounds.here = nil
			return
		end
		local c = Bounds.check(root.Position)
		if c then
			local prev = Bounds.here
			c.since = if prev and prev.part == c.part then prev.since else now
			Bounds.here = c
		else
			Bounds.here = nil
		end
	end
	-- seconds left before the client would report us (nil = not in a volume / never)
	function Bounds.secondsLeft(): number?
		local c = Bounds.here
		if not c or not c.lethal then
			return nil
		end
		return math.max(0, c.budget - (os.clock() - (c.since or os.clock())))
	end
	S.boundsCheck = Bounds.check
	end -- Bounds block

	-----------------------------------------------------------------------------
	-- §4b safe — may the body rest at this spot? Body asks before every relocation:
	--   · inside the map's box (built once per map from the shot geometry, outliers trimmed)
	--   · inside the height band above the ground under the spot — or under the target, when the
	--     caller passes it — so two cheaters can never stack each other up into a sky kill zone
	--   · never inside a lethal out-of-bounds volume for a hold, OOB guard or not (the guard only
	--     silences the client's own report); an instant hop may borrow the volume's budget
	--   · something to stand on, unless the owner explicitly rests inside geometry or under the map
	-----------------------------------------------------------------------------
	do
	local Safe: any = { box = nil, boxAt = 0, boxKey = nil, gFrame = -1, gCache = {}, refusals = {}, EMPTY = {} }
	S.safe = Safe
	Game.safe = Safe
	Safe.downParams = RaycastParams.new()
	Safe.downParams.FilterType = Enum.RaycastFilterType.Include
	Safe.downParams.IgnoreWater = true
	-- ground Y under a point (the first map part within 250 st below), cached per frame on a 2 st grid
	function Safe.groundY(pos: Vector3): number?
		if Safe.gFrame ~= Game.frameId then
			Safe.gFrame = Game.frameId
			table.clear(Safe.gCache)
		end
		local key = math.floor(pos.X * 0.5) * 73856093 + math.floor(pos.Z * 0.5) * 19349663 + math.floor(pos.Y * 0.25)
		local c = Safe.gCache[key]
		if c ~= nil then
			return if c == false then nil else c
		end
		local params = Game.losParams()
		local list = params and params.FilterDescendantsInstances
		if type(list) ~= "table" then
			return nil
		end
		Safe.downParams.FilterDescendantsInstances = list
		local y: number? = nil
		local from = pos + Vector3.new(0, 1, 0)
		for _ = 1, 3 do
			local hit = workspace:Raycast(from, Vector3.new(0, -251, 0), Safe.downParams)
			if not hit then
				break
			end
			if not S.bounds.isEnemyInstance(hit.Instance) then
				y = hit.Position.Y
				break
			end
			from = hit.Position - Vector3.new(0, 0.05, 0)
		end
		Safe.gCache[key] = if y then y else false
		return y
	end
	-- the playable box: 2nd–98th percentile of every collidable map part's extent, padded
	function Safe.mapBox(): any
		local params = Game.losParams()
		local list = params and params.FilterDescendantsInstances
		if type(list) ~= "table" then
			return Safe.box
		end
		local now = os.clock()
		local key = tostring(game.PlaceId) .. ":" .. #list
		if Safe.box and Safe.boxKey == key and now - Safe.boxAt < 30 then
			return Safe.box
		end
		Safe.boxKey, Safe.boxAt = key, now
		local x0, x1, y0, y1, z0, z1 = {}, {}, {}, {}, {}, {}
		local budget = 0
		for _, inst in ipairs(list) do
			if budget > 8000 then
				break
			end
			if typeof(inst) == "Instance" and not S.bounds.isEnemyInstance(inst) then
				local parts = if inst:IsA("BasePart") then { inst } else Game.modelParts(inst, 30)
				for _, p in ipairs(parts) do
					budget += 1
					if budget > 8000 then
						break
					end
					if p:IsA("BasePart") and p.CanCollide then
						local sz = p.Size
						if sz.X < 4000 and sz.Y < 4000 and sz.Z < 4000 then
							local c, h = p.Position, sz * 0.5
							table.insert(x0, c.X - h.X)
							table.insert(x1, c.X + h.X)
							table.insert(y0, c.Y - h.Y)
							table.insert(y1, c.Y + h.Y)
							table.insert(z0, c.Z - h.Z)
							table.insert(z1, c.Z + h.Z)
						end
					end
				end
			end
		end
		if #x0 < 8 then
			-- no map here (the hub around a range, a waiting room): no box, rather than the last arena's box
			-- under the new key — standing in the hub read as "N st outside the map" against it
			Safe.box = nil
			return nil
		end
		local function pct(t: { number }, q: number): number
			table.sort(t)
			return t[math.clamp(math.floor(#t * q + 0.5), 1, #t)]
		end
		local top = pct(y1, 0.98)
		Safe.box = {
			min = Vector3.new(pct(x0, 0.02) - 40, pct(y0, 0.02) - 20, pct(z0, 0.02) - 40),
			max = Vector3.new(pct(x1, 0.98) + 40, top + 40, pct(z1, 0.98) + 40),
			parts = #x0,
		}
		log("DEBUG", ("safe: map box %s … %s from %d parts"):format(tostring(Safe.box.min), tostring(Safe.box.max), #x0))
		return Safe.box
	end
	-- enemy Subspace Tripmines (decompiled SubspaceTripmines: CollectionService tag "SubspaceTripmine",
	-- a Hitbox child, PlacedByUserID / TeamID attributes; ItemLibrary: ExplosionRadius 12, 149 damage).
	-- Enemy mines are invisible to us but still exist locally. Rescanned every 0.25 s.
	Safe.MINE_RADIUS = 15
	Safe.mineList, Safe.mineAt = {}, 0
	function Safe.mines(): { Vector3 }
		local now = os.clock()
		if now - Safe.mineAt < 0.25 then
			return Safe.mineList
		end
		Safe.mineAt = now
		local out = Safe.mineList
		table.clear(out)
		local okT, tagged = pcall(function()
			return game:GetService("CollectionService"):GetTagged("SubspaceTripmine")
		end)
		if not okT or type(tagged) ~= "table" or #tagged == 0 then
			return out
		end
		local lf = Game.localFighter()
		local myTeam = if lf then Game.fighterTeam(lf) else nil
		for _, m in ipairs(tagged) do
			if typeof(m) == "Instance" and m.Parent ~= nil then
				local by = m:GetAttribute("PlacedByUserID")
				local team = m:GetAttribute("TeamID")
				local friendly = by == LP.UserId or (myTeam ~= nil and type(team) == "string" and team ~= "" and team == myTeam)
				if not friendly then
					local hb = m:FindFirstChild("Hitbox")
					local p = if hb and hb:IsA("BasePart") then hb.Position elseif m:IsA("Model") then m:GetPivot().Position elseif m:IsA("BasePart") then m.Position else nil
					if p then
						table.insert(out, p)
					end
				end
			end
		end
		return out
	end
	function Safe.nearMine(pos: Vector3): boolean
		for _, p in ipairs(Safe.mines()) do
			if (p - pos).Magnitude < Safe.MINE_RADIUS then
				return true
			end
		end
		return false
	end
	-- o: hold (s the body rests there), geometry (may be inside map parts), void (may be under the
	-- map), sky (a calibrated void height: no band, no box top), far (the last-resort hide outside
	-- every map part: no box, no band, nothing below — kill volumes, the kill height, the 1e5 cap and
	-- solid parts still refuse), refGround (Y the band is measured from when it is higher than the
	-- ground under the spot — the target's ground)
	function Safe.check(pos: Vector3, o: any?): (boolean, string?)
		o = o or Safe.EMPTY
		if typeof(pos) ~= "Vector3" or pos ~= pos or math.abs(pos.X) > 1e5 or math.abs(pos.Y) > 1e5 or math.abs(pos.Z) > 1e5 then
			return false, "not a position"
		end
		if pos.Y < workspace.FallenPartsDestroyHeight + 40 then
			return false, "below the kill height"
		end
		local c = S.bounds.check(pos)
		if c and c.lethal then
			local hold = o.hold or 0.4
			local margin = S.cfg.oobMargin or 0.6
			local fits = hold <= 0.25 and hold + margin < c.budget
			if not fits and o.budget then
				-- the caller watches Bounds.secondsLeft and leaves in time (defense): what is left of
				-- the clock we are already on counts, not the volume's full budget
				local left = S.bounds.secondsLeft()
				fits = (left or c.budget) > margin + hold + 0.5
			end
			if not fits then
				return false, "kill volume " .. c.part.Name
			end
		end
		local box = Safe.mapBox()
		if box and not o.sky and not o.far then
			-- near: a live enemy stands there, so it is inside the playable map whatever the part box says
			-- (the range rail dummies stand 13 studs past it)
			local nearOk = o.near ~= nil and ((pos - o.near) * Vector3.new(1, 0, 1)).Magnitude <= 12
			if not nearOk and (pos.X < box.min.X or pos.X > box.max.X or pos.Z < box.min.Z or pos.Z > box.max.Z) then
				return false, "outside the map"
			end
			if pos.Y > box.max.Y then
				return false, "above the map"
			end
		end
		local ground = Safe.groundY(pos)
		local base = math.max(ground or -math.huge, o.refGround or -math.huge)
		if base > -math.huge then
			if not o.sky and not o.far and pos.Y - base > S.cfg.safeMaxHeight then
				return false, "too high"
			end
		end
		if not ground then
			if S.bounds.underMap(pos, nil) then
				if not o.void then
					return false, "under the map"
				end
			elseif not o.sky and not o.refGround and not o.far then
				return false, "nothing below"
			end
		end
		if not o.geometry and S.bounds.inGeometry(pos, 0.9) then
			return false, "inside a wall"
		end
		if Safe.nearMine(pos) then
			return false, "tripmine"
		end
		return true, nil
	end
	-- the nearest spot that passes: into the band first (the usual refusal), then into the box
	function Safe.fix(pos: Vector3, o: any?): Vector3?
		o = o or Safe.EMPTY
		if typeof(pos) ~= "Vector3" or pos ~= pos then
			return nil
		end
		if o.far then
			return nil -- the far spot is taken as it is or not at all (Combat.farSpot searches its own)
		end
		local ground = Safe.groundY(pos)
		local base = math.max(ground or -math.huge, o.refGround or -math.huge)
		if base > -math.huge and not o.sky and pos.Y - base > S.cfg.safeMaxHeight then
			local p = Vector3.new(pos.X, base + S.cfg.safeMaxHeight - 1, pos.Z)
			if Safe.check(p, o) then
				return p
			end
		end
		local box = Safe.mapBox()
		if box and not o.sky then
			local p = Vector3.new(math.clamp(pos.X, box.min.X + 4, math.max(box.min.X + 4, box.max.X - 4)), math.min(pos.Y, box.max.Y - 4), math.clamp(pos.Z, box.min.Z + 4, math.max(box.min.Z + 4, box.max.Z - 4)))
			if (p - pos).Magnitude > 0.5 and Safe.check(p, o) then
				return p
			end
		end
		return nil
	end
	-- can the player be left standing here (a hold that ends without a return, a lunge)?
	function Safe.standable(pos: Vector3): boolean
		local ground = Safe.groundY(pos)
		if not ground or pos.Y - ground > 7 then
			return false
		end
		local c = S.bounds.check(pos)
		if c and c.lethal then
			return false
		end
		return not S.bounds.inGeometry(pos, 0.9) and not Safe.nearMine(pos)
	end
	-- a refusal worth remembering (Debug, centerra_state): why and how often, per reason — and one log
	-- line per reason per second (grep [oob:refuse:)
	Safe.noteAt = {}
	function Safe.note(why: string?)
		if why then
			Safe.refusals[why] = (Safe.refusals[why] or 0) + 1
			Safe.lastRefusal, Safe.lastRefusalAt = why, os.clock()
			local now = os.clock()
			if now - (Safe.noteAt[why] or 0) >= 1 then
				Safe.noteAt[why] = now
				local owner, reason = string.match(why, "^([%w]+): (.+)$")
				log("DEBUG", ("[oob:refuse:%s] %s · owner %s · body %s · refused %d×"):format(string.gsub(reason or why, "[%s()]+", "-"), why, owner or "?", (S.body and S.body.owner) or "you", Safe.refusals[why]))
			end
		end
	end
	end -- Safe block

	-----------------------------------------------------------------------------
	-- §5 input — key state (KeyCode / mouse / M4-M5 via the daemon), capture, bind engine
	-----------------------------------------------------------------------------
	local Input: any = {}
	S.input = Input
	local keyDown: { [string]: boolean } = {}
	local keyPrev: { [string]: boolean } = {}
	Input.lastInputName = "—"
	Input.keyDown = keyDown
	Input.bindLabels = {} -- cfgKey -> human label (filled by the menu)

	local KEY_PRETTY = {
		M4 = "M4", M5 = "M5", MouseButton1 = "LMB", MouseButton2 = "RMB", MouseButton3 = "MMB",
		LeftShift = "SHIFT", RightShift = "RSHIFT", LeftControl = "CTRL", RightControl = "RCTRL", LeftAlt = "ALT", RightAlt = "RALT",
		F13 = "M4", F14 = "M5", Return = "ENTER", CapsLock = "CAPS",
	}
	local VK = { Space = 0x20, LeftShift = 0x10, LeftControl = 0x11, LeftAlt = 0x12, Tab = 0x09, CapsLock = 0x14, Q = 0x51, E = 0x45, R = 0x52, F = 0x46, C = 0x43, V = 0x56, X = 0x58, Z = 0x5A, G = 0x47, B = 0x42 }

	function Input.sideInput(): any
		return genv().VoltMCP_Input
	end

	-- key name → resolved enum, once per name (safeEnum is a pcall around a closure; runBinds asked
	-- it for every bind every frame). false = resolved to nothing.
	Input.enumCache = {}
	function Input.resolve(name: string): any
		local c = Input.enumCache[name]
		if c ~= nil then
			return c
		end
		local v: any = false
		if name:sub(1, 11) == "MouseButton" then
			local ut = safeEnum(Enum.UserInputType, name)
			if ut then
				v = { mouse = ut }
			end
		else
			local kc = safeEnum(Enum.KeyCode, name)
			if kc and kc ~= Enum.KeyCode.Unknown then
				v = { key = kc }
			end
		end
		Input.enumCache[name] = v
		return v
	end
	function Input.isKeyDown(name: any): boolean
		if type(name) ~= "string" or name == "" then
			return false
		end
		if name == "M4" or name == "M5" then
			local inp = Input.sideInput()
			return type(inp) == "table" and inp[if name == "M4" then "m4" else "m5"] == true
		end
		local r = Input.resolve(name)
		if r then
			if r.mouse then
				return UIS:IsMouseButtonPressed(r.mouse) or keyDown[name] == true
			end
			return UIS:IsKeyDown(r.key)
		end
		return keyDown[name] == true
	end

	function Input.keyLabel(name: any): string
		if type(name) ~= "string" or name == "" then
			return "—"
		end
		return KEY_PRETTY[name] or name
	end

	function Input.inputName(input: InputObject): string?
		if input.KeyCode ~= Enum.KeyCode.Unknown then
			return input.KeyCode.Name
		end
		local ut = input.UserInputType
		if ut == Enum.UserInputType.MouseButton1 or ut == Enum.UserInputType.MouseButton2 or ut == Enum.UserInputType.MouseButton3 then
			return ut.Name
		end
		return nil
	end

	function Input.vk(name: any): number?
		if type(name) ~= "string" or name == "" then
			return nil
		end
		if VK[name] then
			return VK[name]
		end
		if #name == 1 then
			return string.byte(string.upper(name)) -- letters and digits alike (0x30–0x39, 0x41–0x5A)
		end
		return nil
	end

	-- tap a key through the executor (used by auto-slide); silently no-ops without keypress
	function Input.tap(name: string)
		local vk = Input.vk(name)
		if vk and EXEC.keypress and EXEC.keyrelease then
			pcall(EXEC.keypress, vk)
			task.delay(0.03, function()
				pcall(EXEC.keyrelease, vk)
			end)
		end
	end

	-- fire trigger. VirtualInputManager rides the same UserInputService path the game listens on and
	-- works whether or not the executor's mouse1press does; the executor call is the fallback.
	-- Combat escalates to Gun:StartShooting when neither produces a shot.
	local VIM: any = nil
	pcall(function()
		VIM = game:GetService("VirtualInputManager")
	end)
	local fireHeld = false
	Input.fireMethodUsed = "—"
	local function vimMouse(down: boolean, btn: number?): boolean
		if not VIM then
			return false
		end
		return (pcall(function()
			local m = UIS:GetMouseLocation()
			VIM:SendMouseButtonEvent(m.X, m.Y, btn or 0, down, game, 0)
		end))
	end
	local function execMouse(down: boolean, btn: number?): boolean
		local fn
		if btn == 1 then
			fn = if down then EXEC.mouse2press else EXEC.mouse2release
		else
			fn = if down then EXEC.mouse1press else EXEC.mouse1release
		end
		if type(fn) ~= "function" then
			return false
		end
		return (pcall(fn))
	end
	-- right mouse (katana block, etc.): VIM first, executor fallback
	local rmbHeld = false
	function Input.setRightMouse(down: boolean)
		if down == rmbHeld then
			return
		end
		rmbHeld = down
		if not vimMouse(down, 1) then
			execMouse(down, 1)
		end
	end

	-- game-level inputs: the same call RIVALS' own mobile buttons and its built-in auto-shoot use —
	-- MechanicsController:EquippedItemInput("StartShooting" | "FinishShooting" | "StartAiming" |
	-- "FinishAiming" | "StartReloading"). No mouse, no keyboard: the item receives the input directly.
	local MC: any = nil
	function Input.mechanics(): any
		if MC then
			return MC
		end
		local ps = LP:FindFirstChild("PlayerScripts")
		local ctrl = ps and ps:FindFirstChild("Controllers")
		MC = Game.requireIfLoaded(ctrl and ctrl:FindFirstChild("MechanicsController"))
		return MC
	end
	Input.gameInputOk = 0
	Input.gameInputFail = 0
	function Input.gameInput(name: string): boolean
		local mc = Input.mechanics()
		if type(mc) ~= "table" or type(mc.EquippedItemInput) ~= "function" then
			return false
		end
		if name == "StartShooting" then
			-- the shot code will run in our thread → tell the layers this is a shot (see callerIsShotCode)
			S.ourShotUntil = os.clock() + 0.15
			S.spoofUntil = math.max(S.spoofUntil or 0, os.clock() + 0.6)
			S.firing = true
		end
		local ok, err = Game.asShotCode(mc.EquippedItemInput, mc, name)
		if ok then
			Input.gameInputOk += 1
		else
			Input.gameInputFail += 1
			S.hookErr("game input " .. name, err)
		end
		return ok
	end
	-- a whole game input by name through MechanicsController.SimulateInputBegan/Ended — the mobile
	-- button path, so a plain string ("QuickMelee", "Slide", "Jump", …) is accepted
	function Input.simulate(name: string, holdSec: number?): boolean
		local mc = Input.mechanics()
		if type(mc) ~= "table" or type(mc.SimulateInputBegan) ~= "function" then
			return false
		end
		local ok, err = Game.asShotCode(mc.SimulateInputBegan, mc, name, false)
		if not ok then
			S.hookErr("simulate " .. name, err)
			return false
		end
		task.delay(holdSec or 0.06, function()
			if S.alive and type(mc.SimulateInputEnded) == "function" then
				Game.asShotCode(mc.SimulateInputEnded, mc, name)
			end
		end)
		return true
	end
	-- ADS through the item (StartAiming / FinishAiming), VIM right-click as the fallback
	local adsHeld = false
	Input.adsViaMouse = false -- the press went through the virtual RMB: release through the same path
	function Input.setAds(on: boolean, force: boolean?)
		if on == adsHeld and not force then
			return
		end
		adsHeld = on
		if on then
			if Input.gameInput("StartAiming") then
				Input.adsViaMouse = false
			else
				Input.adsViaMouse = true
				Input.setRightMouse(true)
			end
		else
			local viaMouse = Input.adsViaMouse
			Input.adsViaMouse = false
			if viaMouse then
				Input.setRightMouse(false)
			elseif not Input.gameInput("FinishAiming") then
				Input.setRightMouse(false)
			end
		end
	end
	function Input.adsHeld(): boolean
		return adsHeld
	end
	-- method: "vim" | "executor" | "direct" (direct presses nothing — Combat calls StartShooting)
	local fireMethodHeld = "game"
	function Input.setFire(down: boolean, method: string?)
		if down then
			S.spoofUntil = os.clock() + 0.6 -- rotation/camera spoof outlives the pull (see silentWanted)
		end
		if down == fireHeld and (not down or method == nil or method == fireMethodHeld) then
			return
		end
		if fireHeld and down then
			-- switching method while held: release through the old one first
			Input.setFire(false)
		end
		fireHeld = down
		local m = if down then (method or "game") else fireMethodHeld
		if down then
			fireMethodHeld = m
		end
		local ok = false
		if m == "game" then
			ok = Input.gameInput(if down then "StartShooting" else "FinishShooting")
			if not ok and down then
				ok = vimMouse(down)
				if ok then
					fireMethodHeld = "vim"
					m = "vim"
				end
			end
		elseif m == "executor" then
			ok = execMouse(down)
		elseif m == "vim" then
			ok = vimMouse(down)
			if not ok and down then
				ok = execMouse(down)
				if ok then
					fireMethodHeld = "executor"
					m = "executor"
				end
			end
		else
			ok = true
		end
		if down then
			Input.fireMethodUsed = if ok then m else m .. " (failed)"
		end
	end
	function Input.fireHeld(): boolean
		return fireHeld
	end

	-- capture the next key / mouse button / side button; nil = cleared (Esc/Backspace), false = timeout
	local capturing = false
	function Input.captureKey(done: (any) -> ())
		if capturing then
			return
		end
		capturing = true
		local conn: RBXScriptConnection? = nil
		local hb: RBXScriptConnection? = nil
		local started = os.clock()
		local function finish(name: any)
			if not capturing then
				return
			end
			capturing = false
			Input.cancelCapture = nil
			if conn then
				conn:Disconnect()
			end
			if hb then
				hb:Disconnect()
			end
			done(name)
		end
		-- v5.2: an unload while a bind popup waits for a key must drop these two listeners too
		Input.cancelCapture = function()
			finish(false)
		end
		conn = UIS.InputBegan:Connect(function(input)
			if input.KeyCode == Enum.KeyCode.Escape or input.KeyCode == Enum.KeyCode.Backspace then
				finish(nil)
				return
			end
			if os.clock() - started < 0.2 and input.UserInputType == Enum.UserInputType.MouseButton1 then
				return -- the click that opened the capture
			end
			local nm = Input.inputName(input)
			if nm then
				finish(nm)
			end
		end)
		-- side buttons bind on the press EDGE: one already held when the capture opened is ignored
		local m4Was, m5Was = nil, nil
		hb = RunService.Heartbeat:Connect(function()
			local inp = Input.sideInput()
			local m4 = inp ~= nil and inp.m4 == true
			local m5 = inp ~= nil and inp.m5 == true
			if m4Was == nil then
				m4Was, m5Was = m4, m5
				return
			end
			if m4 and not m4Was then
				finish("M4")
			elseif m5 and not m5Was then
				finish("M5")
			elseif os.clock() - started > 8 then
				finish(false)
			end
			m4Was, m5Was = m4, m5
		end)
	end
	function Input.capturing(): boolean
		return capturing
	end

	-- bind engine: cfg.binds[cfgKey] = { key, mode }. Modes: Toggle | Hold | Always | Never.
	-- Special targets (autokill, autoPeek…) go through S.bindActions[cfgKey](state).
	local bindHoldBase: { [string]: any } = {}
	local bindTouched: { [string]: boolean } = {}
	Input.bindTouched = bindTouched
	Input.pressedNow = {}
	-- Hold binds: let go of everything whose key is no longer down (menu / capture swallow the release edge)
	function Input.releaseHolds()
		for cfgKey, b in pairs(cfg.binds) do
			if type(b) == "table" and b.mode == "Hold" and type(b.key) == "string" and b.key ~= "" and not Input.isKeyDown(b.key) then
				local action = S.bindActions[cfgKey]
				if action then
					if keyPrev[b.key] == true then
						action(false)
					end
				elseif bindHoldBase[cfgKey] ~= nil then
					cfg[cfgKey] = bindHoldBase[cfgKey]
					bindHoldBase[cfgKey] = nil
				end
			end
		end
	end
	function Input.bindEdge(name: string): (boolean, boolean)
		local down = Input.isKeyDown(name)
		local was = keyPrev[name] == true
		Input.pressedNow[name] = down
		return down and not was, (not down) and was
	end
	function Input.runBinds()
		local pressedNow = Input.pressedNow
		table.clear(pressedNow)
		local edge = Input.bindEdge
		-- v5.0.4: typing in the chat / a text box is not a keybind — "k" in a message toggled auto shoot
		-- off every time (K is its bind); found off three times in one session
		local typing = false
		pcall(function()
			typing = UIS:GetFocusedTextBox() ~= nil
		end)
		if S.menuOpen or capturing or typing then
			-- a Hold that was down when the menu opened must not stay engaged forever
			Input.releaseHolds()
			for _, b in pairs(cfg.binds) do
				if type(b) == "table" and type(b.key) == "string" and b.key ~= "" then
					pressedNow[b.key] = Input.isKeyDown(b.key)
				end
			end
			for k, v in pairs(pressedNow) do
				keyPrev[k] = v
			end
			return
		end
		for cfgKey, b in pairs(cfg.binds) do
			if type(b) == "table" then
				local mode = b.mode or "Toggle"
				local action = S.bindActions[cfgKey]
				if mode == "Always" then
					if action then
						if not bindTouched[cfgKey] then
							bindTouched[cfgKey] = true
							action(true)
						end
					elseif cfg[cfgKey] ~= true then
						cfg[cfgKey] = true
					end
				elseif mode == "Never" then
					if action then
						if not bindTouched[cfgKey] then
							bindTouched[cfgKey] = true
							action(false)
						end
					elseif cfg[cfgKey] ~= false then
						cfg[cfgKey] = false
					end
				elseif type(b.key) == "string" and b.key ~= "" then
					local pressed, released = edge(b.key)
					if mode == "Toggle" and pressed then
						if action then
							action(nil)
						else
							cfg[cfgKey] = not cfg[cfgKey]
							-- a combat feature going OFF by key is the classic "it doesn't shoot" — loud and yellow
							local core = cfgKey == "autoShoot" or cfgKey == "silentAim" or cfgKey == "aimbot" or cfgKey == "esp"
							if cfg[cfgKey] then
								notify(("%s ON"):format(Input.bindLabels[cfgKey] or cfgKey), 2, "ok")
							else
								notify(("%s OFF — %s turns it back on"):format(Input.bindLabels[cfgKey] or cfgKey, Input.keyLabel(b.key)), if core then 4 else 2, if core then "warn" else "info")
							end
							saveConfig()
						end
					elseif mode == "Hold" then
						if pressed then
							if action then
								action(true)
							else
								bindHoldBase[cfgKey] = cfg[cfgKey]
								cfg[cfgKey] = true
							end
						elseif released then
							if action then
								action(false)
							elseif bindHoldBase[cfgKey] ~= nil then
								cfg[cfgKey] = bindHoldBase[cfgKey]
								bindHoldBase[cfgKey] = nil
							end
						end
					end
				end
			end
		end
		for k, v in pairs(pressedNow) do
			keyPrev[k] = v
		end
	end

	function Input.aimHeld(): boolean
		return not S.menuOpen and Input.isKeyDown(cfg.aimKey)
	end
	S.isKeyDown = Input.isKeyDown
	S.runBinds = Input.runBinds
	S.keyLabel = Input.keyLabel

	-----------------------------------------------------------------------------
	-- §6 targeting + resolver
	-----------------------------------------------------------------------------
	-- Resolver: per-enemy rolling buffer of the last 8 replicated head/body positions + rotations
	-- (≤60 Hz). Flags anti-aim (yaw spinning while standing still), position desync (>8 stud jumps)
	-- and fake-lag (frozen frames then a jump). The aim point stays the LIVE part position (the
	-- server resolves the hit on its own part position — a delayed median lands short); the flags
	-- drive the ESP tags and body priority for AA users.
	local Resolver: any = { buffers = {} }
	local RES_N = 8
	S.resolver = Resolver

	local function newBuffer(): any
		return { head = {}, body = {}, rot = {}, t = {}, n = 0, i = 0, last = 0, stale = 0, aaHits = 0, desyncHits = 0, lagHits = 0, aa = false, desync = false, fakelag = false }
	end

	Resolver.seen = {}
	function Resolver.update(enemies: { any })
		local now = os.clock()
		local seen: { [any]: boolean } = Resolver.seen
		table.clear(seen)
		for _, f in ipairs(enemies) do
			local root, model = Game.fighterBody(f)
			local head = Game.fighterHead(f)
			if model and root and head then
				seen[model] = true
				local b = Resolver.buffers[model]
				if not b then
					b = newBuffer()
					Resolver.buffers[model] = b
				end
				if now - b.last >= 1 / 61 then
					local rot: Vector2? = nil
					if type(f.GetCameraRotation) == "function" then
						local ok, r = pcall(f.GetCameraRotation, f)
						if ok and typeof(r) == "Vector2" then
							rot = r
						end
					end
					local prev = b.i
					b.i = b.i % RES_N + 1
					b.n = math.min(b.n + 1, RES_N)
					local hp = head.Position
					b.head[b.i] = hp
					b.body[b.i] = root.Position
					b.rot[b.i] = rot
					b.t[b.i] = now
					b.last = now
					if b.n >= 2 and prev > 0 then
						local dp = (hp - b.head[prev]).Magnitude
						local dt = now - b.t[prev]
						if dp > 8 and dt < 0.08 then
							b.desyncHits = math.min(b.desyncHits + 2, 12)
						else
							b.desyncHits = math.max(b.desyncHits - 1, 0)
						end
						local pRot = b.rot[prev]
						if rot and pRot then
							local dy = math.abs(((rot.Y - pRot.Y + math.pi) % (2 * math.pi)) - math.pi)
							if dy > 0.8 and dp < 0.6 then
								b.aaHits = math.min(b.aaHits + 2, 12)
							else
								b.aaHits = math.max(b.aaHits - 1, 0)
							end
						end
						local vel = root.AssemblyLinearVelocity.Magnitude
						if dp < 0.01 and vel > 2 then
							b.stale += 1
						else
							if b.stale >= 3 and dp > 1 then
								b.lagHits = math.min(b.lagHits + 3, 12)
							else
								b.lagHits = math.max(b.lagHits - 1, 0)
							end
							b.stale = 0
						end
						-- sustained patterns only: a single flick or dash must never flag anyone
						b.aa = b.aaHits >= 8
						b.desync = b.desyncHits >= 8
						b.fakelag = b.lagHits >= 6
					end
				end
			end
		end
		for model in pairs(Resolver.buffers) do
			if not seen[model] then
				Resolver.buffers[model] = nil
			end
		end
	end

	function Resolver.flags(model: any): any
		return Resolver.buffers[model]
	end
	-- where the server last registered a HIT on each model ({ pos, at }, from Shots.serverResult): the
	-- aim point when the live part is out of the server ray's reach (Combat.updateLock)
	Resolver.confirmed = setmetatable({}, { __mode = "k" })

	-- Aim position for a fighter's part. In Roblox the replicated part position *is* what the server
	-- hit-tests, so the live position is always the right answer; medians only lag behind dashes and
	-- mouse flicks (they cost real hits). The resolver's flags drive tags and, on confirmed AA, the
	-- optional switch to the live torso — never a delayed position.
	function Resolver.aimPoint(fighter: any, part: BasePart): Vector3
		if cfg.resolver and cfg.resolverBodyOnAA then
			local _, model = Game.fighterBody(fighter)
			local b = model and Resolver.buffers[model]
			if b and b.aa then
				local root = Game.fighterBody(fighter)
				if root then
					return root.Position
				end
			end
		end
		return (Resolver.fixPos(part))
	end

	function Resolver.tag(model: any): string
		local b = model and Resolver.buffers[model]
		if not b then
			return ""
		end
		local t = {}
		if b.aa then
			table.insert(t, "AA")
		end
		if b.desync then
			table.insert(t, "DESYNC")
		end
		if b.fakelag then
			table.insert(t, "LAG")
		end
		return table.concat(t, " ")
	end

	-- Warp backtrack: a desync that throws the replicated root to a random point far off the map (duel log:
	-- 1e6–3e9 st, a fresh one every frame or two) leaves the server with them in two places, and only the
	-- real one can be hit. A live root that reads fake is backtracked to the last real sample and the model
	-- is put back there on our client (the next replicated frame overwrites it), so the lock, the rotation
	-- stream, the echo gate, the planners, the counters and the ESP all work from the spot they keep coming
	-- back to. A first fake frame is answered for WARP_FRESH only (a real voidspam hop goes out and stays
	-- out); after two returns within 2 s the hold is WARP_HOLD.
	Resolver.warp = setmetatable({}, { __mode = "k" })
	Resolver.WARP_PAD = 1500
	Resolver.WARP_FRESH = 0.15
	Resolver.WARP_HOLD = 0.8
	Resolver.WARP_AHEAD = 0.25 -- the real spot rides its own velocity for at most this long
	Resolver.WARP_KEEP = 6 -- past the hold, the aim / stream / planners still answer the last real spot this long (they reappear there)
	function Resolver.fakePos(p: Vector3): boolean
		local x, y, z = p.X, p.Y, p.Z
		if x ~= x or y ~= y or z ~= z or math.abs(x) > 1e5 or math.abs(y) > 1e5 or math.abs(z) > 1e5 then
			return true
		end
		local box = S.safe and S.safe.box
		if not box then
			return false
		end
		local pad, mn, mx = Resolver.WARP_PAD, box.min, box.max
		return x < mn.X - pad or x > mx.X + pad or z < mn.Z - pad or z > mx.Z + pad or y > mx.Y + pad or y < mn.Y - pad * 2
	end
	function Resolver.warpHold(w: any): number
		return if w.flicks >= 2 then Resolver.WARP_HOLD else Resolver.WARP_FRESH
	end
	-- the parts a shot or a planner asks about; their offsets from the root are taken on real frames only
	-- (float32 keeps ~256 st of precision at 3e9: nothing measured on the fake spot means anything)
	Resolver.WARP_PARTS = { "HitboxHead", "HitboxBody", "Head", "HitboxHeadSmall", "HitboxBodySmall", "UpperTorso" }
	function Resolver.warpStep(targets: { any })
		if not (cfg.resolver and cfg.resolverWarp) then
			if next(Resolver.warp) ~= nil then
				table.clear(Resolver.warp)
			end
			return
		end
		if #targets == 0 then
			return
		end
		-- the fake test needs the map box; nothing else may have built it yet this place
		pcall(S.safe.mapBox)
		local now = os.clock()
		for _, f in ipairs(targets) do
			local root, model = Game.fighterBody(f)
			if root and model and root.Parent then
				local w = Resolver.warp[model]
				if not w then
					w = { flicks = 0, flickAt = 0, realAt = 0, vel = Vector3.zero, fixes = 0, rel = setmetatable({}, { __mode = "k" }), parts = {} }
					Resolver.warp[model] = w
				end
				w.root, w.fighter = root, f
				local p = root.Position
				-- our own write from last frame still stands: nothing new arrived, nothing to learn
				if not (w.wrote and (p - w.wrote).Magnitude < 0.01) then
					w.wrote = nil
					if Resolver.fakePos(p) then
						w.fakeSince = w.fakeSince or now
					else
						if w.fakeSince and now - w.fakeSince < 0.5 then
							w.flicks = math.min(w.flicks + 1, 12)
							w.flickAt = now
						end
						w.fakeSince = nil
						local dt = now - w.realAt
						if w.realPos and dt > 1 / 240 and dt < 0.5 then
							local v = (p - w.realPos) / dt
							-- a hop inside the map is not a velocity (the counters own teleports)
							w.vel = if v.Magnitude <= 90 then w.vel:Lerp(v, math.clamp(dt * 10, 0.15, 1)) else Vector3.zero
						elseif dt >= 0.5 then
							w.vel = Vector3.zero
						end
						w.realPos, w.realAt, w.realRot = p, now, root.CFrame.Rotation
						for i, name in ipairs(Resolver.WARP_PARTS) do
							local part = w.parts[i]
							if not (part and part.Parent == model) then
								part = model:FindFirstChild(name)
								w.parts[i] = part or false
							end
							if part and part:IsA("BasePart") then
								w.rel[part] = part.Position - p
							end
						end
					end
				end
				if w.flicks > 0 and now - w.flickAt > 2 then
					w.flicks = 0
				end
				w.active = false
				if w.fakeSince and w.realPos then
					local age = now - w.realAt
					if age < Resolver.warpHold(w) then
						local pos = w.realPos + w.vel * math.min(age, Resolver.WARP_AHEAD)
						local rot = w.realRot or root.CFrame.Rotation
						if pcall(function()
							root.CFrame = CFrame.new(pos) * rot
						end) then
							w.wrote = root.Position
							w.active = true
							w.fixes += 1
						end
					end
				end
				local warping = w.flicks >= 2 or w.active
				if warping and not w.warping and now - (w.loggedAt or -10) > 10 then
					w.loggedAt = now
					log("INFO", ("[resolver:warp] %s flickers off the map — aiming at their real spot"):format(Game.fighterName(f)))
				end
				w.warping = warping
				-- continuous time on the map (a real sample or a held one): Resolver.presentFor
				if w.fakeSince ~= nil and not w.active then
					w.presentSince = nil
				else
					w.presentSince = w.presentSince or now
				end
			end
		end
	end
	-- where `part` really is right now: `at` (default its live position) — or, while its model's live root reads
	-- fake, the part's last real spot (its centre: a point measured on the fake spot is noise) and true, for
	-- WARP_KEEP s. Property reads and table lookups only: the shot hooks call it
	function Resolver.fixPos(part: BasePart, at: Vector3?): (Vector3, boolean)
		local p = at or part.Position
		local w = Resolver.warp[part.Parent]
		local root = w and w.root
		if not (root and w.realPos and root.Parent) then
			return p, false
		end
		local rp = root.Position
		if w.wrote ~= nil and (rp - w.wrote).Magnitude < 0.01 then
			return p, false
		end
		if not Resolver.fakePos(rp) then
			return p, false
		end
		local age = os.clock() - w.realAt
		if age >= Resolver.WARP_KEEP then
			return p, false
		end
		local base = w.realPos + w.vel * math.min(age, Resolver.WARP_AHEAD)
		if part == root then
			return base, true
		end
		return base + (w.rel[part] or Vector3.zero), true
	end
	-- the velocity to lead with: a warping model's replicated velocity is noise (24 000 st/s in the duel log)
	function Resolver.fixVel(part: BasePart): Vector3
		local w = Resolver.warp[part.Parent]
		if w and w.warping then
			return w.vel
		end
		return part.AssemblyLinearVelocity
	end
	function Resolver.warping(model: any): boolean
		local w = model and Resolver.warp[model]
		return w ~= nil and w.warping == true
	end
	-- out past the backtrack's hold: the live root reads fake and nothing put it back. The server has them out
	-- there too (duel, 2026-09-27: one warper read fake 657 of 657 frames over 10 s) — no round reaches them
	function Resolver.away(model: any): boolean
		local root = model and model:FindFirstChild("HumanoidRootPart")
		if not (root and root:IsA("BasePart")) then
			return false
		end
		local rp = root.Position
		local w = Resolver.warp[model]
		if w and w.wrote ~= nil and (rp - w.wrote).Magnitude < 0.01 then
			return false
		end
		return Resolver.fakePos(rp)
	end
	-- seconds they have been on the map without a break (0 while away)
	function Resolver.presentFor(model: any): number
		local w = model and Resolver.warp[model]
		if w then
			return if w.presentSince then os.clock() - w.presentSince else 0
		end
		return if model and Resolver.away(model) then 0 else math.huge
	end

	-- Track: 1 s position history per enemy model (head / body hitbox + root), sampled every frame
	-- from the loop. Backtrack aims at the point in this history the server is most likely to
	-- hit-test against (learned from the server's own ShootEffect results, see Shots).
	local Track: any = { hist = {}, N = 72 }
	S.track = Track
	function Track.newHist(): any
		return { t = table.create(Track.N), head = table.create(Track.N), body = table.create(Track.N), root = table.create(Track.N), i = 0, n = 0 }
	end
	Track.seen = {}
	function Track.update(enemies: { any })
		local now = os.clock()
		local seen: { [any]: boolean } = Track.seen
		table.clear(seen)
		for _, f in ipairs(enemies) do
			local root, model = Game.fighterBody(f)
			if root and model then
				seen[model] = true
				local hs = Track.hist[model]
				if not hs then
					hs = Track.newHist()
					Track.hist[model] = hs
				end
				local headPart = Game.hitboxPart(f, "Head") or Game.fighterHead(f)
				local bodyPart = Game.hitboxPart(f, "Body") or root
				hs.i = hs.i % Track.N + 1
				hs.n = math.min(hs.n + 1, Track.N)
				hs.t[hs.i] = now
				hs.head[hs.i] = if headPart then headPart.Position else root.Position
				hs.body[hs.i] = if bodyPart then bodyPart.Position else root.Position
				hs.root[hs.i] = root.Position
			end
		end
		for model in pairs(Track.hist) do
			if not seen[model] then
				Track.hist[model] = nil
			end
		end
	end
	-- position of `which` (head | body | root) for `model` as it was `agoSec` seconds ago (linear
	-- interpolation between samples; clamped to the oldest sample). nil when nothing is recorded.
	function Track.at(model: any, which: string, agoSec: number): Vector3?
		local hs = model and Track.hist[model]
		if not hs or hs.n == 0 then
			return nil
		end
		local src = hs[which] or hs.head
		local want = os.clock() - math.max(agoSec, 0)
		local newer: number? = nil
		local guard = 0
		local idx = hs.i
		while guard < hs.n do
			guard += 1
			local t = hs.t[idx]
			if t and t <= want then
				local p = src[idx]
				if newer and hs.t[newer] and hs.t[newer] > t then
					local a = (want - t) / math.max(hs.t[newer] - t, 1e-4)
					return p:Lerp(src[newer], math.clamp(a, 0, 1))
				end
				return p
			end
			newer = idx
			idx = (idx - 2) % Track.N + 1
		end
		-- older than everything we have → oldest sample
		local oldest = if hs.n < Track.N then 1 else hs.i % Track.N + 1
		return src[oldest]
	end
	-- the delay in the target's history that puts a history point closest to `serverPos`
	function Track.bestDelay(model: any, which: string, firedAt: number, serverPos: Vector3): (number?, number?)
		local hs = model and Track.hist[model]
		if not hs or hs.n == 0 then
			return nil, nil
		end
		local src = hs[which] or hs.head
		local bestD, bestDelay = math.huge, nil
		for k = 1, hs.n do
			local t = hs.t[k]
			local p = src[k]
			if t and p and t <= firedAt + 0.05 and firedAt - t < 1 then
				local d = (p - serverPos).Magnitude
				if d < bestD then
					bestD = d
					bestDelay = firedAt - t
				end
			end
		end
		return bestDelay, if bestD < math.huge then bestD else nil
	end

	-- Counters: per-enemy edge detection every frame (one position read each). A teleporter's position
	-- jumps further than any walk explains; a void spammer dips under the map and surfaces again and
	-- again. Both are weakest right after the move (their client is still settling, ours is not): the
	-- lock prefers them in that window, magic waits over the spot a spammer left, and the trigger
	-- fires the frame they come back up.
	do
	local Counter: any = { track = setmetatable({}, { __mode = "k" }) }
	S.counter = Counter
	function Counter.update(targets: { any })
		if not (cfg.counterVoid or cfg.counterTeleport) then
			return
		end
		-- every 2nd frame: the jump test scales with the time between samples, and a void dip lasts far longer
		if Game.frameId % 2 == 1 then
			return
		end
		local now = os.clock()
		local box = S.safe and S.safe.box
		local floorY = if box then box.min.Y else nil
		for _, f in ipairs(targets) do
			local root = Game.fighterBody(f)
			if root then
				local t = Counter.track[f]
				if not t then
					t = {}
					Counter.track[f] = t
				end
				local p = root.Position
				local lp, lt = t.pos, t.at
				local jumped = false
				if lp and lt then
					local dt = math.max(now - lt, 1 / 240)
					local walk = root.AssemblyLinearVelocity.Magnitude * dt * 2 + 6
					if (p - lp).Magnitude > math.max(walk, 14) then
						jumped = true
						t.jump2, t.jump1 = t.jump1, now
						t.jumpFrom = lp
					end
				end
				t.pos, t.at = p, now
				-- under the map: below the map box (cheap, every frame), or the cached void test — which a
				-- jump straight up this frame overrides (the cache is up to 0.25 s old)
				-- "away" also covers a spammer parked high in the sky or far outside the arena (ESP showed them
				-- thousands of studs up and nothing reacted): anywhere a round from the map cannot reach
				local off = box ~= nil and (p.Y > box.max.Y + 60 or p.X < box.min.X - 60 or p.X > box.max.X + 60 or p.Z < box.min.Z - 60 or p.Z > box.max.Z + 60)
				local under = (floorY ~= nil and p.Y < floorY) or off or (S.bounds.isVoidFighter(f) and not (jumped and lp ~= nil and p.Y > lp.Y + 10))
				t.off = off == true
				if under and not t.void then
					t.dip2, t.dip1 = t.dip1, now
					t.left = lp or p -- where they dropped from: where they most likely come back up
				elseif t.void and not under then
					t.surfaceAt = now
				end
				t.void = under
			end
		end
	end
	function Counter.spammer(t: any): boolean
		return t ~= nil and t.dip2 ~= nil and os.clock() - t.dip2 < 8
	end
	-- a repeat void spammer who is away right now (under, over or outside the map)
	function Counter.spammerAway(list: { any }?): any
		if not cfg.counterVoid or type(list) ~= "table" then
			return nil
		end
		for _, f in ipairs(list) do
			local t = Counter.track[f]
			if t and t.void and Counter.spammer(t) then
				return f
			end
		end
		return nil
	end
	-- above the map box or outside it (not under it: a void camper is reachable from the measured void)
	function Counter.offMap(f: any): boolean
		local t = f and Counter.track[f]
		return t ~= nil and t.off == true
	end
	function Counter.teleporter(t: any): boolean
		return t ~= nil and t.jump2 ~= nil and os.clock() - t.jump2 < 8
	end
	-- the moment right after a move: they are still settling, we are not
	function Counter.window(f: any): boolean
		local t = f and Counter.track[f]
		if not t then
			return false
		end
		local now = os.clock()
		return (cfg.counterTeleport and t.jump1 ~= nil and now - t.jump1 < 0.45) or (cfg.counterVoid and t.surfaceAt ~= nil and now - t.surfaceAt < 0.6) or false
	end
	-- lock bias (a score multiplier, lower = preferred): the punish window, and a spammer mid-dip keeps
	-- the lock so the shot is ready the frame they surface
	function Counter.bias(f: any): number
		-- a blade about to reach us is the target, whoever else is around
		local mt = S.meleeThreat
		if cfg.antiMelee and cfg.antiMeleeTarget and mt and mt.fighter == f then
			return 0.2
		end
		local t = Counter.track[f]
		if not t then
			return 1
		end
		-- parked high in the sky / far outside the arena: no round reaches them — only when nobody else is there
		if t.off then
			return 8
		end
		if Counter.window(f) then
			return 0.25
		end
		if cfg.counterVoid and t.void and Counter.spammer(t) and os.clock() - (t.dip1 or 0) < 3 then
			return 0.35
		end
		return 1
	end
	-- where magic waits for a spammer who just dipped: over the spot they left (they come back up there
	-- within a second); nil = plan for them where they are
	function Counter.trapPoint(f: any): Vector3?
		local t = cfg.counterVoid and f and Counter.track[f]
		if t and t.void and t.left and Counter.spammer(t) and os.clock() - (t.dip1 or 0) < 1.2 then
			return t.left
		end
		return nil
	end
	-- ESP flag: what this enemy has been doing
	function Counter.tag(f: any): string?
		local t = Counter.track[f]
		-- inside the floor (the under desync), near enough to matter: the buried test is cached per model
		local root, model = Game.fighterBody(f)
		local me = S.myRootPart
		if root and me and model and (root.Position - me.Position).Magnitude < 90 and S.bounds.buriedTop(model) then
			return "UNDER"
		end
		if model and Resolver.warping(model) then
			return "WARP"
		end
		if Counter.spammer(t) then
			return "VOIDSPAM"
		end
		if Counter.teleporter(t) then
			return "TP"
		end
		return nil
	end
	end -- Counter block

	local Target: any = {}
	S.target = Target

	function Target.aimRadius(): number
		if cfg.aimFov360 then
			return math.huge
		end
		return if cfg.fovLinked then cfg.silentFov else cfg.aimFov
	end
	-- the circle, unless "lock anywhere" is on or the ragebot has a positioning mode (it targets 360°)
	function Target.silentRadius(): number
		return if cfg.silentFov360 or Configs.rageOn(cfg) then math.huge else cfg.silentFov
	end
	-- v1.1.3 semi-legit silent aim: with a finite circle the lock only ever aims at a point of a hit box that
	-- is inside the circle. RIVALS registers two boxes (checked live): HitboxHead, and HitboxBody which runs
	-- from the feet to the chest — so arms and legs are body hits. For each box, the point nearest the ray
	-- through the circle's centre (the crosshair) is tested on screen; the preferred box wins when it is in
	-- the circle, else the closest one. Rage and 360° keep the old pick (radius = math.huge never gets here).
	Target.FOV_BOX = { { "Head", "Head" }, { "Body", "Body" }, { "Arms", "Body" }, { "Legs", "Body" } }
	function Target.boxPoint(p: BasePart, ray: Ray, center: Vector2, r2: number): (number?, Vector3?)
		local cf = p.CFrame
		local half = p.Size * 0.42 -- a little inside the box: the round must land in it, not graze its edge
		local t = math.max((p.Position - ray.Origin):Dot(ray.Direction), 0)
		local lq = cf:PointToObjectSpace(ray.Origin + ray.Direction * t)
		lq = Vector3.new(math.clamp(lq.X, -half.X, half.X), math.clamp(lq.Y, -half.Y, half.Y), math.clamp(lq.Z, -half.Z, half.Z))
		local scr = Game.w2s(cf:PointToWorldSpace(lq))
		if not scr then
			return nil, nil
		end
		local dv = scr - center
		local d2 = dv:Dot(dv)
		if d2 > r2 then
			return nil, nil
		end
		return d2, lq
	end
	-- the box of this fighter to shoot inside the circle: part, the point on it (object space; nil = its
	-- centre, when the centre itself is in the circle) and its screen distance². nil = nothing in the circle.
	function Target.fovPart(fighter: any, center: Vector2, radius: number): (BasePart?, Vector3?, number?)
		local cam = workspace.CurrentCamera
		if not cam then
			return nil, nil, nil
		end
		local ray = cam:ViewportPointToRay(center.X, center.Y)
		local r2 = radius * radius
		local set = cfg.silentHitboxes
		local any = cfg.silentFovFallback ~= false
		local preferBox = if cfg.silentPrefer == "Head" then "Head" else "Body"
		local _, model = Game.fighterBody(fighter)
		local bestP, bestL, bestD, bestSeen = nil, nil, nil, false
		local prefP, prefL, prefD = nil, nil, nil
		local done = {}
		for _, gb in ipairs(Target.FOV_BOX) do
			local box = gb[2]
			if not done[box] and (any or (type(set) == "table" and set[gb[1]])) then
				done[box] = true
				local p = Game.hitboxPart(fighter, box)
				if p then
					local d2, lq = Target.boxPoint(p, ray, center, r2)
					if d2 then
						-- the centre is the surest hit: use it when it is in the circle too
						local cs = Game.w2s(p.Position)
						if cs then
							local dv = cs - center
							if dv:Dot(dv) <= r2 then
								lq = nil
							end
						end
						if box == preferBox then
							prefP, prefL, prefD = p, lq, d2
						end
						-- with "visible hitbox" on, a box the server can see beats a closer blocked one
						local seen = not cfg.silentVisibleHitbox or model == nil or Game.rayVisible(model, p)
						if bestP == nil or (seen and not bestSeen) or (seen == bestSeen and d2 < (bestD :: number)) then
							bestP, bestL, bestD, bestSeen = p, lq, d2, seen
						end
					end
				end
			end
		end
		if prefP and (bestSeen == false or not cfg.silentVisibleHitbox or model == nil or Game.rayVisible(model, prefP)) then
			return prefP, prefL, prefD
		end
		return bestP, bestL, bestD
	end
	-- true when the silent pick runs the in-circle rule (a finite circle, not rage / 360°)
	function Target.silentFovMode(radius: number?, kind: string?): boolean
		return kind == "silent" and radius ~= nil and radius ~= math.huge
	end
	-- the hit box a part belongs to: RIVALS registers HitboxHead and HitboxBody (feet to chest); the root
	-- and the visual limbs count as the body
	function Target.boxOf(p: any): string?
		if typeof(p) ~= "Instance" then
			return nil
		end
		return if string.find(string.lower(p.Name), "head", 1, true) then "Head" else "Body"
	end
	-- may this kind put a round on this part? The head needs Head ticked; the body box takes Body, Arms or
	-- Legs. In the circle with "Hit what's in the circle" on, every box in the circle counts.
	function Target.boxAllowed(p: any, kind: string?, inCircle: boolean?): boolean
		local box = Target.boxOf(p)
		if not box then
			return false
		end
		if kind == "silent" and inCircle and cfg.silentFovFallback ~= false then
			return true
		end
		local set = if kind == "silent" then cfg.silentHitboxes else cfg.aimHitboxes
		if type(set) ~= "table" then
			return true
		end
		if box == "Head" then
			return set.Head == true
		end
		return set.Body == true or set.Arms == true or set.Legs == true
	end
	-- is this world point inside the silent circle on screen right now? (360° / rage: always)
	function Target.pointInCircle(pos: Vector3, radius: number): boolean
		if radius == math.huge then
			return true
		end
		local cam = workspace.CurrentCamera
		local scr = cam and Game.w2s(pos)
		if not scr then
			return false
		end
		local dv = scr - cam.ViewportSize / 2
		return dv:Dot(dv) <= radius * radius
	end

	-- 0..1: how squarely the enemy is looking at me (memoised per fighter per frame: situation,
	-- target pick and the auto-block ask about the same people in one frame)
	Target.threatMemo = setmetatable({}, { __mode = "k" })
	Target.threatFrame = -1
	function Target.threat(fighter: any): number
		if Target.threatFrame ~= Game.frameId then
			Target.threatFrame = Game.frameId
			table.clear(Target.threatMemo)
		end
		local cached = Target.threatMemo[fighter]
		if cached ~= nil then
			return cached
		end
		local me = Game.myRoot()
		local root = Game.fighterBody(fighter)
		local v = 0
		if me and root then
			local toMe = me.Position - root.Position
			if toMe.Magnitude < 0.5 then
				v = 1
			else
				local look = Game.enemyLook(fighter)
				if look then
					v = math.clamp((look:Dot(toMe.Unit) - 0.7) / 0.3, 0, 1)
				end
			end
		end
		Target.threatMemo[fighter] = v
		return v
	end

	-- one health read + one IsAlive pcall per fighter per frame (nearest, pick ×2, situation, quick
	-- melee and the kill feed all asked separately)
	Target.deadMemo = setmetatable({}, { __mode = "k" })
	Target.deadFrame = -1
	function Target.isDead(fighter: any): boolean
		if Target.deadFrame ~= Game.frameId then
			Target.deadFrame = Game.frameId
			table.clear(Target.deadMemo)
		end
		local cached = Target.deadMemo[fighter]
		if cached ~= nil then
			return cached
		end
		local dead = false
		local hp = Game.fighterHealth(fighter)
		if hp ~= nil and hp <= 0 then
			dead = true
		elseif type(fighter.IsAlive) == "function" then
			local ok, alive = pcall(fighter.IsAlive, fighter)
			if ok and alive == false then
				dead = true
			end
		end
		Target.deadMemo[fighter] = dead
		return dead
	end

	-- The FOV (or 360°) is the gate; the priority decides among the candidates that pass it.
	-- Returns { fighter, part, pos, model } or nil. pos is the resolver-corrected aim point.
	function Target.pick(enemies: { any }, fovRadius: number?, priority: string?, kind: string?): any
		local cam = workspace.CurrentCamera
		if not cam then
			return nil
		end
		local center = cam.ViewportSize / 2
		local radius = fovRadius or cfg.aimFov
		local all = radius == math.huge
		local best: any = nil
		local bestScore = math.huge
		local camPos, look = cam.CFrame.Position, cam.CFrame.LookVector
		local prefer = if kind == "silent" then cfg.silentPrefer else cfg.aimPrefer
		local fovMode = Target.silentFovMode(radius, kind)
		-- immune (spawn-protected) enemies only get the lock when nobody else qualifies: shooting them
		-- registers IMMUNE and empties the mag for nothing
		local anyMortal = false
		if cfg.immuneCheck then
			for _, fighter in ipairs(enemies) do
				if not Game.fighterImmune(fighter) and not (cfg.deadTargetGuard and Target.isDead(fighter)) then
					anyMortal = true
					break
				end
			end
		end
		local stickyKey = kind or "aim"
		local prev = Target.sticky[stickyKey]
		local prevScore: number? = nil
		local prevListed = false
		-- 5v5 / 10v10: a lock kept on someone behind a wall while others stand in the open made auto shoot
		-- and autokill "do nothing" — a hidden lock never holds against a visible best
		local prevSeen, bestSeen = true, true
		for _, fighter in ipairs(enemies) do
			if prev and fighter == prev.fighter then
				prevListed = true
			end
			-- gate on the preferred hitbox (cheap); the visibility-aware pick runs on the winner only
			local part = Game.hitboxPart(fighter, prefer) or Game.fighterBody(fighter)
			if part and anyMortal and Game.fighterImmune(fighter) then
				part = nil
			end
			if part and not (cfg.deadTargetGuard and Target.isDead(fighter)) then
				-- a warper out past the backtrack's hold is ranked from their last real spot: the lock (and the
				-- stream facing it) is already there the frame they reappear; the off-map bias keeps them last in line
				local at = Resolver.fixPos(part)
				local to = at - camPos
				local gateScore: number? = nil
				-- range gate: a 28-player lobby put the 360° lock on people 9 000 studs away in other
				-- arenas — every manual shot was redirected into a wall. RIVALS maps are < 300 studs.
				-- v5 void hunt: someone deep under the map is still ours when a relocation can reach them
				-- (the horizontal distance is what matters — the depth is the planner's problem)
				if to.Magnitude > cfg.targetMaxDistance then
					local horiz = Vector3.new(to.X, 0, to.Z).Magnitude
					local relocatable = cfg.voidHunt and (cfg.magicBullet or cfg.autokill) and horiz <= cfg.targetMaxDistance and part.Position.Y < camPos.Y
					if not relocatable then
						part = nil
					end
				end
				-- someone parked in the floor under us sits outside any FOV (straight down) and is the one
				-- shooting us: past the gate, first in line
				local under = part ~= nil and kind == "silent" and to.Magnitude <= 48 and S.bounds.underDesync((select(2, Game.fighterBody(fighter))))
				if not part then
					gateScore = nil
				elseif under and not fovMode then
					gateScore = to.Magnitude * 0.01
				elseif all then
					local ang = math.acos(math.clamp(look:Dot(to.Unit), -1, 1))
					gateScore = ang * 1000 + to.Magnitude * 0.01
				elseif fovMode then
					-- semi-legit: any hit box with a point in the circle qualifies (feet in the circle count)
					local _, _, d2 = Target.fovPart(fighter, center, radius)
					gateScore = d2
				else
					local scr = Game.w2s(at)
					if scr then
						local dv = scr - center
						local d2 = dv:Dot(dv)
						if d2 <= radius * radius then
							gateScore = d2
						end
					end
				end
				if gateScore then
					local score = gateScore
					if priority == "Closest" then
						score = to.Magnitude
					elseif priority == "LowestHP" then
						local hp = Game.fighterHealth(fighter)
						score = (hp or 1e9) * 1000 + to.Magnitude
					elseif priority == "Threat" then
						score = (1 - Target.threat(fighter)) * 1000 + to.Magnitude * 0.01
					end
					if cfg.threatPriority and priority ~= "Threat" then
						score = score * (1 - 0.5 * Target.threat(fighter))
					end
					-- v5.0.3: a target the server cannot see from our shot origin is a held trigger; one it can
					-- see is a shot NOW. Visible candidates rank first (×4 penalty; ×1.5 when a relocation can
					-- reach the hidden one anyway). The LOS ray is memoised per part per frame, ESP shares it.
					-- v0.9: the answer is kept 0.1 s per candidate (the ranking tolerates that; the lock's own
					-- S.targetVisible is always fresh) — ~31 rays a frame were 0.7 ms of a 0.9 ms lock step
					local seen = true
					if under then
						score = score * 0.25
					elseif cfg.targetPreferVisible and to.Magnitude <= 300 then
						local _, cmodel = Game.fighterBody(fighter)
						if cmodel then
							local vc = Target.visCache[cmodel]
							local now = os.clock()
							if not vc or vc.part ~= part or now - vc.at > 0.1 then
								vc = vc or {}
								vc.part, vc.at, vc.seen = part, now - math.random() * 0.03, Game.rayVisible(cmodel, part)
								Target.visCache[cmodel] = vc
							end
							if not vc.seen then
								seen = false
								score = score * (if (cfg.magicBullet and cfg.silentAim) or cfg.autokill then 2.5 else 4)
							end
						end
					end
					if prev and fighter == prev.fighter then
						prevSeen = seen
					end
					-- counters: just teleported / just surfaced / a void spammer mid-dip
					score = score * S.counter.bias(fighter)
					if prev and fighter == prev.fighter then
						prevScore = score
					end
					if score < bestScore then
						bestScore = score
						best = fighter
						bestSeen = seen
					end
				end
			end
		end
		-- Sticky aim: the lock outlives the FOV gate while the target is alive, on screen and in range.
		-- Never with the silent circle: a round only ever goes to a box inside it
		if cfg.stickyAim and not fovMode and prev and prevListed and not prevScore and Target.stickyHolds(prev.fighter, prefer, camPos, anyMortal, best ~= nil and bestSeen and cfg.targetPreferVisible) then
			best = prev.fighter
			prevScore = 0
		end
		if not best then
			Target.sticky[stickyKey] = nil
			return nil
		end
		-- stickiness: the current target keeps the lock while it still qualifies unless the new best
		-- scores clearly better (a lock flipping between two enemies every frame lands on neither). In a crowd
		-- the scores cross each other constantly (visibility, threat): a fresh lock is also held for the switch
		-- delay, so the rotation sync, the planner and the body are not restarted every few frames. A lock
		-- that stops qualifying (dead, out of range / circle, hidden while someone else is seen) still moves at once.
		local now = os.clock()
		if prev and prevScore and prev.fighter ~= best and (prevSeen or not bestSeen) then
			local held = now - (prev.since or 0) < Target.switchHold()
			if cfg.stickyAim or held or bestScore > prevScore * 0.6 then
				best = prev.fighter
			end
		end
		local st = Target.sticky[stickyKey]
		if not st then
			st = {}
			Target.sticky[stickyKey] = st
		end
		if st.fighter ~= best then
			st.since = now
		end
		st.fighter = best
		-- semi-legit: the box in the circle and the point on it; a sticky lock held outside the circle (no box
		-- in it) keeps the usual pick
		local fovP, fovL = nil, nil
		if fovMode then
			fovP, fovL = Target.fovPart(best, center, radius)
			if not fovP then
				Target.sticky[stickyKey] = nil
				return nil
			end
		end
		local part = (fovP or Game.aimPart(best, kind)) :: BasePart
		local root, model = Game.fighterBody(best)
		local pos = Resolver.aimPoint(best, part)
		if fovP then
			-- the resolver's torso fallback would leave the circle: stay on the box, shifted to the point
			if root and pos == root.Position and part ~= root then
				pos = part.Position
			end
			if fovL then
				pos = pos + part.CFrame:VectorToWorldSpace(fovL)
			end
		elseif root and pos == root.Position and part ~= root then
			-- resolver moved us to the torso: only when the body is one of this kind's hitboxes
			if Target.boxAllowed(root, kind, false) then
				part = root
			else
				pos = part.Position
			end
		end
		-- one result table per kind, reused every frame (callers read it immediately)
		local res = Target.result[stickyKey]
		if not res then
			res = {}
			Target.result[stickyKey] = res
		end
		res.fighter, res.part, res.pos, res.model = best, part, pos, model
		res.localPoint = if fovP then fovL else nil
		res.inCircle = fovP ~= nil
		return res
	end
	Target.sticky = {}
	Target.result = {}
	-- the shortest time a new lock is kept before another enemy may take it (Aimbot → Targeting → Switch delay);
	-- a crowd gets a longer hold on its own (5+ candidates: the scores cross far more often)
	function Target.switchHold(): number
		local ms = tonumber(cfg.targetSwitchMs) or 300
		if #(S.enemiesNow or {}) >= 5 then
			ms = math.max(ms, 450)
		end
		return ms / 1000
	end
	Target.visCache = setmetatable({}, { __mode = "k" })
	function Target.stickyHolds(fighter: any, prefer: any, camPos: Vector3, anyMortal: boolean, mustSee: boolean?): boolean
		if cfg.deadTargetGuard and Target.isDead(fighter) then
			return false
		end
		local hp = Game.fighterHealth(fighter)
		if hp and hp <= 0 then
			return false
		end
		if anyMortal and Game.fighterImmune(fighter) then
			return false
		end
		local part = Game.hitboxPart(fighter, prefer) or Game.fighterBody(fighter)
		if not part or not part.Parent then
			return false
		end
		if (part.Position - camPos).Magnitude > cfg.targetMaxDistance then
			return false
		end
		if mustSee then
			local _, m = Game.fighterBody(fighter)
			if m and not Game.rayVisible(m, part) then
				return false
			end
		end
		return Game.w2s(part.Position) ~= nil
	end

	function Target.nearest(enemies: { any }, skipImmune: boolean?): (any, number)
		local me = Game.myRoot()
		local best, bestD = nil, math.huge
		if not me then
			return nil, bestD
		end
		for _, f in ipairs(enemies) do
			local r = Game.fighterBody(f)
			if r and not (cfg.deadTargetGuard and Target.isDead(f)) and not (skipImmune and Game.fighterImmune(f)) then
				local d = (r.Position - me.Position).Magnitude
				if d < bestD then
					bestD, best = d, f
				end
			end
		end
		return best, bestD
	end

	-----------------------------------------------------------------------------
	-- §7 combat — aimbot, silent lock, magic Teleport, auto-shoot, autokill, stats
	-----------------------------------------------------------------------------
	local Combat: any = {}
	S.combat = Combat
	local ak = S.autokill

	-- server-consistency: after any teleport the server needs a moment to see the new position
	function Combat.markTeleport()
		S.lastTeleportAt = os.clock()
		S.lastTeleportOwner = (Combat.body and Combat.body.owner) or "you"
		-- the server's stored rotation was aimed from the old spot: the next shot proves the echo again
		-- (Combat.echoAligned is geometric, so an angle that still works from here passes at once)
		S.syncDoneFor = nil
	end
	-- Ragebot Enable off or ragePosition "None" = rage off: nothing that moves the body runs, whatever
	-- its own switch says
	function Combat.rageOn(): boolean
		return Configs.rageOn(cfg)
	end
	-- the Attack time slider's last notch: a run with no clock (sanitize keeps autokillUntilDead in step with it)
	Combat.AK_UNTIL_DEAD = 61
	-- the ragebot's setup check (Ragebot → General → Setup check): every switch that quietly stops it firing.
	-- Most "it doesn't shoot" reports were one of these, not a bug.
	function Combat.rageCheck(): { any }
		local out = {}
		local function add(text)
			table.insert(out, { text = text })
		end
		if cfg.rageEnabled == false then
			add("Ragebot is off")
		end
		if not cfg.silentAim then
			add("silent aim is off (the ragebot aims through it)")
		end
		if not cfg.autoShoot then
			add("auto shoot is off (it only fires when you click)")
		end
		if (cfg.ragePosition == nil or cfg.ragePosition == "None") and not cfg.silentFov360 then
			add("Mode is None, so it only locks inside your silent aim circle")
		end
		if cfg.silentOnlyFiring then
			add("silent aim 'Only while firing' keeps the lock off until you shoot")
		end
		if (tonumber(cfg.silentHitChance) or 100) < 100 then
			add(("silent hit chance is %d%%, so some rounds go where you aim"):format(cfg.silentHitChance))
		end
		if (tonumber(cfg.autoShootMinHitChance) or 0) > 50 then
			add(("min hit chance %d%% holds most shots"):format(cfg.autoShootMinHitChance))
		end
		if cfg.legitTrigger then
			add("the triggerbot takes targets under your crosshair")
		end
		local set = cfg.silentHitboxes
		if type(set) ~= "table" or not (set.Head or set.Body or set.Arms or set.Legs) then
			add("no silent aim hitbox is ticked")
		end
		if (tonumber(cfg.targetMaxDistance) or 400) < 250 then
			add(("max distance is only %d st"):format(cfg.targetMaxDistance))
		end
		return out
	end
	function Combat.rageFix(): { string }
		local fixed = {}
		local function set(key, value, label)
			if cfg[key] ~= value then
				cfg[key] = value
				table.insert(fixed, label)
			end
		end
		set("rageEnabled", true, "Ragebot on")
		set("silentAim", true, "silent aim on")
		set("autoShoot", true, "auto shoot on")
		set("silentOnlyFiring", false, "Only while firing off")
		if (tonumber(cfg.silentHitChance) or 100) < 100 then
			set("silentHitChance", 100, "silent hit chance 100%")
		end
		if (tonumber(cfg.autoShootMinHitChance) or 0) > 50 then
			set("autoShootMinHitChance", 0, "min hit chance 0%")
		end
		set("legitTrigger", false, "triggerbot off")
		if cfg.ragePosition == nil or cfg.ragePosition == "None" then
			set("silentFov360", true, "360° targeting")
		end
		local hb = cfg.silentHitboxes
		if type(hb) ~= "table" or not (hb.Head or hb.Body or hb.Arms or hb.Legs) then
			cfg.silentHitboxes = { Head = true, Body = true }
			table.insert(fixed, "hitboxes head + body")
		end
		if (tonumber(cfg.targetMaxDistance) or 400) < 250 then
			set("targetMaxDistance", 400, "max distance 400 st")
		end
		return fixed
	end
	-- why it is not firing this very moment, in words (the setup is Combat.rageCheck)
	function Combat.rageNow(): string
		if S.featuresPaused then
			return "Lobby: paused until a round or the range"
		end
		local issues = Combat.rageCheck()
		if #issues > 0 then
			return "Setup: " .. issues[1].text
		end
		if S.silentTarget == nil then
			local n = #(S.enemiesNow or {})
			if n == 0 then
				return "No enemies here"
			end
			if Target.silentRadius() ~= math.huge then
				return "Nobody inside the circle"
			end
			return ("No target in range (%d enemies, max %d st)"):format(n, cfg.targetMaxDistance or 400)
		end
		if S.holdReason then
			return "Holding: " .. tostring(S.holdReason)
		end
		return "Firing at " .. (if S.silentFighter then Game.fighterName(S.silentFighter) else "the target")
	end
	-- settle time in seconds: the slider, or ping + 40 ms when that is longer (auto).
	-- Reads S.pingMs (refreshed by the loop) — this runs inside the __namecall hook, where any
	-- method call of our own would clobber the pending namecall method before oldNc runs.
	-- v5.0.3: the position only has to be AT the server when the shot input lands — one-way (ping/2)
	-- + 50 ms, not a round trip. S.settleExtra is the learned correction: a post-hop shot that came
	-- back NO-REPLY, WALL or AIR adds 25 ms (cap 200), a post-hop HIT takes 5 ms off.
	-- v6.3: the learned extra is kept per body owner (autokill / defense / dodge / magic hop differently)
	-- and may grow to one full round trip — at 250–700 ms the old 80 ms cap left every post-hop sniper
	-- round on a wall 5–40 st off (duel logs 2026-09-24). Slow / one-shot guns wait 50 ms more.
	-- Reads only table fields and S.pingMs: this runs inside the __namecall hook.
	S.settleBy = S.settleBy or {}
	-- v6.4: capped at half a round trip (max 150 ms). The 6.3 cap of a full trip ratcheted up to ~470 ms
	-- and, with magic's hops every ~0.6 s, the gun waited after nearly every hop ("teleports and waits":
	-- duel tempo logs showed 31–54 % of idle time on the settle and first shots 3–13 s in)
	function Combat.settleExtraMax(): number
		return math.clamp((S.pingMs or 0) * 0.5, 50, 150)
	end
	function Combat.settleSec(): number
		local base = cfg.silentSettleMs / 1000
		if cfg.settleAuto then
			local extra = math.min(S.settleBy[S.lastTeleportOwner or "you"] or S.settleExtra or 0, Combat.settleExtraMax())
			base = math.max(base, ((S.pingMs or 0) * 0.5 + 50 + extra + (if S.slowGunNow then 25 else 0)) / 1000)
		end
		return math.min(base, 0.6)
	end
	-- hopAt is the teleport before the shot: by the time the answer lands, Body has usually hopped again.
	-- returns the ms it added (a kill found later takes it back, Shots.killed)
	Combat.SETTLE_EXTRA_MAX = 500
	function Combat.settleLearn(verdict: string, shotAt: number, hopAt: number?): number
		if shotAt - (hopAt or S.lastTeleportAt or 0) > Combat.settleSec() + 0.15 then
			return 0 -- not a post-hop shot: says nothing about the settle
		end
		local owner = S.lastTeleportOwner or "you"
		local cur = S.settleBy[owner] or 0
		-- the trigger's line of sight was clear from the claimed origin, so a post-hop ray that stopped
		-- on a wall or went wide left from where the server still had us (those count double)
		local add = if verdict == "WALL" or verdict == "AIR" then 25 elseif verdict == "NO-REPLY" then 15 else 0
		if add > 0 then
			local nv = math.min(Combat.settleExtraMax(), cur + add)
			S.settleBy[owner] = nv
			S.settleExtra = nv
			S.settleExtraAt = os.clock()
			return nv - cur
		elseif verdict == "HIT" then
			S.settleBy[owner] = math.max(0, cur - 5)
		end
		return 0
	end
	-- v6.3 per-gun hit tracker: the last 20 answered rounds per weapon. Under 40 % the gun first flips its
	-- spread mode once (claim ↔ real aim, never for scoped guns), then gives up range 20 % at a time
	-- (floor 50 %). Range scales Combat.gunMaxRange and the origin planner's distance. Minigun: 60 st.
	Combat.gun = { ring = {}, flipped = {}, range = {} }
	-- survey (decompiled/weapons.json): pellet guns spread 10 pellets / 5 for Distortion, the Minigun 8 dmg
	-- rounds at 0.05 s — past these distances most rounds end on walls
	Combat.GUN_RANGE = { Minigun = 60, Shotgun = 25, Shorty = 18, Distortion = 30 }
	function Combat.gunTrack(weapon: string, hit: boolean)
		local G = Combat.gun
		local ring = G.ring[weapon]
		if not ring then
			ring = {}
			G.ring[weapon] = ring
		end
		table.insert(ring, hit)
		if #ring > 20 then
			table.remove(ring, 1)
		end
		if #ring < 20 then
			return
		end
		local hits = 0
		for _, h0 in ipairs(ring) do
			if h0 then
				hits += 1
			end
		end
		if hits >= 8 then
			return
		end
		G.ring[weapon] = {}
		local item = S.gameState and S.gameState.item
		local info = type(item) == "table" and item.Info
		local scoped = type(info) == "table" and info.AimScopePercent ~= nil
		if not G.flipped[weapon] and not scoped and cfg.spreadMode == "Auto" then
			G.flipped[weapon] = true
			local now = cfg.spreadLearned[weapon]
			cfg.spreadLearned[weapon] = if now == "real" then "claim" else "real"
			saveConfigSoon()
			log("INFO", ("[gun:adapt] %s hit %d of 20 — spread mode now %s"):format(weapon, hits, cfg.spreadLearned[weapon]))
			return
		end
		local r = math.max(0.5, (G.range[weapon] or 1) * 0.8)
		G.range[weapon] = r
		log("INFO", ("[gun:adapt] %s hit %d of 20 — engaging only within %d%% of its range"):format(weapon, hits, math.floor(r * 100)))
	end
	-- the farthest this gun should shoot from (studs), nil = no limit beyond targetMaxDistance
	function Combat.gunMaxRange(weapon: string?): number?
		if type(weapon) ~= "string" then
			return nil
		end
		local base = Combat.GUN_RANGE[weapon]
		local scale = Combat.gun.range[weapon]
		if not base and not scale then
			return nil
		end
		return (base or math.min(cfg.targetMaxDistance, 400)) * (scale or 1)
	end
	function Combat.settleUnlearn(ms: number)
		local owner = S.lastTeleportOwner or "you"
		S.settleBy[owner] = math.max(0, (S.settleBy[owner] or 0) - ms)
	end
	S.settleExtra = math.min(S.settleExtra or 0, Combat.SETTLE_EXTRA_MAX)
	-- the learned extra drifts back 10 ms per 6 s without a bad post-hop answer: every hop waits it
	function Combat.settleDecay()
		local now = os.clock()
		if now - (S.settleExtraAt or 0) > 3 then
			S.settleExtraAt = now
			for k, v in pairs(S.settleBy) do
				S.settleBy[k] = if v > 10 then v - 10 else nil
			end
			S.settleExtra = math.max(0, (S.settleExtra or 0) - 10)
		end
		S.slowGunNow = Combat.slowGun()
	end
	-- slow or one-shot guns (sniper, Revolver-class, 1–2 round mags): one miss costs the whole cycle.
	-- From the ORIGINAL cooldown: rapid fire scales the live one.
	function Combat.slowGun(): boolean
		local gs = S.gameState
		local item = gs and gs.item
		local info = type(item) == "table" and item.Info
		if type(info) ~= "table" or info.Type ~= "Gun" then
			return false
		end
		local orig = S.statOriginals and S.statOriginals[tostring(item.Name)]
		local cd = tonumber(orig and orig.ShootCooldown) or tonumber(info.ShootCooldown) or 0
		return info.AimScopePercent ~= nil or cd >= 0.8 or (tonumber(info.MaxAmmo) or 99) <= 2
	end
	S.settleSec = Combat.settleSec
	function Combat.settled(): boolean
		return os.clock() - (S.lastTeleportAt or 0) >= Combat.settleSec()
	end
	-- shortest signed yaw difference a − b in (-π, π]; the one wrap helper (it was hand-rolled four times)
	function Combat.yawDelta(a: number, b: number): number
		return ((a - b + math.pi) % (2 * math.pi)) - math.pi
	end

	-- pin the *rendered* camera (Last+1 so nothing the game does later moves the view);
	-- the gun and the replicated rotation keep reading CameraController, so this only affects what you see
	local CAM_BIND = "centerra_camPin"
	local camPinned = false
	function Combat.pinCamera(on: boolean)
		if on == camPinned then
			return
		end
		camPinned = on
		if on then
			RunService:BindToRenderStep(CAM_BIND, Enum.RenderPriority.Last.Value + 1, function()
				local cam = workspace.CurrentCamera
				local cf = S.pinCF
				if cam and cf then
					-- position stays where you were; rotation stays yours (the game's rotation is not
					-- touched while invisible, the hooks aim the shots) → you keep looking around normally
					local rot = CameraController and CameraController.Rotation
					if typeof(rot) == "Vector2" then
						cam.CFrame = CFrame.new(cf.Position) * CFrame.fromOrientation(rot.X, rot.Y, 0)
					end
					-- no game rotation to follow (lobby, spectating): pinning the whole CFrame froze the
					-- view and "the mouse" with it — leave the camera alone instead
				end
			end)
		else
			pcall(RunService.UnbindFromRenderStep, RunService, CAM_BIND)
		end
	end
	function Combat.pinned(): boolean
		return camPinned
	end

	-----------------------------------------------------------------------------
	-- §7 noclip (v5) — collisions off on the entity model. RIVALS moves the character with a Humanoid
	-- + RootPart (no server position validator in the client scripts; movement replicates through
	-- Roblox physics ownership), so clearing CanCollide each Stepped lets us pass through walls and
	-- floors. Every relocation (magic / autokill / backstab / peek) turns it on for its duration so a
	-- shot origin can sit inside geometry or below the map; the OutOfBounds guard is what keeps that
	-- from being lethal. Originals are restored on release and on unload.
	-----------------------------------------------------------------------------
	do -- block-scoped (200-register cap): reachable as Combat.noclip / S.noclip
	local Noclip: any = { on = false, rageHold = 0, model = nil, saved = S.keep(), conn = nil, floatConn = nil }
	Combat.noclip = Noclip
	function Noclip.entityModel(): Model?
		local lf = Game.localFighter()
		local ent = lf and rawget(lf, "Entity")
		local m = type(ent) == "table" and ent.Model or nil
		-- v5.0.4 guard: only OUR body ever loses its collisions. A fighter object that is not ours
		-- (spectating after death hands the controller someone else's) would otherwise drop an enemy
		-- through the floor — "sometimes it teleports the enemy"
		if typeof(m) == "Instance" and m:IsA("Model") and (m == LP.Character or m.Name == LP.Name) then
			return m
		end
		return LP.Character
	end
	-- clear CanCollide on every BasePart of the model, remembering the originals per part (weak keys —
	-- a respawned model's parts fall out of the table by themselves)
	function Noclip.apply(model: Model)
		for _, d in ipairs(Game.modelParts(model, 0.3)) do
			if d:IsA("BasePart") and d.CanCollide then
				if Noclip.saved[d] == nil then
					Noclip.saved[d] = true
				end
				d.CanCollide = false
			end
		end
	end
	function Noclip.restoreAll()
		for part, was in pairs(Noclip.saved) do
			if typeof(part) == "Instance" and part.Parent and was == true then
				pcall(function()
					part.CanCollide = true
				end)
			end
			Noclip.saved[part] = nil
		end
	end
	-- rage relocations ask for noclip for a short window; it lapses on its own if the caller stops
	function Noclip.rage(holdSec: number?)
		Noclip.rageHold = os.clock() + (holdSec or 0.3)
	end
	-- a relocation handed the body back to the ground: collisions must return NOW, not when the hold
	-- lapses — 0.4 s of gravity with CanCollide off is 15 studs, i.e. through the floor
	function Noclip.release()
		Noclip.rageHold = 0
		if not S.cfg.noclip and Noclip.on then
			Noclip.on = false
			pcall(Noclip.restoreAll)
		end
	end
	function Noclip.wanted(): boolean
		if not S.alive or S.featuresPaused then
			return false
		end
		if S.cfg.noclip then
			return true
		end
		return S.cfg.noclipRage and os.clock() < Noclip.rageHold
	end
	-- one Stepped connection for the life of the state; reads live cfg, never captures it
	function Noclip.ensure()
		if Noclip.conn then
			return
		end
		Noclip.conn = Game.track(RunService.Stepped:Connect(function()
			local want = Noclip.wanted()
			if want then
				local model = Noclip.entityModel()
				if model then
					Noclip.model = model
					local okA, err = pcall(Noclip.apply, model)
					if not okA and S.hookErr then
						S.hookErr("noclip", err)
					end
				end
				Noclip.on = true
			elseif Noclip.on then
				Noclip.on = false
				pcall(Noclip.restoreAll)
			end
		end))
		-- float control: no gravity + WASD/space/ctrl fly while the toggle (not rage) noclip is on.
		-- Rage relocations pivot the body themselves and must not be fought, so float only runs for
		-- the explicit toggle.
		Noclip.floatConn = Game.track(RunService.Heartbeat:Connect(function()
			local root = S.myRootPart
			local active = S.alive and not S.featuresPaused and S.cfg.noclip and S.cfg.noclipFloat and os.clock() >= Noclip.rageHold and root ~= nil and root.Parent ~= nil
			if not active then
				Noclip.floatStop()
				return
			end
			local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
			local cam = workspace.CurrentCamera
			local move = hum and hum.MoveDirection or Vector3.zero
			local speed = S.cfg.noclipSpeed
			-- MoveDirection is world-space and always flat; follow-camera tilts it up/down with the pitch
			local flat = move * speed
			local up = 0
			if S.cfg.noclipFollowCamera and cam and move.Magnitude > 0.05 then
				local lookY = cam.CFrame.LookVector.Y
				up += lookY * speed
			end
			if Input.isKeyDown("Space") then
				up += speed
			end
			if Input.isKeyDown("LeftControl") or Input.isKeyDown("RightControl") then
				up -= speed
			end
			-- v5: a BodyVelocity mover is applied INSIDE the physics step, so the Humanoid's own walk
			-- controller and gravity no longer fight a velocity we wrote after the step (the v5.0 float
			-- stuttered and sagged for exactly that reason)
			local bv = Noclip.bv
			if not (bv and bv.Parent == root) then
				Noclip.floatStop()
				bv = Instance.new("BodyVelocity")
				bv.Name = "CenterraFloat"
				bv.MaxForce = Vector3.new(1e9, 1e9, 1e9)
				bv.P = 1e4
				bv.Parent = root
				Noclip.bv = bv
			end
			bv.Velocity = Vector3.new(flat.X, up, flat.Z)
		end))
	end
	function Noclip.floatStop()
		local bv = Noclip.bv
		if bv then
			Noclip.bv = nil
			pcall(function()
				bv:Destroy()
			end)
		end
	end
	function Noclip.shutdown()
		pcall(Noclip.floatStop)
		if Noclip.conn then
			pcall(function()
				Noclip.conn:Disconnect()
			end)
			Noclip.conn = nil
		end
		if Noclip.floatConn then
			pcall(function()
				Noclip.floatConn:Disconnect()
			end)
			Noclip.floatConn = nil
		end
		Noclip.on = false
		Noclip.rageHold = 0
		pcall(Noclip.restoreAll)
	end
	S.noclip = Noclip
	end -- Noclip block

	-- third person (CS2 style): our own over-the-shoulder camera bound right after the game's camera
	-- step. Aim, shots and replication keep using CameraController (first-person maths) — only the
	-- rendered view moves. Body parts are un-hidden, the viewmodel hidden, both restored on exit.
	local TP_BIND = "centerra_thirdPerson"
	local tpBound = false
	local tpParams = RaycastParams.new()
	tpParams.FilterType = Enum.RaycastFilterType.Exclude
	tpParams.IgnoreWater = true
	local tpPos: Vector3? = nil
	-- weak keys on all three: with third person on for a whole session every weapon swap (new viewmodel
	-- parts) and every respawn (new character) used to add entries that were never freed
	local tpHidden: { [Instance]: number } = S.keep()
	local tpShown: { [Instance]: boolean } = (setmetatable({}, { __mode = "k" }) :: any)
	local tpUnhidden: { [BasePart]: number } = S.keep() -- parts whose Transparency we forced down (original kept)
	local BODY_NAMES = {
		Head = true, UpperTorso = true, LowerTorso = true, Torso = true,
		LeftUpperArm = true, LeftLowerArm = true, LeftHand = true, RightUpperArm = true, RightLowerArm = true, RightHand = true,
		LeftUpperLeg = true, LeftLowerLeg = true, LeftFoot = true, RightUpperLeg = true, RightLowerLeg = true, RightFoot = true,
		["Left Arm"] = true, ["Right Arm"] = true, ["Left Leg"] = true, ["Right Leg"] = true,
	}
	Combat.tpCache = { char = nil, parts = {}, decals = {}, at = 0, filterChar = nil, filterCam = nil }
	local function tpRestoreParts()
		for part, tr in pairs(tpHidden) do
			if part.Parent then
				(part :: any).LocalTransparencyModifier = tr
			end
		end
		for part, tr in pairs(tpUnhidden) do
			if part.Parent then
				part.Transparency = tr
			end
		end
		for part in pairs(tpShown) do
			if part.Parent then
				(part :: any).LocalTransparencyModifier = 0 -- the game re-applies its own first-person hiding next frame
			end
		end
		table.clear(tpHidden)
		table.clear(tpShown)
		table.clear(tpUnhidden)
	end
	local function tpStep()
		local cam = workspace.CurrentCamera
		local char = LP.Character
		local head = S.myHeadPart
		if not (cam and char and head and head.Parent) or camPinned then
			return -- the invisible-teleport pin owns the camera while it is active
		end
		local rot = CameraController and CameraController.Rotation
		if typeof(rot) ~= "Vector2" then
			return
		end
		local rotCF = CFrame.fromOrientation(rot.X, rot.Y, 0)
		local side = if cfg.tpShoulder == "Right" then cfg.tpSide elseif cfg.tpShoulder == "Left" then -cfg.tpSide else 0
		local pivot = head.Position + Vector3.new(0, cfg.tpUp * 0.5, 0)
		local desired = pivot + rotCF:VectorToWorldSpace(Vector3.new(side, cfg.tpUp * 0.5, cfg.tpDist))
		local tc = Combat.tpCache
		if tc.filterChar ~= char or tc.filterCam ~= cam then
			tc.filterChar, tc.filterCam = char, cam
			tpParams.FilterDescendantsInstances = { char, cam }
		end
		local hit = workspace:Raycast(pivot, desired - pivot, tpParams)
		if hit then
			desired = hit.Position + (pivot - desired).Unit * 0.4
		end
		-- squeezed against a wall: the camera would sit inside our own head — fall back to a
		-- first-person view for those frames (body hidden again) instead of a black screen
		local nearWall = (desired - pivot).Magnitude < 1.4
		if nearWall then
			desired = head.Position + rotCF.LookVector * 0.2
		end
		if cfg.tpSmooth and tpPos and not hit then
			tpPos = tpPos:Lerp(desired, 0.35)
		else
			tpPos = desired
		end
		cam.CFrame = CFrame.new(tpPos :: Vector3) * rotCF.Rotation
		-- whole avatar visible: undo the first-person hide (LocalTransparencyModifier) and, for body
		-- parts (incl. accessory handles) the game blanked with Transparency itself, force them back
		-- (original remembered). The descendant list is cached per character and refreshed once a
		-- second — walking GetDescendants() with three IsA per part every frame was a top frame cost.
		if tc.char ~= char or os.clock() - tc.at > 1 then
			tc.char, tc.at = char, os.clock()
			table.clear(tc.parts)
			table.clear(tc.decals)
			for _, d in ipairs(char:GetDescendants()) do
				if d:IsA("BasePart") then
					if d.Name ~= "HumanoidRootPart" then
						table.insert(tc.parts, d)
					end
				elseif d:IsA("Decal") and d.Parent and BODY_NAMES[d.Parent.Name] then
					table.insert(tc.decals, d)
				end
			end
		end
		local wantMod = if nearWall then 1 else 0
		for _, d in ipairs(tc.parts) do
			if d.Parent ~= nil then
				tpShown[d] = true
				if d.LocalTransparencyModifier ~= wantMod then
					d.LocalTransparencyModifier = wantMod
				end
				local isBody = BODY_NAMES[d.Name] == true or (d.Parent ~= nil and d.Parent:IsA("Accessory"))
				if isBody and d.Transparency >= 0.95 and tpUnhidden[d] == nil then
					tpUnhidden[d] = d.Transparency
					d.Transparency = 0
				elseif tpUnhidden[d] ~= nil and d.Transparency >= 0.95 then
					d.Transparency = 0 -- the game set it again
				end
			end
		end
		for _, d in ipairs(tc.decals) do
			if d.Parent ~= nil and d.Transparency >= 0.95 then
				d.Transparency = 0
			end
		end
		if cfg.tpHideViewmodel then
			for _, m in ipairs(Game.viewmodelModels()) do
				for _, d in ipairs(Game.modelParts(m, 0.5)) do
					if d.Parent ~= nil then
						if tpHidden[d] == nil then
							tpHidden[d] = d.LocalTransparencyModifier
						end
						if d.LocalTransparencyModifier < 1 then
							d.LocalTransparencyModifier = 1
						end
					end
				end
				if m:IsA("BasePart") then
					if tpHidden[m] == nil then
						tpHidden[m] = m.LocalTransparencyModifier
					end
					m.LocalTransparencyModifier = 1
				end
			end
		end
	end
	-- body anti-aim: the enemy's view of us is our root part's replicated rotation, not the camera.
	-- Turn the real HumanoidRootPart to the anti-aim yaw after the game's own rotation update — the
	-- server replicates it, enemies see it, and in third person you see exactly what they see.
	-- Body yaw owner. Two jobs, same mechanism (the root part's replicated rotation):
	--  · teleported + invisible (magic / autokill): the body faces the lock even though your view does
	--    not — the server checks the shooter's facing against the shot, and the game keeps turning the
	--    root to the (pinned) camera every frame otherwise. This was the "invisible misses" cause.
	--  · anti-aim: the body turns to the anti-aim yaw (what enemies see; visible in third person).
	-- Applied after rendering AND after physics so the game's own rotation update never wins the tick.
	-- Who rotates the body: MechanicsController._UpdateCharacterRotation writes RootPart.CFrame from
	-- the rendered camera look on a plain RenderStepped connection — that runs AFTER every
	-- BindToRenderStep callback, so a bound step at Last+2 lost every frame (the old anti-aim only
	-- "took" when a Heartbeat write happened to be the last one before replication: ~10%). v4.2 hooks
	-- that method (Hooks.installMechanics → S.h.afterCharRot) and writes our yaw right after the
	-- game's own write, in the same frame, before physics and rendering: enemies, the server and
	-- third person all see it. Heartbeat keeps a second write after physics as a safety net.
	local aaHeartbeat: RBXScriptConnection? = nil
	local aaBound = false
	-- the yaw the body should show right now: the lock while teleported, else the anti-aim yaw
	function Combat.wantedBodyYaw(root: BasePart): number?
		local st = S.cfg
		if S.menuOpen or S.hudEdit or S.calibrating or not S.alive then
			return nil
		end
		local target = S.silentTarget
		if S.teleported and typeof(target) == "Vector3" then
			local d = (target - root.Position) * Vector3.new(1, 0, 1)
			if d.Magnitude > 0.1 then
				S.bodyYawMode = "lock"
				return math.atan2(-d.X, -d.Z) -- Roblox yaw: 0 looks down -Z
			end
		elseif st.aaEnabled and st.aaBody and not (st.aaOnlyIdle and S.firing) then
			local rot = CameraController and CameraController.Rotation
			if typeof(rot) == "Vector2" and type(S.h.rot) == "function" then
				local spoofed = S.h.rot(rot, "aaBody")
				if typeof(spoofed) == "Vector2" and spoofed ~= rot then
					S.bodyYawMode = "anti-aim"
					-- v5 body/replicate split: the physics body (our server-side hitbox orientation and
					-- what a model-reading client renders) can differ from the replicated rotation.
					-- Same = classic body anti-aim; Real = body keeps the true look while the channel
					-- fakes (desync); Opposite = body turned 180° from the fake.
					local mode = st.aaBodyMode
					if mode == "Real" then
						S.bodyYawMode = "desync"
						return rot.Y
					elseif mode == "Opposite" then
						S.bodyYawMode = "desync"
						return spoofed.Y + math.pi
					end
					return spoofed.Y
				end
			end
		end
		S.bodyYawMode = nil
		return nil
	end
	local function bodyYawStep()
		local root = Game.myRoot()
		if not root then
			return
		end
		local yaw = Combat.wantedBodyYaw(root)
		if yaw == nil then
			return
		end
		local v, av = root.AssemblyLinearVelocity, root.AssemblyAngularVelocity
		root.CFrame = CFrame.new(root.Position) * CFrame.Angles(0, yaw, 0)
		root.AssemblyLinearVelocity = v
		root.AssemblyAngularVelocity = av
		S.aaBodyYaw = yaw
	end
	Combat.bodyYawStep = bodyYawStep
	-- called by the _UpdateCharacterRotation hook after the game's write (every rendered frame)
	S.h.afterCharRot = function()
		if aaBound then
			bodyYawStep()
		end
	end
	function Combat.aaBody(on: boolean)
		if on == aaBound then
			return
		end
		aaBound = on
		if on then
			aaHeartbeat = RunService.Heartbeat:Connect(function()
				local ok, err = pcall(bodyYawStep)
				if not ok then
					S.hookErr("body yaw", err)
				end
			end)
		else
			if aaHeartbeat then
				aaHeartbeat:Disconnect()
				aaHeartbeat = nil
			end
		end
	end

	-- Replicated rotation. The game sends UpdateCameraRotation (utf8.char(pitch, yaw) quantised to
	-- 256 steps, verified against the server's echo in Fighter.Data.CameraRotation) only when the
	-- mouse moves, straight from CameraController.Rotation — never through GetCameraRotation, which
	-- is why the old layer-3 spoof never reached the server. v4.2: the namecall hook rewrites the
	-- payload of every send (h.encodeRot) and this re-sends the wanted rotation at cfg.aaSendHz while
	-- it differs from the real one, so spinning / jitter modes animate on the server even with the
	-- mouse still. S.aaServerRot mirrors what the server currently holds (awareness chip).
	Combat.aaSentAt = 0
	Combat.aaEchoAt = 0
	function Combat.updateAA()
		local now = os.clock()
		if now - Combat.aaEchoAt > 0.2 then
			Combat.aaEchoAt = now
			local lf = Game.localFighter()
			local ok, echo = pcall(function()
				return lf and lf:Get("CameraRotation")
			end)
			S.aaServerRot = if ok and typeof(echo) == "Vector2" then echo else nil
		end
		local rem = S.h.rotRemote
		if not (cfg.aaReplicate and rem and S.alive) or S.menuOpen or S.calibrating then
			S.aaServerWant = nil
			return
		end
		local real = CameraController and CameraController.Rotation
		if typeof(real) ~= "Vector2" or type(S.h.rot) ~= "function" then
			return
		end
		local fake = S.h.rot(real, "replicate")
		if typeof(fake) ~= "Vector2" then
			return
		end
		if fake == real then
			-- the game only sends when the mouse moves: a fake angle we sent earlier would stay on the
			-- server and a still-mouse shot would fly along it. Hand it the real rotation once.
			if Combat.aaLastFake then
				Combat.sendRotation(real)
				Combat.aaLastFake = false
			end
			S.aaServerWant = nil
			Combat.aaLastSent = nil
			return
		end
		S.aaServerWant = fake
		-- while a shot can leave the rotation tracks the target: stream it at 20 Hz and push a fresh
		-- one the moment it moves by more than a quantisation step; anti-aim idles at cfg.aaSendHz
		local live = if type(S.h.faceTarget) == "function" then S.h.faceTarget() else (S.lmbDown == true or S.autoEngaged == true)
		local minGap = if live then 0.05 else 1 / math.max(cfg.aaSendHz, 1)
		local last = Combat.aaLastSent
		local moved = last == nil or math.abs(fake.X - last.X) > 0.03 or math.abs(((fake.Y - last.Y + math.pi) % (2 * math.pi)) - math.pi) > 0.03
		if now - Combat.aaSentAt < minGap and not (live and moved and now - Combat.aaSentAt > 0.02) then
			return
		end
		if not live then
			-- an angle that is not the lock's replaces it on the server: the next shot waits for the echo again
			S.syncDoneFor = nil
		elseif S.silentFighter ~= nil and S.syncDoneFor ~= S.silentFighter then
			-- manual silent clicks never pass Combat.syncReady: record the echo here once it lines up
			Combat.refreshEcho()
			if Combat.echoAligned() then
				S.syncDoneFor = S.silentFighter
			end
		end
		Combat.sendRotation(fake)
		Combat.aaLastFake = true
	end
	-- one UpdateCameraRotation with `rot` (nil = whatever h.rot wants right now); also called right
	-- before every trigger pull so the server holds the target-facing rotation when the shot lands
	function Combat.sendRotation(rot: Vector2?)
		local rem = S.h.rotRemote
		if not rem then
			return
		end
		if rot == nil then
			local real = CameraController and CameraController.Rotation
			if typeof(real) ~= "Vector2" or type(S.h.rot) ~= "function" then
				return
			end
			rot = S.h.rot(real, "replicate")
			Combat.aaLastFake = rot ~= real
		end
		local enc = typeof(rot) == "Vector2" and S.h.encodeRot and S.h.encodeRot(rot)
		if enc then
			Combat.aaSentAt = os.clock()
			Combat.aaLastSent = rot
			-- MUST go out as game code: a FireServer from our own thread (identity 8) is silently
			-- dropped — the server echo never moved for hundreds of raw sends, and followed the very
			-- first one sent through the MechanicsController trampoline (verified in the lobby)
			local ok, err = Game.asShotCode(rem.FireServer, rem, enc, nil)
			if not ok and S.hookErr then
				S.hookErr("send rotation", err)
			end
			Combat.aaSends = (Combat.aaSends or 0) + 1
			Combat.noteSent(rot, type(S.h.lockFacingNow) == "function" and S.h.lockFacingNow() == true)
		end
	end
	-- how far the server's idea of our yaw is from the real one (radians, 0..π); nil = unknown
	function Combat.aaServerDelta(): number?
		local echo, real = S.aaServerRot, CameraController and CameraController.Rotation
		if typeof(echo) ~= "Vector2" or typeof(real) ~= "Vector2" then
			return nil
		end
		return math.abs(((echo.Y - real.Y + math.pi) % (2 * math.pi)) - math.pi)
	end

	function Combat.thirdPerson(on: boolean)
		if on == tpBound then
			return
		end
		tpBound = on
		S.tpActive = on -- the shot origin moves to the head while the camera hangs behind us (h.shotOrigin)
		if on then
			tpPos = nil
			RunService:BindToRenderStep(TP_BIND, Enum.RenderPriority.Camera.Value + 1, function()
				local ok, err = pcall(tpStep)
				if not ok then
					S.hookErr("third person", err)
				end
			end)
			log("INFO", "third person: on")
		else
			pcall(RunService.UnbindFromRenderStep, RunService, TP_BIND)
			tpRestoreParts()
			log("INFO", "third person: off")
		end
	end
	S.thirdPerson = Combat.thirdPerson

	-- aimbot: smooth the real camera toward the target (yaw unwrapped so we turn the short way).
	-- Frame-rate independent: a fixed per-frame lerp tracks slowly at low FPS and snaps at high FPS —
	-- on a variable-FPS machine that feels inconsistent ("bad"). Convert aimSmooth into a time
	-- constant so the turn speed is the same at 30 or 144 FPS.
	-- one aim owner per frame: the aimbot and auto-shoot's Camera mode both called this in the same
	-- frame, the second call saw a 1/240 s dt (alpha ÷4) and pulled toward a different point
	local lastAimAt = 0
	Combat.aimFrame = -1
	Combat.aimAcq = { fighter = nil, at = 0 } -- the aimbot's current target and when it was first seen
	-- legit = the aimbot itself (pull strength / mouse-only apply); auto shoot's camera aim and the utility
	-- throw turn at full strength
	-- mods (legit only, from S.ext.legitAim): { speed = 0..1 } scales the turn and its speed cap
	function Combat.aimAt(pos: Vector3, legit: boolean?, mods: any?)
		if Combat.aimFrame == Game.frameId then
			return
		end
		Combat.aimFrame = Game.frameId
		local cf = CameraController:GetCameraCFrame()
		-- aim point randomness: a slow drift around the point, so the aim never sits dead on one spot
		local hz = if legit then cfg.aimHumanize or 0 else 0
		if hz > 0 then
			local t = os.clock() * 0.8
			pos += Vector3.new(math.noise(t, 1.7) * hz, math.noise(t, 5.3) * hz * 0.6, math.noise(t, 9.1) * hz)
		end
		local pitch, yaw = CFrame.lookAt(cf.Position, pos):ToOrientation()
		local cur: Vector2 = CameraController.Rotation
		-- unwrap the yaw so the turn goes the short way (continuous with the current yaw, the way
		-- the game's own mouse input accumulates it)
		local target = Vector2.new(pitch, cur.Y + Combat.yawDelta(yaw, cur.Y))
		local now = os.clock()
		local dt = math.clamp(now - lastAimAt, 1 / 240, 1 / 20)
		lastAimAt = now
		local alpha: number
		if cfg.aimSmooth <= 1 then
			alpha = 1
		else
			-- aimSmooth = how many "60fps frames" to close the gap; exp keeps it FPS-stable
			local rate = 60 / cfg.aimSmooth
			if cfg.aimDynamic then
				-- a close target needs a slightly faster turn than a far one. Capped at ×1.4: the old
				-- distance × error × "aimed at" product reached ×4, which is a flick, not smoothing
				local dist = (pos - cf.Position).Magnitude
				local k = math.clamp(1 + (30 - dist) / 30 * 0.5, 0.8, 1.4)
				rate *= k
			end
			alpha = math.clamp(1 - math.exp(-rate * dt), 0.02, 1)
		end
		-- v6.6 pull strength: how hard each frame pulls toward the target (100 % = the smoothing alone); a
		-- weaker pull leaves part of the turn to your own hand. "Only while moving the mouse" pulls only
		-- while your hand moves, so a still mouse never drifts onto someone
		local strength = if legit then math.clamp((cfg.aimStrength or 100) / 100, 0.05, 1) else 1
		if legit and mods and tonumber(mods.speed) then
			strength = math.clamp(strength * tonumber(mods.speed), 0.02, 1)
		end
		if legit and cfg.aimOnlyMoving then
			local md = UIS:GetMouseDelta()
			if md.X * md.X + md.Y * md.Y < 0.25 then
				return
			end
		end
		alpha *= strength
		local nextRot = cur:Lerp(target, alpha)
		if cfg.aimSmooth > 1 or strength < 1 then
			-- a hand never turns faster than this: 900°/s at smoothing 1 down to 45°/s at 20
			local maxStep = math.rad(900 / cfg.aimSmooth) * dt * strength
			local d = nextRot - cur
			if d.Magnitude > maxStep then
				nextRot = cur + d.Unit * maxStep
			end
		end
		Game.asGame(CameraController.SetRotation, CameraController, nextRot)
	end

	-- Lead on moving targets (v4.3). Which lead the server wants depends on how it resolves a shot
	-- (rewind vs. current state) and on the ping, so Auto measures instead of guessing: six arms
	-- (0 … 260 ms), each scored by HIT verdicts on targets moving > 8 st/s; the best-scoring arm
	-- is used, an under-sampled one every fifth shot. The result is persisted (cfg.leadLearnedMs).
	-- v5: arms reach a full RTT — the server fires along the rotation it holds when the shot arrives,
	-- and that rotation was aimed at a target position already one trip stale (duel evidence: 128 ms
	-- ping, NEAR 3.3–3.8 st on a 7 st/s target with leads ≤ 100 ms)
	Combat.LEAD_ARMS = { 0, 0.05, 0.10, 0.15, 0.20, 0.26, 0.33, 0.40 }
	S.lead = S.lead or { arms = {}, sec = 0, pendingArm = nil, moving = 0, best = 1 }
	for i = 1, #Combat.LEAD_ARMS do
		S.lead.arms[i] = S.lead.arms[i] or { n = 0, hits = 0 }
	end
	-- the lead the rotation STREAM should carry right now — pure (no bandit bookkeeping; leadSec below
	-- draws the arm once per shot). The 20 Hz stream aims where the target will be, not where it is.
	-- v5.0.5 cheater-aware: no legit player moves faster than ~45 st/s (sprint ~30, a Warper dash for
	-- an instant). A steady 80–207 st/s (duel logs: two opponents) is a fly / speed cheat whose
	-- velocity vector says nothing about where they will be — a 150 ms lead put the fallback ray 31 st
	-- from the body. Above this speed the aim is the live part, no lead.
	Combat.CHEAT_SPEED = 60
	function Combat.leadSecNow(speed: number): number
		local mode = cfg.leadMode
		if mode == "Off" or speed < 3 or speed > Combat.CHEAT_SPEED then
			return 0
		end
		if mode == "Manual" then
			return cfg.leadMs / 1000
		end
		local L = S.lead
		local arm = L.pendingArm or L.best or 1
		return Combat.LEAD_ARMS[arm] or 0
	end
	-- where the replicated rotation should point for the locked part: its live position plus the lead
	-- (capped at three part-sizes so a sprinter never gets a 10-stud guess). Pure property reads — safe
	-- inside the namecall hook (h.rot is asked from the payload rewrite there).
	-- v6.3 projectile guns (Energy Pistols, Slingshot, launchers, Crossbow…): the round flies at the
	-- ORIGINAL ProjectileSpeed (Instant projectiles only edits our client's copy), so the aim goes where
	-- the target will be after the flight plus the one-way ping, lifted by the drop. Table / property
	-- reads only (hook-safe). Returns (flight s, gravity) or nil for a hitscan gun.
	function Combat.projectileFlight(part: BasePart): (number?, number)
		local gs = S.gameState
		local item = gs and gs.item
		local info = type(item) == "table" and item.Info
		if type(info) ~= "table" or info.IsProjectile ~= true then
			return nil, 0
		end
		local orig = S.statOriginals and S.statOriginals[tostring(item.Name)]
		local spd = tonumber(orig and orig.ProjectileSpeed) or tonumber(info.ProjectileSpeed)
		if not spd or spd <= 0 or spd >= 50000 then
			return nil, 0
		end
		local head = S.myHeadPart
		if not (head and head.Parent) then
			return nil, 0
		end
		local g = tonumber(orig and orig.ProjectileGravity) or tonumber(info.ProjectileGravity) or 0
		if S.cfg.instantBullet and orig == nil then
			g = 0
		end
		return (Resolver.fixPos(part) - head.Position).Magnitude / spd, g
	end
	function Combat.ledAim(part: BasePart?, fallback: Vector3): Vector3
		if typeof(part) ~= "Instance" or not part.Parent then
			return fallback
		end
		local vel = Resolver.fixVel(part)
		local speed = vel.Magnitude
		local base = Resolver.fixPos(part)
		local fly, grav = Combat.projectileFlight(part)
		if fly then
			local t = fly + (S.pingMs or 0) / 2000
			local p = base
			if speed > 1 and speed <= Combat.CHEAT_SPEED then
				local lead = vel * t
				if lead.Magnitude > 40 then
					lead = lead.Unit * 40
				end
				p += lead
			end
			if grav > 0 then
				-- ProjectileGravity is a multiplier of workspace gravity (library: 0.25 / 0.5 / 1)
				p += Vector3.new(0, math.min(0.5 * grav * workspace.Gravity * fly * fly, 25), 0)
			end
			return p
		end
		local leadSec = Combat.leadSecNow(speed)
		if leadSec <= 0 or speed <= 3 then
			return base
		end
		local lead = vel * leadSec
		-- never further than three part-sizes, nor than the target can actually travel in one-way ping + 50 ms
		local cap = math.min(math.max(part.Size.Magnitude, 1) * 3, speed * ((S.pingMs or 0) / 2000 + 0.05))
		if lead.Magnitude > cap then
			lead = if cap > 0 then lead.Unit * cap else Vector3.zero
		end
		return base + lead
	end
	function Combat.leadBestArm(): number
		local L = S.lead
		local bestI, bestScore = 1, -1
		for i, a in ipairs(L.arms) do
			-- Laplace-smoothed hit rate, seeded toward the persisted value on a fresh session
			local prior = 0
			if cfg.leadLearnedMs >= 0 and math.abs(Combat.LEAD_ARMS[i] * 1000 - cfg.leadLearnedMs) < 26 then
				prior = 2
			end
			local score = (a.hits + 1 + prior) / (a.n + 2 + prior)
			if score > bestScore then
				bestI, bestScore = i, score
			end
		end
		return bestI
	end
	-- the lead (seconds) for the shot about to leave; remembers which arm it was for the verdict
	function Combat.leadSec(speed: number): number
		local mode = cfg.leadMode
		if mode == "Off" or speed < 3 or speed > Combat.CHEAT_SPEED then
			S.lead.pendingArm = nil -- a warper's shot must not teach the lead learner either
			return 0
		end
		if mode == "Manual" then
			S.lead.pendingArm = nil
			return cfg.leadMs / 1000
		end
		local L = S.lead
		local best = Combat.leadBestArm()
		local pick = best
		-- explore: every 5th moving-target shot goes to the arm with the fewest samples
		L.moving += 1
		if L.moving % 5 == 0 then
			local minN, minI = math.huge, best
			for i, a in ipairs(L.arms) do
				if a.n < minN then
					minN, minI = a.n, i
				end
			end
			if minN < 6 then
				pick = minI
			end
		end
		L.best = best
		L.pendingArm = pick
		L.sec = Combat.LEAD_ARMS[pick]
		return L.sec
	end
	-- verdict for a shot that carried a lead arm
	function Combat.leadLearn(arm: number, speed: number, verdict: string)
		local a = S.lead.arms[arm]
		if not a or speed < 8 then
			return
		end
		if verdict == "NO-REPLY" or verdict == "KILL" then
			return -- rejected / target died first: says nothing about the lead
		end
		a.n += 1
		if verdict == "HIT" then
			a.hits += 1
		end
		local best = Combat.leadBestArm()
		S.lead.best = best
		if S.lead.arms[best].n >= 8 then
			local ms = math.floor(Combat.LEAD_ARMS[best] * 1000 + 0.5)
			if ms ~= cfg.leadLearnedMs then
				cfg.leadLearnedMs = ms
				saveConfigSoon() -- runs from the shot-effect hook: never write the file on the shot thread
				log("INFO", ("lead: moving targets now land best with %d ms (%d/%d hits)"):format(ms, S.lead.arms[best].hits, S.lead.arms[best].n))
			end
		end
	end
	function Combat.leadSummary(): string
		local parts = {}
		for i, a in ipairs(S.lead.arms) do
			table.insert(parts, ("%dms %d/%d%s"):format(math.floor(Combat.LEAD_ARMS[i] * 1000 + 0.5), a.hits, a.n, if i == S.lead.best then "*" else ""))
		end
		return table.concat(parts, " · ")
	end

	-- Dynamic hitbox: with a spread weapon at range the head is a coin flip while the body hitbox
	-- (3.5 × 4 studs) is a near-certain hit — pick whichever has the higher expected damage
	-- (chance × damage, crit for the head). No spread → the head, always. A target crossing fast
	-- (angular speed > ~0.8 rad/s from the muzzle) also gets the body: the lead can be off by a
	-- head's width and still land on the 2.4 × 3 body.
	-- hit probability of a part from `origin` for a shot with `spread` degrees of cone: the part's
	-- subtended half-angle over the spread, squared (area), clamped to 1
	function Combat.hitProb(p: BasePart, origin: Vector3, spread: number): number
		local d = (p.Position - origin).Magnitude
		if d < 0.5 then
			return 1
		end
		local sz = p.Size
		local r = math.min(sz.X, sz.Y, sz.Z) * 0.5
		local sub = math.deg(math.atan(r / d))
		return math.clamp((sub / spread) ^ 2, 0, 1)
	end
	function Combat.dynamicPart(fighter: any, part: BasePart?, from: Vector3?): BasePart?
		S.dynamicBody = false -- every early return used to leave the HUD note stale
		if not (cfg.dynamicHitbox and part and part.Parent) then
			return part
		end
		local isHead = part.Name:find("Head", 1, true) ~= nil
		if not isHead then
			return part
		end
		local body = Game.hitboxPart(fighter, "Body")
		if not body or body == part then
			return part
		end
		local _, model = Game.fighterBody(fighter)
		-- `from` stays nil for the LOS asks below so they hit the per-frame memo (an explicit origin
		-- disables it and cost one extra raycast per frame)
		local origin = from or Game.shotOriginPos()
		if not origin then
			return part
		end
		local gs = S.gameState
		local info = gs and gs.item and gs.item.Info
		local oneShotHead = type(info) == "table" and info.AimScopePercent ~= nil -- snipers: the head crit is the point
		-- v5.0.5 cheater-aware: a fly / speed cheat (steady > 60 st/s) is a blur for the server too — the
		-- body hitbox is three times the head, take it whatever the gun
		do
			local rootC = Game.fighterBody(fighter)
			if rootC and Resolver.fixVel(rootC).Magnitude > Combat.CHEAT_SPEED then
				S.dynamicBody = true
				return body
			end
		end
		if not oneShotHead then
			local root = Game.fighterBody(fighter)
			local v = if root then Resolver.fixVel(root) else Vector3.zero
			local horiz = Vector3.new(v.X, 0, v.Z).Magnitude
			local d = (part.Position - origin).Magnitude
			-- v5: with the aim claim the server cone is dead and the hit rides on the part — a close head
			-- (angular size above the 1.4° rotation step) is as hittable as the body, so keep the crit
			local claimed = cfg.spreadClaimAim and S.hooks.installed.spreadClaim == true
			if horiz > 8 and horiz / math.max(d, 1) > 0.8 and not (claimed and d < 25) and Game.rayVisible(model, body, from) then
				S.dynamicBody = true
				return body
			end
		end
		local spread = Combat.currentSpreadDeg()
		if spread <= 0.05 then
			return part
		end
		if type(info) ~= "table" then
			return part
		end
		local dmg = tonumber(info.ShootDamage) or 0
		local crit = tonumber(info.CriticalDamage) or dmg * 2
		local headEV = Combat.hitProb(part, origin, spread) * crit
		local bodyEV = Combat.hitProb(body, origin, spread) * dmg
		if bodyEV > headEV * 1.15 and Game.rayVisible(model, body, from) then
			S.dynamicBody = true
			return body
		end
		S.dynamicBody = false
		return part
	end

	-- one place that drops the lock: every field, so the Debug tab and engagedSince never read a
	-- stale part / lock time after the target is gone
	function Combat.clearLock()
		S.silentTarget = nil
		S.silentTargetModel = nil
		S.silentFighter = nil
		S.silentPart = nil
		S.silentAimPoint = nil
		S.silentAimModel = nil
		S.silentDamageParts = nil
		S.lockSince = nil
		S.cfgOverrideSilent = nil
		S.silentLocal = nil
		S.silentLocalPart = nil
		S.silentInCircle = false
		S.targetAway = false
	end
	-- the parts a damage ray may land on: the model's hitboxes, never its riot shield. Stowed on the back
	-- it absorbs a round from behind (~500 HP), and appending the whole model to the Include list let it
	-- win every time. Built here, outside the __namecall hook — h.redirect only reads the list.
	Combat.dmgCache = setmetatable({}, { __mode = "k" })
	function Combat.damageParts(model: Model?, extra: BasePart?): { BasePart }?
		if not model then
			return nil
		end
		local now = os.clock()
		local c = Combat.dmgCache[model]
		if not (c and now - c.at < 0.5 and c.extra == extra) then
			local list = {}
			for _, d in ipairs(model:GetChildren()) do
				if d:IsA("BasePart") and string.find(d.Name, "Hitbox", 1, true) and not Game.isShieldPart(d, model) then
					table.insert(list, d)
				end
			end
			if #list == 0 then
				-- no Hitbox* parts (an odd rig): every queryable part that is not a shield
				for _, d in ipairs(model:GetDescendants()) do
					if d:IsA("BasePart") and d.CanQuery and not Game.isShieldPart(d, model) then
						table.insert(list, d)
					end
				end
			end
			if extra and extra.Parent and not table.find(list, extra) and not Game.isShieldPart(extra, model) then
				table.insert(list, extra)
			end
			c = { at = now, list = list, extra = extra }
			Combat.dmgCache[model] = c
		end
		return c.list
	end
	-- silent lock: autokill drives it; otherwise the silent picker. Dead-target guard drops the lock
	-- the frame the target's health hits 0 (no bursts into a corpse).
	function Combat.updateLock(enemies: { any })
		local active = ak.state ~= "idle" and ak.state ~= "done" and ak.fighter ~= nil
		if active then
			-- autokill stands above the head: the head is the hitbox that is always exposed from there
			local head = Game.hitboxPart(ak.fighter, "Head") or Game.fighterHead(ak.fighter) or Game.fighterBody(ak.fighter)
			local _, model = Game.fighterBody(ak.fighter)
			-- the head is covered (a ledge, their shield, a crate lip) but the body is in the open: shoot the body
			-- instead of sitting on them with the trigger held. Only when Body is one of your hitboxes.
			if head and model then
				local okB, body = pcall(function()
					if Game.rayVisible(model, head) then
						return nil
					end
					local b = Game.hitboxPart(ak.fighter, "Body")
					return if b and Target.boxAllowed(b, "silent", false) and Game.rayVisible(model, b) then b else nil
				end)
				if okB and body then
					head = body
				end
			end
			S.silentTarget = if head then Resolver.fixPos(head) else nil
			S.silentTargetModel = model
			if S.silentFighter ~= ak.fighter then
				S.lockSince = os.clock()
			end
			S.silentFighter = ak.fighter
			S.silentPart = head
			S.silentLocal, S.silentLocalPart = nil, nil
			S.silentInCircle = false
			S.cfgOverrideSilent = S.silentTarget ~= nil or nil
		elseif cfg.silentAim and not S.menuOpen then
			-- a blade only reaches the nearest enemy: melee locks by distance whatever the priority
			local prio = if Game.weaponProfile().melee then "Closest" else cfg.targetPriority
			local pick = Target.pick(enemies, Target.silentRadius(), prio, "silent")
			local part = pick and pick.part or nil
			local pos = pick and pick.pos or nil
			local lpt = pick and pick.localPoint or nil
			if pick and part then
				-- spread weapon at range: the body may be worth more than a head coin flip
				local dp = Combat.dynamicPart(pick.fighter, part)
				if dp and dp ~= part and not Target.boxAllowed(dp, "silent", pick.inCircle) then
					dp = part -- the body is not one of your hitboxes: the head stays
					S.dynamicBody = false
				end
				if dp and dp ~= part then
					if pick.inCircle then
						-- semi-legit: the body swap only when the body has a point in the circle too
						local cam = workspace.CurrentCamera
						local r = Target.silentRadius()
						local d2, lq = nil, nil
						if cam then
							local c = cam.ViewportSize / 2
							d2, lq = Target.boxPoint(dp, cam:ViewportPointToRay(c.X, c.Y), c, r * r)
						end
						if d2 then
							part, lpt = dp, lq
							pos = if lq then dp.CFrame:PointToWorldSpace(lq) else dp.Position
						end
					else
						part, pos = dp, dp.Position
					end
				end
			end
			-- the point on the part the round must land on (object space), read at shot time by h.silentWanted
			S.silentLocal = if pick and pick.inCircle then lpt else nil
			S.silentLocalPart = if S.silentLocal then part else nil
			S.silentInCircle = pick ~= nil and pick.inCircle == true
			S.silentTarget = pos
			S.silentTargetModel = pick and pick.model or nil
			local newF = pick and pick.fighter or nil
			if newF ~= S.silentFighter then
				S.lockSince = if newF then os.clock() else nil
			end
			S.silentFighter = newF
			S.silentPart = part
			S.cfgOverrideSilent = nil
		else
			Combat.clearLock()
		end
		if cfg.deadTargetGuard and S.silentFighter and Target.isDead(S.silentFighter) then
			Combat.clearLock()
		end
		if S.silentTargetModel and S.silentTarget then
			local part = S.silentPart
			if not (part and part.Parent) then
				part = S.silentTargetModel:FindFirstChild("Head") or S.silentTargetModel:FindFirstChild("HumanoidRootPart")
			end
			-- server-consistent LOS from where the shot really leaves (Game.rayVisible → shot origin)
			S.targetVisible = part ~= nil and Game.rayVisible(S.silentTargetModel, part :: BasePart)
			local ridingUnder = part ~= nil and Combat.ridingUnder(S.silentTargetModel)
			if ridingUnder then
				S.targetVisible = true
			end
			S.headBlockedHold = not ridingUnder and Game.headHold(S.silentTargetModel)
			S.targetImmune = S.silentFighter ~= nil and Game.fighterImmune(S.silentFighter)
			S.silentDamageParts = Combat.damageParts(S.silentTargetModel, S.silentPart)
			S.silentDamageModel = S.silentTargetModel
			-- aim point: the live part whenever the server ray can reach it; otherwise a position a
			-- ShootEffect confirmed on this fighter a moment ago (a desync / fake position) — never a
			-- rewound track point (a delayed aim landed short)
			S.silentAimPoint, S.silentAimModel = nil, nil
			-- v6.6 wallbang without a teleport: the round's claimed origin moves along the line to the target to
			-- just past the wall in front of us (Combat.wallPushPoint) — the rotation is unchanged, and a ray that
			-- starts inside or behind a wall ignores it
			S.wallPushOrigin, S.wallPushModel = nil, nil
			S.wallPushUnder = false
			if not S.targetVisible and part then
				-- an enemy parked inside the floor under us hits us (their ray starts inside the slab and
				-- ignores it) while ours stops on its top face: start ours inside the slab too. Also while
				-- relocated: magic, autokill and the melee ragebot stand on the slab over them for this
				local under = Combat.underDesync(S.silentTargetModel)
				if under or (cfg.silentWallbang and not S.teleported) then
					local po = Combat.wallPushPoint(S.silentTargetModel, part :: BasePart, if under then Combat.underPushLimit() else nil)
					if not po and under then
						po = Combat.floorPushPoint(S.silentTargetModel, part :: BasePart, Combat.underPushLimit())
							or Combat.floorPushPoint(S.silentTargetModel, part :: BasePart, Combat.underPushLimit(), true)
					end
					if po then
						S.wallPushOrigin, S.wallPushModel = po, S.silentTargetModel
						S.wallPushUnder = under
						S.targetVisible = true
					end
				end
			end
			-- anti-shield: the part is covered by their Riot Shield (not a wall): aim at whatever sticks out past it
			S.shieldFlank = false
			if not S.targetVisible and part and cfg.shieldAware and S.silentFighter and not S.cfgOverrideSilent then
				-- its own pcall: a failure here falls back to the plain lock instead of taking silent aim down with it
				local okS, p2, lq = pcall(function()
					local from = Game.shotOriginPos()
					local blk = from and S.bounds.blocker(from, S.silentTargetModel, part :: BasePart)
					if blk and Game.isShieldPart(blk, S.silentTargetModel) then
						return Combat.shieldPoint(S.silentFighter, S.silentTargetModel, S.silentInCircle == true)
					end
					return nil, nil
				end)
				if okS and typeof(p2) == "Instance" and typeof(lq) == "Vector3" then
					S.silentPart = p2
					S.silentLocal, S.silentLocalPart = lq, p2
					S.silentTarget = p2.CFrame:PointToWorldSpace(lq)
					S.targetVisible = true
					S.shieldFlank = true
					part = p2
				elseif not okS and S.hookErr then
					S.hookErr("anti-shield", p2)
				end
			end
			if not S.targetVisible and part then
				local conf = Resolver.confirmed[S.silentTargetModel]
				-- with the circle: only a hit on the same box as the lock, at a point inside the circle. Without it
				-- (rage / 360°): any of your hitboxes, and anything for autokill (it owns the lock)
				local boxOk, inCircle = false, true
				if conf and S.silentInCircle then
					boxOk = Target.boxOf(conf.part) == Target.boxOf(part)
					inCircle = Target.pointInCircle(conf.pos, Target.silentRadius())
				elseif conf then
					boxOk = S.cfgOverrideSilent == true or Target.boxAllowed(conf.part, "silent", false)
				end
				if conf and boxOk and inCircle and os.clock() - conf.at < 0.8 and (conf.pos - (part :: BasePart).Position).Magnitude < 8 and Combat.pointVisible(S.silentTargetModel, conf.pos) then
					-- the point belongs to this model: a lock that moves on (or a fake lock) never aims at it
					S.silentAimPoint, S.silentAimModel = conf.pos, S.silentTargetModel
					S.silentTarget = conf.pos
					S.targetVisible = true
				end
			end
			-- warped away past the backtrack's hold: the server has them out there, and a ray toward a point 1e9 st
			-- off reads clear — every round of the duel log fired at one went AIR
			S.targetAway = Resolver.away(S.silentTargetModel)
			if S.targetAway then
				S.targetVisible = false
				S.silentAimPoint, S.silentAimModel = nil, nil
				S.wallPushOrigin, S.wallPushModel, S.wallPushUnder = nil, nil, false
			end
		else
			S.targetVisible = false
			S.targetAway = false
			S.headBlockedHold = false
			S.targetImmune = false
			S.silentAimPoint, S.silentAimModel = nil, nil
			S.wallPushOrigin, S.wallPushModel = nil, nil
		end
		-- rage with a dry gun: drop the lock so origin / body stop chasing a fight we cannot win
		if cfg.rageEnabled and S.silentFighter then
			local gs = S.gameState
			local prof = Game.weaponProfile()
			if prof.gun and gs and gs.ammo == 0 and (gs.reserve or 0) <= 0 then
				local dry = true
				if cfg.autoSwitchEmpty then
					local lf = Game.localFighter()
					if lf and type(lf.Items) == "table" then
						for _, other in pairs(lf.Items) do
							if other ~= gs.item and type(other) == "table" and type(other.Info) == "table" and other.Info.Type == "Gun" then
								local a = Game.itemAmmo(other)
								if a ~= nil and a > 0 then
									dry = false
									break
								end
							end
						end
					end
				end
				if dry then
					Combat.clearLock()
					S.holdReason = "no ammo"
				end
			end
		end
	end
	-- the farthest the claimed origin may move ahead of the head: the slider, lowered by the server's answers
	-- (Combat.wallPushLearn) for this session
	Combat.wallPush = { max = nil, underMax = nil, ok = 0, bad = 0, fails = 0, warned = false, underHits = 0 }
	function Combat.wallPushLimit(): number
		local W = Combat.wallPush
		return math.min(W.max or cfg.silentWallbangDist, cfg.silentWallbangDist)
	end
	function Combat.underPushLimit(): number
		local W = Combat.wallPush
		-- a refusal can be the target moving mid-flight, not the server's limit: forget it after 20 s
		if W.underMax and os.clock() - (W.underAt or 0) > 20 then
			W.underMax = nil
		end
		return math.min(W.underMax or cfg.antiUnderDist, cfg.antiUnderDist)
	end
	-- where to stand to shoot someone buried in the floor (Bounds.buriedTop): on the slab right over them,
	-- a step toward `from`. The lock's floor push then starts the round ~5.5 st down, inside the slab
	function Combat.buriedStand(target: Vector3, top: number, from: Vector3?): Vector3
		local side = if from then (from - target) * Vector3.new(1, 0, 1) else Vector3.zero
		side = if side.Magnitude > 0.1 then side.Unit else Vector3.new(0, 0, 1)
		return Vector3.new(target.X, top + 3, target.Z) + side * 0.8
	end
	function Combat.underDesync(model: Model?): boolean
		return S.bounds.underDesync(model)
	end
	-- the body holds an Under spot (autokill Under, voidspam's way back) right below this lock: the server takes
	-- those rounds (range: 36 HIT / 5 NO-REPLY) while our own ray out of the slab often reads blocked by the
	-- floor's overlapping parts
	function Combat.ridingUnder(model: Model?): boolean
		local B = Combat.body
		local D = Combat.def
		local kind = if B.owner == "autokill" then ak.desyncKind elseif B.owner == "defense" and D and D.state == "under" then D.kind else nil
		if kind ~= "under" or model == nil or model ~= S.silentTargetModel then
			return false
		end
		local me = S.myRootPart
		local root = model:FindFirstChild("HumanoidRootPart")
		if not (me and me.Parent and root and root:IsA("BasePart")) then
			return false
		end
		local d = root.Position - me.Position
		return d.Y > 2 and d.Y < 12 and d.X * d.X + d.Z * d.Z < 16
	end
	-- worth taking the body to: never away, and on the map for ENGAGE_DWELL s without a break. A warper surfaces
	-- for a frame to shoot and is gone before any body gets there (duel log, 2026-09-27: autokill snapped in on one
	-- five times in two minutes and died each time, waiting next to a spot nobody was on)
	Combat.ENGAGE_DWELL = 0.25
	function Combat.engageable(model: Model?): boolean
		if model == nil then
			return true
		end
		return not Resolver.away(model) and Resolver.presentFor(model) >= Combat.ENGAGE_DWELL
	end
	-- an enemy parked inside the floor under us (their Under desync): their rounds come up through the slab, ours
	-- only reach them through the lock's floor push
	function Combat.underThreat(list: { any }?): any
		if cfg.antiUnder == false or type(list) ~= "table" then
			return nil
		end
		for _, f in ipairs(list) do
			local _, m = Game.fighterBody(f)
			if m and not Target.isDead(f) and S.bounds.underDesync(m) then
				return f
			end
		end
		return nil
	end
	-- a point on the line to `part`, 0.6 st past the first wall in front of us (inside it, or behind a thin
	-- one), when that wall is within the limit and the server's ray reaches the part from there
	function Combat.wallPushPoint(model: Model, part: BasePart, limitOverride: number?): Vector3?
		local from = Game.shotOriginPos()
		local params = Game.losParams()
		if not (from and params) then
			return nil
		end
		local rel = part.Position - from
		local dist = rel.Magnitude
		if dist < 2 then
			return nil
		end
		local dir = rel / dist
		local limit = limitOverride or Combat.wallPushLimit()
		local hit = workspace:Raycast(from, dir * math.min(limit, dist), params)
		if not hit or hit.Instance:IsDescendantOf(model) then
			return nil
		end
		local push = (hit.Position - from).Magnitude + 0.6
		if push > limit or push >= dist then
			return nil
		end
		local p = from + dir * push
		return if Game.rayVisible(model, part, p) then p else nil
	end
	-- 0.6 st into the floor straight under the head: from inside the slab the ray ignores it. `trust` skips our
	-- own line check from there: the server takes rounds our client ray calls blocked (overlapping floor parts)
	function Combat.floorPushPoint(model: Model, part: BasePart, limit: number, trust: boolean?): Vector3?
		local from = Game.shotOriginPos()
		local params = Game.losParams()
		if not (from and params) then
			return nil
		end
		local hit = workspace:Raycast(from, Vector3.new(0, -limit, 0), params)
		if not hit or hit.Instance:IsDescendantOf(model) then
			return nil
		end
		local p = hit.Position - Vector3.new(0, 0.6, 0)
		if (p - from).Magnitude > limit then
			return nil
		end
		return if trust or Game.rayVisible(model, part, p) then p else nil
	end
	-- a pushed round the server answered: HIT keeps the limit, WALL / NO-REPLY lowers it under that push
	function Combat.wallPushLearn(verdict: string, pushed: number)
		local W = Combat.wallPush
		if S.wallPushUnder then
			if verdict == "HIT" then
				W.underHits += 1
			elseif verdict == "WALL" or verdict == "NO-REPLY" then
				W.underMax = math.max(2, math.min(Combat.underPushLimit(), pushed) - 0.75)
				W.underAt = os.clock()
			end
			return
		end
		if verdict == "HIT" then
			W.ok += 1
			W.fails = 0
		elseif verdict == "WALL" or verdict == "NO-REPLY" then
			W.bad += 1
			W.fails += 1
			W.max = math.max(1, math.min(Combat.wallPushLimit(), pushed) - 0.75)
			if W.fails >= 6 and not W.warned then
				W.warned = true
				log("INFO", ("[wallbang] the server keeps refusing moved rounds here — limit now %.1f st"):format(W.max))
			end
		end
	end
	-- a clear server-whitelist line from where the shot leaves to a point (the target's own parts count as clear)
	function Combat.pointVisible(model: Model, pos: Vector3): boolean
		local from = Game.shotOriginPos()
		local params = Game.losParams()
		if not (from and params) then
			return false
		end
		local hit = workspace:Raycast(from, pos - from, params)
		if hit == nil then
			return true
		end
		-- their Riot Shield sits inside their model and absorbs the round: a ray that ends on it is cover
		if cfg.shieldAware and Game.isShieldPart(hit.Instance, model) then
			return false
		end
		return hit.Instance:IsDescendantOf(model)
	end
	-- anti-shield: a Riot Shield covers most of the body from the front (or the back when stowed), but the top
	-- of the head, a shoulder or the feet usually stick out. Points near the edges of each allowed hitbox are
	-- probed from the shot origin; the first with a clear line wins. Throttled per model (a handful of rays).
	Combat.SHIELD_PROBES = {
		Head = { Vector3.new(0, 0.42, 0), Vector3.new(0.42, 0.2, 0), Vector3.new(-0.42, 0.2, 0), Vector3.new(0, 0.2, 0.42), Vector3.new(0, 0.2, -0.42) },
		Body = { Vector3.new(0.42, 0.4, 0), Vector3.new(-0.42, 0.4, 0), Vector3.new(0, -0.42, 0), Vector3.new(0.42, -0.3, 0), Vector3.new(-0.42, -0.3, 0), Vector3.new(0, 0.42, 0) },
	}
	Combat.shieldCache = setmetatable({}, { __mode = "k" })
	function Combat.shieldPoint(fighter: any, model: Model, inCircle: boolean): (BasePart?, Vector3?)
		local now = os.clock()
		local c = Combat.shieldCache[model]
		if c and now - c.at < 0.06 then
			return c.part, c.lq
		end
		local bestPart, bestLq = nil, nil
		-- the preferred box first, then the other
		local order = if cfg.silentPrefer == "Head" then { "Head", "Body" } else { "Body", "Head" }
		for _, box in ipairs(order) do
			local p = Game.hitboxPart(fighter, box)
			if p and p.Parent and Target.boxAllowed(p, "silent", inCircle) then
				local half = p.Size
				for _, k in ipairs(Combat.SHIELD_PROBES[box]) do
					local lq = Vector3.new(half.X * k.X, half.Y * k.Y, half.Z * k.Z)
					local world = p.CFrame:PointToWorldSpace(lq)
					if (not inCircle or Target.pointInCircle(world, Target.silentRadius())) and Combat.pointVisible(model, world) then
						bestPart, bestLq = p, lq
						break
					end
				end
			end
			if bestPart then
				break
			end
		end
		Combat.shieldCache[model] = { at = now, part = bestPart, lq = bestLq }
		return bestPart, bestLq
	end

	-- Magic bullet origin: lowest point above the target with a clear line to it, so short-range
	-- weapons keep their damage (falloff) while still avoiding every obstacle.
	local clearParams = RaycastParams.new()
	clearParams.FilterType = Enum.RaycastFilterType.Exclude
	clearParams.IgnoreWater = true
	local HEIGHT_STEPS = { 3, 6, 10, 16, 24, 36, 55 }
	-- lateral probe offsets as (side, perp) multipliers — one static table instead of a fresh
	-- Vector3 list per call (magicOrigin runs every frame while magic is active)
	Combat.MAGIC_OFFS_MANUAL = { { 0, 0 }, { 1, 0 }, { 0, 1 }, { 0, -1 }, { -1, 0 }, { 2, 0 }, { -2, 0 } }
	Combat.MAGIC_OFFS_AUTO = { { 0, 0 }, { 1, 0 }, { 0, 1 }, { 0, -1 }, { -1, 0 } }
	Combat.clearFilter = {}
	Combat.clearFilterModel, Combat.clearFilterChar = nil, nil
	-- exclude the target model and our own character; reassigned only when either changes
	function Combat.setClearFilter(model: Model?)
		local char = LP.Character
		if Combat.clearFilterModel == model and Combat.clearFilterChar == char then
			return
		end
		Combat.clearFilterModel, Combat.clearFilterChar = model, char
		local filter = Combat.clearFilter
		table.clear(filter)
		if model then
			table.insert(filter, model)
		end
		if char then
			table.insert(filter, char)
		end
		clearParams.FilterDescendantsInstances = filter
	end
	function Combat.clearTo(origin: Vector3, target: Vector3): boolean
		return workspace:Raycast(origin, target - origin, clearParams) == nil
	end

	-----------------------------------------------------------------------------
	-- §7 origin planner (v5) — one shared answer to "where do we shoot the locked hitbox from".
	-- Every rage relocation (magic bullet, autokill Origin mode, backstab, peek) asks Combat.origin.plan.
	-- It scores candidate origins by: the server can see the part from there (its own Include ray),
	-- the spread cone is geometrically dead at that distance (d < h / tan θ), the point is not an
	-- OutOfBoundsPart death (Bounds), and it barely moves from where we already are (no flicker).
	-- Candidates: keep-spot, close ring (wall / pocket huggers — noclip puts us on the part's side of
	-- the wall), a mid ring, above steps (open targets), and below (void hiders under the map).
	-----------------------------------------------------------------------------
	do -- block-scoped (200-register cap): reachable as Combat.origin
	local Origin: any = { scratch = {}, last = setmetatable({}, { __mode = "k" }) }
	Combat.origin = Origin
	Origin.RING_DIRS = {}
	for i = 0, 7 do
		local a = i * (math.pi / 4)
		table.insert(Origin.RING_DIRS, Vector3.new(math.cos(a), 0, math.sin(a)))
	end
	-- worst spread deviation at distance d is d*tan(theta); an origin closer than partHalf/tan(theta)
	-- cannot miss even with the raw cone. Zero cone (aim claim) → any distance is immune.
	function Origin.spreadImmuneDist(part: BasePart?): number
		local gs = S.gameState
		local item = gs and gs.item
		local info = type(item) == "table" and item.Info
		-- the SMALLEST half-extent is the one the cone has to stay inside
		local half = if part then math.min(part.Size.X, part.Size.Y, part.Size.Z) * 0.5 else 0.5
		if type(info) ~= "table" then
			return cfg.originMaxDist
		end
		-- the server's cone comes from the ORIGINAL stats (no-spread zeroes the client copy) times the
		-- aim multiplier the claim hands it; the rotation channel's 1.4° quantisation adds its own
		-- half-step error on top (quantAware)
		local orig = (S.statOriginals and S.statOriginals[tostring(item.Name)]) or {}
		local deg = tonumber(orig.ShootSpread) or tonumber(info.ShootSpread) or 0
		local aimMul = tonumber(orig.AimSpreadMultiplier) or tonumber(info.AimSpreadMultiplier) or 1
		if (cfg.spreadClaimAim and S.hooks.installed.spreadClaim and S.spreadModeFor(item) == "claim") or (gs and gs.aiming) then
			deg *= aimMul
		end
		if cfg.quantAware then
			deg += 0.8
		end
		if deg <= 0.01 then
			return math.huge
		end
		local t = math.tan(math.rad(deg))
		return if t > 1e-4 then math.max(half / t, 4) else math.huge
	end
	-- can the SERVER's ray reach `part` from `origin`? (its Include whitelist + enemy models).
	-- A model-less clear check falls back to the exclude ray.
	function Origin.serverSees(origin: Vector3, model: Model?, part: BasePart?, target: Vector3): boolean
		if part and part.Parent then
			return Game.rayVisible(model, part, origin)
		end
		Combat.setClearFilter(model)
		return Combat.clearTo(origin, target)
	end
	-- enemies other than the target with a gun out who could shoot a spot while we stand on it (legit
	-- players picked the autokill shooter off, worst in 5v5): the 3 nearest heads, collected once per frame
	Origin.watchers, Origin.watchFrame, Origin.watchModel = {}, -1, nil
	Origin.watchCands = {}
	function Origin.watchersFor(model: Model?): { Vector3 }
		if Origin.watchFrame == Game.frameId and Origin.watchModel == model then
			return Origin.watchers
		end
		Origin.watchFrame, Origin.watchModel = Game.frameId, model
		local out, cands = Origin.watchers, Origin.watchCands
		table.clear(out)
		table.clear(cands)
		local me = Game.myRoot()
		if not me then
			return out
		end
		for _, f in ipairs(Game.targets()) do
			if not f.IsBot then
				local root, m = Game.fighterBody(f)
				if root and m ~= model and not Target.isDead(f) then
					local eq = Game.enemyEquipped(f)
					local info = type(eq) == "table" and eq.Info
					local eh = Game.fighterHead(f)
					local d = (root.Position - me.Position).Magnitude
					if eh and type(info) == "table" and info.Type == "Gun" and d <= 250 then
						table.insert(cands, { pos = eh.Position, d = d })
					end
				end
			end
		end
		table.sort(cands, function(a, b)
			return a.d < b.d
		end)
		for i = 1, math.min(3, #cands) do
			out[i] = cands[i].pos
		end
		return out
	end
	-- v6.4 blades out (reach + dash + what our ping lets them close + the margin), once per frame. A shooting
	-- spot inside one of these is where the dodge used to take the body off the ragebot every 1.5 s
	Origin.bladePos, Origin.bladeR, Origin.bladeModel, Origin.bladeFrame = {}, {}, {}, -1
	function Origin.bladesNow(): number
		if Origin.bladeFrame == Game.frameId then
			return #Origin.bladePos
		end
		Origin.bladeFrame = Game.frameId
		local P, R, M = Origin.bladePos, Origin.bladeR, Origin.bladeModel
		table.clear(P)
		table.clear(R)
		table.clear(M)
		for _, f in ipairs(Game.targets()) do
			local item = Game.fighterMeleeOut(f)
			local root, m = nil, nil
			if item then
				root, m = Game.fighterBody(f)
			end
			if root and not Target.isDead(f) then
				local n = #P + 1
				P[n], R[n], M[n] = root.Position, math.min((Combat.meleeThreatRadius(item, root)), 30), m or false
			end
		end
		return #P
	end
	function Origin.bladePenalty(origin: Vector3): number
		local P, R = Origin.bladePos, Origin.bladeR
		local s = 0
		for i = 1, #P do
			local d = (origin - P[i]).Magnitude
			if d < R[i] then
				s += (R[i] - d) * 3
			end
		end
		return s
	end
	-- how many of those watchers have a clear line to a head standing at `origin`
	function Origin.exposure(origin: Vector3, model: Model?): number
		local w = Origin.watchersFor(model)
		if #w == 0 then
			return 0
		end
		local params = Game.losParams()
		if not params then
			return 0
		end
		local head = origin + Vector3.new(0, 1.85, 0)
		local char = LP.Character
		local n = 0
		for _, from in ipairs(w) do
			local hit = workspace:Raycast(from, head - from, params)
			if hit == nil or (char ~= nil and hit.Instance:IsDescendantOf(char)) then
				n += 1
			end
		end
		return n
	end
	-- the whole planner. Returns an origin Vector3. `opts.holdSec` sizes the OOB budget check;
	-- `opts.noclip` allows origins inside geometry / below the map (the caller must hold noclip).
	function Origin.plan(target: Vector3, model: Model?, part: BasePart?, opts: any?): Vector3
		opts = opts or Origin.scratch
		local holdSec = opts.holdSec or 0.4
		local allowNoclip = opts.noclip ~= false and (cfg.noclip or cfg.noclipRage)
		-- a shotgun's pellets spread and fall off with distance: its origin stays close
		local maxDist = if Game.weaponProfile().class == "shotgun" then math.min(cfg.originMaxDist, 7) else cfg.originMaxDist
		local gunScale = Combat.gun and Combat.gun.range[Game.weaponProfile().name]
		if gunScale then
			maxDist = math.max(4, maxDist * gunScale)
		end
		local immune = Origin.spreadImmuneDist(part)
		-- ideal shooting distance: close enough that the cone is dead, never point-blank inside them
		local ideal = math.clamp(math.min(maxDist, immune), 3.5, maxDist)
		-- a target with a blade out: shoot from outside its reach (as far as the gun allows), no pocket ring
		local bladeKeep: number? = nil
		if Origin.bladesNow() > 0 and model ~= nil then
			for i, m in ipairs(Origin.bladeModel) do
				if m == model then
					local bk = Origin.bladeR[i]
					if bk then
						bladeKeep = bk
						ideal = math.max(ideal, math.min(bk, maxDist))
					end
					break
				end
			end
		end
		local cam = workspace.CurrentCamera
		local camPos = cam and cam.CFrame.Position or target
		local B = S.bounds
		local belowMap = B.underMap(target, model)
		-- anti-escalation: heights count from the ground under the target, never from the target — a
		-- lifted enemy (another cheater's magic spot) must not pull our spot up after theirs
		local groundT = S.safe.groundY(target)
		local topY = if groundT then groundT + cfg.safeMaxHeight else math.huge
		-- both buried under the map: cap height so two cheaters cannot ratchet each other skyward
		local char = LP.Character
		if belowMap and groundT and char and model and B.underDesync(char) and B.underDesync(model) then
			topY = math.min(topY, groundT + 6)
		end
		local lifted = groundT ~= nil and target.Y - groundT > 8
		local skipExposure = false -- the sticky check reads the 10 Hz cached exposure instead
		local function score(origin: Vector3): number?
			if (origin - target).Magnitude < 1.5 or origin.Y > topY then
				return nil
			end
			local okB = B.allows(origin, holdSec)
			if not okB then
				return nil
			end
			local buried = B.inGeometry(origin, 1)
			if buried and not allowNoclip then
				return nil
			end
			if not Origin.serverSees(origin, model, part, target) then
				return nil
			end
			local d = (origin - target).Magnitude
			local s = math.abs(d - ideal) -- prefer the spread-immune distance
			if d > immune then
				s += (d - immune) * 2 -- past the immune distance the cone can miss: penalise hard
			end
			if buried then
				-- inside a wall: a ray that STARTS inside a part ignores it (our shot exits), a ray from
				-- outside hits its face (their shot does not reach us) — with noclip that is the safest
				-- origin there is, so cover is a bonus, not a penalty (originPreferCover)
				s += if cfg.originPreferCover then -8 else 6
			end
			-- stickiness: keep close to where we already shoot from — an offset RELATIVE to the target,
			-- so the spot walks with them (an absolute spot let a target stroll 30 st away)
			local prevOff = Origin.last[model]
			if prevOff then
				s += (origin - (target + prevOff)).Magnitude * 0.15
			end
			if not skipExposure then
				s += Origin.exposure(origin, model) * 6
			end
			return s + Origin.bladePenalty(origin)
		end
		local best, bestS = nil, math.huge
		local function consider(origin: Vector3)
			local s = score(origin)
			if s and s < bestS then
				bestS, best = s, origin
			end
		end
		-- 1. keep the spot we already use, carried along with the target, while it still scores
		if cfg.originStick then
			local prevOff = Origin.last[model]
			if prevOff then
				local prev = target + prevOff
				-- a spot another enemy can see is re-planned (at most every 0.5 s: the full search is costly);
				-- its exposure is re-measured at 10 Hz, not every frame
				local ec = Origin.expCache
				if not ec or ec.model ~= model or os.clock() - ec.at > 0.1 then
					ec = { model = model, at = os.clock(), n = Origin.exposure(prev, model) }
					Origin.expCache = ec
				end
				skipExposure = true
				local prevOk = score(prev) ~= nil and Origin.bladePenalty(prev) == 0
				skipExposure = false
				if prevOk and (ec.n == 0 or os.clock() - (Origin.replanAt or 0) < 0.5) then
					return prev
				end
				Origin.replanAt = os.clock()
			end
		end
		local side = (camPos - target) * Vector3.new(1, 0, 1)
		side = if side.Magnitude > 1 then side.Unit else Vector3.new(0, 0, -1)
		local perp = Vector3.new(-side.Z, 0, side.X)
		-- 1b. v6.4 an enemy hiding INSIDE a wall (noclip): every ray from outside stops on the wall face; only a
		-- ray that starts inside the same part ignores it. Spots inside that geometry right around them.
		if allowNoclip and B.inGeometry(target, 0.9) then
			-- the body is pivoted by its root; the round leaves from the head ~1.85 st above it, so the head
			-- goes level with theirs and both have to sit inside the geometry
			local up = Vector3.new(0, 1.85, 0)
			for _, r in ipairs({ 2, 3.5 }) do
				for _, dir in ipairs(Origin.RING_DIRS) do
					local p = target + dir * r - up
					if B.inGeometry(p + up, 0.9) and B.inGeometry(p, 0.9) then
						consider(p)
					end
				end
			end
			if best then
				if model ~= nil then
					Origin.last[model] = best - target
				end
				return best
			end
		end
		-- 1c. the under desync without noclip: they sit inside the floor, so no spot above it sees them. Stand
		-- on the slab over them; the lock (Combat.updateLock) starts the round inside the slab from there
		if model ~= nil then
			local top = B.buriedTop(model)
			if top then
				local stand = Combat.buriedStand(target, top, camPos)
				if B.allows(stand, holdSec) then
					Origin.last[model] = stand - target
					return stand
				end
			end
		end
		-- 2. cover origins first (noclip): walls around the target within the ideal distance — a spot
		-- 1.5 st INSIDE the wall face that looks at them. The server ray from inside the part reaches
		-- them, theirs hit the face and cannot reach us.
		if allowNoclip and cfg.originPreferCover then
			local params = Game.losParams()
			if params then
				local eye = target + Vector3.new(0, 1.5, 0)
				for _, dir in ipairs(Origin.RING_DIRS) do
					local hit = workspace:Raycast(eye, dir * ideal, params)
					if hit and not (model and (hit.Instance == model or hit.Instance:IsDescendantOf(model))) then
						local d = (hit.Position - eye).Magnitude
						if d >= 2.5 then
							local inside = hit.Position + dir * 1.5
							if B.inGeometry(inside, 0.9) then
								consider(inside)
							end
						end
					end
				end
			end
		end
		-- 3. low lateral spots: rings at the ideal and a close pocket distance around them, camera side
		-- first. For a lifted target the ring sits at the top of the band under them — we shoot up at
		-- them instead of following them up
		if not best then
			local ringUp = math.min(1.5, topY - 1 - target.Y)
			for _, ringR in ipairs({ ideal, if bladeKeep then ideal else math.min(4.5, ideal) }) do
				consider(target + side * ringR + Vector3.new(0, ringUp, 0))
				for _, dir in ipairs(Origin.RING_DIRS) do
					consider(target + dir * ringR + Vector3.new(0, ringUp, 0))
					if best and bestS < 1.5 then
						break
					end
				end
				if best and bestS < 2 then
					break
				end
			end
		end
		-- 4. the height band: above the target (out of their view), lowest clear step wins — never
		-- above a lifted target (that is how two cheaters stack each other into the sky)
		if not best and not belowMap and not lifted then
			for _, h in ipairs(HEIGHT_STEPS) do
				if h > cfg.magicHeight or target.Y + h > topY then
					break
				end
				local lateral = math.min(h * 0.6, 8)
				for _, c in ipairs(Combat.MAGIC_OFFS_AUTO) do
					consider(target + Vector3.new(0, h, 0) + side * (c[1] * lateral) + perp * (c[2] * lateral))
				end
				if best then
					break
				end
			end
		end
		-- 5. below the map for a void hider (open air under the floor), noclip only
		if not best and belowMap and allowNoclip and cfg.originBelowMap then
			for _, dy in ipairs({ 4, 8, 14 }) do
				consider(target + Vector3.new(0, -dy, 0))
				consider(target + side * ideal + Vector3.new(0, -dy, 0))
			end
		end
		if not best then
			-- nothing clean: closest immune-distance point on the camera side (noclip will seat it)
			best = target + side * ideal + Vector3.new(0, 1.5, 0)
		end
		if model ~= nil then
			-- relative offset (a nil key — model-less lock — would throw), capped: a sticky spot that rose
			-- with a rising target is how the height ran away between two magic users
			local off = best - target
			local capY = cfg.safeMaxHeight * 0.5
			if off.Y > capY then
				off = Vector3.new(off.X, capY, off.Z)
			end
			if off.Magnitude > 30 then
				off = off.Unit * 30
			end
			Origin.last[model] = off
		end
		return best
	end
	end -- Origin block

	-- v5.2: CFrame.lookAt with coincident points (or a NaN somewhere upstream) yields a NaN basis —
	-- PivotTo then parks the body "nowhere" (stuck under the map until the next hop). Every relocation
	-- goes through this: degenerate → a plain translation, straight up / down → a safe up vector.
	function Combat.lookAtSafe(from: Vector3, to: Vector3): CFrame
		local d = to - from
		if d ~= d or d.Magnitude < 1e-3 or from ~= from then
			return CFrame.new(from)
		end
		if math.abs(d.Unit.Y) > 0.999 then
			return CFrame.lookAt(from, to, Vector3.new(0, 0, -1))
		end
		return CFrame.lookAt(from, to)
	end
	-- one teleport primitive for every relocation: engage noclip for the hold, pivot the body to face
	-- the aim, kill velocity so the server sees a still shooter, mark the settle. Returns the CFrame used.
	function Combat.relocate(origin: Vector3, aim: Vector3, opts: any?): CFrame
		if S.featuresPaused and not S.gateOverride then
			-- the lobby gate: no teleport outside a live duel
			local charP = LP.Character
			return if charP then charP:GetPivot() else CFrame.new(origin)
		end
		opts = opts or Combat.origin.scratch
		if cfg.noclipRage then
			Combat.noclip.rage((opts.holdSec or 0.4) + 0.2)
		end
		local cf = Combat.lookAtSafe(origin, aim)
		local char = LP.Character
		if char and char.PrimaryPart then
			char:PivotTo(cf)
			char.PrimaryPart.AssemblyLinearVelocity = Vector3.zero
			char.PrimaryPart.AssemblyAngularVelocity = Vector3.zero
		end
		if opts.mark ~= false then
			Combat.markTeleport()
		end
		return cf
	end
	-- a local, invisible, anchored pad under an airborne hold (the void under the map, the sky, voidspam
	-- out in the void): the character stands on it instead of free-falling between two pins — one frame
	-- hitch used to drop the body through FallenPartsDestroyHeight ("died out of the map"). Client-only:
	-- the server never sees it, it is in no game ray whitelist, and noclip keeps the Humanoid on it.
	Combat.pad = nil
	function Combat.padAt(spot: Vector3)
		local char = LP.Character
		local root = char and char.PrimaryPart
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		if not (root and hum) then
			return
		end
		-- root centre to the soles: R15 stands on HipHeight, R6 on its 2 st legs
		local drop = (if hum.RigType == Enum.HumanoidRigType.R15 then hum.HipHeight else 2) + root.Size.Y * 0.5
		local p = Combat.pad
		if not (p and p.Parent) then
			p = Instance.new("Part")
			p.Name = "CenterraVoidPad"
			p.Anchored = true
			p.CanCollide = true
			p.CanTouch = false
			p.CastShadow = false
			p.Transparency = 1
			p.Size = Vector3.new(16, 1, 16)
			p.Parent = workspace.CurrentCamera or workspace
			Combat.pad = p
		end
		local want = Vector3.new(spot.X, spot.Y - drop - 0.5, spot.Z)
		if (p.Position - want).Magnitude > 0.02 then
			p.CFrame = CFrame.new(want)
		end
	end
	function Combat.padClear()
		local p = Combat.pad
		if p then
			Combat.pad = nil
			pcall(p.Destroy, p)
		end
	end

	-----------------------------------------------------------------------------
	-- §7 body — the one owner of where the character is. A feature that moves the body calls
	-- Body.request(owner, spot, aim, opts) during its step; Body.commit (once per frame, right after
	-- the positioning steps) hands the body to the highest-priority request whose spot passes Safe,
	-- relocates once, and alone writes S.teleported / S.pinCF and the noclip hold. The spot the player
	-- stood on is captured once, when the body first leaves their control (never a hide spot), and
	-- the body goes back there when nobody asks any more. Death, respawn and the game moving us
	-- (round start, a server yank) end every hold without a teleport.
	-----------------------------------------------------------------------------
	do -- block-scoped (200-register cap): reachable as Combat.body / S.body
	local Body: any = {
		PRIO = { autokill = 70, meleeRage = 60, backstab = 58, dodge = 55, defense = 50, magic = 40, peek = 30 },
		-- longest continuous hold per owner in seconds (defense reads cfg.defenseMaxHide)
		MAX_HOLD = { autokill = 20, meleeRage = 20, dodge = 1.5, magic = 60, peek = 12 },
		req = {},
		order = {},
		owner = nil,
		ownerSince = 0,
		home = nil,
		homeChar = nil,
		homeCam = nil,
		homeRot = nil,
		camTurned = false,
		last = nil,
		lastKey = nil,
		jumpAt = 0,
		committedAt = 0,
		idle = 0,
		ending = nil,
		blocked = {},
		takes = 0,
		EMPTY = {},
	}
	Combat.body = Body
	S.body = Body
	S.charAlive = true
	local Safe = S.safe
	local function finiteCF(cf: CFrame): boolean
		local p = cf.Position
		local m = p.Magnitude
		return m == m and m < 1e6 and cf.LookVector.Magnitude > 0.5
	end
	function Body.pivot(cf: CFrame): boolean
		if typeof(cf) ~= "CFrame" or not finiteCF(cf) then
			S.hookErr("body", "refused a non-finite CFrame")
			return false
		end
		local char = LP.Character
		local root = char and char.PrimaryPart
		if not root then
			return false
		end
		char:PivotTo(cf)
		root.AssemblyLinearVelocity = Vector3.zero
		root.AssemblyAngularVelocity = Vector3.zero
		return true
	end
	-- opts (reuse one table per caller — nothing here keeps it past the frame):
	--   hold      s the body rests there (noclip hold + the lethal-volume rule), default 0.4
	--   pin       keep the rendered view where the player stood
	--   turnCam   the owner turns the game camera: the saved rotation comes back at home
	--   key       jump-detection point (default the spot; magic passes the spot without its jitter)
	--   jumpDist  movement of `key` in one frame that counts as a hop (default 1.5 st)
	--   jump      force a hop (settle restart)
	--   velocity  glide toward the spot at up to this many st/s instead of pivoting (far → pivot)
	--   geometry / void / sky / refGround   passed to Safe.check
	function Body.request(owner: string, spot: Vector3, aim: Vector3?, opts: any?): boolean
		if typeof(spot) ~= "Vector3" or spot ~= spot then
			return false
		end
		if os.clock() < (Body.blocked[owner] or 0) then
			return false
		end
		local r = Body.req[owner]
		if not r then
			r = {}
			Body.req[owner] = r
		end
		r.spot, r.aim, r.opts, r.frame = spot, aim, opts or Body.EMPTY, Game.frameId
		return true
	end
	-- an owner is done. stay = keep the end spot when the player can stand there (else home).
	-- Deferred to the next commit, so a hand-over to another owner never visits home in between.
	function Body.release(owner: string, stay: boolean?)
		local r = Body.req[owner]
		if r then
			r.frame = -1
		end
		if Body.owner == owner then
			Body.ending = { owner = owner, stay = stay == true }
		end
	end
	function Body.holds(owner: string): boolean
		return Body.owner == owner
	end
	-- the owner has had the body, unmoved, for at least one settle (the server sees us there)
	function Body.settledFor(owner: string): boolean
		return Body.owner == owner and os.clock() - Body.jumpAt >= Combat.settleSec()
	end
	function Body.maxHold(owner: string): number
		if owner == "defense" then
			-- voidspam parks in the void for the whole duel; a plain hide ends at Longest hide
			return if cfg.voidSpam then math.huge else cfg.defenseMaxHide
		end
		return Body.MAX_HOLD[owner] or 10
	end
	function Body.captureHome(char: Model)
		Body.home = char:GetPivot()
		Body.homeChar = char
		local cam = workspace.CurrentCamera
		Body.homeCam = cam and cam.CFrame or nil
		Body.homeRot = nil
		pcall(function()
			Body.homeRot = CameraController.Rotation
		end)
		Body.camTurned = false
		Body.takes += 1
	end
	-- everything the holds changed goes back; `move` = pivot to the home spot first
	function Body.finish(why: string, move: boolean)
		local char = LP.Character
		if move and Body.home and char and char == Body.homeChar and char.PrimaryPart then
			Body.pivot(Body.home)
			Combat.markTeleport()
		end
		if move and Body.camTurned and Body.homeRot then
			pcall(function()
				Game.asGame(CameraController.SetRotation, CameraController, Body.homeRot)
			end)
		end
		local was = Body.owner
		Body.owner, Body.home, Body.homeChar, Body.homeCam, Body.homeRot = nil, nil, nil, nil, nil
		Body.camTurned, Body.last, Body.lastKey, Body.idle, Body.ending = false, nil, nil, 0, nil
		S.teleported = false
		S.pinCF = nil
		Combat.noclip.release()
		Combat.padClear()
		if was then
			log("INFO", ("body: %s → you (%s)"):format(was, why))
		end
	end
	function Body.goHome(why: string)
		Body.finish(why, true)
	end
	-- the character is gone or the game moved it: drop every hold, no teleport
	function Body.reset(why: string)
		for _, r in pairs(Body.req) do
			r.frame = -1
		end
		if Body.owner then
			Body.finish(why, false)
		end
	end
	-- hand the body back for good (the lobby gate): home, unless the game already moved us (a duel that
	-- ended put us in the waiting room — "home" is the arena spot, which must not be teleported to)
	function Body.leave(why: string)
		if not Body.owner then
			return
		end
		local char = LP.Character
		local root = char and char.PrimaryPart
		if not root or char ~= Body.homeChar or (Body.last ~= nil and (root.Position - Body.last).Magnitude > 45) then
			Body.reset(why)
		else
			Body.goHome(why)
		end
	end
	-- a one-off move that hands the body straight back (a backstab lunge): only while nobody holds it
	function Body.jump(owner: string, cf: CFrame): boolean
		if Body.owner ~= nil or S.calibrating or Combat.oobProbing or S.featuresPaused then
			return false
		end
		if not Safe.standable(cf.Position) then
			Safe.note(owner .. ": nowhere to stand")
			return false
		end
		if Body.pivot(cf) then
			Combat.markTeleport()
			return true
		end
		return false
	end
	-- this frame's winner: the highest-priority request whose spot passes Safe (or can be fixed into
	-- it). No movement here — commit does that (and the tests call this alone).
	function Body.pick(now: number, frame: number): (string?, Vector3?, any)
		local order = Body.order
		table.clear(order)
		for owner, r in pairs(Body.req) do
			if r.frame == frame then
				table.insert(order, owner)
			end
		end
		if #order > 1 then
			-- an urgent request (a dodge with a blade inside its reach) outranks everything for its frame
			local function prio(o: string): number
				local rq = Body.req[o]
				return (Body.PRIO[o] or 0) + (if rq and rq.opts and rq.opts.urgent then 25 else 0)
			end
			table.sort(order, function(a, b)
				return prio(a) > prio(b)
			end)
		end
		for _, owner in ipairs(order) do
			local rq = Body.req[owner]
			if Body.owner == owner and now - Body.ownerSince > Body.maxHold(owner) then
				Body.blocked[owner] = now + 2
				log("INFO", ("body: %s held %.1f s — its limit"):format(owner, now - Body.ownerSince))
			else
				local o = rq.opts
				local ok, why = Safe.check(rq.spot, o)
				local s = rq.spot
				if not ok then
					s = Safe.fix(rq.spot, o)
					-- a fixed spot is only a candidate: the body moves to it only once Safe.check accepts it
					if s and not Safe.check(s, o) then
						s = nil
					end
					if not s and Body.owner == owner and Body.last and Safe.check(Body.last, o) then
						s = Body.last -- one bad frame (a jitter into a volume) keeps the last spot, while it still passes
					end
					if not s then
						Safe.note(owner .. ": " .. tostring(why))
					end
				end
				if s then
					return owner, s, rq
				end
			end
		end
		return nil, nil, nil
	end
	function Body.commit()
		if S.calibrating or Combat.oobProbing then
			return -- those drive the body themselves
		end
		-- the lobby gate: nothing teleports outside a live duel (a hold still open is handed back once)
		if S.featuresPaused then
			Body.leave("lobby")
			return
		end
		local now = os.clock()
		local frame = Game.frameId
		local char = LP.Character
		local root = char and char.PrimaryPart
		local gs = S.gameState
		if not S.charAlive and gs and gs.alive == true and now - (S.diedAt or 0) > 2 then
			S.charAlive = true -- revived without a new character (the game kept the same model)
		end
		if not S.charAlive or (gs and gs.alive == false) then
			Body.reset("dead") -- nothing moves a dead body; requests resume after the respawn
			return
		end
		if Body.owner then
			if not (char and root) or char ~= Body.homeChar then
				Body.reset("character changed")
			elseif Body.last and (root.Position - Body.last).Magnitude > 45 then
				Body.reset("the game moved you")
			end
		end
		-- damage on a spot we put the body on (magic / hide / peek): that spot is exposed — home now,
		-- before the death reset does it, and that owner waits a moment before it takes the body again
		local hpNow = Game.myHealth()
		local owner0 = Body.owner
		-- v6.3: every real hit is remembered (autokill hides on it — Combat.hurtHide)
		if hpNow and Body.hpLast and hpNow < Body.hpLast - 6 then
			S.hurtAt, S.hurtAmount = now, Body.hpLast - hpNow
		end
		-- voidspam's spots (under them, a bait) are not sent home: home is the exposed spot — voidspam hides instead
		if owner0 and (owner0 == "magic" or (owner0 == "defense" and not Combat.voidSpamOn()) or owner0 == "peek") and hpNow and Body.hpLast and hpNow < Body.hpLast - 6 then
			Body.blocked[owner0] = now + 0.8
			log("INFO", ("[body:home:damaged] %s spot took %.0f (%.0f → %.0f)"):format(owner0, Body.hpLast - hpNow, Body.hpLast, hpNow))
			Body.goHome("damaged")
		end
		Body.hpLast = hpNow
		local win, spot, r = Body.pick(now, frame)
		if not win then
			if Body.owner then
				local e = Body.ending
				if e and e.owner == Body.owner and e.stay and root and Safe.standable(root.Position) then
					Body.finish(e.owner .. " ended here", false)
				elseif (e and e.owner == Body.owner) or Body.idle >= 1 then
					Body.goHome(if e then e.owner .. " ended" else Body.owner .. " let go")
				else
					Body.idle += 1
				end
			end
			return
		end
		if not (char and root) then
			return
		end
		Body.idle = 0
		Body.ending = nil
		local o = r.opts
		if Body.owner ~= win then
			if Body.owner == nil then
				Body.captureHome(char)
			end
			log("DEBUG", ("body: %s → %s"):format(Body.owner or "you", win))
			Body.owner = win
			Body.ownerSince = now
			Body.lastKey = nil
		end
		local key = if spot == r.spot then (o.key or spot) else spot
		local jump = o.jump == true or Body.lastKey == nil or (key - Body.lastKey).Magnitude > (o.jumpDist or 1.5)
		Body.lastKey = key
		if cfg.noclipRage then
			Combat.noclip.rage((o.hold or 0.4) + 0.2)
		end
		local aim = r.aim or (spot + root.CFrame.LookVector * Vector3.new(1, 0, 1))
		if o.velocity and not jump then
			local delta = spot - root.Position
			if delta.Magnitude > 12 then
				Body.pivot(Combat.lookAtSafe(spot, aim))
				jump = true
			else
				local dt = math.clamp(now - Body.committedAt, 1 / 240, 0.1)
				local v = delta / dt
				if v.Magnitude > o.velocity then
					v = v.Unit * o.velocity
				end
				root.AssemblyLinearVelocity = v
				root.AssemblyAngularVelocity = Vector3.zero
				root.CFrame = Combat.lookAtSafe(root.Position, aim)
			end
		else
			Body.pivot(Combat.lookAtSafe(spot, aim))
		end
		-- nothing under an airborne hold: the body stands on our local pad there
		if o.far or o.sky or (o.void and not Safe.groundY(spot)) then
			Combat.padAt(spot)
		elseif Combat.pad then
			Combat.padClear()
		end
		if jump then
			Combat.markTeleport()
			Body.jumpAt = now
		end
		Body.last = spot
		Body.committedAt = now
		S.teleported = true
		S.pinCF = if o.pin then Body.homeCam else nil
		if o.turnCam then
			Body.camTurned = true
		end
	end
	-- death and respawn: nothing we held survives either (S.charAlive is ours; S.alive is the script's)
	function Body.watchChar(char: Model?)
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		if hum then
			Game.track(hum.Died:Connect(function()
				S.charAlive = false
				S.diedAt = os.clock()
				Body.reset("died")
			end))
		end
	end
	Game.track(LP.CharacterAdded:Connect(function(c: Model)
		S.charAlive = true
		Body.reset("respawned")
		task.defer(Body.watchChar, c)
	end))
	Body.watchChar(LP.Character)
	end -- Body block

	-- reusable opts so the per-frame planner call allocates nothing. noclip = false: magic never plans a
	-- spot inside a wall (Combat.magicReq refuses them; the duel log had magic taking damage in walls)
	Combat.magicPlanOpts = { holdSec = 0.4, noclip = false }
	-- part: the hitbox the planner checks the server's line to (default the lock's); false = plan for
	-- the point itself (the spot a void spammer will surface at has no part yet)
	function Combat.magicOrigin(target: Vector3, model: Model?, keepOffset: Vector3?, part: any): Vector3
		local maxH = cfg.magicHeight
		local planPart = if part == false then nil else (part or S.silentPart)
		-- buried in the floor (the under desync): the height slider would put us out of the push's reach
		-- (Auto height plans it in Combat.origin.plan, which prefers a spot inside the slab under noclip)
		local buried = if part ~= false and not cfg.magicAutoHeight then S.bounds.buriedTop(model) else nil
		if buried then
			local cam = workspace.CurrentCamera
			return Combat.buriedStand(target, buried, if cam then cam.CFrame.Position else nil)
		end
		-- Auto height OFF keeps the old contract: the slider is authoritative — exactly magicHeight up,
		-- nudged sideways only if that height is blocked (so the slider visibly changes the distance).
		if not cfg.magicAutoHeight then
			Combat.setClearFilter(model)
			local cam = workspace.CurrentCamera
			local side = if cam then (cam.CFrame.Position - target) * Vector3.new(1, 0, 1) else Vector3.zero
			side = if side.Magnitude > 1 then side.Unit else Vector3.zero
			local perp = Vector3.new(-side.Z, 0, side.X)
			-- v5: the exact height may sit inside a sky OutOfBoundsPart (the v4 "magic teleported me out
			-- of the map" death) — step it down until the spot is outside every lethal volume, then nudge
			-- sideways if that height is blocked. The slider stays authoritative whenever it is safe.
			local h = maxH
			local guard = 0
			while h > 3 and guard < 12 and not S.bounds.allows(target + Vector3.new(0, h, 0), 0.4) do
				guard += 1
				h = math.max(3, h - math.max(3, h * 0.2))
			end
			if h < maxH and h ~= Combat.magicHeightNoted then
				Combat.magicHeightNoted = h
				log("INFO", ("magic: %d studs up is inside an out-of-bounds volume here — using %d"):format(maxH, h))
			end
			local top = target + Vector3.new(0, h, 0)
			for _, c in ipairs(Combat.MAGIC_OFFS_MANUAL) do
				local origin = top + side * (c[1] * 3) + perp * (c[2] * 3)
				if Combat.clearTo(origin, target) and S.bounds.allows(origin, 0.4) then
					return origin
				end
			end
			return top
		end
		-- Auto height ON → the v5 planner: below-map / wall pockets / OOB-safe / spread-immune, not just
		-- "lowest clear point above". The locked part gives it the server-LOS and spread maths.
		Combat.magicPlanOpts.holdSec = 0.4
		-- v6.4 Wallbang: magic may stand inside the wall next to the target (a round that starts inside a part
		-- ignores it) and reach an enemy who noclipped into a wall from inside the same wall
		Combat.magicPlanOpts.noclip = cfg.wallbang == true
		Combat.magicReq.geometry = cfg.wallbang == true
		return Combat.origin.plan(target, model, planPart, Combat.magicPlanOpts)
	end

	-- Magic bullet: hold the character at the clear spot while firing (pre-positioned on the aim key)
	-- through Body; the trigger waits one settle after every hop.
	-- every field the bullet code writes is declared here: the table literal alone would type itself from
	-- its three initial keys and every later brk / park / wantsBody write would be an unknown key
	local magic: {
		active: boolean,
		lastFire: number,
		lastOffset: Vector3?,
		brk: any?,
		brkNext: number?,
		keptLogged: boolean,
		park: any?,
		wantsBody: boolean?,
	} = {
		active = false,
		lastFire = 0,
		lastOffset = nil,
		brk = nil,
		brkNext = nil,
		keptLogged = false,
		park = nil,
		wantsBody = nil,
	}
	Combat.magic = magic
	-- never a still target up there: a fresh random spot around the clear point every 1/Hz s (kept
	-- inside the origin tolerance and re-checked for a clear line to the target) plus a continuous
	-- small wiggle so the body moves between hops too. Returned as an offset on the base origin so
	-- the keep-spot / settle logic still sees the calm base point.
	-- A hop moves the body the server shoots from, so every hop costs one settle (ping/2 + 40 ms)
	-- of held fire — hops are spaced at least that far apart and the trigger waits it out
	-- (S.magicHopSettled). Never upward: the clear point is the lowest safe spot and the OOB
	-- volume can sit right above it (a live match: OutOfBounds fired from a +1.5 st jitter).
	Combat.magicJit = { at = 0, off = Vector3.zero }
	function Combat.magicJitterOffset(target: Vector3, origin: Vector3, model: Model?): Vector3
		if not cfg.magicJitter then
			S.magicHopSettled = true
			Combat.magicJit.force = nil
			return Vector3.zero
		end
		local now = os.clock()
		local j = Combat.magicJit
		local settle = Combat.settleSec()
		-- every hop buys one settle of silence: leave at least 300 ms of firing per hop after it
		local gap = math.max(1 / math.max(cfg.magicJitterHz, 1), settle + 0.3)
		-- the fire window: a round can leave within one settle. The server fires from where it has us,
		-- so the body holds still in it; a slow gun (sniper, shotgun, revolver) moves only while its
		-- cooldown outlasts a hop's settle — one hop the instant a round leaves, more while the cooldown
		-- runs. A fast gun (cycle shorter than the settle: AR, Wildcat, judged by the live ShootCooldown,
		-- not the stamp) lives in the window: it hops at most every 0.6 s, each costing one settle.
		local window = S.silentTarget ~= nil and Combat.cannotFireFor(S.gameState) <= settle + 0.05
		local fast = Combat.gunCycle() < settle * 0.8
		local onShot = cfg.magicHopOnShot and not fast and S.lastShotWindowAt ~= nil and now - S.lastShotWindowAt < 0.03 and now - j.at > 0.08
		-- a forced hop (autokill was hit on this spot) goes even with a round due
		local periodic = (now - j.at >= gap and not window) or (fast and window and now - j.at >= math.max(gap, 0.6)) or (j.force == true and now - j.at > 0.08)
		if periodic or onShot then
			j.at = now
			j.force = nil
			local r = cfg.magicJitterRadius
			Combat.setClearFilter(model)
			for _ = 1, 4 do
				local a = math.random() * 2 * math.pi
				local off = Vector3.new(math.cos(a) * r, -math.random() * math.min(r * 0.3, 0.8), math.sin(a) * r)
				if workspace:Raycast(origin + off, target - (origin + off), clearParams) == nil then
					j.off = off
					break
				end
			end
		end
		local w = if window then 0 else cfg.magicWiggle
		if w == 0 and (j.wig or 0) > 0 then
			j.stillAt = now -- the body steps back onto the calm spot: one settle for the server to see it
		end
		j.wig = w
		S.magicHopSettled = now - math.max(j.at, j.stillAt or 0) >= settle
		local wig = Vector3.new(math.sin(now * 17) * w, -math.abs(math.sin(now * 23 + 1)) * w * 0.4, math.cos(now * 19) * w)
		return j.off + wig
	end
	-- one request table for the life of the script (Body keeps nothing past the frame)
	-- geometry stays false: a magic spot inside a wall or ceiling passed Safe and took the damage
	Combat.magicReq = { hold = 0.4, pin = true, turnCam = false, key = nil, geometry = false, void = false, refGround = nil }
	-- the threat magic was on: kept while they were seen a moment ago, still sit in the void, or only just
	-- left the 400-stud bubble. A lock that drops for a frame (a 10 ms teleport peek, a void dip, the
	-- range gate) must not send the body home — one settle later they are back and we are already there.
	Combat.magicThreat = { fighter = nil, at = 0, void = false, spot = nil, aim = nil }
	function Combat.threatKept(now: number): boolean
		local t = Combat.magicThreat
		local f = t.fighter
		if f == nil or Target.isDead(f) then
			return false
		end
		-- warped away: holding the shooting spot only waits for them to come back and shoot it
		local _, fm = Game.fighterBody(f)
		if fm and Resolver.away(fm) then
			return false
		end
		local age = now - t.at
		if age <= 2.5 then
			return true
		end
		if t.void and age <= 6 and S.bounds.isVoidFighter(f) then
			return true
		end
		local root = Game.fighterBody(f)
		local me = S.myRootPart or Game.myRoot()
		return age <= 4 and root ~= nil and me ~= nil and (root.Position - me.Position).Magnitude <= cfg.targetMaxDistance * 1.3
	end
	function Combat.updateMagic()
		local trigger = S.firing or (cfg.magicPrePosition and S.aimHeld) or (cfg.autoShoot and S.silentTarget ~= nil)
		-- everything but the lock and the trigger: magic may run at all
		local enabled = cfg.silentAim and cfg.magicBullet and Combat.rageOn() and not S.menuOpen
			and ak.state == "idle" and not S.calibrating and not S.peek and Combat.magicWeaponOk(Game.weaponProfile())
		-- never walks up to a lock that is warped away or only just surfaced (Combat.engageable)
		local want = enabled and trigger and S.silentTarget ~= nil and not S.targetAway and Combat.engageable(S.silentTargetModel)
		local Body = Combat.body
		if want then
			if not magic.active then
				magic.active = true
				log("INFO", "magic: on" .. (if cfg.magicInvisible then " (camera pinned)" else ""))
			end
			magic.lastFire = os.clock()
			magic.keptLogged = false
			local target = S.silentTarget :: Vector3
			-- a void spammer who just dipped comes back up where they left: wait over that spot, settled,
			-- instead of re-planning (and re-settling) the frame they surface
			local trap = S.counter.trapPoint(S.silentFighter)
			local planFor = trap or target
			local origin = Combat.magicOrigin(planFor, S.silentTargetModel, magic.lastOffset, if trap then false else nil)
			if (origin - planFor).Magnitude < 0.5 then
				origin = planFor + Vector3.new(0, 3, 0)
			end
			magic.lastOffset = origin - planFor
			local shown = origin + Combat.magicJitterOffset(planFor, origin, S.silentTargetModel)
			-- the jitter must never be what makes a spot unsafe: fall back to the calm origin
			local req = Combat.magicReq
			req.pin = cfg.magicInvisible
			req.turnCam = not cfg.magicInvisible
			req.key = origin
			-- hunting someone under the map: the void is allowed, and a kill volume only while its clock
			-- leaves room (Safe watches Bounds.secondsLeft)
			req.void = not trap and S.bounds.underMap(target, S.silentTargetModel)
			req.budget = req.void
			-- a ray down from inside the slab skips it: the ground for a buried target is the slab's top
			req.refGround = (if trap then nil else S.bounds.buriedTop(S.silentTargetModel)) or S.safe.groundY(planFor)
			req.sky, req.far = false, false
			if not S.safe.check(shown, req) then
				shown = origin
			end
			local nowB = os.clock()
			local busy = Combat.cannotFireFor(S.gameState)
			Combat.magicThreat.fighter, Combat.magicThreat.at = S.silentFighter, nowB
			Combat.magicThreat.void, Combat.magicThreat.spot, Combat.magicThreat.aim = req.void == true, origin, planFor
			-- a defense armed: magic holds the body for its fire window only (from one settle + one echo
			-- before the gun is ready until the round has left); the rest of the cooldown belongs to the
			-- hide, which takes the body in this same frame (Combat.defenseNeeded sees wantsBody false)
			if Combat.magicYields(busy) then
				if magic.wantsBody then
					log("DEBUG", ("[magic:release:shot] gun busy %.2f s → the hide takes the body · body %s"):format(busy, Body.owner or "you"))
				end
				magic.wantsBody = false
				magic.brk, magic.park = nil, nil
				S.magicReady = false
			else
				-- no defense armed: magic hides the body itself while the gun is busy past a round trip — the
				-- void (sky / under the floor / far), never the open shooting spot — and is back on the spot one
				-- fire lead before the gun is ready, already facing the lock (the stream faces it from there)
				local park = nil
				if not Combat.defenseArmed() and Combat.parkWorth(busy) then
					park = magic.park
					if not park or nowB - park.at >= 1 / math.max(cfg.defenseHopHz, 1) then
						local from = if Body.home then Body.home.Position else (if S.myRootPart then S.myRootPart.Position else origin)
						local c = Combat.pickHide(from, S.enemiesNow or {})
						if c and not magic.park then
							log("DEBUG", ("[magic:park] gun busy %.2f s → %s"):format(busy, Combat.hideWhere(c)))
						end
						park = if c then { spot = c.pos, kind = c.kind, at = nowB } else nil
						magic.park = park
					end
				else
					magic.park = nil
				end
				local br = magic.brk
				if park then
					magic.brk, br = nil, nil
					shown = park.spot
					req.key = park.spot
					req.sky, req.void, req.far = park.kind == "sky", park.kind == "void", park.kind == "far"
					req.budget = park.kind == "void"
					req.refGround = nil
					S.preFaceFrom = origin + Vector3.new(0, 1.85, 0)
					S.preFace = busy <= Combat.fireLead() + Combat.echoLead()
				else
					-- break prediction: now and then, while the gun has time to spare, a short hop to a random safe
					-- spot (Safe-checked in breakerSpot), back on the shooting spot one fire lead before it can
					-- fire — never while the next round kills
					if br and (nowB > br.untilT or busy <= Combat.fireLead()) then
						magic.brk, br = nil, nil
					end
					if not br and cfg.rageBreaker and busy > Combat.settleSec() * 2 + 0.35 and nowB >= (magic.brkNext or 0) and not Combat.killable(S.silentFighter) then
						magic.brkNext = nowB + 2 + math.random() * 2
						local b = Combat.breakerSpot(planFor)
						if b then
							br = { spot = b, untilT = nowB + 0.25 }
							magic.brk = br
							log("DEBUG", ("[magic:break] %.0f st hop while the gun is busy %.2f s"):format((b - planFor).Magnitude, busy))
						end
					end
					if br then
						shown = br.spot
						req.key = br.spot
						S.preFaceFrom = origin + Vector3.new(0, 1.85, 0)
					end
				end
				magic.wantsBody = true
				Body.request("magic", shown, planFor, req)
				-- ready = Body gave us the body and it has sat still for one settle (the server sees us there)
				S.magicReady = Body.settledFor("magic") and not br and not park
				if not cfg.magicInvisible and Body.holds("magic") then
					-- visible mode: the view follows the body, so turn the game's camera at the target too
					Game.setCamRotation(Combat.lookAtSafe(shown, planFor))
				end
			end
		elseif magic.active then
			local nowK = os.clock()
			local mt = Combat.magicThreat
			magic.wantsBody = false
			if enabled and S.silentTarget == nil and mt.spot and Combat.threatKept(nowK) then
				-- the lock is gone for now but the threat is kept: hold the shooting spot, no trip home
				-- (while the gun is busy and a defense is armed, the hide keeps the body instead)
				if not Combat.magicYields(Combat.cannotFireFor(S.gameState)) then
					magic.wantsBody = true
					Body.request("magic", mt.spot, mt.aim, Combat.magicReq)
				end
				S.magicReady = false
				if not magic.keptLogged then
					magic.keptLogged = true
					log("INFO", ("[magic:hold:kept-threat] lock lost, %s seen %.1f s ago%s · body %s"):format(Game.fighterName(mt.fighter), nowK - mt.at, if mt.void then " (void)" else "", Body.owner or "you"))
				end
			elseif nowK - magic.lastFire > 0.15 or not enabled then
				Combat.magicRelease(if not enabled then "off" elseif S.silentTarget == nil then "no lock" else "no trigger")
			end
		end
		if not magic.active then
			S.magicReady = false
			magic.wantsBody = false
			if Body.owner == "magic" and not Body.ending then
				Body.release("magic")
				log("INFO", ("[magic:release:stale] magic off (magicBullet %s, rage %s) while Body still said magic"):format(tostring(cfg.magicBullet), cfg.ragePosition))
			end
		end
	end
	-- magic is done; Body takes the body home (or hands it to whoever asks next)
	function Combat.magicRelease(reason: string)
		if not magic.active then
			return
		end
		magic.active = false
		magic.lastOffset = nil
		magic.brk, magic.park = nil, nil
		magic.wantsBody = false
		S.magicReady = false
		Combat.body.release("magic")
		log("INFO", ("[magic:release:%s] magic: %s · body %s"):format(string.gsub(reason, " ", "-"), reason, Combat.body.owner or "you"))
		if reason == "no lock" then
			log("INFO", "[magic:home:no-lock] no lock and no kept threat: the body goes home")
		end
	end

	-- Situation: one cheap read of the fight every few frames that the other systems act on instead
	-- of guessing — how many enemies are close, how many are aiming at us, whether the nearest one
	-- can see us, our HP / ammo state and what we hold. S.situation is also shown as a HUD chip.
	Combat.sit = { near = 0, mid = 0, total = 0, aimingAtMe = 0, nearestDist = math.huge, exposed = false, hpFrac = 1, lowAmmo = false, weaponClass = "none", crowd = false, danger = 0, text = "" }
	S.situation = Combat.sit
	-- the class Game.profileOf gave the item in hand (rifle / sniper / burst / shotgun / projectile /
	-- flamethrower / melee / crit melee / shield / utility)
	function Combat.weaponClass(prof: any): string
		if not prof or not prof.item then
			return "none"
		end
		return prof.class or "rifle"
	end
	-- magic bullet relocates a shooter: only a gun in hand (a blade takes the behind-heavy path, a
	-- shield blocks, a utility does neither)
	function Combat.magicWeaponOk(prof: any): boolean
		return prof ~= nil and prof.gun == true
	end
	-- the gun silent path (lock + trigger + claim): guns only, never a shield or a utility
	function Combat.silentGunOk(prof: any): boolean
		return prof ~= nil and prof.gun == true
	end
	function Combat.updateSituation(enemies: { any }, gs: any)
		local sit = Combat.sit
		-- the hide may already have refreshed it this frame (it runs first when defense wants a fresh read)
		if sit.frame == Game.frameId then
			return
		end
		sit.frame = Game.frameId
		local me = Game.myRoot()
		local near, mid, aiming, nearest, nearestF = 0, 0, 0, math.huge, nil
		if me then
			for _, f in ipairs(enemies) do
				local r = Game.fighterBody(f)
				if r and not Target.isDead(f) then
					local d = (r.Position - me.Position).Magnitude
					if d < nearest then
						nearest, nearestF = d, f
					end
					if d <= 25 then
						near += 1
					end
					if d <= 80 then
						mid += 1
					end
					if d <= 140 and not f.IsBot and Target.threat(f) > 0.5 then
						aiming += 1
					end
				end
			end
		end
		local blade = S.meleeThreat -- Combat.scanMeleeThreats, every frame
		sit.bladeNear = blade ~= nil
		sit.near, sit.mid, sit.total, sit.aimingAtMe, sit.nearestDist = near, mid, #enemies, aiming, nearest
		-- can the nearest enemy see us (from their head to ours, server-style whitelist)
		local exposed = false
		if nearestF and me and nearest < 200 then
			local eHead = Game.fighterHead(nearestF)
			local myHead = S.myHeadPart
			local _, eModel = Game.fighterBody(nearestF)
			if eHead and myHead and myHead.Parent then
				local params = Game.losParams()
				if params then
					-- their own body does not count as cover for them
					local hit = workspace:Raycast(eHead.Position, myHead.Position - eHead.Position, params)
					exposed = hit == nil or (eModel ~= nil and hit.Instance:IsDescendantOf(eModel)) or (LP.Character ~= nil and hit.Instance:IsDescendantOf(LP.Character))
				else
					exposed = Game.rayVisible(LP.Character, myHead, eHead.Position)
				end
			end
		end
		sit.exposed = exposed
		local hp, mx = gs and gs.hp, gs and gs.maxHp
		sit.hpFrac = if hp and mx and mx > 0 then math.clamp(hp / mx, 0, 1) else 1
		sit.lowAmmo = gs ~= nil and gs.ammo ~= nil and gs.maxAmmo ~= nil and gs.maxAmmo > 0 and gs.ammo <= math.max(1, math.floor(gs.maxAmmo * 0.25))
		sit.weaponClass = Combat.weaponClass(Game.weaponProfile())
		sit.crowd = near >= 3 or (mid >= 4)
		sit.danger = math.clamp(aiming * 0.35 + near * 0.15 + (1 - sit.hpFrac) * 0.3 + (if sit.lowAmmo then 0.15 else 0) + (if exposed and nearest < 60 then 0.1 else 0) + (if blade then 0.25 else 0), 0, 1)
		-- the chip text is rebuilt only when one of its inputs changed (string.format + concat at
		-- 20 Hz for an unchanged line was pure churn)
		local bladeKey = if blade then blade.weapon .. math.floor(blade.dist + 0.5) else ""
		local key = near * 1000000 + mid * 10000 + aiming * 100 + (if exposed then 1 else 0) + (if sit.lowAmmo then 2 else 0) + (if nearest < math.huge then 4 else 0)
		if key ~= sit._key or bladeKey ~= sit._bladeKey then
			sit._key, sit._bladeKey = key, bladeKey
			local parts = {}
			if near > 0 then
				table.insert(parts, ("%d near"):format(near))
			elseif mid > 0 then
				table.insert(parts, ("%d mid"):format(mid))
			end
			if aiming > 0 then
				table.insert(parts, ("%d aiming at you"):format(aiming))
			end
			if blade then
				table.insert(parts, ("%s %.0f st"):format(blade.weapon, blade.dist))
			end
			if nearest < math.huge then
				table.insert(parts, if exposed then "exposed" else "in cover")
			end
			if sit.lowAmmo then
				table.insert(parts, "low ammo")
			end
			sit.text = if #parts > 0 then table.concat(parts, " · ") else ""
		end
	end

	-- melee helpers: the game's own reach (Melee.GetAutoShootReach = Info.AttackReach) and the
	-- distance from our shot origin to the locked point
	function Combat.meleeReach(item: any): number
		local info = type(item) == "table" and item.Info
		local r = type(info) == "table" and tonumber(info.AttackReach) or nil
		return r or 10
	end
	function Combat.targetDistance(): number?
		local tgt = S.silentTarget
		local from = Game.shotOriginPos()
		if not (tgt and from) then
			return nil
		end
		return (tgt - from).Magnitude
	end
	-- auto quick melee: gun in hand, an enemy inside the knife's reach with line of sight → the
	-- game's own QuickMelee input (one stab per its cooldown), and the trigger holds for the swing
	local quickMeleeAt = 0
	function Combat.quickMeleeItem(): any
		local lf = Game.localFighter()
		if type(lf) ~= "table" or type(lf.Items) ~= "table" then
			return nil
		end
		for _, it in pairs(lf.Items) do
			if type(it) == "table" and type(it.Info) == "table" and it.Info.Type ~= "Gun" and it.Info.AttackReach then
				return it
			end
		end
		return nil
	end
	function Combat.updateQuickMelee(enemies: { any })
		S.quickMeleeReady = false
		if not (cfg.autoQuickMelee and cfg.silentAim) or S.menuOpen or S.hudEdit or S.calibrating then
			return
		end
		if ak.state ~= "idle" and ak.state ~= "done" then
			return
		end
		local prof = Game.weaponProfile()
		if prof.melee or not prof.item then
			return
		end
		local knife = Combat.quickMeleeItem()
		if not knife then
			return -- nothing to stab with: the 10-stud default reach used to fire QuickMelee anyway
		end
		local reach = Combat.meleeReach(knife) - 0.5
		local from = Game.shotOriginPos()
		if not from then
			return
		end
		local best, bestD = nil, math.huge
		for _, f in ipairs(enemies) do
			local root, model = Game.fighterBody(f)
			if root and not Target.isDead(f) and not (cfg.immuneCheck and Game.fighterImmune(f)) then
				local part = Game.hitboxPart(f, "Body") or root
				local d = (part.Position - from).Magnitude
				if d < bestD and d <= reach and Game.rayVisible(model, part, from) then
					best, bestD = f, d
				end
			end
		end
		if not best then
			return
		end
		S.quickMeleeReady = true
		local now = os.clock()
		local stamp = knife and tonumber(rawget(knife, "_attack_cooldown"))
		local cdOk = if stamp then tick() >= stamp else now - quickMeleeAt >= (knife and tonumber(knife.Info.AttackCooldown) or 0.6)
		if cdOk and now - quickMeleeAt > 0.25 then
			quickMeleeAt = now
			S.quickMeleeUntil = now + 0.35
			Input.simulate("QuickMelee")
			log("INFO", ("auto quick melee → %s (%.1f st)"):format(Game.fighterName(best), bestD))
		end
	end

	-- v6.3 utilities: the game's own QuickUtility input (MechanicsController → LocalFighter:QuickAttackDown
	-- ("Utility")) uses the utility slot without switching weapons, like QuickMelee. Per item (library
	-- survey, decompiled/weapons.json): Medkit / Elixir heal when low and nobody can hit us, Subspace
	-- Tripmine / Satchel drop when a blade closes in, Grenade / Flashbang / Molotov go at a locked target
	-- 12–45 st out (the camera faces it for the throw; the hold sets the charge). All off by default.
	Combat.util = { at = 0, busyUntil = 0 }
	function Combat.utilityItem(): any
		local lf = Game.localFighter()
		if type(lf) ~= "table" or type(lf.Items) ~= "table" then
			return nil
		end
		for _, it in pairs(lf.Items) do
			local info = type(it) == "table" and it.Info
			-- the item's Type is a union of string literals: widen it to a plain string, or the
			-- literal union makes "Throwable" and "Gun" incomparable
			local ty: string = type(info) == "table" and tostring(info.Type) or ""
			-- the "or" narrows ty to the singleton "Throwable", which then cannot be compared with
			-- "Gun"; test the Gun side first so both sides see the plain string
			if type(info) == "table" and ty ~= "Gun" and (info.Class == "Utility" or ty == "Throwable") then
				return it
			end
		end
		return nil
	end
	function Combat.utilityReady(it: any): boolean
		local now = tick()
		for _, k in ipairs({ "_use_cooldown", "_attack_cooldown", "_shoot_cooldown" }) do
			local v = tonumber(rawget(it, k))
			if v and v > now then
				return false
			end
		end
		return true
	end
	Combat.UTIL_KIND = {
		Medkit = "heal", Elixir = "heal",
		["Subspace Tripmine"] = "mine", Satchel = "mine",
		Grenade = "throw", Flashbang = "throw", Molotov = "throw",
	}
	function Combat.updateUtilities(enemies: { any })
		if not cfg.utilAuto or S.menuOpen or S.hudEdit or S.calibrating or S.featuresPaused then
			return
		end
		local now = os.clock()
		local U = Combat.util
		if now < U.busyUntil or now - U.at < 0.5 then
			return
		end
		U.at = now
		local it = Combat.utilityItem()
		if not it or not Combat.utilityReady(it) then
			return
		end
		local name = tostring(it.Name)
		local kind = Combat.UTIL_KIND[name]
		local sit = S.situation
		local why: string? = nil
		local hold = 0.08
		if kind == "heal" and cfg.utilHeal then
			if sit and (sit.hpFrac or 1) * 100 < cfg.utilHealBelow and (S.defenseHiding or not Combat.enemyCanHit(enemies)) then
				why = ("health %d%%"):format(math.floor((sit.hpFrac or 1) * 100))
			end
		elseif kind == "mine" and cfg.utilMine then
			local mt = S.meleeThreat
			if mt and mt.fighter and (mt.dist or 99) < 14 then
				why = "blade closing in"
			end
		elseif kind == "throw" and cfg.utilThrow and S.silentFighter and S.silentPart then
			local from = Game.shotOriginPos()
			local d = from and (S.silentPart.Position - from).Magnitude
			if d and d >= 12 and d <= 45 and not Combat.body.owner and not Game.fighterImmune(S.silentFighter) then
				Combat.aimAt(S.silentTarget)
				hold = math.clamp(d / 45 * 1.2, 0.15, 1.2)
				why = ("target %d st"):format(math.floor(d))
			end
		end
		if not why then
			return
		end
		U.busyUntil = now + hold + 0.4
		S.quickMeleeUntil = now + hold + 0.3 -- the trigger holds while the utility is out
		S.quickUseUntil = now + hold + 0.5 -- and silent aim leaves the throw / placement alone
		Input.simulate("QuickUtility", hold)
		log("INFO", ("[utility] %s (%s)"):format(name, why))
	end
	-- v6.3 silent aim and auto shoot stand down while a utility is in hand or for a moment after the
	-- player presses the game's Quick Utility / Quick Melee / Equip Utility key (the tester's quick util
	-- "didn't work" and jump pads were placed at the enemy). Keys come from the game's InputLibrary.
	Combat.suspendConn = nil
	function Combat.updateSuspend()
		if not Combat.suspendConn then
			local rs = game:GetService("ReplicatedStorage")
			local mods = rs:FindFirstChild("Modules")
			local IL = Game.requireIfLoaded(mods and mods:FindFirstChild("InputLibrary"))
			if type(IL) == "table" and type(IL.InputIs) == "function" then
				Combat.suspendConn = UIS.InputBegan:Connect(function(input, processed)
					if processed or not S.alive then
						return
					end
					for _, name in ipairs({ "QuickUtility", "QuickMelee", "EquipUtility" }) do
						local ok, is = pcall(IL.InputIs, IL, input, name)
						if ok and is then
							S.quickUseUntil = os.clock() + 1
							return
						end
					end
				end)
				Game.track(Combat.suspendConn)
			else
				Combat.suspendConn = false
			end
		end
		local prof = Game.weaponProfile()
		S.silentSuspended = prof.utility == true or os.clock() < (S.quickUseUntil or 0)
	end
	-- v6.3 gun abilities (Gun abilities switch): the Minigun only fires while spun (ViewModel
	-- IsChargingMinigun, decompiled Gun.StartShooting) — keep it spun while a lock exists; the Revolver's
	-- quick shot fans the cylinder at QuickShotCooldown (0.15 s, server-accepted) at close range.
	Combat.ability = { revolverAt = 0 }
	function Combat.updateGunAbilities()
		if not cfg.gunAbilities or S.menuOpen or S.featuresPaused then
			return
		end
		local gs = S.gameState
		local item = gs and gs.item
		local info = type(item) == "table" and item.Info
		if type(info) ~= "table" then
			return
		end
		local name = tostring(item.Name)
		local locked = S.silentFighter ~= nil and S.silentPart ~= nil and not (cfg.immuneCheck and S.targetImmune)
		if name == "Minigun" then
			if locked and not S.adsHeld then
				S.adsHeld = true
				S.adsLockAt = os.clock()
				Input.setAds(true)
			end
			return
		end
		if name == "Revolver" and locked and cfg.autoShoot and (gs.ammo or 0) >= 2 then
			local from = Game.shotOriginPos()
			local d = from and (S.silentPart.Position - from).Magnitude
			local cd = (tonumber(info.QuickShotCooldown) or 0.15) * (tonumber(info.MaxAmmo) or 6)
			if d and d <= 30 and S.targetVisible ~= false and os.clock() - Combat.ability.revolverAt > cd + 0.2 then
				Combat.ability.revolverAt = os.clock()
				Input.gameInput("StartAiming")
				task.delay(0.05, function()
					if S.alive then
						Input.gameInput("FinishAiming")
					end
				end)
				log("DEBUG", ("[ability] revolver quick shot (%.0f st)"):format(d))
			end
		end
	end

	-- katana: auto block (RMB) when a gun is aimed at us; hold fire while the lock has a blade out
	local blocking = false
	function Combat.threatLookingAtMe(enemies: { any }): boolean
		local me = Game.myRoot()
		if not me then
			return false
		end
		-- a blade about to strike is a threat whichever way its owner looks (the crit comes from behind)
		local mt = S.meleeThreat
		if mt and mt.dist <= mt.reach + 2 then
			return true
		end
		local cosLimit = math.cos(math.rad(cfg.autoBlockAngle))
		for _, f in ipairs(enemies) do
			local r = Game.fighterBody(f)
			if r then
				local d = r.Position - me.Position
				if d.Magnitude <= cfg.autoBlockRange then
					local item = Game.enemyEquipped(f)
					local hasGun = item == nil or (type(item.Info) == "table" and item.Info.Type == "Gun")
					if hasGun then
						local look = Game.enemyLook(f)
						if look and look:Dot(-d.Unit) >= cosLimit then
							return true
						end
					end
				end
			end
		end
		return false
	end
	function Combat.updateAutoBlock(enemies: { any })
		local bp = Game.weaponProfile()
		local want = cfg.autoBlock and not S.menuOpen and (bp.melee or bp.shield) and Combat.threatLookingAtMe(enemies)
		if want and not blocking then
			blocking = true
			Input.setRightMouse(true)
		elseif not want and blocking then
			blocking = false
			Input.setRightMouse(false)
		end
		S.blocking = blocking
	end
	-- is the enemy's blade actually deflecting right now (or did it just)? Reads the item's own state
	-- flags / tick()-stamped deflect cooldown — a blade merely being out never holds our fire.
	local bladeFieldsLogged: { [string]: boolean } = {}
	Combat.bladeFieldsLoggedN = 0
	Combat.DEFLECT_FLAGS = { "IsDeflecting", "IsBlocking", "_is_deflecting", "_is_blocking", "Deflecting", "Blocking" }
	Combat.DEFLECT_GET_KEYS = { "IsDeflecting", "Deflecting", "IsBlocking", "Blocking", "Deflect", "Block" }
	Combat.DEFLECT_STAMPS = { "_deflect_cooldown", "_deflect_start", "_deflect_time", "_block_cooldown", "_last_deflect" }
	-- the six replicated Get() probes run at 10 Hz per item, not per frame (the flags cannot flip
	-- faster than the deflect animation anyway); the result is held between probes
	Combat.deflectProbe = setmetatable({}, { __mode = "k" })
	function Combat.enemyDeflecting(fighter: any): boolean
		local item = Game.enemyEquipped(fighter)
		if type(item) ~= "table" then
			return false
		end
		local info = item.Info
		if type(info) ~= "table" or info.Type == "Gun" then
			return false
		end
		local nm = tostring(item.Name)
		if not bladeFieldsLogged[nm] and Combat.bladeFieldsLoggedN < 32 then
			bladeFieldsLogged[nm] = true
			Combat.bladeFieldsLoggedN += 1
			local fs = {}
			for k, v in pairs(item) do
				if type(v) ~= "function" and type(v) ~= "table" and typeof(v) ~= "Instance" then
					table.insert(fs, tostring(k) .. "=" .. tostring(v))
				end
			end
			table.sort(fs)
			log("DEBUG", ("blade item %s fields: %s"):format(nm, table.concat(fs, " ")))
		end
		for _, k in ipairs(Combat.DEFLECT_FLAGS) do
			if item[k] == true then
				return true
			end
		end
		-- enemy item state is replicated through Get() (same channel as Get("Wrap")); check the
		-- deflect/block flags there too
		if type(item.Get) == "function" then
			local probe = Combat.deflectProbe[item]
			local now = os.clock()
			if not probe or now - probe.at > 0.1 then
				local hit = false
				for _, k in ipairs(Combat.DEFLECT_GET_KEYS) do
					local ok, v = pcall(item.Get, item, k)
					if ok and v == true then
						hit = true
						break
					end
				end
				probe = { at = now, hit = hit }
				Combat.deflectProbe[item] = probe
			end
			if probe.hit then
				return true
			end
		end
		local wall = tick()
		local dur = tonumber(info.DeflectDuration) or 1
		local cd = tonumber(info.DeflectCooldown) or 4
		-- Katana (logged fields): _deflect_hash / _deflect_num step on every deflect, and _deflect_cooldown is
		-- the tick() the COOLDOWN ENDS (use + DeflectCooldown). Only the DeflectDuration after the use blocks;
		-- the rest of the cooldown is the best moment to shoot (the old stamp test held fire for all ~5 s).
		local hash, num = tonumber(item._deflect_hash), tonumber(item._deflect_num)
		if hash or num then
			S.deflectSeen = S.deflectSeen or setmetatable({}, { __mode = "k" })
			local rec = S.deflectSeen[item]
			if not rec then
				S.deflectSeen[item] = { hash = hash, num = num, at = 0 }
			elseif hash ~= rec.hash or num ~= rec.num then
				rec.hash, rec.num = hash, num
				rec.at = os.clock()
			end
			rec = S.deflectSeen[item]
			if os.clock() - rec.at < dur + 0.1 then
				return true
			end
		end
		-- the stamps come from the owner's clock (tick() is timezone-local), so only a stamp that makes
		-- sense against ours counts; anything else is ignored rather than holding fire
		local ends = tonumber(item._deflect_cooldown)
		if ends and ends > wall and ends - wall <= cd + 0.5 then
			local started = ends - cd
			if wall >= started - 0.05 and wall < started + dur + 0.1 then
				return true
			end
		end
		for _, k in ipairs(Combat.DEFLECT_STAMPS) do
			local v = tonumber(item[k])
			if v and k ~= "_deflect_cooldown" and k ~= "_block_cooldown" and v <= wall and wall - v < dur + 0.1 then
				return true -- a start stamp inside the deflect window
			end
		end
		return false
	end
	function Combat.katanaHoldFire(): boolean
		if not cfg.katanaCheck or not S.silentFighter then
			return false
		end
		local me = Game.myRoot()
		local r = Game.fighterBody(S.silentFighter)
		if not (r and me) or (r.Position - me.Position).Magnitude > 60 then
			return false
		end
		return Combat.enemyDeflecting(S.silentFighter)
	end

	-- auto shoot: hold or tap while a lock is valid; autokill/peek force hold. If the pressed trigger
	-- produces no shot for 0.7 s (no redirect, ammo unchanged) we escalate to Gun:StartShooting.
	local autoShooting = false
	local lastAutoShot = 0
	local fireWatch: any = nil
	local lastDirect = 0
	-- Direct (item:StartShooting) is NOT on the ladder any more: the decompiled Gun.StartShooting only
	-- animates and *returns* the camera data — ClientFighter:Input is what replicates it. A direct
	-- call fires client-side only (that was "auto shoot stays client-side"). Executor clicks need
	-- mouse1press, which not every executor has.
	local FIRE_LADDER = if EXEC.caps.mouse then { "game", "vim", "executor" } else { "game", "vim" }
	local fireLevel = 1 -- Auto climbs this ladder when a rung produces no shot
	Combat.FIRE_METHOD = { Game = "game", VIM = "vim", Executor = "executor", Direct = "direct" }
	local function fireMethodNow(): string
		local fixed = Combat.FIRE_METHOD[cfg.fireMethod]
		if fixed then
			return fixed
		end
		return FIRE_LADDER[math.clamp(fireLevel, 1, #FIRE_LADDER)]
	end
	-- a rung that produced a shot (or a new round) puts Auto back on the game path: one transient
	-- failure used to demote the trigger to VIM / executor clicks for the rest of the session
	function Combat.resetFireLadder(why: string?)
		if fireLevel ~= 1 then
			fireLevel = 1
			log("INFO", "trigger: back to the game input path" .. (if why then " (" .. why .. ")" else ""))
		end
	end
	-- shotguns and snipers keep their real cadence under rapid fire: the duel log had a shotgun at ×0.05
	-- feeding rounds the server dropped while magic held the body in the open
	Combat.rapidItem = { Name = "", Info = nil }
	Combat.rapidProf = {}
	function Combat.rapidExempt(info: any, name: string?): boolean
		if type(info) ~= "table" or info.Type ~= "Gun" then
			return false
		end
		local it = Combat.rapidItem
		it.Name, it.Info = name or "", info
		local c = Game.profileOf(it, Combat.rapidProf).class
		it.Info = nil
		-- v6.3: shotguns and snipers join rapid fire behind the per-drop learner (start ×0.9, floor ×0.6);
		-- the hold-type flamethrower keeps its own cadence
		if cfg.rapidAdaptive then
			return c == "flamethrower"
		end
		return c == "shotgun" or c == "sniper"
	end
	-- interval between our trigger pulls. Server-safe (default) = the weapon's ORIGINAL cooldown even
	-- with rapid fire on: anything faster is a shot the server never accepts (client-side only).
	local function directCooldown(item: any): number
		local cd = 0.1
		if type(item) == "table" and type(item.Info) == "table" then
			local orig = S.statOriginals[tostring(item.Name)]
			if item.Info.Type ~= "Gun" then
				-- melee: Melee.StartShooting stamps _attack_cooldown from AttackCooldown / BurstCooldown
				local burst = tonumber(item.Info.BurstCount) or 1
				local base = tonumber(item.Info.AttackCooldown) or 0.5
				if burst > 1 then
					base += (tonumber(item.Info.BurstCooldown) or 0) * (burst - 1)
				end
				return math.max(base, 0.05)
			end
			-- the ORIGINAL cooldown × the adaptive rapid-fire multiplier (never the raw slider: the
			-- server-safe cadence is whatever the learned floor says this server accepts)
			cd = tonumber(if orig and orig.ShootCooldown then orig.ShootCooldown else item.Info.ShootCooldown) or cd
			if cfg.rapidFire and not Combat.rapidExempt(item.Info, tostring(item.Name)) then
				cd *= if cfg.autoShootServerSafe then Combat.rapidServerMult(tostring(item.Name)) else Combat.rapidMult(tostring(item.Name))
			end
			local burst = tonumber(item.Info.BurstCount) or 1
			if burst > 1 then
				cd += (tonumber(item.Info.BurstCooldown) or 0) * (burst - 1)
			end
		end
		return math.max(cd, 0.03)
	end
	local function directShot()
		local gs = S.gameState
		local item = gs and gs.item
		if type(item) ~= "table" or type(item.StartShooting) ~= "function" then
			return
		end
		local now = os.clock()
		if now - lastDirect < directCooldown(item) then
			return
		end
		if gs.ammo ~= nil and gs.ammo <= 0 then
			return
		end
		lastDirect = now
		S.spoofUntil = now + 0.6
		S.ourShotUntil = now + 0.15
		S.firing = true
		local ok, err = Game.asGame(item.StartShooting, item)
		if not ok then
			S.hookErr("direct fire", err)
		end
	end
	-- the item's own "a round left" stamps (set client-side the instant it fires): the watch's surest sign
	function Combat.shotStamp(item: any): number
		if type(item) ~= "table" then
			return 0
		end
		return (tonumber(rawget(item, "_last_shot")) or 0) + (tonumber(rawget(item, "_last_attack")) or 0)
	end
	local function startWatch()
		local gs = S.gameState
		fireWatch = { t = os.clock(), shots = S.shotStats.redirected, ammo = gs and gs.ammo, claims = S.shots and S.shots.n or 0, gate = Combat.fireStats.sent + Combat.fireStats.client + Combat.fireStats.held, stamp = Combat.shotStamp(gs and gs.item), item = gs and gs.item }
	end
	-- v4 trigger gate: fire exactly when the item says it can (tick-stamped _shoot_cooldown), never
	-- while it is queueing an input itself, and — for scoped weapons — only once fully aimed in
	-- (the server applies the un-aimed spread otherwise, which is why snipers missed).
	local reactAt: number? = nil
	-- per weapon, how the server gets a tight cone: "claim" = the payload says fully aimed (the aimed
	-- cone on every shot, no scope needed) or "real" = we scope in and fire only once the gun is really
	-- fully aimed. Snipers start on real aim (claimed unscoped shots connected ~2 %); the shot log moves
	-- a claim weapon to real aim when its spread misses pile up (Combat.spreadLearn).
	function Combat.spreadModeFor(item: any): string
		local info = type(item) == "table" and item.Info
		if type(info) ~= "table" or info.Type ~= "Gun" then
			return "claim"
		end
		-- a scoped gun never claims full aim it does not have: the server applied the hip-fire cone to
		-- every claimed-but-unscoped sniper round (17itl: UNAIMED shots 360–400 st off). It scopes for real.
		if info.AimScopePercent ~= nil then
			return "real"
		end
		local m = cfg.spreadMode
		if m == "Claim" then
			return "claim"
		elseif m == "Real aim" then
			return "real"
		end
		local learned = cfg.spreadLearned[tostring(item.Name)]
		if learned == "real" or learned == "claim" then
			return learned
		end
		return if info.AimScopePercent ~= nil then "real" else "claim"
	end
	S.spreadModeFor = Combat.spreadModeFor
	-- one answered claim-mode shot fired while not really aimed: spread misses (NEAR / AIR) piling up
	-- on a weapon mean the server is not taking the claim for it → real aim for that weapon
	Combat.spreadRing = {}
	function Combat.spreadLearn(weapon: string, verdict: string)
		if cfg.spreadMode ~= "Auto" or type(weapon) ~= "string" or cfg.spreadLearned[weapon] ~= nil then
			return
		end
		if verdict ~= "HIT" and verdict ~= "NEAR" and verdict ~= "AIR" and verdict ~= "WALL" then
			return
		end
		local ring = Combat.spreadRing[weapon]
		if not ring then
			ring = {}
			Combat.spreadRing[weapon] = ring
		end
		table.insert(ring, verdict)
		if #ring > 20 then
			table.remove(ring, 1)
		end
		if #ring < 12 then
			return
		end
		local hit, spreadMiss = 0, 0
		for _, v in ipairs(ring) do
			if v == "HIT" then
				hit += 1
			elseif v == "NEAR" or v == "AIR" then
				spreadMiss += 1
			end
		end
		local n = #ring
		if hit / n < 0.25 and spreadMiss >= (n - hit) * 0.5 then
			cfg.spreadLearned[weapon] = "real"
			table.clear(ring)
			saveConfigSoon()
			log("WARN", ("spread: %s — %d of %d claimed shots hit, most misses were spread → real aim (scope in) for this weapon"):format(weapon, hit, n))
			task.defer(function()
				if S.alive then
					notify(weapon .. ": switched to real aim — it scopes in before firing now", 4, "info")
				end
			end)
		end
	end
	function Combat.triggerReady(item: any, now: number): boolean
		if type(item) ~= "table" then
			return false
		end
		local info = item.Info
		-- v6.7 rapid melee lives in the stats (Combat.MELEE_KEYS scaled by the slider → the game's own
		-- _attack_cooldown stamp) and the fire gate (the server's share): the stamp below paces it
		-- guns stamp _shoot_cooldown, melee stamps _attack_cooldown (both tick()-based)
		local stamp = if cfg.autoShootCooldownSync then (tonumber(rawget(item, "_shoot_cooldown")) or tonumber(rawget(item, "_attack_cooldown"))) else nil
		if stamp then
			if tick() < stamp or rawget(item, "_is_input_queueing") == true then
				S.triggerWait = "cooldown"
				return false
			end
			-- a burst weapon needs its burst cooldown too; the stamp already covers it
		elseif now - lastDirect < directCooldown(item) then
			S.triggerWait = "cooldown"
			return false
		end
		-- scoped-weapon aim wait: only when we are actually driving ADS ourselves (auto-aim ADS on, or
		-- the player is already aiming). Otherwise a sniper on manual aim would be gated forever and
		-- "never shoot". We push ADS to reach full zoom, but give up after 0.5 s so a shot still goes.
		-- v5.0.3: with the spread claim hooked the server applies the AIMED cone to every shot of ours
		-- whether or not we are scoped — the scope wait (up to 0.9 s per shot on a sniper) buys nothing
		local mode = Combat.spreadModeFor(item)
		local claimLive = mode == "claim" and cfg.spreadClaimAim and S.hooks.installed.spreadClaim == true
		local sniper = type(info) == "table" and info.AimScopePercent ~= nil
		local scoped = type(info) == "table" and (sniper or mode == "real")
		if (cfg.autoShootWaitAim or sniper) and not claimLive and scoped and type(item.IsFullyAiming) == "function" then
			-- real-aim weapons (snipers by default): we scope in ourselves — an unscoped shot carries the
			-- full spread server-side, which is most "sniper misses"
			local drivingAds = mode == "real" or cfg.autoShootScopeSnipers or cfg.autoShootAimMode == "ADS" or cfg.autoShootAimMode == "ADS + Camera"
			local playerAiming = S.gameState and S.gameState.aiming == true
			if drivingAds or playerAiming then
				-- v5: the spread-claim hook makes item:IsFullyAiming() answer true for our guns — the scope
				-- push must read the REAL answer or auto-scope never scopes (the v5.0.0 "doesn't auto scope")
				local aimed: boolean? = nil
				if type(S.h.realFullyAiming) == "function" then
					aimed = S.h.realFullyAiming(item)
				end
				if aimed == nil then
					local ok, a = pcall(item.IsFullyAiming, item)
					aimed = ok and a == true
				end
				if aimed ~= true then
					if now - (S.adsPushAt or 0) > 0.15 then
						S.adsPushAt = now
						S.waitAimAds = true
						Input.setAds(true, true)
					end
					S.aimWaitSince = S.aimWaitSince or now
					-- give the scope its full time (AimSpeed-scaled) before ever firing unscoped; a sniper
					-- never fires unscoped (the hip cone is the 17itl UNAIMED AIRs)
					local limit = if sniper then math.huge elseif cfg.autoShootScopeSnipers or mode == "real" then 0.9 else 0.5
					if now - S.aimWaitSince < limit then
						S.triggerWait = "aim"
						return false
					end
				else
					S.aimWaitSince = nil
				end
			end
		end
		if cfg.autoShootReactionMs > 0 then
			if not reactAt then
				reactAt = now + math.random() * cfg.autoShootReactionMs / 1000
			end
			if now < reactAt then
				S.triggerWait = "reaction"
				return false
			end
		end
		reactAt = nil
		S.aimWaitSince = nil
		S.triggerWait = nil
		return true
	end
	-- one shot through the game's own path: StartShooting now, FinishShooting 30 ms later (exactly what
	-- MechanicsController._ToggleAutoShoot does; hold-type items like the Flamethrower stay held)
	-- damage one round does to the locked part right now (crit for the head); nil = unknown
	function Combat.shotDamage(): number?
		local gs = S.gameState
		local info = gs and gs.item and gs.item.Info
		if type(info) ~= "table" then
			return nil
		end
		local part = S.silentPart
		local isHead = part ~= nil and part.Name:find("Head", 1, true) ~= nil
		if info.Type ~= "Gun" then
			local base = tonumber(info.AttackDamage) or tonumber(info.Damage)
			return base
		end
		local dmg = tonumber(info.ShootDamage)
		if not dmg then
			return nil
		end
		local pellets = tonumber(info.ShootPellets) or 1
		local per = if isHead then (tonumber(info.CriticalDamage) or dmg) else dmg
		-- shotguns: count on ~60 % of the pellets so the kill-confirm hold never waits on a miss
		return per * math.max(1, math.ceil(pellets * 0.6))
	end
	-- v5 hitscan: the server fires along the rotation it last stored from UpdateCameraRotation. The
	-- pitch/yaw that points the shot origin at the locked part is what we must have echoed before we
	-- pull. wantedShotRot = that angle; echoAligned = the server already holds it (within one 1.4°
	-- quantisation step); refreshEcho reads the server's stored value fast while we are engaging.
	-- the stream's origin (h.lockOrigin: the floor / wall push when the lock has one)
	function Combat.lockOrigin(): Vector3?
		local lo = S.h and S.h.lockOrigin
		return if type(lo) == "function" then lo() else Game.shotOriginPos()
	end
	function Combat.wantedShotRot(): Vector2?
		local part = S.silentPart
		local from = Combat.lockOrigin()
		if typeof(part) ~= "Instance" or not part.Parent or not from then
			return nil
		end
		-- the echo must match the LED rotation the stream sends (see Combat.ledAim / h.rot)
		local lk = CFrame.lookAt(from, Combat.ledAim(part, part.Position))
		local p, y = lk.ToOrientation(lk) -- index + call, not a namecall (hook-reachable)
		return Vector2.new(p, y)
	end
	Combat.echoReadAt = 0
	function Combat.refreshEcho()
		local now = os.clock()
		if now - Combat.echoReadAt < 0.03 then
			return
		end
		Combat.echoReadAt = now
		local lf = Game.localFighter()
		local ok, echo = pcall(function()
			return lf and lf:Get("CameraRotation")
		end)
		if ok and typeof(echo) == "Vector2" then
			S.aaServerRot = echo
		end
	end
	-- every rotation that reaches the server, lock-facing or not (Combat.sendRotation and the game's own
	-- send through h.replicatedPayload): a lock-facing one is kept a moment; any other angle replaces the
	-- lock on the server (Combat.fakeSentAt). Table ops and os.clock only — safe inside the namecall hook.
	Combat.lockSent = {}
	Combat.fakeSentAt = 0
	function Combat.noteSent(rot: Vector2, lockFacing: boolean)
		local now = os.clock()
		if not lockFacing then
			Combat.fakeSentAt = now
			return
		end
		local L = Combat.lockSent
		table.insert(L, { rot = rot, t = now })
		if #L > 48 then
			table.remove(L, 1)
		end
	end
	function Combat.echoAligned(): boolean
		local echo = S.aaServerRot
		if typeof(echo) ~= "Vector2" then
			return false
		end
		-- v6.3 geometric test: does the ray the server holds (our shot origin along its stored rotation)
		-- pass through the locked hitbox? The old angle test also demanded a lock send younger than 1.5 s,
		-- and against a still target the stream stops re-sending an unchanged angle — a server holding our
		-- exact lock angle (0.3° off) timed out into "[shot:sync-cap] firing anyway" 732 times.
		local part = S.silentPart
		local from = Combat.lockOrigin()
		if typeof(part) == "Instance" and part.Parent and from then
			local aim = Combat.ledAim(part, part.Position)
			local dir = CFrame.fromOrientation(echo.X, echo.Y, 0).LookVector
			local rel = aim - from
			-- no `:Dot()` — this runs inside the namecall hook (h.claimReady), where a method call clobbers
			-- the pending method name on some executors
			local along = rel.X * dir.X + rel.Y * dir.Y + rel.Z * dir.Z
			if along <= 0 then
				return false
			end
			local sz = part.Size
			-- inside the hitbox, or within half a quantisation step at this range (the finest the channel can aim)
			local tol = math.max(0.45 * math.min(sz.X, sz.Y, sz.Z), 0.5, along * (math.pi / 256))
			if (rel - dir * along).Magnitude <= tol then
				return true
			end
			-- v6.7: a miss here is not the end — against a moving target the one-trip-old echo trails the
			-- hitbox by speed × round trip and failed this test on every engagement (798 sync-caps in the
			-- log: the first round of every lock and after every magic hop waited the whole cap). The
			-- stream test below still decides it.
		end
		local step = (2 * math.pi / 256) * 1.5 -- within ~2° (one quantisation step + slack)
		local want = Combat.wantedShotRot()
		if want and math.abs(Combat.yawDelta(echo.X, want.X)) <= step and math.abs(Combat.yawDelta(echo.Y, want.Y)) <= step then
			return true
		end
		-- the echo is one trip old: against a moving target (or while we move) it never equals the angle
		-- wanted this frame. The server holding one of the lock-facing rotations we streamed after the last
		-- other angle — and after the last hop, so it was aimed from where the body is now — means it
		-- follows the stream, and the stream keeps it on the lock.
		local now = os.clock()
		local L = Combat.lockSent
		local after = math.max(Combat.fakeSentAt, S.lastTeleportAt or 0)
		for i = #L, 1, -1 do
			local e = L[i]
			if e.t <= after or now - e.t > 1.5 then
				break
			end
			if math.abs(Combat.yawDelta(echo.X, e.rot.X)) <= step and math.abs(Combat.yawDelta(echo.Y, e.rot.Y)) <= step then
				return true
			end
		end
		return false
	end
	-- v6.1: the server fires along the rotation it last STORED, not the payload's (17itl duel: the first
	-- rounds of every engagement flew 360–400 st along the anti-aim yaw). The first shot on a fighter
	-- waits until the server echoes the lock-facing rotation — a round trip, capped a little above it.
	-- Once echoed the stream keeps facing that fighter and the rest go at once; a fake yaw sent in
	-- between (Combat.updateAA) clears the sync. Flick AA re-syncs every shot.
	function Combat.syncReady(f: any, since: number): boolean
		local flick = cfg.aaFlick and cfg.aaEnabled
		if f ~= nil and S.syncDoneFor == f and not flick then
			return true
		end
		Combat.refreshEcho()
		local now = os.clock()
		-- a hop re-arms the sync (markTeleport): its wait counts from the hop, not from the engagement
		local waited = now - math.max(since, S.lastTeleportAt or 0)
		local rtt = (S.pingMs or 0) / 1000
		local aligned = Combat.echoAligned()
		-- v6.3: a slow / one-shot gun never "fires anyway" along a stale angle (the whole cycle is lost to
		-- a wall); a fast gun may after one full round trip. The hard 2.5 s fallback only guards a server
		-- that stopped echoing altogether.
		local slow = S.slowGunNow == true
		-- slow guns wait at most ~1.5 trips (the 2.5 s floor of 6.3 left snipers standing on a clear shot)
		local cap = if slow then math.max(0.6, rtt * 1.5 + 0.15) else math.max((cfg.autoShootLeadMaxMs or 320) / 1000, rtt + 0.12)
		if not aligned and now - (Combat.aaSentAt or 0) > math.max(0.08, rtt * 0.5) then
			-- the stream may have gone quiet on an unchanged angle, or we just hopped: push the lock angle again
			Combat.sendRotation(nil)
		end
		local ready = (waited >= 0.02 and aligned) or waited >= cap
		if ready and f ~= nil then
			S.syncDoneFor = f
			if waited >= cap and not aligned and now - (Combat.syncCapLogAt or 0) > 1 then
				Combat.syncCapLogAt = now
				log("DEBUG", ("[shot:sync-cap] no echo of the lock rotation in %.0f ms (ping %d%s) — firing anyway · %s"):format(cap * 1000, S.pingMs or 0, if slow then ", slow gun" else "", Combat.echoDiag()))
			end
		end
		return ready
	end
	-- for the sync-cap line: how many lock-facing rotations went out since the last other angle, how old
	-- the newest is, and how far the server's echo sits from the closest of them
	function Combat.echoDiag(): string
		local echo = S.aaServerRot
		local now = os.clock()
		local L = Combat.lockSent
		local n, newest, best = 0, nil, math.huge
		for i = #L, 1, -1 do
			local e = L[i]
			if e.t <= Combat.fakeSentAt then
				break
			end
			n += 1
			newest = newest or e.t
			if typeof(echo) == "Vector2" then
				best = math.min(best, math.max(math.abs(Combat.yawDelta(echo.X, e.rot.X)), math.abs(Combat.yawDelta(echo.Y, e.rot.Y))))
			end
		end
		return ("lock sends %d since the last other angle (%.0f ms ago), newest %s, echo off by %s"):format(
			n, (now - Combat.fakeSentAt) * 1000,
			if newest then ("%.0f ms ago"):format((now - newest) * 1000) else "—",
			if best < math.huge then ("%.1f°"):format(math.deg(best)) else "—"
		)
	end
	Combat.lastShotAtFighter = setmetatable({}, { __mode = "k" })
	-- v5.0.3 god-speed fire for automatic weapons: the game's own held-LMB loop (MechanicsController
	-- _InputSpam, decompiled) calls EquippedItemInput("StartShooting") EVERY FRAME while
	-- InputSpammingEnabled.StartShooting is set, and Gun.StartShooting queues any call that lands ≤100 ms
	-- before the cooldown edge to fire exactly on it. Our pulse path (Start → Finish 30 ms → read the
	-- stamp next frame → pulse) measured 6 pulls/s on a 60 ms cooldown. So: same as the game — one
	-- StartShooting per frame while engaged, FinishShooting once on release; shots are counted by the
	-- cooldown stamp moving, and the target-facing rotation goes out (twice, unreliable channel) in the
	-- last 30 ms before each edge.
	Combat.profScratch = {}
	function Combat.spammable(item: any): boolean
		if cfg.autoShootSpam == false or type(item) ~= "table" then
			return false
		end
		-- v5.0.4: the per-frame StartShooting cadence turns a semi-auto (Wildcat, Handgun, Revolver,
		-- shotgun) into a full dump at its server cadence. v6.1: not a sniper (it waits for its real scope
		-- on the pulse path — an unscoped round carries the hip cone), not a burst rifle (one pulse = one
		-- burst, the stamp covers the burst cooldown), not the flamethrower (a held trigger).
		local c = Game.profileOf(item, Combat.profScratch).class
		return c == "rifle" or c == "shotgun" or c == "projectile"
	end
	Combat.spamHeld = false
	Combat.spamStamp = 0
	local function spamCount(item: any, now: number)
		-- a shot = the cooldown stamp moved forward (this frame, or a queued one that fired between frames)
		local stamp = tonumber(rawget(item, "_shoot_cooldown")) or 0
		if stamp ~= Combat.spamStamp then
			if Combat.spamStamp ~= 0 and stamp > tick() - 0.05 then
				lastDirect = now
				S.lastShotWindowAt = now
				S.pulses = (S.pulses or 0) + 1
				Combat.semiFinishDue = true -- a semi-auto needs FinishShooting before its next Start counts
				if S.silentFighter then
					Combat.lastShotAtFighter[S.silentFighter] = now
				end
				if cfg.aaFlick and cfg.aaEnabled then
					S.syncSince = now
				end
			end
			Combat.spamStamp = stamp
		end
		return stamp
	end
	function Combat.spamFire(item: any, now: number)
		local stamp0 = spamCount(item, now)
		local untilEdge = stamp0 - tick()
		-- the fire ladder reads S.triggerWait: on cooldown is not "this rung produced no shot"
		S.triggerWait = if untilEdge > 0.02 then "cooldown" else nil
		local ise = item.Info and item.Info.InputSpammingEnabled
		local spamFlag = type(ise) == "table" and ise.StartShooting or nil
		local auto = spamFlag ~= nil and spamFlag ~= false
		if not auto then
			-- v5.0.4 semi-autos (Handgun, Sniper, Burst Rifle, Revolver, Shotgun…): the fighter's Input
			-- ignores a second StartShooting until a FinishShooting has been seen (a Burst Rifle fired 0
			-- rounds in 4 s on the per-frame path). So: Start pre-queued up to 90 ms before the edge
			-- (Gun.StartShooting queues it and fires exactly on the edge), one Finish the frame after the
			-- round left, next Start — the cadence is the cooldown itself, never our frame timing.
			Combat.spamHeld = true
			Input.fireMethodUsed = "game (edge)"
			if untilEdge < 0.1 then
				S.stillUntil = now + 0.1 + math.max(untilEdge, 0)
				Combat.stillShot(now)
			end
			if Combat.semiFinishDue then
				Combat.semiFinishDue = false
				Input.gameInput("FinishShooting")
			elseif untilEdge <= 0.09 and rawget(item, "_is_input_queueing") ~= true then
				Input.gameInput("StartShooting")
			end
			spamCount(item, now)
			return
		end
		-- automatics: InputSpammingEnabled.StartShooting > 0 is the game's own interval between spam calls
		-- (0 = every frame)
		local interval = tonumber(spamFlag) or 0
		if interval > 0 and now - (Combat.spamCallAt or 0) < interval and untilEdge > 0.1 then
			return
		end
		Combat.spamCallAt = now
		if cfg.silentSpoofServer and S.silentTarget ~= nil and untilEdge < 0.03 then
			Combat.sendRotation(nil)
			Combat.sendRotation(nil)
		end
		if untilEdge < 0.06 then
			S.stillUntil = now + 0.1
			Combat.stillShot(now)
		end
		Combat.spamHeld = true
		Input.fireMethodUsed = "game (spam)"
		Input.gameInput("StartShooting")
		spamCount(item, now)
	end
	function Combat.pulse(item: any)
		local now = os.clock()
		lastDirect = now
		S.spoofUntil = now + 0.6
		S.ourShotUntil = now + 0.15
		S.firing = true
		S.lastShotWindowAt = now
		if S.silentFighter then
			Combat.lastShotAtFighter[S.silentFighter] = now
		end
		if cfg.aaFlick and cfg.aaEnabled then
			S.syncSince = now -- the next pull re-syncs the rotation from the fake angle (echo gate)
		end
		Input.fireMethodUsed = "game"
		-- the server computes velocity spread from RootPart.Velocity around the shot: stand still for
		-- this frame and the next few (Combat.stillShot runs every frame inside the window)
		S.stillUntil = now + 0.1
		Combat.stillShot(now)
		-- a melee swing is judged by the 90° cone from the camera data it carries: face the lock for the
		-- input (Combat.facingInput restores the view the same frame)
		local info = type(item) == "table" and item.Info
		if type(info) == "table" and info.Type ~= "Gun" and cfg.meleeFaceOnSwing then
			Combat.facingInput("StartShooting")
		else
			-- the server shoots along the last rotation it received: hand it the target-facing one first —
			-- twice, UpdateCameraRotation is an UnreliableRemoteEvent and a dropped copy is a shot along
			-- the previous angle
			if cfg.silentSpoofServer and S.silentTarget ~= nil then
				Combat.sendRotation(nil)
				Combat.sendRotation(nil)
			end
			Input.gameInput("StartShooting")
		end
		local holdType = type(item) == "table" and item.Name == "Flamethrower"
		if cfg.autoShootPulse and not holdType then
			task.delay(0.03, function()
				if S.alive then
					Input.gameInput("FinishShooting")
				end
			end)
		end
	end
	-- Legit triggerbot: presses the trigger only while the REAL crosshair (a camera-centre ray through the
	-- game's own whitelist) sits on a visible enemy hitbox, after a reaction delay and a per-target
	-- hit-chance roll. Your aim decides everything: no silent lock, no spoof window, no raycast redirect,
	-- no teleport — a plain EquippedItemInput press paced by the gun's own cooldown stamp. A scoped gun
	-- fires only while really scoped, and never on a spam cadence.
	Combat.lt = { fighter = nil, onAt = 0, roll = true, lastAt = 0, why = nil }
	function Combat.crosshairTarget(targets: { any }): (any, BasePart?, Model?)
		local cam = workspace.CurrentCamera
		local params = Game.losParams()
		if not (cam and params) then
			return nil, nil, nil
		end
		local cf = cam.CFrame
		local hit = workspace:Raycast(cf.Position, cf.LookVector * cfg.targetMaxDistance, params)
		if not hit then
			return nil, nil, nil
		end
		local inst = hit.Instance
		for _, f in ipairs(targets) do
			local _, model = Game.fighterBody(f)
			if model and inst:IsDescendantOf(model) and not Target.isDead(f) and not Game.isShieldPart(inst, model) then
				return f, inst :: BasePart, model
			end
		end
		return nil, nil, nil
	end
	function Combat.legitReady(item: any, now: number): boolean
		local stamp = tonumber(rawget(item, "_shoot_cooldown"))
		if stamp and (tick() < stamp or rawget(item, "_is_input_queueing") == true) then
			return false
		end
		if now - Combat.lt.lastAt < 0.06 then
			return false -- one press per window even when the stamp is unreadable
		end
		local info = item.Info
		if type(info) == "table" and info.AimScopePercent ~= nil and type(item.IsFullyAiming) == "function" then
			local aimed = if type(S.h.realFullyAiming) == "function" then S.h.realFullyAiming(item) else nil
			if aimed == nil then
				local ok, a = pcall(item.IsFullyAiming, item)
				aimed = ok and a == true
			end
			if aimed ~= true then
				Combat.lt.why = "not scoped"
				return false
			end
		end
		return true
	end
	function Combat.updateLegitTrigger(targets: { any })
		local L = Combat.lt
		if not cfg.legitTrigger or S.menuOpen or S.hudEdit or not S.alive or not S.charAlive then
			L.fighter = nil
			return
		end
		-- silent lock owns the fight: legit trigger only when silent auto-shoot is not active
		if cfg.silentAim and cfg.autoShoot and S.silentTarget ~= nil then
			L.fighter = nil
			return
		end
		local prof = Game.weaponProfile()
		local item = prof.item
		local info = type(item) == "table" and item.Info
		if type(info) ~= "table" or not prof.gun or prof.projectile or S.silentSuspended then
			L.fighter, L.why = nil, if prof.projectile then "projectile guns not supported" elseif S.silentSuspended then "utility in use" else "no gun out"
			return
		end
		if cfg.legitTriggerMode == "Hold key" and not Input.isKeyDown(cfg.legitTriggerKey) then
			L.fighter, L.why = nil, "hold the trigger key"
			return
		end
		L.why = nil
		local f, part, model = Combat.crosshairTarget(targets)
		local now = os.clock()
		local fromT = Game.shotOriginPos()
		if not (f and part and model and Game.rayVisible(model, part, fromT)) then
			L.fighter = nil
			return
		end
		if fromT and (part.Position - fromT).Magnitude > cfg.legitTriggerMaxDist then
			L.fighter, L.why = nil, "too far"
			return
		end
		if cfg.legitTriggerStill then
			local myRoot = S.myRootPart
			if myRoot and myRoot.Parent and myRoot.AssemblyLinearVelocity.Magnitude > 4 then
				L.why = "you are moving"
				return
			end
		end
		-- hitbox filter: the part under the crosshair (HitboxHead / Head vs everything else)
		local isHead = part.Name == "HitboxHead" or part.Name == "Head"
		if (cfg.legitTriggerHitbox == "Head" and not isHead) or (cfg.legitTriggerHitbox == "Body" and isHead) then
			L.fighter, L.why = nil, "not the chosen hitbox"
			return
		end
		if f ~= L.fighter then
			L.fighter, L.onAt = f, now
			L.roll = math.random(1, 100) <= cfg.legitTriggerChance
		end
		if not L.roll or now - L.onAt < cfg.legitTriggerDelayMs / 1000 or not Combat.legitReady(item, now) then
			return
		end
		local gs = S.gameState
		if gs and gs.ammo == 0 then
			if (gs.reserve or 0) > 0 then
				L.why = "reloading"
				if cfg.autoReload and os.clock() - (S.autoReloadAt or 0) > 1 and os.clock() >= (S.reloadUntil or 0) then
					S.autoReloadAt = os.clock()
					Input.gameInput("StartReloading")
				end
			else
				L.why = "no ammo"
			end
			return
		end
		L.lastAt = now
		S.firing = true
		S.ourShotUntil = now + 0.15
		S.lastShotWindowAt = now
		Input.fireMethodUsed = "game"
		S.stillUntil = now + 0.1
		Combat.stillShot(now)
		Input.gameInput("StartShooting")
		local holdType = type(item) == "table" and item.Name == "Flamethrower"
		if cfg.autoShootPulse and not holdType then
			task.delay(0.03, function()
				if S.alive then
					Input.gameInput("FinishShooting")
				end
			end)
		end
	end
	-- spread-based hit chance: the weapon's spread cone (degrees, as the game would apply it right now)
	-- against the angle the locked hitbox subtends from the muzzle. 100 when no spread survives.
	function Combat.currentSpreadDeg(): number
		local gs = S.gameState
		local item = gs and gs.item
		local info = type(item) == "table" and item.Info
		if type(info) ~= "table" then
			return 0
		end
		local name = tostring(item.Name)
		local orig = S.statOriginals[name] or {}
		local spread = if cfg.noSpread then 0 else (tonumber(info.ShootSpread) or tonumber(orig.ShootSpread) or 0)
		if spread > 0 then
			-- v5: the aim claim hands the server AimSpreadMultiplier on every shot (0 on most guns), so the
			-- cone the server really applies is the aimed one whether or not we are scoped in
			local claimed = cfg.spreadClaimAim and S.hooks.installed.spreadClaim == true and Combat.spreadModeFor(item) == "claim"
			if gs.aiming or claimed then
				spread *= tonumber(if cfg.noSpread then 0 else (orig.AimSpreadMultiplier or info.AimSpreadMultiplier or 1)) or 1
			end
			local me = Game.myRoot()
			local perUnit = tonumber(if cfg.noSpread then 0 else (info.ShootSpreadPerVelocityUnit or orig.ShootSpreadPerVelocityUnit or 0)) or 0
			local limit = tonumber(info.ShootSpreadPerVelocityLimit or orig.ShootSpreadPerVelocityLimit or 0) or 0
			if me and perUnit > 0 then
				spread += math.min(me.AssemblyLinearVelocity.Magnitude * perUnit, if limit > 0 then limit else math.huge)
			end
		end
		return spread
	end
	function Combat.hitChance(): number
		local part = S.silentPart
		local target = S.silentTarget
		if not (target and part and part.Parent) then
			return 0
		end
		local spread = Combat.currentSpreadDeg()
		if spread <= 0.01 then
			return 100
		end
		-- measured from where the shot really leaves (same origin as dynamicPart)
		local from = Game.shotOriginPos()
		if not from then
			return 0
		end
		return Combat.hitProb(part, from, spread) * 100
	end
	S.hitChance = Combat.hitChance

	-- auto stop: kill horizontal movement while the trigger is held
	local stopping = false
	local function autoStop(on: boolean)
		if not on and not stopping then
			S.autoStopping = false
			return -- nothing to do and nothing to undo: no FindFirstChild per frame with stop mode off
		end
		local char = LP.Character
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		local root = Game.myRoot()
		if on then
			if hum then
				hum:Move(Vector3.zero, false)
			end
			if root then
				local v = root.AssemblyLinearVelocity
				root.AssemblyLinearVelocity = Vector3.new(0, v.Y, 0)
			end
			stopping = true
		elseif stopping then
			stopping = false
		end
		S.autoStopping = stopping
	end

	-- shot chance: one roll per weapon cooldown; a failed roll lifts the trigger for that window
	local chanceUntil, chanceOk = 0, true
	local function chanceAllows(): boolean
		local now = os.clock()
		if now >= chanceUntil then
			local gs = S.gameState
			chanceUntil = now + directCooldown(gs and gs.item)
			S.lastShotWindowAt = now
			chanceOk = cfg.autoShootChance >= 100 or math.random(1, 100) <= cfg.autoShootChance
		end
		return chanceOk
	end
	local function fireOn()
		local method = fireMethodNow()
		if not chanceAllows() then
			if Input.fireHeld() then
				Input.setFire(false)
			end
			S.firing = true -- the lock stays hot; only the trigger is lifted
			return
		end
		if not autoShooting then
			autoShooting = true
			startWatch()
		end
		S.firing = true
		if method == "game" then
			local gs = S.gameState
			local item = gs and gs.item
			local now = os.clock()
			if item and Combat.spammable(item) and not (gs.ammo ~= nil and gs.ammo <= 0) then
				Combat.spamFire(item, now)
			elseif item and not (gs.ammo ~= nil and gs.ammo <= 0) and Combat.triggerReady(item, now) then
				-- v4: discrete pulses at the item's own cadence, no held state to get stuck
				Combat.pulse(item)
				S.pulses = (S.pulses or 0) + 1
			end
		elseif not Input.fireHeld() and method ~= "direct" then
			Input.setFire(true, method)
		end
		if fireWatch and cfg.fireMethod == "Auto" and method ~= "direct" then
			local gs = S.gameState
			local ammoNow = gs and gs.ammo
			local fs = Combat.fireStats
			local itemNow = gs and gs.item
			if itemNow ~= fireWatch.item then
				startWatch() -- a weapon swap is not a failing rung
			elseif S.shotStats.redirected ~= fireWatch.shots or (ammoNow ~= nil and ammoNow ~= fireWatch.ammo) or (S.shots and S.shots.n ~= (fireWatch.claims or 0)) or (fs.sent + fs.client + fs.held) ~= (fireWatch.gate or 0) or Combat.shotStamp(itemNow) ~= fireWatch.stamp then
				fireWatch = nil -- this rung works
				Combat.fireRungOkAt = os.clock()
			elseif S.triggerWait ~= nil or (gs and gs.locked) or (type(itemNow) == "table" and type(itemNow.IsEquipping) == "function" and select(2, pcall(itemNow.IsEquipping, itemNow)) == true) then
				fireWatch.t = os.clock() -- waiting on cooldown / aim / reaction is not a failing rung
			elseif os.clock() - fireWatch.t > 0.7 and (ammoNow == nil or ammoNow > 0) and not (S.reloadUntil and os.clock() < S.reloadUntil) then
				if os.clock() < (Combat.ladderHoldUntil or 0) then
					startWatch() -- the ladder was just exhausted: stay on the game path for a while
				elseif fireLevel < #FIRE_LADDER then
					fireLevel += 1
					local next_ = fireMethodNow()
					log("WARN", ("auto shoot: %s produced no shot in 0.7 s → %s"):format(method, next_))
					notify(("trigger %s not registering → %s"):format(method, next_), 3, "warn")
					Input.setFire(true, next_)
					startWatch()
					method = next_
				else
					-- top rung and still nothing: say it once, keep trying quietly (the old code
					-- re-logged and re-toasted this every 0.7 s for as long as the trigger was held)
					-- no rung is observably better (the watch can be blind: shooting-range dummies, a gun
					-- whose ammo the client does not expose), so park on the game path, the one that
					-- replicates properly, instead of executor clicks for the rest of the session. INFO:
					-- the same state on 20/20 installs (Real, Potassium, Volt) was field noise, not a fault
					if not Combat.fireLadderExhaustedAt or os.clock() - Combat.fireLadderExhaustedAt > 15 then
						Combat.fireLadderExhaustedAt = os.clock()
						log("INFO", ("auto shoot: no trigger path showed a shot (%s) — back to the game input path"):format(method))
					end
					Input.setFire(false)
					fireLevel = 1
					Combat.ladderHoldUntil = os.clock() + 60
					method = fireMethodNow()
					startWatch()
				end
			end
		end
		if method == "direct" then
			directShot()
		end
		-- (the old "re-issue StartShooting every cooldown" fallback for the game method is gone: it
		-- bypassed triggerReady's cooldown stamp / scope wait / reaction and Combat.pulse's bookkeeping,
		-- and put a second and third round into every kill while the stamp still said wait)
	end
	local function fireOff()
		if Combat.spamHeld then
			Combat.spamHeld = false
			Combat.semiFinishDue = false
			Input.gameInput("FinishShooting")
		end
		if autoShooting then
			autoShooting = false
			Input.setFire(false)
			fireWatch = nil
			S.firing = UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
		end
		S.triggerWait = nil
		reactAt = nil
		-- ADS we pushed only to satisfy the scoped-weapon aim wait is let go with the trigger
		if S.waitAimAds and not S.adsHeld then
			S.waitAimAds = nil
			Input.setAds(false)
		end
	end
	function Combat.resetFireEscalation()
		Combat.resetFireLadder("manual")
	end
	S.fireLevel = function()
		return fireMethodNow()
	end
	-- still shot: the server takes velocity spread from our replicated velocity, so the body stands
	-- still for a few frames around every round (pulse / spamFire open the window), not one frame
	-- v6.7: standing still only helps where velocity spread still reaches the server — a gun whose aimed
	-- cone is not zero, or one that does not claim full aim. The claim zeroes it on most guns, and a walking
	-- player with an automatic was frozen every 0.1 s for nothing ("auto shoot is choppy").
	function Combat.stillWorth(): boolean
		local gs = S.gameState
		local item = gs and gs.item
		local info = type(item) == "table" and item.Info
		if type(info) ~= "table" or info.Type ~= "Gun" then
			return false
		end
		local claim = cfg.spreadClaimAim and S.hooks.installed.spreadClaim == true and Combat.spreadModeFor(item) == "claim"
		local orig = S.statOriginals[tostring(item.Name)]
		local aimMult = tonumber(orig and orig.AimSpreadMultiplier) or tonumber(info.AimSpreadMultiplier) or 1
		return not claim or aimMult > 0.05
	end
	function Combat.stillShot(now: number)
		if not cfg.spreadStillShot or now >= (S.stillUntil or 0) then
			return
		end
		local me = S.myRootPart
		if me and me.Parent and (S.teleported or (S.autoEngaged and Combat.stillWorth())) then
			local v = me.AssemblyLinearVelocity
			if v.X ~= 0 or v.Z ~= 0 then
				me.AssemblyLinearVelocity = Vector3.new(0, v.Y, 0)
			end
		end
	end
	function Combat.updateAutoShoot(hasTarget: boolean)
		-- why the trigger is held back (awareness chip); a loop gate that already said no names itself
		local hold: string? = if not hasTarget then S.autoGateWhy else nil
		Combat.stillShot(os.clock())
		-- v5 pre-aim: stream the target-facing rotation to the server BEFORE we can shoot, so the echo
		-- is already aligned the instant a shot becomes possible (they peek, we hit first). On whenever
		-- a lock exists within preAimRange; the rotation channel (updateAA / h.rot) reads S.preAiming.
		if cfg.preAim and cfg.silentAim and cfg.autoShoot and S.silentTarget ~= nil and S.silentPart and not S.menuOpen then
			local from = Game.shotOriginPos()
			local d = if from then (Resolver.fixPos(S.silentPart) - from).Magnitude else math.huge
			local pre = d <= (cfg.preAimRange or 60)
			-- v5.0.3: remember when the target-facing stream started for THIS lock — the sync wait below
			-- counts from here, not from the moment the trigger first wanted to fire (the stream had
			-- usually been on the target for a while already; the wait was paid twice)
			-- v5.0.4: the clock is pinned to the LOCK — a one-frame blip of preAiming used to move it
			-- forward and re-arm a sync wait after every shot
			if pre and (S.preAimSince == nil or (S.lockSince or 0) > S.preAimSince) then
				S.preAimSince = math.max(os.clock(), S.lockSince or 0)
			end
			S.preAiming = pre
			S.syncLostAt = nil
		else
			S.preAiming = false
			-- no lock for a while: the channel went back to anti-aim, the next target pays one sync wait
			if S.silentTarget == nil then
				S.syncLostAt = S.syncLostAt or os.clock()
				if os.clock() - S.syncLostAt > 0.3 then
					S.syncDoneFor = nil
				end
			end
		end
		-- a hide holds the body (defense / voidspam, magic parked): the server has us in the void, not on a
		-- shooting spot — never a round from there (the duel log: AIR from 554 st in the sky, WALL into the
		-- floor from under the map). The fire window brings the body back first.
		if hasTarget and (S.defenseHiding or (Combat.body.owner == "defense" and Combat.def.state ~= "under") or magic.park ~= nil or ak.hiding or ak.state == "void") then
			hasTarget = false
			hold = "hiding"
		end
		-- a shot the server would put into cover or into spawn protection is a wasted round: hold it.
		-- The line is judged from where the shot really leaves (the head, wherever Body put it) through
		-- the server's own whitelist — after a magic / autokill move too (30 % of logged misses were
		-- rounds into map parts fired from a relocated spot without this check)
		if hasTarget and S.headBlockedHold then
			hasTarget = false
			hold = "head blocked"
		end
		if hasTarget and S.targetAway then
			hasTarget = false
			hold = "target warped away"
		end
		if hasTarget and cfg.rageAutoShootVisible and S.targetVisible == false then
			hasTarget = false
			hold = "no line of sight"
		end
		if hasTarget and cfg.immuneCheck and S.targetImmune then
			hasTarget = false
			hold = "target immune"
		end
		-- 85 % of shots sent above 800 ms ping never got an answer: firing there only empties the mag
		if hasTarget and (S.pingMs or 0) > 800 then
			hasTarget = false
			hold = "ping over 800 ms"
		end
		-- magic bullet just hopped: the server still has the body at the old spot for one ping — a
		-- shot now leaves from a place the server disagrees with (live match: three rounds into the
		-- ground beside the head)
		if hasTarget and magic.active and cfg.magicJitter and S.magicHopSettled == false then
			hasTarget = false
			hold = "settling after hop"
		end
		-- empty mag: the game ignores StartShooting, so say so (chip) and start the reload ourselves
		-- when there is reserve left; nothing to do with an empty reserve but say it
		local gsA = S.gameState
		if hasTarget and gsA and gsA.ammo == 0 and gsA.item and type(gsA.item.Info) == "table" and gsA.item.Info.Type == "Gun" then
			hasTarget = false
			if (gsA.reserve or 0) > 0 then
				hold = "reloading"
				-- the reload itself is the user's Auto reload switch; the hold is unconditional
				if cfg.autoReload and os.clock() - (S.autoReloadAt or 0) > 1 and os.clock() >= (S.reloadUntil or 0) then
					S.autoReloadAt = os.clock()
					Input.gameInput("StartReloading")
				end
			else
				hold = "no ammo"
			end
		end
		-- melee: a swing only counts inside Info.AttackReach (the server measures it); outside, the
		-- trigger holds instead of whiffing every AttackCooldown
		local prof = Game.weaponProfile()
		S.meleeOut = prof.melee == true
		if hasTarget and (prof.shield or prof.utility) then
			-- a shield in hand blocks (no bash spam, no gun path); a utility is not a weapon
			hasTarget = false
			hold = if prof.shield then "shield up" else "no weapon out"
		elseif hasTarget and prof.melee then
			local reach = Combat.meleeReach(prof.item)
			local d = Combat.meleeDistance()
			if d == nil or d > reach + cfg.meleeReachSlack then
				hasTarget = false
				-- the numbers are formatted by the HUD chip at its own rate, not here every frame
				hold = "out of reach"
				S.holdReach, S.holdDist = reach, d or 0
			elseif S.meleeHold then
				-- the melee ragebot says wait: the server does not have us at the new spot yet, or this
				-- blade only lands its heavy
				hasTarget = false
				hold = S.meleeHold
			end
		elseif hasTarget and os.clock() < (S.quickMeleeUntil or 0) then
			hasTarget = false
			hold = "quick melee"
		elseif hasTarget and S.silentSuspended then
			hasTarget = false
			hold = "utility in use"
		end
		-- a lock without a fighter is not a target (only the self-test's fake lock looks like that):
		-- the trigger never fires at a point nobody stands on
		local forced0 = (ak.firing == true) or (S.peek == true)
		if hasTarget and S.silentFighter == nil and not forced0 then
			hasTarget = false
		end
		if hasTarget and cfg.autoShootHealthCheck then
			local f = S.silentFighter
			if f and Target.isDead(f) then
				hasTarget = false
			end
		end
		-- slow / one-shot weapons (sniper, Glass Cannon, Shorty): the server resolves the hitbox where
		-- IT has the target one ping later — a target sprinting behind a corner in that window turns
		-- the round into a wall hit and costs the whole reload. Hold while the point the target will
		-- reach in one ping has no line from our shot origin.
		-- (not in the punish window: a target that just teleported or surfaced has a meaningless velocity
		-- and the shot is worth more now than the prediction)
		if hasTarget and cfg.oneShotSafety and S.silentFighter and S.silentPart and not S.counter.window(S.silentFighter) then
			local gsO = S.gameState
			local info = gsO and gsO.item and gsO.item.Info
			-- "slow" from the weapon's ORIGINAL cooldown: rapid fire scales the live one and used to
			-- drop a 0.8 s weapon under the threshold (safety lost exactly when it matters)
			local origO = type(info) == "table" and S.statOriginals[tostring(gsO.item.Name)] or nil
			local cdO = tonumber(origO and origO.ShootCooldown) or (type(info) == "table" and tonumber(info.ShootCooldown)) or 0
			local slow = type(info) == "table" and info.Type == "Gun" and ((tonumber(info.MaxAmmo) or 99) <= 2 or cdO >= 0.8 or info.AimScopePercent ~= nil)
			if slow then
				local root, model = Game.fighterBody(S.silentFighter)
				local from = Game.shotOriginPos()
				if root and from then
					-- a speed / warp cheat's velocity says nothing about where they go: "leaving cover" then held every sniper round
					local v = Resolver.fixVel(root)
					if v.Magnitude > 4 and v.Magnitude <= Combat.CHEAT_SPEED then
						local ahead = S.silentPart.Position + v * (Game.pingMs() / 1000)
						local params = Game.losParams()
						if params then
							local hit = workspace:Raycast(from, ahead - from, params)
							if hit ~= nil and not (model ~= nil and hit.Instance:IsDescendantOf(model)) then
								hasTarget = false
								hold = "target leaving cover"
							end
						end
					end
				end
			end
		end
		-- v6.3 per-gun range (Minigun 60 st, or what the hit tracker narrowed it to): past it the rounds
		-- mostly land on walls — hold rather than pour the mag out
		if hasTarget and S.silentPart and S.gameState and S.gameState.weapon and not magic.active and (ak.state == "idle" or ak.state == "done") then
			local maxR = Combat.gunMaxRange(S.gameState.weapon)
			local from = maxR and Game.shotOriginPos()
			if from and (S.silentPart.Position - from).Magnitude > maxR then
				hasTarget = false
				hold = "out of this gun's range"
			end
		end
		-- kill confirm: when one more round kills, the next pull waits for the server's answer to the
		-- one in flight (one ping) instead of pouring a burst into a corpse — the range dummies showed
		-- two wasted rounds after every kill, real players cost a mag
		if hasTarget and cfg.killConfirmHold and S.silentFighter then
			local f = S.silentFighter
			local hp = Game.fighterHealth(f)
			local dmg = Combat.shotDamage()
			local lastAt = Combat.lastShotAtFighter[f]
			if hp and dmg and dmg > 0 and hp <= dmg and lastAt and os.clock() - lastAt < Game.pingMs() / 1000 + 0.08 then
				hasTarget = false
				hold = "confirming kill"
			end
		end
		if hasTarget and Combat.katanaHoldFire() then
			hasTarget = false
			hold = "blade deflecting"
			S.katanaHold = true
		else
			S.katanaHold = false
		end
		S.holdReason = if S.silentTarget ~= nil then hold else nil
		-- no reload cancel: never interrupt a reload in progress with our own trigger
		if hasTarget and cfg.noReloadCancel and os.clock() < (S.reloadUntil or 0) then
			hasTarget = false
		end
		local forced = (ak.firing == true) or (S.peek == true)
		-- while autokill owns the character, only its own firing windows shoot (never from the void /
		-- mid-snap: those rays go 250 studs through the roof)
		if ak.state ~= "idle" and ak.state ~= "done" and not ak.firing then
			hasTarget = false
		end
		local want = hasTarget and not S.menuOpen and not S.hudEdit and not S.calibrating and (forced or (cfg.autoShoot and (cfg.silentAim or Combat.mr.lockOwned == true)))
		-- auto aim / auto stop apply whenever auto shoot has a lock, even while a gate holds fire
		local engaged = want and not forced
		local aimMode = cfg.autoShootAimMode
		if engaged and S.silentTarget and (aimMode == "Camera" or aimMode == "ADS + Camera") then
			Combat.aimAt(S.silentTarget)
		end
		-- ADS: hold RMB from the moment a lock exists (silent locks through walls, so this is the
		-- "aimed in before the peek" behaviour) and let go a little after the lock is gone
		local adsOn = false
		if cfg.autoShoot and cfg.silentAim and (aimMode == "ADS" or aimMode == "ADS + Camera") and not S.menuOpen and not S.hudEdit then
			local lockNow = S.silentTarget ~= nil and not (cfg.autoShootHealthCheck and S.silentFighter and Target.isDead(S.silentFighter))
			local gs = S.gameState
			local gunOut = gs and gs.item and type(gs.item.Info) == "table" and gs.item.Info.Type == "Gun"
			if lockNow and gunOut then
				S.adsLockAt = os.clock()
			end
			adsOn = gunOut and S.adsLockAt ~= nil and os.clock() - S.adsLockAt < cfg.autoShootAdsRelease
		end
		if adsOn ~= (S.adsHeld == true) then
			S.adsHeld = adsOn
			if not (cfg.autoBlock and S.blocking) then
				Input.setAds(adsOn)
			end
		elseif adsOn then
			-- snipers un-scope after every shot; push StartAiming again until the item reports aiming
			local gs = S.gameState
			if gs and gs.aiming == false and os.clock() - (S.adsPushAt or 0) > 0.15 then
				S.adsPushAt = os.clock()
				Input.setAds(true, true)
			end
		end
		local stopMode = cfg.autoShootStopMode
		local stopNow = false
		if stopMode == "Whenever locked" then
			stopNow = cfg.autoShoot and cfg.silentAim and S.silentTarget ~= nil and not S.menuOpen
		elseif stopMode == "While firing" then
			stopNow = engaged
		elseif stopMode == "Per shot" then
			-- only when the gun is about to be able to fire again: the item's tick()-stamped
			-- _shoot_cooldown says when; we stand still for the last lead-ms before it and until the
			-- shot leaves (the stamp jumps forward), then you move freely between shots
			local gs = S.gameState
			local item = gs and gs.item
			local stamp = type(item) == "table" and tonumber(item._shoot_cooldown)
			if engaged and stamp then
				local untilReady = stamp - tick()
				stopNow = untilReady <= cfg.autoShootStopLeadMs / 1000
			else
				stopNow = engaged and os.clock() - (S.lastShotWindowAt or -1) < cfg.autoShootStopLeadMs / 1000
			end
		end
		autoStop(stopNow)
		-- auto shoot with a lock = we intend to shoot it: keep the replicated-rotation spoof armed the
		-- whole time (not just while the trigger is down), then let one replication tick carry the
		-- target-facing rotation to the server before the first shot on a new lock
		if cfg.autoShoot and cfg.silentAim and S.silentTarget ~= nil and not S.menuOpen then
			S.spoofUntil = math.max(S.spoofUntil or 0, os.clock() + 0.3)
		end
		if want and not forced and cfg.autoShootMinHitChance > 0 then
			S.lastHitChance = Combat.hitChance()
			if S.lastHitChance < cfg.autoShootMinHitChance then
				want = false
			end
		else
			S.lastHitChance = nil
		end
		-- we intend to shoot this lock: the replicated rotation faces it from now on (Combat.updateAA
		-- streams it at 20 Hz while autoEngaged is set; anti-aim resumes the moment it clears). The
		-- server fires along that rotation, so the first shot waits the lead for it to arrive.
		if want and not forced then
			-- v5: a brief hold (kill confirm, head blocked for a frame, reload) used to drop the
			-- engagement, let anti-aim retake the rotation channel and force a full round-trip re-sync
			-- before the next shot — 330–440 ms per pull on a 100 ms gun (range trace). Inside the
			-- grace window (h.faceTarget keeps facing the target) the server still holds our rotation,
			-- so the engagement timer is NOT restarted.
			local nowE = os.clock()
			if not S.autoEngaged and not (S.engagedUntil and nowE < S.engagedUntil) then
				S.engagedSince = nowE
			end
			if S.lockSince and S.lockSince > (S.engagedSince or 0) then
				S.engagedSince = S.lockSince -- new target: its rotation needs its own lead
			end
			-- the pre-aim stream has been facing this lock since S.preAimSince: the sync clock starts there
			if S.preAiming and S.preAimSince and S.preAimSince >= (S.lockSince or 0) and S.preAimSince < (S.engagedSince or math.huge) then
				S.engagedSince = S.preAimSince
			end
			S.autoEngaged = true
			S.engagedUntil = nowE + 0.6
			-- flick AA drops the channel back to the fake angle after every pulse: each shot re-syncs from
			-- its own pulse time (S.syncSince, stamped in Combat.pulse); otherwise the stream holds the
			-- target-facing rotation and only the first shot on a lock waits
			local waited = os.clock() - math.max(S.engagedSince or 0, S.syncSince or 0)
			-- the first shot on this fighter waits for the server to echo the lock-facing rotation (paid
			-- once per fighter; flick AA re-syncs every shot). autoShootEchoGate is always on now: with it
			-- off the first round of every engagement flew along the stored anti-aim yaw.
			local ready = Combat.syncReady(S.silentFighter, math.max(S.engagedSince or 0, S.syncSince or 0))
			if ready and cfg.autoShootLeadMs > 0 and waited < cfg.autoShootLeadMs / 1000 then
				ready = false
			end
			S.syncWaiting = not ready -- read by h.faceTarget (flick AA faces the target only now)
			if not ready then
				want = false
				S.triggerWait = "sync"
			end
		else
			S.autoEngaged = want == true
			S.syncWaiting = false
		end
		if not want then
			fireOff()
			return
		end
		local gsS = S.gameState
		if cfg.autoShootHold or forced or fireMethodNow() == "direct" or (gsS and Combat.spammable(gsS.item)) then
			fireOn() -- automatics always take the game-style per-frame path (Combat.spamFire)
			return
		end
		-- tap mode: the same pulse path as hold mode (cooldown stamp, scope wait, reaction, rotation
		-- pre-send, kill-confirm bookkeeping), only paced no faster than the tap delay. The old raw
		-- StartShooting/FinishShooting tap skipped every one of those gates.
		local now = os.clock()
		if now - lastAutoShot >= cfg.autoShootDelay then
			local method = fireMethodNow()
			if method == "game" then
				local gs = S.gameState
				local item = gs and gs.item
				if item and not (gs.ammo ~= nil and gs.ammo <= 0) and Combat.triggerReady(item, now) then
					lastAutoShot = now
					Combat.pulse(item)
					S.pulses = (S.pulses or 0) + 1
				end
			else
				lastAutoShot = now
				task.spawn(function()
					-- v5.2: a pulse scheduled right before an unload / re-inject must not press the
					-- button for an instance that is gone (the release below still runs either way)
					if not S.alive or Game.superseded() then
						return
					end
					S.firing = true
					Input.setFire(true, method)
					task.wait(0.04)
					Input.setFire(false)
					task.wait(0.02)
					S.firing = S.alive and UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
				end)
			end
		end
	end
	function Combat.releaseFire()
		fireOff()
		Input.setFire(false)
	end
	S.releaseFire = Combat.releaseFire

	---------------------------------------------------------------------------
	-- autokill state machine: idle → snap → orbit (⇄ void) → return → done → idle
	---------------------------------------------------------------------------
	local orbitParams = RaycastParams.new()
	orbitParams.FilterType = Enum.RaycastFilterType.Exclude
	orbitParams.IgnoreWater = true
	-- the one way the orbit filter is built: target model + our character, only the non-nil ones
	-- (two array-literal variants used to get a nil hole when the character was missing → empty
	-- filter), reassigned only when either changes (orbitPoint ran it per frame)
	Combat.orbitFilterTbl = {}
	Combat.orbitFilterModel, Combat.orbitFilterChar = false, false
	function Combat.orbitFilter(model: Model?)
		local char = LP.Character
		if Combat.orbitFilterModel == model and Combat.orbitFilterChar == char then
			return
		end
		Combat.orbitFilterModel, Combat.orbitFilterChar = model, char
		local filt = Combat.orbitFilterTbl
		table.clear(filt)
		if model then
			table.insert(filt, model)
		end
		if char then
			table.insert(filt, char)
		end
		orbitParams.FilterDescendantsInstances = filt
	end

	local function finiteCF(cf: CFrame): boolean
		local p = cf.Position
		local m = p.Magnitude
		return m == m and m < 1e6 and cf.LookVector.Magnitude > 0.5
	end
	local function pivotTo(cf: CFrame)
		if typeof(cf) ~= "CFrame" or not finiteCF(cf) then
			S.hookErr("pivotTo", "refused a non-finite CFrame")
			return
		end
		local char = LP.Character
		local me = Game.myRoot()
		if char and char.PrimaryPart then
			char:PivotTo(cf)
		elseif me then
			me.CFrame = cf
		end
		if me then
			me.AssemblyLinearVelocity = Vector3.zero
			me.AssemblyAngularVelocity = Vector3.zero
		end
	end

	-- collision-aware orbit point around the head; never inside geometry
	-- maxLinear: a lower speed cap (st/s) for this step than the Speed cap slider
	function Combat.orbitPoint(head: BasePart, model: Model?, dt: number, maxLinear: number?): CFrame
		local now = os.clock()
		local baseR = math.clamp(ak.radius or cfg.autokillRadius, 1, 20)
		local baseH = math.clamp(ak.height or cfg.autokillHeight, 0, 20)
		local angSpeed = math.min(ak.speed or cfg.autokillOrbitSpeed, (maxLinear or cfg.autokillMaxSpeed) / math.max(baseR, 1))
		ak.angle = (ak.angle or 0) + angSpeed * dt
		local n1 = math.noise(now * 0.9, 1.3)
		local n2 = math.noise(now * 0.7, 7.1)
		local r = if cfg.autokillOrbit then baseR * (1 + n1 * 0.25) else baseR
		local h = baseH + n2 * 0.8
		local desired = head.Position + Vector3.new(math.cos(ak.angle) * r, h, math.sin(ak.angle) * r)
		if ak.buriedTop then
			-- on the slab over a buried target, close in: the lock starts each round inside the slab straight
			-- under our head, so the orbit stays within a couple of studs of their column
			local rr = math.min(r, 2.5)
			desired = Vector3.new(head.Position.X + math.cos(ak.angle) * rr, ak.buriedTop + 3, head.Position.Z + math.sin(ak.angle) * rr)
			return Combat.lookAtSafe(desired, head.Position)
		end
		Combat.orbitFilter(model)
		local toDesired = desired - head.Position
		-- noclip lets the orbit sit inside geometry, so only pull back off a wall when we are NOT
		-- passing through it; either way keep the spot out of a lethal OOB volume
		if not (cfg.noclip or cfg.noclipRage) then
			local hit = workspace:Raycast(head.Position, toDesired, orbitParams)
			if hit then
				local hitDist = (hit.Position - head.Position).Magnitude
				desired = hit.Position - toDesired.Unit * math.min(1.5, hitDist * 0.5)
			end
		end
		local c = S.bounds.check(desired)
		if c and c.lethal then
			desired = head.Position + Vector3.new(0, math.max(h - 1, 0.5), 0) -- hug the head, out of the volume
		end
		-- never above the band over the target's ground: a lifted target is orbited from below
		local top = if ak.refGround then ak.refGround + cfg.safeMaxHeight - 0.5 else math.huge
		if desired.Y > top then
			desired = Vector3.new(desired.X, top, desired.Z)
		end
		return Combat.lookAtSafe(desired, head.Position)
	end

	function Combat.voidPoint(head: BasePart): CFrame
		-- the measured void under the map (under the target: their floor covers it), the calibrated sky in
		-- Sky mode, else the top of the safe band over the target's ground
		local y = ak.restY or ((S.safe.groundY(head.Position) or head.Position.Y) + cfg.safeMaxHeight - 2)
		local p = Vector3.new(head.Position.X, y, head.Position.Z)
		-- an OutOfBoundsPart there kills us whatever the guard says: step down until the point is out of
		-- every lethal volume (Body refuses it anyway; this keeps the rest useful instead of refused)
		local guard = 0
		while guard < 8 do
			local c = S.bounds.check(p)
			if not (c and c.lethal) then
				break
			end
			guard += 1
			y -= math.max(10, (y - head.Position.Y) * 0.25)
			p = Vector3.new(head.Position.X, y, head.Position.Z)
		end
		-- straight down is parallel to lookAt's default up vector (degenerate basis → NaN and a
		-- refused teleport); use the head's horizontal facing as the up reference
		local look = head.CFrame.LookVector
		local up = Vector3.new(look.X, 0, look.Z)
		up = if up.Magnitude > 0.05 then up.Unit else Vector3.new(0, 0, -1)
		return CFrame.lookAt(p, head.Position, up)
	end
	-- area-based spot choice: of 12 angles around the head, the one whose spot the fewest OTHER
	-- enemies can see (their head → the spot, server-style whitelist), away from the crowd, never
	-- inside geometry. Used for the snap and every hop; the orbit steers toward it.
	function Combat.safestAngle(head: BasePart, model: Model?, enemies: { any }): number
		local r = math.clamp(ak.radius or cfg.autokillRadius, 1, 20)
		local hgt = math.clamp(ak.height or cfg.autokillHeight, 0, 20)
		local params = Game.losParams()
		local others = {}
		for _, f in ipairs(enemies) do
			if f ~= ak.fighter and not Target.isDead(f) then
				local eh = Game.fighterHead(f)
				if eh then
					local _, em = Game.fighterBody(f)
					table.insert(others, { head = eh, model = em })
					if #others >= 6 then
						break
					end
				end
			end
		end
		Combat.orbitFilter(model)
		local bestA, bestS = ak.angle or 0, math.huge
		local base = math.random() * 2 * math.pi
		-- the target's own view: a spot in front of their look is the one their aim is already on
		local look = if ak.fighter then Combat.meleeLook(ak.fighter) else nil
		-- 8 candidates × (1 + up to 6 observers) rays: the 12-angle version was an 84-ray spike on
		-- every hop, and 45° steps still pick the covered side reliably. v5 perf: 4 candidates (90°
		-- steps) once the adaptive tier is at 2+ — half the rays, still picks the covered side.
		local nCand = if (S.perfTier or 0) >= 2 then 4 else 8
		for i = 0, nCand - 1 do
			local a = base + i * (2 * math.pi / nCand)
			local p = head.Position + Vector3.new(math.cos(a) * r, hgt, math.sin(a) * r)
			local score = if workspace:Raycast(head.Position, p - head.Position, orbitParams) ~= nil then 50 else 0
			if look then
				score += math.max(0, look:Dot(Vector3.new(math.cos(a), 0, math.sin(a)))) * 12
			end
			for _, o in ipairs(others) do
				score += math.max(0, 40 - (o.head.Position - p).Magnitude) * 0.1
				if params then
					local hit = workspace:Raycast(o.head.Position, p - o.head.Position, params)
					if hit == nil or (o.model ~= nil and hit.Instance:IsDescendantOf(o.model)) then
						score += 3
					end
				end
			end
			if score < bestS then
				bestS, bestA = score, a
			end
		end
		ak.spotScore = bestS
		return bestA
	end
	-- Backstab geometry: melee crits (Knife / Glast Shard CriticalDamage 150) are decided by where the
	-- victim looks — the spot straight behind their replicated look, at melee range, is a one-shot.
	function Combat.critMelee(item: any): boolean
		return Game.profileOf(item, Combat.profScratch).crit == true
	end
	-- which way the victim faces for the crit, flat (unit) or nil. The server judges it on their
	-- replicated look; against anti-aim that look spins every frame, so Auto switches to the circular
	-- mean of their recent yaws (jitter averages to its base direction) and to their body's facing
	-- when even the mean is noise (a full spin)
	function Combat.meleeLook(fighter: any): Vector3?
		local root, model = Game.fighterBody(fighter)
		if not root then
			return nil
		end
		local function flat(v: Vector3?): Vector3?
			if not v then
				return nil
			end
			local f = Vector3.new(v.X, 0, v.Z)
			return if f.Magnitude > 0.05 then f.Unit else nil
		end
		local src = cfg.meleeLookSource
		local bodyLook = flat(root.CFrame.LookVector)
		if src == "Body" then
			return bodyLook
		end
		local camLook = flat(Game.enemyLook(fighter))
		local b = model and Resolver.buffers[model]
		if src == "Smoothed" or (src == "Auto" and b ~= nil and b.aa) then
			if b and b.n >= 3 then
				local sx, sz, n = 0, 0, 0
				for i = 1, b.n do
					local r = b.rot[i]
					if r then
						local lv = CFrame.fromOrientation(0, r.Y, 0).LookVector
						sx += lv.X
						sz += lv.Z
						n += 1
					end
				end
				if n > 0 then
					local m = Vector3.new(sx / n, 0, sz / n)
					if m.Magnitude > 0.35 then
						return m.Unit
					end
				end
			end
			return bodyLook or camLook
		end
		return camLook or bodyLook
	end
	function Combat.behindAngle(fighter: any): number?
		local look = Combat.meleeLook(fighter)
		if not look then
			return nil
		end
		local back = -look
		return math.atan2(back.Z, back.X) -- orbitPoint uses cos(angle) for X, sin(angle) for Z
	end
	-- are we in their back cone (the crit zone)? Judged around where the server will have them when our
	-- input lands (Combat.meleeTargetPos), the same point the ragebot's spot is built from
	function Combat.isBehind(fighter: any, from: Vector3): boolean
		local look = Combat.meleeLook(fighter)
		local root = Game.fighterBody(fighter)
		if not (look and root) then
			return false
		end
		local at = Combat.meleeTargetPos(fighter) or root.Position
		local toUs = (from - at) * Vector3.new(1, 0, 1)
		if toUs.Magnitude < 0.3 then
			return false
		end
		return look:Dot(toUs.Unit) < -0.35
	end
	-- Auto backstab (outside autokill): crit melee in hand, the lock inside the lunge range with line
	-- of sight and us not in their back cone → hop to the spot behind them; the melee reach gate and
	-- the trigger's settle window take it from there. One lunge per cooldown, never mid-autokill.
	local lungeAt = 0
	-- why the lunge did not run, one line per reason per second (grep [backstab:skip:)
	Combat.bsLogAt = {}
	function Combat.backstabSkip(reason: string, detail: string?)
		local now = os.clock()
		if now - (Combat.bsLogAt[reason] or 0) >= 1 then
			Combat.bsLogAt[reason] = now
			log("DEBUG", ("[backstab:skip:%s]%s"):format(reason, if detail then " " .. detail else ""))
		end
	end
	-- who runs "get behind and land the heavy" right now: the melee ragebot owns it while it is on (it
	-- holds the spot behind them continuously), the one-off lunge only without it. The loop steps this
	-- lunge only when it is the owner — the switch never calls a function that returns at once.
	function Combat.backstabOwner(): string?
		if not (cfg.autoBackstab and cfg.silentAim and Combat.rageOn()) then
			return nil
		end
		return if cfg.meleeRage then "meleeRage" else "lunge"
	end
	function Combat.updateBackstab(enemies: { any })
		S.backstabReady = false
		if Combat.backstabOwner() ~= "lunge" or S.menuOpen or S.hudEdit or S.calibrating then
			return
		end
		if ak.state ~= "idle" and ak.state ~= "done" then
			Combat.backstabSkip("autokill", ak.state)
			return
		end
		local prof = Game.weaponProfile()
		if not (prof.melee and (cfg.autoBackstabAnyMelee or prof.crit)) then
			if prof.melee then
				Combat.backstabSkip("not-crit", prof.name)
			end
			return
		end
		local f = S.silentFighter
		local me = Game.myRoot()
		local head = f and Game.fighterHead(f)
		local root, model = nil, nil
		if f then
			root, model = Game.fighterBody(f) -- (`f and fn()` would truncate the second return)
		end
		if not (f and me and head and root) or Target.isDead(f) or (cfg.immuneCheck and Game.fighterImmune(f)) then
			Combat.backstabSkip("no-target", prof.name)
			return
		end
		local d = (root.Position - me.Position).Magnitude
		if d > cfg.autoBackstabRange then
			Combat.backstabSkip("range", ("%s %.0f > %.0f st"):format(prof.name, d, cfg.autoBackstabRange))
			return
		end
		S.backstabReady = true
		local reach = Combat.meleeReach(prof.item)
		if Combat.isBehind(f, me.Position) and d <= reach + cfg.meleeReachSlack then
			return -- already in the crit zone and inside reach: the auto-swing does the rest
		end
		local now = os.clock()
		if now - lungeAt < 1.2 or S.reloadUntil and now < S.reloadUntil then
			return
		end
		local from = Game.shotOriginPos() or me.Position
		if not Game.rayVisible(model, root, from) then
			Combat.backstabSkip("los", ("%s %.0f st"):format(prof.name, d))
			return
		end
		if Combat.body.owner ~= nil then
			Combat.backstabSkip("body-busy", ("body %s"):format(Combat.body.owner))
			return
		end
		local ang = Combat.behindAngle(f)
		if not ang then
			Combat.backstabSkip("no-look", Game.fighterName(f))
			return
		end
		local r = math.clamp(reach * 0.45, 1.8, 3)
		local tp = Combat.meleeTargetPos(f) or root.Position
		local spot = tp + Vector3.new(math.cos(ang) * r, 0, math.sin(ang) * r)
		Combat.orbitFilter(model)
		if workspace:Raycast(root.Position, spot - root.Position, orbitParams) then
			Combat.backstabSkip("wall", "their back is against a wall")
			return
		end
		-- a ledge / stairs behind them: land on the floor under the spot, or not at all
		local ground = workspace:Raycast(spot + Vector3.new(0, 2, 0), Vector3.new(0, -8, 0), orbitParams)
		if not ground then
			Combat.backstabSkip("ground", "nothing to stand on behind them")
			return
		end
		spot = Vector3.new(spot.X, math.max(ground.Position.Y + 3, root.Position.Y - 3), spot.Z)
		if not Combat.body.jump("backstab", Combat.lookAtSafe(spot, Vector3.new(head.Position.X, spot.Y, head.Position.Z))) then
			Combat.backstabSkip("safe", "the spot behind them is not standable")
			return
		end
		lungeAt = now
		S.aimHeld = false
		log("INFO", ("auto backstab: behind %s (%.1f st)"):format(Game.fighterName(f), d))
	end
	-- Melee ragebot: with a melee in hand the lock is hunted, not waited for. Every attack is judged by
	-- the server on OUR position (reach, measured once our input arrives — one settle after a hop) and on
	-- the camera data sent with it (a 90° cone from our look), and a crit (Knife / Glast Shard, 150) is a
	-- HEAVY attack (RMB = "StartAiming") from inside the victim's back cone. So: hold a spot inside reach
	-- (behind their look for the crit blades), wait until the server has us there, turn the camera at
	-- them for the frame the input goes out (restored the same frame), then heavy / swing.
	-- Modes per weapon (Auto picks): heavy = Knife, Glast Shard · spam = Fists, Maul, Riot Shield, Spear,
	-- Trowel · ability = Katana (deflect), Scythe (dash), Battle Axe (spin), Chainsaw (held attack) ·
	-- walk = no relocation, you move and it only swings.
	Combat.MELEE_AUTO_MODE = { Knife = "heavy", ["Glast Shard"] = "heavy", Katana = "ability", Scythe = "ability", ["Battle Axe"] = "ability", Chainsaw = "ability" }
	Combat.MELEE_MODE_NAMES = { ["Heavy crit"] = "heavy", ["Close spam"] = "spam", Ability = "ability", ["Walk-in"] = "walk" }
	Combat.mr = { holding = false, aimHeld = false, heavyAt = 0, heavies = 0, abilityAt = {}, req = { hold = 0.5, jumpDist = 6, refGround = nil }, lastLog = 0, whyAt = {} }
	function Combat.meleeModeFor(item: any): string
		local name = type(item) == "table" and tostring(item.Name) or ""
		local over = cfg.meleeOverrides[name]
		local pick = Combat.MELEE_MODE_NAMES[if type(over) == "string" then over else cfg.meleeMode]
		if pick then
			return pick
		end
		if Combat.MELEE_AUTO_MODE[name] then
			return Combat.MELEE_AUTO_MODE[name]
		end
		-- an unknown blade with a crit bonus behaves like the Knife
		return if Combat.critMelee(item) then "heavy" else "spam"
	end
	-- the target's root where the server will have it when our input lands (one-way ping ahead)
	function Combat.meleeTargetPos(f: any): Vector3?
		local root = Game.fighterBody(f)
		if not root then
			return nil
		end
		if not cfg.meleePredict then
			return root.Position
		end
		local v = Resolver.fixVel(root) * Vector3.new(1, 0, 1)
		local lead = v * ((S.pingMs or 0) / 2000)
		if lead.Magnitude > 6 then
			lead = lead.Unit * 6
		end
		return root.Position + lead
	end
	-- root to (predicted) root: what the server's reach check measures
	function Combat.meleeDistance(): number?
		local f = S.silentFighter
		local me = S.myRootPart or Game.myRoot()
		local p = f and Combat.meleeTargetPos(f)
		if p and me then
			return (p - me.Position).Magnitude
		end
		return Combat.targetDistance()
	end
	-- the camera faces the lock for the one input, then goes back — the attack carries the facing
	-- camera data, the player never sees the snap (it is restored before the frame renders)
	function Combat.facingInput(input: string)
		local part = S.silentPart
		local from = Game.shotOriginPos()
		local rot0 = CameraController and CameraController.Rotation
		local faced = cfg.meleeFaceOnSwing and part ~= nil and part.Parent ~= nil and from ~= nil and typeof(rot0) == "Vector2"
		if faced then
			Game.setCamRotation(Combat.lookAtSafe(from, part.Position))
		end
		if cfg.silentSpoofServer and S.silentTarget ~= nil then
			Combat.sendRotation(nil)
		end
		Input.gameInput(input)
		if faced then
			Game.asGame(CameraController.SetRotation, CameraController, rot0)
		end
	end
	function Combat.meleeRageRelease(why: string?)
		local MR = Combat.mr
		S.meleeHold = nil
		if MR.lockOwned then
			MR.lockOwned = false
			if not cfg.silentAim and ak.state == "idle" then
				Combat.clearLock()
			end
		end
		if MR.aimHeld then
			MR.aimHeld = false
			Input.gameInput("FinishAiming")
		end
		if MR.holding then
			MR.holding = false
			-- a melee fight ends where it ended when the player can stand there (else Body goes home)
			Combat.body.release("meleeRage", true)
		end
		-- one line per reason per second: [melee:no-target] [melee:melee-away] [melee:out-of-range]
		if why and os.clock() - (MR.whyAt[why] or 0) >= 1 then
			MR.whyAt[why] = os.clock()
			log("DEBUG", ("[melee:%s] melee rage: %s · body %s"):format(string.gsub(why, " ", "-"), why, Combat.body.owner or "you"))
		end
	end
	-- where the melee ragebot stands: behind their look for the crit blades, on our own side for the
	-- rest, a stand-off inside the (heavy) reach from where the server will have them (one-way ping
	-- ahead) — so a runner is met behind, not chased from behind where they were
	function Combat.meleeSpot(f: any, mePos: Vector3, mode: string, reach: number, heavyReach: number): Vector3?
		local root = Game.fighterBody(f)
		if not root then
			return nil
		end
		local tpos = Combat.meleeTargetPos(f) or root.Position
		local look = Combat.meleeLook(f)
		local dir: Vector3
		if mode == "heavy" and look then
			dir = -look
		else
			dir = (mePos - tpos) * Vector3.new(1, 0, 1)
			dir = if dir.Magnitude > 0.05 then dir.Unit else Vector3.new(0, 0, 1)
		end
		local limit = if mode == "heavy" then math.min(reach, heavyReach) else reach
		local standOff0 = math.clamp(cfg.meleeStandoff, 1.5, math.max(limit - 1, 1.5))
		local y = root.Position.Y
		-- buried in the floor (the under desync): stand on the slab over them, close enough that the drop
		-- to their body still fits the reach
		local top = S.bounds.buriedTop((select(2, Game.fighterBody(f))))
		if top then
			y = top + 3
			standOff0 = math.min(standOff0, 1.5)
		end
		local function candidate(i: number): Vector3
			local c, s = Combat.MELEE_COS[i], Combat.MELEE_SIN[i]
			local dx, dz = dir.X * c + dir.Z * s, dir.Z * c - dir.X * s
			local standOff = standOff0
			local spot = Vector3.new(tpos.X + dx * standOff, y, tpos.Z + dz * standOff)
			-- a wall right behind them: come closer instead of standing inside it
			local tries = 0
			while tries < 3 and S.bounds.inGeometry(spot, 0.9) do
				tries += 1
				standOff *= 0.65
				spot = Vector3.new(tpos.X + dx * standOff, y, tpos.Z + dz * standOff)
			end
			return spot
		end
		-- the preferred side first, then bearings around them (the back cone before the sides for the
		-- crit blades): a target against the map edge or a wall had its only spot pulled out of reach by
		-- Safe and the ragebot stood 13 studs off waiting (the range dummies on the rail). The bearing that
		-- passed last is tried first and the full sweep runs at most every 0.15 s (it cost ~1 ms a frame).
		local MR = Combat.mr
		local check = S.safe.check
		if MR.spotFor ~= f then
			MR.spotFor, MR.spotTurn, MR.spotScanAt = f, 1, 0
		end
		local now = os.clock()
		if MR.spotTurn ~= 1 and now - MR.spotScanAt >= 0.5 then
			-- back to the preferred side (behind them for a crit) once it is open again
			MR.spotScanAt = now
			local s = candidate(1)
			if check(s, MR.req) then
				MR.spotTurn = 1
				return s
			end
		end
		local spot = candidate(MR.spotTurn)
		if check(spot, MR.req) then
			return spot
		end
		if now - MR.spotScanAt < 0.15 then
			return spot
		end
		MR.spotScanAt = now
		for i = 1, #Combat.MELEE_COS do
			if i ~= MR.spotTurn then
				local s = candidate(i)
				if check(s, MR.req) then
					MR.spotTurn = i
					return s
				end
			end
		end
		return spot
	end
	Combat.MELEE_COS, Combat.MELEE_SIN = {}, {}
	for i, turn in ipairs({ 0, 35, -35, 70, -70, 110, -110, 150, -150, 180 }) do
		Combat.MELEE_COS[i], Combat.MELEE_SIN[i] = math.cos(math.rad(turn)), math.sin(math.rad(turn))
	end
	-- v0.9: the melee ragebot picks its own target like the gun ragebot — the nearest enemy it can hurt
	-- within Range, FOV and silent aim ignored (it only ever acted on the silent lock, so anyone outside the
	-- FOV was left alone and it did nothing with silent aim off). The current target is kept while it stays
	-- valid; a kill moves straight on to the next one.
	function Combat.meleeValid(f: any, me: Vector3, limit: number): (boolean, number)
		if Target.isDead(f) or (cfg.immuneCheck and Game.fighterImmune(f)) or Game.fighterHealth(f) == math.huge then
			return false, math.huge
		end
		local skip = Combat.akSkip and Combat.akSkip[f]
		if skip and os.clock() < skip then
			return false, math.huge
		end
		local p = Combat.meleeTargetPos(f)
		if not p then
			return false, math.huge
		end
		local d = (p - me).Magnitude
		return d <= limit, d
	end
	function Combat.meleePick(enemies: { any }, me: Vector3): any
		local MR = Combat.mr
		local cur = MR.fighter
		if cur ~= nil and table.find(enemies, cur) then
			local ok = Combat.meleeValid(cur, me, cfg.meleeRageRange * 1.25)
			if ok then
				return cur
			end
		end
		local best, bestD = nil, math.huge
		for _, f in ipairs(enemies) do
			local ok, d = Combat.meleeValid(f, me, cfg.meleeRageRange)
			if ok and d < bestD then
				best, bestD = f, d
			end
		end
		if best ~= cur and cur ~= nil and best ~= nil then
			MR.chained = (MR.chained or 0) + 1
		end
		return best
	end
	-- the lock the swing, the facing camera and auto shoot read (S.silent*), owned by the melee ragebot
	-- for this frame (the lock step runs first and clears or re-picks it each frame)
	function Combat.meleeLockTo(f: any)
		local root, model = Game.fighterBody(f)
		local part = Game.hitboxPart(f, "Body") or Game.fighterHead(f) or root
		if S.silentFighter ~= f then
			S.lockSince = os.clock()
		end
		S.silentFighter, S.silentPart, S.silentTargetModel = f, part, model
		S.silentTarget = part and part.Position or nil
		S.silentLocal, S.silentLocalPart, S.silentInCircle = nil, nil, false
		S.silentAimPoint, S.silentAimModel = nil, nil
		S.cfgOverrideSilent = true
		Combat.mr.lockOwned = true
	end
	function Combat.updateMeleeRage(enemies: { any })
		local MR = Combat.mr
		if not (cfg.meleeRage and cfg.rageEnabled ~= false) or S.menuOpen or S.hudEdit or S.calibrating or (ak.state ~= "idle" and ak.state ~= "done") then
			MR.fighter = nil
			Combat.meleeRageRelease(nil)
			return
		end
		local prof = Game.weaponProfile()
		if not (prof.melee and prof.item) then
			MR.fighter = nil
			Combat.meleeRageRelease("melee away")
			return
		end
		local me = S.myRootPart or Game.myRoot()
		local f = if me then Combat.meleePick(enemies, me.Position) else nil
		MR.fighter = f
		local root = if f then Game.fighterBody(f) else nil
		if not (f and me and root) then
			Combat.meleeRageRelease("no target")
			return
		end
		Combat.meleeLockTo(f)
		local item = prof.item
		local info = item.Info
		local name = tostring(item.Name)
		local mode = Combat.meleeModeFor(item)
		local reach = Combat.meleeReach(item)
		local heavyReach = tonumber(info.HeavyAttackReach) or reach
		local hasHeavy = mode == "heavy" and tonumber(info.HeavyAttackDamage) ~= nil
		local tpos = Combat.meleeTargetPos(f) or root.Position
		local d = (tpos - me.Position).Magnitude
		if d > cfg.meleeRageRange then
			Combat.meleeRageRelease("out of range")
			return
		end
		local now = os.clock()
		-- 1. hold a spot inside reach: behind their look for the crit blades (it follows their turning),
		-- on our own side for everything else; walk-in never moves the body
		MR.req.refGround = S.bounds.buriedTop((select(2, Game.fighterBody(f)))) or S.safe.groundY(root.Position)
		MR.req.near = root.Position
		local spot = if mode ~= "walk" then Combat.meleeSpot(f, me.Position, mode, reach, heavyReach) else nil
		if spot then
			if Combat.body.request("meleeRage", spot, Vector3.new(root.Position.X, spot.Y, root.Position.Z), MR.req) then
				MR.holding = true
				S.aimHeld = false
				if now - MR.lastLog > 2 then
					MR.lastLog = now
					log("INFO", ("melee rage: %s on %s (%s, %.1f st)"):format(name, Game.fighterName(f), mode, d))
				end
			end
		end
		-- the server has us where we stand: one settle after the last hop (+ padding) — every swing before
		-- that is measured from the old spot and misses
		local settled = mode == "walk" or (Combat.body.holds("meleeRage") and os.clock() - Combat.body.jumpAt >= Combat.settleSec() + cfg.meleeSettlePad / 1000)
		local dNow = Combat.meleeDistance() or d
		local behind = Combat.isBehind(f, me.Position)
		local policy = cfg.meleeHeavyPolicy
		-- the light swing is the trigger's (auto shoot) or ours below; these say when it must wait
		S.meleeHold = nil
		if not settled then
			S.meleeHold = "settling"
		elseif hasHeavy and (policy == "Heavy only" or name == "Glast Shard") then
			S.meleeHold = "heavy only" -- the Glast Shard's light swing does 1 damage
		end
		-- 2. the heavy crit: inside its reach and the back cone, once per its cooldown
		if hasHeavy and policy ~= "Light only" and settled and behind and dNow <= heavyReach + cfg.meleeReachSlack then
			local cd = tonumber(info.HeavyAttackCooldown) or 1.25
			if now - MR.heavyAt >= cd and now >= (S.ourShotUntil or 0) then
				MR.heavyAt = now
				MR.heavies += 1
				S.ourShotUntil = now + 0.15
				S.spoofUntil = now + 0.6
				Combat.facingInput("StartAiming")
				local hold = cfg.meleeHeavyHold
				task.delay(hold, function()
					if S.alive then
						Input.gameInput("FinishAiming")
					end
				end)
				log("INFO", ("melee rage: HEAVY on %s from behind (%.1f st)"):format(Game.fighterName(f), dNow))
			end
		elseif mode == "ability" and settled then
			Combat.meleeAbility(item, name, f, dNow, reach, now)
		end
		-- 3. the swing: with auto shoot on, the trigger's melee path swings on our lock (same gates, reads
		-- S.meleeHold); otherwise the ragebot swings itself on the weapon's own cooldown
		if not cfg.autoShoot and S.meleeHold == nil and not MR.aimHeld and dNow <= reach + cfg.meleeReachSlack and now >= (S.ourShotUntil or 0) then
			if Combat.triggerReady(item, now) then
				Combat.pulse(item)
				S.pulses = (S.pulses or 0) + 1
			end
		end
	end
	-- the right-click abilities (cooldowns from the item library): Chainsaw holds its attack while in
	-- reach, the Battle Axe spins when they are inside its radius, the Scythe dashes to close a gap, the
	-- Katana deflects while a gun is on us
	function Combat.meleeAbility(item: any, name: string, f: any, dist: number, reach: number, now: number)
		local MR = Combat.mr
		local info = item.Info
		if name == "Chainsaw" then
			local want = dist <= reach + cfg.meleeReachSlack
			if want ~= MR.aimHeld then
				MR.aimHeld = want
				if want then
					Combat.facingInput("StartAiming")
				else
					Input.gameInput("FinishAiming")
				end
			end
			return
		end
		local cd = tonumber(info.SpinCooldown or info.DashCooldown or info.DeflectCooldown) or 4
		if now - (MR.abilityAt[name] or 0) < cd then
			return
		end
		local use = false
		if name == "Battle Axe" then
			use = dist <= (tonumber(info.SpinRadius) or 10) - 1
		elseif name == "Scythe" then
			local dashLen = (tonumber(info.DashSpeed) or 100) * (tonumber(info.DashDuration) or 0.25)
			use = dist > reach + 1 and dist < dashLen * 0.9
		elseif name == "Katana" then
			use = S.threatOnMe == true
		end
		if use then
			MR.abilityAt[name] = now
			S.ourShotUntil = now + 0.15
			Combat.facingInput("StartAiming")
			task.delay(0.1, function()
				if S.alive then
					Input.gameInput("FinishAiming")
				end
			end)
			log("INFO", ("melee rage: %s ability on %s (%.1f st)"):format(name, Game.fighterName(f), dist))
		end
	end
	-- Anti-melee: a melee threat is an enemy with a blade out close enough to hit us before we can react
	-- — their reach (the heavy's for crit blades, the Battle Axe's spin radius, the Scythe's dash) plus
	-- what our ping lets them close plus a margin. Responses: our replicated look faces them (h.rot:
	-- the crit is judged on where WE look), a dodge through Body to their side or away onto standable
	-- ground, auto block covers them, we back off while the gun is ready, they get the lock first, and
	-- a hit that lands while one is close dodges at once.
	Combat.am = { dodgeAt = 0, dodgeUntil = 0, spot = nil, hpLast = nil, dodges = 0, threat = {}, req = { hold = 0.25, jump = true } }
	function Combat.meleeThreatRadius(item: any, root: BasePart): (number, number)
		local info = item.Info
		local reach = math.max(tonumber(info.AttackReach) or 6, tonumber(info.HeavyAttackReach) or 0, tonumber(info.SpinRadius) or 0)
		local dash = (tonumber(info.DashSpeed) or 0) * (tonumber(info.DashDuration) or 0)
		local closing = Resolver.fixVel(root).Magnitude * ((S.pingMs or 0) / 1000 + 0.1)
		return reach + dash + closing + cfg.antiMeleeMargin, reach, closing
	end
	-- the nearest melee threat this frame → S.meleeThreat (one reused table) or nil
	function Combat.scanMeleeThreats(enemies: { any })
		local me = S.myRootPart or Game.myRoot()
		local best, bestD, bestR, bestReach, bestItem, bestRoot, bestClose = nil, math.huge, 0, 0, nil, nil, 0
		if me and me.Parent and cfg.antiMelee then
			for _, f in ipairs(enemies) do
				local item = Game.fighterMeleeOut(f)
				local root = item and Game.fighterBody(f)
				if root and not Target.isDead(f) then
					local d = (root.Position - me.Position).Magnitude
					local r, reach, closing = Combat.meleeThreatRadius(item, root)
					if d <= r and d < bestD then
						best, bestD, bestR, bestReach, bestItem, bestRoot, bestClose = f, d, r, reach, item, root, closing
					end
				end
			end
		end
		if not best then
			S.meleeThreat = nil
			return
		end
		local t = Combat.am.threat
		t.fighter, t.pos, t.dist, t.radius, t.reach, t.closing = best, bestRoot.Position, bestD, bestR, bestReach, bestClose
		t.weapon, t.name = tostring(bestItem.Name), Game.fighterName(best)
		S.meleeThreat = t
	end
	-- where to dodge: beside them (they have to turn) or straight away, just out of their reach, on
	-- ground the player can stand on
	function Combat.dodgeSpot(t: any): Vector3?
		local me = S.myRootPart or Game.myRoot()
		if not me then
			return nil
		end
		local away = (me.Position - t.pos) * Vector3.new(1, 0, 1)
		away = if away.Magnitude > 0.1 then away.Unit else Vector3.new(0, 0, 1)
		local side = Vector3.new(-away.Z, 0, away.X)
		local dist = t.reach + cfg.antiMeleeMargin + 3
		local myG = S.safe.groundY(me.Position)
		local hip = if myG then math.clamp(me.Position.Y - myG, 2, 4) else 3
		for _, dir in ipairs({ side, -side, away, (away + side).Unit, (away - side).Unit }) do
			local p = t.pos + dir * dist
			local g = S.safe.groundY(p + Vector3.new(0, 4, 0))
			if g and math.abs(g - (me.Position.Y - hip)) < 10 then
				p = Vector3.new(p.X, g + hip, p.Z)
				if S.safe.standable(p) then
					return p
				end
			end
		end
		return nil
	end
	function Combat.updateAntiMelee(enemies: { any })
		local A = Combat.am
		Combat.scanMeleeThreats(enemies)
		local now = os.clock()
		local t = S.meleeThreat
		local B = Combat.body
		-- a dodge in progress: hold the spot for its short window, then the player keeps it
		if A.spot then
			if now < A.dodgeUntil and Combat.rageOn() then
				B.request("dodge", A.spot, if t then t.pos else nil, A.req)
				return
			end
			A.spot = nil
			B.release("dodge", true)
		end
		if not (cfg.antiMelee and t) or S.menuOpen or S.calibrating or not S.charAlive then
			A.hpLast = Game.myHealth()
			return
		end
		-- a hit that lands while a blade is close: dodge now (a shorter cooldown than the planned dodge)
		local hp = Game.myHealth()
		local hit = hp ~= nil and A.hpLast ~= nil and hp < A.hpLast - 8 and t.dist <= t.reach + 3
		A.hpLast = hp
		-- v6.4: the ragebot owns the body while it fights (magic, autokill, melee rage, defense, backstab):
		-- its planner already keeps the shooting spot out of every blade's reach (Origin.bladePenalty). A
		-- dodge on top took the body off it every 1.5 s — every hop cost a settle, so it never fired
		local rageBody = S.teleported or magic.active or (B.owner ~= nil and B.owner ~= "dodge" and B.owner ~= "peek")
		local fighting = rageBody or Combat.mr.holding or (ak.state ~= "idle" and ak.state ~= "done")
		local inStrike = t.dist <= t.reach + (t.closing or 0) + 1.5
		local cd = if hit then 0.5 else cfg.antiMeleeDodgeCd
		-- gun ready and the next round kills them: shooting beats stepping aside
		local killNow = Game.weaponProfile().gun and Combat.cannotFireFor(S.gameState) <= 0 and S.silentFighter == t.fighter and Combat.killable(t.fighter)
		if cfg.antiMeleeDodge and cfg.silentAim and Combat.rageOn() and not fighting and not killNow and (inStrike or (hit and cfg.antiMeleeOnHit)) and now - A.dodgeAt >= cd then
			local spot = Combat.dodgeSpot(t)
			if spot then
				A.dodgeAt, A.dodgeUntil, A.spot = now, now + 0.3, spot
				A.dodges += 1
				A.req.urgent = nil
				B.request("dodge", spot, t.pos, A.req)
				log("INFO", ("anti-melee: dodged %s's %s (%.1f of %.1f st reach%s)"):format(t.name, t.weapon, t.dist, t.reach, if hit then ", after a hit" else ""))
				return
			end
		end
		-- gun ready and nobody driving the body: back off from the blade (your own keys always win)
		if cfg.antiMeleeKeepDistance and Combat.rageOn() and not fighting and B.owner == nil then
			local prof = Game.weaponProfile()
			if prof.gun and Combat.cannotFireFor(S.gameState) <= 0 then
				local keys = Input.isKeyDown("W") or Input.isKeyDown("A") or Input.isKeyDown("S") or Input.isKeyDown("D")
				local me = S.myRootPart or Game.myRoot()
				local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
				if not keys and me and hum then
					local away = (me.Position - t.pos) * Vector3.new(1, 0, 1)
					if away.Magnitude > 0.1 then
						hum:Move(away.Unit, false)
					end
				end
			end
		end
	end
	-- v5.0.3 defense (defenseHide), void only since v6.1.7: the reload / a long cooldown is when we die.
	-- While the gun cannot fire and somebody can punish it, the body hides where nobody can hit it — the
	-- calibrated sky void of this map, the void under the floor, or a far spot outside every map part —
	-- and lands back on the shooting spot one settle + one echo before the gun is ready, already facing
	-- the lock. Never inside a wall or a floor slab: "in wall" in the duel log was a hide that failed.
	Combat.def = { state = "idle", spot = nil, kind = nil, hopAt = 0, since = 0, reason = nil, hides = 0, remaining = 0, keysHeld = false, vsKind = nil, noSpotUntil = 0, req = { hold = 0.6, pin = true, geometry = false, void = false, sky = false, far = false, budget = true } }
	-- how long the gun in hand cannot fire, from the item's own live stamps (tick-based), plus why
	function Combat.cannotFireFor(gs: any): (number, string?)
		-- items locked (the round-start countdown): nothing fires until the game unlocks them
		if gs and gs.locked then
			return 1, "locked"
		end
		local item = gs and gs.item
		local info = type(item) == "table" and item.Info
		if type(info) ~= "table" or info.Type ~= "Gun" then
			return 0, nil
		end
		local wall = tick()
		local now = os.clock()
		local reload = tonumber(rawget(item, "_reload_cooldown"))
		local left, why = 0, nil
		if reload and reload > wall then
			left, why = reload - wall, "reload"
		elseif S.reloadUntil and now < S.reloadUntil then
			left, why = S.reloadUntil - now, "reload"
		end
		if gs.ammo ~= nil and gs.ammo <= 0 and (gs.reserve or 0) > 0 and left < 0.5 then
			-- an empty mag with reserve is a reload about to start (no reserve: nothing to wait out)
			left, why = math.max(left, 0.8), "empty"
		end
		local stamp = tonumber(rawget(item, "_shoot_cooldown"))
		if stamp and stamp - wall > left then
			left, why = stamp - wall, "cooldown"
		end
		return left, why
	end
	-- the tempo of a fight (v6.1.7). One server echo of a rotation change: the bound Combat.syncReady
	-- waits at most. The fire lead: a body must land that long before the gun is ready to be settled
	-- there and already facing the lock when it is — the first ready frame fires.
	function Combat.echoLead(): number
		return ((S.pingMs or 0) * 1.2 + 120) / 1000
	end
	function Combat.fireLead(): number
		return Combat.settleSec() + Combat.echoLead() + 0.05
	end
	-- our next round's damage on `f` from the gun's own numbers: every pellet counted at 75 % (a cone),
	-- the crit when the aim part is the head (CriticalDamage ≤ 5 is a multiplier, above that a value),
	-- dropoff past its start distance. nil = the gun gives no numbers.
	function Combat.nextShotDamage(f: any): number?
		local gs = S.gameState
		local item = gs and gs.item
		local info = type(item) == "table" and item.Info
		if type(info) ~= "table" or info.Type ~= "Gun" then
			return nil
		end
		local base = tonumber(info.ShootDamage)
		if not base or base <= 0 then
			return nil
		end
		local pellets = tonumber(info.ShootPellets) or 1
		local dmg = base * (if pellets > 1 then pellets * 0.75 else 1)
		local part = S.silentPart
		local crit = tonumber(info.CriticalDamage)
		if crit and info.DisableTraditionalCrits ~= true and typeof(part) == "Instance" and (part.Name == "HitboxHead" or part.Name == "Head") then
			dmg = if crit <= 5 then dmg * crit else math.max(dmg, crit)
		end
		local mult, d0, d1 = tonumber(info.RaycastDamageDropoffMultiplier), tonumber(info.RaycastDamageDropoffStartDistance), tonumber(info.RaycastDamageDropoffEndDistance)
		local from = Game.shotOriginPos()
		local root = Game.fighterBody(f)
		if mult and d0 and from and root then
			local d = (root.Position - from).Magnitude
			if d > d0 then
				local t = if d1 and d1 > d0 then math.clamp((d - d0) / (d1 - d0), 0, 1) else 1
				dmg *= 1 + (mult - 1) * t
			end
		end
		return dmg
	end
	function Combat.killable(f: any): boolean
		if f == nil or Target.isDead(f) then
			return false
		end
		local hp = Game.fighterHealth(f)
		local dmg = Combat.nextShotDamage(f)
		return hp ~= nil and dmg ~= nil and hp > 0 and hp <= dmg
	end
	-- somebody can punish the time our gun is busy: aiming at us (the situation read), or a living enemy
	-- with a gun out, within reach, who has a clear server line to our head
	function Combat.enemyCanHit(enemies: { any }?): boolean
		local sit = S.situation
		if sit and sit.aimingAtMe >= 1 then
			return true
		end
		local list = enemies or S.enemiesNow
		local params = Game.losParams()
		local myHead = S.myHeadPart
		if type(list) ~= "table" or not params or not (myHead and myHead.Parent) then
			return sit ~= nil and sit.exposed == true
		end
		local to = myHead.Position
		local reach = cfg.targetMaxDistance * 1.5
		local n = 0
		for _, f in ipairs(list) do
			if not Target.isDead(f) then
				local eq = Game.enemyEquipped(f)
				local info = type(eq) == "table" and eq.Info
				local eh = Game.fighterHead(f)
				if eh and type(info) == "table" and info.Type == "Gun" then
					local rel = to - eh.Position
					if rel.Magnitude <= reach then
						if workspace:Raycast(eh.Position, rel, params) == nil then
							return true
						end
						n += 1
						if n >= 6 then
							break
						end
					end
				end
			end
		end
		return false
	end
	-- v6.3 an enemy projectile (rocket, grenade launcher, energy round…) closing on us inside its blast:
	-- every enemy gun keeps its live projectiles in _projectile_part_to_model (decompiled Gun, line ~500).
	-- 20 Hz, table reads + positions only.
	Combat.blastAt, Combat.blastNow, Combat.blastLast = 0, false, setmetatable({}, { __mode = "k" })
	function Combat.incomingBlast(me: BasePart?, list: { any }?): boolean
		local now = os.clock()
		if now - Combat.blastAt < 0.05 then
			return Combat.blastNow
		end
		Combat.blastAt = now
		Combat.blastNow = false
		if not (me and me.Parent) or type(list) ~= "table" then
			return false
		end
		local myPos = me.Position
		for _, f in ipairs(list) do
			local item = Game.enemyEquipped(f)
			local info = type(item) == "table" and item.Info
			local map = type(item) == "table" and rawget(item, "_projectile_part_to_model")
			if type(info) == "table" and type(map) == "table" then
				local danger = (tonumber(info.ExplosionRadius) or tonumber(info.BlastRadius) or 6) + 8
				for part in pairs(map) do
					if typeof(part) == "Instance" and part:IsA("BasePart") and part.Parent then
						local d = (part.Position - myPos).Magnitude
						local prev = Combat.blastLast[part]
						Combat.blastLast[part] = d
						if d <= danger and (prev == nil or d < prev) then
							Combat.blastNow = true
							return true
						end
					end
				end
			end
		end
		return false
	end
	-- v6.3 "not worth fighting right now": a reason to hide even while the gun could fire. Needs Defense on
	-- (defenseNeeded asks); the hide ends the moment the reason does and the gun is ready.
	function Combat.noFightReason(list: { any }?, left: number): string?
		local me = S.myRootPart or Game.myRoot()
		if me and S.safe.nearMine(me.Position) then
			return "tripmine"
		end
		if Combat.incomingBlast(me, list) then
			return "incoming explosive"
		end
		local gs = S.gameState
		if gs and gs.item and type(gs.item.Info) == "table" and gs.item.Info.Type == "Gun" and gs.ammo ~= nil and gs.ammo <= 0 and (gs.reserve or 0) <= 0 then
			return "out of ammo"
		end
		local sit = S.situation
		if sit and (sit.hpFrac or 1) < 0.5 and (sit.aimingAtMe or 0) >= 2 then
			return "outnumbered"
		end
		local f = S.silentFighter
		if f == nil then
			return nil
		end
		local canHit = Combat.enemyCanHit(list)
		if canHit and cfg.immuneCheck and Game.fighterImmune(f) then
			return "target immune"
		end
		if canHit and Combat.enemyDeflecting(f) then
			return "target deflecting"
		end
		local root = Game.fighterBody(f)
		local from = Game.shotOriginPos()
		if canHit and root and from then
			local d = (root.Position - from).Magnitude
			local maxR = Combat.gunMaxRange(gs and gs.weapon)
			if maxR and d > maxR and not magic.active then
				return "out of this gun's range"
			end
			local prof = Game.weaponProfile()
			if prof.utility or (prof.melee and not Combat.mr.holding and d > Combat.meleeReach(prof.item) + 15) then
				return if prof.utility then "no weapon out" else "blade out of reach"
			end
		end
		return nil
	end
	function Combat.defenseArmed(): boolean
		return cfg.defenseHide == true and cfg.silentAim == true and Combat.rageOn()
	end
	-- voidspam is its own switch: only the Ragebot's Enable and the lobby gate stop it
	function Combat.voidSpamOn(): boolean
		return cfg.voidSpam == true and cfg.rageEnabled ~= false
	end
	-- voidspam's clock. phase "hide" = parked out in the void, "back" = on your spot; `untilT` ends the
	-- phase. fireAt: the last round we wanted to fire (a round from the void reaches nobody — it is held,
	-- the body comes back and the round goes once the server has us there: pendingFire).
	Combat.vs = { phase = "hide", phaseAt = 0, untilT = 0, fireAt = -10, backAt = nil, pendingFire = false, onAt = nil, hidden = 0, hides = 0, state = "off", reason = "", dist = 0, awaySince = nil, bait = { next = 0, untilT = 0, n = 0, lastAt = nil, hits = 0 } }
	function Combat.voidSpamWants(now: number, left: number): (boolean, string)
		local V = Combat.vs
		local back = cfg.voidSpamBack
		-- auto shoot counts as a click: a gun ready within one fire lead on a lock we can shoot from the way back
		if cfg.voidSpamFireBack and cfg.voidSpamMode ~= "Stay hidden" and Combat.vsAutoWants(left) then
			V.fireAt = now
		end
		-- the round left and someone sits in the floor under us: no Back time spent as their target
		if V.phase == "back" and left > Combat.fireLead() + 0.05 and now - V.fireAt > 0.1 and Combat.underThreat(S.enemiesNow) then
			V.phase, V.phaseAt, V.untilT = "hide", now, now + math.min(cfg.voidSpamHide, math.max(left - Combat.fireLead(), 0.2))
			return true, "enemy under you"
		end
		-- hit while back and the gun cannot answer yet: out now, not after Back time (Body no longer sends a
		-- damaged voidspam spot home — home is the open spot they just hit)
		if V.phase == "back" and S.hurtAt and now - S.hurtAt < 0.4 and left > Combat.fireLead() then
			V.phase, V.phaseAt, V.untilT = "hide", now, now + math.min(cfg.voidSpamHide, math.max(left - Combat.fireLead(), 0.3))
			return true, "hit while back"
		end
		-- fire brings you back: back while you keep firing, then Back time on your spot
		if cfg.voidSpamFireBack and now - V.fireAt < math.max(back, Combat.settleSec() + 0.15) then
			if V.phase ~= "back" then
				V.phase, V.phaseAt = "back", now
			end
			V.untilT = math.max(V.untilT, V.fireAt + back)
			return false, "firing"
		end
		-- nobody on the map to shoot for a while (every enemy warped far out or parked off the map): a Back window
		-- only hands them a target to pop in on. Stay out, and bait instead (Combat.baitNow / vsBaitStep)
		if Combat.vsStalemate(now) then
			-- the mode's own Back window must not open the moment they surface: the punish (vsAutoWants, after
			-- Combat.ENGAGE_DWELL) goes first
			V.untilT = math.max(V.untilT, now + Combat.ENGAGE_DWELL + 0.1)
			if Combat.baitNow(now) then
				V.phase = "back"
				return false, "bait"
			end
			V.phase = "hide"
			return true, "enemy away"
		end
		local mode = cfg.voidSpamMode
		if mode == "Stay hidden" then
			V.phase = "hide"
			return true, "voidspam"
		end
		if mode == "Gun ready" then
			local lead = Combat.fireLead()
			if V.phase == "hide" then
				-- back one settle + one echo before the gun can fire (never before the hide's minimum)
				if now >= V.untilT and left <= lead then
					V.phase, V.phaseAt, V.untilT = "back", now, now + back
					return false, "gun ready"
				end
				return true, "voidspam"
			end
			if left > lead + 0.05 then
				-- the round left (the cooldown stamp moved): straight back out until it is ready again
				V.phase, V.phaseAt, V.untilT = "hide", now, now
				return true, "round fired"
			end
			if now >= V.untilT then
				-- a ready gun that fired nothing: out again for the full hide
				V.phase, V.phaseAt, V.untilT = "hide", now, now + cfg.voidSpamHide
				return true, "voidspam"
			end
			return false, "gun ready"
		end
		-- Timer: hide / back on the clock
		if now >= V.untilT then
			if V.phase == "hide" then
				V.phase, V.phaseAt, V.untilT = "back", now, now + back
			else
				V.phase, V.phaseAt, V.untilT = "hide", now, now + cfg.voidSpamHide
			end
		end
		return V.phase == "hide", if V.phase == "hide" then "voidspam" else "timer"
	end
	-- a round of ours while voidspam runs, from the fire gate: fired from the void it reaches nobody (400 st
	-- gun ray), and for one settle after landing the server still has us out there. Hold it (true), call
	-- the body back and fire it for you once the server has you on your spot.
	function Combat.voidFireHold(): boolean
		if not (Combat.voidSpamOn() and cfg.voidSpamFireBack) or S.featuresPaused then
			return false
		end
		local V = Combat.vs
		local now = os.clock()
		V.fireAt = now
		local away = Combat.body.owner == "defense" and Combat.def.state == "hide"
		local settling = V.backAt ~= nil and now - V.backAt < Combat.settleSec()
		if away or settling then
			V.pendingFire = true
			return true
		end
		return false
	end
	-- voidspam's way back (v7.4): with a silent lock in range the body lands 6 st under the target inside the
	-- floor (autokill Under's spot, Combat.desyncSpot) instead of on your spot; over a target that is itself
	-- buried, onto the slab right above it, where the lock's floor push reaches them. nil = your spot (no lock,
	-- no gun, a target out of reach, dead or spawn-protected)
	function Combat.vsUnderSpot(): (Vector3?, string?, Vector3?)
		local f = S.silentFighter
		local part = S.silentPart
		local model = S.silentTargetModel
		if not (cfg.voidSpamUnder and cfg.silentAim and f ~= nil and model ~= nil and typeof(part) == "Instance" and part.Parent) then
			return nil, nil, nil
		end
		if not Game.weaponProfile().gun or Target.isDead(f) or Game.fighterImmune(f) or S.counter.offMap(f) or not Combat.engageable(model) or S.bounds.isVoidFighter(f) then
			return nil, nil, nil
		end
		local root = Game.fighterBody(f)
		local home = Combat.body.home
		local base = if home then home.Position elseif S.myRootPart then S.myRootPart.Position else nil
		if not (root and base) or ((root.Position - base) * Vector3.new(1, 0, 1)).Magnitude > cfg.voidSpamUnderRange then
			return nil, nil, nil
		end
		local top = S.bounds.buriedTop(model)
		if top then
			return Combat.buriedStand(root.Position, top, base), "over", part.Position
		end
		local spot = Combat.desyncSpot(f, part, model, "Under")
		return spot, if spot then "under" else nil, part.Position
	end
	-- can the way back shoot this lock: under / over them, or your spot sees them (0.15 s memo per fighter)
	function Combat.vsAutoWants(left: number): boolean
		if not (cfg.autoShoot and cfg.silentAim) or left > Combat.fireLead() then
			return false
		end
		local f = S.silentFighter
		if f == nil or S.silentTarget == nil or S.targetImmune or Target.isDead(f) or not Game.weaponProfile().gun then
			return false
		end
		if not Combat.engageable(S.silentTargetModel) then
			return false
		end
		if Combat.vsUnderSpot() then
			return true
		end
		local home = Combat.body.home
		if not home then
			return S.targetVisible == true
		end
		local part = S.silentPart
		local _, model = Game.fighterBody(f)
		if not (typeof(part) == "Instance" and part.Parent and model) then
			return false
		end
		local now = os.clock()
		local c = Combat.homeSeen
		if c and c.f == f and now - c.at < 0.15 then
			return c.v
		end
		local eye = home.Position + Vector3.new(0, Combat.DESYNC_EYE, 0)
		local v = (part.Position - eye).Magnitude <= 400 and Game.rayVisible(model, part, eye)
		Combat.homeSeen = { f = f, at = now, v = v }
		return v
	end
	Combat.vsUnderReq = { hold = 0.4, pin = true, geometry = true, void = true, budget = true, jumpDist = 3 }
	-- the back phase under / over the lock; false = your spot (the caller releases the body)
	function Combat.vsUnderStep(reason: string?, now: number): boolean
		local D = Combat.def
		local backPhase = Combat.voidSpamOn() and (reason == "timer" or reason == "firing" or reason == "gun ready")
		local spot, kind, aim = nil, nil, nil
		if backPhase and now >= (D.underRefusedUntil or 0) then
			spot, kind, aim = Combat.vsUnderSpot()
		end
		if not spot then
			Combat.vsUnderEnd(if backPhase then "no spot" else reason or "not needed")
			return false
		end
		if D.state == "under" and now - D.since > 0.3 and not Combat.body.holds("defense") and Combat.body.owner == nil then
			D.underRefusedUntil = now + 1.5
			Combat.vsUnderEnd("body refused")
			return false
		end
		if D.state ~= "under" then
			local wasHidden = D.state == "hide"
			D.state, D.since = "under", now
			S.defenseHiding = false
			Combat.vs.backAt = now -- the held round waits one settle from here
			log("DEBUG", ("voidspam: back %s %s%s"):format(if kind == "over" then "over the buried" else "under", Game.fighterName(S.silentFighter), if wasHidden then "" else " (from your spot)"))
		end
		D.spot, D.kind = spot, kind
		local r = Combat.vsUnderReq
		r.pin = cfg.defensePinCamera
		local inFloor = kind == "under"
		r.geometry, r.void, r.budget = inFloor, inFloor, inFloor
		if inFloor then
			Combat.noclip.rage(0.6) -- physics would push a body out of the slab between frames
		end
		Combat.body.request("defense", spot, aim, r)
		return true
	end
	function Combat.vsUnderEnd(why: string)
		local D = Combat.def
		if D.state ~= "under" then
			return
		end
		D.state = "idle"
		D.spot, D.kind = nil, nil
		Combat.body.release("defense")
		Combat.vs.backAt = os.clock()
		log("DEBUG", ("voidspam: off the lock → your spot (%s)"):format(why))
	end
	-- every enemy has been off the map (warped far out, parked outside it) for STALEMATE_SEC: nothing to shoot, and
	-- anything we show them is a target. Says once who came back out, and how long after the last bait
	Combat.STALEMATE_SEC = 1.5
	function Combat.vsStalemate(now: number): boolean
		local V = Combat.vs
		local any, back = false, nil
		for _, f in ipairs(S.enemiesNow or {}) do
			if not Target.isDead(f) then
				local _, m = Game.fighterBody(f)
				if m then
					any = true
					if not (Resolver.away(m) or S.counter.offMap(f)) then
						back = f
						break
					end
				end
			end
		end
		if back ~= nil or not any then
			if V.awaySince and back ~= nil and now - V.awaySince >= Combat.STALEMATE_SEC then
				local B = V.bait
				log("INFO", ("[voidspam:bait] %s came back out after %.1f s away%s"):format(Game.fighterName(back), now - V.awaySince, if B.lastAt and now - B.lastAt < 6 then (" · %.1f s after bait #%d"):format(now - B.lastAt, B.n) else ""))
			end
			V.awaySince = nil
			return false
		end
		V.awaySince = V.awaySince or now
		return now - V.awaySince >= Combat.STALEMATE_SEC
	end
	-- is a bait on the map right now? Starts one every voidSpamBaitEvery (±30 %) for voidSpamBaitSec. A hit on it
	-- ends it at once and spaces the next one out; never below 25 % health or while items are locked
	function Combat.baitNow(now: number): boolean
		local B = Combat.vs.bait
		if not cfg.voidSpamBait then
			return false
		end
		if S.hurtAt and now - S.hurtAt < 0.5 then
			if now < B.untilT then
				B.untilT = now
				B.hits += 1
				log("INFO", ("[voidspam:bait] bait #%d was hit — back out, the next one waits longer"):format(B.n))
			end
			B.next = math.max(B.next, now + cfg.voidSpamBaitEvery * 1.5)
			return false
		end
		if now < B.untilT then
			return true
		end
		local hp, mx = Game.myHealth()
		local gs = S.gameState
		if now < B.next or (hp and mx and mx > 0 and hp / mx < 0.25) or not gs or gs.locked or gs.alive == false then
			return false
		end
		B.n += 1
		B.untilT = now + cfg.voidSpamBaitSec
		B.next = B.untilT + cfg.voidSpamBaitEvery * (0.7 + math.random() * 0.6)
		B.lastAt = now
		log("DEBUG", ("[voidspam:bait] #%d · %.2f s on the map · next in ~%.1f s"):format(B.n, cfg.voidSpamBaitSec, B.next - now))
		return true
	end
	-- the bait's spot: 3.5 st under your own spot inside the floor slab when it is thick there (on the map for their
	-- targeting, behind the slab's face for rounds from above). nil = your spot itself (the caller sends the body home)
	function Combat.baitSpot(): Vector3?
		if cfg.voidSpamBaitSpot ~= "In the floor" then
			return nil
		end
		local home = Combat.body.home
		local base = if home then home.Position elseif S.myRootPart then S.myRootPart.Position else nil
		if not base then
			return nil
		end
		local now = os.clock()
		local c = Combat.baitCache
		if c and now - c.at < 2 and (c.base - base).Magnitude < 1 then
			return c.spot
		end
		local spot: Vector3? = nil
		local g = S.safe.groundY(base)
		if g and base.Y - g < 8 then
			local p = Vector3.new(base.X, g - 3.5, base.Z)
			if S.bounds.inGeometry(p + Vector3.new(0, 1.5, 0), 0.5) and S.bounds.inGeometry(p, 0.7) then
				spot = p
			end
		end
		Combat.baitCache = { at = now, base = base, spot = spot }
		return spot
	end
	Combat.baitReq = { hold = 0.4, pin = true, geometry = true, void = true, budget = true }
	-- the bait in the floor (false = no floor spot here: the caller hands the body back to your spot)
	function Combat.vsBaitStep(now: number): boolean
		local D = Combat.def
		local spot = Combat.baitSpot()
		if not spot then
			return false
		end
		if D.state ~= "bait" then
			D.state, D.since = "bait", now
			S.defenseHiding = false
		end
		D.spot, D.kind = spot, "bait"
		local home = Combat.body.home
		local r = Combat.baitReq
		r.pin = cfg.defensePinCamera
		Combat.noclip.rage(0.6) -- physics would push a body out of the slab between frames
		Combat.body.request("defense", spot, if home then home.Position + home.LookVector * 10 else spot + Vector3.new(0, 0, -10), r)
		return true
	end
	-- once per frame: on / off edges, the auto-off timer, the held round, the status the HUD and the menu show
	function Combat.voidSpamTick(now: number)
		local V = Combat.vs
		local on = Combat.voidSpamOn()
		if on and V.onAt == nil then
			V.onAt, V.phase, V.phaseAt, V.untilT = now, "hide", now, now + cfg.voidSpamHide
			V.hidden, V.hides, V.pendingFire, V.backAt, V.fireAt = 0, 0, false, nil, -10
			log("INFO", ("voidspam: on · %s · hide %.1f s / back %.2f s · %s st out%s"):format(cfg.voidSpamMode, cfg.voidSpamHide, cfg.voidSpamBack, Game.studs(cfg.voidSpamDist), if cfg.voidSpamAutoOff > 0 then (" · off in %d s"):format(cfg.voidSpamAutoOff) else ""))
		elseif not on and V.onAt ~= nil then
			log("INFO", ("voidspam: off after %.1f s · %d hides · %.1f s hidden"):format(now - V.onAt, V.hides, V.hidden))
			V.onAt, V.pendingFire = nil, false
		end
		if not on then
			V.state, V.reason = "off", ""
			return
		end
		if cfg.voidSpamAutoOff > 0 and now - V.onAt >= cfg.voidSpamAutoOff then
			cfg.voidSpam = false
			saveConfigSoon()
			notify(("Voidspam turned itself off after %d s"):format(cfg.voidSpamAutoOff), 3, "info")
			return
		end
		local D = Combat.def
		local B = Combat.body
		local hidden = B.owner == "defense" and D.state == "hide" and S.defenseHiding == true
		if hidden then
			V.hidden += math.clamp(now - (V.tickAt or now), 0, 0.1)
		end
		V.tickAt = now
		-- the held round: fired for you once the body is home and the server has had it for one settle
		local landed = B.owner ~= "defense" or (D.state == "under" and B.settledFor("defense"))
		if V.pendingFire and not hidden and landed and V.backAt and now - V.backAt >= Combat.settleSec() then
			V.pendingFire = false
			if Input.gameInput("StartShooting") then
				task.delay(0.05, function()
					if S.alive then
						Input.gameInput("FinishShooting")
					end
				end)
			end
		end
		local root = S.myRootPart
		local home = B.home
		V.dist = if hidden and root and home then ((root.Position - home.Position) * Vector3.new(1, 0, 1)).Magnitude else 0
		if S.featuresPaused then
			V.state, V.reason = "waiting", "lobby: starts in a duel"
		elseif not S.charAlive or (S.gameState and S.gameState.alive == false) then
			V.state, V.reason = "waiting", "respawning"
		elseif S.gameState and S.gameState.weapon == "—" then
			V.state, V.reason = "waiting", "between rounds"
		elseif hidden then
			V.state, V.reason = "hidden", if V.awaySince and now - V.awaySince >= Combat.STALEMATE_SEC then "enemy away" else ""
		elseif D.state == "bait" or now < V.bait.untilT then
			V.state, V.reason = "back", "baiting"
		elseif D.state == "under" and B.owner == "defense" then
			local f = S.silentFighter
			V.state, V.reason = "back", ("%s %s"):format(if D.kind == "over" then "over" else "under", if f then (Game.fighterName(f):gsub(" %[BOT%]", "")) else "the lock")
		elseif B.owner ~= nil and B.owner ~= "defense" then
			-- another system drives the body: name what it is doing right now, not "X has the body"
			V.state, V.reason = if B.owner == "autokill" then "autokill" else "waiting", Combat.ownerStep(B.owner)
		elseif D.state == "hide" then
			V.state, V.reason = "waiting", "no safe spot out there yet"
		else
			V.state, V.reason = "back", if now - V.fireAt < 1 then "firing" else ""
		end
	end
	-- what the system holding the body is doing, in a few words ("settling on Dummy", "firing · 3 hits")
	Combat.OWNER_WORDS = { magic = "magic bullet", meleeRage = "melee rage", backstab = "backstab", dodge = "dodging", peek = "peeking" }
	function Combat.ownerStep(owner: string): string
		if owner == "autokill" then
			local f = ak.fighter
			local name = if f then Game.fighterName(f):gsub(" %[BOT%]", "") else nil
			local step = ak.step or "moving in"
			if step == "firing" then
				return ("firing · %d hit%s"):format(ak.hits or 0, if (ak.hits or 0) == 1 then "" else "s")
			end
			return if name then ("%s · %s"):format(step, name) else step
		end
		return Combat.OWNER_WORDS[owner] or owner
	end
	-- seconds to voidspam's next switch (nil = none planned): the timer, or the gun in Gun ready mode
	function Combat.voidSpamLeft(): number?
		local V = Combat.vs
		local now = os.clock()
		if not Combat.voidSpamOn() or V.state == "off" or V.state == "waiting" or V.state == "autokill" then
			return nil
		end
		local mode = cfg.voidSpamMode
		if V.state == "hidden" and V.reason == "enemy away" then
			return if cfg.voidSpamBait then math.max(V.bait.next - now, 0) else nil
		end
		if V.reason == "baiting" then
			return math.max(V.bait.untilT - now, 0)
		end
		if V.state == "back" and cfg.voidSpamFireBack and now - V.fireAt < math.max(cfg.voidSpamBack, Combat.settleSec() + 0.15) then
			return math.max(V.fireAt + cfg.voidSpamBack - now, 0)
		end
		if mode == "Stay hidden" and V.state == "hidden" then
			return nil
		end
		if mode == "Gun ready" and V.state == "hidden" then
			local left = Combat.cannotFireFor(S.gameState) - Combat.fireLead()
			return math.max(left, V.untilT - now, 0)
		end
		return math.max(V.untilT - now, 0)
	end
	-- one plain line for the menu's "Right now" row
	function Combat.voidSpamLine(): string
		local V = Combat.vs
		if not cfg.voidSpam then
			return "Off"
		end
		if cfg.rageEnabled == false then
			return "Off · the Ragebot is disabled"
		end
		if V.state == "waiting" or V.state == "off" then
			return "Waiting · " .. (if V.reason ~= "" then V.reason else "starts in a duel")
		end
		local left = Combat.voidSpamLeft()
		if V.state == "hidden" and V.reason == "enemy away" then
			return ("Hidden · %s st out · everyone warped away · %s"):format(Game.studs(V.dist), if left then ("bait in %.1f s"):format(left) else "waiting for them")
		end
		if V.state == "hidden" then
			return ("Hidden · %s st out · %s"):format(Game.studs(V.dist), if left then ("back in %.1f s"):format(left) else "until you turn it off")
		end
		if V.reason == "baiting" then
			return ("Baiting · #%d on the map for %.2f s"):format(V.bait.n, cfg.voidSpamBaitSec)
		end
		local tail = if V.reason == "firing" or os.clock() - V.fireAt < 1 then "firing" elseif left then ("out again in %.1f s"):format(left) else "ready"
		if Combat.def.state == "under" and V.reason ~= "" and V.reason ~= "firing" then
			return ("Back %s · %s"):format(V.reason, tail)
		end
		return ("Back on your spot · %s"):format(tail)
	end
	-- a hide is worth the trip: the gun is busy past the fire lead, and (voidspam aside) out, a settle
	-- there, back and a settle + an echo fit, the configured minimum is met and — Only when threatened —
	-- an enemy can punish the wait
	function Combat.hideWorth(left: number, enemies: { any }?): boolean
		if left <= Combat.fireLead() then
			return false
		end
		if cfg.voidSpam then
			return true
		end
		if left < math.max(cfg.defenseMinCooldown, Combat.settleSec() * 2 + Combat.echoLead() + 0.1) then
			return false
		end
		return not cfg.defenseOnlyWhenThreat or Combat.enemyCanHit(enemies)
	end
	-- magic's own park (no defense armed): the gun is busy past the fire lead and a trip out and back fits
	function Combat.parkWorth(left: number): boolean
		return left > Combat.fireLead() and left > Combat.settleSec() * 2 + Combat.echoLead() + 0.1
	end
	-- a stored sky height is a real void only well over the whole map: measured from our feet it could sit
	-- a few dozen studs above the tallest parts, in plain sight of the arena (the box top carries 40 st of
	-- padding, so this is ≥ 100 st over the tallest parts)
	function Combat.skyOk(y: any): boolean
		if type(y) ~= "number" then
			return false
		end
		local box = S.safe.mapBox()
		return box == nil or y >= box.max.Y + 60
	end
	-- the game's gun ray (CONSTANTS.MAX_RAYCAST_DISTANCE): no round reaches past it
	function Combat.gunRay(): number
		if Combat.gunRayLen then
			return Combat.gunRayLen
		end
		-- a miss walks the whole loaded-module list (~3 ms): once per 5 s, 400 in between
		local now = os.clock()
		if now - (Combat.gunRayTry or -10) < 5 then
			return 400
		end
		Combat.gunRayTry = now
		local mods = ReplicatedStorage:FindFirstChild("Modules")
		local C = Game.requireIfLoaded(mods and mods:FindFirstChild("CONSTANTS"))
		local n = type(C) == "table" and tonumber(C.MAX_RAYCAST_DISTANCE)
		if n and n > 0 then
			Combat.gunRayLen = n
			return n
		end
		return 400
	end
	-- the void under the map: more than one gun ray under the map's bottom (nobody on the map reaches it,
	-- and the map covers it) and under any kill volume at that spot — the server runs the volumes itself,
	-- the OOB guard only silences our client's report — above FallenPartsDestroyHeight
	Combat.VOID_BELOW = 60
	function Combat.voidTargetY(at: Vector3): number?
		local box = S.safe.mapBox()
		if not box then
			return nil
		end
		local floor = workspace.FallenPartsDestroyHeight + 150
		local y = math.max(box.min.Y - Combat.gunRay() - Combat.VOID_BELOW, floor)
		local B = S.bounds
		for _ = 1, 8 do
			local c = B.check(Vector3.new(at.X, y, at.Z))
			if not (c and c.lethal) then
				return y
			end
			local p = c.part
			local cf, h = p.CFrame, p.Size * 0.5
			local halfY = math.abs(cf.RightVector.Y) * h.X + math.abs(cf.UpVector.Y) * h.Y + math.abs(cf.LookVector.Y) * h.Z
			local under = math.max(cf.Position.Y - halfY - 30, floor)
			if under >= y - 0.5 then
				return nil
			end
			y = under
		end
		return nil
	end
	-- a stored depth is used while it still sits under this map and above the kill height
	function Combat.voidOk(y: any): boolean
		if type(y) ~= "number" or y < workspace.FallenPartsDestroyHeight + 100 then
			return false
		end
		local box = S.safe.mapBox()
		return box == nil or y <= box.min.Y - Combat.VOID_BELOW
	end
	-- one measured void per map: several duel maps load into the same PlaceId, so the key carries the
	-- map's box corner
	function Combat.voidKey(): string?
		local box = S.safe.mapBox()
		if not box then
			return nil
		end
		return tostring(game.PlaceId) .. (":%d:%d"):format(math.floor(box.min.X / 50 + 0.5), math.floor(box.min.Z / 50 + 0.5))
	end
	function Combat.voidY(): number?
		local key = Combat.voidKey()
		local y = key and cfg.voidDepths[key]
		return if Combat.voidOk(y) then y else nil
	end
	-- magic with a defense armed holds the body only for its fire window; the rest of the cooldown goes
	-- to the hide (only while a hide spot was found a moment ago — else the body would just go home)
	function Combat.magicYields(busy: number): boolean
		if not Combat.defenseArmed() or os.clock() < (Combat.def.noSpotUntil or 0) then
			return false
		end
		return Combat.hideWorth(busy, S.enemiesNow)
	end
	function Combat.moveKeysDown(): boolean
		return Input.isKeyDown("W") or Input.isKeyDown("A") or Input.isKeyDown("S") or Input.isKeyDown("D") or Input.isKeyDown("Space")
	end
	-- where our head will be when a hide hands the body back: magic's shooting spot while magic runs,
	-- else where the player stood. The stream faces the lock from there while we hide (h.rot), so the
	-- echo already matches when the body lands.
	function Combat.landingHead(): Vector3?
		local mt = Combat.magicThreat
		local base: Vector3? = nil
		local under = if Combat.voidSpamOn() and cfg.voidSpamUnder and not magic.active then Combat.vsUnderSpot() else nil
		if magic.active and mt.spot then
			base = mt.spot
		elseif under then
			base = under
		elseif Combat.body.home then
			base = Combat.body.home.Position
		end
		return if base then base + Vector3.new(0, 1.85, 0) else nil
	end
	-- per-round tempo: how much of the fight the gun sat ready on a shootable lock without a round
	-- leaving (and why), how long we were hidden, rounds fired against what the cooldown allowed, and how
	-- long a new lock took to its first round. One [tempo] line with the round summary.
	Combat.tempo = { engaged = 0, idle = 0, idleSync = 0, idleSettle = 0, idleHide = 0, idleOther = 0, hidden = 0, shots = 0, possible = 0, firsts = 0, firstSum = 0, lockAt = nil, first = false, wasReady = false }
	function Combat.tempoReset()
		local T = Combat.tempo
		T.engaged, T.idle, T.idleSync, T.idleSettle, T.idleHide, T.idleOther = 0, 0, 0, 0, 0, 0
		T.hidden, T.shots, T.possible, T.firsts, T.firstSum = 0, 0, 0, 0, 0
	end
	function Combat.tempoTick(dt: number)
		local T = Combat.tempo
		dt = math.clamp(dt, 0, 0.1)
		Combat.settleDecay()
		local hidden = S.defenseHiding == true or ak.hiding == true or ak.state == "void"
		if hidden then
			T.hidden += dt
		end
		local f = S.silentFighter
		local gs = S.gameState
		local item = gs and gs.item
		local info = type(item) == "table" and item.Info
		-- spawn protection: nothing lands, so the first-shot clock starts when it drops
		if f == nil or not S.alive or type(info) ~= "table" or info.Type ~= "Gun" or S.targetImmune then
			T.lockAt, T.wasReady = nil, false
			return
		end
		local now = os.clock()
		if T.lockAt == nil then
			T.lockAt, T.first = now, true
		end
		T.engaged += dt
		local orig = S.statOriginals[tostring(item.Name)]
		local cd = tonumber(orig and orig.ShootCooldown) or tonumber(info.ShootCooldown)
		if cd and cd > 0 then
			T.possible += dt / cd
		end
		local ready = Combat.cannotFireFor(gs) <= 0
		if T.wasReady and not ready then
			-- the cooldown stamp moved: a round left
			T.shots += 1
			if T.first then
				T.first = false
				T.firsts += 1
				T.firstSum += now - T.lockAt
			end
		end
		T.wasReady = ready
		if ready and S.targetVisible ~= false and not S.targetImmune then
			T.idle += dt
			-- a hide hops (voidspam) and never settles: it counts as hiding, not as a settle wait
			if hidden then
				T.idleHide += dt
			elseif S.syncWaiting then
				T.idleSync += dt
			elseif S.teleported and not Combat.settled() then
				T.idleSettle += dt
			else
				T.idleOther += dt
			end
		end
	end
	function Combat.tempoLine(): string
		local T = Combat.tempo
		local e = math.max(T.engaged, 1e-3)
		local function pct(v: number): number
			return math.floor(v / e * 100 + 0.5)
		end
		return ("[tempo] engaged %.0f s · ready-idle %d%% (sync %d, settle %d, hide %d, other %d) · hidden %.0f s · shots %d of %d possible · first shot %s"):format(
			T.engaged, pct(T.idle), pct(T.idleSync), pct(T.idleSettle), pct(T.idleHide), pct(T.idleOther), T.hidden, T.shots, math.floor(T.possible + 0.5),
			if T.firsts > 0 then ("%.2f s"):format(T.firstSum / T.firsts) else "—"
		)
	end
	function Combat.defenseNeeded(enemies: { any }?): (boolean, string?)
		local vs = Combat.voidSpamOn()
		if not (vs or Combat.defenseArmed()) or S.hudEdit or S.calibrating or not S.alive or not S.charAlive or S.featuresPaused then
			return false, nil
		end
		-- a plain hide waits for the menu to close; voidspam keeps you out there while you tune it
		if S.menuOpen and not vs then
			return false, nil
		end
		if (ak.state ~= "idle" and ak.state ~= "done") or Combat.mr.holding or S.peek then
			return false, nil
		end
		-- dead or unarmed between rounds: Body moves nothing then (the duel log retried a refused
		-- voidspam hide every second until the respawn)
		local gs = S.gameState
		if gs and (gs.alive == false or gs.weapon == "—") then
			return false, nil
		end
		-- magic's fire window: it asked for the body this frame (its step runs first). Defense never takes
		-- the body from magic — magic hands it over itself once the round has left (Combat.magicYields)
		if magic.wantsBody then
			return false, "magic fire window"
		end
		local now = os.clock()
		local D = Combat.def
		if now < (D.refusedUntil or 0) then
			return false, nil -- Body refused the last hide a moment ago
		end
		-- your own movement keys take the body back from a plain hide (a press made after the hide
		-- began; the Humanoid's MoveDirection is no good — our own teleport leaves it walking). Voidspam
		-- ignores them unless "Movement brings you back" is on: every strafe used to end it (unstable)
		local moveBack = not vs or cfg.voidSpamMoveBack
		if moveBack and now < (D.blockedUntil or 0) then
			return false, nil -- you moved: your body stays yours for a moment
		end
		if moveBack and D.state == "hide" then
			local keys = Combat.moveKeysDown()
			if D.keysHeld and not keys then
				D.keysHeld = false -- the walk that was on when the hide began has ended
			elseif keys and not D.keysHeld then
				D.blockedUntil = now + (if vs then math.max(cfg.voidSpamBack, 0.6) else 1.5)
				log("INFO", ("[hide:abort:moved] after %.1f s · body %s"):format(now - (D.since or now), Combat.body.owner or "you"))
				return false, "moved"
			end
		end
		local left, why = Combat.cannotFireFor(S.gameState)
		D.remaining = left
		if vs then
			return Combat.voidSpamWants(now, left)
		end
		if enemies and #enemies == 0 then
			return false, nil -- nobody here to hide from
		end
		-- an enemy void spammer is away: no round of ours reaches them and they pop up to shoot. Mirror
		-- them — hidden while they are away, back the moment they surface (the punish window)
		if S.counter.spammerAway(enemies or S.enemiesNow) then
			return true, "enemy voidspam"
		end
		-- someone in the floor under us shoots up through it; with the gun busy nothing answers them — out until
		-- it can fire (then the lock's floor push does)
		if left > Combat.fireLead() and Combat.underThreat(enemies or S.enemiesNow) then
			return true, "enemy under you"
		end
		local noFight = Combat.noFightReason(enemies or S.enemiesNow, left)
		if noFight then
			return true, noFight
		end
		-- the kill window: a lock the next round kills, with the gun ready inside one settle — shoot
		local f = S.silentFighter
		if left <= Combat.settleSec() and f ~= nil and Combat.killable(f) then
			return false, "kill window"
		end
		if D.state == "hide" then
			-- land one settle + one echo before the gun is ready: settled there and facing the lock
			if left <= Combat.fireLead() then
				return false, "gun ready"
			end
			return true, why
		end
		if not Combat.hideWorth(left, enemies) then
			return false, nil
		end
		local pending = S.shots and S.shots.pending
		local inFlight = pending ~= nil and #pending > 0 and now - (pending[#pending].t or 0) < 0.4
		return true, if inFlight and why == "cooldown" then "shot in flight" else why
	end
	-- v0.9: every hide is the far spot (Combat.farSpot: 10k+ st past the map's edge, on a local pad). The
	-- old candidates — the measured void ~100 st under the map, a few studs under the floor slab, the sky
	-- over the arena — were all inside gun / wallbang / magic-bullet reach: a "hide" there hid nothing.
	-- Defense, voidspam, Auto-HvH, the hurt hide and the autokill rest all come through here.
	Combat.hideCands = {}
	function Combat.hideSpots(me: Vector3): { any }
		local out = Combat.hideCands
		table.clear(out)
		local far = Combat.farSpot(me)
		if far then
			table.insert(out, { pos = far, kind = "far", d = (far - me).Magnitude })
		end
		return out
	end
	-- the hide spot: voidSpamDist (10k–90k) past the map's edge in a random flat direction, level with where
	-- you stood — never lower than 400 st over the kill height (the old far spot sat 60 st over
	-- FallenPartsDestroyHeight and one frame hitch dropped the body through it). Safe.check (far) has the last
	-- word: no kill volume, nothing solid there. The body rests on a local pad (Combat.padAt), so it never
	-- falls. One direction per 8 s per map: a hide keeps its spot. v0.9: eight directions at the full
	-- distance first, each clipped to the world's ±98k (Safe refuses past 1e5) instead of being skipped.
	Combat.FAR_TRIES = 16
	Combat.FAR_WORLD = 9.8e4
	Combat.farReq = { hold = 30, far = true, geometry = false, void = false, sky = false }
	function Combat.farSpot(me: Vector3): Vector3?
		local now = os.clock()
		local key = tostring(game.PlaceId) .. ":" .. tostring(cfg.voidSpamDist)
		local fc = Combat.farCache
		if fc and fc.key == key and now - fc.at < 8 and fc.pos then
			return fc.pos
		end
		local box = S.safe.mapBox()
		local center = if box then (box.min + box.max) * 0.5 else me
		local half = if box then (box.max - box.min) * 0.5 else Vector3.new(500, 0, 500)
		local edge = math.max(half.X, half.Z)
		local y = math.max(me.Y, workspace.FallenPartsDestroyHeight + 400)
		local best: Vector3? = nil
		local why: string? = nil
		local base = math.random() * math.pi * 2
		local W = Combat.FAR_WORLD
		for i = 0, Combat.FAR_TRIES - 1 do
			-- ring 0: eight directions at the full distance; each further ring (4 each) steps 5,000 st closer
			local ring = if i < 8 then 0 else 1 + math.floor((i - 8) / 4)
			local a = if ring == 0 then base + i * (math.pi / 4) else base + (i % 4) * (math.pi / 2) + ring * 0.7
			local cx, cz = math.cos(a), math.sin(a)
			local dist = math.max(10000, cfg.voidSpamDist - ring * 5000) + edge
			-- the longest step along this bearing that stays inside ±W on both axes
			local lim = math.huge
			if math.abs(cx) > 1e-3 then
				lim = math.min(lim, ((if cx > 0 then W else -W) - center.X) / cx)
			end
			if math.abs(cz) > 1e-3 then
				lim = math.min(lim, ((if cz > 0 then W else -W) - center.Z) / cz)
			end
			dist = math.min(dist, lim)
			local p = Vector3.new(center.X + cx * dist, y, center.Z + cz * dist)
			if dist >= 10000 then
				local ok, w = S.safe.check(p, Combat.farReq)
				if ok then
					best = p
					break
				end
				why = why or w
			end
		end
		Combat.farCache = { key = key, at = now, pos = best, why = why }
		return best
	end
	-- kind costs per mode: Auto / Void take the measured void under the map, Sky the calibrated sky; under
	-- the floor stands in while a map has no measured void; the far spot is the last resort. Distance does
	-- not count: every one of them is out of reach.
	Combat.HIDE_COST = {
		Auto = { void = 0, slab = 20, far = 30 },
		Void = { void = 0, slab = 20, far = 30 },
		Sky = { sky = 0, void = 10, slab = 25, far = 30 },
	}
	function Combat.pickHide(me: Vector3, enemies: { any }): any
		local cands = Combat.hideSpots(me)
		if #cands == 0 then
			return nil
		end
		local B = S.bounds
		local params = Game.losParams()
		local cost = Combat.HIDE_COST[cfg.defenseMode] or Combat.HIDE_COST.Auto
		local ray = Combat.gunRay()
		local best, bestS = nil, math.huge
		local req = Combat.def.req
		Combat.hideRefuse = nil
		Combat.skyRefuse = nil
		Combat.voidRefuse = nil
		for _, c in ipairs(cands) do
			req.void, req.sky, req.far = c.kind == "void" or c.kind == "slab", c.kind == "sky", c.kind == "far"
			req.hold = if c.kind == "slab" and cfg.defenseVoidSpam then 0.25 else 0.6
			local okB, whyB = S.safe.check(c.pos, req)
			if not okB then
				if Combat.hideRefuse == nil then
					Combat.hideRefuse = ("%s: %s"):format(c.kind, tostring(whyB))
				end
				if c.kind == "sky" and Combat.skyRefuse == nil then
					Combat.skyRefuse = tostring(whyB)
				end
				if c.kind == "void" and Combat.voidRefuse == nil then
					Combat.voidRefuse = tostring(whyB)
				end
			end
			local vol = if okB then B.check(c.pos) else nil
			if okB then
				local s = cost[c.kind] or 50
				if vol and vol.lethal then
					s += 15 -- a volume with a running clock is the last choice
				end
				-- who can hit the spot: inside one gun ray of their head with a clear line through the
				-- whitelist; a far spot is past every gun
				if params and c.kind ~= "far" then
					local n = 0
					for _, f in ipairs(enemies) do
						local eh = Game.fighterHead(f)
						if eh and not Target.isDead(f) then
							local to = c.pos - eh.Position
							if to.Magnitude <= ray and workspace:Raycast(eh.Position, to, params) == nil then
								s += 30
							end
							n += 1
							if n >= 6 then
								break
							end
						end
					end
				end
				-- voidspam: never the spot we are already on
				local D = Combat.def
				if D.spot and (D.spot - c.pos).Magnitude < 2 and cfg.defenseVoidSpam then
					s += 4
				end
				if s < bestS then
					best, bestS = c, s
				end
			end
		end
		return best
	end
	-- the hide is over: Body takes the body home, or straight to whoever wants it next (magic)
	function Combat.defenseReturn(why: string)
		local D = Combat.def
		if D.state ~= "hide" then
			return
		end
		D.state = "idle"
		D.spot, D.kind, D.voidSince = nil, nil, nil
		S.defenseHiding = false
		Combat.body.release("defense")
		local vs = Combat.voidSpamOn()
		if vs then
			Combat.vs.backAt = os.clock() -- the held round waits one settle from here
		end
		-- voidspam's timer hands the body back every cycle: one DEBUG line, not an INFO per second
		log(if vs and (why == "timer" or why == "firing" or why == "gun ready" or why == "bait") then "DEBUG" else "INFO", ("%s: back after %.1f s (%s)"):format(if vs then "voidspam" else "defense", os.clock() - (D.since or os.clock()), why))
	end
	-- where a hide went, for the log: the void under the map at its depth, the sky, the voidspam spot far
	-- out in the void, the stand-in under the floor
	function Combat.hideWhere(spot: any): string
		if spot.kind == "sky" then
			return ("in sky void Y %.0f"):format(spot.pos.Y)
		elseif spot.kind == "far" then
			return ("%s st out in the void (Y %.0f)"):format(Game.studs(spot.d), spot.pos.Y)
		elseif spot.kind == "slab" then
			return ("under the floor %.0f st away"):format(spot.d)
		end
		local box = S.safe.mapBox()
		return ("in void Y %.0f (%.0f st under the map)"):format(spot.pos.Y, if box then box.min.Y - spot.pos.Y else spot.d)
	end
	-- voidspam says where it parks once per duel and per change of place (the measured void, or why it
	-- could not); Combat.pauseAll clears it for the next duel
	function Combat.noteVoidspam(spot: any)
		local D = Combat.def
		if not cfg.voidSpam or D.vsKind == spot.kind then
			return
		end
		D.vsKind = spot.kind
		if spot.kind == "far" then
			log("INFO", ("voidspam: parked %s"):format(Combat.hideWhere(spot)))
			return
		elseif spot.kind == "void" then
			local box = S.safe.mapBox()
			log("INFO", ("voidspam: calibrated Y %.0f%s"):format(spot.pos.Y, if box then (" (%.0f st under the map)"):format(box.min.Y - spot.pos.Y) else ""))
			return
		elseif spot.kind == "sky" then
			log("INFO", ("voidspam: calibrated Y %.0f (sky)"):format(spot.pos.Y))
			return
		end
		local why
		local key = Combat.voidKey()
		local stored = key and cfg.voidDepths[key]
		if Combat.voidRefuse then
			why = Combat.voidRefuse
		elseif stored == nil then
			why = "no void measured on this map yet"
		elseif not Combat.voidOk(stored) then
			why = ("stored void Y %.0f does not fit this map — measuring again"):format(stored)
		else
			why = "the void ranked lower here"
		end
		log("INFO", ("voidspam: under the floor (the measured void was refused: %s)"):format(why))
	end
	-- v5.0.5 OOB guard probe (item 3 "verified live"): park the body in the nearest killing volume with
	-- the guard on for longer than its warn+kill budget, watching HP and the suppressed-report counter,
	-- then return. Aborts the moment HP drops. Debug → Bounds button / S.oobProbe(). Result in the log
	-- and S.oobProbeResult.
	Combat.oobProbing = false
	Combat.oobProbeOpts = { holdSec = 0.6, noclip = true, mark = false }
	function Combat.oobProbe(extraSec: number?)
		if Combat.oobProbing then
			return "already running"
		end
		Combat.body.goHome("oob probe")
		local B = S.bounds
		B.refresh(true)
		local me = S.myRootPart or Game.myRoot()
		if not (me and me.Parent) then
			return "no body"
		end
		if (B.n or 0) == 0 then
			log("WARN", "oob probe: no OutOfBoundsPart volumes on this map")
			return "no volumes"
		end
		local best, bestD, bestBudget = nil, math.huge, nil
		for _, p in ipairs(B.parts) do
			if p.Parent then
				local budget = B.budget(p)
				if budget < math.huge then
					local d = (p.Position - me.Position).Magnitude
					if d < bestD then
						best, bestD, bestBudget = p, d, budget
					end
				end
			end
		end
		if not best then
			log("WARN", "oob probe: every volume here is warn-only")
			return "no lethal volume"
		end
		local spot = best.Position
		-- the volume centre may be solid rock: step up inside the volume until the body-box is free
		local tries = 0
		while tries < 6 and B.inGeometry(spot, 1) do
			tries += 1
			spot += Vector3.new(0, 6, 0)
			if not B.inside(best, spot) then
				spot = best.Position + Vector3.new(0, best.Size.Y * 0.45, 0)
				break
			end
		end
		local holdSec = math.min(bestBudget + (extraSec or 2), 12)
		local savedBlock = cfg.oobBlock
		cfg.oobBlock = true
		Combat.oobProbing = true
		local returnCF = LP.Character and LP.Character:GetPivot() or me.CFrame
		local hp0 = Game.myHealth() or 0
		local supp0 = S.oobSuppressed or 0
		local swallowed0 = S.oobSwallowed or 0
		log("INFO", ("oob probe: %s budget %.1f s → holding %.1f s at %s (guard on)"):format(best.Name, bestBudget, holdSec, tostring(spot)))
		task.spawn(function()
			local t0 = os.clock()
			local result = "survived"
			local peakLeft = nil
			while os.clock() - t0 < holdSec do
				if not S.alive then
					result = "unloaded"
					break
				end
				local hp = Game.myHealth()
				if hp ~= nil and hp < hp0 - 5 then
					result = ("HP dropped %.0f → %.0f at %.1f s"):format(hp0, hp, os.clock() - t0)
					break
				end
				local char = LP.Character
				if not (char and char.PrimaryPart) then
					result = ("character gone at %.1f s (killed?)"):format(os.clock() - t0)
					break
				end
				Combat.relocate(spot, spot + Vector3.new(0, 0, -1), Combat.oobProbeOpts)
				local left = B.secondsLeft()
				if left ~= nil then
					peakLeft = left
				end
				RunService.Heartbeat:Wait()
			end
			local held = os.clock() - t0
			local char = LP.Character
			if char and char.PrimaryPart then
				char:PivotTo(returnCF)
				char.PrimaryPart.AssemblyLinearVelocity = Vector3.zero
				Combat.markTeleport()
			end
			Combat.noclip.release()
			cfg.oobBlock = savedBlock
			Combat.oobProbing = false
			local verdict = ("oob probe: %s after %.1f s in %s (budget %.1f s) · client reports suppressed %d · remotes swallowed %d · budget clock left %s"):format(result, held, best.Name, bestBudget, (S.oobSuppressed or 0) - supp0, (S.oobSwallowed or 0) - swallowed0, if peakLeft then ("%.1f s"):format(peakLeft) else "—")
			S.oobProbeResult = { result = result, held = held, budget = bestBudget, volume = best.Name, suppressed = (S.oobSuppressed or 0) - supp0, swallowed = (S.oobSwallowed or 0) - swallowed0, at = os.time() }
			log(if result == "survived" and held >= bestBudget then "INFO" else "WARN", verdict)
			notify(if result == "survived" and held >= bestBudget then ("OOB guard holds vs the server: %.1f s in a %.1f s volume"):format(held, bestBudget) else ("OOB probe: " .. result), 6, if result == "survived" then "ok" else "warn")
		end)
		return "started"
	end
	S.oobProbe = Combat.oobProbe
	function Combat.holdHide()
		local D = Combat.def
		if not D.spot then
			return
		end
		-- face the lock (the trigger may fire out of the cover) or where the player stood facing
		local B = Combat.body
		local aim = S.silentTarget or (B.home and B.home.Position + B.home.LookVector * 10) or (D.spot + Vector3.new(0, 0, -1))
		local req = D.req
		req.pin = cfg.defensePinCamera
		req.void, req.sky, req.far = D.kind == "void" or D.kind == "slab", D.kind == "sky", D.kind == "far"
		req.hold = if D.kind == "slab" and cfg.defenseVoidSpam then 0.25 else 0.6
		B.request("defense", D.spot, Vector3.new(aim.X, D.spot.Y, aim.Z), req)
		S.defenseHiding = B.holds("defense")
		-- the way back lands pre-faced: while we hide the stream faces the lock from where the head will
		-- be, and for the last stretch before the fire window it faces it whatever the trigger does
		S.preFaceFrom = Combat.landingHead()
		local left, why = Combat.cannotFireFor(S.gameState)
		S.preFace = S.silentTarget ~= nil and (left <= Combat.fireLead() + Combat.echoLead() or why == "locked")
	end
	function Combat.updateDefense(enemies: { any })
		local D = Combat.def
		local now = os.clock()
		if D.state ~= "hide" then
			S.defenseHiding = false -- the camera pin and the shot origin read this: never stale
		end
		local need, reason = Combat.defenseNeeded(enemies)
		local me = S.myRootPart or Game.myRoot()
		if not (me and me.Parent) then
			if D.state == "hide" then
				Combat.defenseReturn("no body")
			end
			Combat.vsUnderEnd("no body")
			if D.state == "bait" then
				D.state = "idle"
				Combat.body.release("defense")
			end
			return
		end
		if not need then
			if reason == "bait" and Combat.vsBaitStep(now) then
				return
			end
			local wasBait = D.state == "bait"
			if wasBait then
				D.state = "idle"
				D.spot, D.kind = nil, nil
			end
			if Combat.vsUnderStep(reason, now) then
				return
			end
			if D.state == "hide" then
				Combat.defenseReturn(reason or "not needed")
			elseif wasBait and Combat.body.owner == "defense" then
				Combat.body.release("defense")
			end
			return
		end
		if D.state == "under" or D.state == "bait" then
			-- out of the floor straight into the hide: same owner, the body never stops on your spot
			D.state = "idle"
			D.spot, D.kind = nil, nil
		end
		-- Body refused our last hide (its time limit, no safe spot) or someone outranks us: not hiding
		if D.state == "hide" and now - D.since > 0.3 and not Combat.body.holds("defense") and Combat.body.owner == nil then
			D.refusedUntil = now + 1
			Combat.farCache = nil -- voidspam: a fresh direction next time
			Combat.defenseReturn("body refused")
			return
		end
		if D.state ~= "hide" then
			-- hide spots are searched around where the player stands (Body's home when something
			-- else already holds the body — never around a previous hide spot)
			local from = if Combat.body.home then Combat.body.home.Position else me.Position
			local spot = Combat.pickHide(from, enemies)
			if not spot then
				-- nowhere safe: magic keeps the body for a moment instead of handing it to nobody
				D.noSpotUntil = now + 1
				if Combat.body.owner == "defense" then
					Combat.body.release("defense") -- left the floor under a lock with nowhere to hide: your spot
				end
				if now - (D.noSpotLogAt or 0) > 3 then
					D.noSpotLogAt = now
					local code = if #Combat.hideCands == 0 then "no-candidates" else string.gsub(string.match(tostring(Combat.hideRefuse), ": (.+)$") or "refused", " ", "-")
					log("INFO", ("[hide:refuse:%s] no hide spot here (%s, gun %.2f s) — %d candidate(s)%s · body %s"):format(code, reason or "?", D.remaining or 0, #Combat.hideCands, if Combat.hideRefuse then ", first refusal " .. Combat.hideRefuse else "", Combat.body.owner or "you"))
				end
				return
			end
			D.state = "hide"
			D.since = now
			D.reason = reason
			D.hides += 1
			D.keysHeld = Combat.moveKeysDown()
			D.spot, D.kind, D.hopAt, D.voidSince = spot.pos, spot.kind, now, nil
			if Combat.voidSpamOn() then
				Combat.vs.hides += 1
				log("DEBUG", ("voidspam: hiding %s (%s)"):format(Combat.hideWhere(spot), reason or "?"))
			else
				log("INFO", ("defense: hiding (%s, %.2f s) %s"):format(reason or "?", D.remaining or 0, Combat.hideWhere(spot)))
			end
			Combat.noteVoidspam(spot)
		else
			-- out of a lethal volume before its clock runs down, a fresh spot every hop for voidspam. The
			-- stand-in under the floor is capped at 2.5 s per visit whatever Bounds says — a kill the tag
			-- cache does not know about must never get the time. The measured void has no clock. Out of
			-- time: the void or the far spot, never a wall; nothing safe left → home.
			local left = S.bounds.secondsLeft()
			if D.kind == "slab" then
				D.voidSince = D.voidSince or now
				if now - D.voidSince > 2.5 then
					left = 0
				end
			else
				D.voidSince = nil
			end
			local mustMove = left ~= nil and left < 1.2
			-- the voidspam spot out in the void stays put for the whole hide: nobody reaches it, and a hop
			-- there only cost a teleport per hop (the old "unstable")
			if mustMove or (cfg.defenseVoidSpam and D.kind ~= "far" and now - D.hopAt >= 1 / math.max(cfg.defenseHopHz, 1)) then
				local from = if Combat.body.home then Combat.body.home.Position else me.Position
				local spot = Combat.pickHide(from, enemies)
				if spot and (not mustMove or spot.kind ~= "slab") then
					if spot.kind ~= D.kind then
						log("INFO", ("defense: moving %s (%s)"):format(Combat.hideWhere(spot), if mustMove then "volume clock" else "hop"))
					end
					D.spot, D.kind, D.hopAt = spot.pos, spot.kind, now
					Combat.noteVoidspam(spot)
				elseif mustMove then
					Combat.defenseReturn("volume clock")
					return
				end
			end
		end
		Combat.holdHide()
	end
	-- Hop or Orbit for this moment: Auto hops when the area is hot (crowd, several guns on us, low
	-- HP — a still shooter is easy to line up), orbits otherwise
	function Combat.akMove(): string
		local m = cfg.autokillMove
		if m ~= "Auto" then
			return m
		end
		local sit = S.situation
		if sit and (sit.crowd or sit.aimingAtMe >= 2 or sit.hpFrac < 0.5) then
			return "Hop"
		end
		return "Orbit"
	end

	-- target choice for autokill: nearest by default; adaptive mode scores every candidate — closer,
	-- looking at us and low on health is good, standing in a crowd or deflecting is bad; the dead
	-- and the spawn-protected never qualify
	Combat.akSkip = setmetatable({}, { __mode = "k" })
	function Combat.akScore(f: any, from: Vector3, enemies: { any }): (number?, number)
		local r = Game.fighterBody(f)
		if not r then
			return nil, math.huge
		end
		if (cfg.deadTargetGuard and Target.isDead(f)) or (cfg.immuneCheck and Game.fighterImmune(f)) then
			return nil, math.huge
		end
		-- v6.3: parked in the sky / outside the arena (nothing safe to shoot from), or refused a moment ago
		local _, rm = Game.fighterBody(f)
		if S.counter.offMap(f) or os.clock() < (Combat.akSkip[f] or 0) or not Combat.engageable(rm) then
			return nil, math.huge
		end
		local d = (r.Position - from).Magnitude
		-- a void camper straight below is close, whatever the depth says: judge them by the flat distance
		if S.bounds.isVoidFighter(f) then
			d = ((r.Position - from) * Vector3.new(1, 0, 1)).Magnitude
		end
		local score = d
		-- parked in the floor under us: they are the one hitting us, and the slab push reaches them
		local _, fm = Game.fighterBody(f)
		if S.bounds.underDesync(fm) then
			score -= 40
		end
		if cfg.autokillAdaptive then
			score -= Target.threat(f) * 15
			local hp, mx = Game.fighterHealth(f)
			if hp and mx and mx > 0 then
				score -= (1 - hp / mx) * 20
			end
			for _, o in ipairs(enemies) do
				if o ~= f then
					local ro = Game.fighterBody(o)
					if ro and (ro.Position - r.Position).Magnitude < 25 then
						score += 10
					end
				end
			end
			if Combat.enemyDeflecting(f) then
				score += 25
			end
		end
		return score, d
	end
	function Combat.pickAutokillTarget(enemies: { any }, exclude: any): (any, number)
		local me = Game.myRoot()
		if not me then
			return nil, math.huge
		end
		-- a new run counts from where the player stands: a hide parks the body 400+ st away, and every
		-- enemy measured from there is out of range, so the hide would never end in an attack. A running
		-- chain counts from where the body is.
		local B = Combat.body
		local from = if (ak.state == "idle" or ak.state == "done") and S.teleported and B.home then B.home.Position else me.Position
		local best, bestS, bestD = nil, math.huge, math.huge
		for _, f in ipairs(enemies) do
			if f ~= exclude then
				local s, d = Combat.akScore(f, from, enemies)
				if s and s < bestS then
					best, bestS, bestD = f, s, d
				end
			end
		end
		return best, bestD
	end
	-- orbit geometry for the weapon in hand and the enemy's weapon (adaptive mode)
	function Combat.akGeometry(prof: any, target: any): (number, number, number)
		local r, hgt, speedMult = cfg.autokillRadius, cfg.autokillHeight, 1
		if prof.melee then
			r, hgt = 2.2, 0.6
		elseif prof.pellets > 1 then
			r, hgt = math.min(r, 3), math.min(hgt, 1.5)
		end
		local info = prof.item and prof.item.Info
		if cfg.autokillAdaptive and type(info) == "table" then
			local boom = tonumber(info.ExplosionRadius) or tonumber(info.BlastRadius) or tonumber(info.ExplosionSize) or 0
			if prof.projectile and boom > 0 then
				r, hgt = math.max(r, boom + 2), math.max(hgt, 3) -- never inside our own blast
			end
			if info.AimScopePercent then
				r, hgt = math.max(r, 6), math.max(hgt, 4) -- a scoped weapon gains nothing from hugging
			end
			local eq = Game.enemyEquipped(target)
			local einfo = type(eq) == "table" and eq.Info
			if type(einfo) == "table" then
				if einfo.Type ~= "Gun" or (tonumber(einfo.ShootPellets) or 1) > 1 then
					r, hgt = r + 2, hgt + 1 -- blades and shotguns: stay out of their reach
				end
				if einfo.AimScopePercent then
					speedMult = 1.6 -- a sniper tracks a slow orbit
				end
			end
		end
		return math.clamp(r, 1.5, 8), math.clamp(hgt, 1, 6), speedMult
	end
	-- every autokill position goes to Body through this one request table
	Combat.akReq = { hold = 0.5, pin = false, turnCam = false, key = nil, jump = false, velocity = nil, geometry = true, void = false, sky = false, refGround = nil }
	-- rest: a Void-mode rest spot, a hide kind ("void" under the map, "sky" in Sky mode, "slab", "far"),
	-- never inside geometry
	function Combat.akRequest(spot: Vector3, aim: Vector3, key: Vector3?, jump: boolean?, velocity: number?, rest: string?): boolean
		local r = Combat.akReq
		r.pin = not cfg.autokillVisible
		r.turnCam = cfg.autokillVisible
		r.key = key
		r.jump = jump == true
		r.velocity = velocity
		r.sky = rest == "sky"
		r.void = rest == "void" or rest == "slab" or ak.targetVoid == true
		r.far, r.geometry = rest == "far", rest == nil -- an Auto-HvH hide switched these for its own spot
		r.budget = if rest == "slab" then true else nil
		r.refGround = if rest == nil then ak.refGround else nil
		r.hold = if velocity then 0.3 else 0.5
		-- a velocity move travels up to 5 st a frame at the top speed: that is motion, not a hop (Body
		-- still pivots and counts a jump when the body falls 12 st behind). v0.9: an Origin key (the planned
		-- spot) that drifts < 3 st while a target walks is a glide too — every 1.5 st drift used to restart
		-- the settle, so against a moving player the fire window never opened ("autokill does nothing")
		r.jumpDist = if velocity then 12 elseif key ~= nil and rest == nil then 3 else nil
		return Combat.body.request("autokill", spot, aim, r)
	end
	-- the gun's own cycle (s) as it fires now; 1 without a gun
	function Combat.gunCycle(): number
		local gs = S.gameState
		local item = gs and gs.item
		local info = type(item) == "table" and item.Info
		return (type(info) == "table" and tonumber(info.ShootCooldown)) or 1
	end
	-- the orbit's speed in the fire window: the server fires from where it has us, along the rotation we
	-- sent from there, so the body barely moves while a round can leave
	Combat.ORBIT_FIRE_SPEED = 12
	-- a spot nobody expects: 12–24 st from the target at a random bearing, ground level to a few studs up,
	-- only when Safe passes it (no kill volume, no OOB death, inside the height band)
	Combat.breakReq = { hold = 0.3, geometry = false, void = false, refGround = nil }
	function Combat.breakerSpot(target: Vector3): Vector3?
		local Sf = S.safe
		local g = Sf.groundY(target)
		Combat.breakReq.refGround = g
		for _ = 1, 5 do
			local a = math.random() * 2 * math.pi
			local r = 12 + math.random() * 12
			local base = target + Vector3.new(math.cos(a) * r, 0, math.sin(a) * r)
			local gy = Sf.groundY(base)
			if gy then
				local p = Vector3.new(base.X, gy + 3 + math.random() * 3, base.Z)
				if Sf.check(p, Combat.breakReq) then
					return p
				end
			end
		end
		return nil
	end
	-- Auto-HvH (autokill only): the moment the gun goes on cooldown, leave the shooting spot for a void
	-- hide (sky / under the floor / far; a new one every 1/defenseHopHz with voidspam) while anti-aim
	-- spins (h.rot); back one fire lead before the gun is ready, facing the lock, so the next round fires
	-- on the edge. A breaker spot (12–24 st out, on the ground) only when no void spot is safe. Body runs
	-- every spot through Safe.
	-- v6.3 "dying to legits while raging": a hit taken on the shooting spot means someone is tracking us
	-- there. Unless our next round kills, leave for a hide right away and stay out ~0.6 s so their aim has
	-- to find us again (autokill Origin / Snap via Auto-HvH, Void ends its attack early).
	function Combat.hurtHide(now: number, f: any): boolean
		if not (cfg.autokillHvh and S.hurtAt and now - S.hurtAt < 0.6) then
			return false
		end
		if f ~= nil and Combat.killable(f) then
			return false
		end
		-- in a crowd a hit lands almost every frame: a hide per hit kept autokill hiding, never firing and jumping
		-- between spots. One 0.6 s hide per 1.5 s at most, so every window leaves time to fight back
		if now - (Combat.hurtHideStart or -10) >= 1.5 then
			Combat.hurtHideStart = now
		end
		if now - Combat.hurtHideStart >= 0.6 then
			return false
		end
		if now - (Combat.hurtLogAt or 0) > 2 then
			Combat.hurtLogAt = now
			log("INFO", ("[autokill:hurt] took %.0f on the spot — hiding before the next round"):format(S.hurtAmount or 0))
		end
		return true
	end
	function Combat.akHvhSpot(now: number, origin: Vector3, aim: Vector3): (Vector3?, string?)
		local left = Combat.cannotFireFor(S.gameState)
		local back = Combat.fireLead()
		if left <= back and not Combat.hurtHide(now, ak.fighter) then
			if ak.hvh then
				ak.hvh = nil
				ak.faceSince = now -- facing again: the echo clock for the next round starts here
			end
			return nil, nil
		end
		local hv = ak.hvh
		if not hv then
			hv = { since = now, hopAt = 0, spot = nil, kind = nil }
			ak.hvh = hv
			log("DEBUG", ("[autokill:hvh] gun busy %.2f s → hide + spin (body %s)"):format(left, Combat.body.owner or "you"))
		end
		if not hv.spot or (cfg.defenseVoidSpam and now - hv.hopAt >= 1 / math.max(cfg.defenseHopHz, 1)) then
			local c = Combat.pickHide(origin, Game.targets())
			if cfg.rageBreaker and not c then
				local b = Combat.breakerSpot(aim)
				if b then
					c = { pos = b, kind = "break" }
				end
			end
			if c then
				hv.spot, hv.kind, hv.hopAt = c.pos, c.kind, now
			end
		end
		return hv.spot, hv.kind
	end
	-- Origin mode: the autokill version of magic bullet. Plan a spread-immune, server-visible origin
	-- for the locked hitbox and hold it (a small wiggle so we are not a perfectly still point).
	-- Re-plans only when the current spot stops working (sticky); Body refuses unsafe spots.
	Combat.akOriginOpts = { holdSec = 0.5, noclip = true }
	function Combat.akOriginStep(head: BasePart, model: Model?, f: any, now: number)
		local part = S.silentPart
		local aimPart = if typeof(part) == "Instance" and part.Parent then part else head
		local aim = aimPart.Position
		Combat.akOriginOpts.holdSec = 0.5
		Combat.akOriginOpts.noclip = true
		local origin = Combat.origin.plan(aim, model, aimPart, Combat.akOriginOpts)
		ak.originLast = origin
		-- Auto-HvH: gun on cooldown → hide + spin instead of standing still on the shooting spot
		local hide, kind = nil, nil
		if cfg.autokillHvh and Combat.rageOn() then
			hide, kind = Combat.akHvhSpot(now, origin, aim)
		end
		ak.hiding = hide ~= nil
		if hide then
			local r = Combat.akReq
			r.pin, r.turnCam = not cfg.autokillVisible, cfg.autokillVisible
			r.key, r.jump, r.velocity, r.jumpDist = hide, false, nil, nil
			-- a hide is a void spot (never inside geometry); a breaker spot stands on the ground in the band
			r.sky, r.void, r.far, r.geometry = kind == "sky", kind == "void" or kind == "slab", kind == "far", false
			r.budget = kind == "slab"
			r.refGround = if kind == "break" then ak.refGround else nil
			r.hold = if kind == "slab" then 0.25 else 0.5
			Combat.body.request("autokill", hide, aim, r)
			ak.originSettled = false
			-- back on the shooting spot facing the lock: the stream faces it from there while we hide
			S.preFaceFrom = origin + Vector3.new(0, 1.85, 0)
			S.preFace = Combat.cannotFireFor(S.gameState) <= Combat.fireLead() + Combat.echoLead()
			return
		end
		-- never a still shooter: magic's jitter around the planned origin (its wiggle, a hop the instant a
		-- round leaves a slow gun, periodic hops while no round is due, one forced hop when we are hit).
		-- The key stays on the origin so Body settles on the calm point; the trigger waits out each hop.
		if ak.forceHop then
			ak.forceHop = nil
			Combat.magicJit.force = true
		end
		local off = Combat.magicJitterOffset(aim, origin, model)
		if not cfg.magicJitter then
			off = Vector3.new(math.sin(now * 15) * 0.5, -math.abs(math.sin(now * 11 + 1)) * 0.2, math.cos(now * 13) * 0.5)
		end
		Combat.akRequest(origin + off, aim, origin, false, nil, nil)
		-- a hop (the planned origin moved > 1.5 st) costs one settle of held fire, like magic's hops
		ak.originSettled = Combat.body.settledFor("autokill")
		ak.hopSettled = S.magicHopSettled ~= false
	end
	-- Snap mode: strike from a planned origin, shoot, and rest at home while the gun cycles — the
	-- body is only out there for the shot window. A strike ends when the round left and the gun is
	-- busy for longer than the trip back and forth (a sniper after every round, an automatic at the
	-- reload), or after autokillSnapHold without a shot (no line from any spot); the next strike
	-- leaves one settle before the gun is ready.
	function Combat.akSnapStep(head: BasePart, model: Model?, f: any, now: number)
		local settle = Combat.settleSec()
		local left = Combat.cannotFireFor(S.gameState)
		if ak.snapPhase == "rest" then
			if now - (ak.snapPhaseAt or 0) < 0.12 or left > settle + 0.02 then
				ak.originSettled = false
				return
			end
			ak.snapPhase = nil
		end
		if ak.snapPhase == nil then
			ak.snapPhase, ak.snapPhaseAt, ak.snapPulses = "strike", now, S.pulses or 0
		end
		Combat.akOriginStep(head, model, f, now)
		local shot = (S.pulses or 0) > (ak.snapPulses or 0)
		if (shot and left > settle * 2 + 0.1) or now - ak.snapPhaseAt > cfg.autokillSnapHold + settle then
			ak.snapPhase, ak.snapPhaseAt = "rest", now
			ak.snapStrikes = (ak.snapStrikes or 0) + 1
			Combat.body.release("autokill")
		end
	end
	-- Under / High: the body rides a fixed offset from the target every frame. Under sits 6 st under their
	-- root (inside the floor, or the air under a thin one): measured in the range, the server takes those
	-- rounds (36 HIT / 5 NO-REPLY) although our own client ray from there is blocked by the floor's parts, so
	-- no client line is asked for. Their rounds stop on the slab's top face. High hangs over their head, out
	-- of their view. Both keep a step off their column (a straight-up look has no stable basis). A spot Safe
	-- refuses falls back to Origin's plan for that frame.
	Combat.DESYNC_UNDER = 6
	Combat.DESYNC_HIGH = 25
	Combat.DESYNC_EYE = 1.85 -- root → the claimed shot origin (head + 0.35)
	function Combat.desyncSpot(f: any, part: BasePart, model: Model?, mode: string): (Vector3?, string?)
		local root = Game.fighterBody(f)
		if not root then
			return nil, nil
		end
		local me = S.myRootPart
		local home = if Combat.body.home then Combat.body.home.Position elseif me then me.Position else nil
		local side = if home then (home - root.Position) * Vector3.new(1, 0, 1) else Vector3.zero
		side = if side.Magnitude > 0.1 then side.Unit else Vector3.new(0, 0, 1)
		local col = Vector3.new(root.Position.X, 0, root.Position.Z) + side * 1.2
		if mode == "High" then
			local base = ak.refGround or root.Position.Y
			local y = math.min(root.Position.Y + Combat.DESYNC_HIGH, base + cfg.safeMaxHeight - 0.5)
			if y < root.Position.Y + 4 then
				return nil, nil
			end
			local spot = Vector3.new(col.X, y, col.Z)
			if Game.rayVisible(model, part, spot + Vector3.new(0, Combat.DESYNC_EYE, 0)) then
				return spot, "high"
			end
			return nil, nil
		end
		return Vector3.new(col.X, root.Position.Y - Combat.DESYNC_UNDER, col.Z), "under"
	end
	function Combat.akDesyncStep(head: BasePart, model: Model?, f: any, now: number)
		local part = S.silentPart
		local aimPart = if typeof(part) == "Instance" and part.Parent then part else head
		local aim = aimPart.Position
		local spot, kind = Combat.desyncSpot(f, aimPart, model, ak.mode)
		ak.hiding = false
		if spot then
			local r = Combat.akReq
			r.pin, r.turnCam = not cfg.autokillVisible, cfg.autokillVisible
			-- it follows a walking target: a glide under 3 st per frame is motion, not a hop (no new settle)
			r.key, r.jump, r.velocity, r.jumpDist = nil, false, nil, 3
			r.sky, r.far = false, false
			r.void = kind == "under"
			r.budget = kind == "under"
			r.geometry = kind == "under"
			r.refGround = ak.refGround
			r.hold = 0.4
			if kind == "under" then
				-- physics would push a body out of the slab between frames
				Combat.noclip.rage(0.6)
			end
			if Combat.body.request("autokill", spot, aim, r) then
				if ak.desyncKind ~= kind and now - (ak.desyncLogAt or 0) > 1 then
					ak.desyncLogAt = now
					log("INFO", ("[autokill:%s] riding %s %s"):format(kind, if kind == "under" then "inside the floor under" else "over the head of", Game.fighterName(f)))
				end
				ak.desyncKind = kind
				ak.originSettled = Combat.body.settledFor("autokill")
				return
			end
		end
		if ak.desyncKind ~= nil and now - (ak.desyncLogAt or 0) > 1 then
			ak.desyncLogAt = now
			log("DEBUG", ("[autokill:%s] no spot here → Origin's plan"):format(string.lower(ak.mode)))
		end
		ak.desyncKind = nil
		Combat.akOriginStep(head, model, f, now)
	end
	-- weapon profile → orbit geometry / speed / backstab flag, shared by start and retarget
	function Combat.akSetup(target: any): any
		local prof = Game.weaponProfile()
		ak.profile = prof
		ak.behind = prof.melee and (cfg.autoBackstabAnyMelee or Combat.critMelee(prof.item))
		local speedMult
		ak.radius, ak.height, speedMult = Combat.akGeometry(prof, target)
		ak.speed = math.min(cfg.autokillOrbitSpeed * speedMult, cfg.autokillMaxSpeed / math.max(ak.radius, 1))
		return prof
	end
	function Combat.startAutokill(enemies: { any }?): boolean
		enemies = enemies or Game.targets()
		if ak.state ~= "idle" and ak.state ~= "done" then
			return false
		end
		if S.calibrating then
			return false
		end
		if not Combat.rageOn() then
			log("INFO", "[autokill:skip:rage-off] positioning is None — pick a rage position first")
			notify("autokill needs a rage position (Ragebot → Positioning)", 3, "warn")
			return false
		end
		local me = Game.myRoot()
		if not me then
			log("WARN", "autokill: no character")
			notify("autokill: no character", 3, "warn")
			return false
		end
		local myHp = Game.myHealth()
		local gs0 = Game.state()
		if (myHp ~= nil and myHp <= 0) or gs0.alive == false or gs0.item == nil then
			log("WARN", "autokill: not alive / no weapon out — not starting")
			notify("autokill: you are dead or have no weapon out", 2, "warn")
			return false
		end
		if gs0.locked then
			log("INFO", "autokill: items locked (round start) — not starting")
			notify("autokill: the round has not started yet", 2, "warn")
			return false
		end
		local best, bestD = Combat.pickAutokillTarget(enemies, nil)
		if not best then
			local anyone = Target.nearest(enemies)
			log("WARN", if anyone then "autokill: every enemy is dead or immune" else "autokill: no enemies in list")
			notify(if anyone then "autokill: everyone is spawn-protected right now" else "autokill: no enemies", 3, "warn")
			return false
		end
		-- magic hands over inside Body (autokill outranks it); the spot the player stood on is Body's
		if magic.active then
			Combat.magicRelease("autokill took over")
		end
		ak.fighter = best
		ak.char = LP.Character -- the run belongs to this character: a respawn ends it, never drags the new one
		local prof = Combat.akSetup(best)
		-- Void mode rests in this map's measured void (the calibrated sky only in Sky mode) or not at all:
		-- never an unmeasured "somewhere down there"
		local sky = cfg.voidHeights[tostring(game.PlaceId)]
		ak.restY, ak.restKind = Combat.voidY(), "void"
		if ak.restY == nil and cfg.defenseMode == "Sky" and Combat.skyOk(sky) then
			ak.restY, ak.restKind = sky, "sky"
		end
		ak.voidBlockedLogged = nil
		ak.burstFrom, ak.burstPulses, ak.nextAngle = nil, nil, nil
		ak.originAt, ak.originLast, ak.originSettled, ak.hopSettled = nil, nil, false, nil
		ak.snapPhase, ak.snapPhaseAt, ak.snapStrikes, ak.refusedSince = nil, nil, 0, nil
		ak.desyncKind, ak.buriedTop = nil, nil
		if cfg.autokillMode == "Origin" or cfg.autokillMode == "Snap" or cfg.autokillMode == "Under" or cfg.autokillMode == "High" then
			ak.mode = cfg.autokillMode
		elseif cfg.autokillMode == "Void" then
			-- the rest is the far spot (10k+ st out), which every map has: no measured void needed
			ak.mode = "Void"
		else
			ak.mode = "Orbit"
		end
		local now = os.clock()
		ak.startedAt = now
		-- "Until they die": no clock; every other stop (death, low health, no progress, the menu) still applies
		local runFor = if cfg.autokillUntilDead or (tonumber(cfg.autokillDuration) or 0) >= 61 then 1e6 else cfg.autokillDuration
		ak.until_ = now + runFor
		ak.maxUntil = now + runFor * 2 -- progress may extend the run up to here
		ak.phaseUntil = now + cfg.voidBurst
		ak.angle = math.random() * math.pi * 2
		ak.lastTick = now
		ak.hits = 0
		ak.hitBase = S.shotStats.hitTarget
		ak.statBase = table.clone(S.shotStats)
		ak.targetHp0 = Game.fighterHealth(best)
		ak.lastHp = ak.targetHp0
		ak.lastProgressAt = now
		ak.myHpLast = myHp
		ak.myHpAt = now
		ak.immuneSince = nil
		ak.emptySince = nil
		ak.chained = 0
		ak.firingFrames, ak.frames = 0, 0
		ak.firing = false
		ak.state = "snap"
		local name = Game.fighterName(best)
		log("INFO", ("autokill: snap → %s (%.0fm) weapon %s (%s) r %.1f h %.1f mode %s%s"):format(name, bestD, prof.name, if prof.melee then "melee" elseif prof.pellets > 1 then "shotgun" else "gun", ak.radius, ak.height, ak.mode, if cfg.autokillAdaptive then " adaptive" else ""))
		notify("AUTOKILL → " .. name, 2, "rage")
		Combat.updateAutokill(enemies)
		return true
	end
	-- the target died / went immune with time left: move on to the next one without returning
	function Combat.retargetAutokill(enemies: { any }, why: string): boolean
		if not cfg.autokillChain then
			return false
		end
		local now = os.clock()
		if now > (ak.maxUntil or ak.until_) then
			return false
		end
		local nextF, d = Combat.pickAutokillTarget(enemies, ak.fighter)
		if not nextF then
			return false
		end
		if Game.weaponProfile().item == nil then
			return false
		end
		Combat.akSetup(nextF)
		ak.fighter = nextF
		ak.targetHp0 = Game.fighterHealth(nextF)
		ak.lastHp = ak.targetHp0
		ak.lastProgressAt = now
		ak.originAt, ak.originLast, ak.originSettled = nil, nil, false
		ak.snapPhase, ak.snapPhaseAt, ak.refusedSince, ak.nextAngle = nil, nil, nil, nil
		ak.immuneSince = nil
		ak.until_ = math.min(math.max(ak.until_, now + math.min(cfg.autokillDuration, 2.5)), ak.maxUntil or ak.until_)
		ak.chained = (ak.chained or 0) + 1
		ak.state = "snap"
		local name = Game.fighterName(nextF)
		log("INFO", ("autokill: %s → next target %s (%.0fm)"):format(why, name, d))
		notify("AUTOKILL → " .. name, 1.5, "rage")
		return true
	end

	function Combat.stopAutokill(reason: string)
		if ak.state == "idle" or ak.state == "done" then
			return
		end
		ak.state = "return"
		ak.firing = false
		ak.hiding, ak.hvh, ak.faceSince = false, nil, nil
		ak.buriedTop = nil
		Combat.releaseFire()
		-- Body brings the body home; "no return" keeps the end spot only when the player can stand
		-- there (not inside a wall, under the map or in a kill volume)
		Combat.body.release("autokill", not cfg.autokillReturn)
		ak.state = "done"
		ak.doneAt = os.clock()
		ak.reason = reason
		S.lastAutokillEnd = os.clock()
		local b = ak.statBase or S.shotStats
		local ss = S.shotStats
		local hpNow = ak.fighter and Game.fighterHealth(ak.fighter)
		log("INFO", ("autokill: done (%s) — %.1fs · trigger down %d/%d frames (%s) · redirected %d · hit %d · blocked %d · air %d · confirmed %d · dropped %d · target hp %s → %s"):format(
			reason, os.clock() - (ak.startedAt or os.clock()), ak.firingFrames or 0, ak.frames or 0, Input.fireMethodUsed,
			ss.redirected - (b.redirected or 0), ss.hitTarget - (b.hitTarget or 0), ss.hitOther - (b.hitOther or 0), ss.miss - (b.miss or 0), ss.confirmed - (b.confirmed or 0), ss.dropped - (b.dropped or 0),
			tostring(ak.targetHp0 and math.floor(ak.targetHp0)), tostring(hpNow and math.floor(hpNow))
		))
		notify(("autokill done · %s · %d hits"):format(reason, ak.hits or 0), 2.5, "rage")
		ak.fighter = nil
	end

	function Combat.updateAutokill(enemies: { any })
		local now = os.clock()
		if ak.state == "done" then
			if now - (ak.doneAt or 0) > 1.2 then
				ak.state = "idle"
			end
			return
		end
		if ak.state == "idle" then
			-- aggressive: engage automatically when someone is in range (needs the master toggle)
			if cfg.autokill and cfg.autokillAuto and Combat.rageOn() and not S.menuOpen and not S.calibrating and now - (S.lastAutokillEnd or 0) > cfg.autokillCooldown and now >= (S.autokillCooldownUntil or 0) and now - (ak.autoTryAt or 0) > 0.15 then
				ak.autoTryAt = now
				-- quiet pre-checks: dead / no weapon out is normal between rounds, not a warning per frame
				local gs0 = S.gameState
				local myHp = Game.myHealth()
				-- never during the round-start lock: the body would wait next to them with a gun that cannot fire
				if gs0 and gs0.alive ~= false and gs0.item ~= nil and not gs0.locked and not (myHp ~= nil and myHp <= 0) then
					local pick, d = Combat.pickAutokillTarget(enemies, nil)
					if pick and d <= cfg.autokillAutoRange then
						Combat.startAutokill(enemies)
					end
				end
			end
			return
		end
		if not Combat.rageOn() then
			Combat.stopAutokill("rage off")
			return
		end
		local f = ak.fighter
		local head = f and Game.fighterHead(f)
		local hp = f and Game.fighterHealth(f)
		if not head or (hp ~= nil and hp <= 0) or (f and Target.isDead(f)) then
			local why = if hp ~= nil and hp <= 0 then "target dead" else "target lost"
			if Combat.retargetAutokill(enemies, why) then
				f = ak.fighter
				head = Game.fighterHead(f)
				hp = Game.fighterHealth(f)
			else
				Combat.stopAutokill(why)
				return
			end
		end
		-- progress: a dropping target HP keeps the run alive (up to 2× the duration); a target that
		-- takes nothing for 2.5 s is behind something we cannot see from this orbit → stop
		if hp ~= nil then
			if ak.lastHp == nil or hp < ak.lastHp - 0.5 then
				ak.lastProgressAt = now
				if cfg.autokillAdaptive and now > ak.until_ - 0.6 then
					ak.until_ = math.min(ak.until_ + 1.2, ak.maxUntil or ak.until_)
				end
			end
			ak.lastHp = hp
		end
		-- the gun busy (cooldown, reload) or Auto-HvH hiding: no round could land, so that time is not "no
		-- progress" (the duel log stopped a run 2.5 s in, before its first ready frame). The run's own
		-- duration still ends it.
		if ak.hiding or Combat.cannotFireFor(S.gameState) > 0 then
			ak.lastProgressAt = now
		end
		if cfg.autokillAdaptive and ak.state == "orbit" and now - (ak.lastProgressAt or now) > 2.5 and now - (ak.snapAt or now) > 1.2 then
			if not Combat.retargetAutokill(enemies, "no progress") then
				Combat.stopAutokill("no progress")
				return
			end
		end
		-- warped away for a second (Resolver.away): nothing reaches them — the next target, or stop, instead of a
		-- whole "no progress" run (the duel log spent 10.6 s on one)
		local _, akModel = Game.fighterBody(f)
		if akModel and Resolver.away(akModel) then
			ak.awaySince = ak.awaySince or now
			if now - ak.awaySince > 1 then
				ak.awaySince = nil
				Combat.akSkip[f] = now + 3
				if not Combat.retargetAutokill(enemies, "target warped away") then
					Combat.stopAutokill("target warped away")
					return
				end
				f = ak.fighter
				head = f and Game.fighterHead(f)
				if not head then
					return
				end
			end
		else
			ak.awaySince = nil
		end
		if now > ak.until_ then
			Combat.stopAutokill(if (ak.chained or 0) > 0 then ("timeout · %d chained"):format(ak.chained) else "timeout")
			return
		end
		if S.menuOpen then
			Combat.stopAutokill("menu")
			return
		end
		-- our character changed (death → respawn) or the fighter object is gone: the run is over.
		-- The old code only noticed a death while myHealth() still returned numbers, so a respawned
		-- character was dragged into the orbit spot and then "returned" to where the corpse fell.
		if ak.char ~= nil and LP.Character ~= ak.char then
			Combat.stopAutokill("respawned")
			return
		end
		-- spawn protection: nothing lands; wait a moment for it to drop, then move on
		local immune = cfg.immuneCheck and Game.fighterImmune(f)
		if immune then
			ak.immuneSince = ak.immuneSince or now
			if now - ak.immuneSince > 1.2 then
				if not Combat.retargetAutokill(enemies, "target immune") then
					Combat.stopAutokill("target immune")
					return
				end
				immune = false
			end
		else
			ak.immuneSince = nil
		end
		local myHp, myMax = Game.myHealth()
		if myHp == nil and ak.myHpLast ~= nil then
			Combat.stopAutokill("died") -- the fighter object went away mid-run
			return
		end
		if myHp and myMax and myMax > 0 then
			if myHp <= 0 then
				Combat.stopAutokill("died")
				return
			end
			if myHp / myMax < cfg.autokillAbortHp / 100 then
				Combat.stopAutokill(("low hp %d%%"):format(math.floor(myHp / myMax * 100)))
				S.autokillCooldownUntil = now + 3 -- a real cooldown, not a faked "ended in the future" stamp
				return
			end
			-- taking real damage: someone has our spot — leave it now instead of on the next hop tick
			if cfg.autokillAdaptive and ak.myHpLast and myHp < ak.myHpLast - 12 then
				ak.forceHop = true
			end
			if now - (ak.myHpAt or 0) > 0.5 then
				ak.myHpLast, ak.myHpAt = myHp, now
			end
		end
		-- dry weapon: the game reloads by itself; a mag that stays empty means no reserve → stop
		local gsNow = S.gameState
		if gsNow and gsNow.ammo ~= nil and gsNow.ammo <= 0 then
			ak.emptySince = ak.emptySince or now
			if now - ak.emptySince > 3 then
				Combat.stopAutokill("no ammo")
				return
			end
		else
			ak.emptySince = nil
		end
		local dt = math.clamp(now - (ak.lastTick or now), 0, 0.1)
		ak.lastTick = now
		local _, model = Game.fighterBody(f)
		ak.hits = math.max(0, S.shotStats.hitTarget - (ak.hitBase or 0))
		-- heights are measured from the ground under the target, never from the target itself: a
		-- lifted / teleporting enemy must not pull us up with them
		ak.refGround = S.safe.groundY(head.Position)
		-- buried in the floor (the under desync): the orbit rides the slab's top face over them
		ak.buriedTop = S.bounds.buriedTop(model)
		if ak.buriedTop then
			ak.refGround = ak.buriedTop
		end
		ak.targetVoid = S.bounds.isVoidFighter(f)

		-- crit melee: the only spot that matters is straight behind their look (backstab = one-shot);
		-- it follows their turning every frame instead of orbiting
		local behind = cfg.autoBackstab and ak.behind == true and Combat.behindAngle(f) or nil
		-- Origin mode: autokill-driven magic bullet — plan a spread-immune, server-visible origin for
		-- the locked hitbox and hold it. Snap mode strikes from the same origin and rests between shots.
		if ak.mode == "Origin" or ak.mode == "Snap" or ak.mode == "Under" or ak.mode == "High" then
			if ak.mode == "Snap" then
				Combat.akSnapStep(head, model, f, now)
			elseif ak.mode == "Under" or ak.mode == "High" then
				Combat.akDesyncStep(head, model, f, now)
			else
				Combat.akOriginStep(head, model, f, now)
			end
			if ak.state == "snap" then
				ak.snapAt = now
				ak.state = "orbit"
			end
		elseif ak.state == "snap" then
			if behind then
				ak.angle = behind
			elseif ak.nextAngle then
				ak.angle = ak.nextAngle -- the rest already streamed the lock-facing rotation from this spot
			elseif cfg.autokillAdaptive then
				ak.angle = Combat.safestAngle(head, model, enemies)
			end
			ak.nextAngle = nil
			ak.holdCF = Combat.orbitPoint(head, model, 0)
			ak.holdOffset = ak.holdCF.Position - head.Position
			Combat.akRequest(ak.holdCF.Position, head.Position, nil, true)
			ak.snapAt = now
			ak.hopAt = now
			ak.steerAt = now
			ak.state = "orbit"
			ak.burstFrom, ak.burstPulses = nil, S.pulses or 0
		elseif ak.state == "orbit" then
			local move = Combat.akMove()
			if move == "Hop" or move == "Hold" then
				-- a fresh spot around the head every hop, held still in between so the server sees a
				-- stable shooter. Every hop costs one settle of silence: a slow gun hops only while its
				-- cooldown outlasts the settle (the settle ends inside it, the round leaves on time), a
				-- fast gun lives in the fire window and hops at most every 0.6 s. Hold keeps its spot and
				-- only moves when we are being hit.
				local settle = Combat.settleSec()
				local hopEvery = math.max(cfg.autokillHopMs / 1000, settle + 0.3)
				local fast = Combat.gunCycle() < settle * 0.8
				local sinceHop = now - (ak.hopAt or 0)
				local canHop = Combat.cannotFireFor(S.gameState) > settle + 0.05 or (fast and sinceHop >= math.max(hopEvery, 0.6))
				local hop = (move == "Hop" and sinceHop >= hopEvery and canHop) or (ak.forceHop and sinceHop > settle)
				if hop then
					ak.forceHop = nil
					ak.hopAt = now
					if behind then
						ak.angle = behind
					elseif cfg.autokillAdaptive then
						ak.angle = Combat.safestAngle(head, model, enemies)
					else
						local step = math.pi * (0.45 + math.random() * 0.9)
						ak.angle = (ak.angle or 0) + (if math.random() < 0.5 then step else -step)
					end
					ak.holdCF = Combat.orbitPoint(head, model, 0)
					ak.holdOffset = ak.holdCF.Position - head.Position
				end
				-- the same spot relative to the head in between (ordinary movement when they walk)
				local p = head.Position + (ak.holdOffset or Vector3.new(0, ak.height or 2.5, 0))
				Combat.akRequest(p, head.Position, nil, hop)
			else
				-- smooth orbit as *velocity*, not a teleport per frame: the server sees plausible motion
				-- (capped by the speed slider); Body pivots only when we fell > 12 st behind
				if ak.forceHop then
					-- hit while orbiting: reverse and jump a quarter turn so their aim has to re-acquire
					ak.forceHop = nil
					ak.dir = -(ak.dir or 1)
					ak.angle = (ak.angle or 0) + math.pi * 0.5 * ak.dir
				elseif behind then
					ak.angle = behind
				elseif cfg.autokillAdaptive and now - (ak.steerAt or 0) > 1 then
					-- steer the orbit toward the safest side of the target (fewest other guns see it)
					ak.steerAt = now
					local want = Combat.safestAngle(head, model, enemies)
					local diff = ((want - (ak.angle or 0) + math.pi) % (2 * math.pi)) - math.pi
					ak.dir = if diff >= 0 then 1 else -1
				end
				-- full speed only while no round can leave within one settle; in the fire window the orbit
				-- crawls: the server fires from where it has us, along the rotation we sent from there
				local window = Combat.cannotFireFor(S.gameState) <= Combat.settleSec() + 0.05
				local cap = if window then math.min(cfg.autokillMaxSpeed, Combat.ORBIT_FIRE_SPEED) else math.max(cfg.autokillMaxSpeed, 20)
				local desired = Combat.orbitPoint(head, model, if behind then 0 else dt * (ak.dir or 1), cap)
				Combat.akRequest(desired.Position, head.Position, nil, false, cap)
			end
			-- the attack time counts from the first round that left after the snap (the settle and the echo
			-- come first); a snap that fires nothing rests after the attack time plus 1.5 s
			if ak.mode == "Void" then
				if ak.burstFrom == nil and (S.pulses or 0) > (ak.burstPulses or math.huge) then
					ak.burstFrom = now
				end
				local over = if ak.burstFrom then now - ak.burstFrom >= cfg.voidBurst else now - (ak.snapAt or now) >= cfg.voidBurst + 1.5
				-- hit during the attack: rest now (someone else is tracking the attack spot)
				if not over and now - (ak.snapAt or now) > 0.15 and Combat.hurtHide(now, f) then
					over = true
				end
				if over then
					-- the rest is out of everyone's reach (the far spot, 10k+ st out), never a void a gun
					-- or a magic bullet can still find
					ak.state = "void"
					ak.phaseUntil = now + cfg.voidRest
					ak.voidEnteredAt = now
					ak.restSpot = nil
				end
			end
		elseif ak.state == "void" then
			local jump = now - (ak.voidEnteredAt or now) < 0.05
			if not ak.restSpot then
				local c = Combat.pickHide(head.Position, enemies)
				ak.restSpot = c and c.pos or nil
			end
			if ak.restSpot then
				Combat.akRequest(ak.restSpot, head.Position, nil, jump, nil, "far")
			end
			-- the last echo trip of the rest: the stream already faces the lock from the spot the next attack
			-- lands on, so its first round only waits the settle
			if ak.phaseUntil - now <= Combat.echoLead() then
				if ak.nextAngle == nil then
					ak.nextAngle = if behind then behind elseif cfg.autokillAdaptive then Combat.safestAngle(head, model, enemies) else (ak.angle or 0)
				end
				local keep = ak.angle
				ak.angle = ak.nextAngle
				local cf = Combat.orbitPoint(head, model, 0)
				ak.angle = keep
				S.preFaceFrom = cf.Position + Vector3.new(0, 1.85, 0)
				S.preFace = true
			end
			-- the rest ends at the rest time, or the moment the gun is ready and one round finishes them
			local left = Combat.cannotFireFor(S.gameState)
			local finish = left <= Combat.fireLead() and now - (ak.voidEnteredAt or now) > Combat.settleSec() and Combat.killable(f)
			if now > ak.phaseUntil or finish then
				ak.state = "snap"
			end
		end
		-- Body refused every spot near this target for a second (kill zones, band, map edge): there is
		-- nothing safe to shoot it from — the next target, or stop
		if ak.state == "orbit" and ak.snapPhase ~= "rest" then
			if Combat.body.holds("autokill") then
				ak.refusedSince = nil
			else
				ak.refusedSince = ak.refusedSince or now
				if now - ak.refusedSince > 1 then
					ak.refusedSince = nil
					-- this one stays skipped for 5 s (auto-start and the chain both read akSkip via akScore)
					if ak.fighter ~= nil then
						Combat.akSkip[ak.fighter] = now + 5
					end
					if not Combat.retargetAutokill(enemies, "no safe spot") then
						Combat.stopAutokill("no safe spot near the target")
						return
					end
				end
			end
		end
		-- visible: turn the game's camera at the head (the view follows the body). Invisible: leave the
		-- rotation to the player — the camera/mouse/raycast hooks aim every shot from the real head.
		local me = Game.myRoot()
		if me and cfg.autokillVisible and Combat.body.holds("autokill") then
			Game.setCamRotation(Combat.lookAtSafe(me.Position, head.Position))
		end
		-- fire once Body holds our spot and it has sat for one settle, and only while the server can
		-- see the part from here — an honest gate that stops emptying the mag into cover
		local settledOk = Combat.body.settledFor("autokill")
		local losOk = true
		if ak.mode == "Origin" and cfg.boundsGuard then
			local part = S.silentPart
			-- from where the round really leaves (the head), not the root 1.75 st lower: the root was behind a
			-- ledge the head saw over, and the run held with "no line" while it had a clear shot
			local from = Game.shotOriginPos()
			if typeof(part) == "Instance" and part.Parent and from then
				-- a buried target is only reachable through the lock's push into the slab
				losOk = (S.wallPushUnder and S.wallPushOrigin ~= nil and S.wallPushModel == model) or S.bounds.serverLos(from, model, part)
			end
		end
		-- the stream faces the head for the whole orbit (h.faceTarget): the first round waits for the echo
		local synced = ak.state == "orbit" and not ak.hiding and Combat.syncReady(ak.fighter, math.max(ak.snapAt or 0, ak.faceSince or 0))
		local hopOk = ak.mode ~= "Origin" or ak.hopSettled ~= false
		-- v0.9: which gate holds the trigger (the combat bar shows it, the done log counts it). The echo and the
		-- hop settle are preferences, never a wall: against moving players they kept re-arming and a whole run
		-- fired nothing ("autokill has the body and nothing shoots"). Once the body sits on its spot, the server
		-- can see the part and the target can be hurt, they may hold the trigger at most one settle + 150 ms.
		local why: string? = nil
		if ak.state ~= "orbit" then
			why = if ak.state == "void" then "resting" else "moving in"
		elseif ak.hiding then
			why = "hiding"
		elseif not settledOk then
			why = "settling"
		elseif not losOk then
			why = "no line"
		elseif immune then
			why = "immune"
		elseif not hopOk then
			why = "hop"
		elseif not synced then
			why = "syncing"
		end
		if why == "syncing" or why == "hop" then
			ak.starveSince = ak.starveSince or now
			if now - ak.starveSince >= math.clamp(Combat.settleSec() + 0.15, 0.25, 0.6) then
				why = nil
				ak.forcedFrames = (ak.forcedFrames or 0) + 1
			end
		elseif why == nil then
			ak.starveSince = nil
		end
		ak.waitWhy = why
		ak.firing = why == nil
		-- the step in plain words for the combat bar and the voidspam line
		ak.step = if why == nil then "firing" elseif why == "hop" then "settling" elseif why == "syncing" then "aiming" elseif why == "immune" then "target immune" else why
		ak.frames = (ak.frames or 0) + 1
		if ak.firing then
			ak.firingFrames = (ak.firingFrames or 0) + 1
		else
			ak.whyFrames = ak.whyFrames or {}
			ak.whyFrames[why :: string] = (ak.whyFrames[why :: string] or 0) + 1
		end
	end

	-- Void auto-calibration: once per map per session, at the first quiet moment of a round
	-- (alive, weapon out, nobody within 80 studs, nothing else teleporting us)
	S.voidCalTried = S.voidCalTried or {}
	Combat.VOID_CALIBRATION_RETIRED = true -- v0.9: every hide is the far spot; nothing reads the measured void
	function Combat.updateAutoCalibrate(enemies: { any }, gs: any)
		if Combat.VOID_CALIBRATION_RETIRED then
			return
		end
		-- any duel map without a measured void, for whatever uses it — the hide, voidspam, autokill. Never
		-- behind the lobby gate (the loop skips this step there too) or with the Ragebot off: the probe is
		-- a teleport under the map (into the sky in Sky mode) at the first quiet moment
		if not (cfg.voidAutoCalibrate and Combat.rageOn() and (cfg.defenseHide or cfg.voidSpam or cfg.autokill)) or S.featuresPaused then
			return
		end
		local place = tostring(game.PlaceId)
		-- the void first whenever a map has none that fits; then, for Sky mode only, the sky (a stored one
		-- too close to the map is measured again). Once per session per map and kind.
		local voidKey = Combat.voidKey()
		local needVoid = voidKey ~= nil and Combat.voidY() == nil and not S.voidCalTried[voidKey] and not cfg.voidFatal[voidKey]
		local needSky = cfg.defenseMode == "Sky" and not Combat.skyOk(cfg.voidHeights[place]) and not S.voidCalTried[place .. ":sky"]
		if not (needVoid or needSky) then
			return
		end
		local sky = not needVoid
		local key = if sky then place .. ":sky" else voidKey :: string
		-- a hide may hold the body (voidspam parks for the whole duel): the probe takes it back first
		if S.calibrating or S.menuOpen or magic.active or ak.state ~= "idle" or (S.teleported and Combat.body.owner ~= "defense") then
			return
		end
		if not (gs and gs.alive and gs.weapon ~= "—") then
			return
		end
		-- the scan step already found the nearest enemy this frame; "near" counts from where the player
		-- stands, not from a hide spot
		local nearPos = S.nearestEnemyPos
		local me = Game.myRoot()
		local at = if Combat.body.home then Combat.body.home.Position elseif me then me.Position else nil
		if nearPos and at and (nearPos - at).Magnitude < 80 then
			return
		end
		S.voidCalTried[key] = true
		notify(if sky then "void: auto-calibrating the sky for this map…" else "void: measuring the void under this map…", 3, "info")
		task.spawn(function()
			local ok, err = pcall(Combat.calibrateVoid, true, if sky then "sky" else "void")
			if not ok then
				S.calibrating = false
				S.hookErr("void auto-calibrate", err)
			end
		end)
	end

	function Combat.autokillStatus(): string?
		local st = ak.state
		if st == "idle" then
			return nil
		end
		if st == "snap" then
			return "AUTOKILL · snapping"
		elseif st == "orbit" then
			local how = if ak.mode == "Snap" then (if ak.snapPhase == "rest" then "snap · resting" else "snap · strike") elseif ak.mode == "Origin" then "origin" elseif ak.mode == "Under" or ak.mode == "High" then (if ak.desyncKind then string.lower(ak.mode) else string.lower(ak.mode) .. " · origin") else string.lower(Combat.akMove())
			return ("AUTOKILL · %s %.1fs · %d hits%s%s"):format(how, os.clock() - (ak.startedAt or os.clock()), ak.hits or 0, if ak.immuneSince then " · target immune" else "", if (ak.chained or 0) > 0 then (" · #%d"):format(ak.chained + 1) else "")
		elseif st == "void" then
			return ("AUTOKILL · void %.1fs · %d hits"):format((ak.phaseUntil or os.clock()) - os.clock(), ak.hits or 0)
		elseif st == "done" then
			return ("AUTOKILL · done (%s) · %d hits"):format(ak.reason or "?", ak.hits or 0)
		end
		return nil
	end

	-- Void calibration: stand at the spot for 1 s and watch HP / alive / position for a server yank.
	-- kind "void" (default): the void under the map (Combat.voidTargetY) → cfg.voidDepths; "sky": the
	-- calibrated sky for Sky mode → cfg.voidHeights. auto: the once-per-map measurement
	-- (Combat.updateAutoCalibrate); a manual run overwrites the stored value the same way
	function Combat.calibrateVoid(auto: boolean?, kind: string?): number?
		-- retired: the probe teleported ~100 studs under the map, which hides nothing. Every hide is the far
		-- spot now (10,000+ studs out). A bind or Debug button left from an old config lands here and stops.
		if Combat.VOID_CALIBRATION_RETIRED then
			if not auto then
				notify("Void measuring is gone: every hide is 10,000+ studs out now", 3, "info")
			end
			return nil
		end
		local char = LP.Character
		local me = Game.myRoot()
		if S.featuresPaused and not S.gateOverride then
			-- measuring is for duel maps; the lobby gate holds every teleport
			notify("void: calibrate during a duel — no teleports in the lobby", 4, "warn")
			log("INFO", "void: calibrate refused (lobby gate)")
			return nil
		end
		if cfg.rageEnabled == false then
			notify("void: the Ragebot is off — turn Enable on to calibrate", 4, "warn")
			log("INFO", "void: calibrate refused (Ragebot off)")
			return nil
		end
		if not (char and me and char.PrimaryPart) then
			notify("void: no character", 3, "warn")
			if auto then
				log("INFO", "void: auto failed (no character)")
			end
			return nil
		end
		if S.calibrating then
			return nil
		end
		-- S.calibrating gates auto shoot, autokill and backstab: it is cleared on EVERY path (an
		-- error inside the probe used to leave it stuck for the session — nothing fired any more)
		S.calibrating = true
		local ok, safe = pcall(if kind == "sky" then Combat._calibrateSkyBody else Combat._calibrateVoidBody, char, auto)
		S.calibrating = false
		if not ok then
			S.hookErr("void calibrate", safe)
			notify("void: calibration failed — see F9", 4, "warn")
			if auto then
				log("INFO", "void: auto failed (error)")
			end
			return nil
		end
		return safe
	end
	-- hold the body at `target` for 1 s: false + why on a server yank, damage or death. The caller
	-- takes the body back.
	function Combat.probeHold(target: Vector3, hp0: number?): (boolean, string?)
		local t0 = os.clock()
		pivotTo(CFrame.new(target))
		Combat.markTeleport()
		local guard = 0
		while os.clock() - t0 < 1 and guard < 240 do
			guard += 1
			task.wait()
			local cur = Game.myRoot()
			if not cur then
				return false, "no character"
			end
			if (cur.Position - target).Magnitude > 60 then
				return false, "moved back by the server"
			end
			pivotTo(CFrame.new(target))
			local lf = Game.localFighter()
			if lf and type(lf.IsAlive) == "function" then
				local okA, a = pcall(lf.IsAlive, lf)
				if okA and a == false then
					return false, "died"
				end
			end
			local hp = Game.myHealth()
			if hp and hp0 and hp < hp0 - 0.5 then
				return false, ("took %.0f"):format(hp0 - hp)
			end
		end
		return true, nil
	end
	Combat.voidProbeReq = { hold = 0.6, void = true, geometry = false }
	function Combat._calibrateVoidBody(char: Model, auto: boolean?): number?
		Combat.stopAutokill("calibration")
		Combat.body.goHome("calibration")
		local returnCF = char:GetPivot()
		local base = returnCF.Position
		local hp0 = Game.myHealth()
		local box = S.safe.mapBox()
		if not box then
			log("INFO", if auto then "void: auto failed (no map box)" else "void: no map box here")
			return nil
		end
		local deep = Combat.voidTargetY(base)
		log("INFO", ("void: measuring under the map (bottom Y %.0f, kill height %.0f, gun ray %.0f)…"):format(box.min.Y, workspace.FallenPartsDestroyHeight, Combat.gunRay()))
		-- under where we stand (the floor over it covers the spot), else under the map's middle; the deep
		-- spot first, then one just under the map
		local mid = (box.min + box.max) * 0.5
		local tries = {}
		for _, y in ipairs({ deep or false, box.min.Y - Combat.VOID_BELOW * 2 }) do
			if y then
				table.insert(tries, Vector3.new(base.X, y, base.Z))
				table.insert(tries, Vector3.new(mid.X, y, mid.Z))
			end
		end
		local safe: number? = nil
		local key = Combat.voidKey()
		for _, target in ipairs(tries) do
			local okS, why = S.safe.check(target, Combat.voidProbeReq)
			if okS then
				-- v6.5 kill bricks are usually CanCollide off + Touched: invisible to the geometry test, lethal on
				-- contact (a probe died at Y 5482). Any part at the spot refuses it
				local okP, parts = pcall(function()
					return workspace:GetPartBoundsInBox(CFrame.new(target), Vector3.new(10, 12, 10))
				end)
				if okP and type(parts) == "table" then
					for _, p in ipairs(parts) do
						if not p:IsDescendantOf(char) then
							okS, why = false, "a part there (" .. p.Name .. ")"
							break
						end
					end
				end
			end
			if not okS then
				log("INFO", ("void: Y %.0f refused (%s)"):format(target.Y, tostring(why)))
				continue
			end
			local ok, whyP = Combat.probeHold(target, hp0)
			pivotTo(returnCF)
			Combat.markTeleport()
			if ok then
				local y = target.Y
				safe = y
				-- the step from the map's bottom, signed like the sky probe's "+N" (the void is down)
				log("INFO", ("void: %s%+d safe (Y %.0f, under the map)"):format(if auto then "auto " else "", math.floor(y - box.min.Y + 0.5), y))
				break
			end
			local hpNow = Game.myHealth()
			local died = whyP == "died" or (hpNow ~= nil and hpNow <= 0)
			if died and key then
				-- never again on this map, this server or the next: hides use the voidspam spot here
				cfg.voidFatal[key] = true
				saveConfigSoon()
			end
			log(if died then "WARN" else "INFO", ("void: Y %.0f unsafe (%s)%s"):format(target.Y, tostring(whyP), if died then " — this map is not probed again" else ""))
			if died then
				break
			end
			task.wait(0.6)
		end
		if safe and key then
			cfg.voidDepths[key] = safe
			saveConfigSoon()
			notify(("void measured · Y %.0f, %.0f st under the map"):format(safe, box.min.Y - safe), 4, "ok")
		else
			if auto then
				log("INFO", "void: auto failed")
			end
			notify("void: nothing safe under this map — hides go to the voidspam spot far out in the void", 5, "warn")
		end
		return safe
	end
	function Combat._calibrateSkyBody(char: Model, auto: boolean?): number?
		Combat.stopAutokill("calibration")
		Combat.body.goHome("calibration")
		local returnCF = char:GetPivot()
		local base = returnCF.Position
		local hp0 = Game.myHealth()
		local safe: number? = nil
		local upParams = RaycastParams.new()
		upParams.FilterType = Enum.RaycastFilterType.Exclude
		upParams.FilterDescendantsInstances = { char }
		-- measured from the top of the map, not from our feet: a void 200 st above where we stood sat a few
		-- dozen studs over the tallest parts (the box top carries 40 st of padding)
		local box = S.safe.mapBox()
		local clear = if box then math.max(base.Y, box.max.Y - 40) else base.Y
		log("INFO", ("void: calibrating sky height (map top Y %.0f)…"):format(clear))
		-- +200 then +400; the old +800 probe was mostly a way to die to the OOB volume
		for _, h in ipairs({ 200, 400 }) do
			local target = Vector3.new(base.X, clear + h, base.Z)
			local ceiling = workspace:Raycast(base + Vector3.new(0, 3, 0), Vector3.new(0, target.Y - base.Y - 3, 0), upParams)
			if ceiling then
				log("WARN", ("void: +%d blocked by %s"):format(h, ceiling.Instance and ceiling.Instance.Name or "?"))
				continue
			end
			local ok = Combat.probeHold(target, hp0)
			pivotTo(returnCF)
			Combat.markTeleport()
			if ok then
				local y = target.Y
				safe = y
				log("INFO", ("void: %s+%d safe (Y %.0f)"):format(if auto then "auto " else "", h, y))
				break
			end
			log("WARN", ("void: +%d unsafe"):format(h))
			local hpNow = Game.myHealth()
			if hpNow and hpNow <= 0 then
				break
			end
			task.wait(0.6)
		end
		if safe then
			cfg.voidHeights[tostring(game.PlaceId)] = safe
			saveConfigSoon()
			notify(("void calibrated · sky Y %.0f"):format(safe), 4, "ok")
		else
			if auto then
				log("INFO", "void: auto failed")
			end
			notify("void: the sky is out of bounds on this map — hides use the void under the map or the voidspam spot", 5, "warn")
		end
		return safe
	end

	-- auto-peek (hold key): swing out toward the lock and hold there while the key is down; Body
	-- brings you back on release
	local peek = { active = false, spot = nil, req = { hold = 0.3 } }
	function Combat.updateAutoPeek()
		local want = cfg.autoPeek and Combat.rageOn() and not S.featuresPaused and Input.isKeyDown(cfg.autoPeekKey) and S.silentTarget ~= nil and not S.menuOpen and ak.state == "idle" and not magic.active
		if want then
			if not peek.active then
				local me = Game.myRoot()
				local char = LP.Character
				if not (me and char) then
					return
				end
				local target = S.silentTarget :: Vector3
				local dir = (target - me.Position) * Vector3.new(1, 0, 1)
				if dir.Magnitude <= 0.5 then
					return
				end
				dir = dir.Unit
				orbitParams.FilterDescendantsInstances = { char }
				local dist = cfg.autoPeekDistance
				local hit = workspace:Raycast(me.Position, dir * dist, orbitParams)
				if hit then
					dist = math.max(0, (hit.Position - me.Position).Magnitude - 2)
				end
				peek.spot = me.Position + dir * dist
				peek.active = true
				log("INFO", "peek: out")
			end
			Combat.body.request("peek", peek.spot, S.silentTarget, peek.req)
			S.peek = true
		elseif peek.active then
			peek.active = false
			peek.spot = nil
			S.peek = nil
			Combat.body.release("peek")
			log("INFO", "peek: back")
		end
	end

	---------------------------------------------------------------------------
	-- weapon & movement stat edits — ItemLibrary.Items[name] is the live Info table every gun
	-- reads. Every edit snapshots the original into the persistent S.statOriginals the first time
	-- it is touched and always derives from that snapshot, so restore is exact.
	---------------------------------------------------------------------------
	local SPREAD_KEYS = { "ShootSpread", "AimSpreadMultiplier", "ShootSpreadPerVelocityUnit", "ShootSpreadPerVelocityLimit", "QuickShotSpread" }
	local RECOIL_KEYS = { "ShootRecoil", "ShootCameraDisplacementRecoil", "ShootCameraDisplacementRecoilWhileAiming" }
	-- Rapid fire (v6.7, two rates): RIVALS caps the fire rate server-side with some tolerance for network
	-- jitter. Both cooldowns are scaled by Combat.rapidMult(weapon) = the slider, so the gun fires at the
	-- cadence you picked on your screen; Combat.fireGate sends a round only once the server's gap
	-- (Combat.rapidServerMult: the learned floor, which climbs on the first NO-REPLY and probes back down
	-- after a clean run) has passed. Server ammo only drops for the rounds it gets.
	local FIRE_KEYS = { "ShootCooldown", "BurstCooldown" }
	-- rapid melee (v6.7): the swing cooldowns Melee.StartShooting stamps from; heavy attacks follow too
	Combat.MELEE_KEYS = { "AttackCooldown", "BurstCooldown", "HeavyAttackCooldown" }
	Combat.statWant = {}
	Combat.statLast = {}
	S.rapid = S.rapid or { ring = {}, v = 0, lastChangeAt = 0 }
	-- v6.3: every rapid-fire shot must be one the server answers. A gun that has not learned yet starts
	-- at its class default (the old flat ×0.5 dropped ~1 in 4 rounds); the flat ×0.9 above 400 ms ping is
	-- gone — a margin sized to the measured jitter replaces it (steady high ping does not bunch shots,
	-- unstable ping does). A range calibration (Combat.rapidCalibrate) measures each gun's real limit.
	Combat.RAPID_DEFAULT = { rifle = 0.7, burst = 0.8, projectile = 0.8, shotgun = 0.9, sniper = 0.9 }
	Combat.RAPID_MIN = { shotgun = 0.6, sniper = 0.6 }
	function Combat.rapidClass(name: string?): string
		local items = ItemLibrary and ItemLibrary.Items
		local info = type(items) == "table" and items[name or ""] or nil
		if type(info) ~= "table" then
			return "rifle"
		end
		local it = Combat.rapidItem
		it.Name, it.Info = name or "", info
		local c = Game.profileOf(it, Combat.rapidProf).class
		it.Info = nil
		return c
	end
	function Combat.rapidFloorOf(name: string?): number
		local c = Combat.rapidClass(name)
		local f = tonumber(cfg.rapidFloorSafe[name or ""])
		if f then
			return math.max(f, Combat.RAPID_MIN[c] or 0.3)
		end
		return Combat.RAPID_DEFAULT[c] or 0.7
	end
	-- round-trip samples at 4 Hz (Self.scanStep); the spread of the last ~10 s is how much evenly spaced
	-- shots can bunch up on the way to the server
	S.pingRing = S.pingRing or {}
	Combat.pingNoteAt = 0
	function Combat.notePing(ms: number)
		local now = os.clock()
		if now - Combat.pingNoteAt < 0.25 or type(ms) ~= "number" or ms <= 0 then
			return
		end
		Combat.pingNoteAt = now
		local r = S.pingRing
		table.insert(r, ms)
		if #r > 40 then
			table.remove(r, 1)
		end
		local n = #r
		local mean = 0
		for _, v in ipairs(r) do
			mean += v
		end
		mean /= n
		local var = 0
		for _, v in ipairs(r) do
			var += (v - mean) * (v - mean)
		end
		-- 10 ms buckets: the weapon stats are re-applied only when the bucket moves
		S.jitterMs = math.floor(math.sqrt(var / math.max(1, n - 1)) / 10 + 0.5) * 10
	end
	-- the server's rate check tolerates bunching over a run of shots (the old learner held ×0.55 on the
	-- Assault Rifle with 3 of 4 rounds answered at 470 ms ping), so jitter only nudges the floor: at most
	-- +0.10, and a full jitter of eight cooldowns to get there. The per-drop learner does the rest.
	function Combat.jitterMargin(cooldown: number): number
		local j = (S.jitterMs or 0) / 1000
		if cooldown <= 0 or j <= 0 then
			return 0
		end
		return math.clamp(j / (cooldown * 8), 0, 0.1)
	end
	-- v6.7: the cadence you SEE — the slider, on every gun (a range calibration never runs slower than its step)
	function Combat.rapidMult(name: string?): number
		local user = math.clamp(cfg.rapidFireMult, 0.01, 1)
		local cal = S.rapidCal
		if cal and cal.weapon == name then
			return math.min(user, cal.step)
		end
		return user
	end
	-- the cadence the SERVER gets: the learned per-weapon floor + the jitter margin (the step while measuring)
	function Combat.rapidServerMult(name: string?): number
		local cal = S.rapidCal
		if cal and cal.weapon == name then
			return cal.step
		end
		local orig = S.statOriginals[name or ""]
		local items = ItemLibrary and ItemLibrary.Items
		local info = type(items) == "table" and items[name or ""] or nil
		local cd = tonumber(orig and orig.ShootCooldown) or (type(info) == "table" and tonumber(info.ShootCooldown)) or 0.1
		return math.min(1, Combat.rapidFloorOf(name) + Combat.jitterMargin(cd))
	end
	-- the fire gate (Gun / Melee StartShooting hooks, Hooks.installFire): rounds faster than the server takes
	-- are played on your screen only. fireLast / fireBurst: the last round that went to the server per
	-- weapon (tick) and the burst it belongs to.
	Combat.fireLast = {}
	Combat.fireBurst = {}
	Combat.fireStats = { sent = 0, client = 0, held = 0 }
	-- per weapon: tick of the game's previous StartShooting and the smoothed spacing of those calls
	Combat.fireTry = {}
	-- the library's own value (before our stat edits)
	function Combat.origStat(name: string, info: any, key: string): number?
		local o = S.statOriginals[name]
		local v = o and o[key]
		if v == nil then
			v = info[key]
		end
		return tonumber(v)
	end
	-- seconds the server needs between two rounds of this item (burst guns: inside / after a burst)
	function Combat.fireGap(item: any): number
		local info = item.Info
		local name = tostring(item.Name)
		local O = Combat.origStat
		if info.Type == "Gun" then
			local m = Combat.rapidServerMult(name)
			local burst = tonumber(info.BurstCount) or 1
			local n = Combat.fireBurst[name] or 0
			local cd = O(name, info, "ShootCooldown") or 0.1
			if burst > 1 and n % burst ~= 0 then
				cd = O(name, info, "BurstCooldown") or cd
			end
			return cd * m
		end
		local floor = tonumber(cfg.rapidFloorMelee[name]) or cfg.rapidMeleeServer
		local burst = tonumber(info.BurstCount) or 1
		local n = Combat.fireBurst[name] or 0
		local cd = O(name, info, "AttackCooldown") or 0.5
		if burst > 1 and n % burst ~= 0 then
			cd = O(name, info, "BurstCooldown") or cd
		end
		return cd * math.clamp(floor, 0.1, 1)
	end
	-- "pass" = the game's own shot (sent), "client" = played on your screen only, "block" = not at all
	-- (voidspam holds it until the body is back). Runs inside the item's StartShooting on the shot thread:
	-- table reads and arithmetic only.
	function Combat.fireGate(item: any, replicated: any, quick: any): string
		if replicated or quick or not S.alive or S.featuresPaused or type(item) ~= "table" then
			return "pass"
		end
		local info = item.Info
		if type(info) ~= "table" or (info.Type ~= "Gun" and info.Type ~= "Melee") then
			return "pass"
		end
		if Combat.voidFireHold() then
			Combat.fireStats.held += 1
			return "block"
		end
		local st = S.cfg
		local rapid = if info.Type == "Gun" then (st.rapidFire and not Combat.rapidExempt(info, tostring(item.Name))) else st.rapidMelee
		if not rapid or not st.rapidThrottle then
			return "pass"
		end
		local name = tostring(item.Name)
		local now = tick()
		local tr = Combat.fireTry[name]
		if tr == nil then
			tr = { at = now, every = 0 }
			Combat.fireTry[name] = tr
		else
			local d = now - tr.at
			tr.at = now
			if d < 0.25 then
				tr.every = if tr.every == 0 then d else tr.every + (d - tr.every) * 0.2
			end
		end
		local last = Combat.fireLast[name]
		if last == nil then
			return "pass"
		end
		-- the game offers a round every `every` s: send the one nearest the gap, not the first one past it
		-- (that overshot by up to a whole offer — Assault Rifle 0.097 s between sent rounds on a 0.070 s gap)
		local gap = Combat.fireGap(item)
		if now - last >= gap - math.min(tr.every * 0.5, gap * 0.2) then
			return "pass"
		end
		return "client"
	end
	-- a round actually left the gun (the item returned true): how = "pass" (to the server) / "client"
	function Combat.fireDone(item: any, how: string)
		local name = tostring(item.Name)
		if how == "client" then
			Combat.fireStats.client += 1
			return
		end
		Combat.fireStats.sent += 1
		local info = item.Info
		local burst = type(info) == "table" and tonumber(info.BurstCount) or 1
		local last = Combat.fireLast[name]
		local cd = type(info) == "table" and (Combat.origStat(name, info, if info.Type == "Gun" then "ShootCooldown" else "AttackCooldown") or 0.5) or 0.5
		-- a pause longer than the cooldown starts a fresh burst
		if burst > 1 and last ~= nil and tick() - last < cd then
			Combat.fireBurst[name] = (Combat.fireBurst[name] or 0) + 1
		else
			Combat.fireBurst[name] = 1
		end
		Combat.fireLast[name] = tick()
		if Combat.voidSpamOn() then
			Combat.vs.fireAt = os.clock() -- firing from your spot keeps voidspam from taking you out
		end
	end
	-- range calibration: from ×1.0 down in 0.1 steps, 30 answered-or-dropped rounds per step. The first
	-- step with more than one unanswered round ends it; the last clean step becomes the gun's floor.
	function Combat.rapidCalibrate(weapon: string?)
		if type(weapon) ~= "string" or weapon == "—" then
			notify("Hold the gun you want to measure first", 3, "warn")
			return
		end
		S.rapidCal = { weapon = weapon, step = 1, n = 0, drops = 0, ok = nil }
		log("INFO", ("[rapid:cal] %s: measuring the server's fire-rate limit from ×1.00"):format(weapon))
		notify(("Measuring %s: keep shooting a range dummy (30 rounds per step)"):format(weapon), 5, "info")
		task.defer(Combat.applyWeaponStats, true)
	end
	function Combat.rapidCalStep(drop: boolean)
		local c = S.rapidCal
		if not c then
			return
		end
		c.n += 1
		if drop then
			c.drops += 1
		end
		local finish: number? = nil
		if c.drops > 1 then
			finish = c.ok or 1
		elseif c.n >= 30 then
			c.ok = c.step
			if c.step <= 0.31 then
				finish = c.step
			else
				c.step = math.floor((c.step - 0.1) * 100 + 0.5) / 100
				c.n, c.drops = 0, 0
				log("INFO", ("[rapid:cal] %s: ×%.2f clean — trying ×%.2f"):format(c.weapon, c.ok, c.step))
				task.defer(Combat.applyWeaponStats, true)
			end
		end
		if finish then
			local weapon = c.weapon
			S.rapidCal = nil
			finish = math.min(finish, 0.96) -- sanitize drops ×0.98+ (lag-taught floors); ×0.96 + jitter margin covers it
			cfg.rapidFloorSafe[weapon] = finish
			saveConfigSoon()
			log("INFO", ("[rapid:cal] %s: server limit ×%.2f (saved as its rapid-fire floor)"):format(weapon, finish))
			task.defer(function()
				if S.alive then
					notify(("%s: fastest clean rate ×%.2f — saved"):format(weapon, finish), 5, "ok")
					Combat.applyWeaponStats(true)
				end
			end)
		end
	end
	-- one server verdict for a shot of `weapon` while rapid fire is on
	function Combat.median(t: { number }): number?
		local n = #t
		if n == 0 then
			return nil
		end
		local c = table.clone(t)
		table.sort(c)
		return if n % 2 == 1 then c[(n + 1) / 2] else (c[n / 2] + c[n / 2 + 1]) / 2
	end
	function Combat.rapidLearn(weapon: string, verdict: string, rec: any?)
		-- behind the lobby gate the gun fires at its real cadence: nothing to learn about rapid fire there
		if not (cfg.rapidFire and cfg.rapidAdaptive) or type(weapon) ~= "string" or S.featuresPaused then
			return
		end
		local R = S.rapid
		local drop = verdict == "NO-REPLY"
		local cal = S.rapidCal
		if cal and cal.weapon == weapon then
			Combat.rapidCalStep(drop)
			return
		end
		local now = os.clock()
		R.good = R.good or {}
		R.bad = R.bad or {}
		R.win = R.win or {}
		R.rtt = R.rtt or {}
		R.ansAt = R.ansAt or {}
		local win = R.win[weapon]
		if not win then
			win = {}
			R.win[weapon] = win
		end
		table.insert(win, drop)
		if #win > 12 then
			table.remove(win, 1)
		end
		if not drop then
			R.ansAt[weapon] = now
			if rec and type(rec.rttMs) == "number" then
				table.insert(R.rtt, rec.rttMs)
				if #R.rtt > 8 then
					table.remove(R.rtt, 1)
				end
			end
		end
		local floor = Combat.rapidFloorOf(weapon)
		local minF = Combat.RAPID_MIN[Combat.rapidClass(weapon)] or 0.3
		local changed: number? = nil
		local drops = 0
		for _, d in ipairs(win) do
			if d then
				drops += 1
			end
		end
		-- v6.7: a lost round teaches the fire rate only when the server kept answering around it. A rate
		-- reject drops rounds between answered ones at a normal round trip; lag stalls the answers (none in
		-- the last 1.2 s — this verdict lands 1.5 s after its round left) or slows them down. The 6.6
		-- first-drop rule read every lag spike as a reject and walked the Assault Rifle and Spray to ×1.00.
		-- Two real drops in the last 12 rounds back off +0.04; 20 clean rounds probe −0.03 (never below a
		-- speed that dropped rounds on this server in the last 5 minutes).
		if drop then
			R.good[weapon] = 0
			local med = Combat.median(R.rtt)
			local stalled = now - (R.ansAt[weapon] or 0) > 1.2
			if S.highPing or (S.pingMs or 0) > 350 or (med ~= nil and med > 550) or stalled then
				win[#win] = false -- not the server's rate: keep it out of the count
				if now - (R.lagLogAt or 0) > 5 then
					R.lagLogAt = now
					log("DEBUG", ("[rapid:lag] %s: a lost round ignored (ping %d ms · answers %s ms · %s)"):format(weapon, S.pingMs or 0, if med then tostring(math.floor(med)) else "?", if stalled then "answers stalled" else "slow answers"))
				end
			elseif drops >= 2 then
				R.bad[weapon] = { f = floor, at = now, job = game.JobId }
				-- capped under sanitize's ×0.98 cut (the jitter margin still adds on top when sending)
				if floor < 0.96 then
					changed = math.min(0.96, floor + 0.04)
				end
			end
		else
			R.good[weapon] = (R.good[weapon] or 0) + 1
			if R.good[weapon] >= 20 and floor > minF then
				R.good[weapon] = 0
				local nf = math.max(minF, floor - 0.03)
				local b = R.bad[weapon]
				if not (b and b.job == game.JobId and now - b.at < 300 and nf <= b.f + 1e-6) then
					changed = nf
				end
			end
		end
		local ring = win
		if changed and math.abs(changed - floor) > 1e-6 then
			local down = changed < floor
			cfg.rapidFloorSafe[weapon] = math.floor(changed * 100 + 0.5) / 100
			R.ring[weapon] = {}
			R.v += 1
			R.lastChangeAt = os.clock()
			-- this runs inside the _ShootEffect hook on the game's shot thread: the file write, the
			-- toast and the library walk are deferred to the next frame
			saveConfigSoon()
			log("INFO", ("rapid fire: %s server pace %s to ×%.2f%s"):format(weapon, if down then "probed down" else "backed off", cfg.rapidFloorSafe[weapon], if down then " (20 clean rounds — testing faster)" else (" (%d of the last %d rounds dropped by the server)"):format(drops, #ring)))
			task.defer(function()
				if not S.alive then
					return
				end
				R.toastAt = R.toastAt or {}
				if not down and os.clock() - (R.toastAt[weapon] or 0) > 30 then
					R.toastAt[weapon] = os.clock()
					notify(("rapid fire: %s at ×%.2f — the server dropped a shot"):format(weapon, cfg.rapidFloorSafe[weapon]), 3, "warn")
				end
				Combat.applyWeaponStats(true)
			end)
		end
	end
	local function zeroLike(v: any): any
		return if typeof(v) == "Vector2" then Vector2.zero elseif typeof(v) == "Vector3" then Vector3.zero else 0
	end
	local function statSet(info: any, orig: any, key: string, on: boolean, mapper: (any) -> any)
		if info[key] == nil and orig[key] == nil then
			return
		end
		if orig[key] == nil then
			orig[key] = info[key] -- first touch
		end
		info[key] = if on then mapper(orig[key]) else orig[key]
	end
	function Combat.applyWeaponStats(force: boolean?)
		if not (ItemLibrary and type(ItemLibrary.Items) == "table") then
			return
		end
		-- behind the lobby gate the stats stay real (Combat.pauseAll restored them; statLast is clear)
		if S.featuresPaused and not S.gateOverride then
			return
		end
		local akOn = ak.state ~= "idle" and ak.state ~= "done"
		-- one reused wants-table compared field by field: the old version built a 14-part string
		-- (tostring + concat) on every frame before finding out nothing changed
		local w = Combat.statWant
		w.spread = cfg.noSpread == true or akOn
		w.recoil = cfg.noRecoil == true or akOn
		w.fire = cfg.rapidFire == true
		w.fullAuto = cfg.fullAuto == true
		w.instant = cfg.instantBullet == true
		w.equip = cfg.fastEquip == true
		w.aim = cfg.fastAim == true
		w.speed = cfg.speedBoost == true
		w.noZoom = cfg.noAdsZoom == true
		w.melee, w.meleeMult = cfg.rapidMelee == true, cfg.rapidMeleeMult
		w.speedHook = S.hooks.installed.walkSpeed == true
		-- jitter in 40 ms buckets: a 10 ms bucket re-applied the whole library (and logged) every second
		w.rapidMult, w.rapidAdaptive, w.rapidV, w.jitter = cfg.rapidFireMult, cfg.rapidAdaptive == true, S.rapid.v, math.floor((S.jitterMs or 0) / 40)
		w.cal = if S.rapidCal then S.rapidCal.weapon .. S.rapidCal.step else ""
		w.equipMult, w.aimMult, w.speedMult = cfg.fastEquipMult, cfg.fastAimMult, cfg.speedMult
		local last = Combat.statLast
		local same = not force
		if same then
			for k, v in pairs(w) do
				if last[k] ~= v then
					same = false
					break
				end
			end
		end
		if same then
			return
		end
		for k, v in pairs(w) do
			last[k] = v
		end
		local rapid = math.clamp(cfg.rapidFireMult, 0.01, 1)
		local equipM = math.clamp(cfg.fastEquipMult, 0.01, 1)
		local aimM = math.clamp(cfg.fastAimMult, 1, 30)
		local speedM = math.clamp(cfg.speedMult, 1, 10)
		local meleeM = math.clamp(cfg.rapidMeleeMult, 0.01, 1)
		local function applyTo(info: any, orig: any, name: string?)
			local rapidM = Combat.rapidMult(name)
			local isGun = info.Type == "Gun"
			local rapidOn = w.fire and isGun and not Combat.rapidExempt(info, name)
			local meleeOn = w.melee and info.Type == "Melee"
			for _, k in ipairs(SPREAD_KEYS) do
				statSet(info, orig, k, w.spread, zeroLike)
			end
			statSet(info, orig, "ShootSpreadConsistent", w.spread, function(_)
				return false
			end)
			-- ShootAccuracy is the library's hit-leniency stat (Sniper/Crossbow 0.2 … Revolver/Glass
			-- Cannon 3): no-spread lifts every gun to the most forgiving value in the library
			statSet(info, orig, "ShootAccuracy", w.spread, function(v)
				return if type(v) == "number" then math.max(v, 3) else v
			end)
			for _, k in ipairs(RECOIL_KEYS) do
				statSet(info, orig, k, w.recoil, zeroLike)
			end
			if isGun then
				for _, k in ipairs(FIRE_KEYS) do
					statSet(info, orig, k, rapidOn, function(v)
						return if type(v) == "number" then v * rapidM else v
					end)
				end
				-- FullAuto: the game repeats StartShooting while the trigger is held for any action whose
				-- InputSpammingEnabled entry is a number (0 = every frame); semi-autos carry false there. The
				-- server still paces every round by the gun's cooldown, so nothing is fired faster than it allows
				statSet(info, orig, "InputSpammingEnabled", w.fullAuto, function(v)
					if type(v) ~= "table" or v.StartShooting ~= false then
						return v
					end
					local t = table.clone(v)
					t.StartShooting = 0
					return t
				end)
			else
				-- melee (and every other non-gun): Melee.StartShooting stamps _attack_cooldown from these, so a
				-- manual click swings at the slider's speed too
				for _, k in ipairs(Combat.MELEE_KEYS) do
					statSet(info, orig, k, meleeOn, function(v)
						return if type(v) == "number" then v * meleeM else v
					end)
				end
			end
			statSet(info, orig, "EquipCooldown", w.equip, function(v)
				return if type(v) == "number" then v * equipM else v
			end)
			statSet(info, orig, "AimSpeed", w.aim, function(v)
				return if type(v) == "number" then v * aimM else v
			end)
			-- the _GetWalkSpeed hook boosts every speed (armed or not); the item stat is only the fallback
			statSet(info, orig, "WalkSpeedMultiplier", w.speed and not w.speedHook, function(v)
				return if type(v) == "number" then v * speedM else v
			end)
			statSet(info, orig, "AimFOVOffset", w.noZoom, function(v)
				return if type(v) == "number" then 0 else v
			end)
			local projectile = info.IsProjectile == true
			statSet(info, orig, "ProjectileSpeed", w.instant and projectile, function(v)
				return if type(v) == "number" then 100000 else v
			end)
			statSet(info, orig, "ProjectileGravity", w.instant and projectile, function(v)
				return if type(v) == "number" then 0 else v
			end)
		end
		for name, info in pairs(ItemLibrary.Items) do
			if type(info) == "table" then
				S.statOriginals[name] = S.statOriginals[name] or {}
				applyTo(info, S.statOriginals[name], tostring(name))
			end
		end
		-- live items whose Info is a private copy (not the library table) get the same edits
		local lf = Game.localFighter()
		local copies = 0
		if lf and type(lf.Items) == "table" then
			for _, item in pairs(lf.Items) do
				local info = type(item) == "table" and item.Info
				if type(info) == "table" and ItemLibrary.Items[item.Name] ~= info then
					local orig = S.itemInfoOriginals[info]
					if not orig then
						orig = {}
						S.itemInfoOriginals[info] = orig
					end
					applyTo(info, orig, tostring(item.Name))
					copies += 1
				end
			end
		end
		-- logged only when a switch the player sees changed (learner / jitter re-applies stay quiet)
		local sig = ("%s%s%s%s%s%s%s%.2f%s%.2f%s%s"):format(tostring(w.spread), tostring(w.recoil), tostring(w.fire), tostring(w.instant), tostring(w.equip), tostring(w.aim), tostring(w.speed), rapid, tostring(w.melee), meleeM, tostring(cfg.instantReload), tostring(w.fullAuto))
		if sig ~= Combat.statLogSig then
			Combat.statLogSig = sig
			log("INFO", ("weapon stats: spread=%s recoil=%s rapid fire=%s(on screen x%.2f, server learned per weapon) full auto=%s rapid melee=%s(on screen x%.2f, server x%.2f) instant reload=%s instant projectiles=%s equip=%s aim=%s speed=%s%s"):format(
				tostring(w.spread), tostring(w.recoil), tostring(w.fire), rapid, tostring(w.fullAuto), tostring(w.melee), meleeM, cfg.rapidMeleeServer, tostring(cfg.instantReload == true), tostring(w.instant), tostring(w.equip), tostring(w.aim), tostring(w.speed),
				if copies > 0 then (" · %d live item copies"):format(copies) else ""
			))
		end
	end
	-- the held item set changed (new round, swap): re-apply so private Info copies get the edits
	local lastItemSig = ""
	function Combat.trackItems()
		local lf = Game.localFighter()
		local parts = {}
		if lf and type(lf.Items) == "table" then
			for _, item in pairs(lf.Items) do
				if type(item) == "table" then
					table.insert(parts, tostring(item.Name))
				end
			end
		end
		table.sort(parts)
		local sig = table.concat(parts, ",")
		if sig ~= lastItemSig then
			lastItemSig = sig
			-- behind the lobby gate the stats stay real; the first live frame applies them (statLast is clear)
			if sig ~= "" and not S.featuresPaused then
				Combat.applyWeaponStats(true)
			end
		end
	end
	function Combat.restoreWeaponStats()
		if not (ItemLibrary and type(ItemLibrary.Items) == "table") then
			return
		end
		for name, orig in pairs(S.statOriginals) do
			local info = ItemLibrary.Items[name]
			if type(info) == "table" then
				for k, v in pairs(orig) do
					info[k] = v
				end
			end
		end
		for info, orig in pairs(S.itemInfoOriginals) do
			for k, v in pairs(orig) do
				info[k] = v
			end
		end
		table.clear(Combat.statLast)
	end
	S.applyWeaponStats = Combat.applyWeaponStats
	S.restoreWeaponStats = Combat.restoreWeaponStats

	-- instant reload (v6.7): the server owns Ammo and refills it at the reload file's ActionTimestamp
	-- (Assault Rifle: in at 1.56 s of a 3.0 s reload); the rest is the client's animation lockout. The old
	-- version moved the reload stamps to "now": the next trigger pull then found Ammo still 0 outside a
	-- reload and started ANOTHER reload (Gun.StartShooting → StartReloading, sent to the server again) —
	-- held fire restarted the reload forever. Now the reload runs untouched and ends the moment the
	-- server's refill arrives (Combat.updateInstantReload); segmented reloads (shells) once the mag is full.
	Combat.reloadWatch = nil
	function Combat.afterReload(item: any)
		if type(item) ~= "table" then
			return
		end
		local now = os.clock()
		local wall = tick() -- the Gun class stamps its cooldowns with tick()
		local realStamp = tonumber(rawget(item, "_reload_cooldown"))
		local serverDur = if realStamp and realStamp > wall then realStamp - wall else nil
		-- only mark a reload as in-progress if the item really is reloading; otherwise clear it so the
		-- HUD chip and the trigger gate never show a phantom reload
		if serverDur and serverDur > 0.05 then
			S.reloadStartedAt = now
			S.reloadUntil = now + serverDur
			S.reloadServerEta = serverDur
			local info = type(item.Info) == "table" and item.Info or {}
			local a0, _, reserve = Game.itemAmmo(item)
			local ammo0 = a0 or 0
			local max = tonumber(info.MaxAmmo) or math.huge
			Combat.reloadWatch = {
				item = item,
				ammo0 = ammo0,
				target = if reserve then math.min(max, ammo0 + reserve) else max,
				segmented = info.ReloadType == "Segmented",
				at = now,
				stamp = realStamp,
			}
		else
			S.reloadUntil = 0
		end
	end
	-- once per frame while a reload runs: the server's refill ends the client's lockout
	function Combat.updateInstantReload(gs: any)
		local W = Combat.reloadWatch
		if not W then
			return
		end
		local item = W.item
		local stamp = tonumber(rawget(item, "_reload_cooldown"))
		if gs == nil or gs.item ~= item or not stamp or stamp <= tick() or os.clock() - W.at > 10 then
			Combat.reloadWatch = nil -- finished on its own, swapped away or cancelled
			return
		end
		if not cfg.instantReload then
			return
		end
		local ammo = Game.itemAmmo(item)
		if ammo == nil or ammo <= W.ammo0 then
			return -- the server has not refilled yet
		end
		if W.segmented and ammo < W.target then
			return -- shells: each one can already be fired; the lockout ends with the last one
		end
		Combat.reloadWatch = nil
		local saved = stamp - tick()
		local ok = pcall(item._ResetReloadState, item)
		if ok then
			S.reloadUntil = 0
			log("DEBUG", ("reload: %s ready %.2f s in (server refilled to %d) — %.2f s of animation skipped"):format(tostring(item.Name), os.clock() - W.at, ammo, math.max(saved, 0)))
		end
	end

	-- auto reload when the mag is empty and nothing is locked; auto-switch to a loaded gun mid-lock
	local lastReloadTry = 0
	local lastSwitchTry = 0
	function Combat.updateReload(gs: any)
		local item = gs.item
		if not item or S.menuOpen then
			return
		end
		local now = os.clock()
		-- already reloading? (item's own tick stamp) → never stack another reload
		local reloadingNow = tonumber(rawget(item, "_reload_cooldown"))
		reloadingNow = reloadingNow ~= nil and tick() < reloadingNow
		-- both go through the game's own input path / the MechanicsController trampoline: a reload
		-- or equip replicated from our own thread (plain asGame) is silently dropped by the server
		-- reload early: a mag under the threshold is topped up once nobody is locked or in sight and the
		-- gun has been quiet for a moment, so a fight starts on a full mag instead of a dry click mid-duel
		local early = false
		if cfg.reloadEarly > 0 and gs.ammo ~= nil and gs.ammo > 0 and S.silentTarget == nil and not S.targetVisible then
			local info = type(item.Info) == "table" and item.Info or nil
			local max = info and tonumber(info.MaxAmmo)
			local quiet = tick() - (Combat.fireLast[tostring(item.Name)] or 0) > 0.8
			early = max ~= nil and max > 1 and quiet and gs.ammo < max and gs.ammo / max * 100 <= cfg.reloadEarly
		end
		if (early or (cfg.autoReload and gs.ammo ~= nil and gs.ammo <= 0)) and not reloadingNow and S.silentTarget == nil and now > (S.reloadUntil or 0) and now - lastReloadTry > 1 then
			lastReloadTry = now
			if not Input.gameInput("StartReloading") and type(item.StartReloading) == "function" then
				Game.asShotCode(item.StartReloading, item)
			end
		end
		-- switch when empty: one swap away from a gun that runs dry mid-fight, to a gun known to be loaded.
		-- A gun we swapped away from is left alone once the player picks it again (they want to reload it:
		-- it gets the reload) until its mag is back; a reload in progress is never interrupted; with nothing
		-- loaded to swap to, the empty gun reloads. It used to swap every 1.5 s, straight back out of the gun
		-- the player had just selected, and ping-pong between two empty guns (unknown ammo counted as loaded).
		-- SW.left[gun] = { at, away }: `away` turns true once another gun is really in hand — only then does holding
		-- the empty one again mean "the player came back to reload it". Until then the swap is still landing
		-- (the equip takes a moment): no reload into it, and a swap that never landed may be tried again.
		local SW = Combat.switchEmpty
		for it, e in pairs(SW.left) do
			local a = Game.itemAmmo(it)
			if a ~= nil and a > 0 then
				SW.left[it] = nil
			elseif item ~= it then
				e.away = true
			elseif not e.away and now - e.at > 1.5 then
				SW.left[it] = nil -- the swap never landed
			end
		end
		if cfg.autoSwitchEmpty and gs.ammo ~= nil and gs.ammo <= 0 and S.silentTarget ~= nil and not reloadingNow and now - lastSwitchTry > 0.6 then
			lastSwitchTry = now
			local startReload = function()
				if now > (S.reloadUntil or 0) and now - lastReloadTry > 1 then
					lastReloadTry = now
					if not Input.gameInput("StartReloading") and type(item.StartReloading) == "function" then
						Game.asShotCode(item.StartReloading, item)
					end
				end
			end
			local left = SW.left[item]
			if left then
				if left.away then
					startReload() -- the player came back to it
				end
				return -- else the swap is still landing
			end
			local lf = Game.localFighter()
			local swapped = false
			if lf and type(lf.Items) == "table" then
				for slot, other in pairs(lf.Items) do
					if other ~= item and not SW.left[other] and type(other) == "table" and type(other.Info) == "table" and other.Info.Type == "Gun" then
						local a = Game.itemAmmo(other)
						if a ~= nil and a > 0 then
							local ok = false
							-- ClientFighter:EquipItem takes the slot number ("Argument 1 invalid, expected a number")
							if type(lf.EquipItem) == "function" and type(slot) == "number" then
								ok = Game.asShotCode(lf.EquipItem, lf, slot)
							elseif type(other.Equip) == "function" then
								ok = Game.asShotCode(other.Equip, other)
							end
							log("DEBUG", "auto-switch →", tostring(other.Name), if ok then "ok" else "failed")
							if ok then
								SW.left[item] = { at = now, away = false }
								swapped = true
							end
							break
						end
					end
				end
			end
			if not swapped then
				startReload()
			end
		end
	end
	Combat.switchEmpty = { left = setmetatable({}, { __mode = "k" }) }

	-- movement helpers (everything here is server-checked → experimental, off by default)
	local lastSlide = 0
	function Combat.updateMovement(gs: any)
		if S.menuOpen or not (cfg.bhop or cfg.autoSlide or cfg.noAdsSlow) then
			return -- all three off (the defaults): no Humanoid lookup per frame for nothing
		end
		local char = LP.Character
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		if not hum then
			return
		end
		local grounded = hum.FloorMaterial ~= Enum.Material.Air
		if cfg.bhop and grounded and UIS:IsKeyDown(Enum.KeyCode.Space) then
			hum.Jump = true
		end
		local lf = if cfg.autoSlide then Game.localFighter() else nil
		if cfg.autoSlide and lf and grounded and hum.MoveDirection.Magnitude > 0.1 and os.clock() - lastSlide > 0.7 then
			local sprinting, sliding = false, false
			if type(lf.IsSprinting) == "function" and type(lf.IsSliding) == "function" then
				local okS, sp = pcall(lf.IsSprinting, lf)
				local okL, sl = pcall(lf.IsSliding, lf)
				sprinting = okS and sp == true
				sliding = okL and sl == true
			end
			if sprinting and not sliding then
				lastSlide = os.clock()
				Input.tap(cfg.slideKey)
			end
		end
		-- the _GetWalkSpeed hook does this without racing the game; this write is the fallback without it
		if cfg.noAdsSlow and not S.hooks.installed.walkSpeed then
			if gs.aiming then
				if S.baseWalk and hum.WalkSpeed < S.baseWalk then
					hum.WalkSpeed = S.baseWalk
				end
			elseif hum.WalkSpeed > 0 then
				S.baseWalk = hum.WalkSpeed
			end
		end
	end

	-- server-confirm estimate: a redirected hit that never lowers the target's health within the
	-- window was most likely dropped by the server (fire rate / position / origin checks)
	local lastAirToastAt = 0
	local dmgWatch: { fighter: any, hp: number? } = { fighter = nil, hp = nil }
	function Combat.updateShotConfirm()
		local now = os.clock()
		-- damage actually dealt to the locked fighter (server truth) vs what our hits were worth
		local f = S.silentFighter
		local fresh = now - (S.hitMarkerAt or 0) < 1
		if f ~= dmgWatch.fighter then
			-- the lock left a fighter that died on our round (the dead-target guard drops it the frame its
			-- health hits 0): the health it still had went to us
			local old = dmgWatch.fighter
			if old ~= nil and fresh and (dmgWatch.hp or 0) > 0 then
				local hpOld = Game.fighterHealth(old)
				if hpOld == nil or hpOld <= 0 or Target.isDead(old) then
					S.dmgDealt = (S.dmgDealt or 0) + dmgWatch.hp
				end
			end
			dmgWatch.fighter = f
			dmgWatch.hp = f and Game.fighterHealth(f) or nil
		elseif f then
			local hp = Game.fighterHealth(f)
			if hp ~= nil and dmgWatch.hp ~= nil then
				if hp < dmgWatch.hp and fresh then
					S.dmgDealt = (S.dmgDealt or 0) + (dmgWatch.hp - hp)
				end
				dmgWatch.hp = hp
			elseif hp ~= nil then
				dmgWatch.hp = hp
			elseif fresh and (dmgWatch.hp or 0) > 0 then
				S.dmgDealt = (S.dmgDealt or 0) + dmgWatch.hp -- the fighter is gone the frame it died
				dmgWatch.hp = 0
			end
		end
		local pend = S.pendingHits
		if #pend > 64 then
			-- never let the queue grow unbounded (a stalled confirm loop once froze the client)
			for _ = 1, #pend - 64 do
				table.remove(pend, 1)
			end
		end
		local i = 1
		local guard = 0
		while i <= #pend and guard < 256 do
			guard += 1
			local e = pend[i]
			local hp = e.fighter and Game.fighterHealth(e.fighter)
			if hp == nil then
				local hum = e.model and e.model:FindFirstChildOfClass("Humanoid")
				hp = hum and hum.Health
			end
			if hp ~= nil and hp < e.hp - 0.5 then
				-- one damage tick confirms every shot that had time to reach the server
				local j = 1
				local inner = 0
				while j <= #pend and inner < 256 do
					inner += 1
					local x = pend[j]
					if x.model == e.model and now - x.t >= 0.03 then
						S.shotStats.confirmed += 1
						S.lastConfirmAt = now
						table.remove(pend, j)
					else
						j += 1
					end
				end
				S.lastHitModel = e.model
				S.lastHitAt = now
				local pp = e.model and e.model.PrimaryPart
				S.lastHitPos = pp and pp.Position
				if pend[i] == e then
					-- this entry was too fresh to confirm: keep it but make progress
					e.hp = hp
					i += 1
				end
			elseif now - e.t > 0.45 then
				S.shotStats.dropped += 1
				table.remove(pend, i)
			else
				i += 1
			end
		end
		local ss = S.shotStats
		if ss.redirected >= 50 and ss.redirected % 50 == 0 and ss.redirected ~= S.lastAirCheck then
			S.lastAirCheck = ss.redirected
			if ss.miss / ss.redirected > 0.1 and now - lastAirToastAt > 20 then
				lastAirToastAt = now
				notify(("%d%% of redirected shots hit nothing — usually a lock on a dead/occluded target or a ping spike; the resolver and dead-target guard help"):format(math.floor(ss.miss / ss.redirected * 100)), 6, "warn")
			end
		end
	end

	-- did one of our shots just go into this model? (the silent redirect's own hit, or the last
	-- recorded local shot aimed at it)
	function Combat.recentlyShot(model: Instance, now: number): boolean
		if now - (S.hitMarkerAt or 0) < 0.8 then
			return true
		end
		if S.serverHitModel == model and now - (S.serverHitAt or 0) < 0.8 then
			return true
		end
		local list = S.shots and S.shots.list
		local rec = list and list[#list]
		return rec ~= nil and rec.model == model and now - (rec.t or 0) < 0.8
	end
	-- one kill, once per character model: the HUD kill list and the kill effect
	function Combat.registerKill(model: Instance?, name: string, pos: Vector3?)
		if not model or S.killFeedSeen[model] then
			return
		end
		S.killFeedSeen[model] = true
		S.kills = (S.kills or 0) + 1
		log("INFO", "kill:", name)
		local onKill = S.ext and S.ext.onKill
		if onKill then
			pcall(onKill, model)
		end
		if S.shots and S.shots.killed then
			pcall(S.shots.killed, model)
		end
		if S.shots and S.shots.creditKill then
			pcall(S.shots.creditKill, model)
		end
		if cfg.killFeed then
			table.insert(S.killList, 1, { name = name, weapon = (S.gameState or {}).weapon, t = os.clock() })
			for i = #S.killList, 6, -1 do
				S.killList[i] = nil
			end
		end
		local fx = S.vis
		if cfg.killEffect ~= "Off" and fx and pos and #fx.killQueue < 4 then
			table.insert(fx.killQueue, pos)
		end
	end
	-- kills (HUD kill list, kill effect) and damage numbers: an enemy we recently hit losing health
	-- or dropping to 0 HP
	function Combat.updateKills(enemies: { any })
		-- 10 Hz is plenty to notice a damage tick or a 0-HP transition; per frame this was a health
		-- read per enemy
		if not (cfg.killFeed or cfg.killEffect ~= "Off" or cfg.hitNumbers or S.ext.onKill) or Game.frameId % 6 ~= 0 then
			return
		end
		local now = os.clock()
		local fx = S.vis
		for _, f in ipairs(enemies) do
			local root, model = Game.fighterBody(f)
			local hp = Game.fighterHealth(f)
			if model and hp ~= nil then
				local last = S.hpSeen[model]
				S.hpSeen[model] = hp
				if last and hp < last - 0.5 and Combat.recentlyShot(model, now) then
					S.lastHitModel = model
					S.lastHitAt = now
					S.lastHitPos = root and root.Position
					if cfg.hitNumbers and fx and #fx.hitQueue < 16 then
						local head = Game.fighterHead(f)
						local at = (head and head.Position) or (root and root.Position)
						if at then
							table.insert(fx.hitQueue, { at, last - hp })
						end
					end
				end
				if hp <= 0 then
					if S.lastHitModel == model and now - (S.lastHitAt or 0) < 4 then
						Combat.registerKill(model, Game.fighterName(f), root and root.Position)
					end
				else
					S.killFeedSeen[model] = nil
				end
			end
		end
		-- a dead player leaves the enemy list at once, so the loop above rarely sees their 0 HP: the
		-- model we just hit vanishing (or its Humanoid at 0) right after our hit is the kill
		local lm = S.lastHitModel
		if lm and not S.killFeedSeen[lm] and now - (S.lastHitAt or 0) < 1.5 then
			local gone = lm.Parent == nil
			local hum = if gone then nil else lm:FindFirstChildOfClass("Humanoid")
			if gone or (hum and hum.Health <= 0) then
				Combat.registerKill(lm, lm.Name, S.lastHitPos)
			end
		end
	end

	S.startAutokill = function()
		return Combat.startAutokill(Game.targets())
	end
	S.stopAutokill = Combat.stopAutokill
	S.calibrateVoid = Combat.calibrateVoid
	S.magicOrigin = Combat.magicOrigin

	-----------------------------------------------------------------------------
	-- §7b shots — the recorder. One record per shot we replicate: what we claimed (camera data)
	-- and what the server answered (ShootEffect). Verdicts feed the F9 terminal, Debug → Shots,
	-- centerra/shots.json and the backtrack estimator.
	-----------------------------------------------------------------------------
	local Shots: any = { list = {}, pending = {}, n = 0, max = 60, stats = { hit = 0, near = 0, wall = 0, air = 0, noReply = 0, unaimed = 0, immune = 0 } }
	S.shots = Shots
	S.cdDbg = S.cdDbg or { calls = 0, zeroArg = 0, localZero = 0, claimed = 0, serverResults = 0 }
	S.backtrack = S.backtrack or { delayMs = 0, samples = 0, lastErr = 0 }
	-- \0..\3 are the camera-data slots; \4 \5 complete the 6-number compressed CFrame the game
	-- sends since the v5 update ({x, y, z, rx, ry, rz} in ToOrientation order)
	local KEY = { utf8.char(0), utf8.char(1), utf8.char(2), utf8.char(3), utf8.char(4), utf8.char(5) }
	Shots.keys = KEY

	function Shots.shortName(inst: any): string
		if typeof(inst) ~= "Instance" then
			return "nil"
		end
		local p = inst.Parent
		return (if p and p ~= workspace then p.Name .. "." else "") .. inst.Name
	end
	-- a shot left (camera data with no arguments = the payload Gun.StartShooting replicates)
	function Shots.claim(rec: any)
		Shots.n += 1
		rec.n = Shots.n
		rec.t = os.clock()
		rec.verdict = "…"
		table.insert(Shots.list, rec)
		if #Shots.list > Shots.max then
			table.remove(Shots.list, 1)
		end
		-- melee swings and projectile guns (Energy Pistols, Slingshot, launchers) never get a hitscan
		-- ShootEffect back: they are logged, never judged NO-REPLY or fed to the learners
		if rec.melee or rec.projectile then
			rec.done = true
			rec.verdict = if rec.melee then "SWING" else "PROJECTILE"
			rec.rttMs = 0
			Shots.stats.swing = (Shots.stats.swing or 0) + 1
			return rec
		end
		table.insert(Shots.pending, rec)
		if #Shots.pending > 12 then
			local old = table.remove(Shots.pending, 1)
			Shots.finish(old, "NO-REPLY", nil)
		end
		return rec
	end
	function Shots.finish(rec: any, verdict: string, detail: any)
		if rec.done then
			return
		end
		-- the target died on this round: whatever the ray's end point says (a sniper round goes through
		-- the head into the wall behind it), it landed
		if verdict ~= "HIT" and (rec.killShot or (rec.model ~= nil and S.killFeedSeen[rec.model])) then
			verdict, detail = "HIT", "kill"
		end
		rec.done = true
		rec.verdict = verdict
		rec.detail = detail
		rec.rttMs = math.floor((os.clock() - (rec.t or os.clock())) * 1000 + 0.5)
		local st = Shots.stats
		if verdict == "HIT" then
			st.hit += 1
		elseif verdict == "NEAR" then
			st.near += 1
		elseif verdict == "WALL" then
			st.wall += 1
		elseif verdict == "AIR" then
			st.air += 1
		elseif verdict == "NO-REPLY" then
			st.noReply += 1
		end
		if rec.unaimed then
			st.unaimed += 1
		end
		-- v5.0.3: a shot fired right after a hop teaches the SETTLE, not the fire rate — a NO-REPLY there
		-- is the server not having our position yet, and it used to slow rapid fire for nothing
		local postHop = type(rec.t) == "number" and (rec.t - (rec.hopAt or S.lastTeleportAt or 0)) <= (Combat.settleSec and Combat.settleSec() or 0.2) + 0.15
		if postHop and Combat.settleLearn then
			local okS, added = pcall(Combat.settleLearn, verdict, rec.t, rec.hopAt)
			rec.settleAdded = if okS and type(added) == "number" and added > 0 then added else false
		end
		-- adaptive rapid fire learns from every answered / unanswered gun shot
		if not rec.melee and not postHop and type(rec.weapon) == "string" and Combat.rapidLearn then
			local okL, errL = pcall(Combat.rapidLearn, rec.weapon, verdict, rec)
			if not okL then
				S.hookErr("rapid learn", errL) -- a broken learner used to stop learning silently
			end
		end
		-- the spread mode learns from claimed shots that left while the gun was not really aimed
		if rec.unaimed and not rec.melee and not postHop and type(rec.weapon) == "string" and Combat.spreadLearn then
			pcall(Combat.spreadLearn, rec.weapon, verdict)
		end
		-- v6.3 per-gun hit tracker (answered hitscan rounds only). v6.4: guided rounds only — a player's own
		-- misses with silent aim off flipped the gun's spread mode and cut its range for later
		if rec.pushed and Combat.wallPushLearn then
			pcall(Combat.wallPushLearn, verdict, rec.pushed)
		end
		if rec.spoofed and not rec.melee and not rec.projectile and verdict ~= "NO-REPLY" and type(rec.weapon) == "string" and Combat.gunTrack then
			pcall(Combat.gunTrack, rec.weapon, verdict == "HIT" or rec.killShot == true)
		end
		-- the lead bandit learns from spoofed shots at moving targets
		if rec.leadArm and rec.speed and Combat.leadLearn then
			local okL, errL = pcall(Combat.leadLearn, rec.leadArm, rec.speed, verdict)
			if not okL then
				S.hookErr("lead learn", errL)
			end
		end
		if cfg.shotsLog then
			-- a miss is telemetry, not a fault: INFO (WARN lines are forwarded to the site's Activity log)
			log("INFO", ("[shot:%s] %s · body %s"):format(verdict, Shots.line(rec), (S.body and S.body.owner) or "you"))
		end
		if cfg.shotsExport and Shots.n % 10 == 0 then
			task.defer(Shots.export)
		end
	end
	-- a kill registered on `model` (Combat.registerKill): the latest round at it that was judged a miss
	-- landed after all — it turns into a HIT and a settle it taught is taken back; rounds still waiting
	-- for their answer are judged HIT when it comes
	Shots.STAT_OF = { NEAR = "near", WALL = "wall", AIR = "air", ["NO-REPLY"] = "noReply" }
	function Shots.killed(model: Instance)
		local now = os.clock()
		local flipped = false
		for i = #Shots.list, math.max(1, #Shots.list - 12), -1 do
			local rec = Shots.list[i]
			if rec.model == model and now - (rec.t or 0) < 1.2 then
				if not rec.done then
					rec.killShot = true
				elseif not flipped and Shots.STAT_OF[rec.verdict] then
					flipped = true
					local st = Shots.stats
					local k = Shots.STAT_OF[rec.verdict]
					st[k] = math.max(0, (st[k] or 0) - 1)
					st.hit += 1
					log("DEBUG", ("[shot:kill] SHOT #%d judged %s — the target died on it"):format(rec.n or 0, rec.verdict))
					rec.verdict, rec.detail = "HIT", "kill"
					if rec.settleAdded then
						local ms = tonumber(rec.settleAdded) or 25
						rec.settleAdded = false
						Combat.settleUnlearn(ms)
						S.settleExtra = math.max(0, (S.settleExtra or 0) - ms)
					end
				end
			end
		end
	end
	function Shots.line(rec: any): string
		local parts = { ("SHOT #%d %s"):format(rec.n or 0, rec.verdict or "…") }
		if rec.weapon then
			table.insert(parts, rec.weapon)
		end
		if rec.target then
			table.insert(parts, "→ " .. tostring(rec.target) .. (if rec.part then "/" .. tostring(rec.part) else ""))
		end
		if rec.dist then
			table.insert(parts, ("%.0f st"):format(rec.dist))
		end
		if rec.spoofed then
			table.insert(parts, "silent")
		end
		if rec.unaimed then
			table.insert(parts, "UNAIMED")
		end
		if rec.backMs and rec.backMs > 0 then
			table.insert(parts, ("back %d ms"):format(rec.backMs))
		end
		if rec.speed and rec.speed > 3 then
			table.insert(parts, ("moving %.0f st/s%s"):format(rec.speed, if rec.leadMs and rec.leadMs > 0 then (" · lead %d ms"):format(rec.leadMs) else ""))
		end
		if rec.warp then
			table.insert(parts, ("backtracked %s st"):format(Game.studs(rec.warp)))
		end
		if type(rec.detail) == "string" then
			table.insert(parts, rec.detail)
		end
		if rec.rttMs then
			table.insert(parts, ("rtt %d ms"):format(rec.rttMs))
		end
		return table.concat(parts, " · ")
	end
	-- the enemy model a hitbox our round struck belongs to: never our own body, never a teammate's
	-- (players count only through the enemy list, which applies the team check); a hitbox off the list
	-- that belongs to no player is a range dummy / bot
	function Shots.enemyOf(inst: Instance): Instance?
		local char = LP.Character
		if char and inst:IsDescendantOf(char) then
			return nil
		end
		Game.enemies()
		local set = Game.enemyModelSet
		local cur: Instance? = inst.Parent
		local depth = 0
		while cur and (cur :: any) ~= workspace and depth < 8 do
			if set[cur] then
				return cur
			end
			cur = cur.Parent
			depth += 1
		end
		local m = inst.Parent
		if m and m:IsA("Model") and Players:GetPlayerFromCharacter(m) == nil then
			return m
		end
		return nil
	end
	-- server result for our gun: decode { [i] = { [\0]=Position, [\1]=Instance, [\2]=Normal } }
	function Shots.serverResult(results: any)
		local rec = table.remove(Shots.pending, 1)
		if type(results) ~= "table" then
			if rec then
				-- the record was already popped: close it instead of leaving it "…" forever
				Shots.finish(rec, "NO-REPLY", "bad ShootEffect payload")
			end
			return
		end
		local hits = {}
		for _, r in pairs(results) do
			if type(r) == "table" then
				table.insert(hits, { pos = r[KEY[1]], inst = r[KEY[2]] })
			end
		end
		-- v6.4.1 hit feedback for every round of ours, silent aim or not: a server hit on an enemy hitbox drives
		-- the hit marker, damage numbers, kill feed and kill effect (they only ever knew guided rounds)
		local bq = cfg.hitBlood and S.vis and S.vis.bloodQueue
		local hitEnemy, hitEnemyPos, hitEnemyInst = nil, nil, nil
		for _, hres in ipairs(hits) do
			local inst = hres.inst
			if typeof(inst) == "Instance" and string.sub(inst.Name, 1, 6) == "Hitbox" and inst.Parent ~= nil then
				S.serverHitModel, S.serverHitAt = inst.Parent, os.clock()
				S.hitMarkerAt = os.clock()
				if bq and #bq < 12 and typeof(hres.pos) == "Vector3" then
					table.insert(bq, hres.pos)
				end
				local enemy = Shots.enemyOf(inst)
				if enemy and (not hitEnemy or (enemy == hitEnemy and string.find(string.lower(inst.Name), "head", 1, true))) then
					-- a head pellet names the hit for the whole ShootEffect
					hitEnemy, hitEnemyInst = enemy, inst
					hitEnemyPos = if typeof(hres.pos) == "Vector3" then hres.pos else nil
				end
			end
		end
		-- one hit event per ShootEffect (a shotgun's pellets are one hit), never on a body that already died
		if hitEnemy and not S.killFeedSeen[hitEnemy] then
			S.lastHitModel, S.lastHitAt = hitEnemy, os.clock()
			S.lastHitPos = hitEnemyPos or S.lastHitPos
			local onHit = S.ext and S.ext.onHit
			if onHit then
				pcall(onHit, hitEnemy, hitEnemyInst, hitEnemyPos)
			end
		end
		-- bullet tracers (World → Effects) draw from here: the server's own end points
		local fxq = cfg.shotTracers and S.vis and S.vis.shotQueue
		if fxq and #fxq < 32 then
			local head = S.myHeadPart
			local from = (rec and rec.origin) or (if head and head.Parent then head.Position else nil)
			if from then
				for _, hres in ipairs(hits) do
					if typeof(hres.pos) == "Vector3" then
						table.insert(fxq, { from, hres.pos })
					end
				end
			end
		end
		if not rec then
			return
		end
		rec.server = hits
		local model = rec.model
		local claim: Vector3? = rec.aim
		local hitModel = false
		local hitPos: Vector3? = nil
		local hitInst: Instance? = nil
		local nearest, nearestInst, nearestPos = math.huge, nil, nil
		local partInst = rec.partInst
		for _, hres in ipairs(hits) do
			local inst = hres.inst
			if typeof(inst) == "Instance" and typeof(model) == "Instance" and Game.isShieldPart(inst, model) and inst:IsDescendantOf(model) then
				-- a riot shield ate the round (stowed on the back it absorbs from behind)
				rec.shield = inst.Name
				log("WARN", ("[shield:blocked:%s] %s · %s · %.0f st · body %s"):format(inst.Name, tostring(rec.target), tostring(rec.weapon), rec.dist or 0, Combat.body.owner or "you"))
			elseif typeof(inst) == "Instance" and model and (inst == model or inst:IsDescendantOf(model)) then
				hitModel = true
				if typeof(hres.pos) == "Vector3" then
					hitPos, hitInst = hres.pos, inst
				end
			elseif typeof(inst) == "Instance" and typeof(partInst) == "Instance" and (inst == partInst or (partInst.Parent ~= nil and inst.Parent == partInst.Parent)) then
				hitModel = true -- range dummies: the part's model is not the wrapper's Entity.Model
				if typeof(hres.pos) == "Vector3" then
					hitPos, hitInst = hres.pos, inst
				end
			elseif typeof(inst) == "Instance" and rec.part ~= nil and inst.Name == rec.part and typeof(hres.pos) == "Vector3" and claim and (hres.pos - claim).Magnitude < 2.5 then
				hitModel = true -- the server's own replica of the very part we aimed at, at the aim point
				hitPos, hitInst = hres.pos, inst
			end
			if typeof(hres.pos) == "Vector3" and claim then
				local d = (hres.pos - claim).Magnitude
				if d < nearest then
					nearest = d
					nearestInst = inst
					nearestPos = hres.pos
				end
			end
		end
		if hitModel then
			if typeof(model) == "Instance" and hitPos then
				Resolver.confirmed[model] = { pos = hitPos, at = os.clock(), part = hitInst }
			end
			Shots.finish(rec, "HIT", nil)
		elseif nearest < math.huge then
			local detail = ("off %.2f st%s"):format(nearest, if typeof(nearestInst) == "Instance" then " → " .. Shots.shortName(nearestInst) else "")
			Shots.finish(rec, if nearest < 4 then "NEAR" elseif typeof(nearestInst) == "Instance" then "WALL" else "AIR", detail)
		else
			Shots.finish(rec, "AIR", "no server position")
		end
		-- backtrack learning (display only — layer 0 aims at the live part): where in the target's
		-- history did the server's ray end up? `measured` counts real measurements; a HIT only decays
		-- the estimate toward 0 (the aim that landed needed no rewind)
		if model and claim and cfg.backtrackMode == "Auto" and nearest < 12 and not hitModel and nearestPos then
			local delay, err = Track.bestDelay(model, rec.which or "head", rec.t, nearestPos)
			if delay and err and err < 3 then
				local bt = S.backtrack
				bt.samples += 1
				bt.measured = (bt.measured or 0) + 1
				bt.lastErr = err
				bt.delayMs = if bt.measured == 1 then delay * 1000 else bt.delayMs * 0.7 + delay * 1000 * 0.3
				bt.delayMs = math.clamp(bt.delayMs, 0, 400)
			end
		elseif hitModel and cfg.backtrackMode == "Auto" then
			local bt = S.backtrack
			bt.samples += 1
			bt.delayMs = bt.delayMs * 0.9
		end
	end
	-- the learned rewind (Auto) for the Debug tab. Layer 0 never applies it: the server resolves
	-- the hit on its own part position, so a rewound aim lands short — the retired Manual mode did
	-- exactly that to every shot.
	function Shots.backtrackSec(): number
		if cfg.backtrackMode == "Auto" then
			local bt = S.backtrack
			return if (bt.measured or 0) >= 2 then bt.delayMs / 1000 else 0
		end
		return 0
	end
	function Shots.tick()
		-- claims the server never answered
		local now = os.clock()
		local guard = 0
		while #Shots.pending > 0 and now - Shots.pending[1].t > 1.5 and guard < 16 do
			guard += 1
			local rec = table.remove(Shots.pending, 1)
			-- v5.0.5: rounds that left in the kill window (the target died before the server could answer)
			-- are not server drops — the duel trace showed 4–5 of them after every kill, and each one
			-- taught the rapid-fire learner to slow the gun down
			local model = rec.model
			local dead = false
			if typeof(model) == "Instance" then
				if model.Parent == nil then
					dead = true
				else
					local hum = model:FindFirstChildOfClass("Humanoid")
					dead = hum ~= nil and hum.Health <= 0
				end
			end
			if dead then
				rec.melee = true -- SWING-class: no learner input, not a NO-REPLY in the stats
				Shots.finish(rec, "KILL", "target died before the answer")
				-- the kill list / kill effect when the faster check in Combat.updateKills missed it
				if typeof(model) == "Instance" then
					Combat.registerKill(model, tostring(rec.target or model.Name), rec.aim)
				end
			else
				Shots.finish(rec, "NO-REPLY", "no ShootEffect in 1.5 s")
			end
		end
	end
	function Shots.summary(): any
		local st = Shots.stats
		local total = st.hit + st.near + st.wall + st.air + st.noReply
		local last = {}
		for i = math.max(1, #Shots.list - 9), #Shots.list do
			table.insert(last, Shots.line(Shots.list[i]))
		end
		return {
			total = total,
			hit = st.hit,
			near = st.near,
			wall = st.wall,
			air = st.air,
			noReply = st.noReply,
			unaimed = st.unaimed,
			immune = st.immune or 0,
			hitRate = if total > 0 then math.floor(st.hit / total * 100 + 0.5) else nil,
			backtrackMs = math.floor(S.backtrack.delayMs + 0.5),
			backtrackSamples = S.backtrack.samples,
			last = last,
		}
	end
	-- the server's verdicts (Shots.serverResult / Shots.tick) since `base` (an earlier roundCounts(); the
	-- totals when nil): the numbers the round summary prints — never the client redirect counters
	function Shots.roundCounts(base: any?): any
		local st = Shots.stats
		local b = base or {}
		return { hit = st.hit - (b.hit or 0), wall = st.wall - (b.wall or 0), air = st.air - (b.air or 0), near = st.near - (b.near or 0), noReply = st.noReply - (b.noReply or 0) }
	end
	function Shots.reset()
		table.clear(Shots.list)
		table.clear(Shots.pending)
		for k in pairs(Shots.stats) do
			Shots.stats[k] = 0
		end
		Shots.n = 0
		S.backtrack = { delayMs = 0, samples = 0, lastErr = 0 }
	end
	function Shots.export()
		if not (EXEC.writefile and cfg.shotsExport) then
			return
		end
		local rows = {}
		for _, rec in ipairs(Shots.list) do
			table.insert(rows, {
				n = rec.n,
				verdict = rec.verdict,
				weapon = rec.weapon,
				target = rec.target,
				part = rec.part,
				dist = rec.dist,
				spoofed = rec.spoofed,
				unaimed = rec.unaimed,
				backMs = rec.backMs,
				detail = rec.detail,
				rttMs = rec.rttMs,
				aim = rec.aim and { rec.aim.X, rec.aim.Y, rec.aim.Z } or nil,
				origin = rec.origin and { rec.origin.X, rec.origin.Y, rec.origin.Z } or nil,
				server = rec.server and (function()
					local out = {}
					for _, hres in ipairs(rec.server) do
						table.insert(out, { pos = hres.pos and { hres.pos.X, hres.pos.Y, hres.pos.Z } or nil, inst = Shots.shortName(hres.inst) })
					end
					return out
				end)() or nil,
			})
		end
		pcall(function()
			EXEC.mkdirs(DATA.dir)
			EXEC.writefile(DATA.shots, HttpService:JSONEncode({ at = os.time(), version = VERSION, executor = EXECUTOR_NAME, summary = Shots.summary(), shots = rows }))
		end)
	end

	-----------------------------------------------------------------------------
	-- §7c net — unsafe mode (Volt RakNet). Everything here is bannable by design and gated behind
	-- cfg.unsafeMode + cfg.unsafeAccepted. Only the character physics packet is ever touched: it is
	-- learned at runtime as the busiest unreliable-sequenced packet id (0xA1 on the current client),
	-- reliable game data (0x83: remotes, shots, properties) is never blocked or delayed.
	-----------------------------------------------------------------------------
	local Net: any = { installed = false, physId = nil, counts = {}, window = {}, windowAt = os.clock(), sent = 0, blocked = 0, delayed = 0, rate = 0, physRate = 0, err = 0, sendFail = 0, blockRun = 0, enabledNow = false, enabledAt = 0 }
	S.net = Net
	Net.available = EXEC.caps.raknet
	Net.RELIABLE_GAME_DATA = 0x83 -- remotes, shots, properties: never elected, never touched
	Net.MAX_BLOCK_RUN = 40 -- consecutive physics packets a choke may hold before one is forced through
	function Net.enabled(): boolean
		if not Net.available then
			return false
		end
		-- polled once every 250 ms: the hook asked is_enabled() (a pcall + closure) on every packet
		local now = os.clock()
		if now - Net.enabledAt > 0.25 then
			Net.enabledAt = now
			local ok, en = pcall(EXEC.raknet.is_enabled)
			Net.enabledNow = ok and en == true
		end
		return Net.enabledNow
	end
	function Net.active(): boolean
		local st = S.cfg -- hooks read the live config through the state, never a captured cfg
		return S.alive and st.unsafeMode == true and st.unsafeAccepted == true and Net.enabled()
	end
	-- choke schedule for fake lag: true while our physics packets must be held. The choke is
	-- always shorter than half the period — the sliders allowed choke ≥ every, which held EVERY
	-- packet for as long as fake lag was armed (frozen on the server)
	function Net.choking(): boolean
		local st = S.cfg
		if not st.unsafeFakeLag then
			return false
		end
		if st.unsafeFakeLagOnlyWhenTargeted and not (S.threatOnMe or S.silentTarget ~= nil or S.firing) then
			return false
		end
		local every = math.max(st.unsafeFakeLagEveryMs / 1000, 0.05)
		local choke = math.min(st.unsafeFakeLagChokeMs / 1000, every * 0.5)
		return (os.clock() % every) < choke
	end
	function Net.onPacket(packet: any)
		local id = packet.PacketId
		Net.sent += 1
		local c = Net.counts[id]
		if not c then
			c = { n = 0, rel = packet.Reliability, size = packet.Size }
			Net.counts[id] = c
		end
		c.n += 1
		c.size = packet.Size
		-- learn the physics id: unreliable-sequenced (reliability 5), busiest of its kind, never
		-- the reliable game-data id
		if packet.Reliability == 5 and id ~= Net.RELIABLE_GAME_DATA then
			local w = Net.window
			w[id] = (w[id] or 0) + 1
		end
		if not Net.active() or S.menuOpen then
			return
		end
		if id ~= Net.physId or id == Net.RELIABLE_GAME_DATA then
			return
		end
		local st = S.cfg
		if Net.choking() and Net.blockRun < Net.MAX_BLOCK_RUN then
			packet:Block()
			Net.blocked += 1
			Net.blockRun += 1
			return
		end
		Net.blockRun = 0
		if st.unsafePingBoost and Net.sendFail < 3 then
			-- hold the packet and send the same bytes later: the server learns our position late
			local bytes = packet.AsString
			local prio, rel, ch = packet.Priority, packet.Reliability, packet.OrderingChannel
			if type(bytes) ~= "string" or #bytes == 0 then
				return -- nothing we could re-send: let it through untouched
			end
			packet:Block()
			Net.delayed += 1
			-- always re-sent (even after unload): a held position packet that never leaves would
			-- freeze us on the server for good — and a failing send is counted and, after three,
			-- turns the boost off instead of silently eating position packets
			task.delay(st.unsafePingBoostMs / 1000, function()
				local okS, errS = pcall(EXEC.raknet.send, bytes, prio, rel, ch)
				if not okS then
					Net.sendFail += 1
					task.defer(log, "WARN", "net: raknet.send failed:", errS)
					if Net.sendFail >= 3 then
						local live = genv().CenterraState
						if live and live.cfg then
							live.cfg.unsafePingBoost = false
						end
						task.defer(log, "ERROR", "net: ping boost disabled — three re-sends failed (the server would have frozen us)")
					end
				end
			end)
		end
	end
	function Net.install()
		if Net.installed or not Net.available then
			return
		end
		local g = genv()
		if type(g.CenterraNetHook) == "function" then
			-- two live hooks would Block() the same packet and each re-send it: refuse to stack
			local okR = pcall(EXEC.raknet.remove_send_hook, g.CenterraNetHook)
			if not okR then
				log("WARN", "net: could not remove the previous send hook — not installing a second one")
				return
			end
			g.CenterraNetHook = nil
		end
		local fn = function(packet)
			local ok, err = pcall(Net.onPacket, packet)
			if not ok then
				Net.err += 1
				if Net.err <= 3 then
					task.defer(log, "WARN", "net hook:", err)
				end
			end
		end
		local ok, err = pcall(EXEC.raknet.add_send_hook, fn)
		if ok then
			g.CenterraNetHook = fn
			Net.installed = true
			log("INFO", "net: RakNet send hook installed (unsafe mode " .. (if cfg.unsafeMode then "ON" else "off") .. ")")
		else
			log("WARN", "net: add_send_hook failed:", err)
		end
	end
	function Net.uninstall()
		local g = genv()
		if type(g.CenterraNetHook) == "function" and Net.available then
			pcall(EXEC.raknet.remove_send_hook, g.CenterraNetHook)
		end
		g.CenterraNetHook = nil
		Net.installed = false
	end
	-- once a second: packet rates, physics id election
	function Net.tick()
		local now = os.clock()
		if now - Net.windowAt < 1 then
			return
		end
		local dt = math.max(now - Net.windowAt, 1e-3)
		Net.windowAt = now
		Net.rate = Net.sent / dt
		Net.sent = 0
		local bestId, bestN = nil, 0
		for id, n in pairs(Net.window) do
			if n > bestN and id ~= Net.RELIABLE_GAME_DATA then
				bestId, bestN = id, n
			end
		end
		-- a physics stream runs at ≥ 15 packets/s; a 4 Hz keepalive used to win the election in the
		-- lobby. An id whose rate collapses loses the election again instead of staying elected.
		local rate = bestN / dt
		if bestId and rate >= 15 then
			Net.physId = bestId
			Net.physRate = rate
		elseif Net.physId ~= nil and (Net.window[Net.physId] or 0) / dt < 5 then
			Net.physId = nil
			Net.physRate = 0
		end
		table.clear(Net.window)
		if cfg.unsafeMode and cfg.unsafeAccepted and not Net.installed and Net.available then
			Net.install()
		end
	end
	function Net.summary(): any
		return {
			available = Net.available,
			raknetEnabled = Net.enabled(),
			active = Net.active(),
			installed = Net.installed,
			physId = Net.physId,
			physRate = math.floor(Net.physRate + 0.5),
			rate = math.floor(Net.rate + 0.5),
			blocked = Net.blocked,
			delayed = Net.delayed,
			choking = Net.active() and Net.choking(),
			errors = Net.err,
		}
	end

	-----------------------------------------------------------------------------
	-- §8 hooks — installed once per Lua state (hookfunction can't be undone), versioned through
	-- S.hooks.v; every closure reads live logic from S.h so a reinject refreshes behaviour
	-----------------------------------------------------------------------------
	local Hooks: any = {}
	-- a pass-through "original" for a hook that could not be installed: the closure must never be
	-- handed `target` itself (a live detour calling target == itself recursed forever)
	function Hooks.passThrough(...: any): ...any
		return ...
	end
	-- hook `target` once per Lua state. Returns (original, ok). `S.hookedFns` remembers every
	-- function object ever hooked here (it lives on the reused state), and isfunctionhooked is
	-- consulted where the executor has it — so a re-inject, a retry loop or the integrity check can
	-- never stack a second detour on the same function.
	local function hook(target: any, fn: any): (any, boolean)
		if type(target) ~= "function" or type(EXEC.hookfunction) ~= "function" then
			return target, false
		end
		if S.hookedFns[target] then
			return Hooks.passThrough, false -- normal on a retry / re-inject: the earlier detour is live
		end
		if type(EXEC.isfunctionhooked) == "function" then
			local okH, hooked = pcall(EXEC.isfunctionhooked, target)
			if okH and hooked == true then
				-- not ours (S.hookedFns has every detour this state made): an orphan of an abandoned state
				-- (its closure reads a dead table, so the layer answers nothing) or another script's.
				-- Give the game its function back and hook it fresh; skipping left camera / rotation /
				-- camera data / _CreateViewModel dead until the next server (6.6.1 self-test 16/20)
				local okR = type(EXEC.restorefunction) == "function" and pcall(EXEC.restorefunction, target)
				local okH2, still = pcall(EXEC.isfunctionhooked, target)
				if not okR or (okH2 and still == true) then
					log("DEBUG", "hook: function already carries a detour — skipped")
					S.hookedFns[target] = true
					return Hooks.passThrough, false
				end
				log("INFO", "hook: a foreign detour was restored before hooking")
			end
		end
		local function once(f: any): any
			local ok, old = pcall(EXEC.hookfunction, target, f)
			if ok and type(old) == "function" then
				return old
			end
			return nil
		end
		-- Volt already wraps. Other executors often crash or reject a raw Lua hook, and these
		-- game methods do not yield, so a C closure is safe here (namecall is handled apart).
		if not EXEC.isVolt and type(EXEC.newcclosure) == "function" then
			local okW, wrapped = pcall(EXEC.newcclosure, fn)
			if okW and type(wrapped) == "function" then
				local old = once(wrapped)
				if old then
					S.hookedFns[target] = true
					return old, true
				end
			end
		end
		local old = once(fn)
		if old then
			S.hookedFns[target] = true
			return old, true
		end
		log("WARN", "hook skipped")
		return Hooks.passThrough, false
	end
	-- run `fn` for a hook body; on error report once (rate-limited) and fall back to `fallback`
	function Hooks.guarded(source: string, fallback: any, fn: any, ...: any): any
		local ok, out = pcall(fn, ...)
		if ok then
			return out
		end
		if S.hookErr then
			S.hookErr(source, out)
		end
		return fallback
	end
	-- find a method through a class table's __index chain (RIVALS classes inherit a shared base)
	local function classMethod(cls: any, name: string): any
		local t = cls
		local depth = 0
		while type(t) == "table" and depth < 6 do
			local v = rawget(t, name)
			if type(v) == "function" then
				return v
			end
			local mt = getmetatable(t)
			t = mt and mt.__index
			depth += 1
		end
		return nil
	end

	-- live logic --------------------------------------------------------------
	local h = S.h
	h.pdc = PlayerDataController
	h.cosmetics = CosmeticLibrary.Cosmetics
	h.equipRemote = Game.remote("Data", "EquipCosmetic")
	-- the unreliable remote the game replicates our camera rotation through (Replication.Fighter)
	-- resolved now and re-resolved from the loop while nil (the remote can appear after a hop; a
	-- one-shot lookup silently disabled the whole rotation channel for the session)
	h.resolveRotRemote = function(): Instance?
		local rem = ReplicatedStorage:FindFirstChild("Remotes")
		local rep = rem and rem:FindFirstChild("Replication")
		local fi = rep and rep:FindFirstChild("Fighter")
		local r = fi and fi:FindFirstChild("UpdateCameraRotation")
		if r then
			return r
		end
		-- v5.2: folder moved by an update → by name anywhere under Remotes (must still be a remote event)
		r = Game.adapt.findRemote("UpdateCameraRotation", "UnreliableRemoteEvent") or Game.adapt.findRemote("UpdateCameraRotation", "RemoteEvent")
		if r then
			task.defer(log, "WARN", "adapt: UpdateCameraRotation found at " .. r:GetFullName() .. " (not under Replication/Fighter any more)")
		end
		return r
	end
	h.rotRemote = h.resolveRotRemote()
	if not h.rotRemote then
		log("WARN", "UpdateCameraRotation remote not found yet — rotation channel retried from the loop")
	end
	-- v5: the remote the client reports its own out-of-bounds death through (swallowed while
	-- cfg.oobBlock — see Hooks.installOob; compared by identity inside the namecall hook)
	h.resolveOobRemote = function(): Instance?
		local rem = ReplicatedStorage:FindFirstChild("Remotes")
		local rep = rem and rem:FindFirstChild("Replication")
		local fi = rep and rep:FindFirstChild("Fighter")
		local r = fi and fi:FindFirstChild("OutOfBounds")
		if r then
			return r
		end
		return Game.adapt.findRemote("OutOfBounds", "RemoteEvent")
	end
	h.oobRemote = h.resolveOobRemote()
	-- the remote FighterController._ReplicateControls reports the device through (the device spoof
	-- rewrites its argument; compared by identity inside the namecall hook)
	h.resolveControlsRemote = function(): Instance?
		local rem = ReplicatedStorage:FindFirstChild("Remotes")
		local rep = rem and rem:FindFirstChild("Replication")
		local fi = rep and rep:FindFirstChild("Fighter")
		local r = fi and fi:FindFirstChild("SetControls")
		if r then
			return r
		end
		return Game.adapt.findRemote("SetControls", "RemoteEvent")
	end
	h.magicFilter = {} -- one-slot Include list reused by the pooled magic redirect params
	-- wire format of UpdateCameraRotation: utf8.char(q(pitch), q(yaw)), q = angle mod 2π in 256 steps
	-- (verified: the server echoes code × 2π/256 in Fighter.Data.CameraRotation). Pure math — safe
	-- inside the namecall hook.
	h.encodeRot = function(rot: Vector2): string?
		if typeof(rot) ~= "Vector2" then
			return nil
		end
		local function q(a: number): number
			if a ~= a then
				return 0
			end
			return math.floor(((a % (2 * math.pi)) / (2 * math.pi)) * 256 + 0.5) % 256
		end
		return utf8.char(q(rot.X), q(rot.Y))
	end
	-- the payload the game is about to send → the payload it should send (nil = leave it)
	h.replicatedPayload = function(): string?
		local C = S.combat
		if not (S.alive and S.cfg.aaReplicate) or S.menuOpen then
			if C and C.noteSent then
				C.noteSent(Vector2.zero, false) -- the game's own angle replaces a lock-facing one
			end
			return nil
		end
		local real = CameraController and CameraController.Rotation
		if typeof(real) ~= "Vector2" then
			return nil
		end
		local fake = h.rot(real, "replicate")
		if typeof(fake) ~= "Vector2" or fake == real then
			if C and C.noteSent then
				C.noteSent(real, false)
			end
			return nil
		end
		if C and C.noteSent then
			C.noteSent(fake, h.lockFacingNow())
		end
		return h.encodeRot(fake)
	end
	-- a hit of ours the server registered as immune (spawn protection) — awareness + stats
	h.immuneHit = function()
		S.shotStats.immune = (S.shotStats.immune or 0) + 1
		S.lastImmuneAt = os.clock()
		if S.shots and S.shots.stats then
			S.shots.stats.immune = (S.shots.stats.immune or 0) + 1
		end
		if os.clock() - (S.lastImmuneLogAt or 0) > 1 then
			S.lastImmuneLogAt = os.clock()
			task.defer(log, "INFO", "shot registered as IMMUNE — target is spawn-protected; fire held while it stays invincible")
		end
	end
	h.shotCallers = if type(cfg.shotCallers) == "table" and next(cfg.shotCallers) ~= nil then cfg.shotCallers else { MechanicsController = true, Gun = true, Item = true }
	-- v5.2: shot-code script names learned live — every no-argument GetCameraData() on the local
	-- fighter IS the shot payload (that is how the game builds a shot), so whoever calls it is shot code
	-- by definition. A RIVALS update that renames MechanicsController / Gun / Item no longer blinds the
	-- silent layers: the names are picked up from the first real shot. Carried across re-injects.
	S.learnedShotCallers = S.learnedShotCallers or {}
	S.learnedShotCallersN = S.learnedShotCallersN or 0
	h.learnShotCaller = function()
		if type(EXEC.getcallingscript) ~= "function" or S.learnedShotCallersN >= 8 then
			return
		end
		local ok, scr = pcall(EXEC.getcallingscript)
		if ok and typeof(scr) == "Instance" then
			local nm = scr.Name
			if S.learnedShotCallers[nm] == nil and h.shotCallers[nm] ~= true then
				S.learnedShotCallers[nm] = true
				S.learnedShotCallersN += 1
				task.defer(log, "INFO", ("adapt: shot code also runs in %s — silent layers now trust it"):format(nm))
			end
		end
	end

	h.callerIsShotCode = function(): boolean
		-- a shot we triggered ourselves (game input / StartShooting) runs the game's shot code in OUR
		-- thread: getcallingscript() is nil there, so the layers must trust the trigger window instead
		if S.ourShotUntil and os.clock() < S.ourShotUntil then
			return true
		end
		if type(EXEC.getcallingscript) ~= "function" then
			-- no caller oracle (some executors): only while a shot can actually leave — it used to say
			-- yes to every long cast, so slides / reach probes / tracers were all "shots"
			return S.lmbDown == true or S.autoEngaged == true
		end
		local ok, scr = pcall(EXEC.getcallingscript)
		if not (ok and scr ~= nil) then
			return false
		end
		local nm = scr.Name
		return h.shotCallers[nm] == true or S.learnedShotCallers[nm] == true
	end
	h.callerName = function(): string
		if type(EXEC.getcallingscript) ~= "function" then
			return ""
		end
		local ok, scr = pcall(EXEC.getcallingscript)
		return if ok and scr then scr.Name else ""
	end

	-- the silent target when a redirect is allowed right now (nil otherwise)
	h.silentWanted = function(): Vector3?
		local st = S.cfg
		local override = S.cfgOverrideSilent == true
		if not S.alive or S.calibrating then
			return nil
		end
		-- the menu and the lobby gate stand the layers down, except for an armed override: the self-test's
		-- fake lock runs from Debug → Live (menu open) and in the hub
		if not override and (S.menuOpen or (S.featuresPaused and not S.gateOverride)) then
			return nil
		end
		if not (st.silentAim or override) then
			return nil
		end
		-- v6.3: a utility in hand (Jump Pad, tripmine, grenade…) or a quick utility / quick melee in
		-- progress: the placement / throw goes where YOU aim (the tester's jump pads were redirected at
		-- the enemy). S.silentSuspended is computed in the loop (Combat.updateSuspend).
		if S.silentSuspended and not override then
			return nil
		end
		-- "only while firing" keeps the lock hot for a moment after the last trigger pull: the game
		-- replicates the shot (and our spoofed rotation) a tick later — a tap that ends before that
		-- tick would hand the server the real rotation and the hit gets thrown away
		if st.silentOnlyFiring and not S.firing and not override and os.clock() > (S.spoofUntil or 0) then
			return nil
		end
		-- v6.1: the live part is out of the server's reach but a ShootEffect confirmed where it really
		-- was a moment ago (Combat.updateLock picks it): aim there, while it still belongs to this lock
		local ap = S.silentAimPoint
		if ap ~= nil and S.silentTarget ~= nil and S.silentAimModel ~= nil and S.silentAimModel == S.silentTargetModel then
			return ap
		end
		-- read the locked part *at shot time*: a per-frame position is already up to a frame stale,
		-- and a head is only one stud tall
		local part = S.silentPart
		if S.silentTarget ~= nil and typeof(part) == "Instance" and part.Parent then
			-- a projectile round flies: aim where the target will be when it arrives (hitscan stays live)
			-- semi-legit: the point of the box that sits inside the circle (Combat.updateLock), on the live part
			local lp = S.silentLocal
			local at = if typeof(lp) == "Vector3" and S.silentLocalPart == part then part.CFrame:PointToWorldSpace(lp) else part.Position
			-- the game's input can run before this frame's warp step put a flickering model back
			at = S.resolver.fixPos(part, at)
			local c = S.combat
			if c and type(c.projectileFlight) == "function" and c.projectileFlight(part) then
				return c.ledAim(part, at)
			end
			return at
		end
		return S.silentTarget
	end
	-- the claim (spoofed camera data) goes out only once the server holds the lock-facing rotation: the
	-- round follows the STORED rotation, so a claim along another one is an AIR 400 st away
	h.claimReady = function(): boolean
		local f = S.silentFighter
		if f ~= nil and S.syncDoneFor == f then
			return true
		end
		local c = S.combat
		return c ~= nil and type(c.echoAligned) == "function" and c.echoAligned() == true
	end
	-- A shot the player fires is fired either way: refusing to redirect it only turns a possible hit
	-- into a certain miss (that was the "magic misses 99%" — every ray inside the settle window went
	-- straight ahead from above the target). The settle gate therefore only delays *our* trigger
	-- (auto shoot / autokill wait in the loop); the layers always aim what leaves the barrel.
	h.gateOk = function(): boolean
		local st = S.cfg
		if st.silentSettleGateShots then
			local settle = if type(S.settleSec) == "function" then S.settleSec() else st.silentSettleMs / 1000
			if os.clock() - (S.lastTeleportAt or 0) < settle then
				return false
			end
		end
		return true
	end
	-- where the shot must start while the rendered camera is not at the head: the body sits somewhere
	-- else (magic / invisible autokill) or the camera hangs behind us (third person). The real head,
	-- never the pinned or third-person view. nil = leave the game's origin alone.
	-- (property reads only — no method calls before oldNc inside the namecall hook)
	h.shotOrigin = function(): Vector3?
		if not (S.teleported or S.tpActive) then
			return nil
		end
		local head = S.myHeadPart
		if head and head.Parent then
			return head.Position + Vector3.new(0, 0.3, 0)
		end
		return nil
	end
	-- third person: the game's cast can leave from the camera behind our back, where it stopped on
	-- Extra.Part. The same far point, cast from the live head instead; nil = the origin is the head.
	h.headRay = function(origin: Vector3, dir: Vector3, params: any): (Vector3?, any, Vector3?, boolean?)
		if not S.tpActive then
			return nil, nil, nil, nil
		end
		local head = h.shotOrigin()
		if not head or (head - origin).Magnitude <= 3 then
			return nil, nil, nil, nil
		end
		local nd = (origin + dir) - head
		local m = nd.Magnitude
		if m < 1 then
			return nil, nil, nil, nil
		end
		return nd * (dir.Magnitude / m), params, head, true
	end
	local function usable(target: Vector3, from: Vector3): boolean
		local d = target - from
		local m = d.Magnitude
		return m == m and m > 0.25 and m < 1e5
	end
	-- where the server casts the next round from: the claimed wallbang / under-floor push when this lock has
	-- one (h.cameraData sends it as [\0]), else the camera anchor. The stream, the echo gate and the payload
	-- aim from this one point — a floor push straight down with the stream aimed from the head missed any
	-- buried target that was not directly below
	h.lockOrigin = function(): Vector3?
		local wpo = S.wallPushOrigin
		if wpo ~= nil and S.wallPushModel ~= nil and S.wallPushModel == S.silentTargetModel and (S.teleported ~= true or S.wallPushUnder) then
			return wpo
		end
		return Game.shotOriginPos()
	end

	-- v5: should the replicated rotation face the locked target right now? The shot itself always does
	-- (the server fires along it) — the 150 ms pulse window, a held mouse, autokill firing. Flick mode
	-- (aaFlick) keeps the fake anti-aim angle between shots: the only pre-shot exposure is the sync wait
	-- itself (the trigger wants to fire and the echo is not there yet). Without flick the target-facing
	-- rotation is held for the whole engagement (echo aligns early → first shot lands with no wait), at
	-- the cost of the real angle being visible while engaged.
	h.faceTarget = function(): boolean
		local st = S.cfg
		-- autokill faces the head for its whole orbit (its first round waits for this rotation's echo)
		local akv = S.autokill
		if S.lmbDown == true or os.clock() < (S.ourShotUntil or 0) or (akv and (akv.firing == true or (akv.state == "orbit" and not akv.hiding))) then
			return true
		end
		-- v6.1.7: the last stretch of a hide / breaker hop before the fire window: the body lands facing
		-- the lock, so Combat.syncReady has nothing to wait for
		if S.preFace == true then
			return true
		end
		if st.aaFlick and st.aaEnabled then
			-- the fake angle only between shots: the last echo trip before the gun can fire already faces
			-- the lock, so the re-sync is done by the time the round can leave
			return S.autoEngaged == true and (S.syncWaiting == true or (S.gunReadyIn or math.huge) <= (S.echoLeadNow or 0.3) * 1.3)
		end
		-- the grace window keeps the channel on the target across brief holds between shots (kill
		-- confirm, a frame of blocked head): the server keeps our rotation, the next pull needs no re-sync
		if S.engagedUntil and os.clock() < S.engagedUntil and S.silentTarget ~= nil then
			return true
		end
		return S.autoEngaged == true or S.preAiming == true
	end
	-- is the rotation h.rot hands out right now the lock-facing one (Combat.noteSent)?
	h.lockFacingNow = function(): boolean
		return S.cfg.silentSpoofServer == true and h.silentWanted() ~= nil and h.faceTarget()
	end
	-- v6.3 "Silent hit chance": one roll per shot (every layer of the same shot reads it within 60 ms);
	-- an unguided shot goes exactly where the player aims. math.random only — safe inside the hook.
	h.guideAt, h.guideRoll = 0, true
	h.shotGuided = function(): boolean
		local c = S.cfg.silentHitChance or 100
		if c >= 100 or S.cfgOverrideSilent == true then
			return true
		end
		local now = os.clock()
		if now - h.guideAt > 0.06 then
			h.guideAt = now
			h.guideRoll = math.random(1, 100) <= c
		end
		return h.guideRoll == true
	end
	-- layer 1: the shot code asks CameraController for its CFrame right before it raycasts
	h.camCF = function(cf: CFrame): CFrame
		local target = h.silentWanted()
		if target and h.callerIsShotCode() and not h.shotGuided() then
			target = nil
		end
		local override = S.cfgOverrideSilent == true
		-- an armed override (the self-test probe) is not a shot after a hop: the settle gate stays out of it
		if target and (S.firing or override) and h.callerIsShotCode() and (override or h.gateOk()) then
			local from = h.shotOrigin() or cf.Position
			if usable(target, from) then
				return CFrame.lookAt(from, target)
			end
		end
		return cf
	end
	-- layer 2: the shot code asks the fighter where the mouse is
	h.mouse = function(): Vector2?
		local target = h.silentWanted()
		if target and h.callerIsShotCode() and h.gateOk() and h.shotGuided() then
			local cam = workspace.CurrentCamera
			if cam then
				local v, on = cam:WorldToViewportPoint(target)
				if on then
					return Vector2.new(v.X, v.Y)
				end
			end
		end
		return nil
	end
	-- the rotation we want the server (and other clients) to see for `orig`, the real one: the lock
	-- while a shot can leave, then anti-aim. Consumers: the UpdateCameraRotation payload rewrite in
	-- the namecall hook and Combat.sendRotation (that is the channel the server really fires along —
	-- ClientFighter reads CameraController.Rotation directly, so the GetCameraRotation method hook
	-- only shapes what OTHER client code sees), plus the body-yaw owner. Never for
	-- CameraController / SpectateController (the local view stays untouched).
	h.rot = function(orig: Vector2, callerName: string): Vector2
		if callerName == "CameraController" or callerName == "SpectateController" or S.menuOpen or not S.alive then
			return orig
		end
		-- the lobby gate: no anti-aim and no lock-facing stream outside a live duel (an armed override —
		-- the self-test's fake lock — still gets its answer)
		if S.featuresPaused and not S.gateOverride and not S.cfgOverrideSilent then
			return orig
		end
		local st = S.cfg
		local target = h.silentWanted()
		-- Face the lock while a shot can leave: mouse button held, auto shoot engaged on a target,
		-- our own trigger pulse or autokill's firing window. The SERVER fires along the rotation it
		-- last received here (duel evidence: with the real rotation replicated, silent shots land on
		-- the server only when the real look happens to point at the target — 8%, and 0/7 with a
		-- fake rotation). A bare lock with nothing to fire must not freeze the anti-aim on the target.
		local shotLive = h.faceTarget()
		if target and st.silentSpoofServer and shotLive then
			-- v5.0.3: ONE origin for the stream, the echo gate (Combat.wantedShotRot) and the payload —
			-- Game.shotOriginPos (camera live, head when relocated). Two origins a few degrees apart up
			-- close meant the echo never aligned and every pull ran to the cap. v6.1.7: while the body waits
			-- in a hide (or a breaker hop), the stream already faces the lock from where the head will land.
			-- the pre-face belongs to a real lock (a fake lock, the self-test's, faces from where we are)
			local from = (if S.silentFighter ~= nil then S.preFaceFrom else nil) or h.lockOrigin()
			if from and usable(target, from) then
				-- v5: the stream leads a moving target (the server fires along this rotation one trip
				-- later, at a target that has moved on) — same maths the shot-time payload uses
				local aim = if S.combat and S.combat.ledAim then S.combat.ledAim(S.silentPart, target) else target
				if usable(aim, from) then
					-- index + call, never `:ToOrientation()`: h.rot runs inside the namecall hook (the rotation
					-- rewrite) and a namecall there renamed the game's FireServer on Madium / Potassium
					local lk = CFrame.lookAt(from, aim)
					local pitch, yaw = lk.ToOrientation(lk)
					local r = Vector2.new(pitch, yaw)
					h.lastLockRot, h.lastLockAt, h.lastLockF = r, os.clock(), S.silentFighter
					return r
				end
			end
			-- the lock sits where no round reaches (a warp the backtrack could not place): the server keeps the
			-- last lock-facing angle rather than the real camera (duel log: echoes 70–166° off the head)
			local lr = h.lastLockRot
			if lr ~= nil and S.silentFighter ~= nil and h.lastLockF == S.silentFighter and os.clock() - (h.lastLockAt or 0) < 1.5 then
				return lr
			end
		end
		-- v6.1: no fake yaw inside the shot window. Without a lock the round goes where you really look,
		-- so the server must hold the real rotation, not the anti-aim one
		if shotLive then
			return orig
		end
		-- Auto-HvH: autokill hides between rounds and spins there, whatever the anti-aim switch says
		local akh = S.autokill
		if akh and akh.hiding == true and not S.preFace then
			local sp = math.max(st.aaSpeed or 10, 8)
			local pitch = if st.aaPitch == "Up" then 1.45 elseif st.aaPitch == "Zero" then 0 else -1.45
			return Vector2.new(pitch, (os.clock() * sp * (st.aaSpinDir or 1)) % (2 * math.pi))
		end
		-- anti-melee: a blade inside its strike window gets our face, anti-aim or not — the crit (Knife 150)
		-- is judged on where the victim looks, so nobody stays behind us
		-- v6.4: never away from a different lock — the next round would wait a rotation echo to turn back
		local mt = S.meleeThreat
		local lockF = S.silentFighter
		if st.antiMelee and st.antiMeleeFace and st.rageEnabled and mt and typeof(mt.pos) == "Vector3" and (lockF == nil or lockF == mt.fighter) then
			local meH = S.myHeadPart
			if meH and meH.Parent then
				local d = mt.pos - meH.Position
				if d.X * d.X + d.Z * d.Z > 0.01 then
					S.aaAutoMode = "facing a blade"
					return Vector2.new(orig.X, math.atan2(-d.X, -d.Z))
				end
			end
		end
		if st.aaEnabled and not S.calibrating and not (st.aaOnlyIdle and S.firing) then
			local yaw = orig.Y
			local mode = st.aaMode
			local now = os.clock()
			local jitter = math.rad(st.aaJitterDeg or 70)
			if mode == "Auto" then
				-- situation-driven: someone is lining us up → fast jitter (their aim never settles);
				-- enemies close → random snaps; nobody around → a plain spin
				local sit = S.situation
				if sit and sit.aimingAtMe > 0 then
					mode = "Jitter"
					jitter = math.max(jitter, math.rad(90))
				elseif sit and (sit.near > 0 or sit.mid > 0) then
					mode = "Random"
				else
					mode = "Spin"
				end
				S.aaAutoMode = mode
			end
			local awayYaw: number? = nil
			local enemy = S.nearestEnemyPos
			local me = S.myHeadPart
			if typeof(enemy) == "Vector3" and me and me.Parent then
				local d = enemy - me.Position
				awayYaw = math.atan2(d.X, d.Z) -- yaw that faces away from them (Roblox yaw: 0 looks -Z)
			end
			local aaPitch = if st.aaPitch == "Down" then -1.45 elseif st.aaPitch == "Up" then 1.45 elseif st.aaPitch == "Zero" then 0 elseif st.aaPitch == "Jitter" then (if math.floor(now * 15) % 2 == 0 then -1.45 else 1.45) else orig.X
			if mode == "Spin" then
				-- v5: direction + optional jitter on top of the spin (a plain clock spin is trivially
				-- predictable; the jitter breaks the rhythm every 50 ms)
				yaw = (now * st.aaSpeed * (st.aaSpinDir or 1)) % (2 * math.pi)
				if st.aaSpinJitter then
					yaw += if math.floor(now * 20) % 2 == 0 then jitter * 0.5 else -jitter * 0.5
				end
			elseif mode == "Jitter" then
				yaw = orig.Y + (if math.floor(now * 20) % 2 == 0 then jitter else -jitter)
			elseif mode == "Backwards" then
				yaw = orig.Y + math.pi
			elseif mode == "Sideways" then
				yaw = orig.Y + (if math.floor(now / math.max(st.aaSwitchMs / 1000, 0.05)) % 2 == 0 then math.pi / 2 else -math.pi / 2)
			elseif mode == "Away" then
				yaw = awayYaw or (orig.Y + math.pi)
			elseif mode == "Fake" then
				-- alternate real / backwards: the phase comes from the clock (aaSwitchMs per half),
				-- not from a counter — h.rot is asked from five places per frame, so a per-call flip
				-- made the value the server received depend on call interleaving
				local half = math.max(st.aaSwitchMs / 1000, 0.05)
				yaw = if math.floor(now / half) % 2 == 0 then orig.Y else orig.Y + math.pi
			elseif mode == "Random" then
				if now - (S.aaSwitchAt or 0) > st.aaSwitchMs / 1000 then
					S.aaSwitchAt = now
					S.aaRandomYaw = math.random() * 2 * math.pi
				end
				yaw = S.aaRandomYaw or orig.Y
			end
			return Vector2.new(aaPitch, yaw)
		end
		return orig
	end
	-- layer 4: the raycast itself (also what magic bullet uses to ignore walls)
	-- Vector3:Dot is a namecall too (it would clobber the pending method) → arithmetic only in here
	local function dot3(a: Vector3, b: Vector3): number
		return a.X * b.X + a.Y * b.Y + a.Z * b.Z
	end
	-- where the game thinks we look (CameraController rotation — unaffected by our render-camera pin)
	h.lookVector = function(): Vector3?
		local rot = CameraController and CameraController.Rotation
		if typeof(rot) == "Vector2" then
			return CFrame.fromOrientation(rot.X, rot.Y, 0).LookVector
		end
		local cam = workspace.CurrentCamera
		return cam and cam.CFrame.LookVector
	end
	-- is this raycast one of our shots? Leaves from our camera/head and roughly along our look
	-- (spread only bends a shot a few degrees; slide / reach / other players' casts fail one of the two).
	-- Property reads only — this runs inside the namecall hook.
	h.isOurShotRay = function(origin: Vector3, dir: Vector3): boolean
		if dir.Magnitude < 40 then
			return false
		end
		local cam = workspace.CurrentCamera
		local nearCam = cam ~= nil and (origin - cam.CFrame.Position).Magnitude < 6
		local head = S.myHeadPart
		local nearMe = head ~= nil and head.Parent ~= nil and (origin - head.Position).Magnitude < 6
		if not nearCam and not nearMe then
			return false
		end
		local u = dir.Unit
		local look = h.lookVector()
		if look ~= nil and dot3(u, look) > 0.9 then -- within ~25° of where the game thinks we look
			return true
		end
		-- layer 1 already turned this ray at the lock (teleported / invisible modes): accept it too
		local target = S.silentTarget
		if typeof(target) == "Vector3" then
			local rel = target - origin
			local m = rel.Magnitude
			if m > 0.5 and dot3(u, rel / m) > 0.985 then
				return true
			end
		end
		return false
	end
	h.redirect = function(origin: Vector3, dir: Vector3, params: any): (Vector3?, any, Vector3?, boolean?)
		local st = S.cfg
		if not h.isOurShotRay(origin, dir) then
			return nil, nil, nil, nil
		end
		local target = h.silentWanted()
		if target and not h.shotGuided() then
			target = nil
		end
		if not target then
			-- no lock: "better no spread" — the shot leaves exactly along the look vector
			if st.noSpread and st.noSpreadStraighten and not S.featuresPaused then
				local look = h.lookVector()
				if look then
					S.straightened = (S.straightened or 0) + 1
					return look * dir.Magnitude, params, if S.tpActive then h.shotOrigin() else nil, true
				end
			end
			return h.headRay(origin, dir, params)
		end
		if not h.gateOk() then
			return h.headRay(origin, dir, params)
		end
		-- teleported or third person: the cast must leave from the real head, not from wherever the view
		-- is pinned or from the camera behind us
		local real = h.shotOrigin()
		if real and (real - origin).Magnitude > 3 then
			origin = real
		end
		-- v6.6 wallbang (no teleport): the game's own cast also starts past the wall in front of us
		local wpo = S.wallPushOrigin
		if wpo and S.wallPushModel == S.silentTargetModel and (not S.teleported or S.wallPushUnder) then
			origin = wpo
		end
		if not usable(target, origin) then
			return nil, nil, nil, nil
		end
		local newDir = (target - origin).Unit * math.max(dir.Magnitude, (target - origin).Magnitude + 5)
		local newParams = params
		local model = S.silentTargetModel
		-- v6.1: the damage ray may hit the model's hitboxes, never its riot shield (a stowed shield on the
		-- back absorbed every round from behind). The list is built outside this hook (Combat.updateLock).
		local dmg = if S.silentDamageModel == model then S.silentDamageParts else nil
		-- v5 perf: two pooled RaycastParams instead of a fresh one per redirected shot (this runs on the
		-- game's shot thread, several times per pull for multi-pellet guns)
		if st.magicBullet and model then
			local mp = h.magicParams
			if not mp then
				mp = RaycastParams.new()
				mp.FilterType = Enum.RaycastFilterType.Include
				mp.IgnoreWater = true
				h.magicParams = mp
			end
			if dmg and #dmg > 0 then
				mp.FilterDescendantsInstances = dmg
			else
				h.magicFilter[1] = model
				mp.FilterDescendantsInstances = h.magicFilter
			end
			newParams = mp
		elseif model and typeof(params) == "RaycastParams" and params.FilterType == Enum.RaycastFilterType.Include then
			-- the game's whitelist may not contain the target's own hitboxes (ray through the head → "air");
			-- make sure they are hittable without touching anything else about the cast
			local list = params.FilterDescendantsInstances
			if dmg and #dmg > 0 then
				for _, p in ipairs(dmg) do
					table.insert(list, p)
				end
			else
				table.insert(list, model)
			end
			local wp = h.whitelistParams
			if not wp then
				wp = RaycastParams.new()
				wp.FilterType = Enum.RaycastFilterType.Include
				h.whitelistParams = wp
			end
			wp.FilterDescendantsInstances = list
			wp.IgnoreWater = params.IgnoreWater
			wp.CollisionGroup = params.CollisionGroup
			wp.RespectCanCollide = params.RespectCanCollide
			newParams = wp
		end
		return newDir, newParams, origin, nil
	end
	-- ground truth per redirected shot
	h.recordShot = function(res: any, origin: Vector3, dir: Vector3, params: any)
		local ss = S.shotStats
		local model = S.silentTargetModel
		-- the game also casts an Exclude{target} ray per shot (tracer / wall pass): it can never hit the
		-- lock, so it must not count as a shot at all (it was the phantom "air" in the stats)
		if model and typeof(params) == "RaycastParams" and params.FilterType == Enum.RaycastFilterType.Exclude then
			for _, inst in ipairs(params.FilterDescendantsInstances) do
				if inst == model or inst:IsDescendantOf(model) then
					return
				end
			end
		end
		-- the game casts more than one ray per trigger pull (hit + effects, pellets): rays inside the
		-- same 12 ms count as one shot for the stats and the expected damage
		local nowShot = os.clock()
		if nowShot - (S.lastShotRayAt or 0) < 0.012 then
			S.lastShotRayAt = nowShot
			return
		end
		S.lastShotRayAt = nowShot
		-- a rapid-fire round kept on your screen: no hit marker, no expected damage (it never reaches the server)
		if S.fireClientOnly then
			ss.clientOnly = (ss.clientOnly or 0) + 1
			return
		end
		ss.redirected += 1
		if not S.paramsDumped and typeof(params) == "RaycastParams" then
			-- one-time look at what the game's shot ray is allowed to hit
			S.paramsDumped = true
			local list = params.FilterDescendantsInstances
			local names = {}
			for i = 1, math.min(#list, 12) do
				local inst = list[i]
				names[i] = inst:GetFullName() .. (if inst:IsA("BasePart") then "" else ("[" .. #inst:GetChildren() .. "]"))
			end
			log("INFO", ("shot params: %s · %d entries · group '%s' · respectCanCollide=%s · %s%s"):format(
				tostring(params.FilterType), #list, tostring(params.CollisionGroup), tostring(params.RespectCanCollide),
				table.concat(names, ", "), if #list > 12 then " …" else ""
			))
			if model then
				local parts = {}
				for _, d in ipairs(model:GetDescendants()) do
					if d:IsA("BasePart") then
						table.insert(parts, ("%s(q=%s,c=%s,%s)"):format(d.Name, tostring(d.CanQuery), tostring(d.CanCollide), d.CollisionGroup))
					end
				end
				log("INFO", ("target model %s parts: %s"):format(model.Name, table.concat(parts, " ")))
			end
		end
		if res and res.Instance then
			if ss.hitTarget + ss.hitOther < 12 then
				log("DEBUG", ("shot hit %s (%s) at %.0f studs"):format(res.Instance:GetFullName(), res.Material.Name, (res.Position - origin).Magnitude))
			end
			if model and res.Instance:IsDescendantOf(model) then
				ss.hitTarget += 1
				S.hitMarkerAt = os.clock()
				local gs = S.gameState
				local info = gs and gs.item and gs.item.Info
				if type(info) == "table" then
					-- what this hit should be worth if the server accepts it (pellets = one ray each),
					-- including the weapon's range falloff — without it a Handgun at 90 studs made a
					-- perfectly normal round read as "11 % landed"
					local dmg = tonumber(info.ShootDamage) or 0
					if res.Instance.Name:find("Head", 1, true) and tonumber(info.CriticalDamage) then
						dmg = tonumber(info.CriticalDamage) or dmg
					end
					local d = (res.Position - origin).Magnitude
					local d0, d1 = tonumber(info.RaycastDamageDropoffStartDistance), tonumber(info.RaycastDamageDropoffEndDistance)
					local mult = tonumber(info.RaycastDamageDropoffMultiplier)
					if d0 and d1 and mult and d1 > d0 and d > d0 then
						local t = math.clamp((d - d0) / (d1 - d0), 0, 1)
						dmg = dmg * (1 - t * (1 - mult))
					end
					S.dmgExpected = (S.dmgExpected or 0) + dmg
				end
				local f = S.silentFighter
				local hp = S.fighterHealth and f and S.fighterHealth(f)
				if hp == nil then
					local hum = model:FindFirstChildOfClass("Humanoid")
					hp = hum and hum.Health
				end
				if hp ~= nil then
					table.insert(S.pendingHits, { t = os.clock(), model = model, fighter = f, hp = hp })
					if #S.pendingHits > 64 then
						table.remove(S.pendingHits, 1)
					end
				end
			else
				ss.hitOther += 1
				if ss.hitOther <= 20 or ss.hitOther % 25 == 0 then
					log("DEBUG", ("shot blocked by %s (%.0f studs) — target %s"):format(res.Instance:GetFullName(), (res.Position - origin).Magnitude, model and model.Name or "?"))
				end
			end
		else
			ss.miss += 1
			if ss.miss <= 20 or ss.miss % 25 == 0 then
				-- how far the ray passed from the aim point and from the live head: tells stale lock from filter trouble
				local target = S.silentTarget
				local detail = ""
				if typeof(target) == "Vector3" and dir.Magnitude > 0 then
					local u = dir.Unit
					local rel = target - origin
					local along = math.clamp(rel:Dot(u), 0, dir.Magnitude)
					local offAim = (rel - u * along).Magnitude
					local head = model and model:FindFirstChild("Head")
					local offHead = if head then ((head.Position - origin) - u * math.clamp((head.Position - origin):Dot(u), 0, dir.Magnitude)).Magnitude else -1
					detail = (" · ray passed %.2f from aim point, %.2f from live head, %.0f studs out"):format(offAim, offHead, along)
				end
				log("DEBUG", ("shot hit nothing — dir len %.0f target %s%s"):format(dir.Magnitude, model and model.Name or "?", detail))
			end
		end
	end
	h.afterReload = function(item: any)
		if S.alive and not S.featuresPaused then
			pcall(Combat.afterReload, item)
		end
	end
	-- the fire gate (Hooks.installFire): our own items only — a gun / blade another fighter replicates runs
	-- the same class method
	h.fireGate = function(item: any, replicated: any, quick: any): string
		if type(item) ~= "table" or not (item.ClientFighter and item.ClientFighter.IsLocalPlayer == true) then
			return "pass"
		end
		return Combat.fireGate(item, replicated, quick)
	end
	h.fireDone = function(item: any, how: string)
		if type(item) == "table" and item.ClientFighter and item.ClientFighter.IsLocalPlayer == true then
			Combat.fireDone(item, how)
		end
	end
	-- speed boost / no ADS slowdown on the game's own walk speed (Hooks.installWalkSpeed): table reads only
	h.walkSpeed = function(speed: number, mc: any): number
		local st = S.cfg
		if S.featuresPaused or type(speed) ~= "number" then
			return speed
		end
		-- no slowdowns: _GetWalkSpeed is BASE * (1 + sprint + speed boost) * (… item multiplier …) — a
		-- negative boost (freeze ray, permafrost stacks, minigun spin-up) and an item multiplier under 1
		-- are taken back out; a full freeze (IsFrozen → 0) keeps the last free speed
		if st.noSlow and type(mc) == "table" then
			local lf = mc.LocalFighter
			local ent = lf and lf.Entity
			if speed <= 0 then
				local frozen = type(mc.IsFrozen) == "function" and mc:IsFrozen()
				if frozen and S.walkFree then
					speed = S.walkFree
				end
			else
				local boost = ent and type(ent.GetBoost) == "function" and tonumber(ent:GetBoost("Speed")) or 0
				if boost < 0 then
					local sprint = if mc.IsSprinting then (tonumber(lf:Get("SprintingSpeedBoost")) or 0.5) else 0
					local slowed = 1 + sprint + boost
					if slowed > 0.05 then
						speed *= (1 + sprint) / slowed
					end
				end
				local item = lf and lf.EquippedItem
				local mult = item and type(item.Info) == "table" and tonumber(item.Info.WalkSpeedMultiplier)
				if mult and mult > 0.05 and mult < 1 then
					speed /= mult
				end
				S.walkFree = speed
			end
		end
		if speed <= 0 then
			return speed
		end
		local gs = S.gameState
		if not (gs and gs.aiming == true) then
			S.walkNoAds = speed -- what the game gives us unscoped: No ADS slowdown keeps it while aiming
		elseif st.noAdsSlow and S.walkNoAds and speed < S.walkNoAds then
			speed = S.walkNoAds
		end
		if st.speedBoost then
			speed *= math.clamp(tonumber(st.speedMult) or 1, 1, 10)
		end
		return speed
	end
	-- the wrap the viewmodel/projectiles should use for our own item (skins tab). Returns a wrap the
	-- game's WrapController accepts; nil = leave the real one. Filled from the local equip's data.
	-- RIVALS weapon cosmetics are two different systems:
	--   Wrap-type (has CosmeticLibrary.Cosmetics[name].WrapGroups) → recolour/retexture via GetWrap
	--   Skin-type (no WrapGroups) → a whole model swap chosen by GetViewModelDetails.ViewModelName
	-- Feeding a skin name into GetWrap makes ApplyWrap reset the wrap and find no groups → the wrap
	-- breaks and nothing shows. So GetWrap only ever gets a real wrap; skins go through the model path.
	function h.isWrapType(cosName: any): boolean
		if type(cosName) ~= "string" then
			return false
		end
		local cos = CosmeticLibrary.Cosmetics[cosName]
		return type(cos) == "table" and cos.WrapGroups ~= nil
	end
	-- the wrap to paint for `weaponName` (nil = leave the real one). Only wrap-type cosmetics.
	h.wrapFor = function(weaponName: any, orig: any): any
		if not (S.alive and S.cfg.unlockCosmetics) or type(weaponName) ~= "string" then
			return nil
		end
		local eq = S.localEquips[weaponName]
		if not eq then
			return nil
		end
		-- an explicitly-chosen Wrap wins; a chosen "Skin" that is actually wrap-type also works here
		local wrap = eq.Wrap or (eq.Skin and h.isWrapType(eq.Skin.Name) and eq.Skin)
		if not (wrap and wrap.Name) then
			return nil
		end
		return { Name = wrap.Name, Inverted = wrap.Inverted }
	end
	-- cache of model names that actually exist under PlayerScripts.Assets.ViewModels. A skin whose
	-- model is not present client-side must NEVER be forced — that left the weapon with no viewmodel
	-- and unselectable in the hotbar.
	h.vmCache = nil
	h.vmCacheAt = 0
	function h.viewModelExists(name: string): boolean
		local function scan()
			h.vmCache = {}
			h.vmCacheAt = os.clock()
			local ps = LP:FindFirstChild("PlayerScripts")
			local assets = ps and ps:FindFirstChild("Assets")
			local vm = assets and assets:FindFirstChild("ViewModels")
			if vm then
				for _, d in ipairs(vm:GetDescendants()) do
					if d:IsA("Model") then
						h.vmCache[d.Name] = true
					end
				end
			end
		end
		if not h.vmCache then
			scan()
		end
		if h.vmCache[name] == true then
			return true
		end
		-- the assets folder fills in over time after a hop: a miss re-scans at most every 5 s
		if os.clock() - h.vmCacheAt > 5 then
			scan()
		end
		return h.vmCache[name] == true
	end
	h.invalidateVmCache = function()
		h.vmCache = nil
	end
	-- Where the viewmodel model really comes from (decompile + live trace, v4.1): the server sends
	-- every item with a nested viewmodel serial; the item constructor (Gun/Melee/Custom.new) calls
	-- ClientItem:_CreateViewModel(serial) → ClientViewModel.new(decoded, item), and new() picks the
	-- model by the serial's Name field (Assets.ViewModels.<case>.<Name>, Info = ItemLibrary.ViewModels[Name]).
	-- GetViewModelDetails() only *reads* that data back. So a model skin = rewrite the Name in the
	-- serial before the game builds from it (h.patchVmSerial in the _CreateViewModel / new hooks).
	-- The compressed serial uses short obfuscated keys, so the patch matches by VALUE: the one string
	-- that is a viewmodel name of this weapon (the default model or an owned skin) becomes the skin.
	h.isVmNameFor = function(value: any, weaponName: any): boolean
		if type(value) ~= "string" or type(weaponName) ~= "string" then
			return false
		end
		local vms = ItemLibrary and ItemLibrary.ViewModels
		if type(vms) ~= "table" or vms[value] == nil then
			return false
		end
		if value == weaponName then
			return true
		end
		local cos = CosmeticLibrary.Cosmetics[value]
		return type(cos) == "table" and cos.ItemName == weaponName
	end
	-- the skin viewmodel to build for `weaponName` (nil = the game's own). Model-type skins only,
	-- and only when both the model and its ItemLibrary.ViewModels entry exist client-side.
	h.skinModelFor = function(weaponName: any): string?
		if not (S.alive and S.cfg.unlockCosmetics and S.cfg.skinModelSwap) or type(weaponName) ~= "string" then
			return nil
		end
		local eq = S.localEquips[weaponName]
		local skin = eq and eq.Skin
		local name = type(skin) == "table" and skin.Name
		if type(name) ~= "string" or h.isWrapType(name) then
			return nil
		end
		local vms = ItemLibrary and ItemLibrary.ViewModels
		if type(vms) ~= "table" or vms[name] == nil or not h.viewModelExists(name) then
			return nil
		end
		return name
	end
	-- v6.4 what another centerra user equipped (the add-on pulls everyone's into CenterraSharedSkins, keyed by
	-- user id and lower-case name): the game then builds THEIR viewmodel with the skin and paints their
	-- wrap itself — lobby, duels, every mode — instead of a clone laid over the model
	h.sharedEquip = function(item: any): any
		local cf2 = type(item) == "table" and item.ClientFighter
		local plr = type(cf2) == "table" and cf2.Player
		local shared = genv().CenterraSharedSkins
		if typeof(plr) ~= "Instance" or type(shared) ~= "table" or type(item.Name) ~= "string" then
			return nil
		end
		local row = shared[tostring(plr.UserId)] or shared[string.lower(plr.Name)]
		local eq = type(row) == "table" and row[item.Name]
		return if type(eq) == "table" then eq else nil
	end
	h.sharedSkinFor = function(item: any): string?
		if not (S.alive and S.cfg.skinModelSwap) then
			return nil
		end
		local eq = h.sharedEquip(item)
		local name = eq and eq.Skin
		if type(name) ~= "string" or h.isWrapType(name) then
			return nil
		end
		local cos = CosmeticLibrary.Cosmetics[name]
		local vms = ItemLibrary and ItemLibrary.ViewModels
		if not (type(cos) == "table" and cos.ItemName == item.Name) or type(vms) ~= "table" or vms[name] == nil or not h.viewModelExists(name) then
			return nil
		end
		return name
	end
	h.sharedWrapFor = function(item: any): any
		if not S.alive then
			return nil
		end
		local eq = h.sharedEquip(item)
		if not eq then
			return nil
		end
		local w = if type(eq.Wrap) == "string" then eq.Wrap elseif type(eq.Skin) == "string" then eq.Skin else nil
		if not h.isWrapType(w) then
			return nil
		end
		return { Name = w, Inverted = eq.WrapInverted == true }
	end
	-- rewrite the weapon's viewmodel name inside `serial` to `skinName` IN PLACE (the game's own
	-- _DecodeSerial mutates that same table, so callers must keep seeing the one they passed).
	-- Handles the compressed wire shape { [k] = { [k2] = "Sniper", ... } } and the decoded
	-- { Data = { Name = ... } }. Returns the table when something changed, nil otherwise.
	h.patchVmSerial = function(serial: any, weaponName: string, skinName: string): any
		if type(serial) ~= "table" then
			return nil
		end
		local changed = false
		for k, v in pairs(serial) do
			if type(v) == "table" then
				for k2, v2 in pairs(v) do
					if type(v2) == "string" and v2 ~= skinName and h.isVmNameFor(v2, weaponName) then
						v[k2] = skinName
						changed = true
					end
				end
			elseif type(v) == "string" and v ~= skinName and h.isVmNameFor(v, weaponName) then
				serial[k] = skinName
				changed = true
			end
		end
		return if changed then serial else nil
	end

	-- layer 0 (v4): the camera data table itself. Gun.StartShooting calls GetCameraData() with NO
	-- arguments and replicates the result through ClientFighter:Input — that table is the shot:
	--   [\0] origin CFrame (RootPart + camera spring)   [\1] camera CFrame (rotation → far point)
	--   [\2] hit instance                                [\3] hit offset in that instance's space
	-- With a lock we hand back the same shape aimed at the locked hitbox (origin untouched: it is
	-- derived from the real root even while the rendered camera is pinned elsewhere). Tracer calls
	-- (with arguments) get the same answer so what you see matches what the server is told.
	function h.whichOf(part: BasePart?): string
		local n = part and part.Name or ""
		return if n:find("Head", 1, true) then "head" elseif n:find("Body", 1, true) or n == "HumanoidRootPart" or n:find("Torso", 1, true) then "body" else "root"
	end
	-- v5: the shot payload carries its CFrames COMPRESSED — { [\0]=x, [\1]=y, [\2]=z, [\3]=rx,
	-- [\4]=ry, [\5]=rz } (CFrame:ToOrientation order). The 3-argument tracer call still returns real
	-- CFrames. Both shapes decode to a CFrame here and are written back in the shape they arrived in;
	-- the v4 code tested `typeof(...) == "CFrame"` and silently rewrote nothing after the game update.
	h.decodeCF = function(v: any): CFrame?
		if typeof(v) == "CFrame" then
			return v
		end
		if type(v) == "table" then
			local x, y, z = v[KEY[1]], v[KEY[2]], v[KEY[3]]
			if type(x) == "number" and type(y) == "number" and type(z) == "number" then
				local rx, ry, rz = v[KEY[4]], v[KEY[5]], v[KEY[6]]
				return CFrame.new(x, y, z) * CFrame.fromOrientation(if type(rx) == "number" then rx else 0, if type(ry) == "number" then ry else 0, if type(rz) == "number" then rz else 0)
			end
		end
		return nil
	end
	h.encodeCFLike = function(sample: any, cf: CFrame): any
		if typeof(sample) == "CFrame" or type(sample) ~= "table" then
			return cf
		end
		local rx, ry, rz = cf.ToOrientation(cf) -- hook-reachable: no namecall
		return { [KEY[1]] = cf.X, [KEY[2]] = cf.Y, [KEY[3]] = cf.Z, [KEY[4]] = rx, [KEY[5]] = ry, [KEY[6]] = rz }
	end
	-- v5 spread claim (hooked Gun.IsFullyAiming): our own guns only, live config
	h.claimAim = function(item: any): boolean
		if not S.alive or not S.cfg.spreadClaimAim or (S.featuresPaused and not S.gateOverride) then
			return false
		end
		local cf = type(item) == "table" and rawget(item, "ClientFighter")
		if not (type(cf) == "table" and cf.IsLocalPlayer == true) then
			return false
		end
		-- real-aim weapons are never claimed: the game's own aim state decides (we scope in for them)
		local modeFor = S.spreadModeFor
		return type(modeFor) ~= "function" or modeFor(item) ~= "real"
	end
	-- guns whose rounds are projectiles: the server answers them with a projectile, never a hitscan
	-- ShootEffect (named fallbacks for builds where the library flag moves)
	h.NO_REPLY = { ["Energy Pistols"] = true, ["Energy Pistol"] = true, Slingshot = true }
	h.noReplyWeapon = function(item: any, name: any): boolean
		local info = type(item) == "table" and item.Info
		if type(info) == "table" and (info.IsProjectile == true or info.Type ~= "Gun") then
			return true
		end
		return h.NO_REPLY[tostring(name)] == true
	end
	-- the game's own answers behind our two v5 hooks (originals live in the carried S.hookOrig, so they
	-- survive the installer's early return on a re-inject): nil = the hook is not installed yet
	h.realFullyAiming = function(item: any): boolean?
		local orig = S.hookOrig and S.hookOrig.gunIsFullyAiming
		if type(orig) ~= "function" or type(item) ~= "table" then
			return nil
		end
		local okR, r = pcall(orig, item)
		return if okR then r == true else nil
	end
	h.realOob = function(machine: any): any
		local orig = S.hookOrig and S.hookOrig.oobIsOutOfBounds
		if type(orig) ~= "function" or type(machine) ~= "table" then
			return nil
		end
		local okR, r = pcall(orig, machine)
		return if okR then r else nil
	end
	h.cameraData = function(t: any, fighter: any, nargs: number): any
		if not S.alive or type(t) ~= "table" then
			return t
		end
		local st = S.cfg
		local isShot = nargs == 0
		local originRaw = t[KEY[1]]
		local origin = h.decodeCF(originRaw)
		local camCF = h.decodeCF(t[KEY[2]])
		local haveCF = origin ~= nil and camCF ~= nil
		if S.cdDbg and isShot then
			S.cdDbg.compressed = type(originRaw) == "table" -- the shot payload's shape (tracer calls stay CFrames)
			-- v5.2: a payload whose CFrames decode with neither shape is a game update — say so once
			-- (Adapt contract "shot payload") instead of silently leaving every shot unrewritten
			S.cdDbg.shapeUnknown = not haveCF
			if h.learnShotCaller then
				h.learnShotCaller()
			end
		end
		-- one-time shape capture of the no-arg return (key / value types) for Debug / centerra_state
		if isShot and S.cdDbg and not S.cdDbg.shape and st.debugConsole then
			local shape = {}
			for k, v in pairs(t) do
				local kb = if type(k) == "string" and #k <= 2 then ("b" .. tostring(k:byte(1))) else tostring(k)
				shape[kb] = typeof(v)
			end
			S.cdDbg.shape = shape
		end
		local target = h.silentWanted()
		if target and not h.shotGuided() then
			target = nil -- this shot rolled unguided (Silent hit chance): the payload stays as aimed
		end
		local part = S.silentPart
		local model = S.silentTargetModel
		local gs = S.gameState
		local item = gs and gs.item
		local originPos = if haveCF then origin.Position elseif S.myHeadPart and S.myHeadPart.Parent then S.myHeadPart.Position else nil
		-- record EVERY local shot (a claim needs no CFrame): the server-truth match (_ShootEffect) and
		-- backtrack learning key off this, independent of whether the spoof rewrite can run. A rapid-fire
		-- round the fire gate keeps on your screen never reaches the server: no record, no learner input
		local rec: any = nil
		local clientOnly = S.fireClientOnly == true
		if isShot and st.shotsRecord and not clientOnly then
			local aimed: boolean? = nil
			if type(item) == "table" and type(item.Info) == "table" and item.Info.AimScopePercent and type(item.IsFullyAiming) == "function" then
				-- the honest scope state for the record (the claim hook answers true to the game)
				aimed = h.realFullyAiming(item)
				if aimed == nil then
					local okA, a = pcall(item.IsFullyAiming, item)
					aimed = okA and a == true
				end
			end
			-- v5.0.4 diagnostics: which orientation did the server fire along? Every candidate is stored
			-- per shot and compared against the server's tracer in Shots.serverResult (Debug → Shots)
			local headP = S.myHeadPart
			local rootP = S.myRootPart
			local camNow = workspace.CurrentCamera
			local ccRot = CameraController and CameraController.Rotation
			rec = {
				weapon = gs and gs.weapon,
				origin = originPos,
				unaimed = aimed == false,
				hopAt = S.lastTeleportAt, -- the settle learner tells post-hop shots apart by this
				headLook = if headP and headP.Parent then headP.CFrame.LookVector else nil,
				rootLook = if rootP and rootP.Parent then rootP.CFrame.LookVector else nil,
				camLook = if camNow then camNow.CFrame.LookVector else nil,
				ccRot = if typeof(ccRot) == "Vector2" then ccRot else nil,
				echoRot = S.aaServerRot,
				sentRot = S.combat and S.combat.aaLastSent or nil,
				teleported = S.teleported == true,
				targetImmune = S.targetImmune == true,
				targetHp = S.silentFighter and Game.fighterHealth(S.silentFighter) or nil,
				partPos = if part and part.Parent then part.Position else nil,
				partSize = if part and part.Parent then part.Size else nil,
				which = h.whichOf(part),
				-- a melee swing never answers with a ShootEffect: judged as SWING, not NO-REPLY
				melee = type(item) == "table" and type(item.Info) == "table" and item.Info.Type ~= "Gun",
				projectile = h.noReplyWeapon(item, gs and gs.weapon),
			}
			if S.cdDbg then
				S.cdDbg.claimed += 1
			end
		end
		if haveCF and target and part and part.Parent and model and st.silentCameraData and h.callerIsShotCode() and h.gateOk() and (S.firing or S.cfgOverrideSilent or os.clock() < (S.spoofUntil or 0)) and h.claimReady() then
			-- aim point: the locked part itself, live. Gun._LocalTracers (decompiled) resolves the
			-- shot's target as hitInstance.CFrame * offset on the RECEIVING side — the offset rides on
			-- the part wherever the server has it, which is lag compensation for free. Any rewound
			-- (backtracked) aim shifts that offset off the part and lands short: the old Manual mode
			-- did exactly that to every shot at a runner and is retired. v6.1: when the live part is out
			-- of the server's reach, the position a ShootEffect confirmed a moment ago (S.silentAimPoint).
			-- semi-legit: the point of the box that sits inside the circle, not the box's centre
			local lpt = S.silentLocal
			local confirmedAim = S.silentAimPoint ~= nil and S.silentAimModel == model
			local aim: Vector3 = if confirmedAim then S.silentAimPoint elseif typeof(lpt) == "Vector3" and S.silentLocalPart == part then part.CFrame:PointToWorldSpace(lpt) else part.Position
			-- the warp backtrack (only while the live root reads fake): the aim and the offset ride on the real spot
			local realPos, warped = S.resolver.fixPos(part)
			if warped and not confirmedAim then
				aim = realPos
			end
			local backSec = 0
			local from = origin.Position
			-- v6.6 wallbang: the claimed origin moves ahead along the same line, past the wall in front of us
			local pushed = 0
			local wpo = S.wallPushOrigin
			if wpo and S.wallPushModel == model and (S.teleported ~= true or S.wallPushUnder) then
				pushed = (wpo - from).Magnitude
				from = wpo
			end
			local rel = aim - from
			local dist = rel.Magnitude
			-- LOS is the per-frame value (S.targetVisible), never a fresh raycast here: this runs inside
			-- the GetCameraData hook on the shot thread, and a nested workspace:Raycast would re-enter
			-- our own raycast redirect
			-- v5: while relocated (magic / autokill) the origin is next to the target — distance is small
			-- and LOS is the planner's; the cap only guards the un-relocated case
			local relocatedNow = S.teleported == true
			if dist > 0.5 and (relocatedNow or dist <= (st.targetMaxDistance or 400)) and (st.magicBullet or relocatedNow or S.targetVisible ~= false) then
				-- moving target: the replicated rotation leads the part by Combat.leadSec (learned);
				-- the part + zero offset below still ride on the part itself
				local vel = S.resolver.fixVel(part)
				local speed = vel.Magnitude
				local leadSec = if S.combat and S.combat.leadSec and isShot then S.combat.leadSec(speed) else 0
				local rotAim = aim
				if leadSec > 0 and speed > 3 then
					-- never lead more than the part's own size × 3 (a 20 st/s sprinter at 260 ms is 5 st)
					local lead = vel * leadSec
					local cap = math.max(part.Size.Magnitude, 1) * 3
					if lead.Magnitude > cap then
						lead = lead.Unit * cap
					end
					rotAim = aim + lead
				end
				local look = CFrame.lookAt(from, rotAim).Rotation
				-- the server fires along the rotation it last received: on a manual click this hook
				-- runs before the shot replicates, so push the target-facing rotation now (our own
				-- trigger already did in Combat.pulse — the 10 ms gate skips the duplicate)
				if isShot and not clientOnly and st.silentSpoofServer and S.combat and S.combat.sendRotation and os.clock() - (S.combat.aaSentAt or 0) > 0.01 then
					local p, y = look.ToOrientation(look)
					S.combat.sendRotation(Vector2.new(p, y))
				end
				local out = {}
				for k, v in pairs(t) do
					out[k] = v
				end
				-- both CFrames sit AT the origin and look at the aim: whether the receiver casts from
				-- the origin along the camera look, from the camera position, or origin → hit point,
				-- every construction passes through the hitbox. (v4.2.0 kept the real camera position
				-- — 5 studs behind the head in third person — so the "camera ray" was a parallel copy
				-- offset by the spring: the WALL / NEAR-by-1-3-studs pattern in the duel logs.)
				local aimedCF = CFrame.new(from) * look
				out[KEY[1]] = h.encodeCFLike(originRaw, aimedCF)
				out[KEY[2]] = h.encodeCFLike(t[KEY[2]], aimedCF)
				out[KEY[3]] = part
				-- a miss payload has no hit slot: borrow the origin slot's shape so the offset travels
				-- compressed exactly like the rest of the table
				local partCF = if warped then CFrame.new(realPos) * part.CFrame.Rotation else part.CFrame
				out[KEY[4]] = h.encodeCFLike(if t[KEY[4]] ~= nil then t[KEY[4]] else originRaw, partCF:ToObjectSpace(CFrame.new(aim)))
				if rec then
					rec.spoofed = true
					rec.warp = if warped then math.floor((part.Position - realPos).Magnitude + 0.5) else nil
					rec.target = model.Name
					rec.part = part.Name
					rec.partInst = part
					rec.aim = aim
					rec.model = model
					rec.dist = dist
					rec.backMs = math.floor(backSec * 1000 + 0.5)
					rec.speed = speed
					rec.leadMs = math.floor(leadSec * 1000 + 0.5)
					rec.leadArm = S.lead and S.lead.pendingArm or nil
					rec.pushed = if pushed > 0 then pushed else nil
					Shots.claim(rec)
				end
				S.lastCameraDataSpoofAt = os.clock()
				return out
			end
		end
		if rec then
			-- unspoofed shot: prefer where we are locked (that is what we intend to hit); else where the
			-- game's own camera data aimed (hit instance + offset, when present)
			if target and part and part.Parent and model then
				rec.aim = S.resolver.fixPos(part)
				rec.target = model.Name
				rec.part = part.Name
				rec.model = model
				rec.which = h.whichOf(part)
			else
				local hitInst = t[KEY[3]]
				local relCF = h.decodeCF(t[KEY[4]])
				if typeof(hitInst) == "Instance" and typeof(relCF) == "CFrame" then
					rec.aim = (hitInst.CFrame * relCF).Position
					rec.target = hitInst.Parent and hitInst.Parent.Name or hitInst.Name
					rec.part = hitInst.Name
					local p = hitInst.Parent
					rec.model = if p and p:IsA("Model") then p else nil
				end
			end
			if rec.aim and originPos then
				rec.dist = (rec.aim - originPos).Magnitude
			end
			Shots.claim(rec)
		end
		return t
	end
	-- server → client shot result for our own gun (Gun.ReplicateFromServer("ShootEffect"))
	h.serverShot = function(gunItem: any, results: any)
		if not S.alive then
			return
		end
		local cf = type(gunItem) == "table" and gunItem.ClientFighter
		if type(cf) ~= "table" or cf.IsLocalPlayer ~= true then
			return
		end
		Shots.serverResult(results)
	end
	-- ground truth for "no spread": angle between the game's own shot ray and the camera look vector
	S.spreadSamples = S.spreadSamples or {}
	-- (no logging in here — still inside the namecall hook; Combat.reportSpread logs from the loop)
	h.sampleSpread = function(dir: Vector3)
		local look = h.lookVector()
		if not look then
			return
		end
		local ang = math.deg(math.acos(math.clamp(dot3(dir.Unit, look), -1, 1)))
		local list = S.spreadSamples
		table.insert(list, ang)
		if #list > 60 then
			table.remove(list, 1)
		end
		S.spreadSampleCount = (S.spreadSampleCount or 0) + 1
	end
	local spreadReported = 0
	function Combat.reportSpread()
		local n = S.spreadSampleCount or 0
		if n - spreadReported < 10 then
			return
		end
		spreadReported = n
		local list = S.spreadSamples
		local sum, mx = 0, 0
		for _, a in ipairs(list) do
			sum += a
			mx = math.max(mx, a)
		end
		S.spreadAvg = sum / math.max(#list, 1)
		log("DEBUG", ("spread: game ray vs look — avg %.2f° max %.2f° over last %d unredirected shots (noSpread=%s, straightened %d)"):format(S.spreadAvg, mx, #list, tostring(cfg.noSpread), S.straightened or 0))
	end
	h.canSlide = function(orig: any): any
		return if S.alive and S.cfg.infSlide and not S.featuresPaused then true else orig
	end
	h.canSprint = function(orig: any): any
		return if S.alive and S.cfg.infSprint and not S.featuresPaused then true else orig
	end
	h.thirdPerson = function(): boolean
		return S.alive and S.cfg.thirdPerson == true and not S.featuresPaused
	end
	h.recoilBlocked = function(): boolean
		if not S.alive or S.featuresPaused then
			return false
		end
		return S.cfg.noRecoil == true or (S.autokill and S.autokill.state ~= "idle" and S.autokill.state ~= "done")
	end
	-- fake-duck: lie about crouching to replication-side callers only (experimental)
	h.crouch = function(orig: any, callerName: string): any
		if S.alive and S.cfg.fakeDuck and not S.featuresPaused and callerName ~= "CameraController" and callerName ~= "MechanicsController" and callerName ~= "SpectateController" and not S.menuOpen then
			return math.floor(os.clock() * 8) % 2 == 0
		end
		return orig
	end
	h.spyRemote = function(self: any, method: string, ...)
		if not (S.alive and S.cfg.remoteSpy and S.firing) then
			return
		end
		if self == h.rotRemote then
			return -- our own 20 Hz rotation stream would drown everything else
		end
		local parts = {}
		for i = 1, select("#", ...) do
			local v = select(i, ...)
			local tv = typeof(v)
			parts[i] = if tv == "Instance" then ("<%s %s>"):format(v.ClassName, v.Name) elseif tv == "table" then "{table}" else tv .. ":" .. tostring(v)
		end
		-- deferred: the bridge's print sends over a socket (a method call) and we are still inside the
		-- namecall hook with oldNc pending
		task.defer(print, ("[centerra][spy] %s:%s(%s)"):format(self.Name, method, table.concat(parts, ", ")))
	end
	-- cosmetics logic is filled in by §10 (h.fakeInventory, h.isCosKey, h.unlockable, h.applyLocalEquip, h.weaponData)

	-- installers ---------------------------------------------------------------
	local installed = S.hooks.installed

	function Hooks.installCamera()
		if installed.camera then
			return
		end
		local target = CameraController.GetCameraCFrame
		local oldCamCF: any
		local okHook: boolean
		oldCamCF, okHook = hook(target, function(self, ...)
			local cf = oldCamCF(self, ...)
			local fn = S.h.camCF
			if S.alive and fn and typeof(cf) == "CFrame" then
				local ok, out = pcall(fn, cf)
				if ok and typeof(out) == "CFrame" then
					return out
				elseif not ok and S.hookErr then
					S.hookErr("camera hook", out)
				end
			end
			return cf
		end)
		-- installed = a detour of ours is live on the function (fresh, or from an earlier inject)
		installed.camera = okHook or S.hookedFns[target] == true
	end

	-- the menu's mouse, through the game's own camera: CameraController:Update rewrites MouseBehavior and
	-- MouseIconEnabled every render step from _Modal() (true while a game page is open), so while our
	-- menu is open _Modal answers true and the game itself frees and shows the real cursor — nothing of
	-- ours fights it frame by frame, and the frame after the menu closes the game puts its own state back
	-- (nothing to restore, nothing left locked). _InputChanged turns the camera by mouse deltas the game
	-- did not process, i.e. whenever the cursor was beside the window: dropped while the menu is open.
	h.menuMouse = function(): boolean
		if S.alive == false then return false end
		local L = genv().CenterraLibrary
		if type(L) == "table" and L.Toggled == true then
			S.menuOpen = true
			return true
		end
		return S.menuOpen == true
	end
	function Hooks.installMenuMouse()
		if not installed.menuModal and type(CameraController._Modal) == "function" then
			local oldModal: any
			local okM: boolean
			oldModal, okM = hook(CameraController._Modal, function(self, ...)
				local fn = S.h.menuMouse
				if fn and fn() then
					return true
				end
				return oldModal(self, ...)
			end)
			installed.menuModal = okM or S.hookedFns[CameraController._Modal] == true
		end
		if not installed.menuLook and type(CameraController._InputChanged) == "function" then
			local oldInput: any
			local okI: boolean
			oldInput, okI = hook(CameraController._InputChanged, function(self, input, ...)
				local fn = S.h.menuMouse
				if fn and fn() and typeof(input) == "Instance" and input.UserInputType == Enum.UserInputType.MouseMovement then
					return
				end
				return oldInput(self, input, ...)
			end)
			installed.menuLook = okI or S.hookedFns[CameraController._InputChanged] == true
		end
	end

	function Hooks.installThirdPerson()
		if installed.thirdPerson or type(CameraController.HasThirdPersonAccess) ~= "function" then
			return
		end
		local oldAccess: any
		oldAccess = hook(CameraController.HasThirdPersonAccess, function(self, ...)
			local fn = S.h.thirdPerson
			if fn and fn() then
				return true
			end
			return oldAccess(self, ...)
		end)
		installed.thirdPerson = true
	end
	-- device spoof (Interface → Device): the server hears Touch / Gamepad / VR through the game's own
	-- SetControls send — FighterController._ReplicateControls fires it on ControlsChanged with
	-- ControlsController.CurrentControls. That local value is never written: MechanicsController connects
	-- mouse-look only for "MouseKeyboard" and GetCameraCFrame switches to a VR camera for "VR", so the
	-- mouse, the menu and our aim keep working. The rewrite is a branch of the namecall hook (S.deviceControls,
	-- S.deviceVR); this installs the remote reference and the gamepad-cursor guard.
	Hooks.DEVICE_CONTROLS = { Mobile = "Touch", Controller = "Gamepad", VR = "VR" }
	-- per inject (S.h is this inject's table): the carried `installed` flags outlive a reinject, the remote
	-- refs and the tracked connection below do not
	function Hooks.installDevice()
		S.h.vrService = S.h.vrService or game:GetService("VRService")
		S.h.controlsRemote = S.h.controlsRemote or S.h.resolveControlsRemote()
		if not S.h.controlsRemote then
			log("WARN", "device: SetControls remote not found — the device spoof retries on the next change")
			return
		end
		if S.h.deviceInstalled then
			return
		end
		-- the gamepad cursor captures input: while we play on mouse and keyboard it never stays on
		local gps = game:GetService("GamepadService")
		pcall(function()
			Game.track(gps:GetPropertyChangedSignal("GamepadCursorEnabled"):Connect(function()
				if S.alive and S.deviceControls ~= nil and gps.GamepadCursorEnabled then
					local lt = UIS:GetLastInputType()
					if lt == Enum.UserInputType.Keyboard or lt == Enum.UserInputType.MouseMovement or lt == Enum.UserInputType.MouseButton1 or lt == Enum.UserInputType.MouseButton2 then
						pcall(gps.DisableGamepadCursor, gps)
					end
				end
			end))
		end)
		S.h.deviceInstalled = true
		installed.device = true
	end
	-- the device the server should hear right now: Real behind the lobby gate, else the setting. Logs and
	-- re-sends (the game's own send, 0.2 s throttle inside) only when it changes.
	function Combat.deviceApply()
		local mode = if S.featuresPaused then "Real" else (cfg.deviceSpoof or "Real")
		S.deviceControls = Hooks.DEVICE_CONTROLS[mode]
		S.deviceVR = mode == "VR"
		if mode ~= "Real" and not S.h.deviceInstalled then
			pcall(Hooks.installDevice)
		end
		if mode == S.deviceMode then
			return
		end
		local first = S.deviceMode == nil
		S.deviceMode = mode
		if first and mode == "Real" then
			return
		end
		log("INFO", "device: " .. mode)
		if FighterController and type(FighterController._ReplicateControls) == "function" then
			pcall(Game.asGame, FighterController._ReplicateControls, FighterController)
		end
	end

	-- fighter-class hooks need an instance to reach the class table. The local player is a
	-- ClientFighter subclass and enemies are plain Fighters: a method overridden in the subclass is a
	-- different function → hook whichever class chain we are handed, once per function object.
	S.hookedFns = S.hookedFns or setmetatable({}, { __mode = "k" })
	function Hooks.installFighter(anyFighter: any)
		if type(anyFighter) ~= "table" or anyFighter._fallback then
			return
		end
		local mt = getmetatable(anyFighter)
		local cls = mt and mt.__index
		if type(cls) ~= "table" then
			return
		end
		local isLocal = anyFighter.IsLocalPlayer == true
		if (isLocal and installed.fighterLocal) or (not isLocal and installed.fighterEnemy) then
			return
		end
		-- hook() marks S.hookedFns on success; here we only ask (a pre-mark made hook() refuse)
		local hooked = S.hookedFns
		local function once(fn: any): boolean
			return fn ~= nil and not hooked[fn]
		end
		local getMouse = classMethod(cls, "GetMouseLocation")
		if getMouse and once(getMouse) then
			local oldMouse: any
			oldMouse = hook(getMouse, function(self, ...)
				local fn = S.h.mouse
				if S.alive and fn then
					local ok, v = pcall(fn)
					if ok and typeof(v) == "Vector2" then
						return v
					elseif not ok and S.hookErr then
						S.hookErr("mouse hook", v)
					end
				end
				return oldMouse(self, ...)
			end)
		end
		local getRot = classMethod(cls, "GetCameraRotation")
		if getRot and once(getRot) then
			local oldRot: any
			oldRot = hook(getRot, function(self, ...)
				local orig = oldRot(self, ...)
				local fn = S.h.rot
				-- the caller lookup (pcall + getcallingscript) only when a spoof is possible at all:
				-- this method is read every frame by camera / animation / replication code
				local st = S.cfg
				if S.alive and fn and typeof(orig) == "Vector2" and st and (st.aaEnabled or (st.silentSpoofServer and S.silentTarget ~= nil)) then
					local ok, v = pcall(fn, orig, S.h.callerName())
					if ok and typeof(v) == "Vector2" then
						return v
					elseif not ok and S.hookErr then
						S.hookErr("rotation hook", v)
					end
				end
				return orig
			end)
		end
		-- layer 0: the replicated camera data (see h.cameraData)
		local getCD = classMethod(cls, "GetCameraData")
		if getCD and once(getCD) then
			local oldCD: any
			oldCD = hook(getCD, function(self, ...)
				local nargs = select("#", ...)
				-- Melee.StartShooting reads TWO returns (`local data, hit = GetCameraData()`) and its
				-- impact marker indexes the second — keep every return value, replace only the first
				local rets = table.pack(oldCD(self, ...))
				local t = rets[1]
				local fn = S.h.cameraData
				-- diagnostics: count every call, 0-arg calls, and local-player 0-arg calls, so an empty
				-- recorder can be traced to which filter dropped the shot (Debug → Live / centerra_state)
				local d = S.cdDbg
				if d then
					d.calls += 1
					if nargs == 0 then
						d.zeroArg += 1
						local okL, isLocal = pcall(function()
							return type(self) == "table" and self.IsLocalPlayer == true
						end)
						if okL and isLocal then
							d.localZero += 1
						end
					end
				end
				if S.alive and fn and type(t) == "table" and type(self) == "table" and self.IsLocalPlayer == true then
					local ok, out = pcall(fn, t, self, nargs)
					if ok and type(out) == "table" then
						rets[1] = out
					elseif not ok and S.hookErr then
						S.hookErr("camera data hook", out)
					end
				end
				return table.unpack(rets, 1, rets.n)
			end)
			installed.cameraData = true
		end
		-- CanSlide / CanSprint: the same pass-through shape, guarded (an error in our logic must
		-- never reach the game's movement code)
		local canSlide = classMethod(cls, "CanSlide")
		if canSlide and once(canSlide) then
			local oldSlide: any
			oldSlide = hook(canSlide, function(self, ...)
				local orig = oldSlide(self, ...)
				local fn = S.h.canSlide
				return if fn then Hooks.guarded("CanSlide hook", orig, fn, orig) else orig
			end)
		end
		local canSprint = classMethod(cls, "CanSprint")
		if canSprint and once(canSprint) then
			local oldSprint: any
			oldSprint = hook(canSprint, function(self, ...)
				local orig = oldSprint(self, ...)
				local fn = S.h.canSprint
				return if fn then Hooks.guarded("CanSprint hook", orig, fn, orig) else orig
			end)
		end
		local isCrouch = classMethod(cls, "IsCrouching")
		if isCrouch and once(isCrouch) then
			local oldCrouch: any
			oldCrouch = hook(isCrouch, function(self, ...)
				local orig = oldCrouch(self, ...)
				local fn = S.h.crouch
				-- IsCrouching is queried every frame by camera, mechanics and animation code: the
				-- caller lookup only runs while fake duck is on
				local st = S.cfg
				if fn and st and st.fakeDuck then
					return Hooks.guarded("IsCrouching hook", orig, fn, orig, S.h.callerName())
				end
				return orig
			end)
		end
		-- the server tells our fighter when a hit landed on spawn protection (IMMUNE popup)
		local immune = classMethod(cls, "_ImmuneDamageEffect")
		if isLocal and immune and once(immune) then
			local oldImm: any
			oldImm = hook(immune, function(self, ...)
				local fn = S.h.immuneHit
				if S.alive and fn and type(self) == "table" and self.IsLocalPlayer == true then
					pcall(fn)
				end
				return oldImm(self, ...)
			end)
		end
		if isLocal then
			installed.fighterLocal = true
		else
			installed.fighterEnemy = true
		end
		installed.fighter = installed.fighterLocal == true -- the local chain is the one replication reads
		log("INFO", ("hooks: fighter class [%s] (GetMouseLocation, GetCameraRotation, GetCameraData%s, CanSlide, CanSprint, IsCrouching)"):format(if isLocal then "local ClientFighter" else "enemy Fighter", if getCD then "" else " MISSING"))
	end

	function Hooks.installGun()
		if installed.gun then
			return
		end
		local mods = LP.PlayerScripts:FindFirstChild("Modules")
		local types = mods and mods:FindFirstChild("ItemTypes")
		local Gun = Game.requireIfLoaded(types and types:FindFirstChild("Gun"))
		if type(Gun) ~= "table" then
			-- the game loads Gun with the first gun in hand (the lobby has none): retried from the loop, and
			-- the add-on does not report it as a missing hook meanwhile
			installed.gunWaiting = true
			return
		end
		installed.gunWaiting = nil
		local ok = pcall(function()
			for _, m in ipairs({ "_Recoil", "_Shake", "_ShakeOnce" }) do
				local fn = classMethod(Gun, m)
				if fn then
					local old: any
					old = hook(fn, function(self, ...)
						local blocked = S.h.recoilBlocked
						if blocked and blocked() then
							return
						end
						return old(self, ...)
					end)
				end
			end
			local startReload = classMethod(Gun, "StartReloading")
			if startReload then
				local oldReload: any
				oldReload = hook(startReload, function(self, ...)
					local r = table.pack(oldReload(self, ...))
					local fn = S.h.afterReload
					if fn then
						Hooks.guarded("reload hook", nil, fn, self)
					end
					return table.unpack(r, 1, r.n)
				end)
			end
			-- skins: the gun reads item:GetWrap() when it applies the viewmodel/projectile wrap
			-- (WrapController:ApplyWrap). A local (unowned) wrap the server never granted only reaches
			-- the world model this way — the GetWeaponData hook alone updates the customize UI, not the
			-- in-round viewmodel. Return the local wrap's data for our own items when unlock is on.
			local getWrap = classMethod(Gun, "GetWrap")
			if getWrap then
				local oldGetWrap: any
				oldGetWrap = hook(getWrap, function(self, ...)
					local orig = oldGetWrap(self, ...)
					local fn = S.h.wrapFor
					if fn and type(self) == "table" and self.ClientFighter and self.ClientFighter.IsLocalPlayer == true then
						local ok, w = pcall(fn, self.Name, orig)
						if ok and w ~= nil then
							return w
						end
					end
					return orig
				end)
				installed.wrap = true
			end
			-- server truth per shot: the server's own raycast results come back through ShootEffect
			local shootEffect = classMethod(Gun, "_ShootEffect")
			if shootEffect then
				local oldSE: any
				oldSE = hook(shootEffect, function(self, results, ...)
					local fn = S.h.serverShot
					if fn then
						local okS, err = pcall(fn, self, results)
						if not okS and S.hookErr then
							S.hookErr("shoot effect hook", err)
						end
					end
					return oldSE(self, results, ...)
				end)
				installed.shootEffect = true
			end
			-- v5 spread claim: Gun.StartShooting replicates `isFullyAiming` as the 4th value of its
			-- return tuple and the server multiplies its spread cone by AimSpreadMultiplier (0 on most
			-- guns) when it is truthy — a client claim (range-verified: identical server offsets on every
			-- hip-fire sniper shot with the claim, random 15° misses without). The real answer stays
			-- reachable as S.h.realFullyAiming for our own gates and the Debug panel.
			local fullyAiming = classMethod(Gun, "IsFullyAiming")
			if fullyAiming then
				local oldFA: any
				local hookedFA
				oldFA, hookedFA = hook(fullyAiming, function(self, ...)
					local fn = S.h.claimAim
					if fn and fn(self) then
						return true
					end
					return oldFA(self, ...)
				end)
				if hookedFA then
					S.hookOrig.gunIsFullyAiming = oldFA -- h.realFullyAiming (live logic) reads this across re-injects
				end
				installed.spreadClaim = true
			end
		end)
		if ok then
			installed.gun = true
			log("INFO", ("hooks: gun class (_Recoil, _Shake, _ShakeOnce, StartReloading%s%s%s)"):format(if installed.wrap then ", GetWrap" else "", if installed.shootEffect then ", _ShootEffect" else "", if installed.spreadClaim then ", IsFullyAiming" else ""))
		else
			log("WARN", "hooks: gun class not found")
		end
	end

	-- v6.7 the fire gate: every StartShooting of a gun or blade asks S.h.fireGate whether the round goes to
	-- the server ("pass"), stays on your screen ("client": the item's own animation / tracer / recoil /
	-- cooldown stamp run, the returned tuple is withheld so ClientFighter:Input sends nothing), or waits
	-- ("block": voidspam brings the body back first). Own install flags, so a session whose gun hooks an
	-- older build installed still gets these; the Gun / Melee modules load with the first item in hand.
	function Hooks.installFire()
		local mods = LP.PlayerScripts:FindFirstChild("Modules")
		local types = mods and mods:FindFirstChild("ItemTypes")
		if not types then
			return
		end
		for _, kind in ipairs({ "Gun", "Melee" }) do
			local flag = "fire" .. kind
			if not installed[flag] then
				local cls = Game.requireIfLoaded(types:FindFirstChild(kind))
				local fn = if type(cls) == "table" then classMethod(cls, "StartShooting") else nil
				if fn then
					local old: any
					local hooked: boolean
					old, hooked = hook(fn, function(self, ...)
						local gate = S.h.fireGate
						if not (gate and S.alive) then
							return old(self, ...)
						end
						local okG, how = pcall(gate, self, ...)
						if not okG or how == nil or how == "pass" then
							local r = table.pack(old(self, ...))
							local done = S.h.fireDone
							if r[1] == true and done then
								pcall(done, self, "pass")
							end
							return table.unpack(r, 1, r.n)
						end
						if how == "block" then
							return false
						end
						S.fireClientOnly = true
						local okR, shot = pcall(old, self, ...)
						S.fireClientOnly = false
						local done = S.h.fireDone
						if okR and shot == true and done then
							pcall(done, self, "client")
						end
						return false
					end)
					if hooked then
						installed[flag] = true
						log("INFO", ("hooks: %s.StartShooting (fire gate: rapid %s on screen, server-safe sends, voidspam hold)"):format(kind, if kind == "Gun" then "fire" else "melee"))
					end
				end
			end
		end
	end

	-- the viewmodel's own GetWrap is what paints the EQUIPPED weapon (ClientViewModel:_UpdateWrap →
	-- WrapController:ApplyWrap(record, GetWrap())). Hooking it — and re-applying via _UpdateWrap —
	-- is what makes a selected skin/wrap actually show in-hand. Different function from the gun's.
	function Hooks.installViewModel()
		if installed.viewModel and installed.vmCreate then
			return
		end
		local mods = LP.PlayerScripts:FindFirstChild("Modules")
		local crc = mods and mods:FindFirstChild("ClientReplicatedClasses")
		local cf = crc and crc:FindFirstChild("ClientFighter")
		local ci = cf and cf:FindFirstChild("ClientItem")
		local cvmMod = ci and ci:FindFirstChild("ClientViewModel")
		local CVM = Game.requireIfLoaded(cvmMod)
		if type(CVM) ~= "table" then
			return -- not loaded yet (retried from the loop)
		end
		local getWrap = classMethod(CVM, "GetWrap")
		if getWrap and not S.hookedFns[getWrap] then
			local oldVMWrap: any
			oldVMWrap = hook(getWrap, function(self, ...)
				local orig = oldVMWrap(self, ...)
				local fn = S.h.wrapFor
				local ci2 = type(self) == "table" and self.ClientItem
				local isLocal = type(ci2) == "table" and ci2.ClientFighter and ci2.ClientFighter.IsLocalPlayer == true
				if fn and isLocal then
					local ok, w = pcall(fn, ci2.Name, orig)
					if ok and w ~= nil then
						return w
					end
				elseif not isLocal and type(ci2) == "table" then
					local sw = S.h.sharedWrapFor
					if sw then
						local ok, w = pcall(sw, ci2)
						if ok and w ~= nil then
							return w
						end
					end
				end
				return orig
			end)
		elseif not getWrap then
			log("WARN", "hooks: ClientViewModel.GetWrap not found")
		end
		-- model skins: the serial the game builds each viewmodel from passes through
		-- ClientItem:_CreateViewModel(serial) (compressed wire shape) and ClientViewModel.new(decoded,
		-- item). Both get the Name rewritten for our own items when a local model skin is chosen; the
		-- untouched serial is kept on the item so Skins.rebuild can build again with another skin.
		local function skinFor(item: any): string?
			local fn = S.h.skinModelFor
			if not (S.alive and fn and type(item) == "table") then
				return nil
			end
			local cf2 = item.ClientFighter
			if not (type(cf2) == "table" and cf2.IsLocalPlayer == true) then
				local sf = S.h.sharedSkinFor
				if not (sf and type(cf2) == "table") then
					return nil
				end
				local okS, shared = pcall(sf, item)
				return if okS and type(shared) == "string" then shared else nil
			end
			local ok, name = pcall(fn, item.Name)
			return if ok and type(name) == "string" then name else nil
		end
		local vmNew = rawget(CVM, "new")
		if type(vmNew) == "function" and not S.hookedFns[vmNew] then
			local oldNew: any
			oldNew = hook(vmNew, function(serial, item, ...)
				local skin = skinFor(item)
				if skin and type(serial) == "table" then
					local ok, patched = pcall(S.h.patchVmSerial, serial, item.Name, skin)
					if ok and patched then
						serial = patched
					end
				end
				return oldNew(serial, item, ...)
			end)
			installed.vmNew = true
		end
		local ClientItemMod = ci
		local CI = Game.requireIfLoaded(ClientItemMod)
		if type(CI) == "table" then
			local createVm = classMethod(CI, "_CreateViewModel")
			if createVm and not S.hookedFns[createVm] then
				local oldCreate: any
				oldCreate = hook(createVm, function(self, serial, ...)
					if S.alive and type(self) == "table" and type(serial) == "table" then
						local cf2 = self.ClientFighter
						if type(cf2) == "table" and cf2.IsLocalPlayer == true and not rawget(self, "_centerraRebuild") then
							-- remember the server's serial (the rebuild path passes its own copy); the clone
							-- helper is read from the live state, never a per-inject upvalue
							local clone = S.deepClone
							if clone then
								pcall(rawset, self, "_centerraVmSerial", clone(serial))
							end
						end
						local skin = skinFor(self)
						if skin then
							local ok, patched = pcall(S.h.patchVmSerial, serial, self.Name, skin)
							if ok and patched then
								serial = patched
							end
						end
					end
					return oldCreate(self, serial, ...)
				end)
				installed.vmCreate = true
			end
			-- GetViewModelDetails only reports the built viewmodel; keep it truthful (the game reads
			-- it for hotbar images), so it names the skin only once that model is really in hand
			local getDetails = classMethod(CI, "GetViewModelDetails")
			if getDetails and not S.hookedFns[getDetails] then
				local oldDetails: any
				oldDetails = hook(getDetails, function(self, ...)
					local det = oldDetails(self, ...)
					local skin = skinFor(self)
					if skin and type(det) == "table" then
						local vm = rawget(self, "ViewModel")
						if type(vm) == "table" and vm.Name == skin and det.ViewModelName ~= skin then
							local out = {}
							for k, v in pairs(det) do
								out[k] = v
							end
							out.ViewModelName = skin
							return out
						end
					end
					return det
				end)
			end
		end
		installed.viewModel = true
		-- once per outcome: the loop retries while vmCreate is missing (twice a second)
		local line = ("hooks: ClientViewModel (GetWrap, new) + ClientItem (%s)"):format(if installed.vmCreate then "_CreateViewModel → skin model, GetViewModelDetails" else "GetViewModelDetails only")
		if Hooks.vmLine ~= line then
			Hooks.vmLine = line
			log("INFO", line)
		end
	end

	-- repair dead layers: a function marked as hooked (S.hookedFns) whose detour belongs to an abandoned
	-- state (a test nil-ed CenterraState, a build before 6.6.2 skipped every foreign detour) never answers
	-- and hook() refuses to stack on it. Restore the game's function, forget the mark, install again.
	-- Restoring one of our own live detours is harmless (the new one reads the same S.h).
	function Hooks.rearm(fn: any)
		if type(fn) ~= "function" then
			return
		end
		if type(EXEC.restorefunction) == "function" then
			pcall(EXEC.restorefunction, fn)
		end
		S.hookedFns[fn] = nil
	end
	Hooks.FIGHTER_METHODS = { "GetMouseLocation", "GetCameraRotation", "GetCameraData", "CanSlide", "CanSprint", "IsCrouching", "_ImmuneDamageEffect" }
	function Hooks.repair(why: string)
		Hooks.rearm(CameraController.GetCameraCFrame)
		installed.camera = false
		pcall(Hooks.installCamera)
		local fighters = { Game.localFighter(), Game.enemies()[1] }
		for _, f in ipairs(fighters) do
			local mt = type(f) == "table" and not f._fallback and getmetatable(f)
			local cls = mt and mt.__index
			if type(cls) == "table" then
				for _, name in ipairs(Hooks.FIGHTER_METHODS) do
					Hooks.rearm(classMethod(cls, name))
				end
			end
		end
		installed.fighterLocal, installed.fighterEnemy, installed.fighter, installed.cameraData = nil, nil, nil, nil
		for _, f in ipairs(fighters) do
			if type(f) == "table" then
				pcall(Hooks.installFighter, f)
			end
		end
		local mods = LP.PlayerScripts:FindFirstChild("Modules")
		local crc = mods and mods:FindFirstChild("ClientReplicatedClasses")
		local cf = crc and crc:FindFirstChild("ClientFighter")
		local ciMod = cf and cf:FindFirstChild("ClientItem")
		local CI = Game.requireIfLoaded(ciMod)
		local CVM = Game.requireIfLoaded(ciMod and ciMod:FindFirstChild("ClientViewModel"))
		if type(CI) == "table" and type(CVM) == "table" then
			Hooks.rearm(classMethod(CVM, "GetWrap"))
			Hooks.rearm(rawget(CVM, "new"))
			Hooks.rearm(classMethod(CI, "_CreateViewModel"))
			Hooks.rearm(classMethod(CI, "GetViewModelDetails"))
			installed.viewModel, installed.vmCreate, installed.vmNew = nil, nil, nil
			pcall(Hooks.installViewModel)
		end
		log("INFO", ("hooks: repaired (%s) — camera=%s cameraData=%s vmCreate=%s"):format(why, tostring(installed.camera == true), tostring(installed.cameraData == true), tostring(installed.vmCreate == true)))
	end
	-- the flags themselves betray a dead mark: the fighter chain "installed" without GetCameraData, or
	-- the viewmodel group without _CreateViewModel, while the function is marked as hooked
	function Hooks.staleMarks(): boolean
		local lf = Game.localFighter()
		if installed.fighterLocal and not installed.cameraData and type(lf) == "table" and not lf._fallback then
			local mt = getmetatable(lf)
			local getCD = mt and type(mt.__index) == "table" and classMethod(mt.__index, "GetCameraData")
			if getCD and S.hookedFns[getCD] then
				return true
			end
		end
		if installed.viewModel and not installed.vmCreate then
			local mods = LP.PlayerScripts:FindFirstChild("Modules")
			local crc = mods and mods:FindFirstChild("ClientReplicatedClasses")
			local cf = crc and crc:FindFirstChild("ClientFighter")
			local CI = Game.requireIfLoaded(cf and cf:FindFirstChild("ClientItem"))
			local createVm = type(CI) == "table" and classMethod(CI, "_CreateViewModel")
			if createVm and S.hookedFns[createVm] then
				return true
			end
		end
		return false
	end
	-- re-apply the wrap on the currently held viewmodel so a just-selected skin shows immediately
	h.updateHeldWrap = function()
		local lf = Game.localFighter()
		local item = lf and Game.activeItem(lf)
		local vm = item and item.ViewModel
		if type(vm) == "table" and type(vm._UpdateWrap) == "function" then
			Game.asGame(vm._UpdateWrap, vm)
			return true
		end
		return false
	end

	function Hooks.installCosmetics()
		if installed.cosmetics then
			return
		end
		if PlayerDataController._stub or CosmeticLibrary._stub then
			-- v5.2: the data / cosmetic library is gone (game update) → no inventory to fake; the
			-- self-test / integrity treat the group as "n/a" instead of reinstalling it every 10 s
			installed.cosmetics = "n/a"
			return
		end
		local oldGet: any
		oldGet = hook(PlayerDataController.Get, function(self, key, ...)
			-- every return value is kept; only the inventory table is swapped
			local r = table.pack(oldGet(self, key, ...))
			local data = r[1]
			local fi = S.h.fakeInventory
			if S.alive and fi and S.cfg.unlockCosmetics and select("#", ...) == 0 and S.h.isCosKey(key) and (self == S.h.pdc or self == S.h.pdc.CurrentData) then
				r[1] = Hooks.guarded("inventory hook", data, fi, data)
			end
			return table.unpack(r, 1, r.n)
		end)
		for _, fname in ipairs({ "OwnsCosmetic", "OwnsCosmeticNormally", "OwnsCosmeticUniversally", "OwnsCosmeticForWeapon", "OwnsCosmeticForSomething" }) do
			local target = CosmeticLibrary[fname]
			if type(target) == "function" then
				local old: any
				old = hook(target, function(self, inv, name, ...)
					local un = S.h.unlockable
					if un and Hooks.guarded("owns hook", false, un, name) then
						return true
					end
					return old(self, inv, name, ...)
				end)
			end
		end
		if type(CosmeticLibrary.HasNotification) == "function" then
			local oldNotif: any
			oldNotif = hook(CosmeticLibrary.HasNotification, function(...)
				if S.alive and S.cfg.unlockCosmetics then
					return false
				end
				return oldNotif(...)
			end)
		end
		if type(PlayerDataController.GetWeaponData) == "function" then
			local oldWeaponData: any
			oldWeaponData = hook(PlayerDataController.GetWeaponData, function(self, weaponName, ...)
				local r = table.pack(oldWeaponData(self, weaponName, ...))
				local fn = S.h.weaponData
				if S.alive and fn then
					-- Skins.weaponData clones the record (throws on a protected metatable): guarded
					r[1] = Hooks.guarded("weapon data hook", r[1], fn, r[1], weaponName)
				end
				return table.unpack(r, 1, r.n)
			end)
		end
		installed.cosmetics = true
		log("INFO", "hooks: cosmetics (Get, Owns*, GetWeaponData)")
		Hooks.installCosmeticUi()
	end
	-- scope overlay (sniper vignette) lives in ItemInterface:SetScopeActive — answer "off" while wanted
	function Hooks.installItemInterface()
		if installed.itemInterface then
			return
		end
		local mods = LP.PlayerScripts:FindFirstChild("Modules")
		local II = Game.requireIfLoaded(mods and mods:FindFirstChild("ItemInterface"))
		if type(II) ~= "table" or type(II.SetScopeActive) ~= "function" then
			return
		end
		installed.itemInterface = true
		local oldScope: any
		oldScope = hook(II.SetScopeActive, function(self, active, ...)
			if S.alive and S.cfg.noScopeOverlay and active then
				return oldScope(self, false, ...)
			end
			return oldScope(self, active, ...)
		end)
		log("INFO", "hooks: item interface (SetScopeActive)")
	end
	-- body rotation owner: MechanicsController._UpdateCharacterRotation rewrites RootPart.CFrame from
	-- the rendered camera on every RenderStepped; our yaw is applied right after it (see Combat)
	function Hooks.installMechanics()
		if installed.mechanics then
			return
		end
		local MC = Input.mechanics and Input.mechanics()
		if type(MC) ~= "table" then
			return
		end
		local upd = classMethod(MC, "_UpdateCharacterRotation")
		if not upd then
			installed.mechanics = true
			log("WARN", "hooks: MechanicsController._UpdateCharacterRotation not found — body anti-aim falls back to Heartbeat")
			return
		end
		if not S.hookedFns[upd] then
			local oldUpd: any
			oldUpd = hook(upd, function(self, ...)
				local r = table.pack(oldUpd(self, ...))
				local fn = S.h.afterCharRot
				if S.alive and fn then
					local ok, err = pcall(fn)
					if not ok and S.hookErr then
						S.hookErr("body yaw hook", err)
					end
				end
				return table.unpack(r, 1, r.n)
			end)
		end
		installed.mechanics = true
		log("INFO", "hooks: MechanicsController (_UpdateCharacterRotation → body yaw)")
	end
	-- v6.7 speed boost / no ADS slowdown: MechanicsController._GetWalkSpeed is what _UpdateWalkSpeed writes
	-- into the Humanoid every frame (sprint, crouch, emote, the item's WalkSpeedMultiplier, the freeze).
	-- Adjusting its answer works armed or unarmed and never races the game — scaling the item stat did
	-- nothing without a weapon out, and writing WalkSpeed after the game lost every other frame.
	function Hooks.installWalkSpeed()
		if installed.walkSpeed then
			return
		end
		local MC = Input.mechanics and Input.mechanics()
		if type(MC) ~= "table" then
			return
		end
		local fn = classMethod(MC, "_GetWalkSpeed")
		if type(fn) ~= "function" then
			installed.walkSpeed = true
			log("WARN", "hooks: MechanicsController._GetWalkSpeed not found — speed boost scales the weapon stat instead")
			return
		end
		local old: any
		local hooked
		old, hooked = hook(fn, function(self, ...)
			local speed = old(self, ...)
			local adj = S.h.walkSpeed
			if adj and S.alive then
				local ok, v = pcall(adj, speed, self)
				if ok and type(v) == "number" then
					return v
				end
			end
			return speed
		end)
		if hooked then
			installed.walkSpeed = true
			log("INFO", "hooks: MechanicsController._GetWalkSpeed (speed boost, no ADS slowdown)")
		end
	end
	-- the customize-UI modules only exist once the game required them (lobby); retried from the loop
	function Hooks.installCosmeticUi()
		if installed.cosmeticUi then
			return
		end
		local mods = LP.PlayerScripts:FindFirstChild("Modules")
		local CosmeticSlot = Game.requireIfLoaded(mods and mods:FindFirstChild("CosmeticSlot"))
		local uiRoot = mods and mods:FindFirstChild("UserInterface")
		local Equipment = Game.requireIfLoaded(uiRoot and uiRoot:FindFirstChild("Equipment"))
		if type(CosmeticSlot) ~= "table" or type(Equipment) ~= "table" then
			return
		end
		installed.cosmeticUi = true
		pcall(function()
			local oldSetInteractable: any
			oldSetInteractable = hook(CosmeticSlot.SetInteractable, function(self, interactable, ...)
				if S.alive and S.cfg.unlockCosmetics then
					return oldSetInteractable(self, true, ...)
				end
				return oldSetInteractable(self, interactable, ...)
			end)
		end)
		pcall(function()
			if type(Equipment.SelectCosmetic) == "function" then
				local oldSel: any
				oldSel = hook(Equipment.SelectCosmetic, function(self, ...)
					local lg = S.log -- the live instance's logger, not a per-inject upvalue
					if S.alive and S.cfg.unlockCosmetics and S.cfg.debugConsole and lg then
						local a, b, c = ...
						lg("DEBUG", "skins: SelectCosmetic", tostring(a), tostring(b), tostring(c))
					end
					return oldSel(self, ...)
				end)
			end
		end)
		log("INFO", "hooks: customize UI (SetInteractable, SelectCosmetic)")
	end

	function Hooks.installNamecall()
		if installed.namecall or not (EXEC.hookmetamethod and EXEC.getnamecallmethod) then
			return
		end
		local oldNc: any
		-- Madium / Potassium: any `x:Method()` we run in here (CFrame:ToOrientation, Vector3:Dot…) replaces
		-- the pending namecall method, and the original then calls THAT on the remote ("ToOrientation is
		-- not a valid member of UnreliableRemoteEvent" — 99 site errors, 2 users). Put the name back first.
		local setNc = EXEC.setnamecallmethod
		local function callOld(method: string, self: any, ...): ...any
			if setNc then
				pcall(setNc, method)
			end
			return oldNc(self, ...)
		end
		-- everything of ours runs inside this (pcall-guarded, never yields); returns handled, result
		local function ncLogic(self, method, ...): (boolean, any)
			local st = S.cfg
			-- the caller lookup (pcall + getcallingscript) is the expensive part and MechanicsController
			-- raycasts constantly for slides / reach / tracers: a plain Raycast shorter than the shot
			-- ray's 40 studs can never be ours, so it never pays for the lookup
			local castCandidate = self == workspace and (st.silentAim or S.cfgOverrideSilent) and (st.silentRaycastLayer or st.magicBullet) and S.h.redirect ~= nil
			if castCandidate and method == "Raycast" then
				local dirQ = select(2, ...)
				if typeof(dirQ) ~= "Vector3" or dirQ.Magnitude < 40 then
					castCandidate = false
				end
			end
			if castCandidate and S.h.callerIsShotCode() then
				if method == "Raycast" then
					local origin, dir, params = ...
					if typeof(origin) == "Vector3" and typeof(dir) == "Vector3" then
						if S.rayTrace then
							-- diagnostics ring (property reads only): who casts what from where
							local cam = workspace.CurrentCamera
							local rt = S.rayTraceBuf
							table.insert(rt, {
								t = os.clock(),
								len = dir.Magnitude,
								fromCam = if cam then (origin - cam.CFrame.Position).Magnitude else -1,
								caller = S.h.callerName(),
								ft = if typeof(params) == "RaycastParams" then tostring(params.FilterType) else "nil",
								n = if typeof(params) == "RaycastParams" then #params.FilterDescendantsInstances else -1,
							})
							if #rt > 300 then
								table.remove(rt, 1)
							end
						end
						local newDir, newParams, newOrigin, straight = S.h.redirect(origin, dir, params)
						if newDir then
							local from = newOrigin or origin
							local res = callOld(method, self, from, newDir, newParams)
							if S.h.recordShot and not straight then
								pcall(S.h.recordShot, res, from, newDir, newParams)
							end
							return true, res
						end
						if S.h.sampleSpread and S.h.isOurShotRay(origin, dir) then
							pcall(S.h.sampleSpread, dir)
						end
					end
				elseif method == "Blockcast" then
					local cf, size, dir, params = ...
					if typeof(cf) == "CFrame" and typeof(dir) == "Vector3" then
						local newDir, newParams, newOrigin = S.h.redirect(cf.Position, dir, params)
						if newDir then
							local from = if newOrigin then CFrame.new(newOrigin) * cf.Rotation else cf
							return true, callOld(method, self, from, size, newDir, newParams)
						end
					end
				elseif method == "Spherecast" then
					local pos, radius, dir, params = ...
					if typeof(pos) == "Vector3" and typeof(dir) == "Vector3" then
						local newDir, newParams, newOrigin = S.h.redirect(pos, dir, params)
						if newDir then
							return true, callOld(method, self, newOrigin or pos, radius, newDir, newParams)
						end
					end
				end
			end
			if st.remoteSpy and (method == "FireServer" or method == "InvokeServer") and S.h.spyRemote then
				pcall(S.h.spyRemote, self, method, ...)
			end
			-- v5 OOB guard, second line: the client's own "I am out of bounds" report never leaves. Until the
			-- remote resolves, a FireServer on anything named OutOfBounds counts (a property read, no method)
			if method == "FireServer" and st.oobBlock and not S.featuresPaused then
				local oobR = S.h.oobRemote
				if (oobR ~= nil and self == oobR) or (oobR == nil and self.Name == "OutOfBounds") then
					S.oobSwallowed = (S.oobSwallowed or 0) + 1
					return true, nil
				end
			end
			-- anti-aim / lock-facing rotation: rewrite the payload of the game's own replication send
			if method == "FireServer" and S.h.rotRemote and self == S.h.rotRemote and S.h.replicatedPayload then
				local enc = S.h.replicatedPayload()
				if enc then
					-- only the first argument is ours; everything after it is forwarded as sent
					return true, callOld(method, self, enc, select(2, ...))
				end
			end
			-- device spoof: the server hears the spoofed device through the game's own SetControls send; the
			-- local CurrentControls stays real (Hooks.installDevice). VR also reports its user cframe on.
			if method == "FireServer" and S.deviceControls and S.h.controlsRemote and self == S.h.controlsRemote then
				return true, callOld(method, self, S.deviceControls, select(2, ...))
			end
			if S.deviceVR and S.h.vrService and self == S.h.vrService then
				if method == "GetUserCFrameEnabled" then
					return true, true
				elseif method == "GetUserCFrame" then
					return true, CFrame.identity
				end
			end
			-- (the old `Get` branch here could never match: `self` in an Instance __namecall is a
			-- userdata while PlayerDataController is a Lua table — that interception is the
			-- hookfunction in installCosmetics)
			if st.unlockCosmetics and S.h.fakeInventory then
				if S.h.equipRemote and self == S.h.equipRemote and (method == "FireServer" or method == "InvokeServer") then
					-- cosmetics you really own, "None" (nil) and "Random" go to the server exactly as before —
					-- that equip is server-side and everyone sees it. Only unowned ones are swallowed and
					-- applied locally. A real equip replaces the local one for that slot (persisted +
					-- re-applied off-thread: no Instance methods may run inside this hook).
					local weaponName, cosType, cosName, options = ...
					local owned = S.h.reallyOwned and S.h.reallyOwned(cosName, weaponName)
					if cosName == nil or cosName == "None" or cosName == "NONE_COSMETIC" or cosName == "RANDOM_COSMETIC" or owned then
						if type(weaponName) == "string" and type(cosType) == "string" and S.localEquips[weaponName] and S.localEquips[weaponName][cosType] ~= nil then
							S.localEquips[weaponName][cosType] = nil
							if S.h.localEquipReplaced then
								task.defer(S.h.localEquipReplaced, weaponName, cosType)
							end
						end
						return false, nil
					end
					if S.h.unlockable(cosName) then
						task.defer(S.h.applyLocalEquip, weaponName, cosType, cosName, options)
						return true, nil
					end
				end
			end
			return false, nil
		end
		-- hot path: one table lookup decides whether this method can be ours at all. v5.2: the loop
		-- publishes what the live config wants this frame (S.ncCast — silent / magic redirect or a ray
		-- trace; S.ncRemote — remote spy / OOB swallow / rotation rewrite / cosmetic swallow), so a cast
		-- or a remote nobody is interested in costs one table read instead of a pcall plus the whole
		-- logic. nil (an older loop that never published) counts as "wanted".
		local NC_CAST = { Raycast = true, Blockcast = true, Spherecast = true }
		local NC_REMOTE = { FireServer = true, InvokeServer = true }
		local NC_VR = { GetUserCFrameEnabled = true, GetUserCFrame = true }
		local nc = function(self, ...)
			if S.alive then
				local method = EXEC.getnamecallmethod()
				-- the OOB guard is always wanted while it is on (S.ncRemote is published by the scan step, a frame late)
				local want = if NC_CAST[method] then (S.ncCast ~= false or S.cfgOverrideSilent == true) elseif NC_REMOTE[method] then (S.ncRemote ~= false or S.cfg.oobBlock == true) elseif NC_VR[method] then S.deviceVR == true else false
				if want then
					local ok, handled, res = pcall(ncLogic, self, method, ...)
					if ok then
						if handled then
							return res
						end
					elseif S.hookErr then
						-- report later: logging touches GUI methods, which would clobber the namecall method
						task.defer(S.hookErr, "namecall hook", handled)
					end
					-- our logic ran (and may have made method calls): hand the original its own name back
					return callOld(method, self, ...)
				end
			end
			return oldNc(self, ...)
		end
		-- plain Lua closure: RemoteFunction:InvokeServer yields through here. Executors whose
		-- hookmetamethod wraps a non-yieldable newcclosure freeze the client on that yield
		-- ("cannot resume dead coroutine"), so those get a raw metatable swap instead.
		if EXEC.ncYields == false and type(EXEC.getrawmetatable) == "function" then
			local mt = EXEC.getrawmetatable(game)
			local oldPlain: any = nil
			if type(mt) == "table" then
				if type(EXEC.setreadonly) == "function" then
					pcall(EXEC.setreadonly, mt, false)
				end
				oldPlain = rawget(mt, "__namecall")
				if type(oldPlain) ~= "function" then
					local okOld, v = pcall(function()
						return mt.__namecall
					end)
					oldPlain = if okOld then v else nil
				end
				if type(oldPlain) == "function" then
					rawset(mt, "__namecall", nc)
				end
				if type(EXEC.setreadonly) == "function" then
					pcall(EXEC.setreadonly, mt, true)
				end
			end
			if type(oldPlain) == "function" then
				oldNc = oldPlain
				log("INFO", "hooks: __namecall plain closure (newcclosure cannot yield on this executor)")
			else
				-- hookmetamethod would wrap a non-yieldable closure and freeze the client. Skip.
				log("WARN", "hooks: __namecall skipped — this executor cannot host a yielding namecall hook")
			end
		else
			oldNc = EXEC.hookmetamethod(game, "__namecall", nc)
		end
		if type(oldNc) ~= "function" then
			log("WARN", "hooks: __namecall not installed")
			return
		end
		installed.namecall = true
		log("INFO", "hooks: __namecall (raycast redirect, equip block, remote spy, OOB report)")
	end

	-- v5 OOB guard, first line: OutOfBoundsMachine:IsOutOfBounds is the ONLY input of the client's
	-- out-of-bounds state machine (decompiled) — nil there means no warning, no timer, no Kill signal
	-- and therefore no OutOfBounds:FireServer. Live-gated on cfg.oobBlock; Bounds keeps reading the
	-- real geometry directly so the planner's own answers are never affected.
	function Hooks.installOob()
		if installed.oob and installed.oobKill then
			return
		end
		local mods = ReplicatedStorage:FindFirstChild("Modules")
		local OOB = Game.requireIfLoaded(mods and mods:FindFirstChild("OutOfBoundsMachine"))
		if type(OOB) ~= "table" then
			return -- not loaded yet (retried from the loop)
		end
		if not installed.oob then
			local fn = classMethod(OOB, "IsOutOfBounds")
			if type(fn) ~= "function" then
				log("WARN", "hooks: OutOfBoundsMachine.IsOutOfBounds not found — OOB guard is remote-swallow only")
			else
				local old: any
				local hooked
				old, hooked = hook(fn, function(self, ...)
					-- the lobby / between rounds: the game's own OOB runs untouched (nothing of ours moves the body there)
					if S.alive and S.cfg.oobBlock and not S.featuresPaused then
						S.oobSuppressed = (S.oobSuppressed or 0) + 1
						return nil
					end
					return old(self, ...)
				end)
				if hooked then
					S.hookOrig.oobIsOutOfBounds = old -- h.realOob (live logic) reads this across re-injects
					installed.oob = true -- only once it really hooked: a refused detour keeps retrying
					log("INFO", "hooks: OutOfBoundsMachine.IsOutOfBounds (OOB guard)")
				end
			end
		end
		-- v6.7: Update runs _CheckKill BEFORE IsOutOfBounds, so a warning already counting down when the guard
		-- came on still fired Kill → the OutOfBounds report. With the guard on, a pending timer is dropped here.
		if not installed.oobKill then
			local ck = classMethod(OOB, "_CheckKill")
			if type(ck) == "function" then
				local oldCk: any
				local hookedCk
				oldCk, hookedCk = hook(ck, function(self, ...)
					if S.alive and S.cfg.oobBlock and not S.featuresPaused then
						if type(self) == "table" and rawget(self, "_oob_details") ~= nil then
							rawset(self, "_oob_details", nil)
							S.oobSuppressed = (S.oobSuppressed or 0) + 1
						end
						return nil
					end
					return oldCk(self, ...)
				end)
				if hookedCk then
					installed.oobKill = true
				end
			end
		end
	end

	-- v5.0.3 anti-flash: the blind is applied client-side by Flashbang.ReplicateFromServer("BlindEffect",
	-- ...) (bytecode: BlindEffect · BlindDuration · ObjectID). The class table is shared by every
	-- instance through its metatable, so the method is hooked once; the original lives in the carried
	-- S.hookOrig so a re-inject never double-wraps it.
	function Hooks.installAntiFlash()
		if installed.antiFlash then
			return
		end
		local mod = LP:FindFirstChild("PlayerScripts")
		mod = mod and mod:FindFirstChild("Modules")
		mod = mod and mod:FindFirstChild("Items")
		mod = mod and mod:FindFirstChild("Flashbang")
		if not mod then
			return
		end
		local okR, cls = pcall(require, mod)
		if not okR or type(cls) ~= "table" then
			return
		end
		local fn = rawget(cls, "ReplicateFromServer")
		if type(fn) ~= "function" then
			return
		end
		local old: any
		local hooked
		old, hooked = hook(fn, function(self, kind, ...)
			if S.alive and S.cfg.antiFlash and kind == "BlindEffect" then
				S.flashesBlocked = (S.flashesBlocked or 0) + 1
				return nil
			end
			return old(self, kind, ...)
		end)
		if hooked then
			S.hookOrig.flashReplicate = old
			installed.antiFlash = true
			log("INFO", "hooks: Flashbang.ReplicateFromServer (anti-flash)")
		end
	end

	function Hooks.install()
		if not EXEC.hookfunction then
			log("WARN", "hooks: hookfunction unavailable — silent/skins disabled")
			return
		end
		local function attempt(name: string, fn: () -> ())
			local ok, err = xpcall(fn, traceback)
			if not ok then
				log("WARN", "hooks:", name, "skipped:", tostring(err))
			end
		end
		attempt("camera", Hooks.installCamera)
		attempt("menu mouse", Hooks.installMenuMouse)
		attempt("third person", Hooks.installThirdPerson)
		attempt("device", Hooks.installDevice)
		attempt("fighter", function()
			local lf0 = Game.localFighter()
			if lf0 then
				Hooks.installFighter(lf0)
			end
			local e0 = Game.enemies()[1]
			if e0 then
				Hooks.installFighter(e0)
			end
		end)
		attempt("gun", Hooks.installGun)
		attempt("fire gate", Hooks.installFire)
		attempt("viewmodel", Hooks.installViewModel)
		attempt("cosmetics", Hooks.installCosmetics)
		attempt("namecall", Hooks.installNamecall)
		attempt("item ui", Hooks.installItemInterface)
		attempt("mechanics", Hooks.installMechanics)
		attempt("walk speed", Hooks.installWalkSpeed)
		attempt("oob", Hooks.installOob)
		attempt("anti-flash", Hooks.installAntiFlash)
		if Hooks.staleMarks() then
			Hooks.staleChecked = true
			Hooks.repair("dead marks at install")
		end
		S.hooks.v = 7
		local on = {}
		for _, k in ipairs({ "camera", "fighter", "cameraData", "gun", "spreadClaim", "viewModel", "vmCreate", "shootEffect", "cosmetics", "namecall", "thirdPerson", "mechanics", "oob", "antiFlash" }) do
			table.insert(on, k .. "=" .. tostring(installed[k] == true))
		end
		log("INFO", "hooks v7:", table.concat(on, " "))
	end
	-- lazy installers: fighter class needs an instance; Gun / customize-UI modules need the game to
	-- have required them first (fresh place after a hop). Checked twice a second from the loop.
	local retryAt = 0
	function Hooks.retryFighter(enemies: { any })
		-- v6.5 a fighter class that will not hook (an executor refusing the detour) was retried every frame:
		-- 7 ms per frame on Madium in a 24-enemy lobby. Twice a second is plenty
		local fighterDue = os.clock() - (Hooks.fighterTryAt or 0) > 0.5
		if fighterDue and not (installed.fighterLocal and installed.fighterEnemy) then
			Hooks.fighterTryAt = os.clock()
		end
		if fighterDue and not installed.fighterLocal then
			local lf = Game.localFighter()
			if lf and not lf._fallback then
				local okF, errF = pcall(Hooks.installFighter, lf)
				if not okF then
					S.hookErr("fighter hooks", errF) -- rate-limited; a silent per-frame failure hid the cause
				end
			end
		end
		if fighterDue and not installed.fighterEnemy then
			for _, e in ipairs(enemies) do
				if not e._fallback then
					local okF, errF = pcall(Hooks.installFighter, e)
					if not okF then
						S.hookErr("fighter hooks", errF)
					end
					break
				end
			end
		end
		if (not installed.gun or not installed.fireGun or not installed.fireMelee or not installed.viewModel or not installed.vmCreate or not installed.cosmeticUi or not installed.itemInterface or not installed.mechanics or not installed.walkSpeed or not installed.oob or not installed.oobKill or not installed.antiFlash or not h.rotRemote or not h.oobRemote) and os.clock() - retryAt > 0.5 then
			retryAt = os.clock()
			-- the viewmodel group loads late (first gun in hand): its dead mark shows only now
			if not Hooks.staleChecked and Hooks.staleMarks() then
				Hooks.staleChecked = true
				pcall(Hooks.repair, "dead marks on retry")
			end
			if not h.rotRemote and h.resolveRotRemote then
				h.rotRemote = h.resolveRotRemote()
				if h.rotRemote then
					log("INFO", "UpdateCameraRotation remote found — rotation channel live")
				end
			end
			if (not h.oobRemote or h.oobRemote.Parent == nil) and h.resolveOobRemote then
				h.oobRemote = h.resolveOobRemote()
			end
			if not (installed.oob and installed.oobKill) then
				pcall(Hooks.installOob)
			end
			if not installed.antiFlash then
				pcall(Hooks.installAntiFlash)
			end
			if not installed.gun then
				pcall(Hooks.installGun)
			end
			if not (installed.fireGun and installed.fireMelee) then
				pcall(Hooks.installFire)
			end
			if not installed.mechanics then
				pcall(Hooks.installMechanics)
			end
			if not installed.walkSpeed then
				pcall(Hooks.installWalkSpeed)
			end
			if not installed.viewModel or not installed.vmCreate then
				pcall(Hooks.installViewModel)
			end
			if not installed.cosmeticUi then
				pcall(Hooks.installCosmeticUi)
			end
			if not installed.itemInterface then
				pcall(Hooks.installItemInterface)
			end
		end
	end
	S.installHooks = Hooks.install

	-----------------------------------------------------------------------------
	-- §9 visuals — Drawing pool, ESP, chams, radar, hit markers, world lighting, overlay
	-----------------------------------------------------------------------------
	local Vis: any = {}
	S.vis = Vis
	local drawings: { [string]: any } = {}
	local drawingCount = 0
	local highlights: { [Instance]: Highlight } = {}

	-- GUI-backed stand-in for the Drawing API (Square / Line / Text / Circle / Triangle with the
	-- properties this file uses). Two jobs: executors without Drawing still get ESP, radar, FOV
	-- circles and hit markers; and everyone can pick it as the "Anti-aliased" renderer — UIStroke edges are
	-- anti-aliased, Drawing lines are not. Drawing.Transparency is opacity (1 = solid), GUI is the
	-- inverse; screen coordinates match a ScreenGui with IgnoreGuiInset.
	Vis.guiPool = nil
	function Vis.guiRoot(): ScreenGui?
		local g = Vis.guiPool
		if g and g.Parent then
			return g
		end
		g = Instance.new("ScreenGui")
		g.Name = "CenterraESP"
		g.IgnoreGuiInset = true
		g.ResetOnSpawn = false
		g.DisplayOrder = 500
		-- never throws: an error here paused the whole ESP step (watchdog) on executors whose gethui /
		-- CoreGui refuse children — the PlayerGui is the last resort, and without any parent ESP stays off
		if not Game.parentGui(g) then
			local pg = LP:FindFirstChildOfClass("PlayerGui")
			if not (pg and pcall(function()
				g.Parent = pg
			end)) then
				g:Destroy()
				if not Vis.guiRootWarned then
					Vis.guiRootWarned = true
					log("WARN", "esp: no GUI container accepts the overlay (PlayerGui, gethui and CoreGui refused)")
				end
				return nil
			end
		end
		Vis.guiPool = g
		return g
	end
	function Vis.guiDrawing(class: string): any
		local root = Vis.guiRoot()
		if not root then
			return nil
		end
		local inst: GuiObject
		local strokeObj: UIStroke? = nil
		if class == "Text" then
			local t = Instance.new("TextLabel")
			t.BackgroundTransparency = 1
			local F = S.uikit and S.uikit.F
			if F and typeof(F.semibold) == "Font" then
				t.FontFace = F.semibold
			else
				t.Font = Enum.Font.BuilderSansBold
			end
			t.TextSize = 13
			t.TextXAlignment = Enum.TextXAlignment.Left
			t.TextYAlignment = Enum.TextYAlignment.Top
			t.AutomaticSize = Enum.AutomaticSize.XY
			t.Size = UDim2.new(0, 0, 0, 0)
			t.TextStrokeTransparency = 1
			inst = t
		else
			local f = Instance.new("Frame")
			f.BorderSizePixel = 0
			-- Line / Triangle ARE the frame's background (no UIStroke), so they must start opaque to show: the
			-- setters never write Transparency, which left every coloured line, tracer, skeleton bone, radar axis
			-- and arrow invisible on this renderer. Square / Circle keep a transparent background — their UIStroke
			-- draws them and Filled toggles the fill separately.
			f.BackgroundTransparency = if class == "Line" or class == "Triangle" then 0 else 1
			f.AnchorPoint = if class == "Line" or class == "Circle" then Vector2.new(0.5, 0.5) else Vector2.zero
			if class == "Circle" then
				local c = Instance.new("UICorner")
				c.CornerRadius = UDim.new(1, 0)
				c.Parent = f
			end
			if class == "Square" or class == "Circle" then
				local stroke = Instance.new("UIStroke") :: UIStroke
				stroke.Thickness = 1
				stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
				stroke.LineJoinMode = Enum.LineJoinMode.Miter -- square ESP boxes keep sharp corners
				stroke.Parent = f
				strokeObj = stroke
			end
			inst = f
		end
		inst.Visible = false
		inst.ZIndex = 2
		inst.Parent = root
		local st = { Visible = false, Color = Color3.new(1, 1, 1), Thickness = 1, Filled = false, Transparency = 1, Size = Vector2.zero, Position = Vector2.zero, From = Vector2.zero, To = Vector2.zero, Radius = 0, Text = "", Center = false, Outline = false, PointA = Vector2.zero, PointB = Vector2.zero, PointC = Vector2.zero, ZIndex = 2, NumSides = 12 }
		local function applyLine()
			local d = st.To - st.From
			local len = d.Magnitude
			local mid = (st.From + st.To) * 0.5
			inst.Position = UDim2.fromOffset(mid.X, mid.Y)
			inst.Size = UDim2.fromOffset(len, math.max(1, st.Thickness))
			inst.Rotation = math.deg(math.atan2(d.Y, d.X))
		end
		local function applyTriangle()
			-- an arrow tip: a small rotated square at PointA facing away from the base
			local base = (st.PointB + st.PointC) * 0.5
			local d = st.PointA - base
			inst.Position = UDim2.fromOffset(st.PointA.X, st.PointA.Y)
			inst.Size = UDim2.fromOffset(10, 10)
			inst.Rotation = math.deg(math.atan2(d.Y, d.X)) + 45
			inst.AnchorPoint = Vector2.new(0.5, 0.5)
		end
		local proxy = setmetatable({}, {
			__index = function(_, k)
				if k == "TextBounds" then
					return (inst :: TextLabel).TextBounds
				elseif k == "Remove" or k == "Destroy" then
					return function()
						inst:Destroy()
					end
				end
				return st[k]
			end,
			__newindex = function(_, k, v)
				st[k] = v
				if k == "Visible" then
					inst.Visible = v == true
				elseif k == "Color" then
					if class == "Text" then
						(inst :: TextLabel).TextColor3 = v
					else
						inst.BackgroundColor3 = v
						if strokeObj then
							strokeObj.Color = v
						end
					end
				elseif k == "Transparency" then
					local a = 1 - math.clamp(tonumber(v) or 1, 0, 1)
					if class == "Text" then
						(inst :: TextLabel).TextTransparency = a
					elseif strokeObj then
						strokeObj.Transparency = a
						inst.BackgroundTransparency = if st.Filled then a else 1
					else
						inst.BackgroundTransparency = a
					end
				elseif k == "Filled" then
					if strokeObj then
						strokeObj.Enabled = not v
						inst.BackgroundTransparency = if v then 1 - math.clamp(st.Transparency, 0, 1) else 1
					end
				elseif k == "Thickness" then
					if strokeObj then
						strokeObj.Thickness = math.max(1, tonumber(v) or 1)
					elseif class == "Line" then
						applyLine()
					end
				elseif k == "Size" then
					if class == "Text" then
						(inst :: TextLabel).TextSize = math.clamp(tonumber(v) or 13, 6, 40)
					elseif typeof(v) == "Vector2" then
						inst.Size = UDim2.fromOffset(v.X, v.Y)
					end
				elseif k == "Position" then
					if typeof(v) == "Vector2" then
						if class == "Circle" then
							inst.Position = UDim2.fromOffset(v.X, v.Y)
						elseif class == "Text" then
							inst.AnchorPoint = if st.Center then Vector2.new(0.5, 0) else Vector2.zero
							inst.Position = UDim2.fromOffset(v.X, v.Y)
						else
							inst.Position = UDim2.fromOffset(v.X, v.Y)
						end
					end
				elseif k == "From" or k == "To" then
					if class == "Line" then
						applyLine()
					end
				elseif k == "Radius" then
					local r = tonumber(v) or 0
					inst.Size = UDim2.fromOffset(r * 2, r * 2)
				elseif k == "Text" then
					(inst :: TextLabel).Text = tostring(v)
				elseif k == "Center" then
					(inst :: TextLabel).TextXAlignment = if v then Enum.TextXAlignment.Center else Enum.TextXAlignment.Left
					inst.AnchorPoint = if v then Vector2.new(0.5, 0) else Vector2.zero
				elseif k == "Outline" then
					(inst :: TextLabel).TextStrokeTransparency = if v then 0.25 else 1
				elseif k == "PointA" or k == "PointB" or k == "PointC" then
					applyTriangle()
				elseif k == "ZIndex" then
					inst.ZIndex = tonumber(v) or 2
				end
			end,
		})
		return proxy
	end
	-- Vis.drawingBroken: the executor's Drawing library is missing or keeps failing → the GUI renderer
	-- takes over whatever the setting says (ESP that silently drew nothing was the #1 "ESP broken" report)
	Vis.drawingBroken, Vis.drawingFails = false, 0
	function Vis.useGuiRenderer(): boolean
		if Vis.drawingBroken or EXEC.Drawing == nil then
			return true
		end
		local mode = cfg.espRenderer
		if mode == "Anti-aliased" then
			return true
		end
		return false
	end
	function Vis.markDrawingBroken(why: string)
		if Vis.drawingBroken then
			return
		end
		Vis.drawingBroken = true
		log("WARN", "esp: the executor's Drawing library failed (" .. why .. ") — switched to the built-in renderer")
		pcall(function()
			S.notify("ESP switched to the built-in renderer (this executor's Drawing failed)", 4, "warn")
		end)
		Vis.resetDrawings()
	end
	function Vis.draw(name: string, class: string): any
		local d = drawings[name]
		if not d then
			if Vis.useGuiRenderer() then
				d = Vis.guiDrawing(class)
				if not d then
					return nil
				end
			else
				local ok, obj = pcall(EXEC.Drawing.new, class)
				if not ok or not obj then
					Vis.drawingFails += 1
					if Vis.drawingFails >= 3 then
						Vis.markDrawingBroken(if ok then "Drawing.new returned nothing" else tostring(obj):sub(1, 80))
						return Vis.draw(name, class)
					end
					return nil
				end
				d = obj
			end
			drawings[name] = d
			drawingCount += 1
			if class == "Text" and not Vis.propProbed then
				Vis.probeDrawingProps(d)
			end
		end
		return d
	end
	-- renderer switch: drop every pooled object so the next frame rebuilds them with the other backend
	function Vis.resetDrawings()
		for key, d in pairs(drawings) do
			pcall(function()
				d.Visible = false
				if d.Remove then
					d:Remove()
				end
			end)
			drawings[key] = nil
		end
		drawingCount = 0
		Vis.propAlias.Center, Vis.propAlias.Outline, Vis.propProbed = "Center", "Outline", false
		-- the slot / arrow / radar caches hold the removed objects directly: without dropping them a renderer
		-- switch (or the Clean look button) left the ESP writing into dead objects — nothing drew until a rejoin
		for _, cache in ipairs({ Vis.slots, Vis.arrows, Vis.arrowOut, Vis.arrowLabels, Vis.radarDots }) do
			if type(cache) == "table" then
				table.clear(cache)
			end
		end
		Vis.slotsShown, Vis.arrowsShown, Vis.radarShown = 0, 0, 0
		if Vis.shadow then
			table.clear(Vis.shadow)
		end
	end
	-- Every property write on a Drawing object is a call into the executor; with ~45 objects per
	-- enemy that was ~3 600 native calls a frame for a full lobby, most of them re-writing the same
	-- colour / size / "Visible = false". A shadow copy of the last written value per object lets
	-- sv() skip identical writes, and off() hides an object only if it exists and is showing.
	Vis.shadow = setmetatable({}, { __mode = "k" })
	-- v5.2: Drawing dialects. Volt / Synapse call the text-alignment flag `Center` and the outline
	-- `Outline`; several executors only know `Centered` / `Outlined`. Probed once on the first native
	-- Text object (a readable property is a supported one), then every write uses the local name.
	Vis.propAlias = { Center = "Center", Outline = "Outline" }
	Vis.propProbed = false
	function Vis.probeDrawingProps(d: any)
		Vis.propProbed = true
		if Vis.useGuiRenderer() then
			return
		end
		for _, pair in ipairs({ { "Center", "Centered" }, { "Outline", "Outlined" } }) do
			local ok, v = pcall(function()
				return d[pair[1]]
			end)
			if not (ok and type(v) == "boolean") then
				local ok2, v2 = pcall(function()
					return d[pair[2]]
				end)
				if ok2 and type(v2) == "boolean" then
					Vis.propAlias[pair[1]] = pair[2]
					log("INFO", ("drawing: this executor calls %s `%s`"):format(pair[1], pair[2]))
				end
			end
		end
	end
	function Vis.sv(d: any, key: string, value: any)
		if not d then
			return
		end
		local s = Vis.shadow[d]
		if not s then
			s = {}
			Vis.shadow[d] = s
		end
		if s[key] ~= value then
			s[key] = value
			local alias = Vis.propAlias[key]
			d[alias or key] = value
		end
	end
	-- TextBounds is missing on some Drawing implementations: a guarded read with a width estimate
	function Vis.textWidth(d: any, text: string?, size: number?): number
		local ok, b = pcall(function()
			return d.TextBounds
		end)
		if ok and typeof(b) == "Vector2" and b.X > 0 then
			return b.X
		end
		return #(text or "") * (size or 13) * 0.55
	end
	function Vis.off(name: string)
		local d = drawings[name]
		if d then
			local s = Vis.shadow[d]
			if not s or s.Visible ~= false then
				Vis.sv(d, "Visible", false)
			end
		end
	end
	function Vis.hide(prefix: string, keep: number)
		local plen = #prefix
		for key, d in pairs(drawings) do
			if key:sub(1, plen) == prefix then
				local n = tonumber(key:match("^" .. prefix .. "(%d+)"))
				if n and n > keep then
					Vis.sv(d, "Visible", false)
				end
			end
		end
	end
	function Vis.hideAll(prefix: string?)
		for key, d in pairs(drawings) do
			if not prefix or key:sub(1, #prefix) == prefix then
				Vis.sv(d, "Visible", false)
			end
		end
	end
	function Vis.drawingCount(): number
		return drawingCount
	end
	function Vis.highlightCount(): number
		local n = 0
		for _ in pairs(highlights) do
			n += 1
		end
		return n
	end
	function Vis.destroyAll()
		for _, d in pairs(drawings) do
			pcall(function()
				if d.Remove then
					d:Remove()
				elseif d.Destroy then
					d:Destroy()
				end
			end)
		end
		table.clear(drawings)
		drawingCount = 0
		for _, hl in pairs(highlights) do
			pcall(hl.Destroy, hl)
		end
		table.clear(highlights)
		for _, plr in ipairs(Players:GetPlayers()) do
			local hl = plr.Character and plr.Character:FindFirstChild("CenterraHL")
			if hl then
				pcall(hl.Destroy, hl)
			end
		end
	end
	function Vis.col(key: string): Color3
		return rgb(cfg[key], Color3.fromRGB(255, 70, 100))
	end

	-- highlights (chams): capped, and every property written only when it changes — 24 of them with
	-- six property writes each per frame was a GPU + Lua cost that never showed up in stepMs
	-- (Roblox renders at most 31 Highlights; each one is its own outline pass)
	Vis.HL_CAP = 12
	Vis.hlState = setmetatable({}, { __mode = "k" })
	Vis.hlSeen = {}
	function Vis.syncHighlights(list: { any }, vis: { [any]: boolean }, cap: number)
		if not (cfg.esp and cfg.espHighlight) or cap <= 0 then
			if next(highlights) then
				for _, hl in pairs(highlights) do
					pcall(hl.Destroy, hl)
				end
				table.clear(highlights)
			end
			return
		end
		local seen = Vis.hlSeen
		table.clear(seen)
		-- "Only behind walls" (espChamsOccluded): show the cham only while the enemy is NOT directly visible.
		-- Roblox has no native occluded-only mode, so keep AlwaysOnTop (which draws through walls) and switch the
		-- highlight off for models we can currently see. DepthMode.Occluded used to do the opposite of the label.
		local occludedOnly = cfg.espChamsOccluded == true
		local depth = Enum.HighlightDepthMode.AlwaysOnTop
		local colVis, colFill, colOut = Vis.col("colEspVisible"), Vis.col("colChamsFill"), Vis.col("colChamsOutline")
		local ft, ot = cfg.espChamsFill, cfg.espChamsOutline
		local n = 0
		for _, fighter in ipairs(list) do
			if n >= cap then
				break
			end
			local _, model = Game.fighterBody(fighter)
			if model then
				n += 1
				seen[model] = true
				local hl = highlights[model]
				if not hl or hl.Parent == nil then
					hl = Instance.new("Highlight")
					hl.Name = "CenterraHL"
					hl.Adornee = model
					hl.Parent = model
					highlights[model] = hl
				end
				local st = Vis.hlState[hl]
				if not st then
					st = {}
					Vis.hlState[hl] = st
				end
				local seenVisible = vis[model] == true
				local fill = if seenVisible then colVis else colFill
				local wantOn = not (occludedOnly and seenVisible)
				if st.depth ~= depth then
					st.depth = depth
					hl.DepthMode = depth
				end
				if st.fill ~= fill then
					st.fill = fill
					hl.FillColor = fill
				end
				if st.outline ~= colOut then
					st.outline = colOut
					hl.OutlineColor = colOut
				end
				if st.ft ~= ft then
					st.ft = ft
					hl.FillTransparency = ft
				end
				if st.ot ~= ot then
					st.ot = ot
					hl.OutlineTransparency = ot
				end
				if st.on ~= wantOn then
					st.on = wantOn
					hl.Enabled = wantOn
				end
			end
		end
		for model, hl in pairs(highlights) do
			if not seen[model] then
				pcall(hl.Destroy, hl)
				highlights[model] = nil
			end
		end
	end

	Vis.R15 = {
		{ "Head", "UpperTorso" }, { "UpperTorso", "LowerTorso" },
		{ "UpperTorso", "LeftUpperArm" }, { "LeftUpperArm", "LeftLowerArm" }, { "LeftLowerArm", "LeftHand" },
		{ "UpperTorso", "RightUpperArm" }, { "RightUpperArm", "RightLowerArm" }, { "RightLowerArm", "RightHand" },
		{ "LowerTorso", "LeftUpperLeg" }, { "LeftUpperLeg", "LeftLowerLeg" }, { "LeftLowerLeg", "LeftFoot" },
		{ "LowerTorso", "RightUpperLeg" }, { "RightUpperLeg", "RightLowerLeg" }, { "RightLowerLeg", "RightFoot" },
	}
	Vis.R6 = { { "Head", "Torso" }, { "Torso", "Left Arm" }, { "Torso", "Right Arm" }, { "Torso", "Left Leg" }, { "Torso", "Right Leg" } }
	Vis.BOX_EDGES = { { 1, 2 }, { 2, 4 }, { 4, 3 }, { 3, 1 }, { 5, 6 }, { 6, 8 }, { 8, 7 }, { 7, 5 }, { 1, 5 }, { 2, 6 }, { 3, 7 }, { 4, 8 } }

	-- body parts per model, resolved once a second (the limb / hitbox parts fill in over several
	-- frames after a spawn): the box, the skeleton and the 3D box all read this — no FindFirstChild
	-- per bone per frame (28 of them per enemy before) and no Model:GetBoundingBox() per frame
	Vis.BODY_KEYS = {
		"Head", "UpperTorso", "LowerTorso", "Torso", "HumanoidRootPart",
		"LeftUpperArm", "LeftLowerArm", "LeftHand", "RightUpperArm", "RightLowerArm", "RightHand",
		"LeftUpperLeg", "LeftLowerLeg", "LeftFoot", "RightUpperLeg", "RightLowerLeg", "RightFoot",
		"Left Arm", "Right Arm", "Left Leg", "Right Leg",
	}
	-- the extremities that shape the 2D box (head, hands, feet + root): a crouching or sliding
	-- player gets a box that fits, instead of head-to-(root − 2.9)
	Vis.BOX_KEYS = { "Head", "HumanoidRootPart", "LeftHand", "RightHand", "LeftFoot", "RightFoot", "Left Arm", "Right Arm", "Left Leg", "Right Leg" }
	Vis.bodyCache = setmetatable({}, { __mode = "k" })
	function Vis.bodyParts(model: Instance): any
		local c = Vis.bodyCache[model]
		local now = os.clock()
		-- a rig still filling in after a spawn (few limbs yet) is re-read at 5 Hz, a full one once a second: the
		-- box used to sit on a hand / the root for up to a second after every respawn, then jump
		if c and now - c.at < (if #c.box >= 5 then 1 else 0.2) then
			return c
		end
		if not c then
			c = { at = 0, parts = {}, box = {}, bones = {}, byName = {} }
			Vis.bodyCache[model] = c
		end
		c.at = now
		table.clear(c.parts)
		table.clear(c.box)
		table.clear(c.bones)
		table.clear(c.byName)
		for _, nm in ipairs(Vis.BODY_KEYS) do
			local p = model:FindFirstChild(nm)
			if p and p:IsA("BasePart") then
				c.byName[nm] = p
				table.insert(c.parts, p)
			end
		end
		for _, nm in ipairs(Vis.BOX_KEYS) do
			local p = c.byName[nm]
			if p then
				table.insert(c.box, p)
			end
		end
		local bones = if c.byName.UpperTorso then Vis.R15 else Vis.R6
		for _, pair in ipairs(bones) do
			local a, b = c.byName[pair[1]], c.byName[pair[2]]
			if a and b then
				table.insert(c.bones, a)
				table.insert(c.bones, b)
			end
		end
		return c
	end

	-- Drawing has no anti-aliasing: a line whose centre sits between pixel rows comes out one pixel
	-- thicker or thinner depending on where it lands, so box edges and their dark outlines shimmered
	-- as they moved. Odd widths go on pixel centres, even widths on pixel edges; the anti-aliased
	-- (GUI) renderer keeps exact positions. Vis.guiMode is set once per ESP frame.
	Vis.guiMode = false
	function Vis.pxOff(thick: number): number
		if Vis.guiMode then
			return 0
		end
		return if math.floor(thick + 0.5) % 2 == 1 then 0.5 else 0
	end
	function Vis.snapPt(v: Vector2, thick: number): Vector2
		if Vis.guiMode then
			return v
		end
		local o = Vis.pxOff(thick)
		return Vector2.new(math.floor(v.X) + o, math.floor(v.Y) + o)
	end
	-- the hottest ESP writer (a corner box is 16 of these per enemy): one shadow lookup per line instead of
	-- five Vis.sv calls, the same skip-if-unchanged rule
	function Vis.setLine(d: any, a: Vector2?, b: Vector2?, color: Color3, thick: number?)
		if not d then
			return
		end
		local s = Vis.shadow[d]
		if not s then
			s = {}
			Vis.shadow[d] = s
		end
		if a and b then
			local t = thick or 1
			a, b = Vis.snapPt(a, t), Vis.snapPt(b, t)
			local alias = Vis.propAlias
			if s.From ~= a then
				s.From = a
				d[alias.From or "From"] = a
			end
			if s.To ~= b then
				s.To = b
				d[alias.To or "To"] = b
			end
			if s.Color ~= color then
				s.Color = color
				d[alias.Color or "Color"] = color
			end
			if s.Thickness ~= t then
				s.Thickness = t
				d[alias.Thickness or "Thickness"] = t
			end
			if s.Visible ~= true then
				s.Visible = true
				d[alias.Visible or "Visible"] = true
			end
		elseif s.Visible ~= false then
			s.Visible = false
			d[Vis.propAlias.Visible or "Visible"] = false
		end
	end

	-- ESP slots: one table of pre-resolved Drawing objects per drawn enemy. The old pool was keyed
	-- by strings built per frame ("e" .. idx .. "s" .. i — ~45 concatenations + hash lookups per
	-- enemy per frame) and hidden by scanning every pooled object three times a frame.
	Vis.slots = {}
	Vis.slotsShown = 0
	Vis.arrows = {}
	Vis.arrowsShown = 0
	function Vis.slot(i: number): any
		local s = Vis.slots[i]
		if s then
			return s
		end
		s = { p = "e" .. i, objs = {}, c = {}, co = {}, x = {}, s = {}, fl = {}, hpW = 0, flW = 0, hpShown = nil }
		Vis.slots[i] = s
		return s
	end
	-- objects are created lazily, only for the features that are on
	function Vis.slotObj(s: any, key: string, class: string): any
		local d = s[key]
		if d == nil then
			d = Vis.draw(s.p .. key, class)
			if d then
				table.insert(s.objs, d)
			end
			s[key] = d or false
		end
		return d or nil
	end
	function Vis.slotArr(s: any, arr: { any }, i: number, key: string, class: string): any
		local d = arr[i]
		if d == nil then
			d = Vis.draw(s.p .. key .. i, class)
			arr[i] = d or false
		end
		return d or nil
	end
	function Vis.slotOff(s: any)
		for _, d in ipairs(s.objs) do
			Vis.sv(d, "Visible", false)
		end
		for _, arr in ipairs({ s.c, s.co, s.x, s.s, s.fl }) do
			for _, d in ipairs(arr) do
				if d then
					Vis.sv(d, "Visible", false)
				end
			end
		end
	end
	function Vis.arrsOff(arr: { any }, from: number)
		for i = from, #arr do
			local d = arr[i]
			if d then
				Vis.sv(d, "Visible", false)
			end
		end
	end
	-- one corner-box segment from the corner (ax, ay) outward to (bx, by), with a dark 1 px edge under
	-- it that also covers the line's ends (segments are axis-aligned: the end extension is ±1 on one axis)
	function Vis.cornerSeg(s: any, i: number, ax: number, ay: number, bx: number, by: number, color: Color3, lw: number, outline: boolean)
		local ln = Vis.slotArr(s, s.c, i, "c", "Line")
		if ln then
			Vis.sv(ln, "ZIndex", 2)
			Vis.setLine(ln, Vector2.new(ax, ay), Vector2.new(bx, by), color, lw)
		end
		local o = if outline then Vis.slotArr(s, s.co, i, "co", "Line") else s.co[i]
		if outline and o then
			local ux = if bx > ax then 1 elseif bx < ax then -1 else 0
			local uy = if by > ay then 1 elseif by < ay then -1 else 0
			Vis.sv(o, "ZIndex", 1)
			Vis.sv(o, "Transparency", 0.85)
			Vis.setLine(o, Vector2.new(ax - ux, ay - uy), Vector2.new(bx + ux, by + uy), Vis.OUTLINE, lw + 2)
		elseif o then
			Vis.sv(o, "Visible", false)
		end
	end
	-- the camera plane guard: a point at least nearZ studs in front, projected (nil otherwise)
	Vis.NEAR_Z = 1.5
	function Vis.w2sNear(cam: Camera, pos: Vector3, nearZ: number): Vector2?
		local v = cam:WorldToViewportPoint(pos)
		if v.Z < nearZ then
			return nil
		end
		return Vector2.new(v.X, v.Y)
	end
	-- the flat box (+ its dark outline), shared by the Full style and the 3D box's fallback
	function Vis.box2d(s: any, x: number, y: number, wid: number, hgt: number, color: Color3, lw: number, outline: boolean)
		local sv = Vis.sv
		-- the stroke sits on pixel centres (see Vis.pxOff)
		local po = Vis.pxOff(lw)
		local bpos, bsize = Vector2.new(x + po, y + po), Vector2.new(wid, hgt)
		if outline then
			local bo = Vis.slotObj(s, "bo", "Square")
			sv(bo, "Size", bsize)
			sv(bo, "Position", bpos)
			sv(bo, "Color", Vis.OUTLINE)
			sv(bo, "Thickness", lw + 2)
			sv(bo, "Filled", false)
			sv(bo, "Transparency", 0.85)
			sv(bo, "ZIndex", 1)
			sv(bo, "Visible", true)
		elseif s.bo then
			sv(s.bo, "Visible", false)
		end
		local box = Vis.slotObj(s, "b", "Square")
		sv(box, "Size", bsize)
		sv(box, "Position", bpos)
		sv(box, "Color", color)
		sv(box, "Thickness", lw)
		sv(box, "Filled", false)
		sv(box, "Transparency", 1)
		sv(box, "ZIndex", 2)
		sv(box, "Visible", true)
	end
	function Vis.box2dOff(s: any)
		if s.b then
			Vis.sv(s.b, "Visible", false)
		end
		if s.bo then
			Vis.sv(s.bo, "Visible", false)
		end
	end
	Vis.listTbl, Vis.distTbl, Vis.visTbl, Vis.visLast, Vis.screenTbl, Vis.want = {}, {}, {}, setmetatable({}, { __mode = "k" }), {}, {}
	Vis.sortByDist = function(a: any, b: any): boolean
		return Vis.distTbl[a] < Vis.distTbl[b]
	end
	Vis.espAllOff = false
	Vis.LOD_N = 8 -- enemies drawn with every detail; the rest of a crowd gets box, name and health
	Vis.IMMUNE_COLOR = Color3.fromRGB(120, 200, 255)
	Vis.BAR_BG, Vis.BAR_LOW, Vis.TAG_COLOR = Color3.fromRGB(0, 0, 0), Color3.fromRGB(255, 84, 84), Color3.fromRGB(255, 196, 70)
	Vis.OUTLINE = Color3.new(0, 0, 0)
	Vis.VOID_COLOR = Color3.fromRGB(190, 120, 255)
	Vis.FLAG_DIM = Color3.fromRGB(150, 146, 160)
	Vis.offTbl, Vis.offVoid = {}, {}
	-- one entry of the flag column. Its width is only needed while the column sits left of the box
	-- (near the screen's right edge), and reading TextBounds is a native call: measured only then.
	function Vis.flagAt(s: any, i: number, text: string, color: Color3, x: number, y: number, size: number, measure: boolean): number
		local d = Vis.slotArr(s, s.fl, i, "fl", "Text")
		if not d then
			return 0
		end
		Vis.sv(d, "Text", text)
		Vis.styleText(d, size, color, false)
		Vis.sv(d, "Position", Vector2.new(x, y))
		Vis.sv(d, "Visible", true)
		return if measure then Vis.textWidth(d, text, size) else 0
	end
	-- health: red → amber → the "Full health" colour
	function Vis.hpColor(frac: number, full: Color3?): Color3
		local top = full or Vis.col("colHp")
		frac = math.clamp(frac, 0, 1)
		if frac >= 0.5 then
			return Vis.TAG_COLOR:Lerp(top, (frac - 0.5) * 2)
		end
		return Vis.BAR_LOW:Lerp(Vis.TAG_COLOR, frac * 2)
	end
	-- one text style for every ESP label: a dark outline, left or centred, above the lines. The native
	-- renderer keeps the executor's own font (registering custom fonts through DrawFont is a native call
	-- that is not worth a crash risk for a typeface).
	-- ESP while hidden: 30 000 st out in a void hide, Roblox streams the other characters out of this client —
	-- their parts no longer exist here, so nothing can be read, only remembered. Each enemy's last position,
	-- velocity, name and health are noted while they are streamed in (10 Hz); during a hide, the ones that
	-- vanished are drawn as a dimmed "last seen" box at their predicted spot (velocity for up to 1.5 s) until they
	-- stream back or go stale. Local drawing only. Off: Players → Style → ESP while hidden.
	Vis.ghost = setmetatable({}, { __mode = "k" })
	Vis.ghostShown = 0
	Vis.ghostAt = 0
	Vis.ghostPresent = setmetatable({}, { __mode = "k" })
	function Vis.ghostStep(enemies: { any })
		local cam = workspace.CurrentCamera
		local now = os.clock()
		local present = Vis.ghostPresent
		table.clear(present)
		for _, f in ipairs(enemies) do
			local root = Game.fighterBody(f)
			if root and root.Parent then
				present[f] = root
			end
		end
		if now - Vis.ghostAt >= 0.1 then
			Vis.ghostAt = now
			for f, root in pairs(present) do
				local g = Vis.ghost[f]
				if not g then
					g = { name = (Game.fighterName(f):gsub(" %[BOT%]", "")) }
					Vis.ghost[f] = g
				end
				local head = Game.fighterHead(f)
				g.pos = root.Position
				g.head = if head then head.Position else root.Position + Vector3.new(0, 1.6, 0)
				g.vel = S.resolver.fixVel(root)
				g.t = now
			end
		end
		local me = Game.myRoot()
		local away = cam ~= nil and me ~= nil and (me.Position - cam.CFrame.Position).Magnitude > 200
		local n = 0
		if cfg.esp and cfg.espWhileHidden and away and not S.menuOpen then
			local sv = Vis.sv
			local life = math.max(tonumber(cfg.espGhostSec) or 6, 1)
			local col, textCol = Vis.col("colEsp"), Vis.col("colText")
			local size = math.max(9, (cfg.espTextSize or 13) - 1)
			for f, g in pairs(Vis.ghost) do
				local age = now - (g.t or 0)
				if not present[f] and age < life and n < 16 and g.pos then
					local v = g.vel or Vector3.zero
					if v.Magnitude > 60 then
						v = Vector3.zero -- a fly / speed cheat's velocity says nothing about where they went
					end
					local lead = v * math.min(age, 1.5)
					local top = cam:WorldToViewportPoint(g.head + lead + Vector3.new(0, 0.9, 0))
					local foot = cam:WorldToViewportPoint(g.pos + lead - Vector3.new(0, 3, 0))
					if top.Z > 0 and foot.Z > 0 then
						n += 1
						local h = math.max(math.abs(foot.Y - top.Y), 6)
						local w = h * 0.55
						local fade = math.clamp(1 - age / life, 0.15, 1)
						local box = Vis.draw("_gs" .. n, "Square")
						if box then
							sv(box, "Position", Vector2.new(top.X - w / 2, math.min(top.Y, foot.Y)))
							sv(box, "Size", Vector2.new(w, h))
							sv(box, "Color", col)
							sv(box, "Thickness", 1)
							sv(box, "Filled", false)
							sv(box, "Transparency", 0.85 * fade)
							sv(box, "Visible", true)
						end
						local lbl = Vis.draw("_gl" .. n, "Text")
						if lbl then
							Vis.styleText(lbl, size, textCol, true)
							sv(lbl, "Text", ("%s · last seen %.0fs"):format(g.name or "?", age))
							sv(lbl, "Position", Vector2.new(top.X, math.min(top.Y, foot.Y) - size - 2))
							sv(lbl, "Transparency", fade)
							sv(lbl, "Visible", true)
						end
					end
				end
			end
		end
		if n < Vis.ghostShown then
			Vis.hide("_gs", n)
			Vis.hide("_gl", n)
		end
		Vis.ghostShown = n
	end
	function Vis.styleText(d: any, size: number, color: Color3, center: boolean)
		local sv = Vis.sv
		sv(d, "Size", size)
		sv(d, "Color", color)
		sv(d, "Center", center)
		sv(d, "Outline", true)
		sv(d, "ZIndex", 3)
	end
	-- the "Clean look" button on the Players page
	Vis.CLEAN_ESP = {
		esp = true, espBox = true, espBoxStyle = "Corner", espBoxFill = false, espOutline = true, espLineWidth = 1,
		espSkeleton = false, espHeadDot = false, espNames = true, espHealthBar = true, espHpMode = "When damaged",
		espWeapon = true, espDistance = false, espFlags = true, espTracers = false, espVisibleCheck = true,
		colEsp = { 142, 138, 153 }, colEspVisible = { 173, 102, 255 }, colText = { 242, 240, 247 }, colHp = { 69, 223, 160 },
	}

	-- accepts the same fighter-like tables the scanner produces ({ Player?, Entity = { Model, RootPart, Head, Humanoid } })
	function Vis.drawEsp(enemies: { any })
		local cam = workspace.CurrentCamera
		if not cfg.esp or not cam then
			-- hidden once, not scanned every frame while off
			if not Vis.espAllOff then
				Vis.espAllOff = true
				for i = 1, Vis.slotsShown do
					Vis.slotOff(Vis.slots[i])
				end
				Vis.arrsOff(Vis.arrows, 1)
				Vis.arrsOff(Vis.arrowOut, 1)
				for _, lbl in pairs(Vis.arrowLabels) do
					if lbl then
						Vis.sv(lbl, "Visible", false)
					end
				end
				Vis.slotsShown, Vis.arrowsShown = 0, 0
			end
			Vis.syncHighlights(Vis.listTbl, Vis.visTbl, 0)
			return
		end
		Vis.espAllOff = false
		Vis.guiMode = Vis.useGuiRenderer()
		local myRoot = Game.myRoot()
		local tier = S.perfTier or 0
		local perf = cfg.perfMode or tier >= 2
		local ESP_CAP = if perf then 10 else 16
		-- the drawn list: inside espMaxDistance, closest first when over the cap
		local list, dcache = Vis.listTbl, Vis.distTbl
		table.clear(list)
		table.clear(dcache)
		local maxD = cfg.espMaxDistance
		local myPos = myRoot and myRoot.Position
		-- void-hiding / parked far away: the body is 10 000+ st out while the camera stays pinned where you stood
		-- (Combat.pinCamera). Distances and the visible colour are judged from the camera then, so the ESP keeps
		-- showing the fight instead of dropping everyone past Max distance. Local drawing only: nothing is sent and
		-- the body never moves for it, so it cannot give the hiding spot away.
		local espFrom: Vector3? = nil
		local camPos = cam.CFrame.Position
		if cfg.espWhileHidden and myPos and (myPos - camPos).Magnitude > 200 then
			myPos, espFrom = camPos, camPos
		end
		local voidHunt = cfg.voidHunt
		for _, f in ipairs(enemies) do
			local r = Game.fighterBody(f)
			if r then
				local d = if myPos then (myPos - r.Position).Magnitude else 0
				local keep = d <= maxD
				-- v5.0.3: a void hider is 500–5000 st BELOW us and used to fall out of the list here — judge
				-- them by the horizontal distance (that is what the planner / lock use too)
				if not keep and voidHunt and myPos then
					local dx, dz = myPos.X - r.Position.X, myPos.Z - r.Position.Z
					keep = math.sqrt(dx * dx + dz * dz) <= maxD
				end
				if keep then
					dcache[f] = d
					table.insert(list, f)
				end
			end
		end
		-- crowds (the lobby, the range): closest first, and only the nearest LOD_N keep every detail —
		-- the rest get box, name and health bar. A match never has more enemies than that.
		if #list > Vis.LOD_N then
			table.sort(list, Vis.sortByDist)
			for i = #list, ESP_CAP + 1, -1 do
				list[i] = nil
			end
		end
		-- server-style line of sight, only for the enemies that are drawn (it used to raycast every
		-- enemy in the lobby). v6.7: a third of the list per frame (a sixth at tier ≥ 1) — a colour change a
		-- frame or two late is invisible, 16 whitelist raycasts every frame were not; a new enemy is checked at once
		local vis = Vis.visTbl
		table.clear(vis)
		if cfg.espVisibleCheck then
			local every = if tier >= 1 then 6 else 3
			for i, f in ipairs(list) do
				local root, model = Game.fighterBody(f)
				if model then
					local last = Vis.visLast[model]
					if last ~= nil and (i + Game.frameId) % every ~= 0 then
						vis[model] = last == true
					else
						local v = Game.rayVisible(model, Game.fighterHead(f) or root, espFrom)
						vis[model] = v
						Vis.visLast[model] = v
					end
				end
			end
		end
		Vis.syncHighlights(list, vis, if perf then 6 else Vis.HL_CAP)
		local vp = cam.ViewportSize
		local center = vp / 2
		local textSize = cfg.espTextSize
		local textColor = Vis.col("colText")
		local hpColor = Vis.col("colHp")
		-- colours once per frame instead of a Color3 per enemy per element
		local colVisible = Vis.col("colEspVisible")
		local colHidden = Vis.col("colEsp")
		local lw = cfg.espLineWidth
		local fillAlpha = 1 - cfg.espBoxFillAlpha
		local barBg, tagColor = Vis.BAR_BG, Vis.TAG_COLOR
		local flagDim = textColor:Lerp(Vis.FLAG_DIM, 0.4)
		local weaponColor = textColor:Lerp(Vis.FLAG_DIM, 0.2)
		local tracerColor = Vis.col("colTracer")
		local tracerFrom = if cfg.espTracerFrom == "Center" then center
			elseif cfg.espTracerFrom == "Mouse" then UIS:GetMouseLocation()
			else Vector2.new(center.X, vp.Y)
		-- what this frame draws, decided once instead of per enemy per element. Skeleton / 3D box /
		-- tracers are the extras the perf tiers drop; the box itself is drawn EVERY frame at every
		-- tier (skipping frames made the boxes trail moving players)
		local want = Vis.want
		-- v5.2: tier 1 really drops the skeleton / 3D box now (the tier table always said so; the code
		-- only cut them at tier 2). The 2D box itself stays at every tier.
		local extras = perf or tier >= 1
		local box3d = cfg.espBox and cfg.espBoxStyle == "3D"
		want.fill = cfg.espBox and cfg.espBoxFill and not box3d
		want.full = cfg.espBox and (cfg.espBoxStyle == "Full" or (box3d and extras)) -- a cut 3D box falls back to the 2D one
		want.corner = cfg.espBox and cfg.espBoxStyle == "Corner"
		want.box3d = box3d and not extras
		want.skel = cfg.espSkeleton and not extras
		want.dot = cfg.espHeadDot
		want.bar = cfg.espHealthBar
		want.names = cfg.espNames
		-- the health number rides on the bar: "When damaged" shows it only below full health
		want.hp = cfg.espHealthBar and cfg.espHpMode ~= "Never"
		want.hpAlways = cfg.espHpMode == "Always"
		want.weapon = cfg.espWeapon
		want.dist = cfg.espDistance
		want.flags = cfg.espFlags ~= false
		want.outline = cfg.espOutline ~= false
		want.tracer = cfg.espTracers and not perf
		local outlineColor = Vis.OUTLINE
		local smallSize = math.max(9, textSize - 3)
		local offList, offVoid = Vis.offTbl, Vis.offVoid
		table.clear(offList)
		table.clear(offVoid)
		-- perspective: screen pixels per stud at depth z = (vp.Y / 2) / (z · tan(fov / 2))
		local pxPerStud = (vp.Y * 0.5) / math.tan(math.rad(math.clamp(cam.FieldOfView, 1, 120)) * 0.5)
		-- a limb this close to the camera plane pads the box by size / depth — thousands of pixels at 0.1 st:
		-- the whole-screen boxes when someone walked through / beside the camera
		local nearZ = Vis.NEAR_Z
		local radCap = vp.Y * 0.3
		local sv = Vis.sv
		local sp = Vis.screenTbl
		local idx, arrowIdx = 0, 0
		for rank, fighter in ipairs(list) do
			local root, model = Game.fighterBody(fighter)
			local head = Game.fighterHead(fighter)
			if root then
				local dist = dcache[fighter] or 0
				local bp = if model then Vis.bodyParts(model) else nil
				local detail = rank <= Vis.LOD_N
				local skel = want.skel and detail
				-- project the body once: the box is the extent of the projected parts (each padded by
				-- its own projected half-size), the skeleton reuses the same points
				table.clear(sp)
				local minX, minY, maxX, maxY = math.huge, math.huge, -math.huge, -math.huge
				local anyFront, anyOn = false, false
				local cut = false
				local parts = if bp and #bp.box > 0 then (if skel then bp.parts else bp.box) else nil
				if parts then
					for _, p in ipairs(parts) do
						if p.Parent ~= nil then
							local v, on = cam:WorldToViewportPoint(p.Position)
							if v.Z < nearZ then
								cut = true -- behind the camera or right on its plane
							else
								anyFront = true
								anyOn = anyOn or on
								local x, y = v.X, v.Y
								if skel then
									sp[p] = Vector2.new(x, y)
								end
								local rad = math.min(p.Size.Magnitude * 0.5 * pxPerStud / v.Z, radCap)
								if x - rad < minX then
									minX = x - rad
								end
								if x + rad > maxX then
									maxX = x + rad
								end
								if y - rad < minY then
									minY = y - rad
								end
								if y + rad > maxY then
									maxY = y + rad
								end
							end
						end
					end
				end
				if cut and anyFront then
					-- the camera plane cuts this body: the limbs left in front are a slice, not the player (the
					-- box shrank to a hand or ballooned) — the head-to-feet estimate below, or an arrow
					anyFront, anyOn = false, false
					minX, minY, maxX, maxY = math.huge, math.huge, -math.huge, -math.huge
					table.clear(sp)
				end
				if not anyFront then
					-- no limb parts (a destructible, a bare fallback wrapper) or a cut body: head-to-feet estimate
					local topPos = (if head then head.Position else root.Position + Vector3.new(0, 1.5, 0)) + Vector3.new(0, 0.5, 0)
					local top = Vis.w2sNear(cam, topPos, nearZ)
					local foot = Vis.w2sNear(cam, root.Position - Vector3.new(0, 2.9, 0), nearZ)
					if top and foot then
						anyFront = true
						local hgt0 = math.abs(foot.Y - top.Y)
						local wid0 = math.max(10, hgt0 * 0.45)
						minX, maxX = top.X - wid0 / 2, top.X + wid0 / 2
						minY, maxY = math.min(top.Y, foot.Y), math.max(top.Y, foot.Y)
						anyOn = (top.X >= 0 and top.X <= vp.X and top.Y >= 0 and top.Y <= vp.Y) or (foot.X >= 0 and foot.X <= vp.X and foot.Y >= 0 and foot.Y <= vp.Y)
					end
				end
				-- the box is drawn while it touches the screen at all (a half-visible enemy keeps his
				-- box, clipped by the screen edge); fully outside or behind → arrow
				local onScreen = anyFront and not (maxX < 0 or minX > vp.X or maxY < 0 or minY > vp.Y)
				if onScreen then
					idx += 1
					local s = Vis.slot(idx)
					-- integer-snapped box: fractional edges smear a 1–2 px line over three pixels
					local x, y = math.floor(minX + 0.5), math.floor(minY + 0.5)
					local wid, hgt = math.max(6, math.floor(maxX - minX + 0.5)), math.max(8, math.floor(maxY - minY + 0.5))
					local cx = x + wid / 2
					local foot = Vector2.new(cx, y + hgt)
					local hp, maxHp = Game.fighterHealth(fighter)
					local name = Game.fighterName(fighter)
					local color = if vis[model] then colVisible else colHidden
					-- with flags on, the resolver tags and IMMUNE go into the flag column instead of the name
					local immune = Game.fighterImmune(fighter)
					local tag = if want.flags or not model then "" else Resolver.tag(model)
					if immune then
						if not want.flags then
							tag = if tag == "" then "IMMUNE" else tag .. " IMMUNE"
						end
						color = Vis.IMMUNE_COLOR
					end
					if want.fill then
						local fill = Vis.slotObj(s, "f", "Square")
						sv(fill, "Size", Vector2.new(wid, hgt))
						sv(fill, "Position", Vector2.new(x, y))
						sv(fill, "Color", color)
						sv(fill, "Filled", true)
						sv(fill, "Transparency", fillAlpha)
						sv(fill, "ZIndex", 0)
						sv(fill, "Visible", true)
					elseif s.f then
						sv(s.f, "Visible", false)
					end
					-- a far enemy in a crowd gets the flat box instead of the 3D one
					if want.full or (want.box3d and not detail) then
						Vis.box2d(s, x, y, wid, hgt, color, lw, want.outline)
					else
						Vis.box2dOff(s)
					end
					if want.corner then
						local len = math.max(4, math.floor(math.min(wid, hgt) * 0.25))
						local x2, y2 = x + wid, y + hgt
						local ol = want.outline
						Vis.cornerSeg(s, 1, x, y, x + len, y, color, lw, ol)
						Vis.cornerSeg(s, 2, x, y, x, y + len, color, lw, ol)
						Vis.cornerSeg(s, 3, x2, y, x2 - len, y, color, lw, ol)
						Vis.cornerSeg(s, 4, x2, y, x2, y + len, color, lw, ol)
						Vis.cornerSeg(s, 5, x, y2, x + len, y2, color, lw, ol)
						Vis.cornerSeg(s, 6, x, y2, x, y2 - len, color, lw, ol)
						Vis.cornerSeg(s, 7, x2, y2, x2 - len, y2, color, lw, ol)
						Vis.cornerSeg(s, 8, x2, y2, x2, y2 - len, color, lw, ol)
					else
						Vis.arrsOff(s.c, 1)
						Vis.arrsOff(s.co, 1)
					end
					-- 3D box from the body parts' extents in root space (no GetBoundingBox per frame)
					local box3dOk = want.box3d and detail and bp ~= nil and #bp.parts > 0
					if box3dOk then
						local rcf = root.CFrame
						local lx, ly, lz, hx, hy, hz = math.huge, math.huge, math.huge, -math.huge, -math.huge, -math.huge
						for _, p in ipairs(bp.parts) do
							if p.Parent ~= nil then
								local lp = rcf:PointToObjectSpace(p.Position)
								local hs = p.Size * 0.5
								local r = math.max(hs.X, hs.Y, hs.Z)
								lx, ly, lz = math.min(lx, lp.X - r), math.min(ly, lp.Y - r), math.min(lz, lp.Z - r)
								hx, hy, hz = math.max(hx, lp.X + r), math.max(hy, lp.Y + r), math.max(hz, lp.Z + r)
							end
						end
						if lx < hx then
							local pts = Vis.box3dPts
							pts[1] = Vis.w2sNear(cam, rcf:PointToWorldSpace(Vector3.new(lx, hy, lz)), nearZ)
							pts[2] = Vis.w2sNear(cam, rcf:PointToWorldSpace(Vector3.new(hx, hy, lz)), nearZ)
							pts[3] = Vis.w2sNear(cam, rcf:PointToWorldSpace(Vector3.new(lx, hy, hz)), nearZ)
							pts[4] = Vis.w2sNear(cam, rcf:PointToWorldSpace(Vector3.new(hx, hy, hz)), nearZ)
							pts[5] = Vis.w2sNear(cam, rcf:PointToWorldSpace(Vector3.new(lx, ly, lz)), nearZ)
							pts[6] = Vis.w2sNear(cam, rcf:PointToWorldSpace(Vector3.new(hx, ly, lz)), nearZ)
							pts[7] = Vis.w2sNear(cam, rcf:PointToWorldSpace(Vector3.new(lx, ly, hz)), nearZ)
							pts[8] = Vis.w2sNear(cam, rcf:PointToWorldSpace(Vector3.new(hx, ly, hz)), nearZ)
							-- a corner behind / on the camera plane: the edges would jump between whatever corners are left —
							-- the flat box this frame instead of a broken wireframe
							local all = true
							for i = 1, 8 do
								if pts[i] == nil then
									all = false
									break
								end
							end
							if all then
								for i, e in ipairs(Vis.BOX_EDGES) do
									Vis.setLine(Vis.slotArr(s, s.x, i, "x", "Line"), pts[e[1]], pts[e[2]], color, lw)
								end
							else
							box3dOk = false
							Vis.box2d(s, x, y, wid, hgt, color, lw, want.outline)
							end
						else
							box3d = false
						end
					end
					if not box3d then
						Vis.arrsOff(s.x, 1)
					end
					-- skeleton from the same projected points
					if skel and bp then
						local bones = bp.bones
						local nLines = #bones // 2
						for i = 1, nLines do
							local a, b = bones[i * 2 - 1], bones[i * 2]
							Vis.setLine(Vis.slotArr(s, s.s, i, "s", "Line"), sp[a], sp[b], color, lw)
						end
						Vis.arrsOff(s.s, nLines + 1)
					else
						Vis.arrsOff(s.s, 1)
					end
					local hp2 = if want.dot and detail and head then Game.w2sFront(head.Position) else nil
					if hp2 then
						local dot = Vis.slotObj(s, "hd", "Circle")
						sv(dot, "Position", hp2)
						sv(dot, "Radius", math.max(2, math.floor(hgt * 0.04)))
						sv(dot, "NumSides", 24)
						sv(dot, "Color", color)
						sv(dot, "Filled", false)
						sv(dot, "Thickness", lw)
						sv(dot, "Visible", true)
					elseif s.hd then
						sv(s.hd, "Visible", false)
					end
					local barTop: number? = nil
					local barX = x - 4
					if want.bar and hp ~= nil and maxHp ~= nil and maxHp > 0 then
						local bg, fg = Vis.slotObj(s, "hb", "Square"), Vis.slotObj(s, "hf", "Square")
						-- invulnerable range dummies report inf / inf: a NaN here used to stick in the glide
						local ratio = (hp :: number) / (maxHp :: number)
						local pct = if ratio == ratio and ratio ~= math.huge then math.clamp(ratio, 0, 1) else 1
						-- the bar glides to the new value instead of snapping (readable damage feedback)
						local shown = s.hpShown
						if shown == nil or shown ~= shown or math.abs(shown - pct) < 0.004 then
							shown = pct
						else
							shown = shown + (pct - shown) * 0.35
						end
						s.hpShown = shown
						local barH = math.max(1, math.floor(hgt * shown + 0.5))
						local barW = if hgt > 140 then 3 else 2
						barX = x - 4 - barW
						-- a dark track one pixel larger on every side doubles as the bar's outline
						sv(bg, "Size", Vector2.new(barW + 2, hgt + 2))
						sv(bg, "Position", Vector2.new(barX - 1, y - 1))
						sv(bg, "Filled", true)
						sv(bg, "Color", barBg)
						sv(bg, "Transparency", 0.72)
						sv(bg, "ZIndex", 1)
						sv(bg, "Visible", true)
						sv(fg, "Size", Vector2.new(barW, barH))
						sv(fg, "Position", Vector2.new(barX, y + hgt - barH))
						sv(fg, "Filled", true)
						sv(fg, "Color", Vis.hpColor(shown, hpColor))
						sv(fg, "Transparency", 1)
						sv(fg, "ZIndex", 2)
						sv(fg, "Visible", true)
						barTop = y + hgt - barH
					else
						s.hpShown = nil
						if s.hb then
							sv(s.hb, "Visible", false)
						end
						if s.hf then
							sv(s.hf, "Visible", false)
						end
					end
					-- the health number sits beside the top of the bar (left of it, measured with last
					-- frame's width: TextBounds of a label whose text was just set is one frame stale)
					local showNum = want.hp and barTop ~= nil and hp ~= nil and maxHp ~= nil and (hp :: number) < math.huge and (want.hpAlways or (hp :: number) < (maxHp :: number) - 0.5)
					if showNum then
						local hpT = Vis.slotObj(s, "h", "Text")
						local shownHp = math.ceil(hp :: number)
						if s.hpTxtV ~= shownHp then
							s.hpTxtV = shownHp
							sv(hpT, "Text", tostring(shownHp))
						end
						Vis.styleText(hpT, smallSize, textColor, false)
						-- a far / short box is smaller than the text: the upper bound can fall under the lower
						local ty = math.clamp((barTop :: number) - smallSize * 0.5, y - 2, math.max(y - 2, y + hgt - smallSize))
						sv(hpT, "Position", Vector2.new(barX - 3 - s.hpW, ty))
						sv(hpT, "Visible", true)
						if hpT then
							s.hpW = Vis.textWidth(hpT, Vis.shadow[hpT] and Vis.shadow[hpT].Text, smallSize)
						end
					elseif s.h then
						sv(s.h, "Visible", false)
					end
					if want.names then
						local nameT = Vis.slotObj(s, "n", "Text")
						-- an extension badge (the Max module: "MAX" on other Max users) leads the name
						local badge, badgeCol = nil, nil
						local eb = S.ext.espBadge
						if eb then
							local okB, b, bc = pcall(eb, fighter)
							if okB and type(b) == "string" then
								badge, badgeCol = b, bc
							end
						end
						local label = if tag ~= "" then name .. " [" .. tag .. "]" else name
						sv(nameT, "Text", if badge then badge .. " · " .. label else label)
						Vis.styleText(nameT, textSize, if badge and typeof(badgeCol) == "Color3" then badgeCol elseif tag ~= "" then tagColor else textColor, true)
						sv(nameT, "Position", Vector2.new(cx, y - textSize - 3))
						sv(nameT, "Visible", true)
					elseif s.n then
						sv(s.n, "Visible", false)
					end
					local item = if want.weapon and detail then Game.enemyEquipped(fighter) else nil
					if item then
						local wpT = Vis.slotObj(s, "w", "Text")
						sv(wpT, "Text", tostring(item.Name))
						Vis.styleText(wpT, smallSize + 1, weaponColor, true)
						sv(wpT, "Position", Vector2.new(cx, y + hgt + 3))
						sv(wpT, "Visible", true)
					elseif s.w then
						sv(s.w, "Visible", false)
					end
					-- flags: a short column right of the box (distance, resolver tags, IMMUNE, VOID); near
					-- the screen's right edge it flips to the left of the box
					local nFlags = 0
					if detail and (want.dist or want.flags) then
						-- v5 void hunt: an enemy under the map floor gets a VOID flag (they can still shoot
						-- from a spot that IS on the map; Origin autokill / magic reach them below it).
						-- Only enemies well below us can be under the floor: the check is two raycasts.
						local isVoid = cfg.voidHunt and myPos ~= nil and root.Position.Y < myPos.Y - 30 and S.bounds.isVoidFighter(fighter)
						local flipped = (x + wid + 70) >= vp.X
						local fx = if flipped then barX - 6 - s.flW else x + wid + 4
						local lineH = smallSize + 1
						local maxW = 0
						if want.dist and myRoot then
							local dm = math.floor(dist)
							local key = if isVoid then -dm - 1 else dm
							if s.distV ~= key then
								s.distV = key
								s.distTxt = if isVoid then ("VOID %dm"):format(dm) else ("%dm"):format(dm)
							end
							nFlags += 1
							maxW = math.max(maxW, Vis.flagAt(s, nFlags, s.distTxt, if isVoid then Vis.VOID_COLOR else flagDim, fx, y - 1, smallSize, flipped))
						end
						if want.flags then
							local b = model and Resolver.buffers[model]
							if b and b.aa then
								nFlags += 1
								maxW = math.max(maxW, Vis.flagAt(s, nFlags, "AA", colVisible, fx, y - 1 + (nFlags - 1) * lineH, smallSize, flipped))
							end
							if b and b.desync then
								nFlags += 1
								maxW = math.max(maxW, Vis.flagAt(s, nFlags, "DESYNC", tagColor, fx, y - 1 + (nFlags - 1) * lineH, smallSize, flipped))
							end
							if b and b.fakelag then
								nFlags += 1
								maxW = math.max(maxW, Vis.flagAt(s, nFlags, "LAG", tagColor, fx, y - 1 + (nFlags - 1) * lineH, smallSize, flipped))
							end
							if immune then
								nFlags += 1
								maxW = math.max(maxW, Vis.flagAt(s, nFlags, "IMMUNE", Vis.IMMUNE_COLOR, fx, y - 1 + (nFlags - 1) * lineH, smallSize, flipped))
							end
							if isVoid and not want.dist then
								nFlags += 1
								maxW = math.max(maxW, Vis.flagAt(s, nFlags, "VOID", Vis.VOID_COLOR, fx, y - 1 + (nFlags - 1) * lineH, smallSize, flipped))
							end
							-- the counters' read of what they have been doing (void spam / teleports)
							local ctag = S.counter.tag(fighter)
							if ctag then
								nFlags += 1
								maxW = math.max(maxW, Vis.flagAt(s, nFlags, ctag, if ctag == "TP" then tagColor else Vis.VOID_COLOR, fx, y - 1 + (nFlags - 1) * lineH, smallSize, flipped))
							end
							-- extension flags (the Max module's enemy intel): { { text, Color3? }, ... }, at most 4
							local ef = S.ext.espFlags
							if ef then
							local okF, flags = pcall(ef, fighter)
							if okF and type(flags) == "table" then
								for fi = 1, math.min(#flags, 4) do
									local it = flags[fi]
										if type(it) == "table" and type(it[1]) == "string" then
											nFlags += 1
											maxW = math.max(maxW, Vis.flagAt(s, nFlags, it[1], if typeof(it[2]) == "Color3" then it[2] else flagDim, fx, y - 1 + (nFlags - 1) * lineH, smallSize, flipped))
										end
									end
								end
							end
						end
						if flipped then
							s.flW = maxW
						end
					end
					Vis.arrsOff(s.fl, nFlags + 1)
					if want.tracer and detail then
						local line = Vis.slotObj(s, "l", "Line")
						sv(line, "From", tracerFrom)
						sv(line, "To", foot)
						sv(line, "Color", tracerColor)
						sv(line, "Thickness", math.max(1, lw - 1))
						sv(line, "Visible", true)
					elseif s.l then
						sv(s.l, "Visible", false)
					end
				elseif cfg.voidHunt and myPos ~= nil and root.Position.Y < myPos.Y - 30 and S.bounds.isVoidFighter(fighter) then
					table.insert(offVoid, fighter)
				elseif cfg.espArrows then
					table.insert(offList, fighter)
				end
			end
		end
		-- off-screen arrows: every void hider, then the nearest enemies up to the cap. Nearer = larger
		-- and more solid; the dark edge is skipped on the GUI renderer (its triangle is a square)
		local maxArrows = math.max(1, math.floor(cfg.espArrowMax))
		if #offList > maxArrows then
			table.sort(offList, Vis.sortByDist)
		end
		local nVoid = #offVoid
		local edge = want.outline and not Vis.useGuiRenderer()
		for ai = 1, nVoid + math.min(#offList, maxArrows) do
			-- v5.0.4: a void hider is straight DOWN — the horizontal arrow said nothing about them.
			-- Their arrow points at the bottom of the screen with a depth label
			local voidF = ai <= nVoid
			local fighter = if voidF then offVoid[ai] else offList[ai - nVoid]
			local root, model = Game.fighterBody(fighter)
			local rel = root and cam.CFrame:PointToObjectSpace(root.Position)
			local dir = if voidF then Vector2.new(0, 1) elseif rel then Vector2.new(rel.X, rel.Z) else Vector2.zero
			if root and dir.Magnitude > 0.01 then
				arrowIdx += 1
				local tri = Vis.arrows[arrowIdx]
				if tri == nil then
					tri = Vis.draw("a" .. arrowIdx, "Triangle") or false
					Vis.arrows[arrowIdx] = tri
				end
				dir = dir.Unit
				local dist = dcache[fighter] or 0
				local near = 1 - math.clamp((dist - 20) / 180, 0, 1)
				local len = 10 + 6 * near
				local half = len * 0.55
				local tip = center + dir * cfg.espArrowRadius
				local perp = Vector2.new(-dir.Y, dir.X)
				local pa, pb, pc = tip, tip - dir * len + perp * half, tip - dir * len - perp * half
				local alpha = 0.55 + 0.45 * near
				local out = Vis.arrowOut[arrowIdx]
				if edge then
					if out == nil then
						out = Vis.draw("ao" .. arrowIdx, "Triangle") or false
						Vis.arrowOut[arrowIdx] = out
					end
					if out then
						local cen = (pa + pb + pc) / 3
						sv(out, "PointA", cen + (pa - cen) * 1.25)
						sv(out, "PointB", cen + (pb - cen) * 1.25)
						sv(out, "PointC", cen + (pc - cen) * 1.25)
						sv(out, "Color", outlineColor)
						sv(out, "Filled", true)
						sv(out, "Transparency", alpha * 0.8)
						sv(out, "ZIndex", 1)
						sv(out, "Visible", true)
					end
				elseif out then
					sv(out, "Visible", false)
				end
				if tri then
					sv(tri, "PointA", pa)
					sv(tri, "PointB", pb)
					sv(tri, "PointC", pc)
					sv(tri, "Color", if voidF then Vis.VOID_COLOR elseif vis[model] then colVisible else colHidden)
					sv(tri, "Filled", true)
					sv(tri, "Transparency", alpha)
					sv(tri, "ZIndex", 2)
					sv(tri, "Visible", true)
				end
				local lbl = Vis.arrowLabels[arrowIdx]
				if lbl == nil then
					lbl = Vis.draw("al" .. arrowIdx, "Text") or false
					Vis.arrowLabels[arrowIdx] = lbl
				end
				if lbl then
					if voidF and myRoot then
						local depth = math.floor(myRoot.Position.Y - root.Position.Y)
						local horiz = math.floor((Vector3.new(myRoot.Position.X, 0, myRoot.Position.Z) - Vector3.new(root.Position.X, 0, root.Position.Z)).Magnitude)
						Vis.arrowDistV[arrowIdx] = nil
						sv(lbl, "Text", ("VOID %dm down · %dm away"):format(depth, horiz))
						Vis.styleText(lbl, smallSize + 1, Vis.VOID_COLOR, true)
						sv(lbl, "Transparency", 1)
						sv(lbl, "Position", tip + Vector2.new(0, 10))
						sv(lbl, "Visible", true)
					elseif cfg.espArrowDist then
						local dm = math.floor(dist)
						if Vis.arrowDistV[arrowIdx] ~= dm then
							Vis.arrowDistV[arrowIdx] = dm
							sv(lbl, "Text", ("%dm"):format(dm))
						end
						Vis.styleText(lbl, smallSize, flagDim, true)
						sv(lbl, "Transparency", alpha)
						local lp = tip - dir * (len + 9)
						sv(lbl, "Position", Vector2.new(lp.X, lp.Y - smallSize * 0.5))
						sv(lbl, "Visible", true)
					else
						sv(lbl, "Visible", false)
					end
				end
			end
		end
		-- slots / arrows used last frame but not this one: hidden once (no pool scan)
		for i = idx + 1, Vis.slotsShown do
			local s = Vis.slots[i]
			if s then
				Vis.slotOff(s)
				s.hpShown = nil
			end
		end
		Vis.slotsShown = idx
		for i = arrowIdx + 1, Vis.arrowsShown do
			local tri = Vis.arrows[i]
			if tri then
				sv(tri, "Visible", false)
			end
			local out = Vis.arrowOut[i]
			if out then
				sv(out, "Visible", false)
			end
			local lbl = Vis.arrowLabels[i]
			if lbl then
				sv(lbl, "Visible", false)
			end
		end
		Vis.arrowsShown = arrowIdx
	end
	Vis.arrowLabels = {}
	Vis.arrowOut = {}
	Vis.arrowDistV = {}
	Vis.box3dPts = {}
	S.drawEsp = Vis.drawEsp
	S.drawingCount = Vis.drawingCount
	S.highlightCount = Vis.highlightCount

	-- radar: top-right square, enemies relative to the camera YAW only (the old projection used the
	-- full camera CFrame, so looking up or down squeezed every dot toward the centre)
	Vis.radarDots = {}
	Vis.radarShown = 0
	Vis.radarOn = false
	Vis.RADAR_BG, Vis.RADAR_GRID = Color3.fromRGB(8, 8, 11), Color3.fromRGB(40, 42, 58)
	Vis.LOCK_COLOR = Color3.fromRGB(255, 70, 100)
	function Vis.drawRadar(enemies: { any })
		local cam = workspace.CurrentCamera
		local on = cfg.radar and cfg.esp and cam ~= nil
		if not on then
			if Vis.radarOn then
				Vis.radarOn = false
				Vis.off("_rbg")
				Vis.off("_rbd")
				Vis.off("_rcd")
				Vis.off("_rla")
				Vis.off("_rlb")
				Vis.arrsOff(Vis.radarDots, 1)
				Vis.radarShown = 0
			end
			return
		end
		Vis.radarOn = true
		local bg = Vis.draw("_rbg", "Square")
		local bd = Vis.draw("_rbd", "Square")
		local cd = Vis.draw("_rcd", "Circle")
		local lnA, lnB = Vis.draw("_rla", "Line"), Vis.draw("_rlb", "Line")
		if not (bg and bd and cd and lnA and lnB) then
			return
		end
		local sv = Vis.sv
		local size = cfg.radarSize
		local origin = Vector2.new(cam.ViewportSize.X - size - 16, 64)
		local c = origin + Vector2.new(size / 2, size / 2)
		local sizeV = Vector2.new(size, size)
		sv(bg, "Position", origin)
		sv(bg, "Size", sizeV)
		sv(bg, "Color", Vis.RADAR_BG)
		sv(bg, "Filled", true)
		sv(bg, "Transparency", 0.75)
		sv(bg, "Visible", true)
		sv(bd, "Position", origin)
		sv(bd, "Size", sizeV)
		sv(bd, "Color", Vis.col("colEspVisible"))
		sv(bd, "Filled", false)
		sv(bd, "Thickness", 1)
		sv(bd, "Transparency", 0.9)
		sv(bd, "Visible", true)
		Vis.setLine(lnA, Vector2.new(c.X, origin.Y), Vector2.new(c.X, origin.Y + size), Vis.RADAR_GRID)
		Vis.setLine(lnB, Vector2.new(origin.X, c.Y), Vector2.new(origin.X + size, c.Y), Vis.RADAR_GRID)
		sv(cd, "Position", c)
		sv(cd, "Radius", 3)
		sv(cd, "Color", Vis.col("colText"))
		sv(cd, "Filled", true)
		sv(cd, "NumSides", 12)
		sv(cd, "Visible", true)
		local scale = (size / 2) / cfg.radarRange
		local look = cam.CFrame.LookVector
		local fwd = Vector3.new(look.X, 0, look.Z)
		fwd = if fwd.Magnitude > 0.01 then fwd.Unit else Vector3.new(0, 0, -1)
		local right = Vector3.new(-fwd.Z, 0, fwd.X)
		local camPos = cam.CFrame.Position
		local colVisible, colHidden = Vis.col("colEspVisible"), Vis.col("colEsp")
		local lockModel = S.silentTargetModel
		local vis = Vis.visTbl
		local n = 0
		for _, f in ipairs(enemies) do
			local root, model = Game.fighterBody(f)
			if root then
				n += 1
				local d = Vis.radarDots[n]
				if d == nil then
					d = Vis.draw("r" .. n, "Circle") or false
					Vis.radarDots[n] = d
				end
				if d then
					local rel = root.Position - camPos
					local v = Vector2.new(rel.X * right.X + rel.Z * right.Z, -(rel.X * fwd.X + rel.Z * fwd.Z)) * scale
					if v.Magnitude > size / 2 - 4 then
						v = v.Unit * (size / 2 - 4)
					end
					local locked = model ~= nil and model == lockModel
					sv(d, "Position", c + v)
					sv(d, "Radius", if locked then 4 else 3)
					sv(d, "Color", if locked then Vis.LOCK_COLOR elseif model and vis[model] then colVisible else colHidden)
					sv(d, "Filled", true)
					sv(d, "NumSides", 12)
					sv(d, "Visible", true)
				end
			end
		end
		Vis.arrsOff(Vis.radarDots, n + 1)
		Vis.radarShown = n
	end

	-- overlay: FOV circle, crosshair, hit markers — constants hoisted, every write deduplicated
	Vis.HM_OFF = { Vector2.new(-1, -1), Vector2.new(1, -1), Vector2.new(-1, 1), Vector2.new(1, 1) }
	Vis.CROSS = {
		{ "_c1", Vector2.new(-7, 0), Vector2.new(-2, 0) }, { "_c2", Vector2.new(2, 0), Vector2.new(7, 0) },
		{ "_c3", Vector2.new(0, -7), Vector2.new(0, -2) }, { "_c4", Vector2.new(0, 2), Vector2.new(0, 7) },
	}
	Vis.HM_COLOR_OK, Vis.HM_COLOR = Color3.fromRGB(70, 220, 150), Color3.new(1, 1, 1)
	function Vis.drawOverlay(accent: Color3, accent2: Color3)
		local cam = workspace.CurrentCamera
		if not cam then
			return
		end
		local sv = Vis.sv
		local center = cam.ViewportSize / 2
		-- v6.3: "One circle" (fovLinked) draws a single circle — the radius both the aimbot and silent aim
		-- use (the Silent aim tab's slider). It turns the lock colour while silent aim holds someone.
		-- no aim circles in the lobby: nothing there can be targeted
		local live = not S.featuresPaused
		local silentCircle = live and cfg.silentAim and Target.silentRadius() ~= math.huge
		local aimCircle = live and cfg.aimbot and not cfg.aimFov360
		local fov = Vis.draw("_fov", "Circle")
		if fov then
			local show = cfg.showFov and (if cfg.fovLinked then (aimCircle or silentCircle) else aimCircle)
			sv(fov, "Visible", show)
			if show then
				sv(fov, "Position", center)
				sv(fov, "Radius", if cfg.fovLinked then cfg.silentFov else cfg.aimFov)
				sv(fov, "NumSides", 64)
				sv(fov, "Color", if cfg.fovLinked and S.silentTarget then Vis.LOCK_COLOR elseif S.aimHeld then accent2 else accent)
				sv(fov, "Thickness", 1)
				sv(fov, "Filled", false)
				sv(fov, "Transparency", 0.8)
			end
		end
		local sfov = Vis.draw("_sfov", "Circle")
		if sfov then
			local show = silentCircle and cfg.showFov and not cfg.fovLinked
			sv(sfov, "Visible", show)
			if show then
				sv(sfov, "Position", center)
				sv(sfov, "Radius", cfg.silentFov)
				sv(sfov, "NumSides", 64)
				sv(sfov, "Color", if S.silentTarget then Vis.LOCK_COLOR else accent2)
				sv(sfov, "Thickness", 1)
				sv(sfov, "Filled", false)
				sv(sfov, "Transparency", 0.45)
			end
		end
		for _, seg in ipairs(Vis.CROSS) do
			local ln = Vis.draw(seg[1], "Line")
			if ln then
				sv(ln, "Visible", false)
			end
		end
		local dot = Vis.draw("_cdot", "Circle")
		local ring = Vis.draw("_cring", "Circle")
		local show = cfg.crosshair
		local sz = (cfg.crosshairSize or 1) * 7
		local style = cfg.crosshairStyle or "Classic"
		if dot then
			sv(dot, "Visible", show and (style == "Dot" or style == "Circle"))
			if show and (style == "Dot" or style == "Circle") then
				sv(dot, "Position", center)
				sv(dot, "Radius", if style == "Dot" then math.max(2, sz * 0.35) else sz)
				sv(dot, "Filled", style == "Dot" or style == "Circle")
				sv(dot, "Color", accent)
				sv(dot, "Thickness", 1)
				sv(dot, "NumSides", if style == "Circle" then 48 else 12)
			end
		end
		if ring and style == "Circle" then
			sv(ring, "Visible", show)
			if show then
				sv(ring, "Position", center)
				sv(ring, "Radius", sz)
				sv(ring, "Filled", false)
				sv(ring, "Color", accent)
				sv(ring, "Thickness", 1)
				sv(ring, "NumSides", 48)
			end
		elseif ring then
			sv(ring, "Visible", false)
		end
		if show and (style == "Classic" or style == "Cross") then
			local scale = cfg.crosshairSize or 1
			for _, seg in ipairs(Vis.CROSS) do
				local ln = Vis.draw(seg[1], "Line")
				if ln then
					sv(ln, "Visible", true)
					sv(ln, "From", center + seg[2] * scale)
					sv(ln, "To", center + seg[3] * scale)
					sv(ln, "Color", accent)
					sv(ln, "Thickness", if style == "Cross" then 2 else 1)
				end
			end
		end
		local age = os.clock() - (S.hitMarkerAt or 0)
		local showHm = cfg.hitMarkers and age < 0.25
		if showHm or Vis.hmShown then
			Vis.hmShown = showHm
			local confirmed = os.clock() - (S.lastConfirmAt or 0) < 0.3
			for i = 1, 4 do
				local ln = Vis.draw("_hm" .. i, "Line")
				if ln then
					if showHm then
						local o = Vis.HM_OFF[i]
						local spread = 6 + age * 30
						sv(ln, "From", center + o * spread)
						sv(ln, "To", center + o * (spread + 8))
						sv(ln, "Color", if confirmed then Vis.HM_COLOR_OK else Vis.HM_COLOR)
						sv(ln, "Thickness", 2)
						sv(ln, "Transparency", 1 - age / 0.25)
						sv(ln, "Visible", true)
					else
						sv(ln, "Visible", false)
					end
				end
			end
		end
	end

	---------------------------------------------------------------------------
	-- world lighting: night / fullbright / fog / sky / time / ambient / exposure / shadows / stars.
	-- Per-property ownership: the first write of a property keeps its original; the first pass that
	-- no longer wants it puts the original back and stops touching it. The game's own lighting keeps
	-- working on everything nobody here is changing, and one switch going off restores only its part.
	---------------------------------------------------------------------------
	Vis.worldSig = ""
	Vis.wOwned = setmetatable({}, { __mode = "k" })
	Vis.wUsed = setmetatable({}, { __mode = "k" })
	Vis.worldActive = false
	-- a property SET invalidates the lighting pipeline, a READ is free. Number properties are float32:
	-- a double never reads back equal, so numbers compare with a tolerance
	function Vis.same(cur: any, v: any): boolean
		if cur == v then
			return true
		end
		return type(cur) == "number" and type(v) == "number" and math.abs(cur - v) < 1e-4
	end
	function Vis.setIfDiff(obj: any, key: string, v: any)
		if not Vis.same(obj[key], v) then
			obj[key] = v
		end
	end
	-- values glide instead of popping: each owned property remembers what it shows and moves toward the
	-- wanted value by Vis.wAlpha per pass (set from the frame time, ~0.25 s to settle). Numbers and
	-- colours glide (ClockTime the short way round the clock); booleans and counts snap.
	Vis.wShown = setmetatable({}, { __mode = "k" })
	Vis.wAlpha = 1
	Vis.worldTau = 0.35 -- the glide's time constant in seconds (world preset and the look effects)
	function Vis.wStep(prop: string, from: any, v: any, alpha: number?): any
		local a = alpha or Vis.wAlpha
		if a >= 1 then
			return v
		end
		if type(v) == "number" and type(from) == "number" then
			local d = v - from
			if prop == "ClockTime" then
				d = (d + 12) % 24 - 12
			end
			if math.abs(d) < 1e-3 * math.max(1, math.abs(v)) then
				return v
			end
			local n = from + d * a
			return if prop == "ClockTime" then n % 24 else n
		elseif typeof(v) == "Color3" and typeof(from) == "Color3" then
			local n = from:Lerp(v, a)
			if math.abs(n.R - v.R) + math.abs(n.G - v.G) + math.abs(n.B - v.B) < 0.004 then
				return v
			end
			return n
		end
		return v
	end
	function Vis.wTake(obj: any, prop: string, v: any)
		local own = Vis.wOwned[obj]
		if not own then
			own = {}
			Vis.wOwned[obj] = own
		end
		if own[prop] == nil then
			own[prop] = obj[prop]
		end
		local used = Vis.wUsed[obj]
		if not used then
			used = {}
			Vis.wUsed[obj] = used
		end
		used[prop] = true
		local shown = Vis.wShown[obj]
		if not shown then
			shown = {}
			Vis.wShown[obj] = shown
		end
		local from = shown[prop]
		if from == nil then
			from = own[prop]
		end
		local n = Vis.wStep(prop, from, v)
		shown[prop] = n
		if not Vis.same(obj[prop], n) then
			obj[prop] = n
		end
	end
	-- give back every owned property the pass did not use: it glides home first and is dropped once it
	-- arrives (all = now, for unload / restore)
	function Vis.wRelease(all: boolean)
		for obj, own in pairs(Vis.wOwned) do
			local used = Vis.wUsed[obj]
			local shown = Vis.wShown[obj]
			for prop, orig in pairs(own) do
				if all or not (used and used[prop]) then
					local from = shown and shown[prop]
					local n = if all or from == nil then orig else Vis.wStep(prop, from, orig)
					pcall(function()
						obj[prop] = n
					end)
					if n == orig or Vis.same(n, orig) then
						own[prop] = nil
						if shown then
							shown[prop] = nil
						end
					else
						shown[prop] = n
					end
				end
			end
			if next(own) == nil then
				Vis.wOwned[obj] = nil
			end
		end
		for _, used in pairs(Vis.wUsed) do
			table.clear(used)
		end
	end
	Vis.FULLBRIGHT_AMBIENT = Color3.fromRGB(200, 200, 210)
	Vis.NIGHT_A0, Vis.NIGHT_A1 = Color3.fromRGB(22, 22, 40), Color3.fromRGB(120, 120, 165)
	Vis.NIGHT_O0, Vis.NIGHT_O1 = Color3.fromRGB(30, 30, 56), Color3.fromRGB(140, 140, 185)
	Vis.worldWant = { level = nil, amb = nil, out = nil }
	function Vis.worldWanted(): boolean
		return cfg.nightMode or cfg.fullbright or cfg.noFog or cfg.skyColorOn or cfg.timeOfDayOn or cfg.worldAmbientOn or cfg.worldExposureOn
			or cfg.worldShadows ~= "Default" or cfg.worldAtmos or cfg.worldStars
	end
	-- one pass: the value each property ends up with is decided first (custom ambient over night /
	-- fullbright, custom fog over "no fog"), then written once
	function Vis.worldPass()
		local take = Vis.wTake
		local amb, out, bright, shadows, expo, clock = nil, nil, nil, nil, nil, nil
		if cfg.fullbright then
			amb, out, bright, shadows, expo = Vis.FULLBRIGHT_AMBIENT, Vis.FULLBRIGHT_AMBIENT, cfg.brightness, false, 0.3
		elseif cfg.nightMode then
			-- never pitch black: the floor keeps the map readable on maps with no local lights,
			-- the slider lifts it toward dusk; exposure never goes negative (that was the "too
			-- dark sometimes" — the game's own ColorCorrection stacked on a -0.2 exposure)
			local t = math.clamp((cfg.nightLevel or 40) / 100, 0, 1)
			-- a touch of the accent in the night ambient, so the dark matches the menu and chams
			local ww = Vis.worldWant
			local acc = Vis.accent()
			if ww.level ~= t or ww.accent ~= acc then
				ww.level, ww.accent = t, acc
				ww.amb = Vis.NIGHT_A0:Lerp(Vis.NIGHT_A1, t):Lerp(acc, 0.1)
				ww.out = Vis.NIGHT_O0:Lerp(Vis.NIGHT_O1, t):Lerp(acc, 0.08)
			end
			amb, out, bright, shadows, expo = ww.amb, ww.out, 0.9 + 1.3 * t, false, 0.05 + 0.45 * t
		end
		if cfg.worldAmbientOn then
			amb, out = rgb(cfg.colAmbient), rgb(cfg.colOutdoor)
		end
		if cfg.worldExposureOn then
			expo = cfg.worldExposure
		end
		if cfg.worldShadows ~= "Default" then
			shadows = cfg.worldShadows == "On"
		end
		if cfg.nightMode then
			clock = 0
		elseif cfg.timeOfDayOn then
			clock = cfg.timeOfDay
		end
		if amb ~= nil then
			take(Lighting, "Ambient", amb)
			take(Lighting, "OutdoorAmbient", out)
		end
		if bright ~= nil then
			take(Lighting, "Brightness", bright)
		end
		if shadows ~= nil then
			take(Lighting, "GlobalShadows", shadows)
		end
		if expo ~= nil then
			take(Lighting, "ExposureCompensation", expo)
		end
		if clock ~= nil then
			take(Lighting, "ClockTime", clock)
		end
		-- custom fog on a map without an Atmosphere gets our own, removed with the switch
		local atm = Lighting:FindFirstChildOfClass("Atmosphere")
		if cfg.worldAtmos or cfg.skyColorOn then
			if not atm then
				atm = Vis.fxGet("Atmosphere", "CenterraAtmosphere")
			end
		elseif Vis.fxInst.CenterraAtmosphere then
			Vis.fxDrop("CenterraAtmosphere")
			atm = Lighting:FindFirstChildOfClass("Atmosphere")
		end
		if cfg.noFog and not cfg.worldAtmos then
			take(Lighting, "FogEnd", 1e6)
			take(Lighting, "FogStart", 1e6)
			if atm then
				take(atm, "Density", 0)
				take(atm, "Haze", 0)
			end
		end
		if cfg.worldAtmos and atm then
			local c = rgb(cfg.atmosColor)
			take(atm, "Density", cfg.atmosDensity)
			take(atm, "Haze", cfg.atmosHaze)
			take(atm, "Glare", cfg.atmosGlare)
			take(atm, "Color", c)
			take(atm, "Decay", c:Lerp(Color3.new(0, 0, 0), 0.35))
		end
		if cfg.skyColorOn then
			local c = rgb(cfg.skyColor)
			take(Lighting, "FogColor", c)
			-- the sky only takes a colour through the Atmosphere's haze; a clear one (haze 0) showed nothing
			if atm and not cfg.worldAtmos then
				take(atm, "Color", c)
				take(atm, "Decay", c:Lerp(Color3.new(0, 0, 0), 0.25))
				take(atm, "Haze", 2.2)
				take(atm, "Density", math.max(atm.Density, 0.25))
			end
		end
		if cfg.worldStars then
			local sky = Lighting:FindFirstChildOfClass("Sky") or Vis.fxGet("Sky", "CenterraSky")
			take(sky, "StarCount", 3000)
			take(sky, "CelestialBodiesShown", true)
		elseif Vis.fxInst.CenterraSky then
			Vis.fxDrop("CenterraSky")
		end
	end
	function Vis.worldRestore()
		Vis.wRelease(true)
		Vis.fxDrop("CenterraAtmosphere")
		Vis.fxDrop("CenterraSky")
		if Vis.worldActive then
			log("INFO", "world: lighting restored")
		end
		Vis.worldActive = false
		Vis.worldSig = ""
	end
	function Vis.worldApply()
		local now = os.clock()
		local dt = math.clamp(now - (Vis.wAt or now - 1 / 60), 0, 0.1)
		Vis.wAt = now
		-- a preset eases in over about a second (0.08 s read as a snap)
		Vis.wAlpha = 1 - math.exp(-dt / Vis.worldTau)
		if not Vis.worldWanted() then
			if Vis.worldActive then
				-- everything glides back, then the extras go and the log says so
				Vis.wRelease(false)
				if next(Vis.wOwned) == nil then
					Vis.worldRestore()
				end
			end
			return
		end
		Vis.worldActive = true
		-- at perf tier 1+ run the lighting pass every other frame. The release must run only on frames the pass
		-- ran: on a skipped frame nothing is marked used, so every owned property would glide back toward the
		-- map's value and the next pass drive it forward again — a per-frame flicker (and ~half-strength
		-- brightness/ambient, flipping GlobalShadows/StarCount) on Weak-PC mode and under autoPerf
		if not ((S.perfTier or 0) >= 1 and Game.frameId % 2 == 1) then
			local ok, err = pcall(Vis.worldPass)
			if not ok and Game.frameId % 300 == 0 then
				log("DEBUG", "world: " .. tostring(err):sub(1, 120))
			end
			Vis.wRelease(false)
		end
		-- the log line is built at 1 Hz at most, not every frame
		if Game.frameId % 60 == 0 then
			local sig = ("night %s %s · full %s · fog %s/%s · sky %s · time %s · amb %s · exp %s · shadows %s · stars %s"):format(
				tostring(cfg.nightMode), tostring(cfg.nightLevel), tostring(cfg.fullbright), tostring(cfg.noFog), tostring(cfg.worldAtmos),
				tostring(cfg.skyColorOn), if cfg.timeOfDayOn then tostring(cfg.timeOfDay) else "off", tostring(cfg.worldAmbientOn),
				if cfg.worldExposureOn then tostring(cfg.worldExposure) else "off", tostring(cfg.worldShadows), tostring(cfg.worldStars)
			)
			if sig ~= Vis.worldSig then
				Vis.worldSig = sig
				log("INFO", "world:", sig)
			end
		end
	end
	S.worldRestore = Vis.worldRestore
	S.worldApply = Vis.worldApply

	-- post effects: the game's blur / color correction / bloom / sun rays / DoF (never our CenterraBlur).
	-- Enabled state is remembered per effect and put back on toggle-off / unload.
	local postOrig: { [Instance]: boolean } = {}
	local POST_CLASSES = { BlurEffect = true, ColorCorrectionEffect = true, BloomEffect = true, SunRaysEffect = true, DepthOfFieldEffect = true }
	function Vis.postFxRestore()
		for fx, en in pairs(postOrig) do
			if fx.Parent then
				(fx :: any).Enabled = en
			end
		end
		table.clear(postOrig)
	end
	function Vis.postFxApply()
		local killAll = cfg.noPostFx
		local killCc = cfg.noDamageFx
		if not killAll and not killCc then
			if next(postOrig) then
				Vis.postFxRestore()
			end
			return
		end
		-- Lighting:GetChildren() allocates a table: scan twice a second, not every frame (a newly
		-- added effect is disabled within 0.5 s)
		if Game.frameId % 30 ~= 0 then
			return
		end
		for _, fx in ipairs(Lighting:GetChildren()) do
			if POST_CLASSES[fx.ClassName] and fx.Name:sub(1, 7) ~= "Centerra" then
				local e = fx :: any
				local kill = killAll or (killCc and fx:IsA("ColorCorrectionEffect"))
				if kill then
					if postOrig[fx] == nil then
						postOrig[fx] = e.Enabled
					end
					if e.Enabled then
						e.Enabled = false
					end
				elseif postOrig[fx] ~= nil then
					e.Enabled = postOrig[fx]
					postOrig[fx] = nil
				end
			end
		end
	end
	S.postFxRestore = Vis.postFxRestore

	-- map textures / motion blur / skybox presets (local only; restored on toggle-off / unload)
	Vis.texOrig = S.keep()
	Vis.texLastScan = 0
	Vis.motionLast = nil :: CFrame?
	Vis.motionBlurSize = 0
	local SKY_PRESETS = {
		Sunset = { "rbxassetid://271042516", "rbxassetid://271077243", "rbxassetid://271042556", "rbxassetid://271042658", "rbxassetid://271043003", "rbxassetid://271042964" },
		Nebula = { "rbxassetid://159454299", "rbxassetid://159454296", "rbxassetid://159454293", "rbxassetid://159454286", "rbxassetid://159454299", "rbxassetid://159454296" },
		Arctic = { "rbxassetid://628094946", "rbxassetid://628094947", "rbxassetid://628094948", "rbxassetid://628094949", "rbxassetid://628094950", "rbxassetid://628094951" },
	}
	function Vis.worldExtrasRestore()
		for part, orig in pairs(Vis.texOrig) do
			if part.Parent then
				pcall(function()
					part.Material = orig.material
					part.Color = orig.color
					part.Transparency = orig.trans
					-- put back the decals/textures "No textures" hid: they were never restored before, so the
					-- map's decals and weapon wraps stayed invisible until a rejoin
					if orig.decals then
						for d, t in pairs(orig.decals) do
							if d.Parent then
								d.Transparency = t
							end
						end
					end
				end)
			end
		end
		table.clear(Vis.texOrig)
		Vis.fxDrop("CenterraMotionBlur")
		local sky = Vis.fxInst.CenterraSky
		if sky and cfg.skyboxPreset == "Off" then
			Vis.fxDrop("CenterraSky")
		end
	end
	function Vis.textureScan()
		if not (cfg.worldNoTextures or cfg.worldTextureTint) then
			if next(Vis.texOrig) then
				Vis.worldExtrasRestore()
			end
			return
		end
		local now = os.clock()
		if now - Vis.texLastScan < 2 then
			return
		end
		Vis.texLastScan = now
		local tint = rgb(cfg.colWorldTint)
		local chars = {}
		for _, plr in Players:GetPlayers() do
			if plr.Character then
				chars[plr.Character] = true
			end
		end
		-- never touch view models / held weapons / our own camera fx: stripping and tinting those wrecked
		-- wraps and skins (and, with the decal bug above, never put them back)
		local cam = workspace.CurrentCamera
		local viewModels = workspace:FindFirstChild("ViewModels")
		for _, inst in workspace:GetDescendants() do
			if inst:IsA("BasePart")
				and not chars[inst:FindFirstAncestorOfClass("Model")]
				and not (cam and inst:IsDescendantOf(cam))
				and not (viewModels and inst:IsDescendantOf(viewModels)) then
				local orig = Vis.texOrig[inst]
				if not orig then
					orig = { material = inst.Material, color = inst.Color, trans = inst.Transparency }
					Vis.texOrig[inst] = orig
				end
				if cfg.worldNoTextures then
					inst.Material = Enum.Material.SmoothPlastic
					for _, d in inst:GetDescendants() do
						if d:IsA("Decal") or d:IsA("Texture") then
							orig.decals = orig.decals or {}
							if orig.decals[d] == nil then
								orig.decals[d] = d.Transparency
							end
							d.Transparency = 1
						end
					end
				end
				if cfg.worldTextureTint then
					inst.Color = orig.color:Lerp(tint, 0.35)
				elseif cfg.worldNoTextures then
					inst.Color = orig.color
				end
			end
		end
	end
	function Vis.motionBlurTick()
		if not cfg.worldMotionBlur or cfg.lowSpec then
			Vis.motionLast = nil
			Vis.motionBlurSize = 0
			Vis.fxDrop("CenterraMotionBlur")
			return
		end
		local cam = workspace.CurrentCamera
		if not cam then
			return
		end
		local cf = cam.CFrame
		local last = Vis.motionLast
		Vis.motionLast = cf
		local speed = 0
		if last then
			local _, yaw = (last:ToObjectSpace(cf)):ToEulerAnglesYXZ()
			speed = math.abs(yaw) * 180 / math.pi
		end
		local want = math.clamp(speed * 0.08 * (cfg.worldMotionBlurScale or 1), 0, 24)
		Vis.motionBlurSize = Vis.motionBlurSize + (want - Vis.motionBlurSize) * 0.25
		if Vis.motionBlurSize < 0.05 then
			-- camera stopped: disable the effect, don't destroy it — recreating a BlurEffect on every
			-- stop/start was needless instance churn
			local blur = Vis.fxInst and Vis.fxInst.CenterraMotionBlur
			if blur then
				Vis.fxSet(blur, "Enabled", false)
			end
			return
		end
		local blur = Vis.fxGet("BlurEffect", "CenterraMotionBlur")
		Vis.fxSet(blur, "Enabled", true)
		Vis.fxSet(blur, "Size", Vis.motionBlurSize)
	end
	function Vis.skyboxApply()
		local preset = cfg.skyboxPreset
		if preset == "Off" or preset == nil then
			if cfg.worldStars or cfg.skyColorOn then
				return
			end
			Vis.fxDrop("CenterraSky")
			return
		end
		local ids = SKY_PRESETS[preset]
		if not ids then
			return
		end
		local sky = Vis.fxGet("Sky", "CenterraSky")
		local keys = { "SkyboxBk", "SkyboxDn", "SkyboxFt", "SkyboxLf", "SkyboxRt", "SkyboxUp" }
		for i, k in ipairs(keys) do
			Vis.fxSet(sky, k, ids[i])
		end
	end
	function Vis.worldExtrasTick()
		if Game.frameId % 120 == 0 then
			Vis.textureScan()
		end
		if Game.frameId % 2 == 0 or cfg.worldMotionBlur then
			Vis.motionBlurTick()
		end
		if Game.frameId % 60 == 0 then
			Vis.skyboxApply()
		end
	end
	S.worldExtrasRestore = Vis.worldExtrasRestore

	---------------------------------------------------------------------------
	-- world effects (v5.3): our own grading / bloom / sun rays / depth of field, weather, bullet
	-- tracers, damage numbers, kill effects and the viewmodel / self chams. All local; every instance
	-- is named Centerra* ("Remove the game's effects" leaves them alone) and goes away with its switch
	-- and on unload.
	---------------------------------------------------------------------------
	Vis.fxInst = {}
	Vis.fxShadow = setmetatable({}, { __mode = "k" })
	function Vis.fxGet(class: string, name: string, parent: Instance?): any
		local inst = Vis.fxInst[name]
		if inst and inst.Parent then
			return inst
		end
		inst = Instance.new(class)
		inst.Name = name
		inst.Parent = parent or Lighting
		Vis.fxInst[name] = inst
		return inst
	end
	function Vis.fxDrop(name: string)
		local inst = Vis.fxInst[name]
		if inst then
			pcall(inst.Destroy, inst)
			Vis.fxInst[name] = nil
		end
	end
	-- written only when the value changed since our last write (float32 read-backs never compare
	-- equal to the double we wrote, so our own shadow copy is the reference)
	function Vis.fxSet(inst: any, prop: string, v: any)
		local sh = Vis.fxShadow[inst]
		if not sh then
			sh = {}
			Vis.fxShadow[inst] = sh
		end
		if sh[prop] ~= v then
			sh[prop] = v
			inst[prop] = v
		end
	end
	function Vis.accent(): Color3
		local tc = S.themeColors
		return if tc and typeof(tc.accent) == "Color3" then tc.accent else Color3.fromRGB(173, 102, 255)
	end
	-- the soft round sprite the menu glows use (generated PNG), or a built-in particle as fallback
	function Vis.dotTexture(): string
		local ui = S.uikit
		return if ui and type(ui.glowRadial) == "string" then ui.glowRadial else "rbxasset://textures/particles/sparkles_main.dds"
	end
	-- the local holder for everything placed in the world: an invisible anchored part at the origin
	-- under the camera, so attachment positions are world positions
	function Vis.fxHolder(): BasePart?
		local cam = workspace.CurrentCamera
		if not cam then
			return nil
		end
		local h = Vis.fxInst.CenterraFx
		if h and h.Parent == cam then
			return h
		end
		if h then
			pcall(h.Destroy, h)
		end
		local p = Instance.new("Part")
		p.Name = "CenterraFx"
		p.Anchored = true
		p.CanCollide = false
		p.CanQuery = false
		p.CanTouch = false
		p.CastShadow = false
		p.Transparency = 1
		p.Size = Vector3.new(0.2, 0.2, 0.2)
		p.CFrame = CFrame.new()
		p.Parent = cam
		Vis.fxInst.CenterraFx = p
		return p
	end

	-- the look effects ease like the world preset (about a second): numbers and colours glide toward the
	-- setting, a new effect grows in from its neutral values and a switched-off one fades back to them
	-- before it goes. Returns true once the value has arrived.
	Vis.FX_NEUTRAL = {
		CenterraGrade = { Brightness = 0, Contrast = 0, Saturation = 0, TintColor = Color3.new(1, 1, 1) },
		CenterraBloom = { Intensity = 0 },
		CenterraRays = { Intensity = 0 },
		CenterraDof = { FarIntensity = 0, NearIntensity = 0 },
	}
	Vis.fxAlpha = 1
	function Vis.fxEase(inst: any, prop: string, v: any, neutral: any?): boolean
		local sh = Vis.fxShadow[inst]
		if not sh then
			sh = {}
			Vis.fxShadow[inst] = sh
		end
		local cur = sh[prop]
		if cur == nil then
			cur = if neutral ~= nil then neutral else v
		end
		local n = Vis.wStep(prop, cur, v, Vis.fxAlpha)
		if n ~= sh[prop] then
			sh[prop] = n
			inst[prop] = n
		end
		return n == v
	end
	-- one effect: on → glide to its settings; off → glide to neutral, then drop it
	function Vis.fxRun(on: boolean, class: string, name: string, props: { [string]: any })
		local neutral = Vis.FX_NEUTRAL[name]
		if on then
			local inst = Vis.fxGet(class, name)
			for k, v in pairs(props) do
				Vis.fxEase(inst, k, v, neutral[k])
			end
			return
		end
		local inst = Vis.fxInst[name]
		if not inst then
			return
		end
		local settled = true
		for k, v in pairs(neutral) do
			if not Vis.fxEase(inst, k, v, nil) then
				settled = false
			end
		end
		if settled then
			Vis.fxDrop(name)
		end
	end
	Vis.fxProps = { grade = {}, bloom = {}, rays = {}, dof = {} }
	function Vis.postApply()
		local now = os.clock()
		local dt = math.clamp(now - (Vis.fxAt or now - 1 / 15), 0, 0.3)
		Vis.fxAt = now
		Vis.fxAlpha = 1 - math.exp(-dt / Vis.worldTau)
		local P = Vis.fxProps
		local g = P.grade
		g.Brightness, g.Contrast, g.Saturation, g.TintColor = cfg.gradeBrightness, cfg.gradeContrast, cfg.gradeSaturation, rgb(cfg.gradeTint)
		Vis.fxRun(cfg.worldGrade == true, "ColorCorrectionEffect", "CenterraGrade", g)
		local b = P.bloom
		b.Intensity, b.Size, b.Threshold = cfg.bloomIntensity, cfg.bloomSize, cfg.bloomThreshold
		Vis.fxRun(cfg.worldBloom == true, "BloomEffect", "CenterraBloom", b)
		local r = P.rays
		r.Intensity, r.Spread = cfg.sunRaysIntensity, cfg.sunRaysSpread
		Vis.fxRun(cfg.worldSunRays == true, "SunRaysEffect", "CenterraRays", r)
		local d = P.dof
		d.FocusDistance, d.InFocusRadius, d.FarIntensity, d.NearIntensity = cfg.dofFocus, math.clamp(cfg.dofFocus * 0.5, 5, 50), cfg.dofBlur, 0
		Vis.fxRun(cfg.worldDof == true, "DepthOfFieldEffect", "CenterraDof", d)
	end

	-- weather: one particle emitter on an invisible box that follows the camera. Motion comes from
	-- acceleration (speed 0 or a random 180° spread), so it never depends on the emit direction.
	Vis.WEATHER = {
		-- v6.4.1 sizes: the soft sprite shows ~a third of its size, so 0.05-st drops were sub-pixel; rain now
		-- lives long enough to fall past eye level before it fades
		Snow = { rate = 3, life = NumberRange.new(6, 9), speed = NumberRange.new(0.5, 1.5), accel = Vector3.new(0.6, -2, 0.3), size = { 0.22, 0.36 }, color = ColorSequence.new(Color3.fromRGB(245, 248, 255)), light = 0.35, influence = 0.3, alpha = 0.15, box = Vector3.new(90, 6, 90), offset = Vector3.new(0, 26, 0) },
		Rain = { rate = 24, life = NumberRange.new(0.55, 0.65), speed = NumberRange.new(0, 0), accel = Vector3.new(0, -240, 0), size = { 0.18, 0.18 }, color = ColorSequence.new(Color3.fromRGB(150, 172, 205)), light = 0.1, influence = 1, alpha = 0.2, box = Vector3.new(70, 4, 70), offset = Vector3.new(0, 26, 0), squash = 3, parallel = true },
		Embers = { rate = 1.2, life = NumberRange.new(4, 7), speed = NumberRange.new(0.3, 1), accel = Vector3.new(0.3, 1.4, 0.2), size = { 0.15, 0.28 }, color = ColorSequence.new(Color3.fromRGB(255, 196, 110), Color3.fromRGB(255, 84, 60)), light = 1, influence = 0, alpha = 0.05, box = Vector3.new(70, 10, 70), offset = Vector3.new(0, -3, 0) },
		Dust = { rate = 1, life = NumberRange.new(7, 11), speed = NumberRange.new(0.2, 0.8), accel = Vector3.new(0, 0.05, 0), size = { 0.1, 0.2 }, color = nil, light = 0.6, influence = 0, alpha = 0.35, box = Vector3.new(50, 24, 50), offset = Vector3.zero },
	}
	Vis.weatherKind = nil
	function Vis.weatherTick()
		local kind = cfg.worldWeather
		local w = Vis.WEATHER[kind]
		local cam = workspace.CurrentCamera
		if not (w and cam) then
			if Vis.weatherKind then
				Vis.weatherKind = nil
				Vis.fxDrop("CenterraWeather")
			end
			return
		end
		local part = Vis.fxInst.CenterraWeather
		if not (part and part.Parent == cam) or Vis.weatherKind ~= kind then
			Vis.fxDrop("CenterraWeather")
			part = Instance.new("Part")
			part.Name = "CenterraWeather"
			part.Anchored = true
			part.CanCollide = false
			part.CanQuery = false
			part.CanTouch = false
			part.CastShadow = false
			part.Transparency = 1
			part.Size = w.box
			local pe = Instance.new("ParticleEmitter")
			pe.Name = "CenterraWeatherFx"
			pe.Texture = Vis.dotTexture()
			pe.Shape = Enum.ParticleEmitterShape.Box
			pe.ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume
			pe.Lifetime = w.life
			pe.Speed = w.speed
			pe.SpreadAngle = Vector2.new(180, 180)
			pe.Acceleration = w.accel
			pe.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, w.size[1]), NumberSequenceKeypoint.new(1, w.size[2]) })
			pe.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.15, w.alpha), NumberSequenceKeypoint.new(0.8, w.alpha), NumberSequenceKeypoint.new(1, 1) })
			pe.Color = w.color or ColorSequence.new(Color3.new(1, 1, 1):Lerp(Vis.accent(), 0.35))
			pe.LightEmission = w.light
			pe.LightInfluence = w.influence
			pe.RotSpeed = NumberRange.new(-40, 40)
			pe.Rotation = NumberRange.new(0, 360)
			if w.squash then
				pe.Squash = NumberSequence.new(w.squash)
			end
			if w.parallel then
				pe.Orientation = Enum.ParticleOrientation.VelocityParallel
			end
			pe.Parent = part
			part.Parent = cam
			Vis.fxInst.CenterraWeather = part
			Vis.weatherKind = kind
		end
		local pe = part:FindFirstChild("CenterraWeatherFx")
		if pe then
			Vis.fxSet(pe, "Rate", w.rate * cfg.weatherDensity * (if cfg.lowSpec then 0.5 else 1))
		end
		part.CFrame = CFrame.new(cam.CFrame.Position + w.offset)
	end

	-- bullet tracers: the server's hit points for our own shots (Shots.serverResult queues them),
	-- drawn as a thin bright core inside a soft wider beam that fade out together
	Vis.shotQueue, Vis.tracers = {}, {}
	function Vis.tracerNew(holder: BasePart): any
		local a0 = Instance.new("Attachment")
		a0.Name = "CenterraTracer"
		a0.Parent = holder
		local a1 = Instance.new("Attachment")
		a1.Name = "CenterraTracer"
		a1.Parent = holder
		local function beam(width: number): Beam
			local b = Instance.new("Beam")
			b.Name = "CenterraTracer"
			b.Attachment0 = a0
			b.Attachment1 = a1
			b.FaceCamera = true
			b.LightEmission = 1
			b.LightInfluence = 0
			b.Segments = 1
			b.Width0 = width
			b.Width1 = width
			b.Enabled = false
			b.Parent = holder
			return b
		end
		return { a0 = a0, a1 = a1, core = beam(0.05), glow = beam(0.22), t = 0, busy = false }
	end
	function Vis.tracerTick()
		local q = Vis.shotQueue
		if not cfg.shotTracers then
			table.clear(q)
			for _, tr in ipairs(Vis.tracers) do
				if tr.busy then
					tr.busy = false
					tr.core.Enabled = false
					tr.glow.Enabled = false
				end
			end
			return
		end
		local now = os.clock()
		local holder = if #q > 0 or #Vis.tracers > 0 then Vis.fxHolder() else nil
		if not holder then
			table.clear(q)
			return
		end
		local cam = workspace.CurrentCamera
		local life = cfg.shotTracerLife
		local col = if cfg.shotTracerAccent then Vis.accent() else rgb(cfg.colShotTracer)
		local guard = 0
		while #q > 0 and guard < 16 do
			guard += 1
			local e = table.remove(q, 1)
			local tr = nil
			for _, x in ipairs(Vis.tracers) do
				if not x.busy and x.a0.Parent == holder then
					tr = x
					break
				end
			end
			if not tr and #Vis.tracers < 24 then
				tr = Vis.tracerNew(holder)
				table.insert(Vis.tracers, tr)
			end
			if tr then
				-- first person: start at the gun (below and right of the eye), not inside the camera
				local from = e[1]
				if cam and not cfg.thirdPerson and (from - cam.CFrame.Position).Magnitude < 4 then
					local cf = cam.CFrame
					from = cf.Position + cf.RightVector * 0.5 - cf.UpVector * 0.35 + cf.LookVector * 1.2
				end
				tr.a0.Position = from
				tr.a1.Position = e[2]
				tr.t = now
				tr.busy = true
				tr.core.Color = ColorSequence.new(Color3.new(1, 1, 1):Lerp(col, 0.35))
				tr.glow.Color = ColorSequence.new(col)
				tr.core.Enabled = true
				tr.glow.Enabled = true
			end
		end
		for i = #Vis.tracers, 1, -1 do
			local tr = Vis.tracers[i]
			if tr.a0.Parent ~= holder then
				-- the holder was replaced (new camera): this tracer went with it
				table.remove(Vis.tracers, i)
			elseif tr.busy then
				local k = (now - tr.t) / life
				if k >= 1 then
					tr.busy = false
					tr.core.Enabled = false
					tr.glow.Enabled = false
				else
					local f = k * k
					tr.core.Transparency = NumberSequence.new(0.35 + 0.65 * f, 0.05 + 0.95 * f)
					tr.glow.Transparency = NumberSequence.new(0.85 + 0.15 * f, 0.6 + 0.4 * f)
				end
			end
		end
	end

	-- damage numbers: a billboard per confirmed damage tick, rising and fading (Combat.updateShotConfirm
	-- queues { position, damage })
	Vis.hitQueue, Vis.hitNums = {}, {}
	function Vis.hitNumTick()
		local q = Vis.hitQueue
		if not cfg.hitNumbers then
			table.clear(q)
			for _, h in ipairs(Vis.hitNums) do
				if h.busy then
					h.busy = false
					h.bb.Enabled = false
				end
			end
			return
		end
		if #q == 0 and #Vis.hitNums == 0 then
			return
		end
		local holder = Vis.fxHolder()
		if not holder then
			table.clear(q)
			return
		end
		local now = os.clock()
		local guard = 0
		while #q > 0 and guard < 8 do
			guard += 1
			local e = table.remove(q, 1)
			local h = nil
			for _, x in ipairs(Vis.hitNums) do
				if not x.busy and x.a.Parent == holder then
					h = x
					break
				end
			end
			if not h and #Vis.hitNums < 12 then
				local a = Instance.new("Attachment")
				a.Name = "CenterraHitNum"
				a.Parent = holder
				local bb = Instance.new("BillboardGui")
				bb.Name = "CenterraHitNum"
				bb.AlwaysOnTop = true
				bb.LightInfluence = 0
				bb.Size = UDim2.fromOffset(90, 34)
				bb.Adornee = a
				bb.Enabled = false
				bb.Parent = a
				local t = Instance.new("TextLabel")
				t.BackgroundTransparency = 1
				t.Size = UDim2.fromScale(1, 1)
				t.TextStrokeTransparency = 0.4
				t.TextStrokeColor3 = Color3.new(0, 0, 0)
				local F = S.uikit and S.uikit.F
				if F and typeof(F.bold) == "Font" then
					t.FontFace = F.bold
				else
					t.Font = Enum.Font.BuilderSansBold
				end
				t.Parent = bb
				h = { a = a, bb = bb, t = t, busy = false, at = 0, base = Vector3.zero }
				table.insert(Vis.hitNums, h)
			end
			if h then
				local dmg = math.floor(e[2] + 0.5)
				h.busy = true
				h.at = now
				-- a little sideways scatter so fast ticks don't stack into one number
				h.base = e[1] + Vector3.new((math.random() - 0.5) * 1.2, 0.6, (math.random() - 0.5) * 1.2)
				h.t.Text = tostring(dmg)
				h.t.TextColor3 = if dmg >= 50 then Vis.accent():Lerp(Color3.new(1, 1, 1), 0.25) else Color3.fromRGB(242, 240, 247)
				h.a.Position = h.base
				h.bb.Enabled = true
			end
		end
		for i = #Vis.hitNums, 1, -1 do
			local h = Vis.hitNums[i]
			if h.a.Parent ~= holder then
				table.remove(Vis.hitNums, i)
			elseif h.busy then
				local k = (now - h.at) / 0.9
				if k >= 1 then
					h.busy = false
					h.bb.Enabled = false
				else
					h.a.Position = h.base + Vector3.new(0, 2.4 * (1 - (1 - k) * (1 - k)), 0)
					h.t.TextSize = math.floor(22 - 4 * math.min(k * 4, 1) + 0.5)
					local fade = math.clamp((k - 0.45) / 0.55, 0, 1)
					h.t.TextTransparency = fade
					h.t.TextStrokeTransparency = 0.4 + 0.6 * fade
				end
			end
		end
	end

	-- blood: six reused emitters on the fx holder, round robin. Emitted particles live in world space, so an
	-- emitter moves on to the next hit while the last splash is still falling
	Vis.bloodQueue, Vis.bloodPool, Vis.bloodIdx = {}, {}, 0
	function Vis.bloodAt(pos: Vector3, n: number)
		local holder = Vis.fxHolder()
		if not holder then
			return
		end
		Vis.bloodIdx = Vis.bloodIdx % 6 + 1
		local e = Vis.bloodPool[Vis.bloodIdx]
		if not (e and e.a.Parent == holder) then
			local a = Instance.new("Attachment")
			a.Name = "CenterraBlood"
			a.Parent = holder
			local pe = Instance.new("ParticleEmitter")
			pe.Name = "CenterraBlood"
			pe.Texture = Vis.dotTexture()
			pe.Enabled = false
			pe.Lifetime = NumberRange.new(0.35, 0.7)
			pe.Speed = NumberRange.new(6, 15)
			pe.SpreadAngle = Vector2.new(180, 180)
			pe.Drag = 2
			pe.Acceleration = Vector3.new(0, -45, 0)
			pe.LightEmission = 0
			pe.LightInfluence = 1
			pe.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.3), NumberSequenceKeypoint.new(1, 0.08) })
			pe.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(0.7, 0.1), NumberSequenceKeypoint.new(1, 1) })
			pe.Color = ColorSequence.new(Color3.fromRGB(170, 8, 8), Color3.fromRGB(95, 0, 0))
			pe.Parent = a
			e = { a = a, pe = pe }
			Vis.bloodPool[Vis.bloodIdx] = e
		end
		e.a.Position = pos
		e.pe:Emit(n)
	end
	function Vis.bloodTick()
		local q = Vis.bloodQueue
		if #q == 0 then
			return
		end
		if not cfg.hitBlood then
			table.clear(q)
			return
		end
		local guard = 0
		while #q > 0 and guard < 6 do
			guard += 1
			Vis.bloodAt(table.remove(q, 1), 16)
		end
	end

	-- kill effects: an expanding ring at their feet or a spark burst (Combat.updateKills queues positions)
	Vis.killQueue, Vis.killFx = {}, {}
	function Vis.killFxTick()
		local q = Vis.killQueue
		local now = os.clock()
		if #q > 0 then
			local holder = Vis.fxHolder()
			local kind = cfg.killEffect
			local guard = 0
			while #q > 0 and guard < 4 do
				guard += 1
				local pos = table.remove(q, 1)
				if holder and kind == "Ring" then
					local ring = Instance.new("Part")
					ring.Name = "CenterraKillFx"
					ring.Shape = Enum.PartType.Cylinder
					ring.Material = Enum.Material.Neon
					ring.Color = Vis.accent()
					ring.Anchored = true
					ring.CanCollide = false
					ring.CanQuery = false
					ring.CanTouch = false
					ring.CastShadow = false
					ring.Transparency = 0.2
					ring.Size = Vector3.new(0.12, 2, 2)
					ring.CFrame = CFrame.new(pos - Vector3.new(0, 2.6, 0)) * CFrame.Angles(0, 0, math.pi / 2)
					ring.Parent = holder
					table.insert(Vis.killFx, { inst = ring, t = now, kind = "Ring", life = 0.7 })
				elseif holder and kind == "Blood" then
					Vis.bloodAt(pos, 50)
				elseif holder and kind == "Burst" then
					local a = Instance.new("Attachment")
					a.Name = "CenterraKillFx"
					a.Position = pos
					a.Parent = holder
					local pe = Instance.new("ParticleEmitter")
					pe.Name = "CenterraKillFx"
					pe.Texture = Vis.dotTexture()
					pe.Enabled = false
					pe.Lifetime = NumberRange.new(0.4, 0.8)
					pe.Speed = NumberRange.new(12, 24)
					pe.SpreadAngle = Vector2.new(180, 180)
					pe.Drag = 4
					pe.Acceleration = Vector3.new(0, -10, 0)
					pe.LightEmission = 1
					pe.LightInfluence = 0
					pe.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.35), NumberSequenceKeypoint.new(1, 0) })
					pe.Color = ColorSequence.new(Vis.accent(), Color3.new(1, 1, 1))
					pe.Parent = a
					pe:Emit(36)
					table.insert(Vis.killFx, { inst = a, t = now, kind = "Burst", life = 1.5 })
				end
			end
		end
		for i = #Vis.killFx, 1, -1 do
			local fx = Vis.killFx[i]
			local k = (now - fx.t) / fx.life
			if k >= 1 or fx.inst.Parent == nil then
				pcall(fx.inst.Destroy, fx.inst)
				table.remove(Vis.killFx, i)
			elseif fx.kind == "Ring" then
				local d = 2 + 14 * (1 - (1 - k) * (1 - k))
				fx.inst.Size = Vector3.new(0.12, d, d)
				fx.inst.Transparency = 0.2 + 0.8 * k
			end
		end
	end

	-- chams on your own viewmodel / body: material + colour per part, the part's own look kept the
	-- first time it is touched and put back when the switch goes off (wrap textures hide meanwhile)
	Vis.MATERIALS = { ForceField = Enum.Material.ForceField, Neon = Enum.Material.Neon, Glass = Enum.Material.Glass, SmoothPlastic = Enum.Material.SmoothPlastic }
	function Vis.materialLabel(v: any): string
		return if v == "ForceField" then "Force field" elseif v == "SmoothPlastic" then "Smooth plastic" else tostring(v)
	end
	Vis.chamsStore = S.keep()
	function Vis.chamsPart(p: BasePart, owner: string, mat: any, col: Color3, ltm: number?)
		local st = Vis.chamsStore[p]
		if not st then
			st = { owner = owner, Material = p.Material, Color = p.Color, LTM = p.LocalTransparencyModifier, kids = {} }
			if p:IsA("MeshPart") then
				st.TextureID = (p :: any).TextureID
			end
			for _, ch in ipairs(p:GetChildren()) do
				if ch:IsA("Decal") or ch:IsA("Texture") then
					st.kids[ch] = ch.Transparency
				end
			end
			Vis.chamsStore[p] = st
		end
		if p.Material ~= mat then
			p.Material = mat
		end
		if p.Color ~= col then
			p.Color = col
		end
		if st.TextureID ~= nil and st.TextureID ~= "" and (p :: any).TextureID ~= "" then
			pcall(function()
				(p :: any).TextureID = ""
			end)
		end
		for ch in pairs(st.kids) do
			if ch.Parent == p and ch.Transparency < 1 then
				ch.Transparency = 1
			end
		end
		if ltm and p.LocalTransparencyModifier < ltm then
			p.LocalTransparencyModifier = ltm
		end
	end
	function Vis.chamsRestore(owner: string?)
		if owner == nil or owner == "self" then
			for ch, st in pairs(Vis.clothStore or {}) do
				pcall(function()
					if ch.Parent then
						(ch :: any)[st.prop] = st.v
					end
				end)
				Vis.clothStore[ch] = nil
			end
			if Vis.selfGlow then
				pcall(Vis.selfGlow.Destroy, Vis.selfGlow)
				Vis.selfGlow = nil
			end
		end
		for p, st in pairs(Vis.chamsStore) do
			if owner == nil or st.owner == owner then
				pcall(function()
					if p.Parent then
						p.Material = st.Material
						p.Color = st.Color
						if st.TextureID ~= nil then
							(p :: any).TextureID = st.TextureID
						end
						if owner == "vm" and not cfg.hideViewmodel then
							p.LocalTransparencyModifier = st.LTM
						end
						for ch, tr in pairs(st.kids) do
							if ch.Parent == p then
								ch.Transparency = tr
							end
						end
					end
				end)
				Vis.chamsStore[p] = nil
			end
		end
	end
	Vis.chamsOn = { vm = false, self = false }
	Vis.chamsAt = 0
	function Vis.chamsTick()
		-- v6.3 perf: the full paint pass reads Material / Color / TextureID / decals on every part; it was
		-- 1.35 ms of a 2.75 ms frame in an empty hub. The game only resets them on a swap or respawn, so
		-- 10 passes a second hold the look; switching either option off still restores at once.
		local now = os.clock()
		local turningOff = (not cfg.vmChams and Vis.chamsOn.vm) or (not cfg.selfChams and Vis.chamsOn.self)
		if not turningOff and now - Vis.chamsAt < 0.1 then
			return
		end
		Vis.chamsAt = now
		if cfg.vmChams then
			Vis.chamsOn.vm = true
			local mat = Vis.MATERIALS[cfg.vmMaterial] or Enum.Material.ForceField
			local col = rgb(cfg.colVm)
			-- see-through only while nothing else hides the viewmodel (that one wins)
			local ltm = if cfg.vmAlpha > 0 and not cfg.hideViewmodel and not cfg.thirdPerson then cfg.vmAlpha else nil
			-- the weapon only: the arms are rebuilt, recoloured and hidden by the game every swap and
			-- fought the chams (and the part cache also holds Decals / Textures, never parts)
			for _, m in ipairs(Game.viewmodelModels()) do
				local weapon = Game.viewmodelWeapon(m)
				if weapon then
					for _, p in ipairs(Game.modelParts(weapon, 0.5)) do
						if p.Parent ~= nil and p:IsA("BasePart") and p.Transparency < 1 then
							Vis.chamsPart(p, "vm", mat, col, ltm)
						end
					end
				end
			end
		elseif Vis.chamsOn.vm then
			Vis.chamsOn.vm = false
			Vis.chamsRestore("vm")
		end
		if cfg.selfChams then
			Vis.chamsOn.self = true
			local lf = Game.localFighter()
			local model = nil
			if lf then
				local _, m = Game.fighterBody(lf)
				model = m
			end
			if model then
				Vis.selfChams(model)
			end
		elseif Vis.chamsOn.self then
			Vis.chamsOn.self = false
			Vis.chamsRestore("self")
		end
	end
	-- self chams paint EVERY visible part of the character — accessories too (only the named limbs
	-- used to change, hats and hair kept their look) — and blank the clothing templates, which the
	-- engine composites onto the body over any material (the shirt and pants showed through the
	-- chams). The invisible hitboxes / root / FakeMass are skipped. An accent outline makes the body
	-- read in third person. Everything goes back in Vis.chamsRestore("self").
	Vis.clothStore = S.keep()
	Vis.CLOTH_PROPS = { Shirt = "ShirtTemplate", Pants = "PantsTemplate", ShirtGraphic = "Graphic" }
	function Vis.selfSkip(p: BasePart): boolean
		local n = p.Name
		return p.Transparency >= 1 or n == "HumanoidRootPart" or n == "FakeMass" or n:sub(1, 6) == "Hitbox" or n:sub(1, 14) == "PhysicalHitbox"
	end
	function Vis.selfChams(model: Model)
		local mat = Vis.MATERIALS[cfg.selfMaterial] or Enum.Material.ForceField
		local col = rgb(cfg.colSelf)
		for _, d in ipairs(Game.modelParts(model, 0.5)) do
			if d.Parent ~= nil and d:IsA("BasePart") and not Vis.selfSkip(d) then
				Vis.chamsPart(d, "self", mat, col, nil)
			end
		end
		for _, ch in ipairs(model:GetChildren()) do
			local prop = Vis.CLOTH_PROPS[ch.ClassName]
			if prop then
				if Vis.clothStore[ch] == nil then
					Vis.clothStore[ch] = { prop = prop, v = (ch :: any)[prop] }
				end
				if (ch :: any)[prop] ~= "" then
					(ch :: any)[prop] = ""
				end
			end
		end
		local hl = Vis.selfGlow
		-- first person hides the body locally; an outline there would trace it around the camera
		if S.tpActive ~= true then
			if hl then
				pcall(hl.Destroy, hl)
				Vis.selfGlow = nil
			end
			return
		end
		if not (hl and hl.Parent == model) then
			if hl then
				pcall(hl.Destroy, hl)
			end
			hl = Instance.new("Highlight")
			hl.Name = "CenterraSelfGlow"
			hl.FillTransparency = 1
			hl.DepthMode = Enum.HighlightDepthMode.Occluded
			hl.Adornee = model
			hl.Parent = model
			Vis.selfGlow = hl
		end
		Vis.fxSet(hl, "OutlineColor", col)
		Vis.fxSet(hl, "OutlineTransparency", 0.35)
	end

	-- night mode, ignore hands: night mode darkens through Lighting (ambient, clock, exposure), not a
	-- screen filter, so a light travelling with the camera can keep the viewmodel lit without lifting
	-- the map. A SpotLight sits in front of the gun and shines back at the camera (its cone ends at
	-- you, so walls and floors stay dark), and a Highlight on each viewmodel model adds the accent glow.
	Vis.handsGlow = S.keep()
	function Vis.handsWanted(): boolean
		return cfg.nightMode == true and cfg.nightHands ~= false and not cfg.fullbright and not cfg.hideViewmodel and S.tpActive ~= true
	end
	function Vis.handsOff()
		Vis.fxDrop("CenterraHandsLight")
		for m, hl in pairs(Vis.handsGlow) do
			pcall(hl.Destroy, hl)
			Vis.handsGlow[m] = nil
		end
		Vis.handsLit = false
	end
	function Vis.handsTick()
		if not Vis.handsWanted() then
			if Vis.handsLit then
				Vis.handsOff()
			end
			return
		end
		local cam = workspace.CurrentCamera
		local holder = Vis.fxHolder()
		if not (cam and holder) then
			return
		end
		Vis.handsLit = true
		local g = math.clamp((tonumber(cfg.nightHandsGlow) or 60) / 100, 0, 1)
		local accent = Vis.accent()
		local att = Vis.fxGet("Attachment", "CenterraHandsLight", holder)
		local light = att:FindFirstChildOfClass("SpotLight")
		if not light then
			light = Instance.new("SpotLight")
			light.Shadows = false
			light.Face = Enum.NormalId.Back
			light.Angle = 100
			light.Parent = att
		end
		-- the holder sits at the origin, so the attachment's CFrame is a world CFrame
		att.CFrame = cam.CFrame * CFrame.new(0.35, -0.15, -3.2)
		Vis.fxSet(light, "Range", 4.2)
		Vis.fxSet(light, "Brightness", 0.8 + 3.2 * g)
		Vis.fxSet(light, "Color", Color3.new(1, 1, 1):Lerp(accent, 0.18))
		-- the glow on the weapon only (the arms stay as they are), re-attached when a weapon swap
		-- rebuilds the viewmodel (4 Hz is plenty)
		if Game.frameId % 15 == 0 then
			local fillT, lineT = 1 - 0.22 * g, 0.85 - 0.6 * g
			for _, vm in ipairs(Game.viewmodelModels()) do
				local m = Game.viewmodelWeapon(vm)
				if m then
					local hl = Vis.handsGlow[m]
					if not (hl and hl.Parent == m) then
						hl = Instance.new("Highlight")
						hl.Name = "CenterraHandsGlow"
						hl.DepthMode = Enum.HighlightDepthMode.Occluded
						hl.Adornee = m
						hl.Parent = m
						Vis.handsGlow[m] = hl
					end
					Vis.fxSet(hl, "FillColor", accent)
					Vis.fxSet(hl, "OutlineColor", accent)
					Vis.fxSet(hl, "FillTransparency", fillT)
					Vis.fxSet(hl, "OutlineTransparency", lineT)
				end
			end
			for m, hl in pairs(Vis.handsGlow) do
				if m.Parent == nil or hl.Parent ~= m then
					pcall(hl.Destroy, hl)
					Vis.handsGlow[m] = nil
				end
			end
		end
	end

	-- one step per frame from the loop: effects at 15 Hz, animations every frame, chams at 10 Hz
	-- v6.5 Roblox stops drawing bloom, sun rays, depth of field and most weather particles at low graphics
	-- levels (level 1 showed none of them). While one is on, the render level goes to 8; it goes back to the
	-- player's own level when they are all off, on Weak PC mode and on unload. The saved setting is untouched.
	-- the player's own level is also written to disk while boosted: a server hop drops this Lua state without
	-- an unload, and the next load must restore that level, not mistake the boosted 8 for theirs
	Vis.qualityPrev, Vis.qualityChecked = nil, false
	Vis.QUALITY_FILE = DATA.dir .. "/quality.txt"
	function Vis.qualitySaved(): EnumItem?
		local ok, item = pcall(function()
			if EXEC.isfile and EXEC.readfile and EXEC.isfile(Vis.QUALITY_FILE) then
				return (Enum.QualityLevel :: any)[EXEC.readfile(Vis.QUALITY_FILE)]
			end
			return nil
		end)
		return if ok and typeof(item) == "EnumItem" then item else nil
	end
	function Vis.qualityForget()
		pcall(function()
			if EXEC.isfile and EXEC.delfile and EXEC.isfile(Vis.QUALITY_FILE) then
				EXEC.delfile(Vis.QUALITY_FILE)
			end
		end)
	end
	function Vis.qualityApply(want: boolean)
		local ok, rs = pcall(function()
			return settings().Rendering
		end)
		if not (ok and rs) then
			return
		end
		if want and Vis.qualityPrev == nil then
			Vis.qualityChecked = true
			local saved = Vis.qualitySaved()
			local orig = saved or rs.QualityLevel
			if orig.Value < Enum.QualityLevel.Level08.Value then
				Vis.qualityPrev = orig
				pcall(function()
					rs.QualityLevel = Enum.QualityLevel.Level08
				end)
				if not saved and EXEC.writefile then
					pcall(function()
						EXEC.mkdirs(DATA.dir)
						EXEC.writefile(Vis.QUALITY_FILE, orig.Name)
					end)
				end
				log("INFO", ("world: graphics %s → level 8 while bloom / rays / depth of field / weather are on"):format(orig.Name))
			else
				Vis.qualityPrev = false
			end
		elseif not want and Vis.qualityPrev ~= nil then
			local prev = Vis.qualityPrev
			Vis.qualityPrev = nil
			if prev then
				pcall(function()
					rs.QualityLevel = prev
				end)
			end
			Vis.qualityForget()
		elseif not want and not Vis.qualityChecked then
			-- first check of this load: a boost left over from before a hop goes back to the player's level
			Vis.qualityChecked = true
			local saved = Vis.qualitySaved()
			if saved then
				pcall(function()
					rs.QualityLevel = saved
				end)
				Vis.qualityForget()
				log("INFO", ("world: graphics back to %s (boost left over from the last server)"):format(saved.Name))
			end
		end
	end
	function Vis.fxTick()
		local f = Game.frameId
		if f % 4 == 0 then
			Vis.postApply()
			Vis.qualityApply(cfg.fxQuality and not cfg.lowSpec and (cfg.worldBloom or cfg.worldSunRays or cfg.worldDof or cfg.worldWeather ~= "Off"))
		end
		Vis.weatherTick()
		Vis.handsTick()
	end
	function Vis.shotFxTick()
		Vis.tracerTick()
		Vis.hitNumTick()
		Vis.bloodTick()
		Vis.killFxTick()
	end
	function Vis.fxRestore()
		Vis.handsOff()
		for name in pairs(Vis.fxInst) do
			Vis.fxDrop(name)
		end
		Vis.qualityApply(false)
		table.clear(Vis.tracers)
		table.clear(Vis.hitNums)
		table.clear(Vis.killFx)
		table.clear(Vis.shotQueue)
		table.clear(Vis.hitQueue)
		table.clear(Vis.killQueue)
		table.clear(Vis.bloodQueue)
		table.clear(Vis.bloodPool)
		Vis.weatherKind = nil
		Vis.chamsRestore(nil)
		Vis.chamsOn.vm, Vis.chamsOn.self = false, false
	end
	S.fxRestore = Vis.fxRestore

	-- world looks: one click sets every world switch together (the rest of the config is untouched)
	Vis.WORLD_KEYS = {
		"nightMode", "fullbright", "noFog", "skyColorOn", "timeOfDayOn", "noPostFx", "worldGrade", "worldBloom", "worldSunRays",
		"worldDof", "worldAtmos", "worldAmbientOn", "worldExposureOn", "worldShadows", "worldStars", "worldWeather",
	}
	Vis.WORLD_PRESETS = {
		Dusk = {
			timeOfDayOn = true, timeOfDay = 17.8, worldGrade = true, gradeBrightness = 0, gradeContrast = 0.12, gradeSaturation = 0.2, gradeTint = { 255, 236, 222 },
			worldBloom = true, bloomIntensity = 0.6, bloomSize = 24, bloomThreshold = 1.4, worldSunRays = true, sunRaysIntensity = 0.1, sunRaysSpread = 0.5,
			worldAtmos = true, atmosDensity = 0.32, atmosHaze = 1.6, atmosGlare = 0.4, atmosColor = { 255, 190, 150 },
		},
		["Neon night"] = {
			nightMode = true, nightLevel = 45, worldGrade = true, gradeBrightness = 0.02, gradeContrast = 0.15, gradeSaturation = 0.3, gradeTint = { 236, 226, 255 },
			worldBloom = true, bloomIntensity = 1, bloomSize = 28, bloomThreshold = 1, worldAtmos = true, atmosDensity = 0.3, atmosHaze = 1.2, atmosGlare = 0.2,
			atmosColor = { 173, 102, 255 }, worldAmbientOn = true, colAmbient = { 90, 70, 140 }, colOutdoor = { 110, 90, 170 }, worldStars = true,
		},
		Dream = {
			worldGrade = true, gradeBrightness = 0.03, gradeContrast = 0.05, gradeSaturation = 0.35, gradeTint = { 245, 228, 255 },
			worldBloom = true, bloomIntensity = 1.4, bloomSize = 40, bloomThreshold = 0.9, worldSunRays = true, sunRaysIntensity = 0.2, sunRaysSpread = 0.8,
			worldAtmos = true, atmosDensity = 0.38, atmosHaze = 2.2, atmosGlare = 0.6, atmosColor = { 220, 180, 255 }, worldWeather = "Dust", weatherDensity = 40,
		},
		Arctic = {
			timeOfDayOn = true, timeOfDay = 10, worldGrade = true, gradeBrightness = 0.02, gradeContrast = 0.1, gradeSaturation = -0.2, gradeTint = { 222, 236, 255 },
			worldBloom = true, bloomIntensity = 0.5, bloomSize = 20, bloomThreshold = 1.5, worldAtmos = true, atmosDensity = 0.3, atmosHaze = 1.8, atmosGlare = 0.2,
			atmosColor = { 200, 225, 255 }, worldWeather = "Snow", weatherDensity = 50,
		},
		Crisp = {
			noFog = true, noPostFx = true, worldGrade = true, gradeBrightness = 0.02, gradeContrast = 0.18, gradeSaturation = 0.1, gradeTint = { 255, 255, 255 }, worldShadows = "Off",
		},
	}
	function Vis.applyWorldPreset(name: string)
		local p = Vis.WORLD_PRESETS[name]
		for _, k in ipairs(Vis.WORLD_KEYS) do
			local d = DEFAULTS[k]
			cfg[k] = if type(d) == "table" then table.clone(d) else d
		end
		if p then
			for k, v in pairs(p) do
				cfg[k] = if type(v) == "table" then table.clone(v) else v
			end
		end
		cfg.worldPreset = if p then name else ""
		saveConfig()
		notify(if p then "World look: " .. name else "World effects are off", 2, "ok")
	end

	-- viewmodel hidden everywhere (not only third person). The game's viewmodel is not a Camera
	-- child: Game.viewmodelModels() finds our models under workspace.ViewModels.
	local vmHidden: { [Instance]: number } = S.keep() -- weapon swaps: S.keepPrune drops the dead parts
	function Vis.viewmodelRestore()
		for p, tr in pairs(vmHidden) do
			if p.Parent then
				(p :: any).LocalTransparencyModifier = tr
			end
		end
		table.clear(vmHidden)
	end
	local function hideVmPart(d: Instance)
		if d.Parent ~= nil then
			if vmHidden[d] == nil then
				vmHidden[d] = (d :: any).LocalTransparencyModifier
			end
			if (d :: any).LocalTransparencyModifier < 1 then
				(d :: any).LocalTransparencyModifier = 1
			end
		end
	end
	function Vis.viewmodelApply()
		local mode = if cfg.hideViewmodel then "all" elseif cfg.hideHands then "hands" else nil
		if mode ~= Vis.vmMode then
			-- switching all -> hands must give the weapon back
			Vis.vmMode = mode
			if next(vmHidden) then
				Vis.viewmodelRestore()
			end
		end
		if not mode then
			return
		end
		if mode == "hands" then
			-- the arms are direct children named LeftArm / RightArm (+ "Wrapped" meshes when a wrap is on);
			-- the weapon is ItemVisual beside them. The game rebuilds them each swap, so this re-applies.
			for _, m in ipairs(Game.viewmodelModels()) do
				if m:IsA("Model") then
					for _, c in ipairs(m:GetChildren()) do
						local nm = c.Name
						if nm:sub(1, 7) == "LeftArm" or nm:sub(1, 8) == "RightArm" then
							if c:IsA("BasePart") then
								hideVmPart(c)
							end
							for _, d in ipairs(Game.modelParts(c, 0.5)) do
								hideVmPart(d)
							end
						end
					end
				end
			end
			return
		end
		-- cached part lists (Game.modelParts, refreshed every 0.5 s) instead of GetDescendants + 3 IsA
		-- per descendant per model every 3rd frame
		for _, m in ipairs(Game.viewmodelModels()) do
			for _, d in ipairs(Game.modelParts(m, 0.5)) do
				if d.Parent ~= nil then
					if vmHidden[d] == nil then
						vmHidden[d] = d.LocalTransparencyModifier
					end
					if d.LocalTransparencyModifier < 1 then
						d.LocalTransparencyModifier = 1
					end
				end
			end
			if m:IsA("BasePart") then
				if vmHidden[m] == nil then
					vmHidden[m] = m.LocalTransparencyModifier
				end
				m.LocalTransparencyModifier = 1
			end
		end
	end

	-----------------------------------------------------------------------------
	-- §10 skins — local cosmetic unlock (exact inventory shape), local equips, direct picker data
	-----------------------------------------------------------------------------
	local Skins: any = {}
	S.skins = Skins

	function Skins.isCosKey(key: any): boolean
		return key == "CosmeticInventory" or key == Game.KEY_COS
	end
	function Skins.banned(name: any): boolean
		return type(name) ~= "string" or name:find("MISSING_", 1, true) ~= nil or name:find("Bubblegum", 1, true) ~= nil
	end
	function Skins.allowedType(t: any): boolean
		return t == "Skin" or t == "Wrap" or (cfg.unlockFinisher and t == "Finisher")
	end

	-- Real inventory shape (verified): skins -> { [weaponName] = true }, universal (wraps) -> true.
	-- Anything else breaks the game's ReplicatedController serializer, so mirror it exactly.
	local fakeInvCache: any = nil
	local fakeInvOrig: any = nil
	function Skins.fakeInventory(orig: any): any
		if fakeInvCache and fakeInvOrig == orig then
			return fakeInvCache
		end
		local inv = {}
		if type(orig) == "table" then
			for k, v in pairs(orig) do
				inv[k] = v
			end
		end
		for name, info in pairs(CosmeticLibrary.Cosmetics) do
			if inv[name] == nil and not Skins.banned(name) and not info.Hidden and Skins.allowedType(info.Type) then
				if type(info.ItemName) == "string" then
					inv[name] = { [info.ItemName] = true }
				else
					inv[name] = true
				end
			end
		end
		fakeInvCache = inv
		fakeInvOrig = orig
		return inv
	end
	function Skins.unlockable(name: any): boolean
		if not (S.alive and cfg.unlockCosmetics) or Skins.banned(name) then
			return false
		end
		local info = CosmeticLibrary.Cosmetics[name]
		return info ~= nil and Skins.allowedType(info.Type)
	end
	-- ownership according to the *real* inventory (the last one the game handed to fakeInventory)
	function Skins.reallyOwned(name: any, weaponName: any): boolean
		if type(name) ~= "string" then
			return false
		end
		-- runs inside the namecall hook (equip remote) → no method calls here; the customize UI has
		-- always called Get(CosmeticInventory) before a click, so the real inventory is cached
		local inv = fakeInvOrig
		if type(inv) ~= "table" then
			return false
		end
		local v = inv[name]
		if v == true then
			return true
		end
		if type(v) == "table" then
			-- owned for THIS weapon (or asked without one); "owned for any weapon" used to send an
			-- unowned equip to the server, which rejects it, and the local copy was dropped for nothing
			return weaponName == nil or v[weaponName] == true
		end
		return false
	end
	S.reallyOwned = Skins.reallyOwned

	-- our items by weapon name (LocalFighter.Items is empty between rounds)
	function Skins.items(): { any }
		local out = {}
		local lf = Game.localFighter()
		if type(lf) == "table" and type(lf.Items) == "table" then
			for _, item in pairs(lf.Items) do
				if type(item) == "table" and type(item.Name) == "string" then
					table.insert(out, item)
				end
			end
		end
		return out
	end
	function Skins.item(weaponName: string): any
		for _, item in ipairs(Skins.items()) do
			if item.Name == weaponName then
				return item
			end
		end
		return nil
	end
	-- the wire serial to rebuild from: the pristine copy our _CreateViewModel hook kept, or — for an
	-- item built before the hook — one reassembled from the viewmodel's own `_serial` (the game
	-- decodes only the wrapper key in place; the inner keys stay compressed, so wrapping that Data
	-- table with EnumLibrary:ToEnum("Data") gives back exactly what the constructor consumes)
	Skins.dataKeyCache = nil
	function Skins.dataKey(): string?
		if Skins.dataKeyCache == nil then
			local ok, key = pcall(function()
				return EnumLibrary:ToEnum("Data", true)
			end)
			Skins.dataKeyCache = if ok and type(key) == "string" then key else false
		end
		return if type(Skins.dataKeyCache) == "string" then Skins.dataKeyCache else nil
	end
	function Skins.serialOf(item: any): any
		if type(item) ~= "table" then
			return nil
		end
		local s = rawget(item, "_centerraVmSerial")
		if type(s) == "table" then
			return s
		end
		local vm = rawget(item, "ViewModel")
		local vs = type(vm) == "table" and rawget(vm, "_serial")
		local data = type(vs) == "table" and vs.Data
		local key = Skins.dataKey()
		if type(data) == "table" and key then
			s = { [key] = deepClone(data) }
			rawset(item, "_centerraVmSerial", s)
			return s
		end
		return nil
	end
	-- the model the server asked for (from the serial): the one string in it that is a viewmodel of
	-- this weapon. nil when no serial can be found.
	function Skins.serverVm(item: any, weaponName: string): string?
		local serial = Skins.serialOf(item)
		if type(serial) ~= "table" then
			return nil
		end
		for _, v in pairs(serial) do
			if type(v) == "table" then
				for _, v2 in pairs(v) do
					if S.h.isVmNameFor(v2, weaponName) then
						return v2
					end
				end
			elseif S.h.isVmNameFor(v, weaponName) then
				return v
			end
		end
		return nil
	end
	-- viewmodel name the game should be showing for this weapon right now
	function Skins.wantedVm(weaponName: string): string
		local skin = S.h.skinModelFor and S.h.skinModelFor(weaponName)
		if skin then
			return skin
		end
		return Skins.serverVm(Skins.item(weaponName), weaponName) or weaponName
	end
	-- what is in hand vs what we want: "ok" | "pending" | "none" (+ have, want, why)
	function Skins.state(weaponName: string): (string, string?, string?, string?)
		local item = Skins.item(weaponName)
		local vm = item and rawget(item, "ViewModel")
		local have = if type(vm) == "table" then tostring(vm.Name) else nil
		if not have then
			return "none", nil, Skins.wantedVm(weaponName), nil
		end
		local skin = S.h.skinModelFor and S.h.skinModelFor(weaponName)
		-- without a kept serial we cannot know what the server built → whatever is in hand is right
		local want = skin or Skins.serverVm(item, weaponName) or have
		if have == want then
			return "ok", have, want, nil
		end
		local why = Skins.lastNote[weaponName]
		if not Skins.serialOf(item) then
			why = "no viewmodel serial — shows on your next spawn"
		end
		return "pending", have, want, why
	end
	Skins.lastNote = {} -- weapon -> last rebuild failure note (shown in the menu)
	-- true while the item is mid-action; rebuilding then would cut an animation short
	function Skins.busy(item: any): string?
		if S.firing or (S.autokill and S.autokill.state ~= "idle" and S.autokill.state ~= "done") then
			return "firing"
		end
		local now = tick()
		if (tonumber(rawget(item, "_reload_cooldown")) or 0) > now then
			return "reloading"
		end
		if (tonumber(rawget(item, "_equip_cooldown")) or 0) > now then
			return "equipping"
		end
		if (tonumber(rawget(item, "_shoot_cooldown")) or 0) > now or rawget(item, "_is_input_queueing") == true then
			return "shooting"
		end
		return nil
	end

	-- Rebuild one item's viewmodel through the game's own path: ClientItem:_CreateViewModel(serial)
	-- (the exact call the item constructor makes, with the server's serial we kept) → our hook writes
	-- the skin's model name → the new ClientViewModel is equipped in place of the old one, which is
	-- unequipped, parked and destroyed a little later (nothing else keeps a reference to it: the
	-- fighter's per-frame Update and the interface read item.ViewModel live). Returns ok, note.
	function Skins.rebuild(item: any): (boolean, string)
		if type(item) ~= "table" or type(item._CreateViewModel) ~= "function" then
			return false, "no item"
		end
		local old = rawget(item, "ViewModel")
		if type(old) ~= "table" then
			return false, "item has no viewmodel"
		end
		local serial = Skins.serialOf(item)
		if type(serial) ~= "table" then
			return false, "no serial (shows on next spawn)"
		end
		local busy = Skins.busy(item)
		if busy then
			return false, "busy: " .. busy
		end
		local wasEquipped = item.IsEquipped == true or (type(old.IsEquipped) == "function" and select(2, pcall(old.IsEquipped, old)) == true)
		local wasAiming = select(2, pcall(function()
			return item:Get("IsAiming") == true
		end)) == true
		rawset(item, "_centerraRebuild", true)
		local ok, vm = Game.asGame(item._CreateViewModel, item, deepClone(serial))
		rawset(item, "_centerraRebuild", nil)
		if not ok or type(vm) ~= "table" then
			return false, "constructor failed: " .. tostring(vm):sub(1, 80)
		end
		item.ViewModel = vm
		-- listeners the item/interface attached to the old viewmodel's signals follow to the new one
		-- (GoodSignal: GetConnections + _fn). Skipped per signal when the constructor already wired
		-- as many handlers on the new one, so nothing runs twice.
		local migrated = 0
		for _, sig in ipairs({ "Equipped", "Unequipped", "AnimationPlayed", "AnimationStopped" }) do
			pcall(function()
				local from, to = rawget(old, sig), rawget(vm, sig)
				if type(from) ~= "table" or type(to) ~= "table" or type(from.GetConnections) ~= "function" then
					return
				end
				local have = to:GetConnections()
				local want = from:GetConnections()
				if #have >= #want then
					return
				end
				for _, c in ipairs(want) do
					local fn = rawget(c, "_fn")
					if c.Connected and type(fn) == "function" then
						to:Connect(fn)
						migrated += 1
					end
				end
			end)
		end
		if wasEquipped and type(vm.Equip) == "function" then
			Game.asGame(vm.Equip, vm, true)
			if wasAiming and type(vm.SetAiming) == "function" then
				Game.asGame(vm.SetAiming, vm, true) -- keep the scope where the item thinks it is
			end
		end
		pcall(function()
			if type(old.Unequip) == "function" then
				Game.asGame(old.Unequip, old)
			end
			if old.Model then
				old.Model.Parent = nil
			end
		end)
		task.delay(1, function()
			pcall(function()
				if type(old.Destroy) == "function" and rawget(item, "ViewModel") ~= old then
					Game.asGame(old.Destroy, old)
				end
			end)
		end)
		log("INFO", ("skins: rebuilt %s viewmodel → %s%s, %d listener(s) moved"):format(tostring(item.Name), tostring(vm.Name), if wasEquipped then " (in hand)" else "", migrated))
		return true, tostring(vm.Name)
	end
	-- bring every item we hold in line with the local equips (called after an equip and from the loop).
	-- force = a user click: ignores the retry cap so a stuck weapon can always be retried by hand
	function Skins.applyNow(weaponName: string?, force: boolean?): (number, string?)
		local n, note = 0, nil
		for _, item in ipairs(Skins.items()) do
			if weaponName == nil or item.Name == weaponName then
				local st, _, want = Skins.state(item.Name)
				if st == "pending" then
					-- an explicit apply (menu click, picker) always gets a fresh set of tries: the
					-- per-item retry cap otherwise blocked every later attempt for that item forever
					if force or weaponName ~= nil then
						Skins.tries[item] = nil
					end
					if cfg.skinRebuild then
						local ok, why = Skins.rebuild(item)
						if ok then
							n += 1
							Skins.lastNote[item.Name] = nil
						else
							note = why
							Skins.lastNote[item.Name] = why
							if not why:find("^busy") and not why:find("no serial") then
								log("WARN", ("skins: %s → %s not rebuilt: %s"):format(item.Name, tostring(want), why))
							end
						end
					else
						note = "instant apply is off — shows on your next spawn"
					end
				end
			end
		end
		if S.h.updateHeldWrap then
			pcall(S.h.updateHeldWrap)
		end
		return n, note
	end
	S.skinApplyNow = Skins.applyNow
	-- kept for probes/tests: wrap repaint on the held weapon (+ model catch-up)
	function Skins.refreshViewmodel(weaponName: string?)
		task.defer(function()
			pcall(Skins.applyNow, weaponName)
		end)
	end
	S.refreshViewmodel = Skins.refreshViewmodel

	function Skins.refreshEquipmentUi()
		-- only replicate with real enum keys; string keys make ReplicatedController throw
		pcall(function()
			local cur = PlayerDataController.CurrentData
			if not (cur and cur.Replicate) then
				return
			end
			for _, name in ipairs({ "WeaponInventory", "CosmeticInventory" }) do
				local ok, key = pcall(function()
					return EnumLibrary:ToEnum(name)
				end)
				if ok and key ~= nil and type(key) ~= "string" then
					Game.asGame(cur.Replicate, cur, key)
				end
			end
		end)
		pcall(function()
			local mods = LP.PlayerScripts:FindFirstChild("Modules")
			local ui = mods and mods:FindFirstChild("UserInterface")
			local Equipment = Game.requireIfLoaded(ui and ui:FindFirstChild("Equipment"))
			if type(Equipment) ~= "table" then
				return
			end
			-- the customize list bakes "locked" into each slot when it is generated (a locked slot
			-- ignores clicks), so while it is open re-run its own state-changed path → regenerate
			local iface = Equipment.Interface
			local customize = type(iface) == "table" and iface.Customize
			local cosmetics = type(customize) == "table" and customize.Cosmetics
			if Equipment.IsOpen == true and type(cosmetics) == "table" and type(cosmetics.OnStateChanged) == "function" then
				Game.asGame(cosmetics.OnStateChanged, cosmetics)
			elseif type(Equipment._Update) == "function" then
				Game.asGame(Equipment._Update, Equipment, 0)
			end
		end)
	end

	-- cosmetic data record the game's own code expects for an equip (a copy of the library entry)
	function Skins.record(cosName: string, inverted: boolean?): any
		local base = CosmeticLibrary.Cosmetics[cosName]
		if type(base) ~= "table" then
			return nil
		end
		local data = table.clone(base)
		data.Name = cosName
		if inverted ~= nil then
			data.Inverted = inverted
		end
		return data
	end
	-- local-only cosmetic equips: S.localEquips[weapon] = { Skin = data, Wrap = data } (what the
	-- hooks read) mirrored in cfg.skinEquips (names only, saved — equips survive hops and reinjects)
	function Skins.persist(weaponName: string)
		Skins.equipGen = (Skins.equipGen or 0) + 1
		local eq = S.localEquips[weaponName]
		local skin = eq and eq.Skin and eq.Skin.Name
		local wrap = eq and eq.Wrap and eq.Wrap.Name
		if type(skin) ~= "string" and type(wrap) ~= "string" then
			cfg.skinEquips[weaponName] = nil
		else
			cfg.skinEquips[weaponName] = {
				Skin = if type(skin) == "string" then skin else nil,
				Wrap = if type(wrap) == "string" then wrap else nil,
				WrapInverted = if eq.Wrap and eq.Wrap.Inverted == true then true else nil,
			}
		end
		saveConfigSoon() -- a hop restores 16 slots in one frame: one file write, not sixteen
	end
	-- rebuild S.localEquips from the saved names (fresh Lua state after a hop / first load)
	function Skins.load()
		local n = 0
		for weaponName, eq in pairs(cfg.skinEquips) do
			if type(weaponName) == "string" and type(eq) == "table" then
				local cur = S.localEquips[weaponName] or {}
				if type(eq.Skin) == "string" and CosmeticLibrary.Cosmetics[eq.Skin] then
					cur.Skin = Skins.record(eq.Skin)
					n += 1
				end
				if type(eq.Wrap) == "string" and CosmeticLibrary.Cosmetics[eq.Wrap] then
					cur.Wrap = Skins.record(eq.Wrap, eq.WrapInverted == true)
					n += 1
				end
				if next(cur) ~= nil then
					S.localEquips[weaponName] = cur
				end
			end
		end
		if n > 0 then
			log("INFO", ("skins: %d saved local equip(s) restored"):format(n))
		end
	end
	function Skins.applyLocalEquip(weaponName: any, cosType: any, cosName: any, options: any)
		if type(weaponName) ~= "string" or type(cosType) ~= "string" then
			return
		end
		if cosName == nil or cosName == "None" or cosName == "" then
			if S.localEquips[weaponName] then
				S.localEquips[weaponName][cosType] = nil
				if next(S.localEquips[weaponName]) == nil then
					S.localEquips[weaponName] = nil
				end
			end
			log("INFO", "skins: cleared", cosType, "on", weaponName)
		else
			local inverted = if type(options) == "table" and options.IsInverted ~= nil then options.IsInverted == true else nil
			local data = Skins.record(cosName, inverted)
			if not data then
				return
			end
			S.localEquips[weaponName] = S.localEquips[weaponName] or {}
			S.localEquips[weaponName][cosType] = data
			log("INFO", "skins: equipped", cosName, "(" .. cosType .. ") on", weaponName, "(local)")
		end
		Skins.persist(weaponName)
		task.defer(Skins.refreshEquipmentUi)
		-- wraps repaint live; a model skin (or clearing one) rebuilds the held viewmodel when allowed
		task.defer(function()
			pcall(Skins.applyNow, weaponName)
		end)
	end
	-- merge local equips into GetWeaponData so the customize UI and viewmodel show them
	-- the merged record is cached per (source record, weapon, equip generation): GetWeaponData is
	-- called by the game's UI for every slot render, and each call used to clone the record
	Skins.wdCache = setmetatable({}, { __mode = "k" })
	Skins.equipGen = 0
	function Skins.weaponData(data: any, weaponName: any): any
		if cfg.unlockCosmetics and type(data) == "table" and S.localEquips[weaponName] then
			local c = Skins.wdCache[data]
			if c and c.weapon == weaponName and c.gen == Skins.equipGen then
				return c.merged
			end
			local merged = table.clone(data)
			for cosType, cosData in pairs(S.localEquips[weaponName]) do
				merged[cosType] = cosData
			end
			Skins.wdCache[data] = { weapon = weaponName, gen = Skins.equipGen, merged = merged }
			return merged
		end
		return data
	end
	function Skins.clearAll()
		local weapons = {}
		for w in pairs(S.localEquips) do
			table.insert(weapons, w)
		end
		table.clear(S.localEquips)
		table.clear(cfg.skinEquips)
		Skins.equipGen = (Skins.equipGen or 0) + 1
		saveConfig()
		Skins.refreshEquipmentUi()
		task.defer(function()
			pcall(Skins.applyNow, nil)
		end)
		return #weapons
	end

	-- loop: catch-up rebuilds (a skin picked while firing/reloading, or a wanted model that changed)
	-- at 1 Hz. "busy" skips are free; at most two real constructor failures per item+model so a
	-- model the game refuses can never thrash the viewmodel.
	Skins.tries = setmetatable({}, { __mode = "k" })
	Skins.tickAt = 0
	function Skins.tick()
		if not cfg.skinRebuild or S.firing or os.clock() - Skins.tickAt < 1 then
			return
		end
		Skins.tickAt = os.clock()
		for _, item in ipairs(Skins.items()) do
			local st, _, want = Skins.state(item.Name)
			if st == "pending" and Skins.serialOf(item) then
				local tries = Skins.tries[item] or {}
				Skins.tries[item] = tries
				if (tries[want] or 0) < 2 then
					local ok, why = Skins.rebuild(item)
					if ok then
						Skins.lastNote[item.Name] = nil
					else
						Skins.lastNote[item.Name] = why
						if not why:find("^busy") then
							tries[want] = (tries[want] or 0) + 1
							log("WARN", ("skins: %s → %s not rebuilt: %s"):format(item.Name, tostring(want), why))
						end
					end
					break
				end
			end
		end
	end

	-- hide leftover "Locked" overlays inside the customize frame while unlock is on
	local lockedSweepAt = 0
	function Skins.sweepLocked()
		Skins.tick()
		if not cfg.unlockCosmetics or os.clock() - lockedSweepAt < 0.5 then
			return
		end
		lockedSweepAt = os.clock()
		-- the Customize frame is looked up once (a recursive FindFirstChild through MainGui every
		-- 0.5 s was one of the biggest lobby costs); the padlock badges are cached per generation of
		-- the list and re-collected only when the list was regenerated
		local customize = Skins.customizeFrame
		if not (customize and customize.Parent ~= nil) then
			local pg = LP:FindFirstChild("PlayerGui")
			local main = pg and pg:FindFirstChild("MainGui")
			customize = main and main:FindFirstChild("Customize", true)
			Skins.customizeFrame = customize
			Skins.lockBadges = nil
		end
		if not customize or not (customize :: GuiObject).Visible then
			return
		end
		local badges = Skins.lockBadges
		local now = os.clock()
		if not badges or now - (Skins.lockBadgesAt or 0) > 3 then
			badges = {}
			for _, d in ipairs(customize:GetDescendants()) do
				if (d.Name == "Locked" or d.Name == "Lock") and d:IsA("GuiObject") then
					table.insert(badges, d)
				end
			end
			Skins.lockBadges = badges
			Skins.lockBadgesAt = now
		end
		for _, d in ipairs(badges) do
			if d.Parent ~= nil and d.Visible then
				d.Visible = false
			end
		end
	end

	-- skin browser data -------------------------------------------------------
	function Skins.weapons(): { string }
		local weapons: { string } = {}
		pcall(function()
			local list = ItemLibrary and ItemLibrary.ItemsAlphabetized
			if type(list) == "table" and #list > 0 then
				for _, entry in ipairs(list) do
					local nm = if type(entry) == "table" then (entry.Name or entry[1]) else entry
					if type(nm) == "string" and not nm:find("MISSING_", 1, true) then
						table.insert(weapons, nm)
					end
				end
			elseif ItemLibrary and type(ItemLibrary.Items) == "table" then
				for nm in pairs(ItemLibrary.Items) do
					if not nm:find("MISSING_", 1, true) then
						table.insert(weapons, nm)
					end
				end
				table.sort(weapons)
			end
		end)
		return weapons
	end
	Skins.RARITY_ORDER = { Common = 1, Uncommon = 2, Rare = 3, Epic = 4, Legendary = 5, Mythic = 6, Unobtainable = 7 }
	Skins.RARITY_COLOR = {
		Common = Color3.fromRGB(170, 172, 186), Uncommon = Color3.fromRGB(90, 200, 120), Rare = Color3.fromRGB(80, 160, 255),
		Epic = Color3.fromRGB(170, 100, 255), Legendary = Color3.fromRGB(255, 190, 60), Mythic = Color3.fromRGB(255, 90, 110),
		Unobtainable = Color3.fromRGB(255, 120, 200),
	}
	function Skins.rarity(cosName: any): string
		local info = type(cosName) == "string" and CosmeticLibrary.Cosmetics[cosName]
		local r = type(info) == "table" and info.Rarity
		return if type(r) == "string" then r else ""
	end
	function Skins.rarityColor(cosName: any): Color3
		return Skins.RARITY_COLOR[Skins.rarity(cosName)] or Color3.fromRGB(170, 172, 186)
	end
	-- cosmetics of one type for a weapon, best rarity first then A→Z; skins include wrap-type skins
	function Skins.cosmeticsFor(weapon: string, cosType: string): { string }
		local out = {}
		for nm, info in pairs(CosmeticLibrary.Cosmetics) do
			if type(info) == "table" and info.Type == cosType and not info.Hidden and not Skins.banned(nm) and (cosType ~= "Skin" or info.ItemName == weapon) then
				table.insert(out, nm)
			end
		end
		table.sort(out, function(a, b)
			local ra = Skins.RARITY_ORDER[Skins.rarity(a)] or 0
			local rb = Skins.RARITY_ORDER[Skins.rarity(b)] or 0
			if ra ~= rb then
				return ra > rb
			end
			return a < b
		end)
		return out
	end
	-- true when the skin's model can actually be built on this client
	function Skins.available(cosName: string): boolean
		local info = CosmeticLibrary.Cosmetics[cosName]
		if type(info) ~= "table" then
			return false
		end
		if info.Type == "Wrap" or info.WrapGroups ~= nil then
			return true
		end
		local vms = ItemLibrary and ItemLibrary.ViewModels
		return type(vms) == "table" and vms[cosName] ~= nil and S.h.viewModelExists(cosName)
	end
	-- the weapon the browser should show: the saved pick, else the weapon in hand
	function Skins.browserWeapon(): string
		if cfg.skinWeapon ~= "" then
			return cfg.skinWeapon
		end
		local item = Game.weaponProfile().item
		if item and type(item.Name) == "string" then
			return item.Name
		end
		-- the alphabetised library walk is cached (this is asked per menu tick while the Skins tab is open)
		if not Skins.firstWeapon then
			Skins.firstWeapon = Skins.weapons()[1] or "Sniper"
		end
		return Skins.firstWeapon
	end
	Skins.load()

	-- a real (owned / None / Random) equip from the game UI replaced a local one: persist the removal,
	-- repaint / rebuild the held weapon and let the customize list re-read the equipped state
	function Skins.localEquipReplaced(weaponName: string, cosType: string)
		if S.localEquips[weaponName] and next(S.localEquips[weaponName]) == nil then
			S.localEquips[weaponName] = nil
		end
		Skins.persist(weaponName)
		log("INFO", ("skins: %s %s → game's own (local equip cleared)"):format(weaponName, cosType))
		task.delay(0.2, function()
			pcall(Skins.applyNow, weaponName)
			pcall(Skins.refreshEquipmentUi)
		end)
	end

	-- hand the live logic to the permanent hooks
	h.fakeInventory = Skins.fakeInventory
	h.isCosKey = Skins.isCosKey
	h.unlockable = Skins.unlockable
	h.reallyOwned = Skins.reallyOwned
	h.applyLocalEquip = Skins.applyLocalEquip
	h.localEquipReplaced = Skins.localEquipReplaced
	h.weaponData = Skins.weaponData
	S.applyLocalEquip = Skins.applyLocalEquip
	S.refreshEquipmentUi = Skins.refreshEquipmentUi

	-----------------------------------------------------------------------------
	-- §11 ui kit — tokens, themes, primitives, groupbox + controls, bind popup, tooltip
	-----------------------------------------------------------------------------
	local UI: any = {}
	S.uikit = UI
	-- v5.3 design tokens: one dark neutral family (a hint of violet so the accent sits in it), four
	-- text levels and one accent pair. The deep end of the pair only ever appears inside a gradient on
	-- something that moves (switch, slider fill, active page, logo) — never as decoration.
	local C: any = {
		bg = Color3.fromRGB(15, 14, 19), -- window / content
		side = Color3.fromRGB(11, 10, 15), -- sidebar, HUD panels
		surface = Color3.fromRGB(22, 21, 27), -- inputs, buttons, dropdowns
		card = Color3.fromRGB(28, 27, 34), -- hover / pressed surface
		pop = Color3.fromRGB(20, 19, 26), -- popovers: dropdowns, the bind popup, tooltips
		hairline = Color3.fromRGB(30, 29, 36), -- separators
		edge = Color3.fromRGB(38, 37, 45), -- control borders
		text = Color3.fromRGB(236, 234, 242),
		dim = Color3.fromRGB(161, 157, 173),
		muted = Color3.fromRGB(106, 102, 116),
		faint = Color3.fromRGB(74, 71, 82),
		off = Color3.fromRGB(38, 36, 46), -- switch / slider track
		knobOff = Color3.fromRGB(119, 114, 127),
		accent = Color3.fromRGB(173, 102, 255),
		accent2 = Color3.fromRGB(103, 52, 244),
		danger = Color3.fromRGB(255, 92, 122),
		ok = Color3.fromRGB(69, 223, 160),
		warn = Color3.fromRGB(255, 181, 71),
		rage = Color3.fromRGB(255, 92, 122),
		light = false,
	}
	UI.C = C
	S.themeColors = C
	-- type: Barlow (a DIN-style grotesk, OFL) for text and Material Icons Outlined (Apache 2.0) for
	-- glyphs, downloaded once into the workspace and registered through getcustomasset. The icon font
	-- works through ligatures — the icon's name is the text — because Roblox reserves private-use
	-- codepoints (a PUA icon font renders as boxes). Until the files exist (first run, no HTTP, no
	-- getcustomasset) the kit uses Roblox's BuilderSans and the frame-drawn fallback icons.
	-- bold by default: thin strokes at 12–14 px broke up into pixels
	UI.F = {
		body = Font.fromEnum(Enum.Font.BuilderSansExtraBold),
		medium = Font.fromEnum(Enum.Font.BuilderSansExtraBold),
		semibold = Font.fromEnum(Enum.Font.BuilderSansExtraBold),
		bold = Font.fromEnum(Enum.Font.BuilderSansExtraBold),
		black = Font.fromEnum(Enum.Font.BuilderSansExtraBold),
		code = Font.fromEnum(Enum.Font.RobotoMono),
		icon = nil, -- Material Icons ligature font once registered
	}
	-- the "centerra" wordmark (menu, watermark, intro): Gotham Bold, a clean geometric face built into Roblox
	-- (Enum.Font.Montserrat* resolves to it too)
	UI.BRAND_FONT = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.Bold)
	-- text sizes never draw below UI.TEXT_MIN at any menu size (Menu.layout clamps them)
	UI.TEXT_MIN = 12
	UI.TEXT_KEYS = { title = true, desc = true, group = true, value = true, small = true, tiny = true }
	UI.M = {
		title = 14, -- row labels
		desc = 13, -- tooltips, notes
		group = 14, -- group titles
		value = 13, -- values, dropdowns, list rows
		small = 12, -- chips, sub-tab labels
		tiny = 12, -- section captions
		row = 26,
		rowToggle = 26,
		rowDanger = 26,
		rowSlider = 26,
		rowCycle = 26,
		rowColor = 26,
		rowKeybind = 26,
		rowButton = 32,
		rowNote = 20,
		descLine = 0,
		listRow = 26,
		pillW = 28,
		pillH = 16,
		knob = 12,
		btnH = 26,
		ctrlW = 118, -- dropdown / multiselect box
		trackW = 100, -- slider track
		valueW = 40, -- slider value text
		colW = 300, -- inner width of one column (set by Menu.build from the window size)
	}
	-- wrapped-text height for a given width (notes) — measured with BuilderSans ExtraBold, the widest
	-- face the kit draws (Barlow Bold is narrower)
	function UI.textH(text: string, size: number, _font: any, width: number): number
		local ts = game:GetService("TextService")
		local ok, sz = pcall(ts.GetTextSize, ts, tostring(text or ""), size, Enum.Font.BuilderSansExtraBold, Vector2.new(math.max(width, 40), 4000))
		if ok and sz then
			return math.ceil(sz.Y)
		end
		return size + 4
	end

	-- fonts / icon font ----------------------------------------------------------------------------
	UI.ASSET_DIR = "centerra/fonts"
	UI.BARLOW = "https://raw.githubusercontent.com/google/fonts/main/ofl/barlow/"
	UI.FONT_FACES = {
		{ file = "Barlow-Regular.ttf", weight = 400, name = "Regular" },
		{ file = "Barlow-Medium.ttf", weight = 500, name = "Medium" },
		{ file = "Barlow-SemiBold.ttf", weight = 600, name = "SemiBold" },
		{ file = "Barlow-Bold.ttf", weight = 700, name = "Bold" },
		{ file = "Barlow-ExtraBold.ttf", weight = 800, name = "ExtraBold", optional = true },
	}
	UI.ICON_FONT = { file = "MaterialIconsOutlined.otf", url = "https://raw.githubusercontent.com/google/material-design-icons/master/font/MaterialIconsOutlined-Regular.otf" }
	UI.assetState = "builtin" -- builtin | loading | loaded | failed
	function UI.assetPath(file: string): string
		return UI.ASSET_DIR .. "/" .. file
	end
	function UI.haveAsset(file: string): boolean
		local ok, yes = pcall(function()
			return EXEC.isfile(UI.assetPath(file)) and #EXEC.readfile(UI.assetPath(file)) > 10000
		end)
		return ok and yes == true
	end
	function UI.fetchAsset(file: string, url: string): boolean
		if UI.haveAsset(file) then
			return true
		end
		if type(EXEC.request) ~= "function" then
			return false
		end
		local ok, res = pcall(EXEC.request, { Url = url, Method = "GET" })
		if not (ok and type(res) == "table" and res.StatusCode == 200 and type(res.Body) == "string" and #res.Body > 10000) then
			log("WARN", "font download failed:", file, ok and type(res) == "table" and res.StatusCode or tostring(res))
			return false
		end
		pcall(function()
			for _, dir in ipairs({ "centerra", UI.ASSET_DIR }) do
				if not (EXEC.isfolder and EXEC.isfolder(dir)) and EXEC.makefolder then
					EXEC.makefolder(dir)
				end
			end
		end)
		local okW = pcall(EXEC.writefile, UI.assetPath(file), res.Body)
		return okW
	end
	-- registers the cached files as Roblox font families; true when Barlow is in UI.F
	function UI.applyFonts(): boolean
		if type(EXEC.getcustomasset) ~= "function" then
			return false
		end
		local ok, err = pcall(function()
			local faces = {}
			local extra = false
			for _, f in ipairs(UI.FONT_FACES) do
				if UI.haveAsset(f.file) then
					table.insert(faces, { name = f.name, weight = f.weight, style = "normal", assetId = EXEC.getcustomasset(UI.assetPath(f.file)) })
					extra = extra or f.weight == 800
				elseif not f.optional then
					error("missing " .. f.file)
				end
			end
			EXEC.writefile(UI.assetPath("CenterraBarlow.json"), HttpService:JSONEncode({ name = "CenterraBarlow", faces = faces }))
			local fam = EXEC.getcustomasset(UI.assetPath("CenterraBarlow.json"))
			local heavy = if extra then Enum.FontWeight.ExtraBold else Enum.FontWeight.Bold
			UI.F.body = Font.new(fam, Enum.FontWeight.Bold)
			UI.F.medium = Font.new(fam, Enum.FontWeight.Bold)
			UI.F.semibold = Font.new(fam, heavy)
			UI.F.bold = Font.new(fam, heavy)
			UI.F.black = Font.new(fam, heavy)
			UI.fontFamily = fam
			if UI.haveAsset(UI.ICON_FONT.file) then
				EXEC.writefile(UI.assetPath("CenterraIcons.json"), HttpService:JSONEncode({ name = "CenterraIcons", faces = { { name = "Regular", weight = 400, style = "normal", assetId = EXEC.getcustomasset(UI.assetPath(UI.ICON_FONT.file)) } } }))
				UI.F.icon = Font.new(EXEC.getcustomasset(UI.assetPath("CenterraIcons.json")))
			end
		end)
		if not ok then
			log("DEBUG", "fonts: built-in (" .. tostring(err):sub(1, 60) .. ")")
			return false
		end
		UI.assetState = "loaded"
		return true
	end
	-- cached files load now (the menu is built with them); missing ones download in the background
	-- and the menu + HUD rebuild once they are in
	function UI.loadAssets()
		if UI.applyFonts() then
			-- an optional face added later (Barlow ExtraBold) still downloads once in the background
			local missing = {}
			for _, f in ipairs(UI.FONT_FACES) do
				if f.optional and not UI.haveAsset(f.file) then
					table.insert(missing, f)
				end
			end
			if #missing > 0 and type(EXEC.request) == "function" then
				task.spawn(function()
					local got = false
					for _, f in ipairs(missing) do
						got = UI.fetchAsset(f.file, UI.BARLOW .. f.file) or got
					end
					if got and S.alive ~= false and UI.applyFonts() then
						task.defer(function()
							if S.alive ~= false and S.rebuildMenu then
								pcall(S.rebuildMenu)
							end
						end)
					end
				end)
			end
			return
		end
		if type(EXEC.request) ~= "function" or type(EXEC.getcustomasset) ~= "function" or not EXEC.caps.files then
			UI.assetState = "failed"
			return
		end
		UI.assetState = "loading"
		task.spawn(function()
			local all = true
			for _, f in ipairs(UI.FONT_FACES) do
				all = (UI.fetchAsset(f.file, UI.BARLOW .. f.file) or f.optional == true) and all
			end
			UI.fetchAsset(UI.ICON_FONT.file, UI.ICON_FONT.url)
			if not (all and S.alive ~= false and UI.applyFonts()) then
				UI.assetState = "failed"
				return
			end
			log("INFO", "fonts: Barlow + Material Icons downloaded")
			task.defer(function()
				if S.alive == false then
					return
				end
				if S.rebuildMenu then
					pcall(S.rebuildMenu)
				end
				if S.hud and S.hud.retheme then
					pcall(S.hud.retheme)
				end
				-- the GUI renderer's pooled ESP texts were created with the fallback font
				if S.vis and S.vis.resetDrawings and S.vis.useGuiRenderer and S.vis.useGuiRenderer() then
					pcall(S.vis.resetDrawings)
				end
			end)
		end)
	end

	-- one accent colour per theme: bright + deep (for the gradients). v1: refined for a cleaner, more vivid
	-- and cohesive gradient across the set (matched luminance between the bright/deep stops per theme)
	local THEMES = {
		["Neon purple"] = { Color3.fromRGB(178, 120, 255), Color3.fromRGB(120, 66, 246) },
		Ice = { Color3.fromRGB(116, 206, 255), Color3.fromRGB(58, 128, 255) },
