			for _, k in ipairs({ "colEspVisible", "colTracer", "colChamsFill", "colShotTracer", "colVm", "colSelf" }) do
				local v = cfg[k]
				if type(v) == "table" and v[1] == purple[1] and v[2] == purple[2] and v[3] == purple[3] then
					cfg[k] = table.clone(blue)
				end
