	-- "rage" is two switches: name the one that is off
	function UI.needText(need: string): string
		if need == "rage" then
			if cfg.rageEnabled == false then
				return UI.NEED_TEXT.rageEnabled
			elseif cfg.ragePosition == nil or cfg.ragePosition == "None" then
				return "no rage mode"
			end
		end
		return UI.NEED_TEXT[need] or ("needs " .. tostring(need))
	end
	function UI.needMet(need: string): boolean
		if need == "rage" then
			return Configs.rageOn(cfg)
		elseif need == "noMeleeRage" then
			-- the melee ragebot owns "get behind and land the heavy" while it is on (Combat.backstabOwner)
			return not cfg.meleeRage
		end
		return cfg[need] == true
	end
	-- the first dependency that is off (nil = all met)
	function UI.needUnmet(need: any): string?
		if type(need) == "string" then
			return if UI.needMet(need) then nil else need
		elseif type(need) == "table" then
			for _, n in ipairs(need) do
				if not UI.needMet(n) then
					return n
				end
			end
		end
		return nil
	end
	function UI.isAdvanced(ropts: any, text: string?, groupOpts: any): boolean
		if ropts.advanced ~= nil then
			return ropts.advanced == true
		end
		if groupOpts and groupOpts.simple == true then
			return false
		end
		if ropts.isNote then
			return false -- notes follow their group (orphans are hidden by refilter)
		end
		if ropts.cfgKey ~= nil then
			return UI.SIMPLE_KEYS[ropts.cfgKey] ~= true
		end
		if ropts.isList then
			return false -- the Skins browsers
		end
		return UI.SIMPLE_LABELS[text or ""] ~= true
	end
	local function rowMatches(r: any): boolean
		local q = UI.searchText
		if q == "" then
			return true
		end
		return string.find(string.lower(r.text), q, 1, true) ~= nil or (r.descText ~= nil and string.find(string.lower(r.descText), q, 1, true) ~= nil)
	end
	-- re-evaluate every row/group for the current mode + search
	-- a sub-row shows while its toggle's three-line button is open (and allowed), or when a search finds it
	-- the rows under a three-line button fade in / out (UI.fadeIn / fadeOut) instead of popping; `done`
	-- runs once every row has finished (the close hides them only then)
	function UI.animSub(state: any, open: boolean, done: (() -> ())?)
		local rows = {}
		for _, r in ipairs(UI.rows) do
			if r.parent == state and r.frame.Visible then
				table.insert(rows, r)
			end
		end
		if #rows == 0 then
			if done then
				done()
			end
			return
		end
		state.animating = true
		if open then
			for _, r in ipairs(rows) do
				UI.fadeIn(r.frame)
			end
			task.delay(UI.TW.pop.Time, function()
				state.animating = false
				if done then
					done()
				end
			end)
			return
		end
		local frames = {}
		for _, r in ipairs(rows) do
			table.insert(frames, r.frame)
		end
		UI.fadeOut(frames, UI.TW.hover, function()
			state.animating = false
			if done then
				done()
			end
		end)
	end
	function UI.parentOpen(r: any): boolean
		local p = r.parent
		if p == nil then
			return true
		end
		if UI.searchText ~= "" then
			return true
		end
		return p.open == true and (p.when == nil or p.when() == true)
	end
	function UI.refilter()
		for _, r in ipairs(UI.rows) do
			local show = modeAllows(r.advanced) and rowMatches(r) and UI.parentOpen(r)
			r.frame.Visible = show
			if r.desc then
				-- help text shows in both modes: Simple hides the advanced rows, not the explanations
				local showDesc = r.descText ~= nil and r.descText ~= ""
				r.desc.Visible = showDesc
				r.frame.Size = UDim2.new(1, 0, 0, r.base + (if showDesc then (r.descH or UI.M.descLine) else 0))
			end
		end
		for _, g in ipairs(UI.groups) do
			local any, anyControl, hasControls = false, false, false
			for _, r in ipairs(g.rows) do
				if not r.isNote then
					hasControls = true
				end
				if r.frame.Visible then
					any = true
					if not r.isNote then
						anyControl = true
					end
				end
			end
			-- v5.2: in Simple mode a note whose controls are all advanced would sit alone in its group
			-- (a title over a sentence about rows you cannot see) — the note and the group go with them.
			-- Groups made only of notes (Home hints, Settings → Info) are untouched.
			if cfg.uiMode ~= "Advanced" and hasControls and any and not anyControl then
				for _, r in ipairs(g.rows) do
					if r.isNote and r.frame.Visible then
						r.frame.Visible = false
					end
				end
				any = false
			end
			g.frame.Visible = modeAllows(g.advanced) and (any or (#g.rows == 0 and UI.searchText == ""))
		end
		if UI.afterRefilter then
			pcall(UI.afterRefilter)
		end
	end
	function UI.search(text: string)
		UI.searchText = string.lower(tostring(text or ""))
		UI.refilter()
	end
	function UI.setMode(mode: string)
		cfg.uiMode = if mode == "Simple" then "Simple" else "Advanced"
		saveConfig()
		UI.refilter()
	end

	-- a typed slider value: "0.3", "x0.3", "×0.30", "15k", "20%", "1.5 s", "400st", "never" / "off" → 0
	function UI.parseNumber(s: string): number?
		if type(s) ~= "string" then
			return nil
		end
		s = string.gsub(string.lower((string.gsub(s, "×", ""))), "%s+", "")
		-- "15,000" is a thousands separator, "1,5" a decimal comma
		s = if string.match(s, "^%-?%d+,%d%d%d") then string.gsub(s, ",", "") else string.gsub(s, ",", ".")
		if s == "never" or s == "off" or s == "none" then
			return 0
		end
		local num, suffix = string.match(s, "^x?([%-]?%d*%.?%d+)(%a*)")
		local n = tonumber(num)
		if n == nil or n ~= n then
			return nil
		end
		if suffix == "k" then
			n *= 1000
		end
		return n
	end
	-- tooltip (one per gui)
	function UI.tip(target: GuiObject, text: string)
		target.MouseEnter:Connect(function()
			if not UI.gui or not text or text == "" then
				return
			end
			if not tipFrame or tipFrame.Parent == nil then
				-- wraps at 320 px and never runs off the screen (flips to the left / above the cursor)
				local t = Instance.new("TextLabel")
				t.Name = "Tooltip"
				t.AutomaticSize = Enum.AutomaticSize.XY
				t.Size = UDim2.new(0, 0, 0, 0)
				t.BackgroundColor3 = C.pop
				UI.setFont(t, UI.F.body)
				t.TextSize = UI.M.desc
				t.TextColor3 = C.text
				t.TextWrapped = true
				t.TextXAlignment = Enum.TextXAlignment.Left
				t.LineHeight = 1.1
				t.ZIndex = 200
				t.Visible = false
				t.Parent = UI.gui
				corner(t, if UI.metal then 8 else 6)
				UI.metalEdge(stroke(t, C.edge, 0))
				padding(t, 7, 10, 8, 10)
				local cap = Instance.new("UISizeConstraint")
				cap.MaxSize = Vector2.new(260, 400)
				cap.Parent = t
				tipFrame = t
			end
			local tf = tipFrame :: TextLabel
			tf.Text = text
			UI.snapWrapped(tf, 240, 20, 15)
			-- placed first, shown one frame later: it used to appear at the previous tooltip's
			-- position for a frame and then jump
			local m0 = UIS:GetMouseLocation()
			local inset0 = if UI.gui.IgnoreGuiInset then 0 else GuiService:GetGuiInset().Y
			tf.Position = UDim2.fromOffset(m0.X + 14, m0.Y - inset0 + 8)
			tf.Visible = false
			task.defer(function()
				if tipFrame ~= tf then
					return
				end
				local m = UIS:GetMouseLocation()
				-- the gui ignores the inset (IgnoreGuiInset) → mouse coordinates map 1:1; a gui that
				-- does not gets the top-bar offset subtracted
				local inset = if UI.gui.IgnoreGuiInset then 0 else GuiService:GetGuiInset().Y
				local vp = UI.gui.AbsoluteSize
				local sz = tf.AbsoluteSize
				local x, y = m.X + 14, m.Y - inset + 8
				if x + sz.X > vp.X - 6 then
					x = math.max(6, m.X - 14 - sz.X)
				end
				if y + sz.Y > vp.Y - 6 then
					y = math.max(6, m.Y - inset - 8 - sz.Y)
				end
				tf.Position = UDim2.fromOffset(x, y)
				tf.Visible = true
			end)
		end)
		target.MouseLeave:Connect(function()
			if tipFrame then
				tipFrame.Visible = false
			end
		end)
	end

	---------------------------------------------------------------------------
	-- bind popup: right-click any toggle → key + mode (Toggle / Hold / Always / Never)
	---------------------------------------------------------------------------
	local BIND_MODES = { "Toggle", "Hold", "Always", "Never" }
	local bindPopup: Frame? = nil
	-- one line of text at `size`, measured with the widest face the kit draws (chips size to it)
	function UI.textW(text: string, size: number): number
		local ts = game:GetService("TextService")
		local ok, sz = pcall(ts.GetTextSize, ts, tostring(text or ""), size, Enum.Font.BuilderSansExtraBold, Vector2.new(2000, 200))
		return if ok and sz then math.ceil(sz.X) else #tostring(text or "") * (size * 0.6)
	end
	-- a text box sized to its text in whole, even pixels: automatic sizing takes the font's fractional
	-- advance widths (a 165.8 px toast), and a fractional box — right-aligned or centred on its parent
	-- — puts its edges and stroke on half pixels, blurred across two. `extra` = the label's own padding.
	-- false (automatic size kept) while the text cannot be measured yet.
	function UI.snapWidth(l: TextLabel, extra: number?): boolean
		local w = l.TextBounds.X
		if w < 1 then
			return false
		end
		local total = math.ceil(w - 0.001) + (extra or 0)
		if total % 2 == 1 then
			total += 1
		end
		if l.AutomaticSize == Enum.AutomaticSize.X then
			l.AutomaticSize = Enum.AutomaticSize.None
		elseif l.AutomaticSize == Enum.AutomaticSize.XY then
			l.AutomaticSize = Enum.AutomaticSize.Y
		end
		if l.Size.X.Scale ~= 0 or l.Size.X.Offset ~= total then
			l.Size = UDim2.new(0, total, l.Size.Y.Scale, l.Size.Y.Offset)
		end
		return true
	end
	-- wrapped text in whole pixels: measured at `maxW`, then sized to the longest line and the lines'
	-- height (even width); `padX` / `padY` = the label's own padding
	function UI.snapWrapped(l: TextLabel, maxW: number, padX: number?, padY: number?): boolean
		local auto = l.AutomaticSize
		l.AutomaticSize = Enum.AutomaticSize.None
		l.TextWrapped = true
		l.Size = UDim2.fromOffset(maxW + (padX or 0), 2000)
		local tb = l.TextBounds
		if tb.X < 1 then
			l.AutomaticSize = auto
			return false
		end
		local w = math.ceil(tb.X - 0.001) + (padX or 0)
		if w % 2 == 1 then
			w += 1
		end
		l.Size = UDim2.fromOffset(w, math.ceil(tb.Y - 0.001) + (padY or 0))
		return true
	end
	function UI.closeBindPopup()
		local p = bindPopup
		bindPopup = nil
		if not p then
			return
		end
		if p.Parent and S.menuOpen then
			-- fades out, inert meanwhile (a click on a fading button must not act)
			for _, d in ipairs(p:GetDescendants()) do
				if d:IsA("GuiButton") then
					d.Active = false
					pcall(function()
						(d :: any).Interactable = false
					end)
				end
			end
			UI.fadeOut(p, UI.TW.hover, function()
				p:Destroy()
			end)
		else
			p:Destroy()
		end
	end
	function UI.openBindPopup(cfgKey: string, title: string?, at: Vector2?)
		local root = UI.root
		if not root then
			return
		end
		UI.closeBindPopup()
		-- the bind entry is created only once the user actually sets a key or mode: opening and
		-- closing the popup used to leave an empty { key = "", mode = "Toggle" } in the saved config
		local b = cfg.binds[cfgKey]
		if type(b) ~= "table" then
			b = { key = "", mode = "Toggle" }
		end
		local function commit()
			if cfg.binds[cfgKey] ~= b then
				cfg.binds[cfgKey] = b
			end
			saveConfig()
		end
		-- the popover look every popup shares (C.pop, 10 px corners, a soft shadow with the same corners),
		-- an accent edge because it edits one row; faded in, never unrolled
		local W, H = 300, 206
		local pop = frame(root, C.pop)
		pop.Name = "BindPopup"
		pop.Size = UDim2.fromOffset(W, H)
		local rel = if at then at - root.AbsolutePosition else Vector2.new(root.AbsoluteSize.X / 2 - W / 2, root.AbsoluteSize.Y / 2 - H / 2)
		pop.Position = UDim2.fromOffset(math.floor(math.clamp(rel.X, 8, math.max(8, root.AbsoluteSize.X - W - 8))), math.floor(math.clamp(rel.Y, 8, math.max(8, root.AbsoluteSize.Y - H - 8))))
		pop.ZIndex = 50
		pop.Active = true
		corner(pop, 10)
		UI.softShadow(pop, "Shadow", Color3.new(0, 0, 0), 0.4, 18, 10)
		UI.popEdge(pop, 10)
		bindPopup = pop
		local function zl(t: any, z: number?): any
			t.ZIndex = z or 51
			return t
		end
		local cap = zl(label(pop, "keybind", UI.M.tiny, C.accent, UI.F.semibold))
		cap.Size = UDim2.new(1, -60, 0, 14)
		cap.Position = UDim2.fromOffset(16, 12)
		local head = zl(label(pop, string.lower(title or Input.bindLabels[cfgKey] or cfgKey), UI.M.title, C.text, UI.F.semibold))
		head.Size = UDim2.new(1, -60, 0, 18)
		head.Position = UDim2.fromOffset(16, 27)
		head.TextTruncate = Enum.TextTruncate.AtEnd
		local closeB = zl(button(pop, "", 10, C.text, C.card))
		closeB.Size = UDim2.fromOffset(28, 28)
		closeB.AnchorPoint = Vector2.new(1, 0)
		closeB.Position = UDim2.new(1, -10, 0, 10)
		closeB.BackgroundTransparency = 1
		corner(closeB, 7)
		local closeIc = zl(icon(closeB, "close", 16), 52)
		recolourIcon(closeIc, C.muted)
		closeB.MouseEnter:Connect(function()
			tween(closeB, TW_HOVER, { BackgroundTransparency = 0 })
			UI.tintIcon(closeIc, C.text, true)
		end)
		closeB.MouseLeave:Connect(function()
			tween(closeB, TW_HOVER, { BackgroundTransparency = 1 })
			UI.tintIcon(closeIc, C.muted, true)
		end)
		local hair = zl(frame(pop, C.hairline))
		hair.Size = UDim2.new(1, -32, 0, 1)
		hair.Position = UDim2.fromOffset(16, 56)
		for _, spec in ipairs({ { "key", 68 }, { "mode", 108 } }) do
			local l = zl(label(pop, spec[1], UI.M.title, C.dim))
			l.Size = UDim2.fromOffset(64, 30)
			l.Position = UDim2.fromOffset(16, spec[2])
		end
		-- the key: a field with a keyboard glyph; it lights up while it listens
		local keyB = zl(button(pop, "", UI.M.value, C.text, C.surface))
		keyB.Size = UDim2.fromOffset(W - 104, 30)
		keyB.Position = UDim2.fromOffset(88, 68)
		corner(keyB, 7)
		local keyStroke = stroke(keyB, C.edge, 0)
		local keyIc = zl(icon(keyB, "keyboard", 15), 52)
		keyIc.AnchorPoint = Vector2.new(0, 0.5)
		keyIc.Position = UDim2.new(0, 10, 0.5, 0)
		recolourIcon(keyIc, C.muted)
		local keyTxt = zl(label(keyB, "", UI.M.value, C.text, UI.F.medium), 52)
		keyTxt.Size = UDim2.new(1, -42, 1, 0)
		keyTxt.Position = UDim2.fromOffset(32, 0)
		keyTxt.TextTruncate = Enum.TextTruncate.AtEnd
		keyB.MouseEnter:Connect(function()
			tween(keyB, TW_HOVER, { BackgroundColor3 = C.card })
		end)
		keyB.MouseLeave:Connect(function()
			tween(keyB, TW_HOVER, { BackgroundColor3 = C.surface })
		end)
		-- the mode: a segmented control whose thumb glides to the pick
		local seg = zl(frame(pop, C.surface))
		seg.Size = UDim2.fromOffset(W - 104, 30)
		seg.Position = UDim2.fromOffset(88, 108)
		corner(seg, 7)
		stroke(seg, C.edge, 0)
		local thumb = zl(frame(seg, C.accent), 52)
		thumb.BackgroundTransparency = 0.78
		corner(thumb, 5)
		stroke(thumb, C.accent, 0.5)
		if UI.brushed(thumb) then
			thumb.BackgroundTransparency = 0
		end
		local thumbLiquid = UI.liquid(thumb, function(a: number, b2: number)
			thumb.Position = UDim2.fromOffset(a, 3)
			thumb.Size = UDim2.fromOffset(math.max(4, b2 - a), 24)
		end)
		local segW = (W - 104 - 6) / #BIND_MODES
		local segBtns: { [string]: TextButton } = {}
		local refresh: (boolean?) -> ()
		for i, m in ipairs(BIND_MODES) do
			local sb = zl(button(seg, string.lower(m), UI.M.small, C.muted, C.surface), 53)
			sb.BackgroundTransparency = 1
			sb.Position = UDim2.fromOffset(3 + math.floor((i - 1) * segW + 0.5), 3)
			sb.Size = UDim2.fromOffset(math.floor(i * segW + 0.5) - math.floor((i - 1) * segW + 0.5), 24)
			segBtns[m] = sb
			sb.MouseButton1Click:Connect(function()
				if (b.mode or "Toggle") ~= m then
					b.mode = m
					Input.bindTouched[cfgKey] = nil
					commit()
					refresh(true)
				end
			end)
		end
		-- what the key is, in words, behind a status dot
		local dot = zl(frame(pop, C.muted))
		dot.Size = UDim2.fromOffset(6, 6)
		dot.AnchorPoint = Vector2.new(0, 0.5)
		dot.Position = UDim2.fromOffset(16, 157)
		corner(dot, 3)
		local status = zl(label(pop, "", UI.M.small, C.dim, UI.F.medium))
		status.Name = "Status"
		status.Size = UDim2.fromOffset(W - 44, 18)
		status.Position = UDim2.fromOffset(28, 148)
		status.TextTruncate = Enum.TextTruncate.AtEnd
		local clearB = zl(button(pop, "clear", UI.M.value, C.danger, C.danger))
		clearB.Size = UDim2.fromOffset(76, 26)
		clearB.Position = UDim2.fromOffset(16, H - 38)
		clearB.BackgroundTransparency = 0.87
		corner(clearB, 7)
		stroke(clearB, C.danger, 0.6)
		clearB.MouseEnter:Connect(function()
			tween(clearB, TW_HOVER, { BackgroundTransparency = 0.78 })
		end)
		clearB.MouseLeave:Connect(function()
			tween(clearB, TW_HOVER, { BackgroundTransparency = 0.87 })
		end)
		local hint = zl(label(pop, "esc clears · mouse 4 / 5 work", UI.M.small, C.muted))
		hint.Size = UDim2.fromOffset(W - 116, 26)
		hint.Position = UDim2.fromOffset(100, H - 38)
		hint.TextXAlignment = Enum.TextXAlignment.Right
		local function paintStatus()
			local k = b.key
			if type(k) ~= "string" or k == "" then
				status.Text = if b.mode == "Always" or b.mode == "Never" then ("no key · always %s"):format(if b.mode == "Always" then "on" else "off") else "no key yet"
				status.TextColor3 = C.muted
				dot.BackgroundColor3 = if b.mode == "Always" then C.ok else C.faint
				return
			end
			status.Text = ("bound to %s · %s"):format(Input.keyLabel(k), string.lower(b.mode or "Toggle"))
			status.TextColor3 = C.dim
			dot.BackgroundColor3 = if b.mode == "Never" then C.faint else C.ok
		end
		refresh = function(animate: boolean?)
			keyTxt.Text = Input.keyLabel(b.key)
			local mode = b.mode or "Toggle"
			for m, sb in pairs(segBtns) do
				local col = if m == mode then (if UI.metal then UI.metal.ink else C.text) else C.muted
				if animate then
					tween(sb, TW_HOVER, { TextColor3 = col })
				else
					sb.TextColor3 = col
				end
				UI.setFont(sb, if m == mode then UI.F.bold else UI.F.medium)
			end
			local sb = segBtns[mode]
			if sb then
				thumbLiquid.to(sb.Position.X.Offset, sb.Position.X.Offset + sb.Size.X.Offset, animate)
			end
			paintStatus()
			local tag = UI.bindTags[cfgKey]
			if tag then
				tag()
			end
		end
		refresh(false)
		keyB.MouseButton1Click:Connect(function()
			keyTxt.Text = "Press a key…"
			keyStroke.Color = C.accent
			recolourIcon(keyIc, C.accent)
			Input.captureKey(function(name)
				if name ~= false then
					b.key = name or ""
					commit()
				end
				if pop.Parent then
					keyStroke.Color = C.edge
					recolourIcon(keyIc, C.muted)
					refresh(false)
				end
			end)
		end)
		do
			local base = pop.Position
			pop.Position = base + UDim2.fromOffset(0, 4)
			tween(pop, UI.TW.pop, { Position = base })
			UI.fadeIn(pop)
		end
		clearB.MouseButton1Click:Connect(function()
			cfg.binds[cfgKey] = nil
			Input.bindTouched[cfgKey] = nil
			saveConfig()
			local tag = UI.bindTags[cfgKey]
			if tag then
				tag()
			end
			UI.closeBindPopup()
		end)
		closeB.MouseButton1Click:Connect(UI.closeBindPopup)
	end
	function UI.bindPopupOpen(): boolean
		return bindPopup ~= nil and bindPopup.Parent ~= nil
	end

	---------------------------------------------------------------------------
	-- dropdown popover (cycle / multiselect / colour): one at a time, parented to the menu host so it
	-- scales with the window; an invisible catcher over window + side panel closes it on an outside click
	---------------------------------------------------------------------------
	UI.popup = nil
	UI.popupHost = nil -- set by Menu.build (the frame holding the window and the side panel)
	function UI.closeDropdown()
		local p = UI.popup
		UI.popup = nil
		if p then
			pcall(p.catcher.Destroy, p.catcher)
			pcall(p.frame.Destroy, p.frame)
			if p.onClose then
				pcall(p.onClose)
			end
		end
	end
	-- build(frame) fills the list and returns its height; the list opens under the anchor (above it
	-- when there is no room) and never wider than needed
	function UI.openDropdown(anchor: GuiObject, width: number, build: (Frame) -> number, onClose: (() -> ())?): Frame?
		UI.closeDropdown()
		local host = UI.popupHost or UI.root
		if not host then
			return nil
		end
		local sc = if S.menu and S.menu.scale then S.menu.scale.Scale else 1
		sc = math.max(sc, 0.1)
		local catcher = Instance.new("TextButton")
		catcher.Name = "DropdownCatcher"
		catcher.BackgroundTransparency = 1
		catcher.Text = ""
		catcher.AutoButtonColor = false
		catcher.Size = UDim2.new(1, 400, 1, 0)
		catcher.ZIndex = 58
		catcher.Parent = host
		local f = frame(host, C.pop)
		f.Name = "Dropdown"
		f.ZIndex = 60
		f.Active = true
		corner(f, 8)
		UI.softShadow(f, "Shadow", Color3.new(0, 0, 0), 0.45, 14, 8)
		if not UI.metal then
			stroke(f, C.edge, 0)
		else
			UI.popEdge(f, 8)
		end
		local h = build(f)
		local ap = (anchor.AbsolutePosition - host.AbsolutePosition) / sc
		local as = anchor.AbsoluteSize / sc
		local hostH = host.AbsoluteSize.Y / sc
		local w = math.max(width, as.X)
		local y = ap.Y + as.Y + 4
		local above = false
		if y + h > hostH - 6 and ap.Y - h - 4 > 6 then
			y = ap.Y - h - 4
			above = true
		end
		-- full size at once, fading in while it drifts 4 px out of its anchor (no unroll: see UI.fadeIn)
		local base = UDim2.fromOffset(math.floor(ap.X + as.X - w + 0.5), math.floor(y + 0.5))
		f.Size = UDim2.fromOffset(w, h)
		f.Position = base + UDim2.fromOffset(0, if above then 4 else -4)
		tween(f, UI.TW.pop, { Position = base })
		UI.fadeIn(f)
		catcher.MouseButton1Click:Connect(UI.closeDropdown)
		UI.popup = { frame = f, catcher = catcher, onClose = onClose }
		return f
	end
	-- one 24 px option inside a dropdown
	function UI.dropdownOption(parent: Frame, y: number, text: string, selected: boolean, onPick: () -> ()): TextButton
		local b = button(parent, "", UI.M.value, C.dim, C.card)
		b.BackgroundTransparency = 1
		b.Size = UDim2.new(1, -8, 0, 24)
		b.Position = UDim2.fromOffset(4, y)
		b.ZIndex = 61
		corner(b, 5)
		local l = label(b, text, UI.M.value, if selected then C.accent else C.dim, UI.F.body)
		l.Size = UDim2.new(1, -30, 1, 0)
		l.Position = UDim2.fromOffset(8, 0)
		l.ZIndex = 62
		l.TextTruncate = Enum.TextTruncate.AtEnd
		local ic = icon(b, "check", 14)
		ic.AnchorPoint = Vector2.new(1, 0.5)
		ic.Position = UDim2.new(1, -6, 0.5, 0)
		ic.ZIndex = 62
		ic.Visible = selected
		recolourIcon(ic, C.accent)
		b:SetAttribute("selected", selected)
		-- metal looks: the picked option is a brushed key with dark ink (it keeps it through hovers)
		local keyed = selected and UI.brushed(b)
		if keyed then
			b.BackgroundTransparency = 0
			l.TextColor3 = UI.metal.ink
			UI.setFont(l, UI.F.bold)
			recolourIcon(ic, UI.metal.ink)
		end
		b.MouseEnter:Connect(function()
			if keyed then
				return
			end
			tween(b, TW_HOVER, { BackgroundTransparency = 0 })
			if not b:GetAttribute("selected") then
				tween(l, TW_HOVER, { TextColor3 = C.text })
			end
		end)
		b.MouseLeave:Connect(function()
			if keyed then
				return
			end
			tween(b, TW_HOVER, { BackgroundTransparency = 1 })
			tween(l, TW_HOVER, { TextColor3 = if b:GetAttribute("selected") then C.accent else C.dim })
		end)
		b.MouseButton1Click:Connect(onPick)
		return b
	end
	-- one plain sentence for the old risk tags (the tag itself used to be the UI)
	function UI.riskText(tag: any): string
		local t = string.upper(tostring(tag))
		if t == "SERVER-CHECKED" then
			return "The server checks this. Push it too far and shots stop counting or you get pulled back."
		elseif t == "EXPERIMENTAL" then
			return "Experimental: may not work on every map or after a game update."
		elseif t == "TELEPORT" then
			return "Moves your character. Other players can see it."
		elseif t == "UNTESTED VS SERVER" then
			return "Not yet verified against the server in a real match."
		elseif t == "TRUE" or t == "DANGER" then
			return "Risky: other players or the server can notice it."
		end
		return tostring(tag)
	end

	---------------------------------------------------------------------------
	-- group + controls. A group is a title over a hairline; rows are 26 px, label left, control
	-- right; help lives in a (?) tooltip, risk in one amber warning icon.
	---------------------------------------------------------------------------
	-- a group header's glyph from its title; only names already verified in UI.ICONS (Material ligatures)
	UI.GROUP_ICONS = {
		{ "max", "auto_awesome" }, { "extra", "auto_awesome" }, { "intel", "visibility" }, { "right now", "info" }, { "stat", "info" },
		{ "farm", "refresh" }, { "esp", "visibility" }, { "cham", "visibility" }, { "info", "info" }, { "color", "tune" },
		{ "style", "tune" }, { "look", "tune" }, { "silent", "track_changes" }, { "trigger", "my_location" }, { "aim", "gps_fixed" },
		{ "target", "gps_fixed" }, { "rage", "bolt" }, { "anti", "360" }, { "world", "public" }, { "map", "public" }, { "skin", "checkroom" },
		{ "hud", "dashboard" }, { "menu", "dashboard" }, { "interface", "dashboard" }, { "bind", "keyboard" }, { "key", "keyboard" },
		{ "config", "save" }, { "cloud", "save" }, { "player", "person_outline" }, { "spoof", "person_outline" }, { "staff", "warning_amber" },
	}
	function UI.groupIcon(title: string): string
		local t = string.lower(title)
		for _, p in ipairs(UI.GROUP_ICONS) do
			if string.find(t, p[1], 1, true) then
				return p[2]
			end
		end
		return "tune"
	end
	function UI.group(parent: GuiObject, title: string, opts: any?): any
		opts = opts or {}
		local gf = frame(parent)
		gf.Name = "Group_" .. title
		gf.AutomaticSize = Enum.AutomaticSize.Y
		gf.Size = UDim2.new(1, 0, 0, 0)
		gf.LayoutOrder = nextOrder()
		vlist(gf, 0)
		padding(gf, 0, 0, if opts.bare then 0 else 12, 0)
		local M = UI.M
		-- v1.1: a group is a boxed card (a header row over a hairline, the rows inside), as in the design
		local body: Frame = gf
		if not opts.bare then
			local card = frame(gf, C.surface:Lerp(C.bg, 0.45))
			card.Name = "Card"
			card.AutomaticSize = Enum.AutomaticSize.Y
			card.Size = UDim2.new(1, 0, 0, 0)
			corner(card, 10)
			stroke(card, C.hairline, 0)
			vlist(card, 0)
			padding(card, 0, 10, 6, 10)
			body = card
			local head = frame(card)
			head.Name = "Head"
			head.Size = UDim2.new(1, 0, 0, 32)
			head.LayoutOrder = nextOrder()
			local t = label(head, string.lower(title), M.small + 1, C.dim, UI.F.semibold)
			t.Name = "Title"
			t.Size = UDim2.new(1, 0, 1, 0)
			-- a small accent glyph before the title (the icon font only: a missing ligature would print its name)
			if UI.F.icon then
				local gi = icon(head, UI.groupIcon(title), 14)
				gi.AnchorPoint = Vector2.new(0, 0.5)
				gi.Position = UDim2.new(0, -1, 0.5, 0)
				recolourIcon(gi, C.accent)
				t.Position = UDim2.fromOffset(20, 0)
				t.Size = UDim2.new(1, -20, 1, 0)
			end
			if opts.max then
				-- a Max-only group: the max mark right after its title
				local mk = UI.sparkles(head, 13, UI.MAX_MARK, t.ZIndex + 1)
				mk.Name = "MaxMark"
				mk.AnchorPoint = Vector2.new(0, 0.5)
				local function placeMark()
					mk.Position = UDim2.new(0, t.Position.X.Offset + math.floor(t.TextBounds.X) + 5, 0.5, 0)
				end
				placeMark()
				t:GetPropertyChangedSignal("TextBounds"):Connect(placeMark)
				UI.tip(mk, "Max only")
			end
			local hl = frame(head, C.hairline)
			hl.Size = UDim2.new(1, 20, 0, 1)
			hl.Position = UDim2.new(0, -10, 1, -1)
			local gap = frame(card)
			gap.Size = UDim2.new(1, 0, 0, 4)
			gap.LayoutOrder = nextOrder()
		end

		local g: any = { frame = gf, rows = {}, advanced = opts.advanced == true, title = title }
		table.insert(UI.groups, g)

		local function row(h: number, text: string?, ropts: any?): Frame
			ropts = ropts or {}
			local r = frame(body)
			r.Size = UDim2.new(1, 0, 0, h)
			r.LayoutOrder = nextOrder()
			local entry: any = { frame = r, text = string.lower(text or ""), advanced = UI.isAdvanced(ropts, text, opts), base = h, descText = ropts.desc, isNote = ropts.isNote == true }
			-- a sub-option of the toggle above (its three-line button opens it): indented under a
			-- hairline, hidden until opened
			if g.subParent then
				entry.parent = g.subParent
				entry.advanced = false
				local pad = Instance.new("UIPadding")
				pad.PaddingLeft = UDim.new(0, 16)
				pad.Parent = r
				local rail = frame(r, C.hairline)
				rail.Name = "SubRail"
				rail.Size = UDim2.new(0, 1, 1, -6)
				rail.Position = UDim2.new(0, -10, 0, 3)
				r.Visible = false
			end
			table.insert(UI.rows, entry)
			table.insert(g.rows, entry)
			return r
		end
		g.row = row

		-- the row's label plus, right after its text, a (?) or amber warning icon whose tooltip holds
		-- the help; `reserve` = the width the control on the right needs
		local function rowLabel(r: Frame, text: string, ropts: any, reserve: number): TextLabel
			local l = label(r, string.lower(text), M.title, C.text, UI.F.body)
			l.Name = "Label"
			l.Size = UDim2.new(1, -(reserve + 24), 1, 0)
			l.TextTruncate = Enum.TextTruncate.AtEnd
			local warnText = if ropts.danger then UI.riskText(ropts.danger) else nil
			local helpText = if type(ropts.desc) == "string" and ropts.desc ~= "" then ropts.desc else nil
			-- Max-only rows (a Max group, or a row flagged max): the max mark right after the text, the hint after it
			local markW = 0
			if ropts.max or opts.max then
				markW = 16
				local mk = UI.sparkles(r, 12, UI.MAX_MARK, l.ZIndex + 1)
				mk.Name = "MaxMark"
				mk.AnchorPoint = Vector2.new(0, 0.5)
				local function placeMark()
					mk.Position = UDim2.new(0, math.floor(l.TextBounds.X) + 5, 0.5, 0)
				end
				placeMark()
				l:GetPropertyChangedSignal("TextBounds"):Connect(placeMark)
			end
			if warnText or helpText then
				local tip = if warnText and helpText then warnText .. "\n\n" .. helpText else (warnText or helpText) :: string
				local holder = frame(r)
				holder.Name = "Hint"
				holder.Size = UDim2.fromOffset(16, 16)
				holder.AnchorPoint = Vector2.new(0, 0.5)
				holder.Position = UDim2.new(0, 0, 0.5, 0)
				local ic = icon(holder, if warnText then "warn" else "help", 14)
				recolourIcon(ic, if warnText then C.warn else C.faint)
				local function place()
					holder.Position = UDim2.new(0, math.floor(l.TextBounds.X) + 6 + markW, 0.5, 0)
				end
				place()
				l:GetPropertyChangedSignal("TextBounds"):Connect(place)
				UI.tip(holder, tip)
				UI.tip(l, tip)
				holder.MouseEnter:Connect(function()
					if not warnText then
						recolourIcon(ic, C.dim)
					end
				end)
				holder.MouseLeave:Connect(function()
					if not warnText then
						recolourIcon(ic, C.faint)
					end
				end)
			end
			return l
		end
		g.rowLabel = rowLabel

		function g.toggle(_, text: string, key: string, topts: { [string]: any })
			topts = topts or {}
			topts.cfgKey = key
			UI.count("toggle")
			Input.bindLabels[key] = text
			local r = row(M.row, text, topts)
			local l = rowLabel(r, text, topts, M.pillW + 8)
			-- the switch: a transparent hit area holding glow → track → knob
			local pill = button(r, "", 10, C.text, C.off)
			pill.Name = "Switch"
			pill.BackgroundTransparency = 1
			pill.Size = UDim2.new(0, M.pillW, 0, M.pillH)
			pill.AnchorPoint = Vector2.new(1, 0.5)
			pill.Position = UDim2.new(1, 0, 0.5, 0)
			local glow = UI.glow(pill, 7, 0.9)
			glow.ZIndex = 1
			local track = frame(pill, C.off)
			track.Size = UDim2.fromScale(1, 1)
			track.ZIndex = 2
			corner(track, M.pillH // 2)
			-- the accent fill fades over the off track while the knob travels (it used to swap colour
			-- in one frame at the start of the knob's slide)
			local fill = frame(pill, Color3.new(1, 1, 1))
			fill.Size = UDim2.fromScale(1, 1)
			fill.ZIndex = 2
			fill.BackgroundTransparency = 1
			corner(fill, M.pillH // 2)
			UI.metalFill(gradient(fill, C.accent2, C.accent))
			local knob = frame(pill, C.knobOff)
			knob.Size = UDim2.new(0, M.knob, 0, M.knob)
			knob.AnchorPoint = Vector2.new(0, 0.5)
			knob.Position = UDim2.new(0, 2, 0.5, 0)
			knob.ZIndex = 3
			corner(knob, M.knob // 2)
			-- key chip left of the switch while a bind exists
			local tag = label(r, "", M.small, C.muted, UI.F.medium)
			tag.Name = "Bind"
			tag.Size = UDim2.new(0, 30, 0, 18)
			tag.AnchorPoint = Vector2.new(1, 0.5)
			tag.Position = UDim2.new(1, -(M.pillW + 8), 0.5, 0)
			tag.BackgroundColor3 = Color3.fromRGB(26, 25, 32)
			tag.BackgroundTransparency = 0
			tag.TextXAlignment = Enum.TextXAlignment.Center
			tag.Visible = false
			corner(tag, 4)
			stroke(tag, C.edge, 0)
			-- "needs silent aim" while the switch is on but the one it depends on is off
			local need = topts.needs or UI.NEEDS[key]
			local needTag: TextLabel? = nil
			if need then
				local first = if type(need) == "table" then need[1] else need
				local nt = label(r, UI.needText(first), M.small, C.warn, UI.F.medium)
				nt.Name = "Needs"
				nt.Size = UDim2.new(0, 96, 0, 18)
				nt.AnchorPoint = Vector2.new(1, 0.5)
				nt.TextXAlignment = Enum.TextXAlignment.Right
				nt.Visible = false
				needTag = nt
			end
			-- three-line button: this row has sub-options (topts.sub builds them as rows right under it,
			-- shown only while it is open; topts.subWhen can hide the button, e.g. while rage is off)
			local subState: any = nil
			local exp: TextButton? = nil
			local expIc: GuiObject? = nil
			if type(topts.sub) == "function" then
				subState = { open = false, when = topts.subWhen }
				local eb = button(r, "", M.small, C.text, C.card)
				eb.Name = "Expand"
				eb.BackgroundTransparency = 1
				eb.Size = UDim2.fromOffset(20, 20)
				eb.AnchorPoint = Vector2.new(1, 0.5)
				corner(eb, 5)
				expIc = icon(eb, "menu", 14)
				recolourIcon(expIc :: GuiObject, C.muted)
				exp = eb
				UI.tip(eb, "More options for " .. text)
			end
			local function expShown(): boolean
				return subState ~= nil and (subState.when == nil or subState.when() == true)
			end
			-- chips right to left: switch, key chip, sub-options, needs chip; the label gives up their width
			local function layout()
				local x = M.pillW + 8
				if tag.Visible then
					x += tag.Size.X.Offset + 6
				end
				if exp then
					local shown = expShown()
					exp.Visible = shown
					exp.Position = UDim2.new(1, -x, 0.5, 0)
					if shown then
						x += 20 + 6
					end
				end
				if needTag then
					needTag.Position = UDim2.new(1, -x, 0.5, 0)
					if needTag.Visible then
						x += needTag.Size.X.Offset + 6
					end
				end
				l.Size = UDim2.new(1, -(x + 24), 1, 0)
			end
			local function refreshTag()
				local b = cfg.binds[key]
				if type(b) == "table" and ((b.key and b.key ~= "") or b.mode == "Always" or b.mode == "Never") then
					local mode = b.mode or "Toggle"
					tag.Text = if mode == "Toggle" then Input.keyLabel(b.key) elseif mode == "Hold" then Input.keyLabel(b.key) .. " hold" else string.lower(mode)
					tag.Size = UDim2.new(0, math.max(24, UI.textW(tag.Text, M.small) + 14), 0, 18)
					-- metal looks: the key chip is a small brushed key (dark ink), as in the design
					tag.TextColor3 = if UI.brushed(tag) then UI.metal.ink else C.muted
					tag.Visible = true
				else
					tag.Text = ""
					tag.Visible = false
				end
				layout()
			end
			refreshTag()
			-- the same key can have several rows (Home + its own tab): every registered tag refreshes
			do
				local prevTag = UI.bindTags[key]
				UI.bindTags[key] = if prevTag then function()
					prevTag()
					refreshTag()
				end else refreshTag
			end
			r.Active = true
			local function onRight(input: InputObject)
				if input.UserInputType == Enum.UserInputType.MouseButton2 then
					UI.openBindPopup(key, text, UIS:GetMouseLocation() - Vector2.new(0, GuiService:GetGuiInset().Y))
				end
			end
			r.InputBegan:Connect(onRight)
			pill.InputBegan:Connect(onRight)
			local lastShown: boolean? = nil
			local lastNeed: string? = nil
			local function refresh(animate: boolean)
				local on = cfg[key] == true
				lastShown = on
				local unmet = UI.needUnmet(need)
				local blocked = unmet ~= nil
				lastNeed = unmet
				if needTag then
					local show = on and blocked
					if unmet then
						needTag.Text = UI.needText(unmet)
					end
					if needTag.Visible ~= show then
						needTag.Visible = show
						layout()
					end
				end
				local knobGoal = if on then UDim2.new(1, -(M.knob + 2), 0.5, 0) else UDim2.new(0, 2, 0.5, 0)
				local knobCol = if on then Color3.new(1, 1, 1) else C.knobOff
				local labelCol = if on and not blocked then C.text else C.dim
				local glowTr = if on then UI.glowAlpha(0.9) else 1
				if animate then
					tween(knob, TW_TOGGLE, { Position = knobGoal, BackgroundColor3 = knobCol })
					tween(fill, TW_TOGGLE, { BackgroundTransparency = if on then 0 else 1 })
					tween(l, TW_TOGGLE, { TextColor3 = labelCol })
					tween(glow, TW_TOGGLE, { ImageTransparency = glowTr })
				else
					knob.Position = knobGoal
					knob.BackgroundColor3 = knobCol
					fill.BackgroundTransparency = if on then 0 else 1
					l.TextColor3 = labelCol
					glow.ImageTransparency = glowTr
				end
				glow:SetAttribute("glowOff", not on)
			end
			refresh(false)
			local lastExp = expShown()
			table.insert(UI.sync, function()
				if (cfg[key] == true) ~= lastShown or (need ~= nil and UI.needUnmet(need) ~= lastNeed) then
					refresh(true)
				end
				if exp and expShown() ~= lastExp then
					lastExp = expShown()
					layout()
					UI.refilter()
				end
			end)
			-- registry for tests / automation: S.ui.toggles[cfgKey].shown() is what the pill currently
			-- displays. A duplicate row (Home + tab) chains its refresh so a programmatic change
			-- (PANIC, presets, binds) repaints every pill, not only the last one built.
			do
				local prevReg = S.ui.toggles[key]
				S.ui.toggles[key] = { pill = pill, row = r, refresh = function()
					if prevReg then
						prevReg.refresh()
					end
					refresh(true)
				end, shown = function()
					return lastShown
				end }
			end
			pill.MouseEnter:Connect(function()
				if cfg[key] == true then
					tween(glow, TW_HOVER, { ImageTransparency = UI.glowAlpha(1.3) })
				else
					tween(knob, TW_HOVER, { BackgroundColor3 = C.dim })
				end
			end)
			pill.MouseLeave:Connect(function()
				if cfg[key] == true then
					tween(glow, TW_HOVER, { ImageTransparency = UI.glowAlpha(0.9) })
				else
					tween(knob, TW_HOVER, { BackgroundColor3 = C.knobOff })
				end
			end)
			pill.MouseButton1Click:Connect(function()
				cfg[key] = not cfg[key]
				refresh(true)
				-- onChange may change other keys (a positioning toggle sets ragePosition, the accent cycle sets
				-- maxTheme): save AFTER it, or the derived change is lost on the next hop / reinject
				if topts.onChange then
					topts.onChange(cfg[key])
				end
				saveConfig()
			end)
			if subState and exp then
				-- the sub-rows: ordinary rows of this group, indented, placed right after this one
				local prevParent = g.subParent
				g.subParent = subState
				local okSub, errSub = pcall(topts.sub, g)
				g.subParent = prevParent
				if not okSub then
					log("WARN", ("menu: the sub-options of %s failed to build: %s"):format(text, tostring(errSub)))
				end
				exp.MouseButton1Click:Connect(function()
					if subState.animating then
						return
					end
					local opening = not subState.open
					if UI.brushed(exp :: TextButton) then
						-- metal looks: an open sub-options button is a brushed key, as in the design
						local light = (exp :: TextButton):FindFirstChild("BrushedLight")
						if light then
							(light :: Frame).Visible = opening
						end
						(exp :: TextButton).BackgroundTransparency = if opening then 0 else 1
						recolourIcon(expIc :: GuiObject, if opening then UI.metal.ink else C.muted)
					else
						recolourIcon(expIc :: GuiObject, if opening then C.accent else C.muted)
					end
					if opening then
						subState.open = true
						UI.refilter()
						UI.animSub(subState, true, nil)
					else
						UI.animSub(subState, false, function()
							subState.open = false
							UI.refilter()
						end)
					end
				end)
				exp.MouseEnter:Connect(function()
					if not (UI.metal and subState.open) then
						(exp :: TextButton).BackgroundTransparency = if UI.metal then 0.85 else 0
					end
				end)
				exp.MouseLeave:Connect(function()
					if not (UI.metal and subState.open) then
						(exp :: TextButton).BackgroundTransparency = 1
					end
				end)
			end
			return r
		end

		function g.slider(_, text: string, key: string, min: number, max: number, step: number?, sopts: { [string]: any })
			sopts = sopts or {}
			sopts.cfgKey = key
			UI.count("slider")
			local r = row(M.row, text, sopts)
			local trackW = sopts.trackW or M.trackW
			local reserve = trackW + 10 + M.valueW
			rowLabel(r, text, sopts, reserve)
			-- value (right): the number in text colour, the unit muted
			local v = button(r, "", M.value, C.text, C.surface)
			v.Name = "Value"
			v.BackgroundTransparency = 1
			v.Size = UDim2.new(0, M.valueW, 1, 0)
			v.AnchorPoint = Vector2.new(1, 0)
			v.Position = UDim2.new(1, 0, 0, 0)
			v.TextXAlignment = Enum.TextXAlignment.Right
			v.RichText = true
			-- outside the safe range an amber warning appears left of the track
			local warnIc: GuiObject? = nil
			if sopts.safe then
				local holder = frame(r)
				holder.Size = UDim2.fromOffset(16, 16)
				holder.AnchorPoint = Vector2.new(1, 0.5)
				holder.Position = UDim2.new(1, -(reserve + 4), 0.5, 0)
				holder.Visible = false
				local wi = icon(holder, "warn", 14)
				recolourIcon(wi, C.warn)
				UI.tip(holder, UI.riskText(sopts.safeText or "SERVER-CHECKED"))
				warnIc = holder
			end
			-- hit area (16 px tall) → track (4 px) → glow → fill → knob
			local rail = button(r, "", 10, C.text, C.off)
			rail.Name = "Rail"
			rail.BackgroundTransparency = 1
			rail.Size = UDim2.new(0, trackW, 0, 16)
			rail.AnchorPoint = Vector2.new(1, 0.5)
			rail.Position = UDim2.new(1, -(M.valueW + 10), 0.5, 0)
			local track = frame(rail, C.off)
			track.Size = UDim2.new(1, 0, 0, 4)
			track.AnchorPoint = Vector2.new(0, 0.5)
			track.Position = UDim2.new(0, 0, 0.5, 0)
			corner(track, 2)
			local fillGlow = UI.glow(track, 5, 0.7)
			fillGlow.AnchorPoint = Vector2.new(0, 0.5)
			fillGlow.Position = UDim2.new(0, -5, 0.5, 0)
			local fill = frame(track, Color3.new(1, 1, 1))
			fill.Size = UDim2.new(0, 0, 1, 0)
			corner(fill, 2)
			UI.metalFill(gradient(fill, C.accent2, C.accent))
			local knob = frame(track, Color3.new(1, 1, 1))
			knob.Size = UDim2.new(0, 10, 0, 10)
			knob.AnchorPoint = Vector2.new(0.5, 0.5)
			knob.Position = UDim2.new(0, 0, 0.5, 0)
			corner(knob, 5)
			local ring = stroke(knob, if UI.metal then UI.metal.lite else C.accent, 1)
			ring.Thickness = if UI.metal then 2 else 3
			local function fmt(n: number): string
				if sopts.fmt then
					return sopts.fmt(n)
				end
				return tostring(math.floor(n * 100 + 0.5) / 100)
			end
			local unit = if type(sopts.unit) == "string" and sopts.unit ~= "" then sopts.unit else nil
			local mutedHex = ("#%02x%02x%02x"):format(math.floor(C.muted.R * 255 + 0.5), math.floor(C.muted.G * 255 + 0.5), math.floor(C.muted.B * 255 + 0.5))
			local shownText = ""
			local function refresh(animateKnob: boolean?)
				local n = tonumber(cfg[key]) or min
				local rel = math.clamp((n - min) / math.max(max - min, 1e-6), 0, 1)
				local kp = UDim2.new(rel, 0, 0.5, 0)
				fillGlow.Visible = rel > 0.01
				-- the fill travels with the knob (a click-jump used to snap the fill and glide the knob)
				if animateKnob then
					tween(knob, TW_KNOB, { Position = kp })
					tween(fill, TW_KNOB, { Size = UDim2.new(rel, 0, 1, 0) })
					tween(fillGlow, TW_KNOB, { Size = UDim2.new(rel, 10, 1, 10) })
				else
					knob.Position = kp
					fill.Size = UDim2.new(rel, 0, 1, 0)
					fillGlow.Size = UDim2.new(rel, 10, 1, 10)
				end
				shownText = fmt(n)
				local unsafe = sopts.safe ~= nil and (n < sopts.safe[1] or n > sopts.safe[2])
				local numCol = if unsafe then ("#%02x%02x%02x"):format(math.floor(C.warn.R * 255 + 0.5), math.floor(C.warn.G * 255 + 0.5), math.floor(C.warn.B * 255 + 0.5)) else nil
				local num = if numCol then ('<font color="%s">%s</font>'):format(numCol, shownText) else shownText
				v.Text = if unit then ('%s<font color="%s">%s%s</font>'):format(num, mutedHex, if unit == "%" or unit == "°" or unit == "×" then "" else " ", unit) else num
				if warnIc then
					warnIc.Visible = unsafe
				end
			end
			local function setRing(on: boolean)
				tween(ring, TW_HOVER, { Transparency = if on then 0.72 else 1 })
			end
			rail.MouseEnter:Connect(function()
				setRing(true)
			end)
			rail.MouseLeave:Connect(function()
				if not (UI.drag and UI.drag.owner == rail) then
					setRing(false)
				end
			end)
			local lastChangeAt = 0
			local function setValue(n: number, dragging: boolean?)
				if step then
					n = math.floor(n / step + 0.5) * step
					-- kill float dust (0.1 + 0.2 → 0.30000000000000004 in the badge and the config)
					local digits = math.max(0, math.ceil(-math.log10(step)))
					local pow = 10 ^ digits
					n = math.floor(n * pow + 0.5) / pow
				end
				n = math.clamp(n, min, max)
				if cfg[key] == n then
					return
				end
				cfg[key] = n
				-- while the mouse drags: no knob tween per pixel and the change callback at ≤ 20 Hz
				-- (the release fires it once more with the final value)
				refresh(not dragging)
				if sopts.onChange then
					local now = os.clock()
					if not dragging or now - lastChangeAt > 0.05 then
						lastChangeAt = now
						sopts.onChange(n)
					end
				end
			end
			local function setFromX(x: number, dragging: boolean?)
				local rel = math.clamp((x - rail.AbsolutePosition.X) / math.max(rail.AbsoluteSize.X, 1), 0, 1)
				setValue(min + (max - min) * rel, dragging)
			end
			refresh(false)
			table.insert(UI.sync, function()
				if fmt(tonumber(cfg[key]) or min) ~= shownText then
					refresh(true)
				end
			end)
			-- one kit-level drag manager (UI.beginDrag) instead of two UserInputService connections per
			-- slider: ~120 sliders used to run 240 handlers on every mouse movement
			rail.InputBegan:Connect(function(i)
				if i.UserInputType == Enum.UserInputType.MouseButton1 then
					setFromX(i.Position.X, true)
					setRing(true)
					UI.beginDrag(function(pos: Vector2)
						setFromX(pos.X, true)
					end, function()
						if sopts.onChange then
							sopts.onChange(tonumber(cfg[key]) or min)
						end
						refresh(true)
						setRing(false)
						saveConfig()
					end)
					if UI.drag then
						UI.drag.owner = rail
					end
				end
			end)
			-- click the number to type a value: Enter sets it, Esc / clicking away keeps the old one. The box
			-- starts with the plain number ("×0.05" / "15k" / "never" could not be parsed back — the old
			-- double-click box silently ignored every Enter on those), accepts "0.3", "x0.3", "15k", "20%",
			-- "never", and a typed value may pass the track's ends up to sopts.typeMin / typeMax.
			local tMin = if type(sopts.typeMin) == "number" then sopts.typeMin else min
			local tMax = if type(sopts.typeMax) == "number" then sopts.typeMax else max
			local typeDigits = if step and step >= 1 then 0 else 3
			local function plain(n: number): string
				local s = ("%." .. typeDigits .. "f"):format(n)
				if typeDigits > 0 then
					s = string.gsub(string.gsub(s, "0+$", ""), "%.$", "")
				end
				return s
			end
			UI.tip(v, ("Click to type a value (%s – %s)"):format(plain(tMin), plain(tMax)))
			v.MouseEnter:Connect(function()
				v.BackgroundTransparency = 0.55
			end)
			v.MouseLeave:Connect(function()
				v.BackgroundTransparency = 1
			end)
			local editing = false
			v.MouseButton1Click:Connect(function()
				if editing then
					return
				end
				editing = true
				local box = Instance.new("TextBox")
				box.Size = UDim2.new(0, math.max(M.valueW + 24, 66), 0, 22)
				box.AnchorPoint = Vector2.new(1, 0.5)
				box.Position = UDim2.new(1, 2, 0.5, 0)
				box.BackgroundColor3 = C.surface
				box.BorderSizePixel = 0
				UI.setFont(box, UI.F.medium)
				box.TextSize = M.value
				box.TextColor3 = C.text
				box.PlaceholderText = plain(tonumber(cfg[key]) or min)
				box.PlaceholderColor3 = C.muted
				box.TextXAlignment = Enum.TextXAlignment.Right
				box.Text = plain(tonumber(cfg[key]) or min)
				box.ClearTextOnFocus = false
				box.ZIndex = 5
				box.Parent = r
				corner(box, 5)
				stroke(box, C.accent, 0.2)
				padding(box, 0, 6, 0, 6)
				box:CaptureFocus()
				pcall(function()
					box.SelectionStart = 1
					box.CursorPosition = #box.Text + 1
				end)
				box.FocusLost:Connect(function(enterPressed: boolean)
					editing = false
					local n = if enterPressed then UI.parseNumber(box.Text) else nil
					box:Destroy()
					if n == nil then
						return
					end
					local pow = 10 ^ typeDigits
					n = math.clamp(math.floor(n * pow + 0.5) / pow, tMin, tMax)
					if cfg[key] ~= n then
						cfg[key] = n
						refresh(true)
						if sopts.onChange then
							sopts.onChange(n)
						end
					else
						refresh(true)
					end
					saveConfig()
				end)
			end)
			return r
		end

		function g.cycle(_, text: string, key: string, options: { string }, copts: { [string]: any })
			copts = copts or {}
			copts.cfgKey = key
			UI.count("cycle")
			local r = row(M.row, text, copts)
			rowLabel(r, text, copts, M.ctrlW)
			-- v5: optional copts.fmt(value) → display text, so numeric options read as words
			-- shown lowercase like every label (the stored value keeps its case)
			local function shownOf(v: any): string
				if copts.fmt then
					local okF, s = pcall(copts.fmt, v)
					if okF and s ~= nil then
						return string.lower(tostring(s))
					end
				end
				return string.lower(tostring(v))
			end
			local b = button(r, "", M.value, C.text, C.surface)
			b.Name = "Dropdown"
			b.Size = UDim2.new(0, M.ctrlW, 0, 22)
			b.AnchorPoint = Vector2.new(1, 0.5)
			b.Position = UDim2.new(1, 0, 0.5, 0)
			corner(b, 5)
			local bs = stroke(b, C.edge, 0)
			local val = label(b, "", M.value, C.text, UI.F.body)
			val.Size = UDim2.new(1, -30, 1, 0)
			val.Position = UDim2.fromOffset(9, 0)
			val.TextTruncate = Enum.TextTruncate.AtEnd
			local chev = icon(b, "expand", 16)
			chev.AnchorPoint = Vector2.new(1, 0.5)
			chev.Position = UDim2.new(1, -4, 0.5, 0)
			recolourIcon(chev, C.muted)
			local function refresh()
				val.Text = shownOf(cfg[key])
			end
			refresh()
			table.insert(UI.sync, function()
				if val.Text ~= shownOf(cfg[key]) then
					refresh()
				end
			end)
			b.MouseEnter:Connect(function()
				b.BackgroundColor3 = C.card
			end)
			b.MouseLeave:Connect(function()
				b.BackgroundColor3 = C.surface
			end)
			b.MouseButton1Click:Connect(function()
				bs.Color = C.accent
				UI.openDropdown(b, M.ctrlW, function(f: Frame): number
					for i, opt in ipairs(options) do
						UI.dropdownOption(f, 4 + (i - 1) * 24, shownOf(opt), cfg[key] == opt, function()
							cfg[key] = opt
							refresh()
							UI.closeDropdown()
							-- save AFTER onChange: the Accent cycle's onChange sets cfg.maxTheme, which was lost
							-- (a Max look picked as the last change reverted after a hop)
							if copts.onChange then
								copts.onChange(opt)
							end
							saveConfig()
						end)
					end
					return 8 + #options * 24
				end, function()
					bs.Color = C.edge
				end)
			end)
			return r
		end

		function g.color(_, text: string, key: string, copts: { [string]: any })
			copts = copts or {}
			copts.cfgKey = key
			UI.count("color")
			local r = row(M.row, text, copts)
			rowLabel(r, text, copts, 36)
			local sw = button(r, "", 10, C.text, Vis.col(key))
			sw.Name = "Swatch"
			sw.Size = UDim2.new(0, 28, 0, 16)
			sw.AnchorPoint = Vector2.new(1, 0.5)
			sw.Position = UDim2.new(1, 0, 0.5, 0)
			corner(sw, 4)
			stroke(sw, Color3.new(1, 1, 1), 0.82)
			local hh, ss, vv = Vis.col(key):ToHSV()
			local function apply(c3: Color3)
				cfg[key] = { math.floor(c3.R * 255 + 0.5), math.floor(c3.G * 255 + 0.5), math.floor(c3.B * 255 + 0.5) }
				sw.BackgroundColor3 = c3
				if copts.onChange then
					copts.onChange(c3)
				end
			end
			table.insert(UI.sync, function()
				local c = Vis.col(key)
				if sw.BackgroundColor3 ~= c then
					sw.BackgroundColor3 = c
				end
			end)
			sw.MouseButton1Click:Connect(function()
				hh, ss, vv = Vis.col(key):ToHSV()
				UI.openDropdown(sw, 206, function(f: Frame): number
					local rails: any = {}
					local function refreshRails()
						local hueKeys = {}
						for i = 0, 6 do
							table.insert(hueKeys, ColorSequenceKeypoint.new(i / 6, Color3.fromHSV((i / 6) % 1, 1, 1)))
						end
						rails.h.grad.Color = ColorSequence.new(hueKeys)
						rails.s.grad.Color = ColorSequence.new(Color3.fromHSV(hh, 0, vv), Color3.fromHSV(hh, 1, vv))
						rails.v.grad.Color = ColorSequence.new(Color3.new(0, 0, 0), Color3.fromHSV(hh, ss, 1))
						rails.h.mark.Position = UDim2.new(hh, 0, 0.5, 0)
						rails.s.mark.Position = UDim2.new(ss, 0, 0.5, 0)
						rails.v.mark.Position = UDim2.new(vv, 0, 0.5, 0)
					end
					local function setFrom(kind: string, px: number)
						local rl = rails[kind].rail
						local rel = math.clamp((px - rl.AbsolutePosition.X) / math.max(rl.AbsoluteSize.X, 1), 0, 1)
						if kind == "h" then
							hh = rel
						elseif kind == "s" then
							ss = rel
						else
							vv = rel
						end
						apply(Color3.fromHSV(hh, ss, vv))
						refreshRails()
					end
					local function mkRail(kind: string, y: number)
						local rl = button(f, "", 10, C.text, Color3.new(1, 1, 1))
						rl.Size = UDim2.new(1, -20, 0, 10)
						rl.Position = UDim2.fromOffset(10, y)
						rl.ZIndex = 61
						corner(rl, 5)
						local grad = Instance.new("UIGradient")
						grad.Parent = rl
						local mark = frame(rl, Color3.new(1, 1, 1))
						mark.Size = UDim2.fromOffset(4, 14)
						mark.AnchorPoint = Vector2.new(0.5, 0.5)
						mark.ZIndex = 62
						corner(mark, 2)
						stroke(mark, Color3.new(0, 0, 0), 0.45)
						rails[kind] = { rail = rl, grad = grad, mark = mark }
						rl.InputBegan:Connect(function(i)
							if i.UserInputType == Enum.UserInputType.MouseButton1 then
								setFrom(kind, i.Position.X)
								UI.beginDrag(function(pos: Vector2)
									setFrom(kind, pos.X)
								end, function()
									saveConfig()
								end)
							end
						end)
					end
					mkRail("h", 40)
					mkRail("s", 60)
					mkRail("v", 80)
					local presets = { C.accent, Color3.fromRGB(242, 240, 247), Color3.fromRGB(142, 138, 153), Color3.fromRGB(255, 92, 122), Color3.fromRGB(255, 150, 70), Color3.fromRGB(255, 214, 90), Color3.fromRGB(69, 223, 160), Color3.fromRGB(111, 201, 255), Color3.fromRGB(255, 114, 176) }
					for i, pc in ipairs(presets) do
						local pb = button(f, "", 10, C.text, pc)
						pb.Size = UDim2.fromOffset(18, 18)
						pb.Position = UDim2.fromOffset(10 + (i - 1) * 21, 10)
						pb.ZIndex = 61
						corner(pb, 9)
						stroke(pb, Color3.new(1, 1, 1), 0.82)
						pb.MouseButton1Click:Connect(function()
							hh, ss, vv = pc:ToHSV()
							apply(pc)
							saveConfig()
							refreshRails()
						end)
					end
					refreshRails()
					return 102
				end, copts.onClose)
			end)
			return r
		end

		-- keybind: click → press a key / mouse button / M4 / M5 (Escape or Backspace clears)
		function g.keybind(_, text: string, key: string, kopts: { [string]: any })
			kopts = kopts or {}
			kopts.cfgKey = key
			UI.count("keybind")
			local r = row(M.row, text, kopts)
			rowLabel(r, text, kopts, 90)
			local b = button(r, "", M.small, C.dim, Color3.fromRGB(26, 25, 32))
			b.Name = "Key"
			b.AutomaticSize = Enum.AutomaticSize.X
			b.Size = UDim2.new(0, 34, 0, 20)
			b.AnchorPoint = Vector2.new(1, 0.5)
			b.Position = UDim2.new(1, 0, 0.5, 0)
			UI.setFont(b, UI.F.semibold)
			corner(b, 4)
			local ks = stroke(b, C.edge, 0)
			padding(b, 0, 8, 0, 8)
			-- metal looks: the key is a brushed keycap with dark ink
			local keyed = UI.brushed(b)
			if keyed then
				b.TextColor3 = UI.metal.ink
				UI.setFont(b, UI.F.bold)
				b.BackgroundColor3 = Color3.fromRGB(228, 228, 232)
			end
			b.MouseEnter:Connect(function()
				if keyed then
					tween(b, TW_HOVER, { BackgroundColor3 = Color3.new(1, 1, 1) })
				else
					ks.Color = C.muted
				end
			end)
			b.MouseLeave:Connect(function()
				if keyed then
					tween(b, TW_HOVER, { BackgroundColor3 = Color3.fromRGB(228, 228, 232) })
				else
					ks.Color = C.edge
				end
			end)
			local function show()
				b.Text = Input.keyLabel(cfg[key])
			end
			show()
			table.insert(UI.sync, function()
				if not Input.capturing() and b.Text ~= Input.keyLabel(cfg[key]) then
					show()
				end
			end)
			b.MouseButton1Click:Connect(function()
				b.Text = "Press a key…"
				Input.captureKey(function(name)
					if name ~= false then
						cfg[key] = name or ""
						saveConfig()
						if kopts.onChange then
							kopts.onChange(cfg[key])
						end
					end
					show()
				end)
			end)
			return r
		end

		function g.button(_, text: string, fn: () -> (), tint: Color3?, bopts: any?)
			bopts = bopts or {}
			UI.count("button")
			local r = row(M.rowButton, text, bopts)
			-- neutral by default; a tint (accent / danger / warn) makes it the tinted primary style
			local base = if tint then tint else C.surface
			local b = button(r, string.lower(text), M.value, if tint then tint else C.dim, base)
			b.Size = UDim2.new(1, 0, 0, 26)
			b.AnchorPoint = Vector2.new(0, 0.5)
			b.Position = UDim2.new(0, 0, 0.5, 0)
			b.BackgroundTransparency = if tint then 0.87 else 0
			b.TextTruncate = Enum.TextTruncate.AtEnd
			corner(b, 6)
			local st = stroke(b, if tint then tint else C.edge, if tint then 0.6 else 0)
			-- metal looks: the accent (primary) button is a brushed key with dark ink; danger / warn keep their tint
			local keyed = tint == C.accent and UI.brushed(b)
			local rest = Color3.fromRGB(228, 228, 232)
			if keyed then
				b.BackgroundTransparency = 0
				b.BackgroundColor3 = rest
				b.TextColor3 = UI.metal.ink
				UI.setFont(b, UI.F.bold)
			end
			b.MouseEnter:Connect(function()
				if keyed then
					tween(b, TW_HOVER, { BackgroundColor3 = Color3.new(1, 1, 1) })
				elseif tint then
					tween(b, TW_HOVER, { BackgroundTransparency = 0.8 })
				else
					tween(b, TW_HOVER, { BackgroundColor3 = C.card, TextColor3 = C.text })
				end
			end)
			b.MouseLeave:Connect(function()
				if keyed then
					tween(b, TW_HOVER, { BackgroundColor3 = rest })
				elseif tint then
					tween(b, TW_HOVER, { BackgroundTransparency = 0.87 })
				else
					tween(b, TW_HOVER, { BackgroundColor3 = C.surface, TextColor3 = C.dim })
				end
			end)
			-- press feedback: a 1 px dip so a click is visibly acknowledged
			b.MouseButton1Down:Connect(function()
				b.Position = UDim2.new(0, 0, 0.5, 1)
				st.Transparency = 0
			end)
			b.MouseButton1Up:Connect(function()
				b.Position = UDim2.new(0, 0, 0.5, 0)
				st.Transparency = if keyed then 0.5 elseif tint then 0.6 else 0
			end)
			b.MouseButton1Click:Connect(function()
				local ok, err = pcall(fn)
				if not ok then
					reportError("button " .. text, err)
				end
			end)
			if type(bopts.desc) == "string" and bopts.desc ~= "" then
				UI.tip(b, bopts.desc)
			end
			return b
		end

		function g.note(_, text: string, nopts: { [string]: any })
			nopts = nopts or {}
			nopts.isNote = true
			UI.count("note")
			-- the row grows with its text (live notes change length) — a note can never run into the
			-- next row; nopts.height is only a floor
			local width = opts.colW or M.colW
			local minH = if text ~= "" then UI.textH(text, M.desc, nil, width) + 8 else math.max(18, nopts.height or 18)
			local r = row(minH, text, nopts)
			r.AutomaticSize = Enum.AutomaticSize.Y
			local l = label(r, text, M.desc, nopts.color or C.muted, UI.F.body)
			l.Size = UDim2.new(1, 0, 0, 0)
			l.Position = UDim2.new(0, 0, 0, 3)
			l.AutomaticSize = Enum.AutomaticSize.Y
			l.TextWrapped = true
			l.TextYAlignment = Enum.TextYAlignment.Top
			return l
		end

		-- picker: ‹ value › over a list that can change; idxKey persists the index
		function g.picker(_, text: string, getList: () -> { string }, idxKey: string, onChange: (string) -> ())
			UI.count("picker")
			local r = row(M.row, text)
			local l = label(r, string.lower(text), M.title, C.text, UI.F.body)
			l.Size = UDim2.new(0, 70, 1, 0)
			local val = label(r, "", M.value, C.text, UI.F.medium)
			val.Size = UDim2.new(1, -140, 1, 0)
			val.Position = UDim2.new(0, 74, 0, 0)
			val.TextTruncate = Enum.TextTruncate.AtEnd
			local function mk(ic: string, x: number): TextButton
				local b = button(r, "", M.title, C.text, C.surface)
				b.Size = UDim2.new(0, 24, 0, 22)
				b.AnchorPoint = Vector2.new(0, 0.5)
				b.Position = UDim2.new(1, x, 0.5, 0)
				corner(b, 5)
				stroke(b, C.edge, 0)
				recolourIcon(icon(b, ic, 16), C.dim)
				return b
			end
			local prev, nxt = mk("left", -52), mk("right", -24)
			local function refresh()
				local list = getList()
				if #list == 0 then
					val.Text = "—"
					return
				end
				cfg[idxKey] = ((tonumber(cfg[idxKey]) or 1) - 1) % #list + 1
				val.Text = list[cfg[idxKey]]
				onChange(list[cfg[idxKey]])
			end
			prev.MouseButton1Click:Connect(function()
				cfg[idxKey] = (tonumber(cfg[idxKey]) or 1) - 1
				refresh()
				saveConfig()
			end)
			nxt.MouseButton1Click:Connect(function()
				cfg[idxKey] = (tonumber(cfg[idxKey]) or 1) + 1
				refresh()
				saveConfig()
			end)
			refresh()
			return refresh
		end

		-- multiselect: cfg[key] = { [option] = true }
		function g.multiselect(_, text: string, key: string, options: { string }, mopts: { [string]: any })
			mopts = mopts or {}
			mopts.cfgKey = key
			UI.count("multiselect")
			local r = row(M.row, text, mopts)
			rowLabel(r, text, mopts, M.ctrlW)
			if type(cfg[key]) ~= "table" then
				cfg[key] = {}
			end
			local b = button(r, "", M.value, C.text, C.surface)
			b.Name = "Multiselect"
			b.Size = UDim2.new(0, M.ctrlW, 0, 22)
			b.AnchorPoint = Vector2.new(1, 0.5)
			b.Position = UDim2.new(1, 0, 0.5, 0)
			corner(b, 5)
			local bs = stroke(b, C.edge, 0)
			local val = label(b, "", M.value, C.text, UI.F.body)
			val.Size = UDim2.new(1, -30, 1, 0)
			val.Position = UDim2.fromOffset(9, 0)
			val.TextTruncate = Enum.TextTruncate.AtEnd
			local chev = icon(b, "expand", 16)
			chev.AnchorPoint = Vector2.new(1, 0.5)
			chev.Position = UDim2.new(1, -4, 0.5, 0)
			recolourIcon(chev, C.muted)
			local function summary(): string
				local on = {}
				for _, opt in ipairs(options) do
					if cfg[key][opt] == true then
						table.insert(on, opt)
					end
				end
				if #on == 0 then
					return "None"
				elseif #on == #options then
					return "All"
				end
				return table.concat(on, ", ")
			end
			local function refresh()
				val.Text = summary()
			end
			refresh()
			-- follows changes made elsewhere (sanitize forcing a hitbox on, presets, a duplicate row)
			table.insert(UI.sync, function()
				if val.Text ~= summary() then
					refresh()
				end
			end)
			b.MouseEnter:Connect(function()
				b.BackgroundColor3 = C.card
			end)
			b.MouseLeave:Connect(function()
				b.BackgroundColor3 = C.surface
			end)
			b.MouseButton1Click:Connect(function()
				bs.Color = C.accent
				UI.openDropdown(b, M.ctrlW, function(f: Frame): number
					local optBtns = {}
					local function paint()
						for opt, ob in pairs(optBtns) do
							local on = cfg[key][opt] == true
							ob:SetAttribute("selected", on)
							local ic = ob:FindFirstChild("Icon")
							if ic then
								ic.Visible = on
							end
							local lb = ob:FindFirstChildOfClass("TextLabel")
							if lb and lb.Name ~= "Icon" then
								lb.TextColor3 = if on then C.accent else C.dim
							end
						end
					end
					for i, opt in ipairs(options) do
						optBtns[opt] = UI.dropdownOption(f, 4 + (i - 1) * 24, opt, cfg[key][opt] == true, function()
							cfg[key][opt] = if cfg[key][opt] then nil else true
							if mopts.onChange then
								mopts.onChange(cfg[key])
							end
							saveConfig()
							refresh()
							paint()
						end)
					end
					return 8 + #options * 24
				end, function()
					bs.Color = C.edge
				end)
			end)
			return r
		end

		function g.custom(_, hgt: number, text: string?, copts: any?): Frame
			return row(hgt, text or "", copts)
		end
		-- a short text value bound to cfg[key] (a name, a tag): typed in a field on the right, committed on
		-- Enter or when focus leaves; topts.maxLen caps it, topts.placeholder shows while empty
		function g.textbox(_, text: string, key: string, topts: { [string]: any })
			topts = topts or {}
			topts.cfgKey = key
			UI.count("textbox")
			local r = row(M.row, text, topts)
			rowLabel(r, text, topts, 150)
			local box = Instance.new("TextBox")
			box.Name = "Field"
			box.Size = UDim2.new(0, 140, 0, 22)
			box.AnchorPoint = Vector2.new(1, 0.5)
			box.Position = UDim2.new(1, 0, 0.5, 0)
			box.BackgroundColor3 = C.surface
			box.BorderSizePixel = 0
			box.ClearTextOnFocus = false
			box.FontFace = UI.F.medium
			box.TextSize = M.value
			box.TextColor3 = C.text
			box.PlaceholderColor3 = C.muted
			box.PlaceholderText = topts.placeholder or ""
			box.TextXAlignment = Enum.TextXAlignment.Left
			box.TextTruncate = Enum.TextTruncate.AtEnd
			box.Text = tostring(cfg[key] or "")
			box.Parent = r
			corner(box, 5)
			stroke(box, C.edge, 0)
			padding(box, 0, 8, 0, 8)
			local maxLen = topts.maxLen or 24
			box:GetPropertyChangedSignal("Text"):Connect(function()
				local cut = utf8.offset(box.Text, maxLen + 1)
				if utf8.len(box.Text) and cut then
					box.Text = box.Text:sub(1, cut - 1)
				end
			end)
			box.FocusLost:Connect(function()
				local v = box.Text:gsub("^%s+", ""):gsub("%s+$", "")
				cfg[key] = v
				box.Text = v
				if topts.onChange then
					topts.onChange(v)
				end
			end)
			table.insert(UI.sync, function()
				if not box:IsFocused() and box.Text ~= tostring(cfg[key] or "") then
					box.Text = tostring(cfg[key] or "")
				end
			end)
			return box
		end

		-- read-only row: label left, a live value right (the getter runs while the menu is open)
		function g.info(_, text: string, getter: () -> any, iopts: any?): TextLabel
			iopts = iopts or {}
			UI.count("info")
			local r = row(M.row, text, iopts)
			local l = label(r, string.lower(text), M.title, C.dim, UI.F.body)
			l.Size = UDim2.new(0.45, 0, 1, 0)
			l.TextTruncate = Enum.TextTruncate.AtEnd
			local v = label(r, "", M.value, C.text, UI.F.medium)
			v.Size = UDim2.new(0.55, 0, 1, 0)
			v.Position = UDim2.new(0.45, 0, 0, 0)
			v.TextXAlignment = Enum.TextXAlignment.Right
			v.TextTruncate = Enum.TextTruncate.AtEnd
			local function refresh()
				local ok, s = pcall(getter)
				local txt = if ok and s ~= nil then tostring(s) else "—"
				if v.Text ~= txt then
					v.Text = txt
				end
			end
			refresh()
			UI.syncLazy(function()
				if r.Visible then
					refresh()
				end
			end)
			return v
		end
		-- a key / value row its owner fills (the Debug readouts): the everyday row look, the value
		-- right-aligned in the value face; the caller may tint it
		function g.stat(_, text: string, sopts: any?): TextLabel
			UI.count("info")
			local r = row(M.row, text, sopts or {})
			local l = label(r, string.lower(text), M.title, C.dim, UI.F.body)
			l.Size = UDim2.new(0.34, 0, 1, 0)
			l.TextTruncate = Enum.TextTruncate.AtEnd
			local v = label(r, "—", M.value, C.text, UI.F.medium)
			v.Size = UDim2.new(0.66, -8, 1, 0)
			v.Position = UDim2.new(0.34, 8, 0, 0)
			v.TextXAlignment = Enum.TextXAlignment.Right
			v.TextTruncate = Enum.TextTruncate.AtEnd
			return v
		end
		-- a card of `n` monospace lines (shot and packet logs)
		function g.logBlock(_, text: string, n: number): { TextLabel }
			local lineH = math.max(16, UI.TEXT_MIN + 5)
			local r = row(n * lineH + 18, text, {})
			local card = frame(r, C.surface)
			card.Size = UDim2.new(1, 0, 1, -6)
			card.Position = UDim2.fromOffset(0, 3)
			corner(card, 8)
			stroke(card, C.edge, 0)
			padding(card, 6, 10, 6, 10)
			vlist(card, 0)
			local out = {}
			for i = 1, n do
				local t = label(card, "", UI.TEXT_MIN, C.dim, UI.F.code)
				t.Size = UDim2.new(1, 0, 0, lineH)
				t.TextTruncate = Enum.TextTruncate.AtEnd
				t.LayoutOrder = i
				out[i] = t
			end
			return out
		end

		-- a row of equal buttons: items = { { label, fn, tint? }, ... }
		function g.buttonRow(_, text: string, items: { any }, bopts: any?): { TextButton }
			bopts = bopts or {}
			UI.count("button")
			local r = row(M.rowButton, text, bopts)
			local out = {}
			local n = #items
			for i, it in ipairs(items) do
				local tint = it[3]
				local b = button(r, string.lower(tostring(it[1])), M.value, if tint then tint else C.dim, if tint then tint else C.surface)
				b.Size = UDim2.new(1 / n, if i < n then -6 else 0, 0, 26)
				b.AnchorPoint = Vector2.new(0, 0.5)
				b.Position = UDim2.new((i - 1) / n, if i > 1 then (i - 1) * 6 / n else 0, 0.5, 0)
				b.BackgroundTransparency = if tint then 0.87 else 0
				b.TextTruncate = Enum.TextTruncate.AtEnd
				corner(b, 6)
				stroke(b, if tint then tint else C.edge, if tint then 0.6 else 0)
				-- metal looks: an accent button is a brushed key (see g.button)
				local keyed = tint == C.accent and UI.brushed(b)
				if keyed then
					b.BackgroundTransparency = 0
					b.BackgroundColor3 = Color3.fromRGB(228, 228, 232)
					b.TextColor3 = UI.metal.ink
					UI.setFont(b, UI.F.bold)
				end
				b.MouseEnter:Connect(function()
					if keyed then
						b.BackgroundColor3 = Color3.new(1, 1, 1)
					elseif tint then
						b.BackgroundTransparency = 0.8
					else
						b.BackgroundColor3 = C.card
						b.TextColor3 = C.text
					end
				end)
				b.MouseLeave:Connect(function()
					if keyed then
						b.BackgroundColor3 = Color3.fromRGB(228, 228, 232)
					elseif tint then
						b.BackgroundTransparency = 0.87
					else
						b.BackgroundColor3 = C.surface
						b.TextColor3 = C.dim
					end
				end)
				b.MouseButton1Click:Connect(function()
					local ok, err = pcall(it[2])
					if not ok then
						reportError("button " .. tostring(it[1]), err)
					end
				end)
				out[i] = b
			end
			return out
		end

		-- list: single-select scrolling list with a search box. lopts = { height, search = true,
		--   items = () -> { { id, label, sub?, color?, dim? } }, selected = () -> id?, onSelect = (id) -> () }
		-- Rows are pooled; returns refresh(). Re-renders itself when the selection changes elsewhere.
		function g.list(_, text: string, lopts: any)
			lopts = lopts or {}
			lopts.isList = true
			UI.count("list")
			-- the visible area is a whole number of rows (+ 8 px padding): no half row cut off at
			-- the bottom edge of the list
			local RH = M.listRow
			local hdr = if lopts.search ~= false then 52 else 24
			local wanted = math.ceil((lopts.height or 200) * 1.15)
			local rowsFit = math.max(3, math.floor((wanted - hdr - 8) / RH))
			local height = hdr + rowsFit * RH + 8
			local r = row(height, text, lopts)
			local l = label(r, string.lower(text), M.title, C.text, UI.F.body)
			l.Size = UDim2.new(1, -110, 0, 22)
			local countLbl = label(r, "", M.small, C.muted, UI.F.medium)
			countLbl.Size = UDim2.new(0, 100, 0, 22)
			countLbl.Position = UDim2.new(1, -100, 0, 0)
			countLbl.TextXAlignment = Enum.TextXAlignment.Right
			local top = 24
			local query = ""
			local refresh: any
			if lopts.search ~= false then
				local box = Instance.new("TextBox")
				box.Size = UDim2.new(1, 0, 0, 24)
				box.Position = UDim2.new(0, 0, 0, 24)
				box.BackgroundColor3 = C.surface
				box.BorderSizePixel = 0
				UI.setFont(box, UI.F.body)
				box.TextSize = M.value
				box.TextColor3 = C.text
				box.PlaceholderText = lopts.placeholder or "Search"
				box.PlaceholderColor3 = C.muted
				box.Text = ""
				box.ClearTextOnFocus = false
				box.TextXAlignment = Enum.TextXAlignment.Left
				box.Parent = r
				corner(box, 6)
				local bs = stroke(box, C.edge, 0)
				padding(box, 0, 8, 0, 26)
				local sic = icon(box, "search", 14)
				sic.AnchorPoint = Vector2.new(0, 0.5)
				sic.Position = UDim2.new(0, -19, 0.5, 0)
				recolourIcon(sic, C.muted)
				box.Focused:Connect(function()
					tween(bs, TW_HOVER, { Color = C.accent })
				end)
				box.FocusLost:Connect(function()
					tween(bs, TW_HOVER, { Color = C.edge })
				end)
				box:GetPropertyChangedSignal("Text"):Connect(function()
					query = string.lower(box.Text)
					if refresh then
						refresh()
					end
				end)
				top = 52
			end
			local sc = Instance.new("ScrollingFrame")
			sc.Size = UDim2.new(1, 0, 1, -top)
			sc.Position = UDim2.new(0, 0, 0, top)
			sc.BackgroundColor3 = C.side
			sc.BackgroundTransparency = 0
			sc.BorderSizePixel = 0
			sc.ScrollBarThickness = 4
			sc.ScrollBarImageColor3 = C.faint
			sc.ScrollBarImageTransparency = 0
			sc.AutomaticCanvasSize = Enum.AutomaticSize.Y
			sc.CanvasSize = UDim2.new(0, 0, 0, 0)
			sc.ScrollingDirection = Enum.ScrollingDirection.Y
			sc.Parent = r
			corner(sc, 6)
			stroke(sc, C.edge, 0)
			vlist(sc, 2)
			padding(sc, 4, 6, 4, 4)
			local pool: { any } = {}
			local rowId: { [Instance]: string } = {}
			local lastSel: any = nil
			local function mkRow(): any
				local b = button(sc, "", M.value, C.dim, C.accent)
				b.BackgroundTransparency = 1
				b.Size = UDim2.new(1, 0, 0, RH - 2)
				b.TextXAlignment = Enum.TextXAlignment.Left
				b.TextTruncate = Enum.TextTruncate.AtEnd
				UI.setFont(b, UI.F.body)
				corner(b, 5)
				padding(b, 0, 8, 0, 8)
				local st = stroke(b, C.accent, 1)
				local sub = label(b, "", M.small, C.muted, UI.F.medium)
				sub.Size = UDim2.new(0, 120, 1, 0)
				sub.Position = UDim2.new(1, -120, 0, 0)
				sub.TextXAlignment = Enum.TextXAlignment.Right
				local rec = { btn = b, sub = sub, stroke = st, selected = false }
				b.MouseEnter:Connect(function()
					if not rec.selected then
						tween(b, TW_HOVER, { BackgroundTransparency = 0.88 })
					end
				end)
				b.MouseLeave:Connect(function()
					if not rec.selected then
						tween(b, TW_HOVER, { BackgroundTransparency = 1 })
					end
				end)
				b.MouseButton1Click:Connect(function()
					local id = rowId[b]
					if id ~= nil and lopts.onSelect then
						local ok, err = pcall(lopts.onSelect, id)
						if not ok then
							reportError("list " .. text, err)
						end
						refresh()
					end
				end)
				return rec
			end
			local scrolledFor: any = nil
			refresh = function()
				local items = lopts.items and lopts.items() or {}
				local sel = lopts.selected and lopts.selected() or nil
				lastSel = sel
				local shown = 0
				local selIdx: number? = nil
				for _, it in ipairs(items) do
					local lab = tostring(it.label or it.id)
					if query == "" or string.find(string.lower(lab), query, 1, true) or (it.sub and string.find(string.lower(tostring(it.sub)), query, 1, true)) then
						shown += 1
						local rec = pool[shown]
						if not rec then
							rec = mkRow()
							pool[shown] = rec
						end
						local b = rec.btn
						rowId[b] = it.id
						b.Visible = true
						b.LayoutOrder = shown
						b.Text = lab
						rec.sub.Text = tostring(it.sub or "")
						rec.sub.TextColor3 = it.color or C.muted
						rec.selected = it.id == sel
						if rec.selected then
							selIdx = shown
						end
						b.TextColor3 = if rec.selected then C.text elseif it.dim then C.muted else C.dim
						b.BackgroundColor3 = C.accent
						b.BackgroundTransparency = if rec.selected then 0.82 else 1
						rec.stroke.Transparency = if rec.selected then 0.35 else 1
					end
				end
				for i = shown + 1, #pool do
					pool[i].btn.Visible = false
				end
				countLbl.Text = if shown == #items then tostring(#items) else ("%d / %d"):format(shown, #items)
				-- bring the selection into view when it changed (a weapon picked elsewhere, first build)
				if selIdx and sel ~= scrolledFor then
					scrolledFor = sel
					local visible = math.max(sc.AbsoluteWindowSize.Y, RH)
					local y = math.max(0, (selIdx - 1) * RH - visible / 2 + RH / 2)
					task.defer(function()
						if sc.Parent then
							sc.CanvasPosition = Vector2.new(0, y)
						end
					end)
				end
			end
			refresh()
			table.insert(UI.sync, function()
				local sel = lopts.selected and lopts.selected() or nil
				if sel ~= lastSel then
					refresh()
				end
			end)
			return refresh
		end

		return g
	end

	-----------------------------------------------------------------------------
	-- §12 menu — window, rail, sub-tabs, search, Simple/Advanced, presets, pages, preview
	-----------------------------------------------------------------------------
	local Menu: any = { pages = {}, tabBtns = {}, subs = {}, activeTab = "", chips = {}, syncMarks = {} }
	S.menu = Menu
	-- window 820 × 520 at 100 % (Menu size re-lays it out in whole pixels), sidebar 184, top bar 50,
	-- sub-tab bar 32, docked side panel 236 with a 14 px gap. Menu.layout() fills these per build.
	local MENU_W, MENU_H, RAIL_W, HEADER_H, SUBBAR_H, PREVIEW_W = 820, 520, 184, 50, 32, 236
	local PANEL_GAP = 14
	local menuAnimToken = 0
	-- sidebar order. The ids stay what tests and saved state use; TAB_LABEL is what shows.
	local TAB_ORDER = { "Aimbot", "Silent", "Rage", "Visuals", "World", "Skins", "Misc", "Interface", "Config", "Debug" }
	-- an extension page (the Max module): placed before Config, built by Menu.buildPages on every (re)build
	function S.ext.addTab(id: string, label: string, section: string, icon: string, build: any)
		if not table.find(TAB_ORDER, id) then
			table.insert(TAB_ORDER, (table.find(TAB_ORDER, "Config") or #TAB_ORDER + 1), id)
		end
		Menu.TAB_LABEL[id], Menu.TAB_SECTION[id] = label, section
		UI.ICONS[id] = icon
		for i, t in ipairs(S.ext.tabs) do
			if t.id == id then
				table.remove(S.ext.tabs, i)
				break
			end
		end
		table.insert(S.ext.tabs, { id = id, build = build })
	end
	-- an extension sub-tab on a base page (appended after the page's own sub-tabs)
	function S.ext.addSub(tab: string, sub: string)
		local list = S.ext.subs[tab]
		if not list then
			list = {}
			S.ext.subs[tab] = list
		end
		if not table.find(list, sub) then
			table.insert(list, sub)
		end
	end
	-- an extension group on a base page: build(Group, UI, column) runs after the page's own groups on every
	-- (re)build. `id` replaces an earlier registration (a reinjected module). Every row it builds carries
	-- the Max mark and shows in Simple mode.
	function S.ext.addSection(id: string, tab: string, sub: string, side: string, build: any)
		for i, s in ipairs(S.ext.sections) do
			if s.id == id then
				table.remove(S.ext.sections, i)
				break
			end
		end
		table.insert(S.ext.sections, { id = id, tab = tab, sub = sub, side = side, build = build })
	end
	Menu.TAB_LABEL = {
		Aimbot = "Aimbot", Trigger = "Triggerbot", Silent = "Silent aim", Rage = "Ragebot", Visuals = "Players",
		World = "World", Skins = "Skins", Misc = "Misc", Interface = "Interface", Config = "Config", Debug = "Debug",
	}
	Menu.TAB_SECTION = {
		Aimbot = "Combat", Trigger = "Combat", Silent = "Combat", Rage = "Combat",
		Visuals = "Visuals", World = "Visuals", Skins = "Visuals",
		Misc = "Other", Interface = "Other", Config = "Other", Debug = "Other",
	}
	-- the Debug page is in the sidebar only for a licence an admin turned it on for (admin panel → licence →
	-- Debug menu, sent as debugMenu), or a dev inject with no licence session. The page itself is still built
	-- (tests and centerra_state read it).
	function Menu.debugAllowed(): boolean
		local lic = genv().CenterraLicense
		return type(lic) ~= "table" or lic.debugMenu == true
	end
	-- whole-pixel sizes for the current Menu size (UIScale stays exactly 1: a fractional scale put
	-- every 1 px line and every glyph on half pixels — the "pixelated" menu)
	Menu.s = 1
	function Menu.px(n: number): number
		return math.floor(n * Menu.s + 0.5)
	end
	Menu.M_BASE = nil
	function Menu.layout()
		local vs = if Menu.gui then Menu.gui.AbsoluteSize else Vector2.new(1920, 1080)
		if vs.X < 200 or vs.Y < 200 then
			local cam = workspace.CurrentCamera
			vs = if cam then cam.ViewportSize else Vector2.new(1920, 1080)
		end
		-- the chosen size, stepped down until the window (and its side panel) fits the screen
		local want = tonumber(cfg.menuScale) or 1
		local s = 0.9
		for _, step in ipairs({ 1.25, 1.1, 1, 0.9 }) do
			if step <= want + 1e-6 and (820 + 250) * step <= vs.X - 24 and 520 * step <= vs.Y - 24 then
				s = step
				break
			end
		end
		Menu.s = s
		MENU_W, MENU_H = Menu.px(820), Menu.px(520)
		MENU_W -= MENU_W % 2 -- even: a centred window lands on whole pixels
		MENU_H -= MENU_H % 2
		RAIL_W, HEADER_H, SUBBAR_H, PREVIEW_W, PANEL_GAP = Menu.px(184), Menu.px(50), Menu.px(32), Menu.px(236), Menu.px(14)
		-- the kit's metrics follow the size (fonts and every control dimension, rounded)
		Menu.M_BASE = Menu.M_BASE or table.clone(UI.M)
		for k, v in pairs(Menu.M_BASE) do
			if type(v) == "number" and k ~= "descLine" then
				UI.M[k] = if UI.TEXT_KEYS[k] then math.max(UI.TEXT_MIN, Menu.px(v)) else Menu.px(v)
			end
		end
	end
	-- pages that dock a panel beside the window: the hitbox figure or the live ESP preview
	Menu.SIDE_PANEL = { Aimbot = "hitbox", Silent = "hitbox", Rage = "hitbox", Visuals = "preview" }

	function Menu.blur(open: boolean)
		local blur = Lighting:FindFirstChild("CenterraBlur") :: BlurEffect?
		if not cfg.menuBlur or cfg.lowSpec then
			if blur then
				blur.Enabled = false
			end
			return
		end
		if not blur then
			blur = Instance.new("BlurEffect")
			blur.Name = "CenterraBlur"
			blur.Size = 0
			blur.Parent = Lighting
		end
		blur.Enabled = true
		local t = tween(blur, TW_OPEN, { Size = if open then cfg.menuBlurSize else 0 })
		if not open then
			t.Completed:Connect(function()
				if not S.menuOpen and blur then
					blur.Enabled = false
				end
			end)
		end
	end

	-- user scale × auto-fit so the window always fits the viewport with a margin
	local HUD_setEdit: any = nil -- filled by §13 (HUD is built after the menu)
	function Menu.setHudEditHook(fn: any)
		HUD_setEdit = fn
	end
	-- a continuous Quart slide (the resting position stays whole-pixel; only the motion passes through
	-- fractions). `dy` is the offset from `base` at the far end; `fade` (optional) is a frame whose
	-- transparency runs 0 → 1 while opening (1 → 0 closing). `done` runs only when it completes.
	function Menu.slide(obj: GuiObject, base: UDim2, dy: number, dur: number, fade: GuiObject?, closing: boolean?, done: (() -> ())?)
		local info = TweenInfo.new(dur, Enum.EasingStyle.Quart, if closing then Enum.EasingDirection.In else Enum.EasingDirection.Out)
		obj.Position = if closing then base else base + UDim2.fromOffset(0, dy)
		local t: Tween
		if fade then
			fade.BackgroundTransparency = if closing then 1 else 0
			t = TweenService:Create(fade, info, { BackgroundTransparency = if closing then 0 else 1 })
			if dy ~= 0 then
				tween(obj, info, { Position = if closing then base + UDim2.fromOffset(0, dy) else base })
			end
		else
			t = TweenService:Create(obj, info, { Position = if closing then base + UDim2.fromOffset(0, dy) else base })
		end
		t.Completed:Connect(function(state: any)
			if state ~= Enum.PlaybackState.Completed then
				return
			end
			if closing and obj.Parent then
				obj.Position = base
			end
			if done then
				done()
			end
		end)
		t:Play()
	end
	-- ambient motion (the turning edge, the breathing aura, the logo): engine-driven looping tweens that
	-- run only while the menu shows (Menu.set plays / pauses them, Menu.destroy cancels them)
	function Menu.loop(obj: Instance, info: TweenInfo, props: any): Tween
		local t = TweenService:Create(obj, info, props)
		table.insert(Menu.loops, t)
		if S.menuOpen then
			t:Play()
		end
		return t
	end
	function Menu.runLoops(on: boolean)
		for _, t in ipairs(Menu.loops or {}) do
			if on then
				t:Play()
			else
				t:Pause()
			end
		end
	end
	-- the window is one layer stepped at the rail's edge (the hairline sits on the step): the tab list
	-- in an accent-tinted acrylic the game shows through a little (cfg.railGlass), the content solid
	function Menu.applyGlass()
		local g = Menu.glassGrad
		if not g then
			return
		end
		-- metal looks: a solid rail (the design's; the game showing through read as a broken background)
		local railA = if UI.metal then 0 else math.clamp((tonumber(cfg.railGlass) or 14) / 100, 0, 0.4)
		local r = math.clamp(Menu.glassSplit or 0.22, 0.01, 0.98)
		-- metal looks tint the rail with the metal's shadow tone, not the glow colour
		local railTint = if UI.metal then C.side:Lerp(UI.metal.mid, 0.1) else C.side:Lerp(C.accent2, 0.16)
		g.Rotation = 0
		g.Color = ColorSequence.new({
			ColorSequenceKeypoint.new(0, railTint),
			ColorSequenceKeypoint.new(r - 0.002, railTint),
			ColorSequenceKeypoint.new(r, C.bg),
			ColorSequenceKeypoint.new(1, C.bg),
		})
		g.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, railA),
			NumberSequenceKeypoint.new(r - 0.002, railA),
			NumberSequenceKeypoint.new(r, 0),
			NumberSequenceKeypoint.new(1, 0),
		})
	end
	function Menu.ctrlDown(): boolean
		local down = false
		pcall(function()
			down = UIS:IsKeyDown(Enum.KeyCode.LeftControl) or UIS:IsKeyDown(Enum.KeyCode.RightControl)
		end)
		if not down then
			pcall(function()
				for _, pressed in ipairs(UIS:GetKeysPressed()) do
					local code = pressed.KeyCode
					if code == Enum.KeyCode.LeftControl or code == Enum.KeyCode.RightControl then
						down = true
					end
				end
			end)
		end
		if down then
			return true
		end
		-- IsKeyDown stays false on some executors; the key tracker is filled from InputBegan
		local kd = Input.keyDown
		return type(kd) == "table" and (kd.LeftControl == true or kd.RightControl == true)
	end
	function Menu.pressed(kc: any): boolean
		if typeof(kc) ~= "EnumItem" then
			return false
		end
		if (kc :: any) == Enum.KeyCode.O and Menu.ctrlDown() then
			return true
		end
		local mk = cfg.menuKey
		return type(mk) == "string" and mk ~= "" and mk ~= "None" and kc.Name == mk
	end
	function Menu.panic(err: any)
		local msg = string.sub(tostring(err), 1, 90)
		log("ERROR", "menu:", msg)
		notify("menu failed: " .. msg, 8, "error")
	end
	function Menu.toggle()
		do
			local g = genv()
			local L = g.CenterraLibrary
			if type(L) == "table" and type(L.Toggle) == "function" then
				pcall(L.Toggle)
				return
			end
		end
		local now = os.clock()
		if now - (Menu._toggleAt or 0) < 0.2 then
			return
		end
		Menu._toggleAt = now
		if not (Menu.gui and Menu.root and Menu.backdrop and Menu.host) then
			local okB, errB = pcall(Menu.rebuild)
			if not okB then
				Menu.panic(errB)
				return
			end
		end
		local ok, err = pcall(Menu.set, not S.menuOpen)
		if ok then
			return
		end
		if S.hookErr then
			S.hookErr("menu", err)
		end
		local ok2, err2 = pcall(Menu.rebuild)
		if not ok2 then
			Menu.panic(err2)
			return
		end
		pcall(Menu.set, true)
	end
	-- the game keeps running under the menu: no camera freeze. In a duel the camera hook
	-- (Hooks.installMenuMouse) makes RIVALS' own camera free and show the real cursor, so this late render
	-- step (after every camera) finds nothing to write. Where another camera locks it anyway — the hub
	-- runs Roblox's default camera, which pins the mouse to the centre every frame, Modal button or not
	-- (measured) — it puts the cursor back before the frame renders.
	function UI.mouseTick()
		local L = genv().CenterraLibrary
		if type(L) == "table" and L.Toggled == true then
			S.menuOpen = true
		end
		if not S.menuOpen or S.alive == false then
			return
		end
		if UIS.MouseBehavior ~= Enum.MouseBehavior.Default then
			UIS.MouseBehavior = Enum.MouseBehavior.Default
		end
		if not UIS.MouseIconEnabled then
			UIS.MouseIconEnabled = true
		end
	end
	function Menu.set(open: boolean)
		S.menuOpen = open
		S.aimHeld = false
		menuAnimToken += 1
		local token = menuAnimToken
		Menu.blur(open)
		if Menu.mouseFree then
			Menu.mouseFree.Visible = open
		end
		if not (Menu.gui and Menu.root and Menu.backdrop and Menu.host) then
			return
		end
		local host, curtain = Menu.host, Menu.curtain
		-- the resting position (drags and the screen clamp keep it whole-pixel); an animation cut short
		-- by a fast re-toggle restarts from here, never from a mid-slide offset
		Menu.hostBase = Menu.hostBase or host.Position
		local base = Menu.hostBase
		if open then
			if HUD_setEdit then
				HUD_setEdit(false)
			end
			Menu.gui.Enabled = true
			Menu.runLoops(true)
			Menu.backdrop.Visible = true
			Menu.backdrop.BackgroundTransparency = 1
			Menu.root.Visible = true
			host.Visible = true
			if curtain then
				curtain.Visible = true
				curtain.BackgroundTransparency = 0
			end
			UI.mouseTick()
			-- the selection pill and sub-tab thumb measure the laid-out gui: place them once it exists
			Menu.measureSoon(false)
			task.defer(function()
				if token == menuAnimToken then
					Menu.syncNow(Menu.activeTab)
				end
			end)
			-- the content fades in under a curtain of the window's colour; the window itself stays put
			-- (sliding the host re-laid the whole menu out every frame of the open)
			Menu.slide(host, base, 0, TW_OPEN.Time, curtain, false, function()
				if token == menuAnimToken and curtain then
					curtain.Visible = false
				end
				if token == menuAnimToken and S.menuOpen and Menu.clampToScreen then
					Menu.clampToScreen()
				end
			end)
		else
			UI.closeBindPopup()
			UI.closeDropdown()
			-- nothing to restore: the game's camera writes its own cursor state every render step (a
			-- restored snapshot from the moment the menu opened was stale by now — the locked-mouse bugs)
			if curtain then
				curtain.Visible = true
			end
			Menu.slide(host, base, 0, UI.TW.close.Time, curtain, true, function()
				if token == menuAnimToken and not S.menuOpen then
					host.Visible = false
					host.Position = base
					Menu.backdrop.Visible = false
					Menu.gui.Enabled = false
					Menu.runLoops(false)
				end
			end)
		end
	end
	S.setMenu = Menu.set

	-- page / sub-page change: a sheet of the window's colour over the new content lifts away, so the old
	-- content never cuts to the new in one frame; the pill / thumb carry the motion. The page itself
	-- stays put — sliding it re-laid ~1000 elements every frame of the transition (measured: the
	-- "laggy" page change). `dx` / `dy` are accepted and ignored; `cover` = where the sheet starts
	-- (sub-pages keep their tab bar uncovered).
	Menu.revealTw = setmetatable({}, { __mode = "k" })
	function Menu.settle(obj: GuiObject, base: UDim2)
		local t = Menu.revealTw[obj]
		if t then
			t:Cancel()
			Menu.revealTw[obj] = nil
		end
		if obj.Position ~= base then
			obj.Position = base
		end
	end
	function Menu.reveal(obj: GuiObject, base: UDim2, _dx: number, _dy: number, cover: number)
		Menu.settle(obj, base)
		local sheet = Menu.pageCurtain
		if not sheet then
			return
		end
		Menu.revealToken = (Menu.revealToken or 0) + 1
		local token = Menu.revealToken
		sheet.Position = UDim2.fromOffset(0, cover)
		sheet.Size = UDim2.new(1, 0, 1, -cover)
		sheet.BackgroundTransparency = 0.12
		sheet.Visible = true
		tween(sheet, UI.TW.reveal, { BackgroundTransparency = 1 }).Completed:Connect(function(state: any)
			if state == Enum.PlaybackState.Completed and token == Menu.revealToken then
				sheet.Visible = false
			end
		end)
	end
	function Menu.showTab(name: string)
		local was = Menu.activeTab
		Menu.activeTab = name
		UI.closeDropdown()
		local changed = was ~= name
		local animate = changed and was ~= "" and S.menuOpen == true
		local dir = 1
		if animate and (table.find(TAB_ORDER, name) or 0) < (table.find(TAB_ORDER, was) or 0) then
			dir = -1
		end
		for n, page in pairs(Menu.pages) do
			local show = n == name
			if show and animate then
				Menu.reveal(page, UDim2.new(), 0, dir * Menu.px(18), 0)
			elseif changed then
				Menu.settle(page, UDim2.new())
			end
			page.Visible = show
		end
		if Menu.layoutPane then
			Menu.layoutPane(name)
		end
		for n, d in pairs(Menu.tabBtns) do
			if d.paint and (not changed or n == name or n == was or not animate) then
				d.paint(n == name, animate)
			end
		end
		Menu.measureSoon(animate)
		if changed and Menu.syncNow then
			Menu.syncNow(name)
		end
	end
	-- the pill and the thumb read AbsolutePosition: right after a page change that forces a full
	-- synchronous layout of everything just shown. After this frame's render the layout is done and the
	-- read is free — the glide starts one frame later, which nobody sees.
	function Menu.measureSoon(animate: boolean?)
		if Menu.measurePending then
			Menu.measureAnimate = Menu.measureAnimate or animate
			return
		end
		Menu.measurePending = true
		Menu.measureAnimate = animate
		local function run()
			Menu.measurePending = false
			local anim = Menu.measureAnimate
			Menu.measureAnimate = nil
			if Menu.placeNav then
				Menu.placeNav(anim)
			end
			Menu.placeSubThumb(Menu.activeTab, false)
		end
		local ok = pcall(function()
			RunService.Heartbeat:Once(run)
		end)
		if not ok then
			task.defer(run)
		end
	end
	function Menu.placeSubThumb(tab: string, animate: boolean?)
		local st = Menu.subs[tab]
		if not (st and st.liquid and st.track) then
			return
		end
		local b = st.btns[st.active]
		local btn = b and b.btn
		if not (btn and btn.Visible) then
			st.thumb.Visible = false
			return
		end
		local w = btn.AbsoluteSize.X
		if w < 1 then
			return -- not laid out yet: the list's AbsoluteSize signal places it
		end
		st.thumb.Visible = true
		local x = btn.AbsolutePosition.X - st.track.AbsolutePosition.X
		st.liquid.to(x, x + w, animate and S.menuOpen == true)
	end
	function Menu.showSub(tab: string, sub: string)
		local st = Menu.subs[tab]
		if not st then
			return
		end
		UI.closeDropdown()
		local was = st.active
		st.active = sub
		local changed = was ~= sub
		if st.crumb then
			st.crumb.Text = string.lower((Menu.TAB_LABEL[tab] or tab) .. " / " .. sub)
		end
		local animate = changed and st.built == true and S.menuOpen == true and Menu.activeTab == tab
		local dir = 1
		if animate and (table.find(st.order, sub) or 0) < (table.find(st.order, was) or 0) then
			dir = -1
		end
		for n, fr in pairs(st.frames) do
			local show = n == sub
			if show and animate then
				Menu.reveal(fr, st.base, dir * Menu.px(22), 0, st.top)
			elseif changed then
				Menu.settle(fr, st.base)
			end
			fr.Visible = show
		end
		for n, b in pairs(st.btns) do
			local on = n == sub
			local col = if on and UI.metal then UI.metal.ink elseif on then C.text else C.muted
			if animate then
				tween(b.lbl, TW_HOVER, { TextColor3 = col })
			else
				b.lbl.TextColor3 = col
			end
			UI.setFont(b.lbl, if on then UI.F.medium else UI.F.body)
		end
		if animate then
			-- measured after this frame's layout (see Menu.measureSoon)
			local ok = pcall(function()
				RunService.Heartbeat:Once(function()
					Menu.placeSubThumb(tab, true)
				end)
			end)
			if not ok then
				Menu.placeSubThumb(tab, true)
			end
		else
			Menu.placeSubThumb(tab, false)
		end
	end
	-- v5.2 menu pass: a sub-tab whose every group is hidden (Simple mode, or a search) hides its button
	-- too and hands the page to the first sub-tab that still shows something — an empty page with a
	-- bar of dead tabs was the most confusing screen in the menu. Runs after every UI.refilter.
	function Menu.hideEmptySubs()
		-- group frames that still show at least one control (a group of notes alone does not count)
		local live: { [Instance]: boolean } = {}
		for _, g in ipairs(UI.groups) do
			if g.frame.Visible then
				for _, r in ipairs(g.rows) do
					if not r.isNote and r.frame.Visible then
						live[g.frame] = true
						break
					end
				end
			end
		end
		local activeTabVisible = Menu.activeTab == nil
		for tab, st in pairs(Menu.subs or {}) do
			local firstVisible: string? = nil
			local firstOrder = math.huge
			local activeVisible = false
			local tabAny = false
			for sub, fr in pairs(st.frames) do
				local any, nGroups = false, 0
				for _, colName in ipairs({ "L", "R" }) do
					local col = fr:FindFirstChild(colName)
					if col then
						for _, ch in ipairs(col:GetChildren()) do
							if ch:IsA("Frame") then
								nGroups += 1
								if live[ch] then
									any = true
								end
							end
						end
					end
				end
				-- a page built without groups (the Visuals preview pane) is never "empty"
				if nGroups == 0 then
					any = true
				end
				tabAny = tabAny or any
				local b = st.btns[sub]
				local btn = b and b.lbl and b.lbl.Parent
				if btn and btn:IsA("GuiObject") then
					btn.Visible = any
					if any and btn.LayoutOrder < firstOrder then
						firstOrder, firstVisible = btn.LayoutOrder, sub
					end
				elseif any and firstVisible == nil then
					firstVisible = sub
				end
				if any and sub == st.active then
					activeVisible = true
				end
			end
			if not activeVisible and firstVisible then
				Menu.showSub(tab, firstVisible)
			end
			-- the sidebar: a page with nothing left to show (Debug in Simple mode) leaves it
			local tb = Menu.tabBtns and Menu.tabBtns[tab]
			if tb and tb.item then
				tb.item.Visible = tabAny
			end
			if tab == Menu.activeTab and tabAny and (tb ~= nil or tab ~= "Debug") then
				activeTabVisible = true
			end
		end
		-- a section caption with no page left under it goes too
		for sec, cap in pairs(Menu.sectionCaps or {}) do
			local anyItem = false
			for tab, d in pairs(Menu.tabBtns or {}) do
				if Menu.TAB_SECTION[tab] == sec and d.item and d.item.Visible then
					anyItem = true
				end
			end
			cap.Visible = anyItem
		end
		-- the page on screen emptied out (a search, Simple mode): go to the first page that shows something
		if not activeTabVisible and Menu.pages then
			for _, name in ipairs(TAB_ORDER) do
				local tb = Menu.tabBtns and Menu.tabBtns[name]
				if Menu.pages[name] and tb and tb.item and tb.item.Visible then
					Menu.showTab(name)
					break
				end
			end
		end
	end
	UI.afterRefilter = function()
		Menu.hideEmptySubs()
		-- Simple mode empties whole columns: rebalance the two columns for the rows that are visible
		-- NOW (the build-time balance only knew the mode the menu was built in)
		if Menu.balanceColumns then
			Menu.balanceColumns()
		end
		-- a search can hide sidebar items above the active one: the pill follows once the list re-lays
		task.defer(function()
			if Menu.placeNav then
				Menu.placeNav(false)
			end
		end)
	end

	-- page = Frame with a sub-tab bar and one ScrollingFrame (two columns) per sub-tab
	function Menu.addTab(name: string, subs: { string }): any
		local extra = S.ext.subs[name]
		if extra and #extra > 0 then
			local merged = table.clone(subs)
			for _, s in ipairs(extra) do
				if not table.find(merged, s) then
					table.insert(merged, s)
				end
			end
			subs = merged
		end
		table.insert(Menu.syncMarks, { at = #UI.sync + 1, tab = name })
		local content = Menu.content
		local page = frame(content)
		page.Name = "Page_" .. name
		page.Size = UDim2.new(1, 0, 1, 0)
		page.Visible = false
		Menu.pages[name] = page
		S.ui.tabs[name] = page
		S.ui.subTabs[name] = {}
		local multi = #subs > 1
		-- sub-tabs: a segmented control on an acrylic track; the active segment is an accent acrylic
		-- thumb that glides between segments (UI.liquid). The thumb is the track's own child, beside the
		-- laid-out list, so the list layout never moves it.
		local bar = frame(page)
		bar.Name = "SubBar"
		bar.Size = UDim2.new(1, -36, 0, SUBBAR_H)
		bar.Position = UDim2.new(0, 18, 0, 4)
		bar.Visible = multi
		local track = frame(bar, C.surface)
		track.Name = "Track"
		track.AutomaticSize = Enum.AutomaticSize.X
		track.Size = UDim2.new(0, 0, 1, -2)
		track.AnchorPoint = Vector2.new(0, 0.5)
		track.Position = UDim2.new(0, 0, 0.5, 0)
		corner(track, 8)
		stroke(track, C.edge, 0.2)
		-- the active segment: a lighter solid surface with a hairline, the same treatment as the nav selection
		local thumb = frame(track, Color3.new(1, 1, 1))
		thumb.Name = "Thumb"
		thumb.BackgroundTransparency = 0.91
		thumb.ZIndex = 2
		thumb.Visible = false
		corner(thumb, 6)
		stroke(thumb, Color3.new(1, 1, 1), 0.9)
		if UI.brushed(thumb) then
			thumb.BackgroundTransparency = 0
		end
		local list = frame(track)
		list.Name = "Segments"
		list.AutomaticSize = Enum.AutomaticSize.X
		list.Size = UDim2.new(0, 0, 1, 0)
		list.ZIndex = 3
		vlist(list, 2, true)
		padding(list, 3, 3, 3, 3)
		local st: any = { frames = {}, btns = {}, active = subs[1], order = subs, track = track, thumb = thumb }
		Menu.subs[name] = st
		-- where you are, right of the sub-tabs ("players / esp", the design's crumb)
		local crumb = label(bar, "", UI.M.small, C.muted, UI.F.body)
		crumb.Name = "Crumb"
		crumb.AnchorPoint = Vector2.new(1, 0)
		crumb.Position = UDim2.new(1, 0, 0, 0)
		crumb.Size = UDim2.new(0.4, 0, 1, 0)
		crumb.TextXAlignment = Enum.TextXAlignment.Right
		crumb.TextTruncate = Enum.TextTruncate.AtEnd
		st.crumb = crumb
		st.liquid = UI.liquid(thumb, function(a: number, b: number)
			thumb.Position = UDim2.new(0, a, 0, 3)
			thumb.Size = UDim2.new(0, math.max(4, b - a), 1, -6)
		end)
		UI.conn(list:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
			Menu.placeSubThumb(name, false)
		end))
		local top = if multi then SUBBAR_H + 6 else 0
		st.top = top
		st.base = UDim2.new(0, 0, 0, top)
		for i, sub in ipairs(subs) do
			local b = button(list, "", UI.M.value, C.muted, C.surface)
			b.BackgroundTransparency = 1
			b.AutomaticSize = Enum.AutomaticSize.X
			b.Size = UDim2.new(0, 0, 1, 0)
			b.LayoutOrder = i
			b.ZIndex = 3
			local lbl = label(b, string.lower(sub), UI.M.value + 1, C.muted, UI.F.body)
			lbl.Size = UDim2.new(0, 0, 1, 0)
			lbl.AutomaticSize = Enum.AutomaticSize.X
			lbl.TextYAlignment = Enum.TextYAlignment.Center
			lbl.ZIndex = 3
			padding(lbl, 0, Menu.px(12), 0, Menu.px(12))
			-- whole-pixel segments, so the thumb that glides onto them rests on whole pixels
			UI.snapWidth(lbl, Menu.px(12) * 2)
			st.btns[sub] = { lbl = lbl, btn = b }
			b.MouseEnter:Connect(function()
				if st.active ~= sub then
					tween(lbl, TW_HOVER, { TextColor3 = C.dim })
				end
			end)
			b.MouseLeave:Connect(function()
				if st.active ~= sub then
					tween(lbl, TW_HOVER, { TextColor3 = C.muted })
				end
			end)
			b.MouseButton1Click:Connect(function()
				Menu.showSub(name, sub)
			end)
			local scroll = Instance.new("ScrollingFrame")
			scroll.Name = "Sub_" .. sub
			scroll.Size = UDim2.new(1, 0, 1, -top)
			scroll.Position = UDim2.new(0, 0, 0, top)
			scroll.BackgroundTransparency = 1
			scroll.BorderSizePixel = 0
			scroll.ScrollBarThickness = 4
			scroll.ScrollBarImageColor3 = C.faint
			scroll.ScrollBarImageTransparency = 0.1
			scroll.TopImage = "rbxasset://textures/ui/Scroll/scroll-middle.png"
			scroll.BottomImage = "rbxasset://textures/ui/Scroll/scroll-middle.png"
			scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
			scroll.CanvasSize = UDim2.new(0, 0, 0, 0)
			scroll.Visible = i == 1
			scroll.Parent = page
			padding(scroll, 14, 18, 10, 18)
			-- an open dropdown would stay where its control used to be
			scroll:GetPropertyChangedSignal("CanvasPosition"):Connect(UI.closeDropdown)
			-- two columns with a 24 px gutter. Inside a padded ScrollingFrame a child's Size scale is
			-- measured against the full frame while its Position scale is measured against the padded
			-- box (verified on the live GUI): half the padding (36 → 18) and half the gutter (12)
			-- come off each width; the right column starts 12 px past the padded midpoint.
			local left = frame(scroll)
			left.Name = "L"
			left.Size = UDim2.new(0.5, -30, 0, 0)
			left.AutomaticSize = Enum.AutomaticSize.Y
			vlist(left, 0)
			local right = frame(scroll)
			right.Name = "R"
			right.Size = UDim2.new(0.5, -30, 0, 0)
			right.Position = UDim2.new(0.5, 12, 0, 0)
			right.AutomaticSize = Enum.AutomaticSize.Y
			vlist(right, 0)
			st.frames[sub] = scroll
			S.ui.subTabs[name][sub] = scroll
			scroll:SetAttribute("Sub", sub)
			st[sub] = { L = left, R = right, scroll = scroll }
		end
		Menu.showSub(name, subs[1])
		st.built = true
		return st
	end

	-- live ESP preview for the docked panel: a figure drawn with frames and every ESP option on it
	-- the way the in-game ESP draws it (outlined box, health bar coloured by HP, number only when
	-- damaged, name above, weapon below, flags on the right)
	-- the local player's avatar for the preview panels (ESP preview, hitbox figure): one model from the
	-- same UserId as the sidebar headshot, a clone per ViewportFrame. Highlights do not render inside a
	-- viewport, so chams and the hitbox choices paint the parts themselves (UI.avatarTint).
	UI.avatarSlots = {}
	UI.avatarState = "idle" -- idle → loading → ready | failed
	-- CreateHumanoidModelFromUserId hands the rig over unsolved outside the workspace (the head sat 36 st
	-- from the body, the accessories 14 st above it): every part is placed from its joints, outward from the
	-- root, and a part no joint reaches (a head the description swapped in, an accessory without its weld yet)
	-- lines a same-named attachment up with one on a placed part (NeckRigAttachment, HatAttachment, …)
	function UI.avatarAssemble(model: Model)
		local root = model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
		if not (root and root:IsA("BasePart")) then
			return
		end
		local placed = { [root] = true }
		local joints, parts = {}, {}
		for _, d in ipairs(model:GetDescendants()) do
			if d:IsA("JointInstance") and d.Part0 and d.Part1 then
				table.insert(joints, d)
			elseif d:IsA("BasePart") then
				table.insert(parts, d)
			end
		end
		for _ = 1, 12 do
			local moved = false
			for _ = 1, 32 do
				local step = false
				for _, j in ipairs(joints) do
					local p0, p1 = j.Part0, j.Part1
					if placed[p0] and not placed[p1] then
						p1.CFrame = p0.CFrame * j.C0 * j.C1:Inverse()
						placed[p1], step = true, true
					elseif placed[p1] and not placed[p0] then
						p0.CFrame = p1.CFrame * j.C1 * j.C0:Inverse()
						placed[p0], step = true, true
					end
				end
				moved = moved or step
				if not step then
					break
				end
			end
			for _, part in ipairs(parts) do
				if not placed[part] then
					for _, att in ipairs(part:GetChildren()) do
						if att:IsA("Attachment") then
							local mate: Attachment? = nil
							for _, other in ipairs(parts) do
								if placed[other] then
									local a = other:FindFirstChild(att.Name)
									if a and a:IsA("Attachment") then
										mate = a
										break
									end
								end
							end
							if mate then
								part.CFrame = mate.WorldCFrame * att.CFrame:Inverse()
								placed[part], moved = true, true
								break
							end
						end
					end
				end
			end
			if not moved then
				break
			end
		end
	end
	-- a statue for the viewport: no scripts (a LocalScript under PlayerGui would run), anchored, no tag
	function UI.avatarPrepare(model: Model)
		for _, d in ipairs(model:GetDescendants()) do
			if d:IsA("LuaSourceContainer") or d:IsA("ForceField") or d:IsA("Sound") then
				d:Destroy()
			elseif d:IsA("BasePart") then
				d.Anchored = true
				d.CanCollide = false
				d.CastShadow = false
			elseif d:IsA("Humanoid") then
				d.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
				d.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
			end
		end
		local root = model:FindFirstChild("HumanoidRootPart")
		if root and root:IsA("BasePart") then
			model.PrimaryPart = root
		end
		model:PivotTo(CFrame.new())
	end
	function UI.avatarLoad()
		if UI.avatarState ~= "idle" then
			return
		end
		UI.avatarState = "loading"
		task.spawn(function()
			local model: Model? = nil
			local ok, m = pcall(function()
				return Players:CreateHumanoidModelFromUserId(LP.UserId)
			end)
			if ok and typeof(m) == "Instance" and m:IsA("Model") then
				model = m
			else
				-- the character itself, copied (Archivable only for the moment of the copy)
				pcall(function()
					local char = LP.Character
					if char then
						local was = char.Archivable
						char.Archivable = true
						model = char:Clone()
						char.Archivable = was
					end
				end)
			end
			if not model then
				UI.avatarState = "failed"
				log("DEBUG", "preview: no avatar model (" .. tostring(m) .. ")")
				return
			end
			pcall(UI.avatarAssemble, model)
			pcall(UI.avatarPrepare, model)
			UI.avatarModel = model
			UI.avatarState = "ready"
			for _, slot in ipairs(UI.avatarSlots) do
				pcall(UI.avatarFill, slot)
			end
		end)
	end
	-- a viewport over (x, y, w, h) in the parent's pixels, the avatar's body framed to fill `fill` of its
	-- height (0.9 by default); `bodyOnly` leaves the accessories out of the copy
	function UI.avatarViewport(parent: GuiObject, x: number, y: number, w: number, h: number, z: number, opts: any?): any
		local vf = Instance.new("ViewportFrame")
		vf.Name = "Avatar"
		vf.BackgroundTransparency = 1
		vf.Position = UDim2.fromOffset(x, y)
		vf.Size = UDim2.fromOffset(w, h)
		vf.ZIndex = z
		vf.Ambient = Color3.fromRGB(170, 165, 185)
		vf.LightColor = Color3.fromRGB(255, 250, 245)
		vf.LightDirection = Vector3.new(-0.4, -1, -0.6)
		local world = Instance.new("WorldModel")
		world.Parent = vf
		local cam = Instance.new("Camera")
		cam.FieldOfView = 30
		cam.Parent = vf
		vf.CurrentCamera = cam
		vf.Parent = parent
		local slot = { vf = vf, world = world, cam = cam, w = w, h = h, model = nil, orig = {}, clothes = nil, tintSig = nil, onReady = nil, bodyOnly = opts and opts.bodyOnly == true, fill = opts and opts.fill or 0.9 }
		-- a menu rebuild left the old panels' slots behind: drop them
		for i = #UI.avatarSlots, 1, -1 do
			if not UI.avatarSlots[i].vf.Parent then
				table.remove(UI.avatarSlots, i)
			end
		end
		table.insert(UI.avatarSlots, slot)
		if UI.avatarState == "ready" then
			pcall(UI.avatarFill, slot)
		else
			UI.avatarLoad()
		end
		return slot
	end
	function UI.avatarFill(slot: any)
		if slot.model or not slot.vf.Parent or not UI.avatarModel then
			return
		end
		local m = UI.avatarModel:Clone()
		if slot.bodyOnly then
			for _, d in ipairs(m:GetChildren()) do
				if d:IsA("Accoutrement") then
					d:Destroy()
				end
			end
		end
		m.Parent = slot.world
		slot.model = m
		-- framed on the body (a hat or a sword on the back doesn't shrink the figure), from the front
		local lo, hi = Vector3.one * math.huge, Vector3.one * -math.huge
		for _, p in ipairs(UI.avatarBody(m)) do
			for _, c in ipairs(UI.CORNERS) do
				local wp = p.CFrame:PointToWorldSpace(p.Size * 0.5 * c)
				lo, hi = lo:Min(wp), hi:Max(wp)
			end
		end
		local center, size
		if lo.X == math.huge then
			local cf, sz = m:GetBoundingBox()
			center, size = cf.Position, sz
		else
			center, size = (lo + hi) * 0.5, hi - lo
		end
		local t = math.tan(math.rad(slot.cam.FieldOfView) * 0.5)
		local aspect = slot.w / math.max(slot.h, 1)
		local dist = math.max((size.Y * 0.5 / slot.fill) / t, (size.X * 0.5 / 0.96) / (t * aspect)) + size.Z * 0.5
		local root = m:FindFirstChild("HumanoidRootPart")
		local front = if root and root:IsA("BasePart") then root.CFrame.LookVector else m:GetPivot().LookVector
		slot.cam.CFrame = CFrame.lookAt(center + front * dist, center)
		slot.tintSig = nil
		if slot.onReady then
			slot.onReady(slot)
		end
	end
	UI.CORNERS = {
		Vector3.new(-1, -1, -1), Vector3.new(1, -1, -1), Vector3.new(-1, 1, -1), Vector3.new(1, 1, -1),
		Vector3.new(-1, -1, 1), Vector3.new(1, -1, 1), Vector3.new(-1, 1, 1), Vector3.new(1, 1, 1),
	}
	function UI.avatarBody(m: Model): { BasePart }
		local out = {}
		for _, d in ipairs(m:GetDescendants()) do
			if d:IsA("BasePart") and UI.HITBOX_OF[d.Name] and not d:FindFirstAncestorWhichIsA("Accoutrement") then
				table.insert(out, d)
			end
		end
		return out
	end
	-- a world point in the slot's viewport pixels (nil behind the camera)
	function UI.avatarProject(slot: any, p: Vector3): Vector2?
		local q = slot.cam.CFrame:PointToObjectSpace(p)
		if q.Z > -0.05 then
			return nil
		end
		local t = math.tan(math.rad(slot.cam.FieldOfView) * 0.5)
		local aspect = slot.w / math.max(slot.h, 1)
		return Vector2.new((1 + q.X / (-q.Z * t * aspect)) * 0.5 * slot.w, (1 - q.Y / (-q.Z * t)) * 0.5 * slot.h)
	end
	-- the body's rect on the viewport in pixels: x, y, w, h
	function UI.avatarRect(slot: any): (number?, number?, number?, number?)
		if not slot.model then
			return nil, nil, nil, nil
		end
		local x0, y0, x1, y1 = math.huge, math.huge, -math.huge, -math.huge
		for _, p in ipairs(UI.avatarBody(slot.model)) do
			for _, c in ipairs(UI.CORNERS) do
				local s = UI.avatarProject(slot, p.CFrame:PointToWorldSpace(p.Size * 0.5 * c))
				if s then
					x0, y0, x1, y1 = math.min(x0, s.X), math.min(y0, s.Y), math.max(x1, s.X), math.max(y1, s.Y)
				end
			end
		end
		if x0 == math.huge then
			return nil, nil, nil, nil
		end
		return x0, y0, x1 - x0, y1 - y0
	end
	-- part name → the hitbox group the figure's dots edit
	UI.HITBOX_OF = {
		Head = "Head", UpperTorso = "Body", LowerTorso = "Body", Torso = "Body",
		LeftUpperArm = "Arms", LeftLowerArm = "Arms", LeftHand = "Arms", RightUpperArm = "Arms", RightLowerArm = "Arms", RightHand = "Arms", ["Left Arm"] = "Arms", ["Right Arm"] = "Arms",
		LeftUpperLeg = "Legs", LeftLowerLeg = "Legs", LeftFoot = "Legs", RightUpperLeg = "Legs", RightLowerLeg = "Legs", RightFoot = "Legs", ["Left Leg"] = "Legs", ["Right Leg"] = "Legs",
	}
	-- paint the avatar: colorOf(part) → the colour and transparency to show it in, or nil for its real
	-- look. Originals are kept per part (a tint that goes away restores it exactly); clothing and the
	-- face print over paint, so they step out while any part is painted. `sig` skips repeat work.
	function UI.avatarTint(slot: any, sig: string, colorOf: (BasePart) -> (Color3?, number?))
		local m = slot.model
		if not m or slot.tintSig == sig then
			return
		end
		slot.tintSig = sig
		local orig = slot.orig
		local painted = false
		for _, d in ipairs(m:GetDescendants()) do
			if d:IsA("BasePart") and d.Name ~= "HumanoidRootPart" and (if orig[d] then orig[d].tr else d.Transparency) < 0.99 then
				local c, a = colorOf(d)
				local o = orig[d]
				if c then
					if not o then
						o = { color = d.Color, mat = d.Material, tr = d.Transparency, tex = if d:IsA("MeshPart") then d.TextureID else nil }
						orig[d] = o
					end
					d.Color, d.Material, d.Transparency = c, Enum.Material.SmoothPlastic, a or 0
					if d:IsA("MeshPart") then
						d.TextureID = ""
					end
					painted = true
				elseif o then
					d.Color, d.Material, d.Transparency = o.color, o.mat, o.tr
					if o.tex ~= nil and d:IsA("MeshPart") then
						d.TextureID = o.tex
					end
					orig[d] = nil
				end
			elseif d:IsA("Decal") and d.Parent and d.Parent:IsA("BasePart") and d.Parent.Name == "Head" then
				if orig[d] == nil then
					orig[d] = { tr = d.Transparency }
				end
				d.Transparency = if colorOf(d.Parent :: BasePart) then 1 else orig[d].tr
			end
		end
		if painted and not slot.clothes then
			slot.clothes = {}
			for _, d in ipairs(m:GetDescendants()) do
				if d:IsA("Clothing") or d:IsA("ShirtGraphic") or d:IsA("SurfaceAppearance") then
					table.insert(slot.clothes, { d, d.Parent })
				end
			end
			for _, e in ipairs(slot.clothes) do
				pcall(function()
					e[1].Parent = nil
				end)
			end
		elseif not painted and slot.clothes then
			for _, e in ipairs(slot.clothes) do
				if e[2] == m or (e[2] and e[2]:IsDescendantOf(m)) then
					pcall(function()
						e[1].Parent = e[2]
					end)
				end
			end
			slot.clothes = nil
		end
	end
	function Menu.buildPreview(parent: GuiObject)
		local scene = frame(parent)
		scene.Name = "EspPreview"
		scene.Size = UDim2.new(1, 0, 1, 0)
		scene.ClipsDescendants = true
		-- the figure: same geometry as the design mockup (200 × 330 box, scaled 0.62) — your own avatar,
		-- framed into the ESP box so the box, bar, name and flags sit on it the way they sit on a player
		local FX, FY, SC = 38, 58, 0.8
		local shadow = frame(scene, Color3.new(0, 0, 0))
		shadow.Size = UDim2.fromOffset(math.floor(148 * SC), 8)
		shadow.AnchorPoint = Vector2.new(0.5, 0.5)
		shadow.Position = UDim2.fromOffset(FX + 100 * SC, FY + 322 * SC)
		shadow.BackgroundTransparency = 0.55
		corner(shadow, 4)
		-- box geometry (the ESP bounds of the figure): the mockup's body box until the avatar is framed,
		-- then the avatar's own outline, the way the ESP boxes a player
		local BX, BY = math.floor(FX + 38 * SC), math.floor(FY + 20 * SC)
		local BW, BH = math.floor(124 * SC), math.floor(300 * SC)
		local headX, headY = math.floor(FX + 100 * SC), math.floor(FY + 40 * SC)
		local avatar = UI.avatarViewport(scene, FX, FY, math.floor(200 * SC), math.floor(330 * SC), 2, { fill = 300 / 330 })
		local function bar(z: number, color: Color3): Frame
			local f = frame(scene, color)
			f.ZIndex = z
			f.Visible = false
			return f
		end
		local fill = bar(3, Color3.new(1, 1, 1))
		local outlines: { Frame } = {}
		local lines: { Frame } = {}
		for i = 1, 8 do
			outlines[i] = bar(4, Color3.new(0, 0, 0))
			lines[i] = bar(5, Color3.new(1, 1, 1))
		end
		local hpOut, hpFill = bar(4, Color3.new(0, 0, 0)), bar(5, Color3.new(1, 1, 1))
		local headDot = bar(5, Color3.new(1, 1, 1))
		headDot.BackgroundTransparency = 1
		corner(headDot, 100)
		local headStroke = stroke(headDot, Color3.new(1, 1, 1), 0)
		local function txt(size: number, xAlign: any): TextLabel
			local t = label(scene, "", size, Color3.new(1, 1, 1), UI.F.semibold)
			t.ZIndex = 6
			t.TextXAlignment = xAlign
			t.TextStrokeTransparency = 0.15
			t.TextStrokeColor3 = Color3.new(0, 0, 0)
			return t
		end
		local nameT = txt(UI.TEXT_MIN + 1, Enum.TextXAlignment.Center)
		nameT.Text = if LP.DisplayName ~= "" then LP.DisplayName else LP.Name
		local wpT = txt(UI.TEXT_MIN, Enum.TextXAlignment.Center)
		wpT.Text = "Sniper"
		local hpT = txt(UI.TEXT_MIN, Enum.TextXAlignment.Right)
		local flags: { TextLabel } = {}
		for i = 1, 3 do
			flags[i] = txt(UI.TEXT_MIN, Enum.TextXAlignment.Left)
		end
		-- a line segment as a frame: (x, y, w, h), outline 1 px around it
		local function seg(i: number, x: number, y: number, w: number, h: number, color: Color3, outline: boolean)
			local l, o = lines[i], outlines[i]
			l.Visible = true
			l.Position = UDim2.fromOffset(x, y)
			l.Size = UDim2.fromOffset(w, h)
			l.BackgroundColor3 = color
			o.Visible = outline
			o.Position = UDim2.fromOffset(x - 1, y - 1)
			o.Size = UDim2.fromOffset(w + 2, h + 2)
		end
		local function refresh()
			local on = cfg.esp == true
			local color = Vis.col("colEspVisible")
			local chams = on and cfg.espHighlight == true and not cfg.espChamsOccluded
			-- chams paint the avatar with the fill colour at the fill transparency; off shows its real look
			local fillC = Vis.col("colChamsFill")
			local fillA = math.clamp(cfg.espChamsFill, 0, 0.9) * 0.8
			UI.avatarTint(avatar, if chams then ("chams %s %.2f"):format(tostring(fillC), fillA) else "real", function(_p: BasePart)
				if chams then
					return fillC, fillA
				end
				return nil, nil
			end)
			for i = 1, 8 do
				lines[i].Visible, outlines[i].Visible = false, false
			end
			local box = on and cfg.espBox == true
			local outline = cfg.espOutline ~= false
			fill.Visible = box and cfg.espBoxFill == true
			fill.Position, fill.Size = UDim2.fromOffset(BX, BY), UDim2.fromOffset(BW, BH)
			fill.BackgroundColor3 = color
			fill.BackgroundTransparency = cfg.espBoxFillAlpha
			if box and cfg.espBoxStyle == "Corner" then
				local L = math.floor(math.min(BW, BH) * 0.25)
				seg(1, BX, BY, L, 1, color, outline)
				seg(2, BX, BY, 1, L, color, outline)
				seg(3, BX + BW - L, BY, L, 1, color, outline)
				seg(4, BX + BW - 1, BY, 1, L, color, outline)
				seg(5, BX, BY + BH - 1, L, 1, color, outline)
				seg(6, BX, BY + BH - L, 1, L, color, outline)
				seg(7, BX + BW - L, BY + BH - 1, L, 1, color, outline)
				seg(8, BX + BW - 1, BY + BH - L, 1, L, color, outline)
			elseif box then
				seg(1, BX, BY, BW, 1, color, outline)
				seg(2, BX, BY + BH - 1, BW, 1, color, outline)
				seg(3, BX, BY, 1, BH, color, outline)
				seg(4, BX + BW - 1, BY, 1, BH, color, outline)
			end
			local hp = math.clamp((tonumber(cfg.previewHp) or 72) / 100, 0.01, 1)
			local showBar = on and cfg.espHealthBar == true
			hpOut.Visible, hpFill.Visible = showBar, showBar
			hpOut.Position, hpOut.Size = UDim2.fromOffset(BX - 7, BY - 1), UDim2.fromOffset(4, BH + 2)
			local fh = math.max(1, math.floor(BH * hp + 0.5))
			hpFill.Position, hpFill.Size = UDim2.fromOffset(BX - 6, BY + BH - fh), UDim2.fromOffset(2, fh)
			hpFill.BackgroundColor3 = Vis.hpColor(hp)
			local mode = cfg.espHpMode or "When damaged"
			hpT.Visible = showBar and (mode == "Always" or (mode == "When damaged" and hp < 1))
			hpT.Text = tostring(math.floor(hp * 100 + 0.5))
			hpT.Size = UDim2.fromOffset(30, 12)
			hpT.Position = UDim2.fromOffset(BX - 40, BY + BH - fh - 4)
			headDot.Visible = on and cfg.espHeadDot == true
			headDot.Size = UDim2.fromOffset(12, 12)
			headDot.Position = UDim2.fromOffset(headX - 6, headY - 6)
			headStroke.Color = color
			local textColor = Vis.col("colText")
			nameT.Visible = on and cfg.espNames == true
			nameT.TextColor3 = textColor
			nameT.Size = UDim2.fromOffset(BW + 60, 14)
			nameT.Position = UDim2.fromOffset(BX - 30, BY - 18)
			wpT.Visible = on and cfg.espWeapon == true
			wpT.TextColor3 = textColor
			wpT.Size = UDim2.fromOffset(BW + 40, 12)
			wpT.Position = UDim2.fromOffset(BX - 20, BY + BH + 4)
			local fl = {}
			if on and cfg.espDistance then
				table.insert(fl, { "24m", textColor:Lerp(Vis.FLAG_DIM, 0.4) })
			end
			if on and cfg.espFlags ~= false then
				table.insert(fl, { "AA", color })
				table.insert(fl, { "LAG", Vis.TAG_COLOR })
			end
			for i = 1, 3 do
				local e = fl[i]
				flags[i].Visible = e ~= nil
				if e then
					flags[i].Text = e[1]
					flags[i].TextColor3 = e[2]
					flags[i].Size = UDim2.fromOffset(40, 12)
					flags[i].Position = UDim2.fromOffset(BX + BW + 5, BY + (i - 1) * 12)
				end
			end
		end
		table.insert(UI.sync, function()
			if Menu.activeTab == "Visuals" and ((Menu.panel and Menu.panel.Visible) or parent.Visible) then
				refresh()
			end
		end)
		local function place()
			local x, y, w, h = UI.avatarRect(avatar)
			if not (x and y and w and h) then
				return
			end
			BX, BY = math.floor(FX + x) - 2, math.floor(FY + y) - 2
			BW, BH = math.ceil(w) + 4, math.ceil(h) + 4
			local head = avatar.model and avatar.model:FindFirstChild("Head")
			local hp = if head and head:IsA("BasePart") then UI.avatarProject(avatar, head.Position) else nil
			if hp then
				headX, headY = math.floor(FX + hp.X + 0.5), math.floor(FY + hp.Y + 0.5)
			end
			shadow.Position = UDim2.fromOffset(BX + math.floor(BW / 2), BY + BH - 1)
		end
		avatar.onReady = function()
			place()
			refresh()
		end
		if avatar.model then
			place()
		end
		refresh()
	end

	-- the hitbox figure for the docked panel: a dot per hitbox, click to enable / disable it (the
	-- preferred one always stays on and carries a ring). Which set it edits follows the page.
	Menu.hitboxSet = "Silent"
	function Menu.hitboxKeys(): (string, string)
		if Menu.hitboxSet == "Aimbot" then
			return "aimHitboxes", "aimPrefer"
		end
		return "silentHitboxes", "silentPrefer"
	end
	function Menu.buildHitboxPanel(parent: GuiObject)
		local SC = 0.9
		local fig = frame(parent)
		fig.Name = "HitboxFigure"
		local FW, FH = math.floor(200 * SC), math.floor(330 * SC)
		fig.Size = UDim2.fromOffset(FW, FH)
		fig.AnchorPoint = Vector2.new(0.5, 0.5)
		fig.Position = UDim2.fromScale(0.5, 0.5)
		-- your own avatar, body only, over the whole figure. Each dot sits on the part it stands for once the
		-- avatar is framed (the mockup's spots until then); the avatar faces you, so its right arm is on the left
		local avatar = UI.avatarViewport(fig, 0, 0, FW, FH, 2, { bodyOnly = true, fill = 0.92 })
		local DOTS = {
			{ "Head", 100, 40, { { "Head", 0 } } },
			{ "Body", 100, 102, { { "UpperTorso", 0 }, { "Torso", 0.45 } } },
			{ "Body", 100, 146, { { "LowerTorso", 0 }, { "Torso", -0.55 } } },
			{ "Arms", 47, 188, { { "RightLowerArm", 0 }, { "Right Arm", -0.3 } } },
			{ "Arms", 153, 188, { { "LeftLowerArm", 0 }, { "Left Arm", -0.3 } } },
			{ "Legs", 86, 262, { { "RightLowerLeg", 0 }, { "Right Leg", -0.4 } } },
			{ "Legs", 114, 262, { { "LeftLowerLeg", 0 }, { "Left Leg", -0.4 } } },
		}
		local recs = {}
		local function place()
			local m = avatar.model
			if not m then
				return
			end
			for _, rec in ipairs(recs) do
				for _, a in ipairs(rec.anchors) do
					local p = m:FindFirstChild(a[1])
					if p and p:IsA("BasePart") then
						local s = UI.avatarProject(avatar, p.Position + Vector3.new(0, a[2], 0))
						if s then
							rec.hit.Position = UDim2.fromOffset(math.floor(s.X + 0.5), math.floor(s.Y + 0.5))
						end
						break
					end
				end
			end
		end
		local OFF_TINT = Color3.fromRGB(42, 40, 50)
		local function paint()
			local setKey, prefKey = Menu.hitboxKeys()
			local set = if type(cfg[setKey]) == "table" then cfg[setKey] else {}
			for _, rec in ipairs(recs) do
				local on = set[rec.part] == true
				rec.dot.Visible = on
				rec.off.Visible = not on
				rec.glow.ImageTransparency = if on then UI.glowAlpha(1.1) else 1
				rec.glow:SetAttribute("glowOff", not on)
				rec.ring.Visible = cfg[prefKey] == rec.part
			end
			-- the hitboxes that are on light up in the accent colour, the rest of the body stays dark
			local accent = C.accent
			local sig = ("%s %s %s %s %s %s"):format(setKey, tostring(set.Head), tostring(set.Body), tostring(set.Arms), tostring(set.Legs), tostring(accent))
			UI.avatarTint(avatar, sig, function(p: BasePart)
				local grp = UI.HITBOX_OF[p.Name]
				if grp and set[grp] == true then
					return accent, 0.1
				end
				return OFF_TINT, 0
			end)
		end
		avatar.onReady = function()
			place()
			paint()
		end
		for _, d in ipairs(DOTS) do
			local hit = button(fig, "", UI.TEXT_MIN, C.text, C.bg)
			hit.BackgroundTransparency = 1
			hit.Size = UDim2.fromOffset(24, 24)
			hit.AnchorPoint = Vector2.new(0.5, 0.5)
			hit.Position = UDim2.fromOffset(math.floor(d[2] * SC), math.floor(d[3] * SC))
			hit.ZIndex = 5
			local glow = UI.glow(hit, 0, 1)
			glow.Size = UDim2.fromOffset(24, 24)
			glow.SliceScale = 0.12
			glow.ZIndex = 5
			local ring = frame(hit)
			ring.Size = UDim2.fromOffset(19, 19)
			ring.AnchorPoint = Vector2.new(0.5, 0.5)
			ring.Position = UDim2.fromScale(0.5, 0.5)
			ring.ZIndex = 6
			corner(ring, 10)
			stroke(ring, C.accent, 0.4)
			local dot = frame(hit, C.accent)
			dot.Size = UDim2.fromOffset(11, 11)
			dot.AnchorPoint = Vector2.new(0.5, 0.5)
			dot.Position = UDim2.fromScale(0.5, 0.5)
			dot.ZIndex = 7
			corner(dot, 6)
			local core = frame(dot, Color3.new(1, 1, 1))
			core.Size = UDim2.fromOffset(4, 4)
			core.AnchorPoint = Vector2.new(0.5, 0.5)
			core.Position = UDim2.fromScale(0.5, 0.5)
			core.ZIndex = 8
			corner(core, 2)
			local off = frame(hit, C.bg)
			off.Size = UDim2.fromOffset(9, 9)
			off.AnchorPoint = Vector2.new(0.5, 0.5)
			off.Position = UDim2.fromScale(0.5, 0.5)
			off.ZIndex = 7
			corner(off, 5)
			local offStroke = stroke(off, C.muted, 0)
			offStroke.Thickness = 1.5
			table.insert(recs, { part = d[1], ring = ring, glow = glow, dot = dot, off = off, hit = hit, anchors = d[4] })
			UI.tip(hit, d[1])
			hit.MouseEnter:Connect(function()
				offStroke.Color = C.accent
			end)
			hit.MouseLeave:Connect(function()
				offStroke.Color = C.muted
			end)
			hit.MouseButton1Click:Connect(function()
				local setKey, prefKey = Menu.hitboxKeys()
				if type(cfg[setKey]) ~= "table" then
					cfg[setKey] = {}
				end
				if cfg[prefKey] == d[1] then
					notify(d[1] .. " is the preferred hitbox, so it stays on", 2, "info")
					return
				end
				cfg[setKey][d[1]] = if cfg[setKey][d[1]] then nil else true
				sanitize(cfg)
				saveConfig()
				paint()
			end)
		end
		Menu.paintHitboxes = paint
		table.insert(UI.sync, function()
			if Menu.panel and Menu.panel.Visible then
				paint()
			end
		end)
		if avatar.model then
			place()
		end
		paint()
	end

	---------------------------------------------------------------------------
	-- pages
	---------------------------------------------------------------------------
	function Menu.buildPages()
		local function G(colFrame: GuiObject, title: string, opts: any?)
			return UI.group(colFrame, title, opts)
		end
		local function int(n: number): string
			return tostring(math.floor(n + 0.5))
		end
		local function one(n: number): string
			return ("%.1f"):format(n)
		end
		local function mult(n: number): string
			return ("×%.2f"):format(n)
		end
		-- Aimbot ---------------------------------------------------------------
		do
			local t = Menu.addTab("Aimbot", { "Aim", "Triggerbot", "Weapon", "Movement" })
			Menu.aimTab = t
			local a = t.Aim
			local g = G(a.L, "Aimbot")
			-- legit aim: the real camera only (no silent aim, no spoof, no teleport). The three-line button
			-- on each row holds its tuning.
			g:toggle("Aimbot", "aimbot", { desc = "Turns your real camera toward the target while you hold the aim key. No silent aim, nothing teleports.", sub = function(sg)
				sg:keybind("Aim key", "aimKey", { desc = "Any key or mouse button, Mouse 4 and 5 included." })
				sg:slider("FOV radius", "aimFov", 20, 1000, 5, { unit = "px", fmt = int, desc = "The aimbot's circle on your screen. Silent aim has its own circle on the Silent aim tab." })
				sg:slider("Smoothing", "aimSmooth", 1, 40, 1, { fmt = int, desc = "1 snaps. 4–8 turns like a hand; it never turns faster than 900°/s divided by this." })
				sg:slider("Pull strength", "aimStrength", 5, 100, 5, { unit = "%", fmt = int, desc = "How hard it pulls your aim toward the target. 100 % does the whole turn; lower leaves part of it to your hand, which looks more human." })
				sg:toggle("Only while moving the mouse", "aimOnlyMoving", { advanced = true, desc = "Pulls only while you move your mouse, so a still hand never drifts onto someone." })
				sg:slider("Aim point randomness", "aimHumanize", 0, 3, 0.1, { advanced = true, unit = "st", fmt = function(n)
					return ("%.1f"):format(n)
				end, desc = "The aim drifts slowly around the point instead of sitting dead on it. 0.3–0.8 looks human." })
				sg:slider("Reaction", "aimReactionMs", 0, 500, 10, { unit = "ms", fmt = int, desc = "A new target is only followed after this long on it." })
				sg:toggle("Adaptive smoothing", "aimDynamic", { desc = "A little faster on close targets, never a flick." })
			end })
			g:toggle("Team check", "teamCheck")
			g:toggle("Aim anywhere (ignore the circle)", "aimFov360", { desc = "Picks targets all around you instead of only inside the circle." })
			local gt = G(a.R, "Targeting")
			gt:cycle("Priority", "targetPriority", { "Crosshair", "Closest", "LowestHP", "Threat" }, { fmt = function(v)
				return if v == "LowestHP" then "Lowest HP" else tostring(v)
			end, desc = "Who gets picked when several enemies qualify. Shared with silent aim." })
			gt:toggle("Prefer threats", "threatPriority", { desc = "Favors enemies who are aiming at you." })
			gt:slider("Switch delay", "targetSwitchMs", 0, 1000, 25, { unit = "ms", fmt = int, desc = "A new target is kept at least this long before another one may take the lock. Stops the aim, silent aim and the ragebot from jumping between enemies in a crowd. A target that dies or leaves the circle is dropped at once. Shared with silent aim and the ragebot." })
			gt:toggle("Sticky aim", "stickyAim", { desc = "Keeps the locked target until it dies, leaves your screen or goes out of range, even outside the circle. Silent aim with a circle never keeps a lock outside it. Shared with the ragebot." })
			local go = G(a.R, "Overlay")
			go:toggle("FOV circle", "showFov")
			go:toggle("Crosshair", "crosshair", { desc = "RIVALS already draws one. This adds ours on top." })

			local w = t.Weapon
			local gw = G(w.L, "Weapon")
			-- one switch drives the client stat zeroing, the straightened rays, the server-side aim
			-- claim and the still shot (sanitize derives the other three from it)
			gw:toggle("No spread", "noSpread", { desc = "Every shot goes exactly where you aim.", onChange = function(v)
				cfg.noSpreadStraighten, cfg.spreadClaimAim, cfg.spreadStillShot = v == true, v == true, v == true
				Combat.applyWeaponStats(true)
			end })
			gw:toggle("No recoil", "noRecoil")
			gw:toggle("Rapid fire", "rapidFire", { danger = "SERVER-CHECKED", desc = "Your guns fire at the speed below on your screen, shotguns and snipers included. Only the rounds this server accepts are sent (learned per weapon), so none get rejected; the rest are shown to you only." })
			gw:slider("Fire speed", "rapidFireMult", 0.05, 1, 0.05, { fmt = mult, typeMin = 0.01, desc = "The cooldown between rounds on your screen: ×0.50 fires twice as fast, ×0.05 twenty times as fast. The server keeps its own pace (Server gets, below)." })
			gw:toggle("Full auto", "fullAuto", { desc = "Semi-auto guns (Handgun, Revolver, Sniper, Shotgun, Crossbow, Flare Gun) keep firing while you hold the trigger, at each gun's own fire rate. Works with Rapid fire.", onChange = function()
				Combat.applyWeaponStats(true)
			end })
			gw:toggle("Only send what the server accepts", "rapidThrottle", { desc = "On: rounds faster than the server's limit stay on your screen, so the server never rejects one. Off: every round is sent and the extra ones are dropped by the server (no extra damage)." })
			gw:info("Server gets", function(): string
				local wname = tostring((S.gameState or {}).weapon or "")
				local info = wname ~= "" and S.itemLibrary and S.itemLibrary.Items and S.itemLibrary.Items[wname]
				if type(info) == "table" and info.Type == "Melee" then
					if not cfg.rapidMelee then
						return "rapid melee is off"
					end
					return ("×%.2f · swing limit"):format(math.clamp(tonumber(cfg.rapidFloorMelee[wname]) or cfg.rapidMeleeServer, 0.1, 1))
				end
				if not cfg.rapidFire then
					return "rapid fire is off"
				end
				if type(info) ~= "table" or info.Type ~= "Gun" then
					return "hold a gun"
				end
				return ("×%.2f · %s"):format(Combat.rapidServerMult(wname), if cfg.rapidFloorSafe[wname] then "learned" else "default")
			end)
			gw:info("Rounds", function(): string
				local fs = Combat.fireStats
				return ("%d sent · %d on screen only"):format(fs.sent, fs.client)
			end)
			gw:button("Measure this gun's limit", function()
				Combat.rapidCalibrate((S.gameState or {}).weapon)
			end, C.accent, { desc = "In the shooting range: hold the gun and keep shooting a dummy. It steps the server's pace from ×1.00 down, 30 rounds per step, and saves the fastest rate the server answered every round of." })
			gw:toggle("Fast equip", "fastEquip")
			gw:slider("Equip time", "fastEquipMult", 0.01, 1, 0.02, { fmt = mult })
			gw:toggle("Fast ADS", "fastAim")
			gw:slider("ADS speed", "fastAimMult", 1, 30, 0.1, { fmt = function(n)
				return ("×%.1f"):format(n)
			end })
			gw:toggle("Instant projectiles", "instantBullet", { desc = "Projectile weapons hit instantly with no drop." })
			local grl = G(w.R, "Reload")
			grl:toggle("Instant reload", "instantReload", { desc = "Your gun is ready the moment the server puts the new mag in, skipping the rest of the reload animation. Measured: Shorty 2.9 → 1.9 s, Assault Rifle 3.0 → 1.6 s, Sniper 2.8 → 1.8 s; guns with a short tail (Wildcat, Exogun) gain little. Shotguns: after the last shell. The server's own refill time can't be changed." })
			grl:toggle("Auto reload", "autoReload", { desc = "Reloads an empty gun when nothing is locked." })
			grl:slider("Reload early below", "reloadEarly", 0, 90, 5, { fmt = function(n)
				return if n <= 0 then "Off" else ("%d %%"):format(n)
			end, desc = "Tops the mag up once it is under this share and nobody is locked or in sight (after a short pause in firing), so the next fight starts on a full mag." })
			grl:toggle("Don't cancel reloads", "noReloadCancel", { desc = "Auto shoot never interrupts a reload." })
			grl:toggle("Switch when empty", "autoSwitchEmpty", { advanced = true, desc = "When the mag runs out mid-fight, swaps once to a loaded gun. Switch back to the empty one and it reloads instead of swapping again; with nothing loaded to swap to, it reloads." })
			local gwt = G(w.R, "Melee speed")
			gwt:toggle("Rapid melee", "rapidMelee", { danger = "SERVER-CHECKED", desc = "Every blade swings faster, your own clicks included (heavy attacks too). Swings reach the server no faster than the limit below; the rest are shown to you only." })
			gwt:slider("Swing speed", "rapidMeleeMult", 0.05, 1, 0.05, { fmt = mult, typeMin = 0.01, desc = "The swing cooldown on your screen: ×0.30 swings about three times as fast." })
			gwt:slider("Server swing limit", "rapidMeleeServer", 0.1, 1, 0.05, { safe = { 0.3, 1 }, safeText = "Below ×0.30 the server starts dropping swings (Knife, measured in the range).", fmt = mult, desc = "How fast swings are sent. ×0.30 = 4.5 Knife swings a second, all accepted." })

			local m = t.Movement
			local gm = G(m.L, "Movement")
			gm:toggle("Infinite slide", "infSlide", { danger = "EXPERIMENTAL" })
			gm:toggle("Infinite sprint", "infSprint", { danger = "EXPERIMENTAL" })
			gm:toggle("No ADS slowdown", "noAdsSlow", { danger = "EXPERIMENTAL", desc = "Aiming keeps the speed you had before (sprint included)." })
			gm:toggle("No slowdowns", "noSlow", { danger = "EXPERIMENTAL", desc = "Freeze Ray and Permafrost slows, the Minigun's spin-up and heavy-weapon walk penalties (Minigun, Grenade Launcher…) no longer slow you. A full freeze keeps your last speed." })
			gm:toggle("Speed boost", "speedBoost", { danger = "SERVER-CHECKED", desc = "Multiplies the game's own walk speed every frame: sprinting, crouching, unarmed or holding any weapon." })
			gm:slider("Walk speed", "speedMult", 1, 10, 0.05, { safe = { 1, 1.25 }, safeText = "Past ×1.25 the server may pull you back now and then; it's your call.", fmt = mult })
			local gm2 = G(m.R, "Automation")
			gm2:toggle("Auto slide", "autoSlide", { danger = "EXPERIMENTAL", desc = "Slides automatically while you sprint." })
			gm2:keybind("Slide key", "slideKey")
			gm2:toggle("Bunny hop", "bhop", { danger = "EXPERIMENTAL", desc = "Hold Space." })
		end

		-- Triggerbot (v6.4: a sub-tab of Aimbot; independent of the aimbot switch) --------
		do
			local tb = Menu.aimTab.Triggerbot
			local gtb = G(tb.L, "Triggerbot", { simple = true })
			gtb:toggle("Triggerbot", "legitTrigger", { desc = "Fires while your own crosshair sits on a visible enemy. Your aim decides: no silent aim, nothing teleports. Snipers only fire scoped." })
			gtb:cycle("Mode", "legitTriggerMode", { "Always", "Hold key" }, { desc = "Always, or only while you hold the trigger key." })
			gtb:keybind("Trigger key", "legitTriggerKey", { desc = "Held in \"Hold key\" mode. Right mouse (aiming down sights) by default." })
			gtb:cycle("Hitbox", "legitTriggerHitbox", { "Any", "Head", "Body" }, { desc = "Which part under your crosshair counts. Head only is the most legit-looking." })
			local gtt = G(tb.R, "Timing", { simple = true })
			gtt:slider("Delay", "legitTriggerDelayMs", 0, 500, 10, { unit = "ms", fmt = int, desc = "How long the crosshair has to be on them first. 80–150 ms reads as a human reaction." })
			gtt:slider("Hit chance", "legitTriggerChance", 5, 100, 5, { unit = "%", fmt = int, desc = "Of the times your crosshair lands on someone, how often it fires." })
			gtt:slider("Max distance", "legitTriggerMaxDist", 10, 1000, 10, { advanced = true, unit = "st", fmt = int, desc = "Never fires at anyone farther than this." })
			gtt:toggle("Only while standing still", "legitTriggerStill", { advanced = true, desc = "Fires only while you are not moving: more accurate, and it looks like you stopped to aim." })
			gtt:info("Status", function()
				local L = Combat.lt
				if not cfg.legitTrigger then
					return "off"
				end
				if L.fighter then
					return ("on %s%s"):format(Game.fighterName(L.fighter), if L.why then " · " .. L.why else "")
				end
				return L.why or "waiting for a target under the crosshair"
			end)
		end

		-- Silent -----------------------------------------------------------------
		do
			local t = Menu.addTab("Silent", { "General", "Auto shoot" })
			local s = t.General
			local gs = G(s.L, "Silent aim")
			gs:toggle("Silent aim", "silentAim", { desc = "Shots hit the target without moving your camera." })
			gs:slider("FOV radius", "silentFov", 20, 1500, 10, { unit = "px", fmt = int, desc = "The circle on your screen. Silent aim and auto shoot only lock enemies inside it. The aimbot has its own circle (Aimbot tab)." })
			gs:slider("Silent hit chance", "silentHitChance", 0, 100, 5, { unit = "%", fmt = int, desc = "How many of your shots silent aim guides. The rest go exactly where you aim. 60–80 % feels like a good player instead of a lock." })
			gs:toggle("Only while firing", "silentOnlyFiring", { desc = "Keeps the lock off until you shoot. Off keeps the lock all the time." })
			gs:toggle("Lock anywhere (ignore the circle)", "silentFov360", { desc = "Locks enemies all around you, not only inside the circle. The ragebot does this by itself while a positioning mode is on." })
			gs:toggle("Hit what's in the circle", "silentFovFallback", { desc = "With the circle, the shot goes to the part of them that is inside it: your hitbox when it is in the circle, otherwise the exposed part nearest your crosshair (their feet in the circle → a body hit, never a head outside it). Off: only your ticked hitboxes count, and no shot when none is in the circle. Rage and lock anywhere are not affected." })
			gs:slider("Max distance", "targetMaxDistance", 50, 5000, 50, { unit = "st", fmt = int, desc = "No lock beyond this. Maps are smaller than 300 studs." })
			local gld = G(s.R, "Accuracy")
			gld:cycle("Lead moving targets", "leadMode", { "Auto", "Off", "Manual" }, { desc = "Aims slightly ahead of fast-moving enemies. Auto learns what lands." })
			gld:slider("Manual lead", "leadMs", 0, 400, 10, { unit = "ms", fmt = int })
			gld:toggle("Dynamic hitbox", "dynamicHitbox", { desc = "Switches to the body when your weapon's spread makes the head hard to hit." })
			gld:slider("Body aim delay", "bodyAimHoldMs", 0, 1000, 10, { unit = "ms", fmt = int, desc = "How long the head must stay covered before the aim moves to another hitbox." })
			gld:toggle("Rotation step fix", "quantAware", { advanced = true, desc = "The server rounds your aim to 1.4° steps: aims where that rounding lands, and takes the body when the head is smaller than one step." })
			gld:toggle("Hold redirect while settling", "silentSettleGateShots", { advanced = true, desc = "After a teleport, your own clicks aren't redirected until the server has you at the new spot either (off: only auto shoot waits)." })
			gld:toggle("Wallbang", "silentWallbang", { danger = "SERVER-CHECKED", desc = "Shoots through a wall in front of you without moving you: the bullet starts just past the wall on the same line. Works on walls close to you; it learns how far this server lets a bullet start ahead of you.", sub = function(sg)
				sg:slider("Max distance", "silentWallbangDist", 1, 25, 0.5, { unit = "st", fmt = function(n)
					return ("%.1f"):format(n)
				end, desc = "How far ahead of your head a bullet may start. Farther reaches more walls; the server refuses rounds that start too far, and the limit drops by itself when it does." })
			end })
			gld:toggle("Counter under-map desync", "antiUnder", { desc = "Someone parked inside the floor (under you or anyone else) can hit you but you can't hit them. This starts your bullet inside the floor too, so it reaches them. Magic bullet, autokill and the melee ragebot stand on the floor right over them for it. Picks them first and flags them UNDER.", sub = function(sg)
				sg:slider("Reach into floor", "antiUnderDist", 3, 14, 0.5, { unit = "st", fmt = function(n)
					return ("%.1f"):format(n)
				end, desc = "How far below your head the bullet may start. Lowers itself if the server refuses." })
			end })

			local asL, asR = t["Auto shoot"].L, t["Auto shoot"].R
			local ga = G(asL, "Auto shoot")
			ga:toggle("Auto shoot", "autoShoot", { desc = "Fires as soon as a locked target is in the open." })
			ga:toggle("Hold trigger", "autoShootHold", { desc = "Holds the trigger instead of tapping." })
			ga:slider("Tap delay", "autoShootDelay", 0.05, 1, 0.01, { unit = "s" })
			ga:slider("Reaction time", "autoShootReactionMs", 0, 200, 5, { unit = "ms", fmt = int })
			ga:slider("Shot chance", "autoShootChance", 10, 100, 5, { unit = "%", fmt = int, safe = { 100, 100 }, safeText = "Below 100 % auto shoot skips shots on purpose.", desc = "A humanizer: the chance each shot is taken. Keep 100 for rage." })
			ga:slider("Min hit chance", "autoShootMinHitChance", 0, 100, 5, { unit = "%", fmt = int, desc = "Fires only when the spread still gives at least this chance to hit. 0 always fires." })
			ga:toggle("Pre-aim", "preAim", { desc = "Faces locked targets in range before you can see them. Other players can notice." })
			ga:slider("Pre-aim range", "preAimRange", 10, 400, 5, { unit = "st", fmt = int })
			local gg = G(asR, "Hold fire when")
			gg:toggle("Target is dead", "autoShootHealthCheck", { desc = "Stops the moment the target dies." })
			gg:toggle("One shot already kills", "killConfirmHold", { desc = "Waits for the server before firing into a target your last shot kills." })
			gg:toggle("Target is leaving cover", "oneShotSafety", { desc = "Snipers and one-shot guns wait while the target is about to break line of sight." })
			gg:toggle("Target is spawn-protected", "immuneCheck")
			gg:toggle("Target is behind cover", "rageAutoShootVisible", { desc = "Uses the line of sight the server checks, from where your shot really leaves — after a teleport too." })
			gg:toggle("Scope is not in yet", "autoShootWaitAim", { desc = "Weapons on real aim (snipers by default) wait until fully scoped." })
			gg:toggle("Scope in automatically", "autoShootScopeSnipers", { desc = "Aims down sights before each shot of a weapon on real aim." })
			local gsa = G(asR, "Auto stop and aim")
			gsa:cycle("Auto stop", "autoShootStopMode", { "Off", "Per shot", "While firing", "Whenever locked" }, { desc = "Stands still for the shot so movement spread doesn't apply.", onChange = function()
				sanitize(cfg)
			end })
			gsa:slider("Stop early by", "autoShootStopLeadMs", 30, 400, 10, { unit = "ms", fmt = int })
			gsa:cycle("Auto aim", "autoShootAimMode", { "Off", "ADS", "Camera", "ADS + Camera" }, { desc = "ADS aims down sights while a target is locked. Camera turns your view onto it.", onChange = function()
				sanitize(cfg)
			end })
			gsa:slider("Release ADS after", "autoShootAdsRelease", 0, 3, 0.1, { unit = "s", fmt = one })
		end

		-- Ragebot ------------------------------------------------------------------
		-- General picks the ONE way the body moves for a lock (the other pages tune each way); every
		-- teleport goes through Body and the safe-spot check whatever is picked
		do
			local t = Menu.addTab("Rage", { "General", "Magic bullet", "Autokill", "Melee", "Defense", "Anti-aim" })
			Menu.rageTab = t
			-- a positioning switch (magic / autokill / peek) is one mode: turning one on picks it
			local function positionToggle(mode: string)
				return function(v: boolean)
					cfg.ragePosition = if v then mode elseif cfg.ragePosition == mode then "None" else cfg.ragePosition
					sanitize(cfg)
					Menu.refreshToggles()
				end
			end
			local ge = t.General
			local gen = G(ge.L, "Ragebot", { simple = true })
			gen:toggle("Enable", "rageEnabled", { desc = "Master switch for everything that moves your body: magic bullet, autokill, peek, defense, voidspam, melee rage, backstab and the anti-melee dodge. Off keeps the Mode below, so turning it back on picks up where you left off.", onChange = function()
				-- every rage mode aims through silent aim: switching the ragebot on brings it (and its trigger) along
				if cfg.rageEnabled and not cfg.silentAim then
					cfg.silentAim, cfg.autoShoot = true, true
					notify("Ragebot on — silent aim and auto shoot turned on with it", 4, "info")
				end
				sanitize(cfg)
				Menu.refreshToggles()
			end })
			Input.bindLabels.rageEnabled = "Ragebot"
			local gpos = G(ge.L, "Positioning", { simple = true })
			gpos:cycle("Mode", "ragePosition", { "None", "Magic bullet", "Autokill", "Peek" }, { desc = "What moves you when a target is locked. Magic bullet shoots from a clear spot next to them, Autokill teleports around them until they drop, Peek swings out while you hold the peek key. One at a time; other players can see it.", onChange = function()
				sanitize(cfg)
				Menu.refreshToggles()
			end })
			gpos:info("Holding your body", function()
				local B = Combat.body
				return if B.owner then ("%s · %.1f s"):format(B.owner, os.clock() - B.ownerSince) else "Nobody (it's yours)"
			end)
			gpos:slider("Height limit", "safeMaxHeight", 8, 150, 1, { unit = "st", fmt = int, desc = "No teleport rests higher than this above the ground under the spot or the target. Stops two cheaters from lifting each other into a sky kill zone." })
			gpos:toggle("Break prediction", "rageBreaker", { danger = "TELEPORT", desc = "While magic bullet or autokill runs and the gun has time to spare, a short hop to a random safe spot 12–24 st away, back before it can fire." })
			local gtg = G(ge.L, "Targeting", { simple = true })
			gtg:cycle("Priority", "targetPriority", { "Closest", "Crosshair", "LowestHP", "Threat" }, { fmt = function(v)
				return if v == "LowestHP" then "Lowest health" elseif v == "Threat" then "Aiming at you" else tostring(v)
			end })
			gtg:toggle("Prefer threats", "threatPriority", { desc = "Favours enemies who are aiming at you." })
			gtg:toggle("Melee threats first", "antiMeleeTarget", { desc = "A blade about to reach you gets the lock before anyone else." })
			gtg:toggle("Visible targets first", "targetPreferVisible", { desc = "Ranks enemies the server can see from your shot first." })
			gtg:toggle("Lock anywhere without a mode", "silentFov360", { desc = "With a positioning mode on, the ragebot always targets all around you. This keeps silent aim at 360° with the mode set to None too." })
			gtg:slider("Max distance", "targetMaxDistance", 50, 5000, 50, { unit = "st", fmt = int })
			-- setup check: every switch the ragebot needs, why it is not firing right now, one button to fix it
			local gck = G(ge.R, "Setup check", { simple = true })
			gck:info("Setup", function()
				local issues = Combat.rageCheck()
				return if #issues == 0 then "Ready" else ("%d to fix · %s"):format(#issues, issues[1].text)
			end)
			gck:info("Right now", function()
				return Combat.rageNow()
			end)
			gck:button("Fix setup", function()
				local fixed = Combat.rageFix()
				sanitize(cfg)
				saveConfig()
				Menu.refreshToggles()
				notify(if #fixed == 0 then "Ragebot setup already fine" else "Fixed: " .. table.concat(fixed, ", "), 5, "ok")
			end, C.accent, { desc = "Turns on what the ragebot needs (Ragebot, silent aim, auto shoot, 360° targeting when Mode is None) and turns off what quietly stops it firing (Only while firing, a low silent hit chance, a high min hit chance, the triggerbot). Your mode, hitbox choice and everything else stay as they are." })
			local gfi = G(ge.R, "Firing", { simple = true })
			gfi:toggle("Auto shoot", "autoShoot", { desc = "Fires as soon as a locked target is in the open." })
			gfi:slider("Min hit chance", "autoShootMinHitChance", 0, 100, 5, { unit = "%", fmt = int })
			gfi:cycle("Auto stop", "autoShootStopMode", { "Off", "Per shot", "While firing", "Whenever locked" }, { onChange = function()
				sanitize(cfg)
			end })
			gfi:cycle("Spread", "spreadMode", { "Auto", "Claim", "Real aim" }, { desc = "Claim tells the server every shot is aimed (no scope needed). Real aim scopes in and waits. Auto: snipers on real aim, the rest claim, and a weapon whose claimed shots keep missing switches by itself." })
			gfi:info("Switched to real aim", function()
				local list = {}
				for w, m in pairs(cfg.spreadLearned) do
					if m == "real" then
						table.insert(list, w)
					end
				end
				return if #list > 0 then table.concat(list, ", ") else "None"
			end)
			gfi:button("Forget what Auto learned", function()
				table.clear(cfg.spreadLearned)
				saveConfig()
				notify("Spread modes back to their defaults", 2, "ok")
			end)
			local gct = G(ge.R, "Counters")
			gct:toggle("Void spam trap", "counterVoid", { desc = "Keeps the lock on someone dipping under the map, waits over the spot they left and fires the frame they come back up." })
			gct:toggle("Punish teleports", "counterTeleport", { desc = "Right after an enemy teleports they are still settling: they get the lock for that moment." })
			gct:toggle("Anti riot shield", "shieldAware", { desc = "A riot shield (every skin) counts as cover: rounds never go into it. When it covers your hitbox, silent aim shoots the part that sticks out past it (top of the head, a shoulder, the feet), and magic bullet / autokill pick spots that see around it." })
			gct:toggle("Anti-flash", "antiFlash", { desc = "Flashbangs don't blind you." })
			gct:toggle("Hunt void campers", "voidHunt", { desc = "Enemies under the map stay on ESP and can be locked." })
			local gut = G(ge.R, "Utilities and abilities", { simple = true })
			gut:toggle("Use utilities", "utilAuto", { desc = "Uses your utility slot by itself through the game's quick-utility input, without switching weapons.", sub = function(sg)
				sg:toggle("Heal when low", "utilHeal", { desc = "Medkit or Elixir when your health drops below the line and nobody can hit you." })
				sg:slider("Heal below", "utilHealBelow", 10, 90, 5, { unit = "%", fmt = int })
				sg:toggle("Mine a blade", "utilMine", { desc = "Drops a Subspace Tripmine or Satchel when a melee player closes in." })
				sg:toggle("Throw at the target", "utilThrow", { desc = "Throws a Grenade, Flashbang or Molotov at the locked target 12–45 studs away. Experimental." })
			end })
			gut:toggle("Gun abilities", "gunAbilities", { desc = "Keeps the Minigun spun up while you have a target, and fans the Revolver's quick shot at close range." })

			local mb = t["Magic bullet"]
			local gm = G(mb.L, "Magic bullet", { simple = true })
			gm:toggle("Magic bullet", "magicBullet", { danger = "TELEPORT", desc = "Shoots from a clear spot next to the target, then brings you back. Turning it on picks it as the positioning mode.", onChange = positionToggle("Magic bullet") })
			gm:toggle("Move early on aim key", "magicPrePosition", { desc = "Teleports while you hold the aim key so the first shot is ready." })
			gm:toggle("Keep your view", "magicInvisible", { desc = "Your camera stays put while your body moves." })
			gm:toggle("Wallbang", "wallbang", { desc = "Shoots through walls: stands inside the wall next to the target so the round starts past it. Also reaches enemies hiding inside a wall." })
			gm:toggle("Auto height", "magicAutoHeight", { desc = "Picks the spot itself: cover first, then beside the target, then above within the height limit." })
			gm:slider("Max height", "magicHeight", 5, 150, 1, { unit = "st", fmt = int })
			gm:toggle("Hop after each shot", "magicHopOnShot", { desc = "Slow weapons move right after each shot; the server sees the new spot before the next one." })
			local gj = G(mb.L, "Jitter")
			gj:toggle("Jitter", "magicJitter", { desc = "Keeps moving between spots so you're harder to hit." })
			gj:slider("Jitter radius", "magicJitterRadius", 0.5, 20, 0.5, { unit = "st", fmt = one })
			gj:slider("Jitter rate", "magicJitterHz", 1, 40, 1, { unit = "/s", fmt = int })
			gj:slider("Wiggle", "magicWiggle", 0, 4, 0.1, { unit = "st", fmt = one })
			local gsp = G(mb.R, "Shooting spots")
			gsp:toggle("Prefer cover spots", "originPreferCover", { desc = "Autokill Origin (and magic bullet with Wallbang) stands inside a wall next to the target: your shots get out, theirs don't get in." })
			gsp:slider("Shooting distance", "originMaxDist", 2, 120, 1, { unit = "st", fmt = int, desc = "How far from the target spots try to stand (closer beats spread)." })
			gsp:toggle("Follow targets under the map", "originBelowMap")
			gsp:toggle("Keep a working spot", "originStick")

			local a = t.Autokill
			local gk = G(a.L, "Autokill", { simple = true })
			gk:toggle("Autokill", "autokill", { danger = "TELEPORT", desc = "Teleports around the target and shoots until it drops. Right-click to bind a key." })
			gk:toggle("Engage automatically", "autokillAuto", { danger = "TELEPORT", desc = "Starts on its own when an enemy is in range. Turning it on picks Autokill as the positioning mode.", onChange = positionToggle("Autokill") })
			gk:cycle("Mode", "autokillMode", { "Origin", "Orbit", "Void", "Snap", "Under", "High" }, { desc = "Origin shoots from a spot with a clear shot and never stands still on it. Orbit circles them. Void attacks, then rests in this map's void under the map. Snap shoots, then waits where you stood while the gun cycles. Under sits inside the floor right under them: your shots come up through it, theirs stop on it. High hangs 25 studs over their head." })
			gk:button("Start autokill now", function()
				Menu.set(false)
				task.delay(0.1, function()
					Combat.startAutokill(Game.targets())
				end)
			end, C.rage)
			gk:toggle("Hide + spin between shots", "autokillHvh", { danger = "TELEPORT", desc = "The moment the gun goes on cooldown you hide in the void under the map (hopping with voidspam) and spin, and come back just before it can fire again." })
			gk:toggle("Return when done", "autokillReturn")
			gk:toggle("Camera follows", "autokillVisible", { desc = "Off keeps your own view while your body moves." })
			gk:toggle("Adapt to weapon and enemy", "autokillAdaptive", { desc = "Picks targets by threat and health and moves to suit your weapon." })
			gk:toggle("Chain to the next enemy", "autokillChain", { desc = "Moves on to the next enemy instead of returning." })
			-- how long and how far: the settings people change most, in one place
			local gat = G(a.L, "Attack", { simple = true })
			-- one slider: 1–60 s, and the last notch (61) is "until they die" (no clock)
			gat:slider("Attack time", "autokillDuration", 1, Combat.AK_UNTIL_DEAD, 0.5, { fmt = function(n: number): string
				return if n >= Combat.AK_UNTIL_DEAD then "until dead" else ("%.1f s"):format(n)
			end, onChange = function(v)
				cfg.autokillUntilDead = v >= Combat.AK_UNTIL_DEAD
			end, desc = "How long one run stays on its target. Landing hits extends it (up to twice this). Slide all the way right for \"until dead\": no time limit, it only stops when the target dies, you drop below the health limit, the target can't be hurt from anywhere for a few seconds, or you open the menu. Approaching and lining up the first shot take about a second, so very short runs can end before they fire." })
			gat:slider("Engage range", "autokillAutoRange", 10, 1000, 5, { unit = "st", fmt = int, desc = "How far away an enemy can be for autokill to go after them. Silent aim's Max distance is raised to match, so the lock reaches them too.", onChange = function(v)
				if (tonumber(cfg.targetMaxDistance) or 400) < v then
					cfg.targetMaxDistance = v
				end
			end })
			gat:slider("Shooting distance", "originMaxDist", 2, 120, 1, { unit = "st", fmt = int, desc = "How far from the target it tries to stand while shooting. Closer beats spread and damage falloff; farther is safer." })
			local gkr = G(a.L, "Limits")
			gkr:slider("Cooldown", "autokillCooldown", 0, 10, 0.5, { unit = "s", fmt = one })
			gkr:slider("Stop below health", "autokillAbortHp", 0, 80, 5, { unit = "%", fmt = int })
			gkr:slider("Snap: strike for", "autokillSnapHold", 0.1, 5, 0.1, { unit = "s", fmt = one, desc = "Longest strike without a shot before it goes home and tries a fresh spot." })
			local gor = G(a.R, "Around the target")
			gor:cycle("Movement", "autokillMove", { "Auto", "Hop", "Orbit", "Hold" }, { desc = "Auto hops while it's dangerous and orbits otherwise. Hold keeps one spot and only moves when you're hit." })
			gor:slider("Hop every", "autokillHopMs", 120, 600, 10, { unit = "ms", fmt = int })
			gor:toggle("Radius noise", "autokillOrbit")
			gor:slider("Orbit speed", "autokillOrbitSpeed", 1, 120, 1, { fmt = int })
			gor:slider("Speed cap", "autokillMaxSpeed", 20, 600, 5, { unit = "st/s", fmt = int, safe = { 20, 60 }, safeText = "Moving faster than this can get you pulled back." })
			gor:slider("Orbit radius", "autokillRadius", 1, 20, 0.5, { unit = "st", fmt = one })
			gor:slider("Height above head", "autokillHeight", 0, 20, 0.5, { unit = "st", fmt = one })
			local gv = G(a.R, "Void mode")
			gv:slider("Void attack time", "voidBurst", 0.1, 20, 0.1, { unit = "s", fmt = one, desc = "Void mode only: how long each attack lasts before resting. Counts from the first shot." })
			gv:slider("Rest time", "voidRest", 0.1, 15, 0.1, { unit = "s", fmt = one, desc = "Longest rest, parked 10,000+ studs out where nothing can reach you. It ends early when the gun is ready and one shot kills." })

			local ml = t.Melee
			local gmr = G(ml.L, "Melee ragebot", { simple = true })
			gmr:toggle("Melee ragebot", "meleeRage", { danger = "TELEPORT", desc = "The ragebot for blades: picks the nearest enemy in Range by itself (no FOV, no silent aim needed), stays on them in reach (behind them for crit blades), swings at the weapon's own speed and moves straight on to the next one after a kill." })
			gmr:cycle("Mode", "meleeMode", { "Auto", "Heavy crit", "Close spam", "Ability", "Walk-in" }, { desc = "Auto picks per weapon: heavy crits from behind with the Knife and Glast Shard, abilities for the Katana, Scythe, Battle Axe and Chainsaw, fast swings for the rest. Walk-in never teleports." })
			gmr:cycle("Heavy attack", "meleeHeavyPolicy", { "Heavy then light", "Heavy only", "Light only" }, { desc = "The heavy (right click) is the 150 crit from behind." })
			gmr:cycle("Their facing", "meleeLookSource", { "Auto", "Camera", "Body", "Smoothed" }, { desc = "Decides where \"behind\" is. Auto uses their look, and against anti-aim a smoothed look or their body." })
			gmr:slider("Range", "meleeRageRange", 6, 250, 2, { unit = "st", fmt = int })
			gmr:slider("Stand-off", "meleeStandoff", 1, 12, 0.5, { unit = "st", fmt = one, desc = "How far from them the spot is (kept inside reach)." })
			gmr:slider("Settle padding", "meleeSettlePad", 0, 200, 10, { unit = "ms", fmt = int, desc = "Extra wait after a teleport before attacking, on top of your ping." })
			gmr:slider("Heavy hold", "meleeHeavyHold", 0.05, 0.5, 0.01, { unit = "s", desc = "How long the right click stays down." })
			gmr:toggle("Face them on each attack", "meleeFaceOnSwing", { desc = "The attack carries a camera that faces them (the server checks a 90° cone); your view snaps back the same frame." })
			gmr:toggle("Predict their movement", "meleePredict")
			gmr:slider("Reach slack", "meleeReachSlack", 0, 4, 0.5, { unit = "st", fmt = one })
			local gpw = G(ml.L, "Per weapon")
			gpw:list("Click a weapon to change its mode", {
				height = 150,
				search = false,
				items = function()
					local out = {}
					for _, nm in ipairs({ "Knife", "Glast Shard", "Katana", "Scythe", "Battle Axe", "Chainsaw", "Fists", "Maul", "Riot Shield", "Spear", "Trowel" }) do
						local over = cfg.meleeOverrides[nm]
						table.insert(out, { id = nm, label = nm, sub = over or "follows Mode", color = if over then C.accent else nil })
					end
					return out
				end,
				onSelect = function(id: string)
					local order = { "Heavy crit", "Close spam", "Ability", "Walk-in" }
					local cur = cfg.meleeOverrides[id]
					local nextMode: string? = order[1]
					for i, m in ipairs(order) do
						if m == cur then
							nextMode = order[i + 1] -- past the last one: back to following Mode
						end
					end
					cfg.meleeOverrides[id] = nextMode
					saveConfig()
				end,
			})
			local gam = G(ml.R, "Anti-melee", { simple = true })
			gam:toggle("Anti-melee", "antiMelee", { desc = "Reacts to an enemy with a blade out inside their reach, dash and your ping." })
			gam:toggle("Face blades", "antiMeleeFace", { desc = "Other players see you facing the blade, so there is no behind for a crit." })
			gam:toggle("Dodge", "antiMeleeDodge", { danger = "TELEPORT", desc = "A short teleport to their side or away just before they strike." })
			gam:slider("Dodge cooldown", "antiMeleeDodgeCd", 0.3, 6, 0.1, { unit = "s", fmt = one })
			gam:toggle("Dodge when hit", "antiMeleeOnHit")
			gam:toggle("Keep your distance", "antiMeleeKeepDistance", { desc = "With a gun ready you walk away from the blade while you're not steering yourself." })
			gam:slider("Margin", "antiMeleeMargin", 0, 12, 1, { unit = "st", fmt = int })
			local gbs = G(ml.R, "Backstab and quick melee")
			gbs:toggle("Auto backstab", "autoBackstab", { danger = "TELEPORT", desc = "Without the ragebot: one hop behind the target for a crit." })
			gbs:toggle("Backstab with any melee", "autoBackstabAnyMelee", { desc = "Off hops only with crit blades like the Knife." })
			gbs:slider("Backstab range", "autoBackstabRange", 4, 150, 1, { unit = "st", fmt = int })
			gbs:toggle("Auto quick melee", "autoQuickMelee", { desc = "Stabs with the knife when an enemy is in reach. It swaps to the knife." })
			local gkt = G(ml.R, "Blocking")
			gkt:toggle("Auto block", "autoBlock", { desc = "Blocks with a melee in hand when a gun is aimed at you or a blade is about to strike." })
			gkt:slider("Block range", "autoBlockRange", 10, 200, 5, { unit = "st", fmt = int })
			gkt:slider("Block angle", "autoBlockAngle", 5, 180, 1, { unit = "°", fmt = int })
			gkt:toggle("Hold fire while they deflect", "katanaCheck")

			local df = t.Defense
			-- voidspam is its own switch: no silent aim, rage position or hide needed (only the Ragebot's Enable)
			local gvs = G(df.L, "Voidspam", { simple = true })
			gvs:toggle("Voidspam", "voidSpam", { danger = "TELEPORT", desc = "Parks your body far out in the void (30,000 studs past the map by default; guns reach 400) on an invisible pad so it never falls, and brings it back to your spot to shoot. Needs nothing else on. Right-click to bind a key." })
			gvs:cycle("Comes back", "voidSpamMode", { "Timer", "Gun ready", "Stay hidden" }, { desc = "Timer: out for Hide time, back for Back time, repeating. Gun ready: back when your gun can fire, gone right after each round (best with auto shoot). Stay hidden: out there the whole time; autokill and magic bullet still borrow the body for their shots." })
			gvs:slider("Hide time", "voidSpamHide", 0.1, 30, 0.1, { unit = "s", fmt = one, desc = "How long each trip into the void lasts (Timer; Gun ready also stays out this long when you did not fire)." })
			gvs:slider("Back time", "voidSpamBack", 0.05, 10, 0.05, { unit = "s", fmt = function(n: number): string
				return ("%.2f"):format(n)
			end, desc = "How long you stand on your spot between trips. Keep it above half your ping or your rounds leave before the server has you back (the panel warns you)." })
			gvs:slider("Distance", "voidSpamDist", 10000, 90000, 1000, { unit = "st", fmt = function(n: number): string
				return ("%dk"):format(math.floor(n / 1000 + 0.5))
			end, desc = "How far past the map's edge you park. Guns reach 400 st, so 10k is already out of everything." })
			gvs:toggle("Fire brings you back", "voidSpamFireBack", { desc = "Clicking while hidden brings you back, and that round fires by itself once the server has you on your spot. You stay back while you keep firing." })
			gvs:toggle("Movement brings you back", "voidSpamMoveBack", { desc = "Your movement keys end the current trip. Off: voidspam ignores them." })
			gvs:toggle("Come back under them", "voidSpamUnder", { danger = "TELEPORT", desc = "With silent aim locked on someone, each trip back lands 6 studs under them inside the floor (autokill Under's spot: your rounds come up through the floor, theirs stop on it) instead of on your spot. Over someone already buried in the floor it lands on the slab right above them. With auto shoot, a ready gun on a shootable lock also brings you back (not in Stay hidden)." })
			gvs:slider("Under range", "voidSpamUnderRange", 50, 1000, 10, { unit = "st", fmt = int, desc = "The lock must stand within this many studs of your spot (flat); farther away you come back to your spot." })
			gvs:toggle("Bait them out", "voidSpamBait", { danger = "TELEPORT", desc = "When every enemy has been warped far out for a while, you stay out too (no Back time for them to aim at) and now and then show yourself on the map for a moment — shorter than any round needs to reach you — so they come out to fight. The moment one stays out, auto shoot brings you back under them.", sub = function(sg)
				sg:cycle("Bait spot", "voidSpamBaitSpot", { "In the floor", "Your spot" }, { desc = "In the floor: under your spot inside the floor slab (rounds from above stop on it); your spot where the floor is thin." })
				sg:slider("Shown for", "voidSpamBaitSec", 0.1, 1, 0.05, { unit = "s", fmt = function(n: number): string
					return ("%.2f"):format(n)
				end, desc = "How long each bait stays on the map. Long enough for them to see it, shorter than their shot." })
				sg:slider("Every", "voidSpamBaitEvery", 0.5, 10, 0.5, { unit = "s", fmt = one, desc = "Time between baits (varies ±30 % so there is no rhythm to time)." })
			end })
			gvs:slider("Turn off after", "voidSpamAutoOff", 0, 600, 5, { fmt = function(n: number): string
				return if n <= 0 then "never" else ("%ds"):format(math.floor(n + 0.5))
			end, desc = "Voidspam switches itself off after this long. 0 = never." })
			gvs:toggle("Timer on screen", "voidSpamHud", { desc = "Voidspam in the combat bar above your crosshair: hidden or back, the countdown to the next switch and how far out you are." })
			gvs:info("Right now", function(): string
				return Combat.voidSpamLine()
			end)
			local gdf = G(df.L, "Hide while reloading", { simple = true })
			-- its tuning sits behind the row's three-line button, which only shows while rage is on
			gdf:toggle("Hide while reloading", "defenseHide", { danger = "TELEPORT", desc = "While your gun can't fire and someone can hit you, parks you 10,000+ studs out in the void (the voidspam distance, where nothing reaches) and lands you back on your shooting spot just before it can fire. Needs silent aim and a rage position.", subWhen = Combat.rageOn, sub = function(sg)
				sg:slider("Counts from", "defenseMinCooldown", 0.1, 3, 0.05, { unit = "s", desc = "A reload or cooldown at least this long is worth hiding for (never shorter than the trip out and back at your ping)." })
				sg:slider("Longest hide", "defenseMaxHide", 0.5, 20, 0.5, { unit = "s", fmt = one, desc = "No hide lasts longer (voidspam has its own timer above)." })
				sg:toggle("Only when someone can hit you", "defenseOnlyWhenThreat", { desc = "Hides only while an enemy aims at you or has a clear line with a gun out. Off hides on every long cooldown." })
				sg:toggle("Keep your view", "defensePinCamera", { desc = "Your camera stays where you stood while the body is away (voidspam too)." })
				sg:toggle("Hop between hiding spots", "defenseVoidSpam", { desc = "Out in the void it moves to a fresh far spot a few times a second instead of sitting still." })
				sg:slider("Hops per second", "defenseHopHz", 1, 20, 1, { fmt = int })
			end })
			local gpk = G(df.L, "Auto peek")
			gpk:toggle("Auto peek", "autoPeek", { desc = "Hold the peek key to swing out and shoot; you come back when you let go. Turning it on picks Peek as the positioning mode.", onChange = positionToggle("Peek") })
			gpk:keybind("Peek key", "autoPeekKey")
			gpk:slider("Peek distance", "autoPeekDistance", 1, 60, 1, { unit = "st", fmt = int })
			local gob = G(df.R, "Out of bounds")
			gob:toggle("Out of bounds guard", "oobBlock", { danger = "CLIENT ONLY", desc = "Stops your own client from reporting you out of bounds. The server still kills inside kill zones, so teleports never rest in one." })
			gob:slider("Safety margin", "oobMargin", 0.1, 10, 0.1, { unit = "s", fmt = one })
			gob:toggle("Refuse lethal spots", "boundsGuard", { advanced = true, desc = "Teleports never rest inside a kill zone, even with the guard on. Leave this on." })
			gob:button("Test the guard", function()
				local r = Combat.oobProbe(2)
				notify("Out of bounds test: " .. tostring(r), 3, if r == "started" then "info" else "warn")
			end, C.warn)
			gob:info("Last refused spot", function()
				local Sf = S.safe
				return if Sf.lastRefusal and os.clock() - (Sf.lastRefusalAt or 0) < 30 then Sf.lastRefusal else "None lately"
			end)
			local gnc = G(df.R, "Noclip")
			gnc:toggle("Noclip", "noclip", { danger = true, desc = "Walk through walls and floors. Hold mode works best: right-click to bind." })
			gnc:toggle("Fly", "noclipFloat", { desc = "No falling: Space goes up, Ctrl goes down." })
			gnc:slider("Fly speed", "noclipSpeed", 8, 300, 2, { fmt = int })
			gnc:toggle("Fly where you look", "noclipFollowCamera")
		end

		-- Misc (network) and the Ragebot's Anti-aim sub-tab ----------------------------
		do
			local t = Menu.addTab("Misc", { "Network", "Utility" })
			local ut = t.Utility
			local gsv = G(ut.L, "Session")
			gsv:toggle("Anti-AFK", "antiAfk", { desc = "Never get kicked for idling in the lobby or a queue." })
			gsv:toggle("Auto rejoin", "autoRejoin", { desc = "When you get disconnected or kicked, rejoin the game on its own." })
			gsv:slider("Rejoin after", "autoRejoinDelay", 1, 30, 1, { unit = "s", fmt = int })
			local gsr = G(ut.R, "Server")
			gsr:button("Rejoin this server", function()
				notify("Rejoining…", 3)
				local ok, e = pcall(Game.util.teleportHere)
				if not ok then
					notify("Rejoin failed: " .. tostring(e):sub(1, 60), 4, "warn")
				end
			end)
			gsr:button("Server hop", function()
				task.spawn(function()
					local ok, e = pcall(Game.util.serverHop)
					if not ok then
						notify("Server hop failed: " .. tostring(e):sub(1, 60), 4, "warn")
					end
				end)
			end)
			gsr:button("Copy join code", function()
				local code = ('game:GetService("TeleportService"):TeleportToPlaceInstance(%d, "%s")'):format(game.PlaceId, game.JobId)
				if type(setclipboard) == "function" and pcall(setclipboard, code) then
					notify("Copied: paste it in a friend's executor to join you", 4)
				else
					notify("This executor can't copy to the clipboard", 3, "warn")
				end
			end)
			-- network (RakNet, Volt only): everything here is detectable and gated behind the acceptance
			local nt = t.Network
			local gu = G(nt.L, "Network")
			if not S.net.available then
				gu:note("This executor has no RakNet library (Volt only), so nothing here can run.")
			end
			gu:toggle("I accept the ban risk", "unsafeAccepted", { desc = "Required. These change raw network packets, which Roblox can detect.", onChange = function(v)
				if not v then
					cfg.unsafeMode = false
				end
			end })
			gu:toggle("Network mode", "unsafeMode", { desc = "Master switch for the options below.", onChange = function(v)
				if v and not cfg.unsafeAccepted then
					cfg.unsafeMode = false
					notify("Accept the ban risk first", 3, "warn")
					return
				end
				if v and not S.net.available then
					cfg.unsafeMode = false
					notify("This executor has no RakNet library", 3, "warn")
					return
				end
				if v and not S.net.enabled() then
					cfg.unsafeMode = false
					notify("Turn on RakNet Library in Volt → Settings → Client, then try again", 5, "warn")
					return
				end
				if v then
					S.net.install()
				end
			end })
			gu:toggle("Packet monitor", "unsafeShowNet", { desc = "Shows outgoing packets on the Debug page." })
			local gpb = G(nt.R, "Ping")
			gpb:toggle("Ping boost", "unsafePingBoost", { desc = "Makes the server think you lag more so it compensates more. Your real ping doesn't drop. Needs Network mode." })
			gpb:slider("Extra delay", "unsafePingBoostMs", 20, 400, 10, { unit = "ms", fmt = int })

			local aa = Menu.rageTab["Anti-aim"]
			local gaa = G(aa.L, "Anti-aim")
			gaa:toggle("Anti-aim", "aaEnabled", { desc = "Other players see a fake body direction. Your view stays the same." })
			gaa:cycle("Yaw", "aaMode", { "Auto", "Spin", "Jitter", "Backwards", "Sideways", "Away", "Fake", "Random" }, { desc = "Auto uses jitter when someone aims at you, random snaps when enemies are near and a spin when you're alone." })
			gaa:cycle("Pitch", "aaPitch", { "Down", "Up", "Zero", "Jitter", "Real" })
			gaa:slider("Spin speed", "aaSpeed", 1, 120, 1, { fmt = int })
			gaa:cycle("Spin direction", "aaSpinDir", { 1, -1 }, { fmt = function(v)
				return if v == -1 then "Counter-clockwise" else "Clockwise"
			end })
			gaa:toggle("Jitter on spin", "aaSpinJitter", { desc = "Breaks the rhythm so the spin is harder to predict." })
			gaa:slider("Jitter range", "aaJitterDeg", 10, 180, 5, { unit = "°", fmt = int })
			gaa:slider("Switch interval", "aaSwitchMs", 50, 2000, 50, { unit = "ms", fmt = int, desc = "For the Random and Sideways yaw modes." })
			gaa:toggle("Fake flick", "aaFlick", { desc = "Shows your real angle only for the instant of each shot." })
			gaa:toggle("Pause while firing", "aaOnlyIdle")
			local gb = G(aa.R, "Body")
			gb:toggle("Body anti-aim", "aaBody", { desc = "Your character's body turns too, visible to everyone." })
			gb:cycle("Body direction", "aaBodyMode", { "Same", "Real", "Opposite" }, { desc = "Real keeps your hitbox facing forward while the fake angle shows." })
			gb:toggle("Send the fake angle", "aaReplicate", { desc = "Makes the server hold your fake rotation." })
			gb:slider("Send rate", "aaSendHz", 1, 60, 1, { unit = "Hz", fmt = int, advanced = true })
			gb:toggle("Fake duck", "fakeDuck", { danger = "EXPERIMENTAL" })
			local grs = G(aa.R, "Resolver")
			grs:toggle("Resolver", "resolver", { desc = "Corrects for enemies using anti-aim, desync and fake lag." })
			grs:toggle("Body aim on anti-aim users", "resolverBodyOnAA")
			grs:toggle("Backtrack warps", "resolverWarp", { desc = "Against desync cheats that flicker their position thousands of studs off the map every frame: aims, faces and plans from the spot they keep coming back to (ESP tag WARP)." })
			grs:toggle("Ignore dead targets", "deadTargetGuard")
			-- fake lag rides on the network mode (Misc → Network), but it is an anti-aim trick: it lives here
			local gfl = G(aa.L, "Fake lag")
			gfl:toggle("Fake lag", "unsafeFakeLag", { desc = "Others see you late and jumping, so their shots land where you were. Needs Network mode (Misc → Network)." })
			gfl:slider("Hold for", "unsafeFakeLagChokeMs", 50, 400, 10, { unit = "ms", fmt = int })
			gfl:slider("Every", "unsafeFakeLagEveryMs", 200, 3000, 50, { unit = "ms", fmt = int })
			gfl:toggle("Only while fighting", "unsafeFakeLagOnlyWhenTargeted", { desc = "Off lags all the time, which is very visible." })
		end

		-- Visuals ----------------------------------------------------------------
		do
			local t = Menu.addTab("Visuals", if cfg.previewPane then { "ESP", "Chams & more" } else { "ESP", "Chams & more", "Preview" })
			local e = t.ESP
			local g = G(e.L, "ESP")
			g:toggle("ESP", "esp", { desc = "Shows enemies through walls." })
			g:toggle("Box", "espBox")
			g:cycle("Box style", "espBoxStyle", { "Corner", "Full", "3D" })
			g:toggle("Box fill", "espBoxFill")
			g:slider("Fill transparency", "espBoxFillAlpha", 0.3, 0.98, 0.02, { unit = "%", fmt = function(n)
				return tostring(math.floor(n * 100 + 0.5))
			end })
			g:toggle("Outline", "espOutline", { desc = "A thin dark edge around lines and text so they read on any background." })
			g:toggle("Skeleton", "espSkeleton")
			g:toggle("Head dot", "espHeadDot")
			g:toggle("Visible color", "espVisibleCheck", { desc = "Enemies you can see use the second color." })
			local gc = G(e.L, "Colors")
			gc:color("Enemy", "colEsp")
			gc:color("Enemy, visible", "colEspVisible")
			gc:color("Text", "colText")
			gc:color("Full health", "colHp", { desc = "The health bar fades from red to this color as health goes up." })
			local gi = G(e.R, "Info")
			gi:toggle("Name", "espNames")
			gi:toggle("Health bar", "espHealthBar")
			gi:cycle("Health number", "espHpMode", { "When damaged", "Always", "Never" }, { onChange = function(v)
				cfg.espHealth = v ~= "Never"
			end })
			gi:toggle("Weapon", "espWeapon")
			gi:toggle("Distance", "espDistance")
			gi:toggle("Flags", "espFlags", { desc = "Short tags next to the box: anti-aim, fake lag, under the map, reloading." })
			local gs = G(e.R, "Style")
			gs:toggle("Show in the lobby", "espLobby", { desc = "ESP, chams and radar on the lobby's players. Off: only during a round and in the shooting range." })
			gs:toggle("ESP while hidden", "espWhileHidden", { desc = "During a void hide the game unloads the other players from your client (you're 30,000 studs away), so they can't be drawn live. This keeps the ESP on the fight: enemies still loaded are measured from your camera, and the ones that unloaded show as a dimmed \"last seen\" box at where they were heading. Local only, it never reveals your spot. Turn it off if it costs you frames.", sub = function(sg)
				sg:slider("Keep last seen for", "espGhostSec", 1, 30, 1, { unit = "s", fmt = int })
			end })
			gs:slider("Max distance", "espMaxDistance", 100, 10000, 100, { unit = "st", fmt = int })
			gs:slider("Text size", "espTextSize", 8, 32, 1, { unit = "px", fmt = int })
			gs:slider("Line width", "espLineWidth", 1, 6, 1, { unit = "px", fmt = int })
			gs:cycle("Renderer", "espRenderer", { "Auto", "Drawing", "Anti-aliased" }, { desc = "Drawing is the fastest and snaps every line to whole pixels. Anti-aliased draws smooth lines with GUI frames and works on every executor; the crowd limit keeps it cheap in duels.", onChange = function()
				Vis.resetDrawings()
			end })
			gs:button("Clean look", function()
				for k, v in pairs(Vis.CLEAN_ESP) do
					cfg[k] = if type(v) == "table" then table.clone(v) else v
				end
				cfg.espHealth = cfg.espHpMode ~= "Never"
				Vis.resetDrawings()
				saveConfig()
				Menu.refreshToggles()
				notify("Clean ESP look applied", 2, "ok")
			end, nil, { desc = "Neutral colors, thin outlined lines, name, health and weapon only." })

			local c = t["Chams & more"]
			local gch = G(c.L, "Chams")
			gch:toggle("Chams", "espHighlight", { desc = "Colors the whole enemy model, visible through walls." })
			gch:toggle("Only behind walls", "espChamsOccluded")
			gch:slider("Fill transparency", "espChamsFill", 0, 1, 0.05, { unit = "%", fmt = function(n)
				return tostring(math.floor(n * 100 + 0.5))
			end })
			gch:slider("Outline transparency", "espChamsOutline", 0, 1, 0.05, { unit = "%", fmt = function(n)
				return tostring(math.floor(n * 100 + 0.5))
			end })
			gch:color("Fill", "colChamsFill")
			gch:color("Outline", "colChamsOutline")
			local gt = G(c.L, "Tracers")
			gt:toggle("Tracers", "espTracers")
			gt:cycle("Start from", "espTracerFrom", { "Bottom", "Center", "Mouse" })
			gt:color("Tracer", "colTracer")
			local gar = G(c.R, "Off-screen arrows")
			gar:toggle("Off-screen arrows", "espArrows", { desc = "Points at enemies you can't see on screen." })
			gar:slider("Distance from center", "espArrowRadius", 50, 800, 10, { unit = "px", fmt = int })
			gar:slider("Max arrows", "espArrowMax", 1, 16, 1, { fmt = int, desc = "Only the nearest enemies get an arrow." })
			gar:toggle("Show distance", "espArrowDist")
			local gra = G(c.R, "Radar")
			gra:toggle("Radar", "radar")
			gra:slider("Size", "radarSize", 80, 500, 10, { unit = "px", fmt = int })
			gra:slider("Range", "radarRange", 50, 2000, 10, { unit = "st", fmt = int })
			local gf = G(c.R, "Feedback")
			gf:toggle("Hit markers", "hitMarkers", { desc = "White on a hit, green once the server confirms the damage." })

			if t.Preview then
				Menu.buildPreview(t.Preview.scroll)
			end
		end

		-- World ------------------------------------------------------------------
		do
			local t = Menu.addTab("World", { "Lighting", "Effects", "Camera" })
			local pct = function(n: number): string
				return tostring(math.floor(n * 100 + 0.5))
			end
			local signed = function(n: number): string
				return ("%+.2f"):format(n)
			end
			local function preset(name: string): any
				return { name, function()
					Vis.applyWorldPreset(name)
					Menu.refreshToggles()
				end }
			end
			local w = t.Lighting
			local gp = G(w.L, "Looks")
			gp:buttonRow("World looks", { preset("Dusk"), preset("Neon night"), preset("Dream") }, { advanced = false, desc = "One click sets the lighting, grading, fog and effects together." })
			gp:buttonRow("World looks 2", { preset("Arctic"), preset("Crisp"), { "Reset", function()
				Vis.applyWorldPreset("Off")
				Menu.refreshToggles()
			end } }, { advanced = false })
			gp:info("Current look", function()
				return if cfg.worldPreset ~= "" then cfg.worldPreset else "Your own"
			end, { advanced = false })
			local gl = G(w.L, "Lighting")
			-- every change glides in over ~0.25 s; each switch keeps its amount behind the three lines
			gl:toggle("Night mode", "nightMode", { desc = "Dark sky and ambient so chams and ESP stand out.", sub = function(sg)
				sg:slider("Night brightness", "nightLevel", 0, 100, 5, { unit = "%", fmt = int })
				sg:toggle("Ignore hands", "nightHands", { desc = "Your gun stays lit and glows in your accent while the world goes dark." })
				sg:slider("Hands glow", "nightHandsGlow", 0, 100, 5, { unit = "%", fmt = int, desc = "How bright your gun stays and how strongly it glows at night." })
			end })
			gl:toggle("Fullbright", "fullbright", { desc = "Everything evenly lit with no shadows. Wins over night mode.", sub = function(sg)
				sg:slider("Fullbright brightness", "brightness", 0, 10, 0.1, { fmt = one })
			end })
			gl:toggle("Time of day", "timeOfDayOn", { desc = "Night mode keeps the clock at midnight while it's on.", sub = function(sg)
				sg:slider("Time", "timeOfDay", 0, 24, 0.5, { fmt = function(n)
					return ("%02d:%02d"):format(math.floor(n), math.floor((n % 1) * 60))
				end })
			end })
			gl:toggle("Custom ambient", "worldAmbientOn", { desc = "Tints the light in shadows and indoors.", sub = function(sg)
				sg:color("Indoor light", "colAmbient")
				sg:color("Outdoor light", "colOutdoor")
			end })
			gl:toggle("Exposure", "worldExposureOn", { sub = function(sg)
				sg:slider("Exposure amount", "worldExposure", -2, 2, 0.05, { fmt = signed })
			end })
			gl:cycle("Shadows", "worldShadows", { "Default", "On", "Off" })
			local gg = G(w.R, "Color grading")
			gg:toggle("Color grading", "worldGrade", { desc = "Adjusts the contrast, saturation and tint of the whole screen." })
			gg:slider("Brightness", "gradeBrightness", -0.3, 0.3, 0.01, { fmt = signed })
			gg:slider("Contrast", "gradeContrast", -0.5, 1, 0.01, { fmt = signed })
			gg:slider("Saturation", "gradeSaturation", -1, 1, 0.01, { fmt = signed })
			gg:color("Tint", "gradeTint")
			local gfs = G(w.R, "Fog & sky")
			gfs:toggle("No fog", "noFog")
			gfs:toggle("Custom fog", "worldAtmos", { desc = "Your own haze color and thickness.", sub = function(sg)
				sg:slider("Fog density", "atmosDensity", 0, 1, 0.01, { unit = "%", fmt = pct })
				sg:slider("Haze", "atmosHaze", 0, 10, 0.1, { fmt = one })
				sg:slider("Glare", "atmosGlare", 0, 10, 0.1, { fmt = one })
				sg:color("Fog color", "atmosColor")
			end })
			gfs:toggle("Custom sky color", "skyColorOn", { sub = function(sg)
				sg:color("Sky color", "skyColor")
			end })
			gfs:toggle("Starry sky", "worldStars", { desc = "Fills the night sky with stars." })

			local fx = t.Effects
			local gbl = G(fx.L, "Glow")
			gbl:toggle("Bloom", "worldBloom", { desc = "Bright lights and surfaces glow softly." })
			gbl:slider("Bloom strength", "bloomIntensity", 0, 3, 0.05, { fmt = function(n)
				return ("%.2f"):format(n)
			end })
			gbl:slider("Bloom size", "bloomSize", 0, 56, 1, { fmt = int })
			gbl:slider("Bloom threshold", "bloomThreshold", 0, 3, 0.05, { fmt = function(n)
				return ("%.2f"):format(n)
			end })
			gbl:toggle("Sun rays", "worldSunRays")
			gbl:slider("Ray strength", "sunRaysIntensity", 0, 1, 0.01, { unit = "%", fmt = pct })
			gbl:slider("Ray spread", "sunRaysSpread", 0, 1, 0.01, { unit = "%", fmt = pct })
			local gd = G(fx.L, "Depth of field")
			gd:toggle("Depth of field", "worldDof", { desc = "Blurs things far away. Distant enemies get harder to see." })
			gd:slider("Focus distance", "dofFocus", 5, 200, 1, { unit = "st", fmt = int })
			gd:slider("Blur", "dofBlur", 0, 1, 0.01, { unit = "%", fmt = pct })
			local gpe = G(fx.L, "Game effects")
			gpe:toggle("Remove the game's effects", "noPostFx", { desc = "Turns off the game's own blur, bloom and color effects. Yours stay on." })
			gpe:toggle("No damage flash", "noDamageFx")
			local gw = G(fx.R, "Weather")
			gw:cycle("Weather", "worldWeather", { "Off", "Snow", "Rain", "Embers", "Dust" }, { desc = "Particles falling around you. Only you see them." })
			gw:slider("Amount", "weatherDensity", 5, 100, 5, { unit = "%", fmt = int })
			gw:toggle("Raise graphics for effects", "fxQuality", { desc = "Roblox hides bloom, sun rays, depth of field and most weather at low graphics. While one of them is on, the graphics level goes up to 8 and back when they're off. Costs some FPS on weak PCs." })
			local gsk = G(fx.R, "Shots & kills")
			gsk:toggle("Bullet tracers", "shotTracers", { desc = "A fading beam from your gun to where each shot landed." })
			gsk:slider("Tracer time", "shotTracerLife", 0.15, 2, 0.05, { unit = "s", fmt = function(n)
				return ("%.2f"):format(n)
			end })
			gsk:toggle("Tracer uses accent", "shotTracerAccent")
			gsk:color("Tracer color", "colShotTracer")
			gsk:toggle("Damage numbers", "hitNumbers", { desc = "Floating numbers where your confirmed hits land." })
			gsk:toggle("Blood on hit", "hitBlood", { desc = "A blood splash where each of your confirmed hits lands. Only you see it." })
			gsk:cycle("Kill effect", "killEffect", { "Off", "Ring", "Burst", "Blood" })
			local gyou = G(fx.R, "Chams on you")
			gyou:toggle("Viewmodel chams", "vmChams", { desc = "Recolors your weapon in first person (your arms keep their look)." })
			gyou:cycle("Viewmodel material", "vmMaterial", { "ForceField", "Neon", "Glass", "SmoothPlastic" }, { fmt = Vis.materialLabel })
			gyou:color("Viewmodel color", "colVm")
			gyou:slider("See-through", "vmAlpha", 0, 0.9, 0.05, { unit = "%", fmt = pct, desc = "How transparent your weapon gets with viewmodel chams." })
			gyou:toggle("Self chams", "selfChams", { desc = "Recolors your own character in third person." })
			gyou:cycle("Self material", "selfMaterial", { "ForceField", "Neon", "Glass", "SmoothPlastic" }, { fmt = Vis.materialLabel })
			gyou:color("Self color", "colSelf")

			local cm = t.Camera
			local gcam = G(cm.L, "Third person")
			gcam:toggle("Third person", "thirdPerson", { desc = "Over-the-shoulder camera. Shots still come from your head along your aim." })
			gcam:cycle("Shoulder", "tpShoulder", { "Right", "Left", "Center" })
			gcam:slider("Distance", "tpDist", 1, 30, 0.5, { unit = "st", fmt = one })
			gcam:slider("Height", "tpUp", 0, 12, 0.25, { unit = "st", fmt = function(n)
				return ("%.2f"):format(n)
			end })
			gcam:slider("Side offset", "tpSide", 0, 10, 0.25, { unit = "st", fmt = function(n)
				return ("%.2f"):format(n)
			end })
			gcam:toggle("Smooth follow", "tpSmooth")
			gcam:toggle("Hide weapon in third person", "tpHideViewmodel")
			local gfov = G(cm.R, "Field of view")
			gfov:toggle("Custom field of view", "fovChanger")
			gfov:slider("Field of view", "fov", 60, 120, 1, { unit = "°", fmt = int })
			gfov:toggle("No zoom when aiming", "noAdsZoom", { desc = "Aiming down sights keeps your field of view, snipers included." })
			local gsc = G(cm.R, "Screen")
			gsc:toggle("Hide scope overlay", "noScopeOverlay", { desc = "Removes the black sniper scope around the screen." })
			gsc:toggle("Hide weapon", "hideViewmodel", { desc = "Hides your weapon and arms in first person too." })
			gsc:toggle("Hide hands", "hideHands", { desc = "Hides only your arms; the weapon stays. Hide weapon wins when both are on." })
			gsc:toggle("Hide crosshair spread", "noCrosshairBloom", { advanced = true })
			gsc:cycle("Crosshair style", "crosshairStyle", { "Classic", "Dot", "Circle", "Cross" })
