				if on then
					notify("Skins unlocked (local only)", 3, "ok")
				end
				task.defer(function()
					pcall(Skins.applyNow, nil)
					pcall(Skins.refreshEquipmentUi) -- customize slots regenerate as unlocked/locked
				end)
			end })
			g:toggle("Include finishers", "unlockFinisher", { advanced = true })
