			g:button("Lock everything", function()
				setUnlockAll(false)
			end, nil, { desc = "Turns every unlock off and puts the game's own inventory back." })
			g:toggle("Full model skins", "skinModelSwap", { desc = "Swaps the whole weapon model, not just the paint.", onChange = function()
				task.defer(function()
					pcall(Skins.applyNow, nil)
				end)
			end })
			g:toggle("Apply instantly", "skinRebuild", { desc = "Rebuilds the weapon in your hand right away. Off shows model skins from your next spawn.", onChange = function(on)
