				return w .. (if st == "none" then " (not in hand)" elseif st == "ok" then " (ready)" else " (updating)")
			end, { advanced = false })
			g:info("On this weapon", function()
				local eq = S.localEquips[weapon()]
				local parts = {}
				if eq and eq.Skin then
					table.insert(parts, tostring(eq.Skin.Name))
				end
				if eq and eq.Wrap then
