				return if #parts > 0 then table.concat(parts, ", ") else "Game default"
			end, { advanced = false })

			local gw = G(s.L, "Weapon")
			refreshWeapons = gw:list("Browse a weapon", {
				height = 210,
				placeholder = "Search weapons",
				items = function()
					local lf = Game.localFighter()
					local held = lf and Game.activeItem(lf)
					local heldName = held and held.Name
					local out = {}
					for _, w in ipairs(weapons) do
						local eq = S.localEquips[w]
						local sub, col = "", C.muted
						if w == heldName then
							sub, col = "in hand", C.accent
						elseif eq and (eq.Skin or eq.Wrap) then
							sub, col = "custom", C.ok
						end
						table.insert(out, { id = w, label = w, sub = sub, color = col })
					end
					return out
				end,
				selected = weapon,
				onSelect = function(id)
