					saveConfig()
					if refreshSkins then
						refreshSkins()
					end
					if refreshWraps then
						refreshWraps()
					end
				end,
			})
			gw:button("Follow the weapon in hand", function()
				cfg.skinWeapon = ""
				saveConfig()
				refreshWeapons()
				if refreshSkins then
