						table.insert(out, {
							id = nm,
							label = nm,
							sub = if avail then kind else "not available",
							color = if avail then Skins.rarityColor(nm) else C.muted,
							dim = not avail,
						})
					end
					return out
				end,
				selected = function()
					local cur = localOf(weapon(), "Skin")
					return if cur and cur.Name then cur.Name else "None"
				end,
				onSelect = function(id)
					local w = weapon()
					cfg.unlockCosmetics = true
					if id == "None" then
						Skins.applyLocalEquip(w, "Skin", nil)
						notify(w .. ": default model", 2, "info")
					else
						Skins.applyLocalEquip(w, "Skin", id)
						local avail = Skins.available(id)
						notify(("%s: %s%s"):format(w, id, if not avail then " isn't available, so it stays default" elseif not cfg.skinRebuild then " (shows from your next spawn)" else ""), 4, if avail then "ok" else "warn")
					end
				end,
			})

			local gwr = G(s.R, "Wrap")
			refreshWraps = gwr:list("Wrap for the selected weapon", {
				height = 190,
				placeholder = "Search wraps",
				items = function()
					local out = { { id = "None", label = "Default", sub = "", color = C.muted } }
					for _, nm in ipairs(Skins.cosmeticsFor(weapon(), "Wrap")) do
						table.insert(out, { id = nm, label = nm, sub = Skins.rarity(nm), color = Skins.rarityColor(nm) })
					end
					return out
				end,
				selected = function()
					local cur = localOf(weapon(), "Wrap")
					return if cur and cur.Name then cur.Name else "None"
				end,
				onSelect = function(id)
					local w = weapon()
					cfg.unlockCosmetics = true
					if id == "None" then
						Skins.applyLocalEquip(w, "Wrap", nil)
						notify(w .. ": default wrap", 2, "info")
					else
						local cur = localOf(w, "Wrap")
						Skins.applyLocalEquip(w, "Wrap", id, { IsInverted = cur and cur.Inverted == true })
						notify(("%s: %s"):format(w, id), 3, "ok")
					end
				end,
			})
			local invBtn: any
			local function invText(): string
				local cur = localOf(weapon(), "Wrap")
				return if cur and cur.Inverted then "Invert wrap colors: on" else "Invert wrap colors: off"
			end
			invBtn = gwr:button(invText(), function()
				local w = weapon()
				local cur = localOf(w, "Wrap")
				if not (cur and cur.Name) then
					notify("Pick a wrap first", 2, "warn")
					return
				end
				Skins.applyLocalEquip(w, "Wrap", cur.Name, { IsInverted = not (cur.Inverted == true) })
				invBtn.Text = invText()
			end)
			UI.syncLazy(function()
				local txt = invText()
				if invBtn.Text ~= txt then
					invBtn.Text = txt
				end
			end)
		end

		-- Debug ------------------------------------------------------------------
		do
			local Dbg: any = {}
			S.dbg = Dbg
			local function summarize(v: any): string
				local tv = typeof(v)
				if tv == "table" then
					local n = 0
					for _ in pairs(v) do
						n += 1
					end
					return ("{table ×%d}"):format(n)
				elseif tv == "Instance" then
					return ("<%s %s>"):format(v.ClassName, v.Name)
				elseif tv == "function" then
					return "fn"
				end
				return tostring(v)
			end
			-- log a table's fields (sorted) as one INFO block; optionally to the clipboard too
			function Dbg.dump(label: string, t: any, opts: any?): string
				opts = opts or {}
				local lines = { "== " .. label }
				if type(t) ~= "table" then
					table.insert(lines, "(" .. typeof(t) .. ") " .. tostring(t))
				else
					local keys = {}
					for k in pairs(t) do
						table.insert(keys, k)
					end
					table.sort(keys, function(a, b)
						return tostring(a) < tostring(b)
					end)
					for _, k in ipairs(keys) do
						local v = t[k]
						if not (opts.skipFunctions and type(v) == "function") then
							table.insert(lines, ("  %s = %s"):format(tostring(k), summarize(v)))
						end
					end
					local mt = getmetatable(t)
					if type(mt) == "table" and type(mt.__index) == "table" and opts.methods ~= false then
						local ms = {}
						local depth, cls = 0, mt.__index
						while type(cls) == "table" and depth < 5 do
							for k, v in pairs(cls) do
								if type(v) == "function" then
									table.insert(ms, tostring(k))
								end
							end
							local m2 = getmetatable(cls)
							cls = m2 and m2.__index
							depth += 1
						end
						table.sort(ms)
						table.insert(lines, "  methods: " .. table.concat(ms, ", "))
					end
				end
				local text = table.concat(lines, "\n")
				for _, l in ipairs(lines) do
					log("INFO", l)
				end
				if opts.clipboard ~= false and EXEC.setclipboard then
					pcall(EXEC.setclipboard, text)
				end
				notify(("%s → log (%d lines) + clipboard"):format(label, #lines), 3, "ok")
				return text
			end
			function Dbg.dumpWeapon()
				local gs = S.gameState or {}
				if not gs.item then
					notify("no weapon in hand", 2, "warn")
					return
				end
				Dbg.dump("item " .. tostring(gs.weapon), gs.item, { clipboard = false })
				Dbg.dump("item.Info " .. tostring(gs.weapon), gs.item.Info)
			end
			function Dbg.dumpFighter()
				local lf = Game.localFighter()
				if not lf then
					notify("no local fighter", 2, "warn")
					return
				end
				Dbg.dump("LocalFighter", lf)
			end
			function Dbg.dumpEnemyModel()
				local model = S.silentTargetModel
				if not model then
					local f = Game.enemies()[1]
					local _, m = Game.fighterBody(f)
					model = m
				end
				if not model then
					notify("no enemy model", 2, "warn")
					return
				end
				local parts = {}
				for _, d in ipairs(model:GetDescendants()) do
					if d:IsA("BasePart") then
						parts[d.Name] = ("size %s · CanQuery %s · CanCollide %s · group %s · transp %.1f"):format(tostring(d.Size), tostring(d.CanQuery), tostring(d.CanCollide), d.CollisionGroup, d.Transparency)
					end
				end
				Dbg.dump("enemy model " .. model.Name .. " parts", parts, { methods = false })
			end
			-- module list for the picker (controllers, item types, replicated modules) with loaded flags
			function Dbg.modules(): { string }
				local out = {}
				local function add(folder: Instance?, prefix: string)
					if not folder then
						return
					end
					for _, d in ipairs(folder:GetDescendants()) do
						if d:IsA("ModuleScript") then
							local loaded = true
							if type(EXEC.ismoduleloaded) == "function" then
								local ok, l = pcall(EXEC.ismoduleloaded, d)
								loaded = ok and l == true
							end
							table.insert(out, (if loaded then "" else "· ") .. prefix .. d.Name)
						end
					end
				end
				local ps = LP:FindFirstChild("PlayerScripts")
				add(ps and ps:FindFirstChild("Controllers"), "")
				add(ps and ps:FindFirstChild("Modules"), "M/")
				add(ReplicatedStorage:FindFirstChild("Modules"), "RS/")
				table.sort(out)
				return out
			end
			local function findModule(entry: string): ModuleScript?
				local name = entry:gsub("^· ", "")
				local root: Instance? = nil
				if name:sub(1, 2) == "M/" then
					name = name:sub(3)
					root = LP.PlayerScripts:FindFirstChild("Modules")
				elseif name:sub(1, 3) == "RS/" then
					name = name:sub(4)
					root = ReplicatedStorage:FindFirstChild("Modules")
				else
					root = LP.PlayerScripts:FindFirstChild("Controllers")
				end
				if not root then
					return nil
				end
				local last = name:match("([^/]+)$") or name
				local found = root:FindFirstChild(last, true)
				return if found and found:IsA("ModuleScript") then found else nil
			end
			-- "decompiler": Wave cannot decompile this game's bytecode (v12), so this produces the next best
			-- thing — every function with its string/number constants, upvalue kinds and nested protos.
			-- Enough to see which Info keys / remotes / methods a routine touches.
			function Dbg.decompile(entry: string): string?
				local inst = findModule(entry)
				if not inst then
					notify("module not found: " .. entry, 3, "warn")
					return nil
				end
				local out = { ("-- pseudo-decompile of %s (%s)"):format(inst:GetFullName(), os.date("%Y-%m-%d %H:%M:%S")) }
				local dec = waveGlobal("decompile")
				if type(dec) == "function" then
					local ok, src = pcall(dec, inst)
					if ok and type(src) == "string" and #src > 40 and not src:find("unhandled", 1, true) then
						table.insert(out, src)
					else
						table.insert(out, "-- decompile() unavailable for this bytecode: " .. tostring(src):sub(1, 120))
					end
				end
				local mod = Game.requireIfLoaded(inst)
				if type(mod) ~= "table" then
					table.insert(out, "-- module not loaded by the game yet (or not a table) — constants skipped")
				else
					local seen = {}
					local function fnInfo(name: string, fn: any, indent: string)
						if seen[fn] then
							return
						end
						seen[fn] = true
						local okI, info = pcall(function()
							return (debug :: any).getinfo(fn)
						end)
						if not okI or type(info) ~= "table" then
							info = nil
						end
						table.insert(out, ("%sfunction %s -- line %s, %s params%s"):format(indent, name, tostring(info and info.linedefined), tostring(info and info.nparams), if info and info.is_vararg then ", vararg" else ""))
						local okc, consts = pcall(debug.getconstants, fn)
						if okc and type(consts) == "table" then
							local strs = {}
							for _, c in pairs(consts) do
								if type(c) == "string" then
									table.insert(strs, ('"%s"'):format(c))
								elseif type(c) == "number" then
									table.insert(strs, tostring(c))
								end
							end
							if #strs > 0 then
								table.insert(out, indent .. "  constants: " .. table.concat(strs, ", "))
							end
						end
						local oku, ups = pcall(debug.getupvalues, fn)
						if oku and type(ups) == "table" then
							local kinds = {}
							for i, u in pairs(ups) do
								table.insert(kinds, ("%s:%s"):format(tostring(i), summarize(u)))
							end
							if #kinds > 0 then
								table.insert(out, indent .. "  upvalues: " .. table.concat(kinds, ", "))
							end
						end
						local okp, protos = pcall(debug.getprotos, fn)
						if okp and type(protos) == "table" then
							for i, p in ipairs(protos) do
								fnInfo(("%s.<proto %d>"):format(name, i), p, indent .. "  ")
							end
						end
					end
					local names = {}
					local function collect(t: any, label: string, depth: number)
						if type(t) ~= "table" or depth > 4 or seen[t] then
							return
						end
						seen[t] = true
						for k, v in pairs(t) do
							if type(v) == "function" then
								table.insert(names, { label .. tostring(k), v })
							end
						end
						local mt = getmetatable(t)
						if type(mt) == "table" and type(mt.__index) == "table" then
							collect(mt.__index, label .. "^", depth + 1)
						end
					end
					collect(mod, "", 0)
					table.sort(names, function(a, b)
						return a[1] < b[1]
					end)
					table.insert(out, ("-- %d functions"):format(#names))
					for _, pair in ipairs(names) do
						fnInfo(pair[1], pair[2], "")
					end
				end
				local text = table.concat(out, "\n")
				local file = ("%s/%s.lua"):format(DATA.decompiled, inst.Name)
				pcall(function()
					EXEC.mkdirs(DATA.decompiled)
					EXEC.writefile(file, text)
				end)
				if EXEC.setclipboard then
					pcall(EXEC.setclipboard, text)
				end
				log("INFO", ("decompile: %s → %d lines · workspace\\%s · clipboard"):format(inst.Name, #out, file:gsub("/", "\\")))
				notify(("%s: %d lines → clipboard + %s"):format(inst.Name, #out, file), 4, "ok")
				return text
			end
			function Dbg.traceRays(seconds: number)
				if S.rayTrace then
					return
				end
				table.clear(S.rayTraceBuf)
				S.rayTrace = true
				local base = table.clone(S.shotStats)
				notify(("tracing shot-code raycasts for %ds — fire a bit"):format(seconds), 3, "info")
				task.delay(seconds, function()
					S.rayTrace = false
					local buckets = {}
					for _, r in ipairs(S.rayTraceBuf) do
						local key = ("%s · len≈%d · %s cam · %s/%d"):format(r.caller, math.floor(r.len / 50 + 0.5) * 50, if r.fromCam >= 0 and r.fromCam < 6 then "from" else "away from", (r.ft:gsub("Enum.RaycastFilterType.", "")), r.n)
						buckets[key] = (buckets[key] or 0) + 1
					end
					local lines = {}
					for k, n in pairs(buckets) do
						table.insert(lines, ("%4d × %s"):format(n, k))
					end
					table.sort(lines, function(a, b)
						return a > b
					end)
					local ss = S.shotStats
					log("INFO", ("ray trace %ds: %d raycasts from shot code · redirected %d hit %d blocked %d air %d confirmed %d dropped %d"):format(seconds, #S.rayTraceBuf, ss.redirected - base.redirected, ss.hitTarget - base.hitTarget, ss.hitOther - base.hitOther, ss.miss - base.miss, ss.confirmed - base.confirmed, ss.dropped - base.dropped))
					for _, l in ipairs(lines) do
						log("INFO", "  " .. l)
					end
					notify(("ray trace done: %d casts, %d kinds → log"):format(#S.rayTraceBuf, #lines), 4, "ok")
				end)
			end
			function Dbg.resetStats()
				for k in pairs(S.shotStats) do
					S.shotStats[k] = 0
				end
				table.clear(S.pendingHits)
				table.clear(S.spreadSamples or {})
				S.spreadSampleCount = 0
				S.straightened = 0
				S.errCounts = {}
				notify("shot stats reset", 2, "ok")
			end
			function Dbg.summary(): string
				local ss = S.shotStats
				local hooks = {}
				for k, v in pairs(S.hooks.installed) do
					table.insert(hooks, k .. "=" .. tostring(v))
				end
				table.sort(hooks)
				local errs = {}
				for k, n in pairs(S.errCounts or {}) do
					table.insert(errs, k .. "×" .. n)
				end
				local steps = {}
				for k, rec in pairs(S.stepState or {}) do
					table.insert(steps, ("%s(%d err%s)"):format(k, rec.n or 0, if rec.pausedUntil and os.clock() < rec.pausedUntil then ", PAUSED" else ""))
				end
				local gs = S.gameState or {}
				return table.concat({
					("centerra v%s · place %s · ping %d ms · frame %.1f ms"):format(VERSION, tostring(game.PlaceId), S.pingMs or 0, S.frameMs or 0),
					("weapon %s · ammo %s · hp %s · enemies %d · lock %s · trigger %s (%s)"):format(tostring(gs.weapon), tostring(gs.ammo), tostring(gs.hp), #Game.enemies(), tostring(S.silentTargetModel and S.silentTargetModel.Name), tostring(S.fireLevel and S.fireLevel()), Input.fireMethodUsed),
					("shots %d · hit %d · blocked %d · air %d · confirmed %d · dropped %d · straightened %d · spread avg %s°"):format(ss.redirected, ss.hitTarget, ss.hitOther, ss.miss, ss.confirmed, ss.dropped, S.straightened or 0, if S.spreadAvg then ("%.2f"):format(S.spreadAvg) else "—"),
					("settle %d ms · teleported %s · magic %s · autokill %s"):format(math.floor(Combat.settleSec() * 1000), tostring(S.teleported), tostring(Combat.magic.active), tostring(S.autokill.state)),
					"hooks: " .. table.concat(hooks, " "),
					"steps: " .. (if #steps > 0 then table.concat(steps, " ") else "clean"),
					"errors: " .. (if #errs > 0 then table.concat(errs, " ") else "none"),
				}, "\n")
			end

			local t = Menu.addTab("Debug", { "Live", "Internals", "Shots", "Net", "Inspect", "Decompile" })
			local lv = t.Live
			-- Shots: the recorder (claim vs server truth) ------------------------------------
			do
				local sh = t.Shots
				local gsum = G(sh.L, "Shot recorder")
				gsum:toggle("Record shots", "shotsRecord", { desc = "One record per replicated shot: what we claimed (camera data) vs what the server hit (ShootEffect)" })
				gsum:toggle("SHOT lines in the F9 terminal", "shotsLog")
				gsum:toggle("Export centerra/shots.json", "shotsExport", { desc = "Every 10 shots and on unload — readable through the MCP (read_file centerra/shots.json)" })
				local sumRows: { [string]: TextLabel } = {}
				for _, key in ipairs({ "Total", "Hit", "Near", "Wall", "Air", "No reply", "Unaimed", "Backtrack" }) do
					sumRows[key] = gsum:stat(key)
				end
				sumRows.Hit.TextColor3 = C.ok
				sumRows.Near.TextColor3 = C.warn
				sumRows.Wall.TextColor3 = C.danger
				sumRows.Air.TextColor3 = C.danger
				sumRows["No reply"].TextColor3 = C.danger
				gsum:button("Reset recorder", function()
					S.shots.reset()
					notify("shot recorder reset", 2, "ok")
				end)
				gsum:button("Export shots now", function()
					S.shots.export()
					notify("shots.json written", 2, "ok")
				end, C.accent, { desc = "Writes centerra/shots.json in the Volt workspace." })
				gsum:note("HIT the server hit the lock · NEAR its ray ended under 4 st from the claim · WALL blocked · AIR nothing · NO-REPLY no answer in 1.5 s · UNAIMED a scoped gun fired unscoped · SWING melee (the server never answers)")
				local glist = G(sh.R, "Last shots")
				local lines = glist:logBlock("Last shots", 14)
				UI.syncLazy(function()
					if not sh.scroll.Visible then
						return
					end
					local sm = S.shots.summary()
					sumRows.Total.Text = ("%d · hit rate %s"):format(sm.total, if sm.hitRate then sm.hitRate .. "%" else "—")
					sumRows.Hit.Text = tostring(sm.hit)
					sumRows.Near.Text = tostring(sm.near)
					sumRows.Wall.Text = tostring(sm.wall)
					sumRows.Air.Text = tostring(sm.air)
					sumRows["No reply"].Text = tostring(sm.noReply)
					sumRows.Unaimed.Text = tostring(sm.unaimed)
					sumRows.Backtrack.Text = ("%d ms learned · %d samples · %s"):format(sm.backtrackMs, sm.backtrackSamples, cfg.backtrackMode)
					local list = S.shots.list
					local n = #list
					for i = 1, 14 do
						local rec = list[n - i + 1]
						local lbl = lines[i]
						if rec then
							lbl.Text = S.shots.line(rec)
							lbl.TextColor3 = if rec.verdict == "HIT" then C.ok elseif rec.verdict == "…" or rec.verdict == "SWING" then C.muted elseif rec.verdict == "NEAR" then C.warn else C.danger
						else
							lbl.Text = if i == 1 then "no shots recorded yet" else ""
							lbl.TextColor3 = C.faint
						end
					end
				end)
			end
			-- Net: packet monitor ----------------------------------------------------------------
			do
				local nt = t.Net
				local gn = G(nt.L, "RakNet monitor")
				local netRows: { [string]: TextLabel } = {}
				for _, key in ipairs({ "Library", "Hook", "Physics id", "Rate", "Blocked", "Delayed", "Choking", "Errors" }) do
					netRows[key] = gn:stat(key)
				end
				gn:button("Install monitor hook", function()
					S.net.install()
				end, nil, { desc = "Read-only until Unsafe mode is on." })
				gn:note("Outgoing packet ids seen this session are on the right. Reliable 0x83 is game data (remotes, shots, properties) and is never touched; the busiest unreliable-sequenced id is the physics packet Unsafe mode chokes.")
				local gids = G(nt.R, "Packet ids (this session)")
				local idLines = gids:logBlock("Packet ids", 10)
				UI.syncLazy(function()
					if not nt.scroll.Visible then
						return
					end
					local n = S.net
					netRows.Library.Text = if not n.available then "not available (Volt only)" elseif n.enabled() then "available · enabled" else "available · DISABLED in Volt settings"
					netRows.Hook.Text = if n.installed then "installed" else "not installed"
					netRows["Physics id"].Text = if n.physId then ("0x%02X · %d/s"):format(n.physId, math.floor(n.physRate + 0.5)) else "learning… (move around)"
					netRows.Rate.Text = ("%d packets/s"):format(math.floor(n.rate + 0.5))
					netRows.Blocked.Text = tostring(n.blocked)
					netRows.Delayed.Text = tostring(n.delayed)
					netRows.Choking.Text = if n.active() then (if n.choking() then "YES" else "no") else "unsafe mode off"
					netRows.Errors.Text = tostring(n.err)
					local ids = {}
					for id, c in pairs(n.counts) do
						table.insert(ids, { id = id, n = c.n, rel = c.rel, size = c.size })
					end
					table.sort(ids, function(a, b)
						return a.n > b.n
					end)
					for i = 1, 10 do
						local e = ids[i]
						idLines[i].Text = if e then ("0x%02X  ×%-7d rel %d  last %d B%s"):format(e.id, e.n, e.rel or -1, e.size or 0, if e.id == n.physId then "  ← physics" else "") else ""
					end
				end)
			end
			local gl = G(lv.L, "Live state")
			local rows: { [string]: TextLabel } = {}
			for _, key in ipairs({ "Build", "Self-test", "Integrity", "Hooks", "Steps", "Errors", "Frame", "Shots", "Spread", "Hit chance", "Trigger", "Settle", "Lock", "Teleport" }) do
				rows[key] = gl:stat(key)
			end
			UI.syncLazy(function()
				if not lv.scroll.Visible then
					return
				end
				local hooks = {}
				for k, v in pairs(S.hooks.installed) do
					table.insert(hooks, (if v then "" else "!") .. k)
				end
				table.sort(hooks)
				rows.Build.Text = ("v%s · loaded %.0fs ago · place %s"):format(VERSION, os.clock() - (genv().CenterraLoadedAt or os.clock()), tostring(game.PlaceId))
				local st = S.selfTestResult
				rows["Self-test"].Text = if st then ("%d/%d%s · %.0fs ago"):format(st.pass, st.total, if #st.failed > 0 then " FAILED: " .. table.concat(st.failed, ", ") else " ok", os.clock() - st.at) else "pending (runs 4 s after load)"
				rows["Self-test"].TextColor3 = if st and #st.failed > 0 then C.danger else C.text
				local ii = S.integrityIssues
				rows.Integrity.Text = if ii and #ii > 0 then table.concat(ii, "; ") else ("clean · perf tier %d (%.1f ms)"):format(S.perfTier or 0, S.perfEma or 0)
				rows.Integrity.TextColor3 = if ii and #ii > 0 then C.danger else C.text
				rows.Hooks.Text = table.concat(hooks, " ")
				local steps, paused = 0, {}
				for k, rec in pairs(S.stepState or {}) do
					steps += rec.n or 0
					if rec.pausedUntil and os.clock() < rec.pausedUntil then
						table.insert(paused, k)
					end
				end
				rows.Steps.Text = ("%d error(s) this window%s"):format(steps, if #paused > 0 then " · PAUSED: " .. table.concat(paused, ", ") else "")
				local errs = {}
				for k, n in pairs(S.errCounts or {}) do
					table.insert(errs, k .. "×" .. n)
				end
				rows.Errors.Text = if #errs > 0 then table.concat(errs, " ") else "none"
				local topSteps = {}
				for k, v in pairs(S.stepMs or {}) do
					table.insert(topSteps, { k, v })
				end
				table.sort(topSteps, function(a, b)
					return a[2] > b[2]
				end)
				local topStr = {}
				for i = 1, math.min(4, #topSteps) do
					table.insert(topStr, ("%s %.2f"):format(topSteps[i][1], topSteps[i][2]))
				end
				rows.Frame.Text = ("%.1f ms/frame · top: %s"):format(S.frameMs or 0, table.concat(topStr, ", "))
				local ss = S.shotStats
				local de, dd = S.dmgExpected or 0, S.dmgDealt or 0
				rows.Shots.Text = ("%d · hit %d · blocked %d · air %d · confirmed %d · dropped %d · dmg %d/%d (%d%% landed)"):format(ss.redirected, ss.hitTarget, ss.hitOther, ss.miss, ss.confirmed, ss.dropped, math.floor(dd), math.floor(de), if de > 0 then math.floor(dd / de * 100 + 0.5) else 0)
				rows.Spread.Text = ("weapon %.2f° · measured avg %s° · straightened %d"):format(Combat.currentSpreadDeg(), if S.spreadAvg then ("%.2f"):format(S.spreadAvg) else "—", S.straightened or 0)
				rows["Hit chance"].Text = if S.silentTarget then ("%d%%"):format(math.floor(Combat.hitChance() + 0.5)) else "— (no lock)"
				rows.Trigger.Text = ("%s → %s · used %s%s"):format(cfg.fireMethod, tostring(S.fireLevel and S.fireLevel()), Input.fireMethodUsed, if Input.fireHeld() then " · HELD" else "")
				rows.Settle.Text = ("%d ms (ping %d)"):format(math.floor(Combat.settleSec() * 1000), S.pingMs or 0)
				rows.Lock.Text = if S.silentTargetModel then ("%s · %s · visible %s"):format(S.silentTargetModel.Name, tostring(S.silentPart and S.silentPart.Name), tostring(S.targetVisible)) else "—"
				rows.Teleport.Text = ("teleported %s · magic %s · autokill %s"):format(tostring(S.teleported), tostring(Combat.magic.active), tostring(S.autokill.state))
			end)
			-- the live readouts that used to sit between the everyday rows of the combat pages; one getter
			-- per row so a failing one leaves the others updating
			local DETAILS: { { any } } = {
				{ "Weapon", function(): string
					local gs = S.gameState or {}
					local wname = tostring(gs.weapon or "—")
					return ("%s · ammo %s · hp %s · aiming %s · ping %d ms"):format(
						wname,
						if gs.ammo then tostring(gs.ammo) .. (if gs.maxAmmo then "/" .. tostring(gs.maxAmmo) else "") else "—",
						if gs.hp then tostring(math.floor(gs.hp)) else "—",
						if gs.aiming then "yes" else "no",
						Game.pingMs()
					)
				end },
				{ "Rapid fire", function(): string
					local wname = tostring((S.gameState or {}).weapon or "")
					if wname ~= "" and wname ~= "—" then
						local fs = Combat.fireStats
						return ("%s · you see ×%.2f · server gets ×%.2f%s · jitter %d ms · sent %d / on screen only %d"):format(wname, Combat.rapidMult(wname), Combat.rapidServerMult(wname), if cfg.rapidFloorSafe[wname] then " (learned)" else " (default)", S.jitterMs or 0, fs.sent, fs.client)
					end
					local n = 0
					for _ in pairs(cfg.rapidFloorSafe) do
						n += 1
					end
					return ("%d learned floor(s)"):format(n)
				end },
				{ "Hitbox", function(): string
					return if S.silentPart then ("%s%s · spread %.2f°"):format(S.silentPart.Name, if S.dynamicBody then " (dynamic body)" else "", Combat.currentSpreadDeg()) else "no lock"
				end },
				{ "Lead", function(): string
					return ("learned %s · %s"):format(if cfg.leadLearnedMs >= 0 then cfg.leadLearnedMs .. " ms" else "nothing yet", Combat.leadSummary and Combat.leadSummary() or "")
				end },
				{ "Trigger wait", function(): string
					local hc = S.lastHitChance or (if S.silentTarget then Combat.hitChance() else nil)
					return (if hc then ("hit chance %d%%"):format(math.floor(hc + 0.5)) else "no lock") .. (if S.triggerWait then " · waiting: " .. tostring(S.triggerWait) else "")
				end },
				{ "Melee", function(): string
					local prof = Game.weaponProfile()
					local armed = if S.backstabReady then " · BACKSTAB ARMED" else ""
					if prof.melee then
						local d = Combat.targetDistance()
						return ("%s · reach %.0f st · target %s%s"):format(prof.name, Combat.meleeReach(prof.item), if d then ("%.1f st"):format(d) else "—", armed)
					end
					local knife = Combat.quickMeleeItem()
					return ("quick melee %s · reach %.0f st%s%s"):format(if knife then tostring(knife.Name) else "none", Combat.meleeReach(knife), if S.quickMeleeReady then " · IN REACH" else "", armed)
				end },
				{ "Autokill", function(): string
					return Combat.autokillStatus() or ("idle · last: " .. tostring(S.autokill.reason or "—"))
				end },
				{ "Hiding", function(): string
					local D = Combat.def
					return if D.state == "hide" then ("in %s (%s) · %d hides"):format(tostring(D.kind), tostring(D.reason), D.hides) else ("idle · %d hides"):format(D.hides)
				end },
				{ "Bounds", function(): string
					local Bounds = S.bounds
					local here = Bounds.here
					if here and here.lethal then
						return ("IN %s · %.1f s left"):format(tostring(here.part and here.part.Name or "?"), Bounds.secondsLeft() or 0)
					end
					return ("%d volume(s) · guard %s · swallowed %d"):format(Bounds.n or 0, if S.hooks.installed.oob then "ok" else "not installed", S.oobSwallowed or 0)
				end },
				{ "Anti-aim", function(): string
					local d = Combat.aaServerDelta()
					local echo = S.aaServerRot
					return ("server %s · off by %s · body %s%s%s"):format(
						if typeof(echo) == "Vector2" then ("%d°"):format(math.floor(math.deg(echo.Y) + 0.5)) else "—",
						if d then ("%d°"):format(math.floor(math.deg(d) + 0.5)) else "—",
						tostring(S.bodyYawMode or "real"),
						if cfg.aaMode == "Auto" and S.aaAutoMode then " · auto " .. S.aaAutoMode else "",
						if Combat.aaSends then (" · %d sent"):format(Combat.aaSends) else ""
					)
				end },
				{ "Resolver", function(): string
					local flagged = {}
					for _, f in ipairs(Game.enemies()) do
						local _, model = Game.fighterBody(f)
						local tag = if model then Resolver.tag(model) else ""
						if tag ~= "" then
							table.insert(flagged, Game.fighterName(f):sub(1, 12) .. " " .. tag)
							if #flagged >= 4 then
								break
							end
						end
					end
					return if #flagged > 0 then table.concat(flagged, " · ") else "no flags"
				end },
				{ "Katana", function(): string
					local f = S.silentFighter
					if not f then
						return "no lock"
					end
					return ("blade out %s · deflecting %s%s"):format(tostring(Game.enemyHasKatanaOut(f)), tostring(Combat.enemyDeflecting(f)), if S.katanaHold then " · FIRE HELD" else "")
				end },
				{ "Network", function(): string
					local n = S.net
					if not n.available then
						return "RakNet unavailable"
					end
					return ("%s · hook %s · physics %s · blocked %d · delayed %d%s"):format(
						if n.enabled() then "enabled" else "disabled in Volt",
						if n.installed then "on" else "off",
						if n.physId then ("0x%02X"):format(n.physId) else "learning",
						n.blocked,
						n.delayed,
						if n.active() and n.choking() then " · CHOKING" else ""
					)
				end },
				{ "Targets", function(): string
					local bots, players = 0, 0
					for _, f in ipairs(Game.enemies()) do
						if f.IsBot then
							bots += 1
						else
							players += 1
						end
					end
					return ("%d player(s) · %d bot(s) · our cost %.1f ms · tier %d"):format(players, bots, S.frameMs or 0, S.perfTier or 0)
				end },
			}
			local gdt = G(lv.L, "Live details")
			for _, d in ipairs(DETAILS) do
				d[3] = gdt:stat(d[1])
			end
			UI.syncLazy(function()
				if not lv.scroll.Visible then
					return
				end
				for _, d in ipairs(DETAILS) do
					local ok, s = pcall(d[2])
					local txt = if ok then tostring(s) else "—"
					if d[3].Text ~= txt then
						d[3].Text = txt
					end
				end
			end)
			local gq = G(lv.R, "Quick actions")
			gq:button("Copy state summary", function()
				local text = Dbg.summary()
				if EXEC.setclipboard then
					pcall(EXEC.setclipboard, text)
				end
				for line in text:gmatch("[^\n]+") do
					log("INFO", line)
				end
				notify("summary → log + clipboard", 2, "ok")
			end, C.accent)
			gq:button("Trace shot-code raycasts (10 s)", function()
				Dbg.traceRays(10)
			end)
			gq:button("Reset shot stats", Dbg.resetStats)
			gq:toggle("Remote spy (log FireServer while shooting)", "remoteSpy")
			gq:toggle("DEBUG lines to the executor console", "debugConsole", { desc = "By default DEBUG only reaches the F9 terminal and the log file" })
			gq:toggle("Write log file (centerra/centerra.log)", "logToFile")
			gq:button("Open F9 terminal", function()
				if S.setTerminal then
					S.setTerminal(true)
				end
			end)
			gq:note("Everything here is read-only for the game. Dumps go to the F9 terminal, the log file and the clipboard.", { height = 30 })
			-- v5.2 menu pass: the engine internals that used to sit between the everyday rows on the Silent
			-- and Rage tabs. All default to the measured answer; they are here for range experiments.
			local gin = G(t.Internals.L, "Internals (silent layers · trigger cadence · settle)")
			gin:note("Every row here defaults to what the live measurements picked. Turn one off only to reproduce a problem — nothing here makes shots land better.", { height = 30 })
			gin:toggle("Silent layer 0 — camera data", "silentCameraData", { desc = "Gun.StartShooting replicates ClientFighter:GetCameraData(); the table is answered aimed at the locked hitbox (decompile-verified, the layer that lands)" })
			gin:toggle("Silent layer 3 — replicated rotation", "silentSpoofServer", { desc = "The rotation channel (UpdateCameraRotation) faces the lock while a shot can leave; anti-aim cover between shots" })
			gin:toggle("Silent layer 4 — raycast redirect", "silentRaycastLayer", { desc = "The shot-code raycast itself is turned onto the lock (client-side tracers / hit markers agree with the server)" })
			gin:toggle("Game-style pulses (Start + Finish 30 ms)", "autoShootPulse", { desc = "Exactly the sequence the game's own auto shoot uses; hold-type items (Flamethrower) stay held" })
			gin:toggle("Fire on the item's own cooldown stamp", "autoShootCooldownSync", { desc = "Pull the moment item._shoot_cooldown expires — never early (rejected), never late" })
			gin:toggle("Server-safe cadence", "autoShootServerSafe", { desc = "Pull the trigger at the weapon's real cooldown even with rapid fire on — faster pulls are shots the server never accepts" })
			gin:toggle("Game-loop fire for automatics", "autoShootSpam", { desc = "Automatic guns: StartShooting every frame like the game's held LMB (queued to the cooldown edge) instead of the pulse loop (6 pulls/s on a 60 ms cooldown). Semi-autos keep the pulse path" })
			gin:cycle("Trigger method", "fireMethod", { "Auto", "Game", "VIM", "Executor" }, { desc = "Game = MechanicsController:EquippedItemInput(StartShooting), what the game's own mobile buttons call. Auto starts there and falls back to VIM / executor click", onChange = function()
				Combat.resetFireEscalation()
			end })
			gin:toggle("Ping-aware settle (auto)", "settleAuto", { desc = "After a teleport no faked shot leaves before ping/2 + 50 ms (+ the learned extra) — the main cause of misses after a hop" })
			gin:slider("Settle gate (ms)", "silentSettleMs", 0, 400, 10, { desc = "Manual settle when the auto one is off", fmt = function(n)
				return tostring(math.floor(n))
			end })
			local gnb = G(t.Internals.R, "Measured: no benefit (kept for experiments)")
			gnb:note("Each of these was measured in live duels and found to cost more than it gave — they default off. The learners and shot recorder keep working without them.", { height = 30 })
			gnb:toggle("Echo-gated first shot", "autoShootEchoGate", { desc = "Fire only once the server echoes our target-facing rotation. v5.0.5 duel data: the server fires along the aim carried WITH the shot (0.0° deviation) while the echo sat 7–126° away — the gate only delayed the first round" })
			gnb:slider("Echo wait", "autoShootLeadMaxMs", 60, 1500, 10, { unit = "ms", desc = "Longest wait for the server echo before the first shot.", fmt = function(n)
				return tostring(math.floor(n))
			end })
			gnb:slider("First-shot delay", "autoShootLeadMs", 0, 300, 10, { unit = "ms", desc = "Fixed first-shot delay when the echo gate is off (0 = none)", fmt = function(n)
				return tostring(math.floor(n))
			end })
			gnb:cycle("Backtrack learner", "backtrackMode", { "Off", "Auto" }, { desc = "Display only: Auto learns the server's rewind delay for Debug → Shots. Layer 0 aims at the LIVE hitbox (the server resolves part + offset on its own position), so a rewound aim landed short of every runner" })
			local btNote = gnb:note("", { height = 16 })
			UI.syncLazy(function()
				local bt = S.backtrack or {}
				btNote.Text = ("learned delay %d ms · %d samples · shots hit %d / near %d / no-reply %d"):format(math.floor((bt.delayMs or 0) + 0.5), bt.samples or 0, S.shots.stats.hit, S.shots.stats.near, S.shots.stats.noReply)
			end)
			gnb:multiselect("Shot callers", "shotCallers", { "MechanicsController", "Gun", "Item" }, { desc = "Scripts whose camera / mouse / raycast reads get the target-facing answer. v5.2 learns the real ones from every shot (Adapt); this list is the seed", onChange = function(set)
				S.h.shotCallers = set
			end })

			local ins = t.Inspect
			local gi = G(ins.L, "Dumps")
			gi:button("Held weapon: item + Info", Dbg.dumpWeapon)
			gi:button("Local fighter: fields + methods", Dbg.dumpFighter)
			gi:button("Enemy model: parts, hitboxes, collision groups", Dbg.dumpEnemyModel)
			gi:button("Config (cfg)", function()
				Dbg.dump("cfg", cfg, { methods = false })
			end)
			gi:button("CenterraState keys", function()
				Dbg.dump("CenterraState", S, { skipFunctions = true, methods = false })
			end)
			local gp2 = G(ins.R, "Game facts (verified)")
			gp2:note("Shots: MechanicsController → GetCameraData → GetCameraCFrame → GetMouseLocation → workspace:Raycast(origin, dir≈1000, Include{map, <enemy>.HitboxHead/HitboxBody, <enemy model>}).", { height = 44 })
			gp2:note("Hit detection uses <model>.HitboxHead / HitboxBody (+Small). Aim there — the visual Head is smaller.", { height = 30 })
			gp2:note("Gun cooldown / reload stamps use tick(). Info tables are shared with ItemLibrary.Items[name] — edits reach live guns.", { height = 30 })
			gp2:note("Health: fighter:GetHealth(). Humanoid.Health also replicates for confirms.", { height = 16 })
			gp2:note("Inside a __namecall hook never call a method before the original runs — it clobbers the pending method name (GetNetworkPing-on-Workspace bug).", { height = 44 })

			local dc = t.Decompile
			local gd = G(dc.L, "Pseudo-decompiler")
			local modList: { string } = {}
			local lastList = 0
			local function getList(): { string }
				if os.clock() - lastList > 5 or #modList == 0 then
					lastList = os.clock()
					modList = Dbg.modules()
				end
				return modList
			end
			gd:picker("Module", getList, "debugModuleIdx", function() end)
			gd:button("Decompile selected", function()
				local list = getList()
				local entry = list[cfg.debugModuleIdx or 1]
				if entry then
					task.spawn(Dbg.decompile, entry)
				end
			end, C.accent, { desc = "The source goes to the clipboard and centerra/decompiled/." })
			gd:note("Volt: decompile() returns real source (ClientFighter is VM-obfuscated, everything else reads clean). Wave cannot read this bytecode, so the pseudo listing (constants, upvalue kinds, nested closures) is appended either way. '·' marks modules the game has not loaded yet (never required first).", { height = 58 })
			local gq2 = G(dc.R, "Quick decompiles")
			for _, nm in ipairs({ "MechanicsController", "CameraController", "FighterController", "PlayerDataController", "M/Gun", "M/Fighter", "RS/ItemLibrary", "RS/CosmeticLibrary" }) do
				gq2:button(nm, function()
					task.spawn(Dbg.decompile, nm)
				end)
			end
		end

		-- Interface --------------------------------------------------------------
		do
			local t = Menu.addTab("Interface", { "Menu", "HUD" })
			local s = t.Menu
			local gm = G(s.L, "Menu", { simple = true })
			gm:cycle("Mode", "uiMode", { "Simple", "Advanced" }, { desc = "Simple shows the everyday options. Advanced adds every fine-tuning setting and the Debug page. Switching never changes a setting.", onChange = function(v)
				UI.setMode(v)
			end })
			gm:keybind("Menu key", "menuKey", { desc = "Ctrl+O always opens the menu too." })
			-- whole-pixel re-layout (never a fractional UIScale, which blurs every line and glyph)
			gm:cycle("Menu size", "menuScale", { 0.9, 1, 1.1, 1.25 }, { fmt = function(v)
				return ("%d%%"):format(math.floor((tonumber(v) or 1) * 100 + 0.5))
			end, onChange = function()
				task.defer(Menu.rebuild)
			end })
			gm:toggle("Blur the game behind", "menuBlur", { desc = "Costs some FPS on weak PCs." })
			gm:slider("Blur strength", "menuBlurSize", 4, 30, 1, { fmt = int })
			gm:toggle("Preview panel", "previewPane", { desc = "The hitbox and ESP preview next to the menu. Off moves the ESP preview onto its own Players page.", onChange = function()
				task.defer(Menu.rebuild)
			end })
			gm:toggle("Hide ESP while the menu is open", "espHideInMenu")
			local gdv = G(s.L, "Device", { simple = true })
			gdv:cycle("Device", "deviceSpoof", { "Real", "Mobile", "Controller", "VR" }, { desc = "What the server and other players see you playing on. Your mouse, keyboard, the menu and aim keep working either way. Only during a duel: the lobby always reports your real device.", onChange = function()
				Combat.deviceApply()
			end })
			gdv:info("Reported now", function()
				return S.deviceMode or "Real"
			end)
			local glk = G(s.L, "Look")
			local function customAccentChanged()
				if cfg.theme == "Custom" then
					task.defer(Menu.applyTheme)
				end
			end
			glk:cycle("Accent", "theme", THEME_ORDER, { desc = if S.edition == "max" then "The look of the menu and HUD. Max starts in toxic. The Max looks (Cute, Pride, Trans, Femboy, Xmas, Matcha) bring their own logo, colors, MAX tag and effects. A pick here stays for Max." else "The highlight color of the menu and HUD.", onChange = function()
				if S.edition == "max" then
					cfg.maxTheme = cfg.theme
				end
				task.defer(Menu.applyTheme)
			end })
			if S.edition == "max" then
				glk:toggle("Theme effects", "themeFx", { desc = "Max looks: hearts, paws, snow or leaves drifting behind the menu, and a burst from the intro logo.", onChange = function()
					task.defer(Menu.rebuild)
				end })
			end
			glk:color("Custom accent", "colAccent", { desc = "Used when Accent is set to Custom.", onClose = customAccentChanged })
			glk:color("Custom accent, dark", "colAccent2", { desc = "The deep end of the Custom accent's gradients.", onClose = customAccentChanged })
			glk:slider("Glow", "uiGlow", 0, 100, 5, { unit = "%", fmt = int, desc = "The soft light around active switches, the selection, the window edge and the logo.", onChange = function()
				UI.refreshGlows(Menu.gui)
			end })
			glk:slider("Tab list glass", "railGlass", 0, 40, 2, { unit = "%", fmt = int, desc = "How much of the game shows through the tab list's acrylic. 0 = solid. Obsidian and toxic are always solid.", onChange = function()
				Menu.applyGlass()
			end })
			glk:toggle("Intro animation", "introAnim", { desc = "Plays once when centerra loads." })
			glk:button("Play the intro", function()
				Menu.set(false)
				task.delay(0.2, function()
					if S.playIntro then
						S.playIntro()
					end
				end)
			end)
			local gk = G(s.R, "Keys", { simple = true })
			gk:info("Open the menu", function()
				return Input.keyLabel(cfg.menuKey) .. " or Ctrl+O"
			end)
			gk:info("Aim", function()
				return Input.keyLabel(cfg.aimKey)
			end)
			gk:info("Bind any switch", function()
				return "Right-click it"
			end)
			gk:info("Console", function()
				return "F9"
			end)
			local gp2 = G(s.R, "Panic", { simple = true })
			-- two clicks: one stray click must never switch every feature off
			local armedUntil = 0
			local panicBtn: TextButton
			panicBtn = gp2:button("Turn everything off", function()
				local now = os.clock()
				if now < armedUntil then
					armedUntil = 0
					panicBtn.Text = "Turn everything off"
					Menu.panicAll()
					return
				end
				armedUntil = now + 3
				panicBtn.Text = "Click again to turn everything off"
				task.delay(3, function()
					if os.clock() >= armedUntil and panicBtn.Parent then
						panicBtn.Text = "Turn everything off"
					end
				end)
			end, C.danger, { desc = "Every combat feature, weapon and movement mod and anti-aim off at once. Skins and the menu stay. Click twice." })

			local hu = t.HUD
			local gi = G(hu.L, "On screen", { simple = true })
			gi:slider("HUD size", "hudScale", 0.7, 1.6, 0.05, { fmt = function(n)
				return ("%d%%"):format(math.floor(n * 100 + 0.5))
			end, desc = "Size of everything on screen outside the menu: the combat bar, the status line, watermark, keybinds, messages and the kill list. The menu has its own size under Interface → Menu.", onChange = function()
				if S.hud and S.hud.applyScale then
					S.hud.applyScale()
				end
			end })
			gi:toggle("Watermark", "hud", { desc = "One small line with the name, FPS and ping." })
			gi:toggle("Keybind list", "showBinds", { desc = "Your bound keys and whether each one is on." })
			gi:toggle("Active features", "indicators", { desc = "A compact list of what's on, at the right edge." })
			gi:toggle("Combat bar", "combatBar", { desc = "A small bar above the crosshair while autokill runs: its step (moving in, aiming, firing, hiding), the target, hits and a timer. Voidspam shares it (Ragebot → Voidspam → Timer on screen)." })
			gi:toggle("Status line", "awarenessHud", { desc = "One short line under the crosshair when something needs you: fire held, out of bounds, target immune." })
			gi:toggle("Reload and danger", "statusSituation", { desc = "Adds the reload countdown and your danger level (enemies near, exposed) to the status line." })
			gi:toggle("Anti-aim check", "statusAa", { advanced = true, desc = "Adds whether the server holds your fake angle to the status line." })
			local gn = G(hu.L, "Messages")
			gn:toggle("Pop-up messages", "toasts", { desc = "Short confirmations in the corner. Warnings and errors always show." })
			gn:toggle("Kill list", "killFeed", { desc = "Your recent kills in the top-right corner." })
			local gl = G(hu.R, "Layout", { simple = true })
			gl:button("Arrange HUD", function()
				Menu.set(false)
				task.delay(0.15, function()
					if S.setHudEdit then
						S.setHudEdit(true)
					end
				end)
			end, C.accent, { desc = "Drag any panel where you want it. Press Esc or Done when finished." })
			gl:button("Reset layout", function()
				if S.hud and S.hud.resetLayout then
					S.hud.resetLayout()
				end
			end)
			local gt = G(hu.R, "Console")
			gt:button("Open the console (F9)", function()
				cfg.terminal = not cfg.terminal
				if S.setTerminal then
					S.setTerminal(cfg.terminal)
				end
			end)
			gt:button("Copy logs", function()
				if EXEC.setclipboard then
					local lines = {}
					for _, e in ipairs(logBuffer) do
						table.insert(lines, ("[%s] %s"):format(e.level, e.text))
					end
					pcall(EXEC.setclipboard, table.concat(lines, "\n"))
					notify("Logs copied", 2, "ok")
				end
			end)

			local gtg = G(s.R, "Targets")
			gtg:toggle("Target bots", "targetBots", { desc = "Range dummies and bots count as enemies for every feature, so you can practice on them." })
			gtg:info("Tracking", function()
				local bots, players = 0, 0
				for _, f in ipairs(Game.enemies()) do
					if f.IsBot then
						bots += 1
					else
						players += 1
					end
				end
				return ("%d player(s), %d bot(s)"):format(players, bots)
			end, { advanced = false })
			local gpf = G(s.R, "Performance")
			gpf:toggle("Adaptive performance", "autoPerf", { desc = "Lightens ESP extras and the radar when your frame rate drops, and brings them back when it recovers." })
			gpf:toggle("Performance mode", "perfMode", { desc = "Always uses the lighter ESP: no tracers, skeleton or 3D box." })
			gpf:toggle("Weak PC mode", "lowSpec", { desc = "Lighter ESP, fewer targets, no menu blur or intro. Aiming and combat aren't affected." })
			gpf:toggle("Watchdog", "watchdog", { desc = "Pauses a feature that keeps failing instead of letting it spam errors." })
			gpf:info("Frame cost", function()
				return ("%.1f ms · tier %d"):format(S.frameMs or 0, S.perfTier or 0)
			end)
		end

		-- Config -----------------------------------------------------------------
		-- one file per config (centerra/configs/<name>.json); the list is what is on disk
		do
			local t = Menu.addTab("Config", { "Config" })
			local c = t.Config
			if not (Menu.cfgSel and Configs.exists(Menu.cfgSel)) then
				Menu.cfgSel = if Configs.active ~= "" then Configs.active else nil
			end
			local function sel(): string?
				local nm = Menu.cfgSel
				return if type(nm) == "string" and nm ~= "" then nm else nil
			end
			-- file details for the selection, re-read only when the selection or the file changes
			local meta: any = { name = nil }
			local function metaOf(nm: string?): any
				if nm ~= meta.name or meta.stale then
					local data = nm and Configs.read(nm)
					meta = { name = nm, saved = data and tonumber(data.saved), version = data and data.centerra, missing = nm ~= nil and data == nil }
				end
				return meta
			end
			local refreshList: any
			local function done(ok: boolean, msg: string, okText: string?)
				meta.stale = true
				notify(if ok then okText or msg else msg, if ok then 2 else 3, if ok then "ok" else "warn")
				if refreshList then
					refreshList()
				end
			end
			-- destructive buttons fire on a second click within 3 s; the first one says what it will do
			local armed: { [string]: number } = {}
			local function twice(id: string, btn: TextButton?, prompt: string, fn: () -> ())
				if armed[id] and os.clock() - armed[id] < 3 then
					armed[id] = nil
					fn()
					return
				end
				armed[id] = os.clock()
				if btn then
					local old = btn.Text
					btn.Text = prompt
					task.delay(3, function()
						if btn.Parent and btn.Text == prompt then
							btn.Text = old
						end
					end)
				end
			end

			local gl = G(c.L, "Configs", { simple = true })
			local nr = gl:custom(UI.M.rowButton, "config name")
			local box = Instance.new("TextBox")
			box.Size = UDim2.new(1, 0, 0, 26)
			box.AnchorPoint = Vector2.new(0, 0.5)
			box.Position = UDim2.new(0, 0, 0.5, 0)
			box.BackgroundColor3 = C.surface
			box.BorderSizePixel = 0
			UI.setFont(box, UI.F.body)
			box.TextSize = UI.M.value
			box.TextColor3 = C.text
			box.PlaceholderText = "Name for a new config"
			box.PlaceholderColor3 = C.muted
			box.Text = ""
			box.ClearTextOnFocus = false
			box.TextXAlignment = Enum.TextXAlignment.Left
			box.Parent = nr
			corner(box, 6)
			local boxStroke = stroke(box, C.edge, 0)
			padding(box, 0, 8, 0, 8)
			box.Focused:Connect(function()
				tween(boxStroke, TW_HOVER, { Color = C.accent })
			end)
			box.FocusLost:Connect(function()
				tween(boxStroke, TW_HOVER, { Color = C.edge })
			end)
			gl:buttonRow("config create import", {
				{ "Create", function()
					local ok, res = Configs.create(box.Text)
					if ok then
						Menu.cfgSel = res
						box.Text = ""
					end
					done(ok, res, "Created " .. res .. " from your current settings")
				end, C.accent },
				{ "Import", function()
					local ok, res = Configs.import()
					if ok then
						Menu.cfgSel = res
					end
					done(ok, res, "Imported as " .. res)
				end },
			}, { desc = "Create saves your current settings under the name above. Import makes a new config from one someone copied." })
			refreshList = gl:list("Saved configs", {
				height = 190,
				placeholder = "Search configs",
				items = function()
					local out = {}
					local dirty = Configs.isDirty()
					for _, nm in ipairs(Configs.list()) do
						local tags = {}
						if nm == Configs.active then
							table.insert(tags, if dirty then "active · unsaved" else "active")
						end
						if nm == Configs.startup then
							table.insert(tags, "on start")
						end
						table.insert(out, { id = nm, label = nm, sub = table.concat(tags, " · "), color = if nm == Configs.active then C.accent else nil })
					end
					return out
				end,
				selected = sel,
				onSelect = function(id: string)
					-- v6.4 a second click on the selected config loads it
					local again = Menu.cfgSel == id and os.clock() - (Menu.cfgClickAt or 0) < 1.5
					Menu.cfgSel, Menu.cfgClickAt = id, os.clock()
					if again then
						local ok, res = Configs.load(id)
						done(ok, res, "Loaded " .. res)
						if ok then
							Menu.afterConfigSwap()
						end
					end
				end,
			})
			gl:note("Click a config twice to load it.", {})
			if type(EXEC.listfiles) ~= "function" then
				gl:note("This executor can't list files, so only configs made in this session show up.", { color = C.warn })
			end

			local gs = G(c.R, "Selected config", { simple = true })
			gs:info("Config", function()
				local nm = sel()
				if not nm then
					return "Pick one from the list"
				end
				return if metaOf(nm).missing then nm .. " (file gone)" else nm
			end)
			gs:info("Last saved", function()
				local m = metaOf(sel())
				if not m.saved then
					return "—"
				end
				local ago = os.time() - m.saved
				return if ago < 60 then "Just now" elseif ago < 3600 then ("%d min ago"):format(ago // 60) elseif ago < 86400 then ("%d h ago"):format(ago // 3600) else os.date("%b %d", m.saved)
			end)
			local function picked(): string?
				local nm = sel()
				if not nm then
					notify("Pick a config from the list first", 2, "warn")
				end
				return nm
			end
			gs:buttonRow("config load save", {
				{ "Load", function()
					local nm = picked()
					if not nm then
						return
					end
					local ok, res = Configs.load(nm)
					done(ok, res, "Loaded " .. res)
					if ok then
						Menu.afterConfigSwap()
					end
				end, C.accent },
				{ "Save", function()
					local nm = picked()
					if not nm then
						return
					end
					local ok, res = Configs.save(nm)
					done(ok, res, "Saved your settings into " .. res)
				end },
			}, { desc = "Load replaces your settings with the config's. Save writes your current settings into it." })
			gs:buttonRow("config rename duplicate", {
				{ "Rename", function()
					local nm = picked()
					if not nm then
						return
					end
					local ok, res = Configs.rename(nm, box.Text)
					if ok then
						Menu.cfgSel = res
						box.Text = ""
					end
					done(ok, res, "Renamed to " .. res)
				end },
				{ "Duplicate", function()
					local nm = picked()
					if not nm then
						return
					end
					local ok, res = Configs.duplicate(nm)
					if ok then
						Menu.cfgSel = res
					end
					done(ok, res, "Copied to " .. res)
				end },
			}, { desc = "Rename uses the name typed on the left." })
			local rowC: { TextButton } = {}
			rowC = gs:buttonRow("config export delete", {
				{ "Export", function()
					local ok = Configs.export(sel())
					notify(if ok then "Copied to the clipboard" else "No clipboard on this executor", 2, if ok then "ok" else "warn")
				end },
				{ "Delete", function()
					local nm = picked()
					if not nm then
						return
					end
					twice("delete " .. nm, rowC[2], "Click again", function()
						local ok, res = Configs.delete(nm)
						if ok then
							Menu.cfgSel = nil
						end
						done(ok, if ok then res else "Could not delete " .. nm, "Deleted " .. nm)
					end)
				end, C.danger },
			}, { desc = "Export copies the config so someone can import it. Delete asks for a second click." })
			gs:buttonRow("config load on start", {
				{ "Load on start", function()
					local nm = picked()
					if not nm then
						return
					end
					if Configs.startup == nm then
						Configs.setStartup("")
						done(true, "", "Nothing loads on start now")
					else
						Configs.setStartup(nm)
						done(true, "", nm .. " loads every time centerra starts")
					end
				end },
			}, { desc = "The picked config loads each time centerra starts, instead of the settings from last time." })
			gs:info("Loads on start", function()
				return if Configs.startup ~= "" then Configs.startup else "Last settings"
			end)
			local gc = G(c.R, "Settings")
			gc:note("Every change saves by itself and survives a reinject. A config only changes when you save into it.")
			local resetBtns: { TextButton } = {}
			resetBtns = gc:buttonRow("reset to defaults", {
				{ "Reset to defaults", function()
					twice("reset", resetBtns[1], "Click again to reset", function()
						Configs.reset()
						Menu.afterConfigSwap()
						notify("Every setting is back to its default", 2, "info")
					end)
				end },
			})
			gc:button("Unload centerra", function()
				local unload = genv().CenterraUnload
				if unload then
					unload()
				end
			end, C.danger)
			local gu = G(c.R, "Updates")
			gu:toggle("Update automatically", "autoUpdate", { desc = "Installs a newer version by itself while you're in the lobby, never during a match." })
			gu:toggle("Game update warnings", "adaptToasts", { desc = "A message when a RIVALS update breaks something centerra relies on." })
			gu:button("Check for update", function()
				task.spawn(function()
					Game.adapt.checkUpdate(true)
				end)
			end)
			gu:button("Reload the latest version", function()
				Menu.set(false)
				Game.adapt.reloadLatest()
			end, C.accent)
			gu:info("Game checks", function()
				local A = Game.adapt
				if A.nBroken > 0 then
					return ("%d broken"):format(A.nBroken)
				end
				return ("%d of %d fine%s"):format(A.n - A.pending, A.n, if A.pending > 0 then (", %d waiting"):format(A.pending) else "")
			end, { advanced = false })
			gu:info("Broken", function()
				local A = Game.adapt
				return if A.nBroken > 0 then table.concat(A.brokenList(), ", ") else "Nothing"
			end)
			gu:button("Check the game again", function()
				local r = Game.adapt.verify("manual")
				notify(if r.broken == 0 then ("Game checks: %d of %d fine, %d waiting"):format(r.total - r.pending, r.total, r.pending) else ("Game checks: %d broken (%s)"):format(r.broken, table.concat(Game.adapt.brokenList(), "; "):sub(1, 90)), 5, if r.broken == 0 then "ok" else "warn")
			end)
			local gab = G(c.R, "About", { simple = true })
			gab:info("Version", function()
				local A = Game.adapt
				return ("v%s · build %s%s"):format(PUBLIC_VERSION, VERSION, if A.latestVersion and A.latestVersion ~= VERSION then (" (v%s available)"):format(A.latestVersion) else "")
			end)
			gab:info("Executor", function()
				return EXECUTOR_NAME
			end)
			gab:info("Config folder", function()
				return DATA.configs
			end)
			local compat = EXEC.report()
			if #compat == 0 then
				gab:note("Everything centerra uses is available on this executor.", { color = C.ok })
			else
				for _, line in ipairs(compat) do
					gab:note(line, { color = C.warn })
				end
			end
		end

		-- extension groups on the base pages (the Max module): marked Max, shown in Simple mode
		local function maxGroup(colFrame: GuiObject, title: string, opts: any?)
			local o = if opts then table.clone(opts) else {}
			o.max, o.simple = true, true
			return UI.group(colFrame, title, o)
		end
		for _, sec in ipairs(S.ext.sections) do
			local st = Menu.subs[sec.tab]
			local col = st and st[sec.sub] and st[sec.sub][if sec.side == "R" then "R" else "L"]
			if col then
				local okS, errS = pcall(sec.build, maxGroup, UI, col)
				if not okS then
					log("WARN", ("ext section %s: %s"):format(tostring(sec.id), tostring(errS)))
				end
			end
		end
		-- extension pages (the Max module): same builders as every page above
		for _, ext in ipairs(S.ext.tabs) do
			local okX, errX = pcall(ext.build, Menu.addTab, G, UI)
			if not okX then
				log("WARN", ("ext page %s: %s"):format(tostring(ext.id), tostring(errX)))
			end
		end
	end

	---------------------------------------------------------------------------
	-- window
	---------------------------------------------------------------------------
	-- Pages are laid out by hand in two columns; when one column ends up far taller than the other
	-- (a wall of groups beside dead space) its trailing groups move to the short column. Heights come
	-- from the rows themselves (everything is offset-sized), so this runs right after building,
	-- before any layout pass, and keeps the top groups of each column where they were designed.
	function Menu.groupHeight(g: any): number
		local h = 32 + 4 + 6 + 12 -- card header, gap under it, card bottom padding, spacing under the group
		for _, r in ipairs(g.rows) do
			if r.frame.Visible then
				h += math.max(r.base, if r.frame.AbsoluteSize.Y > 0 and r.isNote then r.frame.AbsoluteSize.Y else 0)
			end
		end
		return h
	end
	function Menu.balanceColumns()
		local byOrder = function(a: any, b: any)
			return a.frame.LayoutOrder < b.frame.LayoutOrder
		end
		local function height(list: { any }): number
			local h = 0
			for _, g in ipairs(list) do
				h += Menu.groupHeight(g)
			end
			return h
		end
		local moves = 0
		for _, st in pairs(Menu.subs) do
			for _, sc in pairs(st.frames) do
				local L, R = sc:FindFirstChild("L"), sc:FindFirstChild("R")
				if L and R then
					local cols: { [Instance]: { any } } = { [L] = {}, [R] = {} }
					for _, g in ipairs(UI.groups) do
						local p = g.frame.Parent
						if (p == L or p == R) and g.frame.Visible then
							table.insert(cols[p], g)
						end
					end
					table.sort(cols[L], byOrder)
					table.sort(cols[R], byOrder)
					local guard = 0
					while guard < 12 do
						guard += 1
						local hl, hr = height(cols[L]), height(cols[R])
						local tall, short = if hl >= hr then L else R, if hl >= hr then R else L
						local list = cols[tall]
						if #list < 2 then
							break
						end
						-- the group whose move brings the columns closest; trailing groups append to the
						-- short column, the column's lead group (its primary content) goes to the short
						-- column's top so it stays where the eye lands first
						local diff = math.abs(hl - hr)
						local bestIdx, bestDiff = nil, diff - 24
						for i = 1, #list do
							local gh = Menu.groupHeight(list[i])
							local after = math.abs(diff - 2 * gh)
							if after < bestDiff then
								bestIdx, bestDiff = i, after
							end
						end
						if not bestIdx then
							break -- nothing would clearly help
						end
						local g = table.remove(list, bestIdx)
						local minOrder, maxOrder = math.huge, 0
						for _, other in ipairs(cols[short]) do
							minOrder = math.min(minOrder, other.frame.LayoutOrder)
							maxOrder = math.max(maxOrder, other.frame.LayoutOrder)
						end
						if bestIdx == 1 then
							table.insert(cols[short], 1, g)
							g.frame.LayoutOrder = if minOrder == math.huge then 1 else minOrder - 1
						else
							table.insert(cols[short], g)
							g.frame.LayoutOrder = maxOrder + 1
						end
						g.frame.Parent = short
						moves += 1
					end
				end
			end
		end
		if moves > 0 then
			log("DEBUG", ("menu: balanced %d group(s) across columns"):format(moves))
		end
	end

	function Menu.build()
		if genv().CenterraLibrary then return end
		UI.resetRegistries()
		Menu.syncMarks = {}
		UI.syncTab = {} -- sync index → the page that registered it (nil = global)
		local gui = Instance.new("ScreenGui")
		gui.Name = "Centerra"
		gui.ResetOnSpawn = false
		gui.IgnoreGuiInset = true
		gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
		gui.DisplayOrder = 1000
		gui.Enabled = false
		if not Game.parentGui(gui) then
			error("could not parent the menu (PlayerGui, gethui and CoreGui all refused)")
		end
		Menu.gui = gui
		UI.gui = gui

		-- invisible and inert: clicks beside the window go to the game (only the window captures input)
		local backdrop = frame(gui)
		backdrop.Name = "Backdrop"
		backdrop.Size = UDim2.fromScale(1, 1)
		backdrop.BackgroundTransparency = 1
		backdrop.Active = false
		backdrop.Visible = false
		backdrop.ZIndex = 1
		Menu.backdrop = backdrop
		-- the real cursor, never a drawn one (a gui cursor trails the mouse by a render frame): the game
		-- frees and shows it itself while the menu is open (Hooks.installMenuMouse); UI.mouseTick corrects
		-- any camera that still locks it
		UI.cursor = nil
		if not UI.mouseBound then
			UI.mouseBound = true
			pcall(RunService.UnbindFromRenderStep, RunService, "centerra_menuMouse")
			pcall(RunService.BindToRenderStep, RunService, "centerra_menuMouse", Enum.RenderPriority.Last.Value, function()
				pcall(UI.mouseTick)
			end)
		end

		-- 820 × 520 at 100 %; Menu size re-lays everything out in whole pixels (UIScale stays 1)
		Menu.layout()
		local px = Menu.px
		-- inner width of one column (see the column comment in Menu.addTab: 0.5 × content − 30)
		UI.M.colW = math.floor((MENU_W - RAIL_W) / 2) - 30
		-- host = the window plus the docked side panel: dragged and shown as one
		local host = frame(gui)
		host.Name = "Host"
		host.AnchorPoint = Vector2.new(0.5, 0.5)
		host.Size = UDim2.new(0, MENU_W, 0, MENU_H)
		host.Position = UDim2.fromScale(0.5, 0.5)
		host.Visible = false
		host.ZIndex = 2
		Menu.host = host
		Menu.hostBase = nil
		Menu.panelShift = 0
		UI.popupHost = host

		-- the window is ONE layer (a translucent rail panel over a solid window would stack into a darker,
		-- opaque rail): a hard-stepped gradient paints the tab list in its acrylic tint and see-through
		-- amount and the content solid (Menu.applyGlass). Outside it: an accent edge, a hollow shadow and
		-- an accent aura — all static (a looping tween on a window-sized element costs every frame)
		local root = frame(host, Color3.new(1, 1, 1))
		root.Name = "Root"
		root.Size = UDim2.fromScale(1, 1)
		root.ZIndex = 1
		root.Active = true
		root.ClipsDescendants = false
		corner(root, 12)
		Menu.root = root
		UI.root = root
		Menu.loops = {}
		Menu.glassSplit = RAIL_W / MENU_W
		Menu.glassGrad = gradient(root, C.side, C.bg)
		do
			local edge = stroke(root, Color3.new(1, 1, 1), 0)
			local eg = Instance.new("UIGradient")
			eg.Rotation = 35
			local lookFx = UI.themeFx()
			eg.Color = if lookFx
				then UI.fxSeq(lookFx.flag)
				else ColorSequence.new({
					ColorSequenceKeypoint.new(0, C.accent),
					ColorSequenceKeypoint.new(0.35, C.edge),
					ColorSequenceKeypoint.new(0.7, C.edge),
					ColorSequenceKeypoint.new(1, C.accent2),
				})
			eg.Parent = edge
			if not lookFx and UI.metalEdge(edge) then
				Menu.loop(eg, TweenInfo.new(30, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, -1), { Rotation = 395 })
			end
			-- 22 px: the docked panel sits 14 px away and the falloff must be nearly gone by then
			UI.softShadow(root, "Shadow", Color3.new(0, 0, 0), 0.45, 22)
			UI.softShadow(root, "Aura", C.accent, UI.glowAlpha(0.4), 20)
		end
		-- a visible Modal button frees the cursor even while the game locks it (no camera freeze needed)
		local mouseFree = Instance.new("TextButton")
		mouseFree.Name = "MouseFree"
		mouseFree.Modal = true
		mouseFree.Text = ""
		mouseFree.AutoButtonColor = false
		mouseFree.BackgroundTransparency = 1
		mouseFree.Size = UDim2.fromOffset(1, 1)
		mouseFree.Visible = S.menuOpen == true
		mouseFree.Parent = root
		Menu.mouseFree = mouseFree
		-- open / close fade: a sheet of the window's own colour over everything, faded by Menu.slide
		local curtain = frame(root, C.bg)
		curtain.Name = "Curtain"
		curtain.Size = UDim2.fromScale(1, 1)
		curtain.ZIndex = 60
		curtain.Visible = false
		corner(curtain, 12)
		Menu.curtain = curtain

		-- sidebar: logo, pages by section, user card — a container on the window's acrylic rail, coloured
		-- by an accent → deep-accent wash with grain, two soft lights (accent behind the logo, the deep
		-- accent low down) and an accent edge. The wash runs 12 px past the rail so its rounded right
		-- corners are clipped away (the rail is square on the content side).
		local side = frame(root)
		side.Name = "Sidebar"
		side.Size = UDim2.new(0, RAIL_W, 1, 0)
		side.ZIndex = 2
		side.ClipsDescendants = true
		corner(side, 12)
		do
			local wash = frame(side, Color3.new(1, 1, 1))
			wash.Name = "AcrylicWash"
			wash.Size = UDim2.new(1, 12, 1, 0)
			wash.ZIndex = 2
			wash.Active = false
			corner(wash, 12)
			local wg = gradient(wash, C.accent, C.accent2, 90)
			local washFx = UI.themeFx()
			if washFx then
				wg.Color = UI.fxSeq(washFx.flag)
			elseif UI.metal then
				wg.Color = ColorSequence.new(UI.metal.lite, UI.metal.mid)
			end
			wg.Transparency = if UI.metal and not washFx
				then NumberSequence.new({
					NumberSequenceKeypoint.new(0, 0.9),
					NumberSequenceKeypoint.new(0.45, 0.975),
					NumberSequenceKeypoint.new(1, 0.93),
				})
				else NumberSequence.new({
					NumberSequenceKeypoint.new(0, 0.8),
					NumberSequenceKeypoint.new(0.45, 0.94),
					NumberSequenceKeypoint.new(1, 0.84),
				})
			UI.acrylic(wash, { light = 0, grain = 0.96, radius = 12, z = 2 })
			-- the lights sit far enough in that their falloff ends before the window's rounded corners
			-- (the rail clips rectangles, not UICorner shapes: a light near a corner glowed past it)
			if UI.glowRadial then
				for _, spec in ipairs({ { C.accent, 0.72, math.floor(RAIL_W * 0.55), px(80), px(240), px(190) }, { C.accent2, 0.8, px(170), MENU_H - px(90), px(260), px(260) } }) do
					local bleed = Instance.new("ImageLabel")
					bleed.Name = "AcrylicBleed"
					bleed.BackgroundTransparency = 1
					bleed.Image = UI.glowRadial
					bleed.ImageColor3 = spec[1]
					bleed.ImageTransparency = spec[2]
					bleed.AnchorPoint = Vector2.new(0.5, 0.5)
					bleed.Position = UDim2.fromOffset(spec[3], spec[4])
					bleed.Size = UDim2.fromOffset(spec[5], spec[6])
					bleed.ZIndex = 3
					bleed.Parent = side
				end
			end
		end
		local sideHair = frame(root, Color3.new(1, 1, 1))
		sideHair.Size = UDim2.new(0, 1, 1, 0)
		sideHair.Position = UDim2.new(0, RAIL_W, 0, 0)
		sideHair.ZIndex = 4
		gradient(sideHair, C.accent, C.hairline, 90).Transparency = NumberSequence.new(0.2, 0)
		local LOGO_H = px(58)
		local logo = frame(side)
		logo.Name = "Logo"
		logo.Size = UDim2.new(1, 0, 0, LOGO_H)
		logo.ZIndex = 4
		logo.Active = true
		local gemPx = px(20)
		local gemHolder = frame(logo)
		gemHolder.Size = UDim2.fromOffset(gemPx, gemPx)
		gemHolder.AnchorPoint = Vector2.new(0, 0.5)
		gemHolder.Position = UDim2.new(0, px(18), 0.5, 0)
		gemHolder.ZIndex = 5
		-- a soft halo behind the face, kept low so the mark itself reads over it
		local gemGlow = UI.glow(gemHolder, 9, 0.45)
		gemGlow.ZIndex = 5
		Menu.loop(gemGlow, TweenInfo.new(2.6, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), { ImageTransparency = math.min(1, gemGlow.ImageTransparency + 0.15) })
		local gem = UI.logoMark(gemHolder, gemPx + 2, 45)
		gem.ZIndex = 6
		-- the wordmark: "centerra" in Montserrat, the 0 in the accent; Max adds its badge beside it
		local brandRow = frame(logo)
		brandRow.Name = "Brand"
		brandRow.Size = UDim2.new(1, -px(50), 1, 0)
		brandRow.Position = UDim2.new(0, px(46), 0, 0)
		brandRow.ZIndex = 5
		local brl = vlist(brandRow, px(7), true)
		brl.VerticalAlignment = Enum.VerticalAlignment.Center
		local wordSize = px(21)
		local word = label(brandRow, ("c<font color=\"#%s\">0</font>caine"):format(C.accent:ToHex()), wordSize, C.text, UI.HUD_BOLD)
		word.RichText = true
		word.AutomaticSize = Enum.AutomaticSize.None
		word.Size = UDim2.new(0, UI.gw("centerra", wordSize, true) + 2, 1, 0)
		word.LayoutOrder = 1
		word.ZIndex = 5
		if S.edition == "max" then
			local chip = UI.maxBadge(brandRow, px(16))
			chip.LayoutOrder = 2
			chip.ZIndex = 6
			for _, d in ipairs(chip:GetDescendants()) do
				if d:IsA("GuiObject") then
					d.ZIndex = 7
				end
			end
		end
		-- a band of the accent sweeps across the wordmark every few seconds
		do
			local shimmer = Instance.new("UIGradient")
			shimmer.Color = ColorSequence.new({
				ColorSequenceKeypoint.new(0, Color3.new(1, 1, 1)),
				ColorSequenceKeypoint.new(0.42, Color3.new(1, 1, 1)),
				ColorSequenceKeypoint.new(0.5, C.accent),
				ColorSequenceKeypoint.new(0.58, Color3.new(1, 1, 1)),
				ColorSequenceKeypoint.new(1, Color3.new(1, 1, 1)),
			})
			local shineFx = UI.themeFx()
			if shineFx then
				local kp = { ColorSequenceKeypoint.new(0, Color3.new(1, 1, 1)), ColorSequenceKeypoint.new(0.36, Color3.new(1, 1, 1)) }
				local n = #shineFx.flag
				for i, c in ipairs(shineFx.flag) do
					table.insert(kp, ColorSequenceKeypoint.new(0.4 + 0.2 * (i - 1) / (n - 1), c))
				end
				table.insert(kp, ColorSequenceKeypoint.new(0.64, Color3.new(1, 1, 1)))
				table.insert(kp, ColorSequenceKeypoint.new(1, Color3.new(1, 1, 1)))
				shimmer.Color = ColorSequence.new(kp)
			end
			if UI.metal and not shineFx then
				-- metal looks: the wordmark is lit metal (top light, a darker band, a bright line) and the band
				-- drifts slowly up and down, like the site's wordmark
				word.Text = "centerra"
				word.TextColor3 = Color3.new(1, 1, 1)
				shimmer.Rotation = 90
				shimmer.Color = ColorSequence.new({
					ColorSequenceKeypoint.new(0, UI.metal.hi),
					ColorSequenceKeypoint.new(0.34, UI.metal.hi:Lerp(UI.metal.lite, 0.6)),
					ColorSequenceKeypoint.new(0.48, UI.metal.lite:Lerp(UI.metal.mid, 0.3)),
					ColorSequenceKeypoint.new(0.58, UI.metal.hi),
					ColorSequenceKeypoint.new(0.78, UI.metal.hi:Lerp(UI.metal.lite, 0.5)),
					ColorSequenceKeypoint.new(1, UI.metal.hi),
				})
				shimmer.Offset = Vector2.new(0, -0.14)
				shimmer.Parent = word
				Menu.loop(shimmer, TweenInfo.new(6, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), { Offset = Vector2.new(0, 0.14) })
			else
				shimmer.Offset = Vector2.new(-1, 0)
				shimmer.Parent = word
				Menu.loop(shimmer, TweenInfo.new(1.8, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, false, 3.2), { Offset = Vector2.new(1, 0) })
			end
		end
		-- decoration only: a failure here must never cost the menu
		do
			local fxOk, fxErr = pcall(UI.fxMenu, root, side, px, Menu.loop)
			if not fxOk then
				log("WARN", "theme effects: " .. tostring(fxErr):sub(1, 120))
			end
		end

		-- top bar (over the content): preset + save on the left, search / panic / settings right
		local top = frame(root)
		top.Name = "TopBar"
		top.Size = UDim2.new(1, -RAIL_W, 0, HEADER_H)
		top.Position = UDim2.new(0, RAIL_W, 0, 0)
		top.ZIndex = 3
		top.Active = true
		local topHair = frame(top, C.hairline)
		topHair.Size = UDim2.new(1, 0, 0, 1)
		topHair.Position = UDim2.new(0, 0, 1, -1)
		topHair.ZIndex = 3
		local function topButton(w: number, x: number, anchorRight: boolean): TextButton
			local b = button(top, "", UI.M.value, C.dim, C.surface)
			b.Size = UDim2.fromOffset(px(w), px(28))
			b.AnchorPoint = Vector2.new(if anchorRight then 1 else 0, 0.5)
			b.Position = UDim2.new(if anchorRight then 1 else 0, px(x), 0.5, 0)
			b.ZIndex = 4
			corner(b, 6)
			stroke(b, C.edge, 0)
			return b
		end
		-- config picker: the active config, a quick load list and the way to the Config page
		local cfgBtn = topButton(140, 16, false)
		local cfgLbl = label(cfgBtn, "", UI.M.value, C.text, UI.F.body)
		cfgLbl.Size = UDim2.new(1, -30, 1, 0)
		cfgLbl.Position = UDim2.fromOffset(10, 0)
		cfgLbl.TextTruncate = Enum.TextTruncate.AtEnd
		cfgLbl.ZIndex = 5
		local cfgChev = icon(cfgBtn, "expand", 16)
		cfgChev.AnchorPoint = Vector2.new(1, 0.5)
		cfgChev.Position = UDim2.new(1, -5, 0.5, 0)
		cfgChev.ZIndex = 5
		recolourIcon(cfgChev, C.muted)
		local function syncCfgLabel()
			local t2 = if Configs.active ~= "" then Configs.active else "No config"
			if cfgLbl.Text ~= t2 then
				cfgLbl.Text = t2
			end
			cfgLbl.TextColor3 = if Configs.active ~= "" then C.text else C.muted
		end
		syncCfgLabel()
		table.insert(UI.sync, syncCfgLabel)
		cfgBtn.MouseButton1Click:Connect(function()
			local names = Configs.list()
			local shown = math.min(#names, 8)
			UI.openDropdown(cfgBtn, 180, function(f: Frame): number
				for i = 1, shown do
					local nm = names[i]
					UI.dropdownOption(f, 4 + (i - 1) * 24, nm, nm == Configs.active, function()
						UI.closeDropdown()
						local ok, res = Configs.load(nm)
						notify(if ok then "Loaded " .. res else res, if ok then 2 else 3, if ok then "ok" else "warn")
						if ok then
							Menu.afterConfigSwap()
						end
					end)
				end
				UI.dropdownOption(f, 4 + shown * 24, if #names > shown then "All configs…" else "Manage configs…", false, function()
					UI.closeDropdown()
					Menu.showTab("Config")
				end)
				return 8 + (shown + 1) * 24
			end)
		end)
		UI.tip(cfgBtn, "The config your settings came from. Pick another to load it, or manage them on the Config page.")
		local saveBtn = topButton(76, 164, false)
		local saveIc = icon(saveBtn, "save", 15)
		saveIc.AnchorPoint = Vector2.new(0, 0.5)
		saveIc.Position = UDim2.new(0, 10, 0.5, 0)
		saveIc.ZIndex = 5
		recolourIcon(saveIc, C.dim)
		local saveLbl = label(saveBtn, "save", UI.M.value, C.dim, UI.F.medium)
		saveLbl.Size = UDim2.new(1, -32, 1, 0)
		saveLbl.Position = UDim2.fromOffset(31, 0)
		saveLbl.ZIndex = 5
		-- unsaved-changes dot: the live settings differ from the active config's file
		-- (it flashes: a solid core and a ring that swells and fades, 1.5 times a second)
		local dirtyDot = frame(saveBtn, C.accent)
		dirtyDot.Size = UDim2.fromOffset(9, 9)
		dirtyDot.AnchorPoint = Vector2.new(0.5, 0.5)
		dirtyDot.Position = UDim2.new(1, -2, 0, 2)
		dirtyDot.ZIndex = 6
		dirtyDot.Visible = false
		corner(dirtyDot, 5)
		local dirtyRing = stroke(dirtyDot, C.accent, 0)
		table.insert(UI.sync, function()
			local d = Configs.isDirty()
			if dirtyDot.Visible ~= d then
				dirtyDot.Visible = d
			end
			if d then
				local wave = 0.5 + 0.5 * math.sin(os.clock() * math.pi * 3)
				dirtyDot.BackgroundTransparency = 0.45 * (1 - wave)
				dirtyRing.Color = dirtyDot.BackgroundColor3
				dirtyRing.Thickness = 1 + 4 * wave
				dirtyRing.Transparency = 0.25 + 0.75 * wave
			end
		end)
		saveBtn.MouseButton1Click:Connect(function()
			if Configs.active == "" then
				notify("Create a config first — your settings are kept either way", 3, "info")
				Menu.showTab("Config")
				return
			end
			local ok, res = Configs.save()
			notify(if ok then "Saved into " .. res else res, if ok then 2 else 3, if ok then "ok" else "warn")
		end)
		UI.tip(saveBtn, "Writes your current settings into the active config. The dot means there are changes it doesn't have yet.")
		-- metal looks: Save is a brushed key (dark ink); its hover lifts the metal's brightness
		if UI.brushed(saveBtn) then
			saveLbl.TextColor3 = UI.metal.ink
			recolourIcon(saveIc, UI.metal.ink)
			UI.setFont(saveLbl, UI.F.bold)
			saveBtn.BackgroundColor3 = Color3.fromRGB(228, 228, 232)
		end
		for _, b in ipairs({ cfgBtn, saveBtn }) do
			b.MouseEnter:Connect(function()
				tween(b, TW_HOVER, { BackgroundColor3 = if b == saveBtn and UI.metal then Color3.new(1, 1, 1) else C.card })
			end)
			b.MouseLeave:Connect(function()
				tween(b, TW_HOVER, { BackgroundColor3 = if b == saveBtn and UI.metal then Color3.fromRGB(228, 228, 232) else C.surface })
			end)
		end
		local function iconButton(name: string, x: number, hoverColor: Color3?): TextButton
			local b = button(top, "", 10, C.text, C.card)
			b.Size = UDim2.fromOffset(px(28), px(28))
			b.AnchorPoint = Vector2.new(1, 0.5)
			b.Position = UDim2.new(1, px(x), 0.5, 0)
			b.BackgroundTransparency = 1
			b.ZIndex = 4
			corner(b, 6)
			local ic = icon(b, name, px(17))
			ic.ZIndex = 5
			recolourIcon(ic, C.muted)
			b.MouseEnter:Connect(function()
				tween(b, TW_HOVER, { BackgroundTransparency = 0 })
				UI.tintIcon(ic, hoverColor or C.text, true)
			end)
			b.MouseLeave:Connect(function()
				tween(b, TW_HOVER, { BackgroundTransparency = 1 })
				UI.tintIcon(ic, C.muted, true)
			end)
			return b
		end
		local closeBtn = iconButton("close", -14)
		closeBtn.MouseButton1Click:Connect(function()
			Menu.set(false)
		end)
		UI.tip(closeBtn, "Close the menu (" .. Input.keyLabel(cfg.menuKey) .. ")")
		local settingsBtn = iconButton("Settings", -46)
		settingsBtn.MouseButton1Click:Connect(function()
			Menu.showTab("Interface")
		end)
		UI.tip(settingsBtn, "Interface: Simple / Advanced mode, accent, menu size, panic")
		local searchBox = frame(top, C.surface)
		searchBox.Size = UDim2.fromOffset(px(176), px(28))
		searchBox.AnchorPoint = Vector2.new(1, 0.5)
		searchBox.Position = UDim2.new(1, -px(82), 0.5, 0)
		searchBox.ZIndex = 4
		corner(searchBox, 6)
		local searchStroke = stroke(searchBox, C.edge, 0)
		local sIc = icon(searchBox, "search", 15)
		sIc.AnchorPoint = Vector2.new(0, 0.5)
		sIc.Position = UDim2.new(0, 9, 0.5, 0)
		sIc.ZIndex = 5
		recolourIcon(sIc, C.muted)
		local search = Instance.new("TextBox")
		search.Name = "Search"
		search.Size = UDim2.new(1, -38, 1, 0)
		search.Position = UDim2.fromOffset(30, 0)
		search.BackgroundTransparency = 1
		search.BorderSizePixel = 0
		UI.setFont(search, UI.F.body)
		search.TextSize = UI.M.value
		search.TextColor3 = C.text
		search.PlaceholderText = "search settings"
		search.PlaceholderColor3 = C.muted
		search.Text = ""
		search.ClearTextOnFocus = false
		search.TextXAlignment = Enum.TextXAlignment.Left
		search.ZIndex = 5
		search.Parent = searchBox
		search:GetPropertyChangedSignal("Text"):Connect(function()
			UI.search(search.Text)
		end)
		search.Focused:Connect(function()
			tween(searchStroke, TW_HOVER, { Color = C.accent })
		end)
		search.FocusLost:Connect(function()
			tween(searchStroke, TW_HOVER, { Color = C.edge })
		end)
		Menu.search = search
		-- the Simple / Advanced switch lives on the Settings page now
		function Menu.refreshModeSwitch() end

		-- content area (pages live here)
		local content = frame(root)
		content.Name = "Content"
		content.Size = UDim2.new(1, -RAIL_W, 1, -HEADER_H)
		content.Position = UDim2.new(0, RAIL_W, 0, HEADER_H)
		content.ClipsDescendants = true
		content.ZIndex = 3
		Menu.content = content
		-- the sheet Menu.reveal lifts off a page as it comes in (above every page, never catches input);
		-- rounded like the window so it never paints a square corner over the rounded bottom right
		do
			local pageCurtain = frame(content, C.bg)
			pageCurtain.Name = "PageCurtain"
			pageCurtain.Size = UDim2.fromScale(1, 1)
			pageCurtain.ZIndex = 40
			pageCurtain.Visible = false
			pageCurtain.Active = false
			corner(pageCurtain, 12)
			Menu.pageCurtain = pageCurtain
		end

		-- sidebar navigation: Combat / Visuals / Other with a caption each. A scrolling list that ends
		-- above the user card (it used to run under it: "Debug" drawn over the profile)
		local CARD_H = px(56)
		local nav = Instance.new("ScrollingFrame")
		nav.Name = "Nav"
		nav.Position = UDim2.new(0, 0, 0, LOGO_H)
		nav.Size = UDim2.new(1, 0, 1, -LOGO_H - CARD_H)
		nav.BackgroundTransparency = 1
		nav.BorderSizePixel = 0
		nav.ScrollBarThickness = 2
		nav.ScrollBarImageColor3 = C.faint
		nav.ScrollingDirection = Enum.ScrollingDirection.Y
		nav.AutomaticCanvasSize = Enum.AutomaticSize.Y
		nav.CanvasSize = UDim2.new(0, 0, 0, 0)
		nav.ZIndex = 4
		nav.Parent = side
		vlist(nav, 1)
		padding(nav, 0, 8, px(6), 8)
		-- the selection: one acrylic pill under the nav (a list layout would place it as an item), on a
		-- layer clipped to the nav's box. It glides between items with a stretch (UI.liquid) and snaps
		-- while the nav scrolls or a search re-lays the list.
		do
			local navClip = frame(side)
			navClip.Name = "NavSelection"
			navClip.Position = nav.Position
			navClip.Size = nav.Size
			navClip.ClipsDescendants = true
			navClip.ZIndex = 3
			-- a quiet solid highlight: a lighter surface with a hairline, no wash, no glowing edge strip
			local sel = frame(navClip, Color3.new(1, 1, 1))
			sel.Name = "Pill"
			sel.BackgroundTransparency = 0.93
			sel.Visible = false
			sel.ZIndex = 3
			corner(sel, 6)
			stroke(sel, Color3.new(1, 1, 1), 0.92)
			-- metal looks: the pill is a brushed metal key and the active item's text goes dark on it
			if UI.brushed(sel) then
				sel.BackgroundTransparency = 0
			end
			Menu.navSel = sel
			Menu.navLiquid = UI.liquid(sel, function(a: number, b: number)
				sel.Position = UDim2.fromOffset(Menu.navSelX or 8, a)
				sel.Size = UDim2.fromOffset(Menu.navSelW or (RAIL_W - 16), math.max(4, b - a))
			end)
			function Menu.placeNav(animate: boolean?)
				local d = Menu.tabBtns[Menu.activeTab]
				local item = d and d.item
				if not (item and item.Parent and item.Visible) then
					sel.Visible = false
					return
				end
				local rel = item.AbsolutePosition - navClip.AbsolutePosition
				local size = item.AbsoluteSize
				if size.Y < 1 then
					return -- not laid out yet (the gui is still disabled): Menu.set places it on open
				end
				Menu.navSelX, Menu.navSelW = rel.X, size.X
				sel.Visible = true
				Menu.navLiquid.to(rel.Y, rel.Y + size.Y, animate and S.menuOpen == true)
			end
			UI.conn(nav:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
				if Menu.placeNav then
					Menu.placeNav(false)
				end
			end))
		end
		Menu.sectionCaps = {}
		local lastSection: string? = nil
		local navOrder = 0
		for _, name in ipairs(TAB_ORDER) do
			if name == "Debug" and not Menu.debugAllowed() then
				continue
			end
			local sec = Menu.TAB_SECTION[name]
			if sec and sec ~= lastSection then
				navOrder += 1
				local cap = label(nav, string.lower(sec), UI.M.tiny, C.muted, UI.F.body)
				cap.Size = UDim2.new(1, 0, 0, px(26))
				cap.TextYAlignment = Enum.TextYAlignment.Bottom
				cap.LayoutOrder = navOrder
				cap.ZIndex = 5
				padding(cap, 0, 0, 5, 10)
				Menu.sectionCaps[sec] = cap
				lastSection = sec
			end
			navOrder += 1
			local item = button(nav, "", 10, C.text, Color3.new(1, 1, 1))
			item.Name = "Nav_" .. name
			item.BackgroundTransparency = 1
			item.Size = UDim2.new(1, 0, 0, px(30))
			item.LayoutOrder = navOrder
			item.ZIndex = 5
			corner(item, 6)
			local ic = icon(item, name, px(17))
			ic.AnchorPoint = Vector2.new(0, 0.5)
			ic.Position = UDim2.new(0, px(11), 0.5, 0)
			ic.ZIndex = 7
			local lbl = label(item, string.lower(Menu.TAB_LABEL[name] or name), UI.M.title, C.dim, UI.F.body)
			lbl.Size = UDim2.new(1, -px(46), 1, 0)
			lbl.Position = UDim2.new(0, px(38), 0, 0)
			lbl.ZIndex = 7
			local hovered = false
			-- the pill marks the active page; colours and the hover wash fade (a paint during the
			-- build sets them at once)
			local function paint(on: boolean, animate: boolean?)
				-- metal looks: dark ink on the brushed pill; the Max tab's sparkle keeps the accent
				local icCol = if on and UI.metal then UI.metal.ink elseif on or name == "Max" then C.accent elseif hovered then C.dim else C.muted
				local txtCol = if on and UI.metal then UI.metal.ink elseif on or hovered then C.text elseif name == "Max" then C.accent:Lerp(C.text, 0.3) else C.dim
				local bgTr = if hovered and not on then 0.96 else 1
				UI.tintIcon(ic, icCol, animate)
				if animate then
					tween(lbl, TW_HOVER, { TextColor3 = txtCol })
					tween(item, TW_HOVER, { BackgroundTransparency = bgTr })
				else
					lbl.TextColor3 = txtCol
					item.BackgroundTransparency = bgTr
				end
				UI.setFont(lbl, if on then UI.F.medium else UI.F.body)
			end
			item.MouseEnter:Connect(function()
				hovered = true
				paint(Menu.activeTab == name, true)
			end)
			item.MouseLeave:Connect(function()
				hovered = false
				paint(Menu.activeTab == name, true)
			end)
			item.MouseButton1Click:Connect(function()
				Menu.showTab(name)
			end)
			Menu.tabBtns[name] = { item = item, paint = paint, glyph = ic, cap = lbl }
			paint(false)
		end
		-- 1–9 jump to the tabs in sidebar order while the menu is open (never while typing in a field)
		local DIGITS = { One = 1, Two = 2, Three = 3, Four = 4, Five = 5, Six = 6, Seven = 7, Eight = 8, Nine = 9 }
		UI.conn(UIS.InputBegan:Connect(function(input: InputObject)
			if not S.menuOpen or input.UserInputType ~= Enum.UserInputType.Keyboard or UIS:GetFocusedTextBox() then
				return
			end
			local n = DIGITS[input.KeyCode.Name]
			if not n then
				return
			end
			local items = {}
			for tabName, d in pairs(Menu.tabBtns) do
				if d.item and d.item.Parent and d.item.Visible then
					table.insert(items, { name = tabName, order = d.item.LayoutOrder })
				end
			end
			table.sort(items, function(a, b)
				return a.order < b.order
			end)
			if items[n] then
				Menu.showTab(items[n].name)
			end
		end))

		-- user card at the bottom of the sidebar, on the rail's acrylic (the nav is a scrolling frame
		-- that ends above it and clips its own content, so the card needs no fill of its own)
		local card = frame(side)
		card.Name = "UserCard"
		card.Size = UDim2.new(1, 0, 0, CARD_H)
		card.Position = UDim2.new(0, 0, 1, -CARD_H)
		card.ZIndex = 8
		card.Active = true
		corner(card, 12)
		local cardHair = frame(card, C.hairline)
		cardHair.Size = UDim2.new(1, 0, 0, 1)
		cardHair.ZIndex = 8
		local avPx = px(28)
		local avatar = Instance.new("ImageLabel")
		avatar.Size = UDim2.fromOffset(avPx, avPx)
		avatar.AnchorPoint = Vector2.new(0, 0.5)
		avatar.Position = UDim2.new(0, px(14), 0.5, 0)
		avatar.BackgroundColor3 = C.card
		avatar.Image = ("rbxthumb://type=AvatarHeadShot&id=%d&w=48&h=48"):format(LP.UserId)
		avatar.ZIndex = 9
		avatar.Parent = card
		corner(avatar, avPx // 2)
		do
			-- metal looks: a metal ring round the headshot, as in the design
			local ring = stroke(avatar, C.accent, 0.55)
			if UI.metalEdge(ring) then
				ring.Thickness = 1.5
			end
		end
		local online = frame(avatar, C.ok)
		online.Size = UDim2.fromOffset(8, 8)
		online.AnchorPoint = Vector2.new(1, 1)
		online.Position = UDim2.new(1, 1, 1, 1)
		online.ZIndex = 10
		corner(online, 4)
		local onStroke = stroke(online, C.side, 0)
		onStroke.Thickness = 2
		local nameL = label(card, LP.DisplayName, UI.M.title, C.text, UI.F.medium)
		nameL.Size = UDim2.new(1, -px(60), 0, px(16))
		nameL.Position = UDim2.new(0, px(50), 0, px(11))
		nameL.TextTruncate = Enum.TextTruncate.AtEnd
		nameL.ZIndex = 9
		local subL = label(card, ("%s · v%s"):format(string.lower(EXECUTOR_NAME), PUBLIC_VERSION), UI.M.small, C.muted, UI.F.body)
		subL.Name = "SubLine" -- the site add-on writes the licence's days left here
		subL.Size = UDim2.new(1, -px(60), 0, px(14))
		subL.Position = UDim2.new(0, px(50), 0, px(28))
		subL.ZIndex = 9
		if S.edition == "max" then
			-- second line: the MAX tag, then executor and Max's version beside it
			local chip = UI.maxBadge(card, 15)
			chip.AnchorPoint = Vector2.new(0, 0.5)
			chip.Position = UDim2.new(0, px(50), 0, px(28) + px(7))
			chip.ZIndex = 10
			for _, d in ipairs(chip:GetDescendants()) do
				if d:IsA("GuiObject") then
					d.ZIndex = 11
				end
			end
			local cw = chip.Size.X.Offset + px(6)
			subL.Position = UDim2.new(0, px(50) + cw, 0, px(28))
			subL.Size = UDim2.new(1, -px(60) - cw, 0, px(14))
			subL.Text = ("%s · v%s"):format(string.lower(EXECUTOR_NAME), MAX_PUBLIC_VERSION)
		end
		UI.tip(avatar, "@" .. LP.Name)

		-- the docked side panel: hitbox figure (Aimbot / Silent aim / Ragebot) or ESP preview (Players)
		local panel = frame(host, C.bg)
		panel.Name = "SidePanel"
		panel.Size = UDim2.new(0, PREVIEW_W, 1, 0)
		panel.Position = UDim2.new(1, PANEL_GAP, 0, 0)
		panel.Visible = false
		panel.Active = true
		panel.ZIndex = 1
		corner(panel, 12)
		UI.softShadow(panel, "Shadow", Color3.new(0, 0, 0), 0.45, 22)
		do
			-- metal looks: the same turning metal edge and even glow as the window
			local peg = UI.metalEdge(stroke(panel, C.edge, 0))
			if peg then
				peg.Rotation = 180
				Menu.loop(peg, TweenInfo.new(30, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, -1), { Rotation = 540 })
				UI.softShadow(panel, "Aura", C.accent, UI.glowAlpha(0.4), 20)
			end
		end
		Menu.panel = panel
		Menu.applyGlass()
		local function panelView(title: string): (Frame, Frame)
			local v = frame(panel)
			v.Size = UDim2.fromScale(1, 1)
			v.Visible = false
			local head = frame(v)
			head.Size = UDim2.new(1, 0, 0, HEADER_H)
			local t = label(head, string.lower(title), UI.M.group, C.text, UI.F.semibold)
			t.Size = UDim2.new(1, -28, 1, 0)
			t.Position = UDim2.fromOffset(14, 0)
			local hh = frame(head, C.hairline)
			hh.Size = UDim2.new(1, 0, 0, 1)
			hh.Position = UDim2.new(0, 0, 1, -1)
			return v, head
		end
		local function footer(v: Frame, h: number): Frame
			local foot = frame(v)
			foot.Size = UDim2.new(1, 0, 0, h)
			foot.Position = UDim2.new(0, 0, 1, -h)
			local fh = frame(foot, C.hairline)
			fh.Size = UDim2.new(1, 0, 0, 1)
			local holder = frame(foot)
			holder.Size = UDim2.new(1, -28, 1, -14)
			holder.Position = UDim2.fromOffset(14, 9)
			return holder
		end
		-- hitboxes: which set the figure edits (Aimbot / Silent) + prefer / fallback rows
		local hbView, hbHead = panelView("Hitboxes")
		local segF = frame(hbHead, C.surface)
		segF.Size = UDim2.fromOffset(112, 24)
		segF.AnchorPoint = Vector2.new(1, 0.5)
		segF.Position = UDim2.new(1, -12, 0.5, 0)
		corner(segF, 6)
		stroke(segF, C.edge, 0)
		local segBtns = {}
		for i, nm in ipairs({ "Aimbot", "Silent" }) do
			local sb = button(segF, string.lower(nm), UI.M.small, C.muted, C.accent)
			sb.Size = UDim2.new(0.5, -3, 1, -4)
			sb.Position = UDim2.new((i - 1) * 0.5, if i == 1 then 2 else 1, 0, 2)
			sb.BackgroundTransparency = 1
			corner(sb, 4)
			segBtns[nm] = sb
			sb.MouseButton1Click:Connect(function()
				Menu.setHitboxSet(nm)
			end)
		end
		local hbBody = frame(hbView)
		hbBody.Position = UDim2.new(0, 0, 0, HEADER_H)
		hbBody.Size = UDim2.new(1, 0, 1, -HEADER_H - 76)
		Menu.buildHitboxPanel(hbBody)
		local hbHolder = footer(hbView, 76)
		local function hitboxRows(prefKey: string, visKey: string): Frame
			local holder = frame(hbHolder)
			holder.Size = UDim2.fromScale(1, 1)
			local gg = UI.group(holder, "Hitbox figure " .. prefKey, { bare = true, simple = true })
			gg:cycle("Prefer", prefKey, { "Head", "Body", "Arms", "Legs" }, { onChange = function()
				sanitize(cfg)
				if Menu.paintHitboxes then
					Menu.paintHitboxes()
				end
			end })
			gg:toggle("Visible fallback", visKey, { desc = "Aims at any exposed hitbox when the preferred one is covered." })
			return holder
		end
		local rowsAim = hitboxRows("aimPrefer", "aimVisibleHitbox")
		local rowsSilent = hitboxRows("silentPrefer", "silentVisibleHitbox")
		function Menu.setHitboxSet(nm: string)
			Menu.hitboxSet = nm
			rowsAim.Visible = nm == "Aimbot"
			rowsSilent.Visible = nm ~= "Aimbot"
			for k, sb in pairs(segBtns) do
				local on = k == nm
				-- metal looks: the picked set is a brushed key with dark ink
				if UI.brushed(sb) then
					local light = sb:FindFirstChild("BrushedLight")
					if light then
						(light :: Frame).Visible = on
					end
					sb.BackgroundTransparency = if on then 0 else 1
					sb.TextColor3 = if on then UI.metal.ink else C.muted
					UI.setFont(sb, if on then UI.F.bold else UI.F.medium)
				else
					sb.BackgroundTransparency = if on then 0.86 else 1
					sb.TextColor3 = if on then C.accent else C.muted
				end
			end
			if Menu.paintHitboxes then
				Menu.paintHitboxes()
			end
		end
		Menu.setHitboxSet("Silent")
		-- ESP preview + a test-health slider
		local pvView, pvHead = panelView("Preview")
		local pvHint = label(pvHead, "visible enemy", UI.M.small, C.muted, UI.F.body)
		pvHint.Size = UDim2.fromOffset(100, 16)
		pvHint.AnchorPoint = Vector2.new(1, 0.5)
		pvHint.Position = UDim2.new(1, -14, 0.5, 0)
		pvHint.TextXAlignment = Enum.TextXAlignment.Right
		local pvBody = frame(pvView)
		pvBody.Position = UDim2.new(0, 0, 0, HEADER_H)
		pvBody.Size = UDim2.new(1, 0, 1, -HEADER_H - 50)
		Menu.buildPreview(pvBody)
		local pvHolder = footer(pvView, 50)
		local pg = UI.group(pvHolder, "Preview health", { bare = true, simple = true })
		pg:slider("Health", "previewHp", 1, 100, 1, { unit = "%", trackW = 86, fmt = function(n)
			return tostring(math.floor(n))
		end })
		-- new panel content fades in under a sheet of the panel's colour (moving the panel would re-lay
		-- its avatar viewport every frame of the slide)
		do
			local sheet = frame(panel, C.bg)
			sheet.Name = "Sheet"
			sheet.Size = UDim2.fromScale(1, 1)
			sheet.ZIndex = 50
			sheet.Visible = false
			sheet.Active = false
			corner(sheet, 12)
			Menu.panelSheet = sheet
		end
		-- the window never moves for the panel (re-centring the pair jumped the whole window sideways on
		-- every page with a panel and re-laid all of it out): the panel docks on the right, and only a
		-- panel that would leave the screen nudges the window left, once, in whole pixels
		function Menu.layoutPane(tabName: string)
			local kind = if cfg.previewPane ~= false then Menu.SIDE_PANEL[tabName] else nil
			local show = kind ~= nil
			local wasKind = Menu.paneKind
			Menu.paneKind = kind
			if panel.Visible ~= show then
				panel.Visible = show
			end
			hbView.Visible = kind == "hitbox"
			pvView.Visible = kind == "preview"
			local sheet = Menu.panelSheet
			if sheet and show and kind ~= wasKind and S.menuOpen then
				Menu.panelSheetToken = (Menu.panelSheetToken or 0) + 1
				local token = Menu.panelSheetToken
				sheet.BackgroundTransparency = 0.1
				sheet.Visible = true
		tween(sheet, UI.TW.reveal, { BackgroundTransparency = 1 }).Completed:Connect(function(state: any)
					if state == Enum.PlaybackState.Completed and token == Menu.panelSheetToken then
						sheet.Visible = false
					end
				end)
			end
			if kind == "hitbox" then
				Menu.setHitboxSet(if tabName == "Aimbot" then "Aimbot" else "Silent")
			end
			if show then
				local vp = gui.AbsoluteSize
				local base = Menu.hostBase or host.Position
				local cx = base.X.Scale * vp.X + base.X.Offset
				local over = cx + MENU_W / 2 + PANEL_GAP + PREVIEW_W - (vp.X - 12)
				if vp.X > 100 and over > 0 then
					local nx = math.floor(math.max(MENU_W / 2 + 12, cx - over) + 0.5)
					local ny = math.floor(base.Y.Scale * vp.Y + base.Y.Offset + 0.5)
					Menu.hostBase = UDim2.fromOffset(nx, ny)
					host.Position = Menu.hostBase
				end
			end
		end

		Menu.pages = {}
		Menu.subs = {}
		Menu.buildPages()
		-- every sync entry a page registered belongs to that page (pages build one after another);
		-- entries outside a page (top bar, side panels, anything added later) stay global
		table.insert(Menu.syncMarks, { at = #UI.sync + 1, tab = nil })
		for i, mark in ipairs(Menu.syncMarks) do
			local nextAt = if Menu.syncMarks[i + 1] then Menu.syncMarks[i + 1].at else mark.at
			for j = mark.at, nextAt - 1 do
				UI.syncTab[j] = mark.tab
			end
		end
		Menu.showTab(TAB_ORDER[1])
		UI.refilter()
		Menu.balanceColumns()

		-- drag by the top bar or the logo; window + panel always stay on screen
		local dragging, dragStart, startPos = false, Vector2.zero, UDim2.new()
		function Menu.clampToScreen()
			local vp = gui.AbsoluteSize
			if vp.X < 100 or vp.Y < 100 then
				return
			end
			local half = host.AbsoluteSize * 0.5
			local center = host.AbsolutePosition + half
			local extra = if panel.Visible then PANEL_GAP + PREVIEW_W else 0
			-- with IgnoreGuiInset the reported AbsolutePosition is the screen position minus the inset
			local inset = if gui.IgnoreGuiInset then GuiService:GetGuiInset().Y else 0
			local cx = math.clamp(center.X, half.X, math.max(half.X, vp.X - half.X - extra))
			local cy = math.clamp(center.Y, half.Y - inset, math.max(half.Y - inset, vp.Y - half.Y - inset))
			-- whole pixels: a centred window on an odd viewport sat on a half pixel and every hairline
			-- and glyph edge in it blurred across two
			local nx = math.floor(cx + 0.5)
			local ny = math.floor(cy + inset + 0.5)
			if host.Position.X.Scale ~= 0 or host.Position.Y.Scale ~= 0 or math.abs(cx - center.X) > 0.01 or math.abs(cy - center.Y) > 0.01 then
				host.Position = UDim2.fromOffset(nx, ny)
			end
			Menu.hostBase = host.Position
		end
		for _, handle in ipairs({ top, logo }) do
			handle.InputBegan:Connect(function(i)
				if i.UserInputType == Enum.UserInputType.MouseButton1 then
					dragging = true
					dragStart = i.Position
					startPos = host.Position
				end
			end)
			handle.InputEnded:Connect(function(i)
				if i.UserInputType == Enum.UserInputType.MouseButton1 then
					dragging = false
					Menu.applyDrag()
					Menu.clampToScreen()
				end
			end)
		end
		-- a mouse reports many moves per frame (1000 Hz polling): each move only records where the window
		-- should go and Menu.tick moves it once per frame (a move per event re-laid the menu several
		-- times a frame — the laggy drag)
		UI.conn(UIS.InputChanged:Connect(function(i)
			if dragging and i.UserInputType == Enum.UserInputType.MouseMovement then
				local d = i.Position - dragStart
				Menu.dragTo = UDim2.new(startPos.X.Scale, startPos.X.Offset + math.floor(d.X + 0.5), startPos.Y.Scale, startPos.Y.Offset + math.floor(d.Y + 0.5))
			end
		end))
		function Menu.applyDrag()
			local to = Menu.dragTo
			if to then
				Menu.dragTo = nil
				if host.Position ~= to then
					host.Position = to
				end
				Menu.hostBase = to
			end
		end
		UI.conn(gui:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
			task.defer(Menu.clampToScreen)
		end))
	end

	function Menu.destroy()
		UI.closeBindPopup()
		UI.closeDropdown()
		for _, t in ipairs(Menu.loops or {}) do
			pcall(t.Cancel, t)
		end
		Menu.loops = {}
		Menu.glassGrad = nil
		for _, c in ipairs(UI.conns) do
			pcall(c.Disconnect, c)
		end
		table.clear(UI.conns)
		UI.dragInstalled = false
		UI.drag = nil
		-- a rebuild starts with an empty search box, so the filter must start empty too (a stale
		-- query used to hide most rows of the fresh menu with nothing in the box to explain it)
		UI.searchText = ""
		if Menu.gui then
			pcall(Menu.gui.Destroy, Menu.gui)
		end
		Menu.gui = nil
		Menu.root = nil
		Menu.host = nil
		Menu.panel = nil
		Menu.backdrop = nil
		Menu.curtain = nil
		Menu.pageCurtain = nil
		Menu.navSel = nil
		Menu.navLiquid = nil
		Menu.placeNav = nil
		Menu.hostBase = nil
		Menu.paintHitboxes = nil
		UI.gui = nil
		UI.root = nil
		UI.popupHost = nil
		Menu.tabBtns = {}
		Menu.pages = {}
		Menu.subs = {}
	end
	-- repaint every switch at once (panic and config loads change many keys in one go)
	function Menu.refreshToggles()
		for _, t2 in pairs(S.ui.toggles or {}) do
			if t2.refresh then
				pcall(t2.refresh)
			end
		end
	end
	-- panic: every combat feature, weapon / movement mod, anti-aim and the unsafe network mode off,
	-- the trigger / ADS / third person released. Skins and the menu stay.
	function Menu.panicAll()
		if Combat.stopAutokill then
			Combat.stopAutokill("panic")
		end
		if Combat.magicRelease then
			Combat.magicRelease("panic")
		end
		for _, k in ipairs({
			"aimbot", "silentAim", "autoShoot", "esp", "aaEnabled", "aaBody", "autokill", "autokillAuto", "magicBullet", "autoBackstab", "autoQuickMelee",
			"rapidFire", "noSpread", "noRecoil", "instantBullet", "instantReload", "fastEquip", "fastAim", "noAdsZoom", "speedBoost", "noAdsSlow", "bhop", "autoSlide",
			"thirdPerson", "fakeDuck", "autoPeek", "autoBlock", "unsafeMode", "unsafeFakeLag", "unsafePingBoost", "meleeRage", "voidSpam", "defenseHide",
			"antiMelee",
			-- these were missing, so panic left them running: the legit triggerbot kept firing (it doesn't need
			-- silent aim, which panic turns off), noclip stayed on, and rapid melee / full-auto / no-slow /
			-- inf slide+sprint / auto-utility / gun abilities all kept going
			"legitTrigger", "noclip", "rapidMelee", "fullAuto", "noSlow", "infSlide", "infSprint", "utilAuto", "gunAbilities",
		}) do
			cfg[k] = false
		end
		cfg.deviceSpoof = "Real" -- a string enum, not a boolean: back to reporting the real device
		-- magic / autokill-auto / peek are one positioning mode: switch that off, then re-derive
		cfg.ragePosition = "None"
		sanitize(cfg)
		if Combat.body then
			Combat.body.goHome("panic")
		end
		if Combat.releaseFire then
			Combat.releaseFire()
		end
		if Input.setAds then
			Input.setAds(false)
		end
		if Combat.aaBody then
			Combat.aaBody(false)
		end
		if Combat.thirdPerson then
			Combat.thirdPerson(false)
		end
		if S.net and S.net.uninstall then
			pcall(S.net.uninstall)
		end
		if Combat.applyWeaponStats then
			Combat.applyWeaponStats(true)
		end
		saveConfig()
		Menu.refreshToggles()
		notify("Everything is off", 3, "warn")
	end
	-- theme / profile change: tear the menu down and build it again in place
	function Menu.rebuild()
		local wasOpen = S.menuOpen
		local tab = Menu.activeTab
		Menu.destroy()
		S.menuOpen = false
		Menu.build()
		if tab ~= "" and Menu.pages[tab] then
			Menu.showTab(tab)
		end
		if wasOpen then
			Menu.set(true)
		end
	end
	function Menu.applyTheme()
		UI.applyTheme()
		Menu.rebuild()
		if S.hud and S.hud.retheme then
			pcall(S.hud.retheme)
		end
		notify("Theme: " .. UI.themeName(), 2, "ok")
		log("INFO", "theme:", UI.themeName())
	end
	-- a whole config was swapped in (profile load, clipboard import, reset): the theme, the HUD
	-- colours and the weapon stat edits all derive from it — a bare rebuild kept the old theme and
	-- left the old stat edits on the guns
	function Menu.afterConfigSwap()
		-- the skin picks travel with the config: rebuild the local equips the hooks read
		table.clear(S.localEquips)
		pcall(Skins.load)
		Skins.equipGen = (Skins.equipGen or 0) + 1
		pcall(Skins.refreshEquipmentUi)
		task.defer(function()
			pcall(Skins.applyNow, nil)
		end)
		if S.edition == "max" then
			cfg.theme = UI.maxThemeName() -- a loaded config never takes Max's colour away
		end
		UI.applyTheme()
		Menu.rebuild()
		if S.hud and S.hud.retheme then
			pcall(S.hud.retheme)
		end
		if Combat.applyWeaponStats then
			pcall(Combat.applyWeaponStats, true)
		end
	end
	S.rebuildMenu = Menu.rebuild
	S.applyTheme = Menu.applyTheme
	S.ui.openBindPopup = function(cfgKey: string)
		UI.openBindPopup(cfgKey)
	end
	S.ui.closeBindPopup = UI.closeBindPopup
	S.ui.search = UI.search
	S.ui.setMode = function(mode: string)
		UI.setMode(mode)
		if Menu.refreshModeSwitch then
			Menu.refreshModeSwitch()
		end
	end
	-- live rows refresh at ~15 Hz. Read-only readouts (UI.syncLazy) run only for the page on screen:
	-- their getters were most of each pass, on pages nobody was looking at, and the pass lands under
	-- every menu animation. A page catches up the moment it is shown (Menu.syncNow from showTab).
	local lastSyncAt = 0
	function Menu.syncNow(tab: string?)
		local owner = UI.syncTab or {}
		local lazy = UI.lazySync
		for i, fn in ipairs(UI.sync) do
			local t = owner[i]
			if t == nil or t == tab or not lazy[fn] then
				pcall(fn)
			end
		end
	end
	function Menu.tick(enemies: { any })
		if not S.menuOpen then
			return
		end
		if Menu.dragTo and Menu.applyDrag then
			Menu.applyDrag()
		end
		local now = os.clock()
		if now - lastSyncAt >= 0.066 then
			lastSyncAt = now
			Menu.syncNow(Menu.activeTab)
		end
	end

	-----------------------------------------------------------------------------
	-- §13 hud — watermark, indicators, binds overlay, toasts, status chips, F9 terminal
	-----------------------------------------------------------------------------
	local HUD: any = { gui = nil }
	S.hud = HUD
	local TERM_MAX = 150
	local function hex(c: Color3): string
		return ("#%02x%02x%02x"):format(math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5))
	end

	---------------------------------------------------------------------------
	-- movable panels: every HUD element registers here. Positions persist in cfg.hudPos[key] as
	-- viewport fractions of the panel's anchor point. Dragging happens in "arrange" mode
	-- (Interface → HUD → Arrange HUD, or the terminal header any time); Esc / the menu key / Done leaves it.
	---------------------------------------------------------------------------
	HUD.panels = {}
	HUD.editMode = false
	local function panelAnchorFraction(panel: GuiObject): (number, number)
		local gui = HUD.gui
		local vs = gui and gui.AbsoluteSize or Vector2.new(1920, 1080)
		local ap = panel.AbsolutePosition + panel.AnchorPoint * panel.AbsoluteSize
		return math.clamp(ap.X / math.max(vs.X, 1), 0, 1), math.clamp(ap.Y / math.max(vs.Y, 1), 0, 1)
	end
	function HUD.savePanel(key: string)
		local panel = HUD.panels[key] and HUD.panels[key].frame
		if not panel then
			return
		end
		local x, y = panelAnchorFraction(panel)
		cfg.hudPos[key] = { x = x, y = y }
		HUD.panels[key].base = UDim2.fromScale(x, y)
		saveConfig()
	end
	-- a panel's layout stays a viewport fraction (rec.base) but it is PLACED on whole pixels: a
	-- fractional scale (0.72 of 864 = 622.08) put its text and strokes across two pixels, and a UDim
	-- offset cannot hold the -0.08 that would correct it. Re-placed when the viewport changes.
	function HUD.snapPanel(rec: any)
		local cam = workspace.CurrentCamera
		local vs = cam and cam.ViewportSize
		local b = rec.base
		if not (vs and vs.X > 100 and vs.Y > 100 and b) then
			return
		end
		rec.frame.Position = UDim2.fromOffset(math.floor(b.X.Scale * vs.X + b.X.Offset + 0.5), math.floor(b.Y.Scale * vs.Y + b.Y.Offset + 0.5))
	end
	function HUD.snapAll()
		for _, rec in pairs(HUD.panels) do
			if not rec.dragging then
				HUD.snapPanel(rec)
			end
		end
	end
	function HUD.register(panel: GuiObject, key: string, title: string, dragAnywhere: boolean?)
		local saved = cfg.hudPos[key]
		if type(saved) == "table" and type(saved.x) == "number" and type(saved.y) == "number" then
			panel.Position = UDim2.fromScale(saved.x, saved.y)
		end
		-- HUD size (Interface -> HUD): scales the panel and everything in it, the menu keeps its own size
		local sc = Instance.new("UIScale")
		sc.Name = "HudScale"
		sc.Scale = math.clamp(tonumber(cfg.hudScale) or 1, 0.7, 1.6)
		sc.Parent = panel
		-- arrange-mode chrome: outline + name tag, hidden otherwise
		local es = Instance.new("UIStroke")
		es.Name = "EditStroke"
		es.Color = C.accent
		es.Thickness = 1
		es.LineJoinMode = Enum.LineJoinMode.Round
		es.Transparency = 0.15
		es.Enabled = false
		es.Parent = panel
		local tag = label(panel, string.lower(title), 12, C.accent, UI.F.semibold)
		tag.Name = "EditTag"
		tag.AnchorPoint = Vector2.new(0, 1)
		tag.Position = UDim2.new(0, 0, 0, -4)
		tag.Size = UDim2.new(0, 140, 0, 13)
		tag.Visible = false
		tag.ZIndex = panel.ZIndex + 5
		local rec = { frame = panel, key = key, title = title, stroke = es, tag = tag, dragging = false, start = Vector2.zero, startPos = UDim2.new(), anywhere = dragAnywhere == true }
		rec.base = panel.Position
		HUD.panels[key] = rec
		HUD.snapPanel(rec)
		panel.InputBegan:Connect(function(i)
			if i.UserInputType ~= Enum.UserInputType.MouseButton1 then
				return
			end
			if HUD.editMode or rec.anywhere then
				rec.dragging = true
				rec.start = i.Position
				rec.startPos = panel.Position
			end
		end)
		panel.InputEnded:Connect(function(i)
			if i.UserInputType == Enum.UserInputType.MouseButton1 and rec.dragging then
				rec.dragging = false
				HUD.savePanel(key)
			end
		end)
	end
	function HUD.dragTick(i: InputObject)
		if i.UserInputType ~= Enum.UserInputType.MouseMovement then
			return
		end
		for _, rec in pairs(HUD.panels) do
			if rec.dragging and rec.frame.Parent then
				local d = i.Position - rec.start
				local sp = rec.startPos
				rec.frame.Position = UDim2.new(sp.X.Scale, sp.X.Offset + d.X, sp.Y.Scale, sp.Y.Offset + d.Y)
			end
		end
	end
	function HUD.setEditMode(on: boolean)
		if on == HUD.editMode then
			return
		end
		HUD.editMode = on
		S.hudEdit = on
		for _, rec in pairs(HUD.panels) do
			rec.stroke.Enabled = on
			rec.tag.Visible = on
			rec.dragging = false
			if on then
				rec.frame.Visible = true -- show every panel so it can be placed, even if empty right now
			end
		end
		if HUD.editBar then
			HUD.editBar.Visible = on
		end
		pcall(function()
			CameraController:Freeze(on)
		end)
		if on then
			UIS.MouseBehavior = Enum.MouseBehavior.Default
			UIS.MouseIconEnabled = true
			notify("Drag any panel where you want it. Press Esc, " .. Input.keyLabel(cfg.menuKey) .. " or Done when finished.", 4, "info")
		end
	end
	S.setHudEdit = HUD.setEditMode
	function HUD.resetLayout()
		cfg.hudPos = {}
		saveConfig()
		HUD.retheme()
		notify("HUD layout reset", 2, "ok")
	end

	-- the look every HUD panel shares: the sidebar's near-black, a hairline edge, 8 px corners
	function HUD.applyScale()
		local v = math.clamp(tonumber(cfg.hudScale) or 1, 0.7, 1.6)
		for _, rec in pairs(HUD.panels) do
			local sc = rec.frame and rec.frame:FindFirstChild("HudScale")
			if sc then
				sc.Scale = v
			end
		end
		task.defer(HUD.snapAll)
	end
	function HUD.card(parent: GuiObject, name: string): Frame
		local f = frame(parent, C.side)
		f.Name = name
		f.BackgroundTransparency = 0.06
		f.Active = true
		corner(f, if UI.metal then 8 else 6)
		-- metal looks: the menu's metal edge (still here: the HUD is on screen all match)
		local s = stroke(f, C.edge, 0.15)
		UI.metalEdge(s)
		return f
	end
	-- a HUD card's title as a brushed header band with dark ink (the design); the plain caption elsewhere
	function HUD.band(parent: GuiObject, text: string): GuiObject
		if not UI.metal then
			local t = label(parent, text, 12, C.muted, UI.HUD_FONT)
			t.Size = UDim2.fromOffset(HUD.BIND_W, 18)
			t.LayoutOrder = 0
			return t
		end
		local band = frame(parent, Color3.new(1, 1, 1))
		band.Name = "Band"
		band.Size = UDim2.fromOffset(HUD.BIND_W, 20)
		band.LayoutOrder = 0
		corner(band, 5)
		UI.brushed(band)
		local t = label(band, text, 12, UI.metal.ink, UI.HUD_BOLD)
		t.Size = UDim2.new(1, -16, 1, 0)
		t.Position = UDim2.fromOffset(8, 0)
		local sp = frame(parent)
		sp.Size = UDim2.fromOffset(HUD.BIND_W, 2)
		sp.LayoutOrder = 1
		return band
	end
	-- status under the crosshair (v0.9): one line of text, no chip, no dots. The most urgent thing that needs
	-- the player (fire held, out of bounds, target immune) with its head in its colour and the detail dimmed,
	-- a soft shadow for contrast over the map. Autokill and voidspam live in the combat bar above.
	HUD.STATUS_ORDER = { "oob", "hold", "immune", "reload", "void", "aa", "situation" }
	function HUD.richEscape(s: string): string
		return (s:gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;"))
	end
	HUD.studs = Game.studs
	function HUD.statusBuild(gui: GuiObject?)
		local root = frame(gui)
		root.Name = "Status"
		root.AnchorPoint = Vector2.new(0.5, 0)
		root.Size = UDim2.fromOffset(420, 18)
		root.Position = UDim2.new(0.5, 0, 0.5, 44)
		root.Active = true
		local l = label(root, "", 13, C.text, UI.HUD_FONT)
		l.Size = UDim2.fromScale(1, 1)
		l.TextXAlignment = Enum.TextXAlignment.Center
		l.RichText = true
		l.TextStrokeColor3 = Color3.new(0, 0, 0)
		l.TextStrokeTransparency = 0.6
		l.Visible = false
		HUD.tags = { root = root, label = l, txt = {}, sev = {}, lineKey = nil }
		HUD.register(root, "tags", "status")
	end
	function HUD.statusSet(id: string, text: string?, sev: Color3?)
		local T = HUD.tags
		if T then
			T.txt[id], T.sev[id] = text, sev
		end
	end
	function HUD.statusRender()
		local T = HUD.tags
		if not T then
			return
		end
		local lineId: string? = nil
		for _, id in ipairs(HUD.STATUS_ORDER) do
			if T.txt[id] ~= nil then
				lineId = id
				break
			end
		end
		local text = if lineId then T.txt[lineId] elseif HUD.editMode then "Holding fire · out of reach" else nil
		local col = if lineId then T.sev[lineId] or C.accent else C.warn
		local on = text ~= nil
		if T.label.Visible ~= on then
			T.label.Visible = on
		end
		if not on then
			T.lineKey = nil
			return
		end
		local key = (text :: string) .. hex(col)
		if T.lineKey == key then
			return
		end
		T.lineKey = key
		-- the state word lowercase like every label; the detail after it keeps its case (it can name a player)
		local head, rest = string.match(text :: string, "^(.-) · (.+)$")
		T.label.Text = if head
			then ('<font color="#%s"><b>%s</b></font>   <font color="#%s">%s</font>'):format(col:ToHex(), HUD.richEscape(string.lower(head)), C.dim:ToHex(), HUD.richEscape(rest))
			else ('<font color="#%s"><b>%s</b></font>'):format(col:ToHex(), HUD.richEscape(string.lower(text :: string)))
	end
	-- the combat bar (v0.9), just above the crosshair: one compact 196×42 card for whatever holds the body
	-- in a fight — autokill first, else voidspam. A glowing state dot, the state in one bold word, a glowing
	-- timer on the right, one dim detail line and a gradient bar that drains to the next switch. The two
	-- sources cross-fade; it hides when neither runs. Draggable like every HUD panel (key "voidspam").
	function HUD.voidBuild(gui: Instance)
		local card = HUD.card(gui, "CombatBar")
		card.AnchorPoint = Vector2.new(0.5, 1)
		card.Size = UDim2.fromOffset(196, 46)
		-- high enough to clear the target's ESP name tag (Drawing renders above every GUI, and in a fight
		-- the target sits on the crosshair)
		card.Position = UDim2.new(0.5, 0, 0.5, -96)
		card.Visible = false
		padding(card, 8, 11, 7, 11)
		local state = label(card, "", 13, C.text, UI.HUD_BOLD)
		state.Size = UDim2.new(1, -64, 0, 15)
		state.TextTruncate = Enum.TextTruncate.AtEnd
		local timer = label(card, "", 12, C.dim, UI.HUD_FONT)
		timer.Size = UDim2.new(0, 60, 0, 15)
		timer.AnchorPoint = Vector2.new(1, 0)
		timer.Position = UDim2.new(1, 0, 0, 0)
		timer.TextXAlignment = Enum.TextXAlignment.Right
		local detail = label(card, "", 12, C.dim, UI.HUD_FONT)
		detail.Size = UDim2.new(1, 0, 0, 13)
		detail.Position = UDim2.fromOffset(0, 17)
		detail.TextTruncate = Enum.TextTruncate.AtEnd
		local track = frame(card, C.off)
		track.Size = UDim2.new(1, 0, 0, 2)
		track.AnchorPoint = Vector2.new(0, 1)
		track.Position = UDim2.new(0, 0, 1, 0)
		corner(track, 1)
		local fill = frame(track, Color3.new(1, 1, 1))
		fill.Size = UDim2.new(1, 0, 1, 0)
		corner(fill, 1)
		local fillGrad = UI.gradient(fill, C.accent, C.accent2)
		HUD.vs = {
			card = card, state = state, timer = timer, detail = detail, fill = fill, fillGrad = fillGrad,
			src = nil, fadeAt = 0, col = nil, stateText = nil, timerText = nil, detailText = nil, frac = -1,
		}
		HUD.register(card, "voidspam", "combat bar")
	end
	-- autokill in the bar's words: state word, colour, timer, detail, bar fraction (nil = not running)
	function HUD.akView(now: number): (string?, Color3?, string?, string?, number?)
		local st = ak.state
		if st == "idle" or (st == "done" and now - (ak.doneAt or 0) > 1.5) then
			return nil
		end
		local f = ak.fighter
		local who = if f then (Game.fighterName(f):gsub(" %[BOT%]", "")) else "no target"
		local hits = ak.hits or 0
		local hitTxt = ("%d hit%s"):format(hits, if hits == 1 then "" else "s")
		local chain = if (ak.chained or 0) > 0 then (" · #%d"):format(ak.chained + 1) else ""
		if st == "done" then
			return "Done", C.ok, hitTxt, ("%s%s"):format(tostring(ak.reason or "finished"), chain), 0
		end
		local elapsed = now - (ak.startedAt or now)
		local len = math.max(cfg.autokillDuration, 0.5)
		-- "until dead" has no clock: the bar stays full instead of draining over a made-up 61 s
		local frac = if cfg.autokillUntilDead then 1 else math.clamp(1 - elapsed / len, 0, 1)
		local timerTxt = ("%.1fs"):format(elapsed)
		local step = ak.step
		if st == "void" or step == "resting" then
			local left = math.max((ak.phaseUntil or now) - now, 0)
			return "Resting", Vis.VOID_COLOR, ("%.1fs"):format(left), ("%s · %s%s"):format(who, hitTxt, chain), math.clamp(left / math.max(cfg.voidRest or 1, 0.05), 0, 1)
		elseif st == "snap" or step == nil or step == "moving in" then
			return "Moving in", C.warn, timerTxt, who .. chain, frac
		elseif step == "firing" then
			return "Firing", C.rage, timerTxt, ("%s · %s%s"):format(who, hitTxt, chain), frac
		elseif step == "hiding" then
			return "Hiding", Vis.VOID_COLOR, timerTxt, ("%s · %s"):format(who, hitTxt), frac
		elseif step == "target immune" then
			return "Target immune", Vis.IMMUNE_COLOR, timerTxt, who .. " · spawn protection", frac
		end
		return (step:sub(1, 1):upper() .. step:sub(2)), C.warn, timerTxt, ("%s · %s"):format(who, hitTxt), frac
	end
	-- voidspam in the bar's words (nil = off or its panel switched off)
	function HUD.vsView(now: number): (string?, Color3?, string?, string?, number?)
		local V = Combat.vs
		if not (cfg.voidSpam == true and cfg.voidSpamHud == true) or V.state == "off" then
			return nil
		end
		local left = Combat.voidSpamLeft()
		if V.state == "hidden" then
			local len = if cfg.voidSpamMode == "Gun ready" then math.max(left or 0, 0.01) else cfg.voidSpamHide
			return "Hidden", C.accent, if left then ("%.1fs"):format(left) else "∞", Game.studs(V.dist) .. " st out", if left then math.clamp(left / math.max(len, 0.01), 0, 1) else 1
		elseif V.state == "back" then
			local short = cfg.voidSpamMode == "Timer" and cfg.voidSpamBack < Combat.settleSec()
			local detail = if V.reason == "firing" then "on your spot · firing" elseif short then "on your spot · back time < ping" else "on your spot"
			return "Back", C.warn, if left then ("%.1fs"):format(left) else "", detail, if left then math.clamp(left / math.max(cfg.voidSpamBack, 0.01), 0, 1) else 0
		end
		return "Waiting", C.muted, "", if V.reason ~= "" then V.reason else "starts in a duel", 0
	end
	function HUD.voidTick(now: number)
		local P = HUD.vs
		if not P then
			return
		end
		local src, stateText, col, timerText, detailText, frac = nil, nil, nil, nil, nil, nil
		if not S.menuOpen and not S.featuresPaused then
			if cfg.combatBar ~= false then
				stateText, col, timerText, detailText, frac = HUD.akView(now)
				src = if stateText then "ak" else nil
			end
			if not src then
				stateText, col, timerText, detailText, frac = HUD.vsView(now)
				src = if stateText then "vs" else nil
			end
		end
		if not src and HUD.editMode then
			src, stateText, col, timerText, detailText, frac = "edit", "Hidden", C.accent, "1.2s", "30,000 st out", 0.6
		end
		local on = src ~= nil
		if P.card.Visible ~= on then
			P.card.Visible = on
		end
		if not on then
			P.src = nil
			return
		end
		-- a new source fades its text in over 0.2 s (autokill taking over from voidspam and back)
		if P.src ~= src then
			P.src, P.fadeAt = src, now
		end
		local a = math.clamp((now - P.fadeAt) / 0.2, 0, 1)
		if a < 1 or P.alpha ~= 1 then
			P.alpha = a
			local t = 1 - a
			P.state.TextTransparency, P.timer.TextTransparency, P.detail.TextTransparency = t, t, t
		end
		if P.col ~= col then
			P.col = col
			local deep = if col == C.accent then C.accent2 else col:Lerp(C.accent2, 0.45)
			P.fillGrad.Rotation = 0
			P.fillGrad.Color = ColorSequence.new(col, deep)
			if col == C.accent then
				-- metal looks: the normal state's bar is the lit metal fill, like the menu's sliders
				UI.metalFill(P.fillGrad)
			end
			P.state.TextColor3 = col
		end
		if P.stateText ~= stateText then
			P.stateText = stateText
			-- lowercase like every label (the detail keeps player names as they are)
			P.state.Text = string.lower(stateText :: string)
		end
		if P.timerText ~= timerText then
			P.timerText = timerText
			P.timer.Text = timerText or ""
		end
		if P.detailText ~= detailText then
			P.detailText = detailText
			P.detail.Text = detailText or ""
		end
		local fr = math.floor((frac or 0) * 200 + 0.5) / 200
		if P.frac ~= fr then
			P.frac = fr
			P.fill.Size = UDim2.new(fr, 0, 1, 0)
		end
	end

	function HUD.build()
		local gui = Instance.new("ScreenGui")
		gui.Name = "CenterraHUD"
		gui.ResetOnSpawn = false
		gui.IgnoreGuiInset = true
		gui.DisplayOrder = 999
		gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
		gui.Enabled = true
		if not Game.parentGui(gui) then
			error("could not parent the HUD")
		end
		HUD.gui = gui
		HUD.panels = {}
		local inset = GuiService:GetGuiInset().Y
		local topY = math.max(inset, 36) + 10 -- never under the Roblox topbar

		-- watermark: face, name, the MAX tag on Max, version | fps, ping, signal, clock. Every width is measured.
		local wm = HUD.card(gui, "Watermark")
		wm.AutomaticSize = Enum.AutomaticSize.X
		wm.Size = UDim2.new(0, 0, 0, 28)
		wm.Position = UDim2.new(0, 14, 0, topY)
		wm.Visible = cfg.hud
		pcall(function()
			-- a Max look paints the watermark's edge in its flag
			local fx = UI.themeFx()
			local edge = fx and wm:FindFirstChildOfClass("UIStroke")
			if edge then
				edge.Color = Color3.new(1, 1, 1)
				edge.Transparency = 0.15
				local g = Instance.new("UIGradient")
				g.Color = UI.fxSeq(fx.flag)
				g.Parent = edge
			end
		end)
		padding(wm, 0, 11, 0, 9)
		local wl = vlist(wm, 7, true)
		wl.VerticalAlignment = Enum.VerticalAlignment.Center
		local gemBox = frame(wm)
		gemBox.Size = UDim2.fromOffset(14, 14)
		gemBox.LayoutOrder = 1
		UI.logoMark(gemBox, 14, 90)
		local brand = label(wm, ('c<font color="#%s">0</font>caine'):format(C.accent:ToHex()), 13, C.text, UI.HUD_BOLD)
		brand.RichText = true
		if UI.metal then
			-- metal looks: the lit-metal wordmark, like the menu's (static here)
			brand.Text = "centerra"
			brand.TextColor3 = Color3.new(1, 1, 1)
			local bg = gradient(brand, UI.metal.hi, UI.metal.lite, 90)
			bg.Color = ColorSequence.new({
				ColorSequenceKeypoint.new(0, UI.metal.hi),
				ColorSequenceKeypoint.new(0.45, UI.metal.lite),
				ColorSequenceKeypoint.new(0.6, UI.metal.hi),
				ColorSequenceKeypoint.new(1, UI.metal.lite),
			})
		end
		brand.Size = UDim2.new(0, UI.gw("centerra", 13, true) + 1, 1, 0)
		brand.LayoutOrder = 2
		if S.edition == "max" then
			UI.maxBadge(wm, 16).LayoutOrder = 3
		end
		local verTxt = "v" .. S.shownVersion
		local ver = label(wm, verTxt, 12, C.muted, UI.HUD_FONT)
		ver.Size = UDim2.new(0, UI.gw(verTxt, 12) + 1, 1, 0)
		ver.LayoutOrder = 4
		local sep = frame(wm, C.edge)
		sep.Size = UDim2.fromOffset(1, 12)
		sep.LayoutOrder = 5
		HUD.wm = wm
		HUD.wmStats = label(wm, "", 12, C.dim, UI.HUD_FONT)
		HUD.wmStats.Size = UDim2.new(0, 10, 1, 0)
		HUD.wmStats.RichText = true
		HUD.wmStats.LayoutOrder = 6
		-- signal: four rising bars coloured by the connection's quality (Roblox's own ping reading)
		local bars = frame(wm)
		bars.Name = "PingBars"
		bars.Size = UDim2.fromOffset(4 * 3 + 3 * 2, 12)
		bars.LayoutOrder = 7
		HUD.pingBars = {}
		for i = 1, 4 do
			local b = frame(bars, C.edge)
			local h = 3 + i * 2
			b.Size = UDim2.fromOffset(3, h)
			b.AnchorPoint = Vector2.new(0, 1)
			b.Position = UDim2.new(0, (i - 1) * 5, 1, 0)
			corner(b, 1)
			HUD.pingBars[i] = b
		end
		HUD.register(wm, "watermark", "watermark")

		-- status dots + one short line under the crosshair; the combat bar above it
		HUD.statusBuild(gui)
		HUD.voidBuild(gui)

		-- active features (right edge): the keybind panel's look — a titled card, the feature on the left and
		-- its value (×0.05, hidden, firing) in an accent keycap on the right
		local ind = HUD.card(gui, "Indicators")
		ind.AnchorPoint = Vector2.new(1, 0.5)
		ind.AutomaticSize = Enum.AutomaticSize.Y
		ind.Size = UDim2.fromOffset(HUD.BIND_W + 20, 20)
		ind.Position = UDim2.new(1, -14, 0.5, 0)
		ind.Visible = false
		vlist(ind, 2)
		padding(ind, 7, 10, 8, 10)
		HUD.band(ind, "active")
		HUD.indicators = ind
		HUD.indicatorLabels = {}
		HUD.register(ind, "indicators", "active features")

		-- keybinds: left edge just below the middle (the game's health / ability HUD owns the
		-- bottom-left corner in a match)
		local binds = HUD.card(gui, "Binds")
		binds.AnchorPoint = Vector2.new(0, 1)
		binds.AutomaticSize = Enum.AutomaticSize.XY
		binds.Size = UDim2.fromOffset(40, 20)
		binds.Position = UDim2.new(0, 14, 0.72, 0)
		binds.Visible = false
		vlist(binds, 2)
		padding(binds, 7, 10, 8, 10)
		HUD.band(binds, "keybinds")
		HUD.binds = binds
		HUD.bindRows = {}
		HUD.register(binds, "binds", "keybinds")

		-- messages: right edge, raised above the game's ammo / weapon HUD
		local toasts = frame(gui)
		toasts.Name = "Toasts"
		toasts.AnchorPoint = Vector2.new(1, 1)
		toasts.AutomaticSize = Enum.AutomaticSize.Y
		toasts.Size = UDim2.new(0, 300, 0, 20)
		toasts.Position = UDim2.new(1, -14, 0.72, 0)
		toasts.Active = true
		local tl = vlist(toasts, 6)
		tl.VerticalAlignment = Enum.VerticalAlignment.Bottom
		tl.HorizontalAlignment = Enum.HorizontalAlignment.Right
		HUD.toasts = toasts
		HUD.register(toasts, "toasts", "messages")

		-- kill list: under the watermark, newest first, each row fades out after a few seconds
		local kills = frame(gui)
		kills.Name = "Kills"
		kills.AutomaticSize = Enum.AutomaticSize.XY
		kills.Size = UDim2.fromOffset(40, 20)
		kills.Position = UDim2.new(0, 14, 0, topY + 36)
		kills.Active = true
		vlist(kills, 4)
		HUD.kills = kills
		HUD.killRows = {}
		for i = 1, 5 do
			local row = HUD.card(kills, "Kill")
			row.AutomaticSize = Enum.AutomaticSize.X
			row.Size = UDim2.fromOffset(0, 24)
			row.LayoutOrder = i
			row.Visible = false
			padding(row, 0, 10, 0, 8)
			local rl = vlist(row, 6, true)
			rl.VerticalAlignment = Enum.VerticalAlignment.Center
			local nm = label(row, "", 12, C.text, UI.HUD_BOLD)
			nm.AutomaticSize = Enum.AutomaticSize.X
			nm.Size = UDim2.new(0, 0, 1, 0)
			nm.LayoutOrder = 2
			local wp = label(row, "", 12, C.muted, UI.HUD_FONT)
			wp.AutomaticSize = Enum.AutomaticSize.X
			wp.Size = UDim2.new(0, 0, 1, 0)
			wp.LayoutOrder = 3
			HUD.killRows[i] = { frame = row, name = nm, weapon = wp, stroke = row:FindFirstChildOfClass("UIStroke") }
		end
		HUD.register(kills, "kills", "kill list")

		-- arrange-mode bar (top center)
		local bar = HUD.card(gui, "EditBar")
		bar.AnchorPoint = Vector2.new(0.5, 0)
		bar.Size = UDim2.fromOffset(390, 38)
		bar.Position = UDim2.new(0.5, 0, 0, topY)
		bar.BackgroundTransparency = 0.04
		bar.Visible = false
		bar.ZIndex = 50
		local barIconBox = frame(bar)
		barIconBox.Size = UDim2.fromOffset(18, 18)
		barIconBox.AnchorPoint = Vector2.new(0, 0.5)
		barIconBox.Position = UDim2.new(0, 12, 0.5, 0)
		barIconBox.ZIndex = 51
		local barIcon = icon(barIconBox, "arrange", 16)
		recolourIcon(barIcon, C.accent)
		local barText = label(bar, "arrange hud: drag any panel", 12, C.text, UI.F.medium)
		barText.Size = UDim2.new(1, -190, 1, 0)
		barText.Position = UDim2.new(0, 38, 0, 0)
		barText.ZIndex = 51
		local function barButton(text: string, x: number, tint: Color3?): TextButton
			local b = button(bar, text, 12, tint or C.dim, tint or C.surface)
			b.Size = UDim2.fromOffset(64, 26)
			b.AnchorPoint = Vector2.new(0, 0.5)
			b.Position = UDim2.new(1, x, 0.5, 0)
			b.BackgroundTransparency = if tint then 0.85 else 0
			b.ZIndex = 51
			corner(b, 6)
			stroke(b, tint or C.edge, if tint then 0.55 else 0)
			-- metal looks: the accent (primary) button is a brushed key with dark ink
			if tint == C.accent and UI.brushed(b) then
				b.BackgroundTransparency = 0
				b.TextColor3 = UI.metal.ink
				UI.setFont(b, UI.F.bold)
			end
			return b
		end
		barButton("reset", -144).MouseButton1Click:Connect(function()
			HUD.setEditMode(false)
			HUD.resetLayout()
		end)
		barButton("done", -74, C.accent).MouseButton1Click:Connect(function()
			HUD.setEditMode(false)
		end)
		HUD.editBar = bar
		-- one drag listener per HUD lifetime: every retheme used to add another (never disconnected
		-- until unload) — after a few theme changes each mouse move ran the drag tick several times
		if HUD.dragConn then
			pcall(HUD.dragConn.Disconnect, HUD.dragConn)
		end
		HUD.dragConn = track(UIS.InputChanged:Connect(HUD.dragTick))
		-- panels are placed on whole pixels from their fractions: place them again when the window resizes
		if HUD.vpConn then
			pcall(HUD.vpConn.Disconnect, HUD.vpConn)
		end
		HUD.vpConn = nil
		if workspace.CurrentCamera then
			HUD.vpConn = track(workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
				task.defer(HUD.snapAll)
			end))
		end
		local KIND = { info = C.accent, ok = C.ok, warn = C.warn, error = C.danger, rage = C.accent }
		local toastOrder = 0
		S.toast = function(text: string, duration: number, kind: string)
			if not HUD.gui then
				return
			end
			-- confirmations follow "Pop-up messages"; warnings and errors always show
			if cfg.toasts == false and kind ~= "warn" and kind ~= "error" then
				return
			end
			toastOrder += 1
			local tint = KIND[kind] or C.accent
			local alert = kind == "warn" or kind == "error"
			local t = frame(toasts, C.side)
			t.Name = "Toast"
			t.AutomaticSize = Enum.AutomaticSize.XY
			t.Size = UDim2.fromOffset(0, 0)
			t.BackgroundTransparency = 0.06
			t.LayoutOrder = toastOrder
			corner(t, if UI.metal then 8 else 6)
			-- metal looks: the metal edge (warnings keep a plain edge so their icon carries the colour)
			local te = stroke(t, C.edge, 0.15)
			if not alert then
				UI.metalEdge(te)
			end
			padding(t, 9, 12, 9, if alert then 32 else 12)
			if alert then
				local glyph = icon(t, "warn", 14)
				glyph.AnchorPoint = Vector2.new(0, 0)
				glyph.Position = UDim2.fromOffset(-21, 0)
				recolourIcon(glyph, tint)
			end
			local body = label(t, text, 13, if alert then C.text else C.dim:Lerp(C.text, 0.5), UI.HUD_FONT)
			body.AutomaticSize = Enum.AutomaticSize.XY
			body.Size = UDim2.fromOffset(0, 0)
			body.TextWrapped = true
			body.LineHeight = 1.1
			if not UI.snapWrapped(body, 280) then
				local cap = Instance.new("UISizeConstraint")
				cap.MaxSize = Vector2.new(280, math.huge)
				cap.Parent = body
			end
			UI.fadeIn(t, TW_TOAST_IN)
			task.delay(duration, function()
				if not t.Parent then
					return
				end
				UI.fadeOut(t, TW_TOAST_OUT, function()
					t:Destroy()
				end)
			end)
			local kids = {}
			for _, k in ipairs(toasts:GetChildren()) do
				if k:IsA("Frame") then
					table.insert(kids, k)
				end
			end
			if #kids > 5 then
				table.sort(kids, function(a, b)
					return a.LayoutOrder < b.LayoutOrder
				end)
				kids[1]:Destroy()
			end
		end

		HUD.buildTerminal()
	end

	---------------------------------------------------------------------------
	-- F9 terminal: live log view + status line with shot stats and the dropped-shot estimate
	---------------------------------------------------------------------------
	function HUD.termAppend(entry: any)
		local list = HUD.termList
		if not list then
			return
		end
		-- the terminal is closed most of the time: no label per log line while nobody can see it (the
		-- log ring is replayed when it opens — see HUD.setTerminal)
		if HUD.term and not HUD.term.Visible then
			HUD.termDirty = true
			return
		end
		local l = Instance.new("TextLabel")
		l.AutomaticSize = Enum.AutomaticSize.Y
		l.Size = UDim2.new(1, -6, 0, 0)
		l.BackgroundTransparency = 1
		UI.setFont(l, UI.F.code)
		l.TextSize = 12
		l.TextWrapped = true
		l.TextXAlignment = Enum.TextXAlignment.Left
		l.TextYAlignment = Enum.TextYAlignment.Top
		l.RichText = true
		local lc = { INFO = C.text, DEBUG = C.muted, WARN = C.warn, ERROR = C.danger }
		l.TextColor3 = lc[entry.level] or C.text
		l.Text = ('<font color="%s">%s</font> <font color="%s">%-5s</font> %s'):format(hex(C.muted), os.date("%H:%M:%S"), hex(C.accent2), entry.level, (tostring(entry.text):gsub("<", "&lt;")))
		l.LayoutOrder = math.floor(entry.t * 1000)
		l.Parent = list
		-- a running count instead of GetChildren() + IsA per label per appended line
		HUD.termCount = (HUD.termCount or 0) + 1
		if HUD.termCount > TERM_MAX then
			local kids = list:GetChildren()
			local n = HUD.termCount
			for _, k in ipairs(kids) do
				if k:IsA("TextLabel") then
					k:Destroy()
					n -= 1
					if n <= TERM_MAX then
						break
					end
				end
			end
			HUD.termCount = n
		end
		if not HUD.termScrollPending then
			HUD.termScrollPending = true
			task.defer(function()
				HUD.termScrollPending = false
				if list.Parent then
					list.CanvasPosition = Vector2.new(0, math.max(0, list.AbsoluteCanvasSize.Y - list.AbsoluteSize.Y))
				end
			end)
		end
	end

	function HUD.setTerminal(open: boolean)
		cfg.terminal = open
		if HUD.term then
			HUD.term.Visible = open
			-- lines logged while it was closed are replayed from the ring now
			if open and HUD.termDirty and HUD.termList then
				HUD.termDirty = false
				for _, ch in ipairs(HUD.termList:GetChildren()) do
					if ch:IsA("TextLabel") then
						ch:Destroy()
					end
				end
				HUD.termCount = 0
				local buf = logBuffer
				for i = math.max(1, #buf - TERM_MAX + 1), #buf do
					HUD.termAppend(buf[i])
				end
			end
		end
		saveConfig()
	end
	S.setTerminal = HUD.setTerminal

	function HUD.buildTerminal()
		local gui = HUD.gui
		local term = frame(gui, C.bg)
		term.Name = "Terminal"
		term.Size = UDim2.new(0, 620, 0, 280)
		term.Position = UDim2.new(0, 12, 1, -292)
		term.BackgroundTransparency = 0.04
		term.Visible = cfg.terminal
		term.Active = true
		corner(term, 8)
		UI.metalEdge(stroke(term, C.edge, 0.1))
		HUD.term = term
		local head = frame(term, C.side)
		head.Size = UDim2.new(1, 0, 0, 30)
		corner(head, 8)
		local headLine = frame(term, C.hairline)
		headLine.Size = UDim2.new(1, 0, 0, 1)
		headLine.Position = UDim2.fromOffset(0, 30)
		local title = label(head, "console", 12, C.text, UI.F.semibold)
		title.Size = UDim2.new(0, 70, 1, 0)
		title.Position = UDim2.new(0, 12, 0, 0)
		HUD.termStatus = label(head, "", 12, C.muted, UI.F.code)
		HUD.termStatus.Size = UDim2.new(1, -270, 1, 0)
		HUD.termStatus.Position = UDim2.new(0, 84, 0, 0)
		HUD.termStatus.TextTruncate = Enum.TextTruncate.AtEnd
		local function headBtn(text: string, xOff: number, fn: () -> ())
			local b = button(head, string.lower(text), 12, C.dim, C.surface)
			b.Size = UDim2.new(0, 52, 0, 22)
			b.Position = UDim2.new(1, xOff, 0.5, -11)
			corner(b, 5)
			stroke(b, C.edge, 0)
			b.MouseEnter:Connect(function()
				b.BackgroundColor3 = C.card
				b.TextColor3 = C.text
			end)
			b.MouseLeave:Connect(function()
				b.BackgroundColor3 = C.surface
				b.TextColor3 = C.dim
			end)
			b.MouseButton1Click:Connect(fn)
		end
		headBtn("Clear", -176, function()
			for _, k in ipairs(HUD.termList:GetChildren()) do
				if k:IsA("TextLabel") then
					k:Destroy()
				end
			end
			table.clear(logBuffer)
		end)
		headBtn("Copy", -118, function()
			if EXEC.setclipboard then
				local lines = {}
				for _, e in ipairs(logBuffer) do
					table.insert(lines, ("[%s] %s"):format(e.level, e.text))
				end
				pcall(EXEC.setclipboard, table.concat(lines, "\n"))
				notify("Log copied", 2, "ok")
			end
		end)
		headBtn("Close", -60, function()
			HUD.setTerminal(false)
		end)
		local list = Instance.new("ScrollingFrame")
		list.Size = UDim2.new(1, -8, 1, -38)
		list.Position = UDim2.new(0, 4, 0, 34)
		list.BackgroundTransparency = 1
		list.BorderSizePixel = 0
		list.ScrollBarThickness = 4
		list.ScrollBarImageColor3 = C.faint
		list.AutomaticCanvasSize = Enum.AutomaticSize.Y
		list.CanvasSize = UDim2.new()
		list.Parent = term
		vlist(list, 1)
		padding(list, 2, 4, 2, 6)
		HUD.termList = list
		HUD.register(term, "terminal", "terminal")
		-- the header drags any time (not only in arrange mode)
		local rec = HUD.panels.terminal
		head.InputBegan:Connect(function(i)
			if i.UserInputType == Enum.UserInputType.MouseButton1 and rec then
				rec.dragging, rec.start, rec.startPos = true, i.Position, term.Position
			end
		end)
		head.InputEnded:Connect(function(i)
			if i.UserInputType == Enum.UserInputType.MouseButton1 and rec and rec.dragging then
				rec.dragging = false
				HUD.savePanel("terminal")
			end
		end)
		-- the terminal starts hidden unless cfg.terminal; the ring is replayed only when it shows
		HUD.termCount = 0
		term.Visible = cfg.terminal == true
		if term.Visible then
			for i = math.max(1, #logBuffer - TERM_MAX + 1), #logBuffer do
				HUD.termAppend(logBuffer[i])
			end
		else
			HUD.termDirty = true
		end
		-- ONE listener per HUD build: HUD.retheme rebuilds the terminal, and every old listener kept
		-- appending to a destroyed list (and kept the old closure alive)
		if HUD.termListener then
			local idx = table.find(logListeners, HUD.termListener)
			if idx then
				table.remove(logListeners, idx)
			end
		end
		HUD.termListener = HUD.termAppend
		table.insert(logListeners, HUD.termAppend)
	end

	HUD.BIND_W = 188
	HUD.bindKeys = {}
	function HUD.updateBinds()
		local ov = HUD.binds
		if not ov then
			return
		end
		ov.Visible = cfg.showBinds and next(cfg.binds) ~= nil
		if not ov.Visible then
			return
		end
		local seen: { [string]: boolean } = {}
		local akOn = ak.state ~= "idle" and ak.state ~= "done"
		-- rows in name order (a pairs() walk reshuffled them between refreshes)
		local keys = HUD.bindKeys
		table.clear(keys)
		for cfgKey, b in pairs(cfg.binds) do
			if type(b) == "table" and ((b.key and b.key ~= "") or b.mode == "Always" or b.mode == "Never") then
				table.insert(keys, cfgKey)
			end
		end
		table.sort(keys, function(a, b)
			return (Input.bindLabels[a] or a) < (Input.bindLabels[b] or b)
		end)
		for i, cfgKey in ipairs(keys) do
			local b = cfg.binds[cfgKey]
			seen[cfgKey] = true
			local row = HUD.bindRows[cfgKey]
			if not row then
				-- the feature on the left, its key as a small keycap on the right; on = bright name, accent keycap
				local f = frame(ov)
				f.Size = UDim2.fromOffset(HUD.BIND_W, 20)
				local nm = label(f, "", 12, C.dim, UI.HUD_FONT)
				nm.TextTruncate = Enum.TextTruncate.AtEnd
				local chip = frame(f, C.surface)
				chip.Size = UDim2.fromOffset(24, 16)
				chip.AnchorPoint = Vector2.new(1, 0.5)
				chip.Position = UDim2.new(1, 0, 0.5, 0)
				corner(chip, 4)
				local key = label(chip, "", 11, C.muted, UI.HUD_BOLD)
				key.Size = UDim2.fromScale(1, 1)
				key.TextXAlignment = Enum.TextXAlignment.Center
				row = { frame = f, name = nm, key = key, chip = chip }
				HUD.bindRows[cfgKey] = row
			end
			row.frame.LayoutOrder = 10 + i
			local on = if cfgKey == "autokill" then akOn else cfg[cfgKey] == true
			local nameTxt = string.lower(Input.bindLabels[cfgKey] or cfgKey)
			if row.name.Text ~= nameTxt then
				row.name.Text = nameTxt
			end
			local mode = b.mode or "Toggle"
			local keyTxt = if mode == "Always" or mode == "Never" then string.lower(mode)
				elseif mode == "Toggle" then Input.keyLabel(b.key)
				else ("%s · %s"):format(Input.keyLabel(b.key), string.lower(mode))
			if row.key.Text ~= keyTxt then
				row.key.Text = keyTxt
				local cw = math.max(UI.gw(keyTxt, 11, true) + 10, 18)
				row.chip.Size = UDim2.fromOffset(cw, 16)
				row.name.Size = UDim2.new(0, HUD.BIND_W - cw - 8, 1, 0)
			end
			if row.on ~= on then
				row.on = on
				row.name.TextColor3 = if on then C.text else C.dim
				-- metal looks: an active bind's keycap is brushed metal with dark ink
				if UI.keyState(row.chip, on, C.surface) then
					row.key.TextColor3 = if on then UI.metal.ink else C.muted
				else
					row.chip.BackgroundColor3 = if on then C.accent else C.surface
					row.chip.BackgroundTransparency = if on then 0.8 else 0
					row.key.TextColor3 = if on then C.accent:Lerp(Color3.new(1, 1, 1), 0.35) else C.muted
				end
			end
		end
		for k, row in pairs(HUD.bindRows) do
			if not seen[k] then
				row.frame:Destroy()
				HUD.bindRows[k] = nil
			end
		end
	end

	function HUD.updateIndicators(active: { any })
		local ind = HUD.indicators
		if not ind then
			return
		end
		local any = false
		for i, entry in ipairs(active) do
			local name, on = entry[1], entry[2] == true
			local row = HUD.indicatorLabels[name]
			if not row then
				local f = frame(ind)
				f.Size = UDim2.fromOffset(HUD.BIND_W, 20)
				local nm = label(f, string.lower(name), 12, C.text, UI.HUD_FONT)
				nm.Size = UDim2.new(1, 0, 1, 0)
				nm.TextTruncate = Enum.TextTruncate.AtEnd
				local chip = frame(f, C.accent)
				chip.BackgroundTransparency = 0.8
				chip.Size = UDim2.fromOffset(24, 16)
				chip.AnchorPoint = Vector2.new(1, 0.5)
				chip.Position = UDim2.new(1, 0, 0.5, 0)
				chip.Visible = false
				corner(chip, 4)
				local keyed = UI.keyState(chip, true, C.surface)
				local val = label(chip, "", 11, if keyed then UI.metal.ink else C.accent:Lerp(Color3.new(1, 1, 1), 0.35), UI.HUD_BOLD)
				val.Size = UDim2.fromScale(1, 1)
				val.TextXAlignment = Enum.TextXAlignment.Center
				row = { frame = f, name = nm, chip = chip, val = val, text = nil }
				HUD.indicatorLabels[name] = row
			end
			-- "Rapid fire ×0.05" / "Voidspam · hidden" → the name, and the rest as the value
			local text = if type(entry[4]) == "string" then entry[4] else name
			if row.text ~= text then
				row.text = text
				local rest = if text:sub(1, #name) == name then text:sub(#name + 1):gsub("^%s*·?%s*", "") else ""
				row.val.Text = rest
				row.chip.Visible = rest ~= ""
				local cw = if rest ~= "" then math.max(UI.gw(rest, 11, true) + 10, 18) else 0
				row.chip.Size = UDim2.fromOffset(cw, 16)
				row.name.Size = UDim2.new(0, HUD.BIND_W - cw - (if cw > 0 then 8 else 0), 1, 0)
			end
			row.frame.LayoutOrder = i
			if row.frame.Visible ~= on then
				row.frame.Visible = on
			end
			any = any or on
		end
		local show = any or HUD.editMode
		if ind.Visible ~= show then
			ind.Visible = show
		end
	end

	-- fps
	local fpsAccum, fpsFrames, fpsValue = 0, 0, 0
	local lastHudUpdate = 0
	function HUD.tick(dt: number, enemies: { any }, gs: any)
		fpsAccum += dt
		fpsFrames += 1
		if fpsAccum >= 0.5 then
			fpsValue = math.floor(fpsFrames / fpsAccum + 0.5)
			fpsAccum, fpsFrames = 0, 0
		end
		if not HUD.gui then
			return
		end
		local now = os.clock()
		-- status at 10 Hz: tenths of a second at most, each a string.format + a Text write. Everything
		-- follows "Status tags"; the situation and anti-aim readouts have their own switches on top. Each
		-- line is a word or two: "HOLD · no line", "OOB · 2.1s", "RELOAD · 0.8s".
		local tg = HUD.tags
		if tg and now - (HUD.tagsAt or 0) >= 0.1 then
			HUD.tagsAt = now
			-- combat status only in a live round or the range: the lobby has no fight to report on
			local aw = cfg.awarenessHud == true and not S.menuOpen and not S.featuresPaused
			local show = HUD.statusSet
			-- off the map on one of OUR moves that the combat bar does not already show (a defense hide
			-- without voidspam, magic, melee rage): how far out and for how long
			local voidTxt: string? = nil
			local owner = Combat.body and Combat.body.owner
			local inBar = owner == "autokill" or (owner == "defense" and cfg.voidSpam and cfg.voidSpamHud)
			local root = if aw and owner ~= nil and not S.featuresPaused and not inBar then Game.myRoot() else nil
			local box = S.safe and S.safe.box
			if root and box then
				local p = root.Position
				local under = box.min.Y - p.Y
				local out = math.max(box.min.X - p.X, p.X - box.max.X, box.min.Z - p.Z, p.Z - box.max.Z)
				if under > 12 or out > 60 then
					HUD.voidSince = HUD.voidSince or now
					local where = if out > 60 then HUD.studs(out) .. " st out" else ("%d st under"):format(math.floor(under + 0.5))
					voidTxt = ("Hidden · %s · %.1fs"):format(where, now - HUD.voidSince)
				else
					HUD.voidSince = nil
				end
			else
				HUD.voidSince = nil
			end
			show("void", voidTxt, Vis.VOID_COLOR)
			-- why the trigger is held, or the switch that is off while an enemy is locked (the #1
			-- "it does not shoot" cause, shown red)
			local holdTxt: string? = nil
			local holdSev = C.warn
			if aw then
				local reason = if cfg.autoShoot and cfg.silentAim and S.holdReason then S.holdReason elseif S.triggerWait == "aim" and S.silentTarget then "scoping in" else nil
				if reason == "out of reach" and S.holdReach then
					reason = ("out of reach, %.0f of %.0f st"):format(S.holdDist or 0, S.holdReach)
				end
				if not cfg.silentAim then
					-- what does nothing without it: shown even without a lock, because without silent aim
					-- there never is one. A legit profile (rage off, auto shoot off) has nothing to say.
					local dep = Configs.silentDependent(cfg)
					if dep then
						local b = cfg.binds and cfg.binds.silentAim
						local keyTxt = if type(b) == "table" and b.key and b.key ~= "" then (" · press %s"):format(Input.keyLabel(b.key)) else (" · %s needs it"):format(dep)
						holdTxt, holdSev = "Silent aim off" .. keyTxt, C.danger
					end
				elseif S.silentTarget and not cfg.autoShoot then
					local b = cfg.binds and cfg.binds.autoShoot
					local keyTxt = if type(b) == "table" and b.key and b.key ~= "" then (" · press %s"):format(Input.keyLabel(b.key)) else ""
					holdTxt, holdSev = "Auto shoot off" .. keyTxt, C.danger
				end
				if not holdTxt and reason then
					holdTxt = "Holding fire · " .. reason
				end
			end
			show("hold", holdTxt, holdSev)
			-- standing in an OutOfBoundsPart volume: its kill timer (the server runs it too, guard or not)
			local oobLeft = aw and S.bounds.secondsLeft() or nil
			local oobTxt: string? = nil
			if oobLeft then
				local txt = ("Out of bounds · %.1fs left"):format(oobLeft)
				if cfg.oobBlock then
					txt ..= (" · guard %d/%d"):format(S.oobSuppressed or 0, S.oobSwallowed or 0)
				end
				oobTxt = txt
			elseif aw and cfg.oobBlock then
				local sup, sw = S.oobSuppressed or 0, S.oobSwallowed or 0
				if sup > 0 or sw > 0 then
					oobTxt = ("OOB guard · %d suppressed · %d swallowed"):format(sup, sw)
				end
			end
			show("oob", oobTxt, C.danger)
			show("immune", if aw and now - (S.lastImmuneAt or 0) < 1.5 then ("Target immune · %d shots wasted"):format(S.shotStats.immune or 0) else nil, Vis.IMMUNE_COLOR)
			local reloading = aw and cfg.statusSituation and (S.reloadUntil or 0) > now and cfg.instantReload
			show("reload", if reloading then ("Reloading · %.1fs"):format(S.reloadUntil - now) else nil, C.accent)
			local aaTxt: string? = nil
			local aaSev = C.warn
			if aw and cfg.statusAa and cfg.aaEnabled then
				local d = Combat.aaServerDelta()
				if d == nil then
					aaTxt = "Anti-aim · no server echo"
				elseif d > 0.35 then
					aaTxt, aaSev = ("Anti-aim · %d° off"):format(math.floor(math.deg(d) + 0.5)), C.ok
				elseif S.aaServerWant then
					aaTxt = "Anti-aim · syncing"
				else
					aaTxt = "Anti-aim · real angle showing"
				end
			end
			show("aa", aaTxt, aaSev)
			local sit = S.situation
			local sitOn = aw and cfg.statusSituation and sit ~= nil and sit.text ~= "" and sit.danger > 0.3
			show("situation", if sitOn then ("Danger · %d%%"):format(math.floor(sit.danger * 100 + 0.5)) else nil, if sitOn and sit.danger > 0.6 then C.danger else C.warn)
			HUD.statusRender()
		end
		-- the voidspam panel: every frame while it shows (its countdown bar drains smoothly)
		HUD.voidTick(now)
		-- kill list at 10 Hz: newest first, fading over the last second of its 6 s — every frame while a
		-- row is fading (a 10 Hz fade showed as ten visible steps)
		local rows = HUD.killRows
		if rows and HUD.kills and (HUD.killFading or now - (HUD.killsAt or 0) >= 0.1) then
			HUD.killsAt = now
			HUD.killFading = false
			local listOn = cfg.killFeed == true or HUD.editMode
			if HUD.kills.Visible ~= listOn then
				HUD.kills.Visible = listOn
			end
			for i, row in ipairs(rows) do
				local e = S.killList[i]
				local age = if e then now - e.t else math.huge
				local on = cfg.killFeed and age < 6
				local vis = on or (HUD.editMode and i == 1)
				if row.frame.Visible ~= vis then
					row.frame.Visible = vis
				end
				if on then
					if row.name.Text ~= e.name then
						row.name.Text = e.name
						row.weapon.Text = if e.weapon and e.weapon ~= "—" then tostring(e.weapon) else ""
					end
					local a = math.clamp(6 - age, 0, 1)
					if a < 1 then
						HUD.killFading = true
					end
					row.frame.BackgroundTransparency = 1 - 0.88 * a
					row.name.TextTransparency = 1 - a
					row.weapon.TextTransparency = 1 - a
					if row.stroke then
						row.stroke.Transparency = 1 - 0.75 * a
					end
				elseif HUD.editMode and i == 1 then
					-- a sample row so the panel can be placed
					if row.name.Text == "" then
						row.name.Text = "Kill list"
					end
					row.frame.BackgroundTransparency = 0.12
					row.name.TextTransparency = 0
					row.weapon.TextTransparency = 0
				end
			end
		end
		-- 5 Hz normally; the tier table promised 2 Hz at tier 3 since v5 — v5.2 keeps that promise
		if now - lastHudUpdate < (if (S.perfTier or 0) >= 3 then 0.5 else 0.2) then
			return
		end
		lastHudUpdate = now
		-- the theme's hex strings are computed once per theme, not seven times per refresh
		local hx = HUD.hex
		if not hx or hx.theme ~= S.themeApplied or hx.accent ~= C.accent then
			hx = { theme = S.themeApplied, accent = C.accent, acc = hex(C.accent), mut = hex(C.muted), text = hex(C.text), danger = hex(C.danger), warn = hex(C.warn), ok = hex(C.ok), rage = hex(C.rage) }
			HUD.hex = hx
		end
		local mut = hx.mut
		if HUD.wm then
			HUD.wm.Visible = cfg.hud or HUD.editMode
			if cfg.hud then
				local ping = Game.displayPingMs()
				local pingCol = if ping == nil then mut elseif ping > 180 then hx.danger elseif ping > 100 then hx.warn else hx.text
				local txt = ('<font color="%s">%d</font> fps  <font color="%s">·</font>  <font color="%s">%s</font> ms  <font color="%s">·</font>  %s'):format(
					if fpsValue < 40 then hx.warn else hx.text,
					fpsValue,
					mut,
					pingCol,
					if ping then tostring(ping) else "—",
					mut,
					os.date("%H:%M")
				)
				if HUD.wmStats.Text ~= txt then
					HUD.wmStats.Text = txt
					local plain = ("%d fps  ·  %s ms  ·  %s"):format(fpsValue, if ping then tostring(ping) else "—", os.date("%H:%M"))
					HUD.wmStats.Size = UDim2.new(0, UI.gw(plain, 12) + 2, 1, 0)
				end
				local lvl = if ping == nil then 0 elseif ping <= 80 then 4 elseif ping <= 130 then 3 elseif ping <= 200 then 2 else 1
				if HUD.pingLevel ~= lvl or HUD.pingTheme ~= S.themeApplied then
					HUD.pingLevel, HUD.pingTheme = lvl, S.themeApplied
					local col = if lvl >= 3 then C.ok elseif lvl == 2 then C.warn else C.danger
					for i, b in ipairs(HUD.pingBars or {}) do
						b.BackgroundColor3 = if i <= lvl then col else C.edge
					end
				end
			end
		end
		if HUD.termStatus then
			local ss = S.shotStats
			local vs = S.shots.stats
			HUD.termStatus.Text = ("%s · %d enemies · %s · shots %d · server HIT %d · WALL %d · AIR %d · no reply %d · confirmed %d · dropped ≈%d"):format(
				tostring(gs.weapon), #enemies, if S.silentTarget then "locked" else "no lock", ss.redirected, vs.hit, vs.wall, vs.air, vs.noReply, ss.confirmed, ss.dropped
			)
		end
		if gs.weapon ~= S.lastWeapon then
			local hadWeapon = S.lastWeapon ~= nil and S.lastWeapon ~= "—"
			S.lastWeapon = gs.weapon
			log("INFO", "weapon:", gs.weapon)
			if gs.weapon == "—" and Combat.resetFireLadder then
				Combat.resetFireLadder("new round") -- a demoted trigger path gets the game input back each round
			end
			if gs.weapon ~= "—" and not S.roundBase then
				S.roundBase = { t = now, stats = table.clone(S.shotStats), verdicts = S.shots.roundCounts(), kills = S.killCount or 0, dealt = S.dmgDealt or 0, expected = S.dmgExpected or 0 }
				Combat.tempoReset()
			elseif gs.weapon == "—" and hadWeapon and S.roundBase and now - S.roundBase.t > 8 then
				-- weapon put away after a real stretch of play: one line per round with what actually happened.
				-- HIT / WALL / AIR are the server's (ShootEffect); the client redirect rate is only a hint
				local b, ss = S.roundBase.stats, S.shotStats
				local v = S.shots.roundCounts(S.roundBase.verdicts)
				local dealt = (S.dmgDealt or 0) - S.roundBase.dealt
				local expected = (S.dmgExpected or 0) - S.roundBase.expected
				log("INFO", ("round summary: %.0fs · shots %d · server HIT %d · WALL %d · AIR %d · NEAR %d · no reply %d · client redirect hit %d%% · confirmed %d · dropped %d · damage dealt %d of %d expected (%d%% landed server-side) · straightened %d · trigger %s · rapid %s · ping %d"):format(
					now - S.roundBase.t, ss.redirected - b.redirected, v.hit, v.wall, v.air, v.near, v.noReply,
					if ss.redirected > b.redirected then math.floor((ss.hitTarget - b.hitTarget) / (ss.redirected - b.redirected) * 100 + 0.5) else 0,
					ss.confirmed - b.confirmed, ss.dropped - b.dropped,
					math.floor(dealt), math.floor(expected), if expected > 0 then math.floor(dealt / expected * 100 + 0.5) else 0,
					S.straightened or 0, Input.fireMethodUsed, if cfg.rapidFire then ("×%.2f"):format(cfg.rapidFireMult) else "off", S.pingMs or 0
				))
				log("INFO", Combat.tempoLine())
				if expected > 0 and dealt / expected < 0.5 and cfg.rapidFire and not cfg.autoShootServerSafe then
					notify("less than half your hits landed server-side — rapid fire above the server cooldown is the usual cause", 6, "warn")
				end
				S.roundBase = nil
			end
		end
		HUD.updateBinds()
		if HUD.indicators then
			if not cfg.indicators then
				HUD.indicators.Visible = false
			else
				local akOn = ak.state ~= "idle" and ak.state ~= "done"
				-- in the lobby the combat features are paused: one line says so instead of a list of switches that
				-- do nothing there; the visual ones below stay
				local live = not S.featuresPaused
				HUD.updateIndicators({
					{ "Lobby", not live and (cfg.silentAim or cfg.aimbot or cfg.rageEnabled or cfg.aaEnabled) == true, C.muted, "Lobby · combat paused" },
					{ "Autokill", live and akOn, C.rage, if akOn then "Autokill · " .. tostring(ak.step or "moving in") else "Autokill" },
					{ "Voidspam", live and cfg.voidSpam and cfg.rageEnabled ~= false, C.rage, if Combat.vs.state == "hidden" then "Voidspam · hidden" elseif Combat.vs.state == "back" then "Voidspam · back" else "Voidspam" },
					{ "Rapid fire", live and cfg.rapidFire, C.warn, ("Rapid fire ×%.2f"):format(cfg.rapidFireMult) },
					{ "Rapid melee", live and cfg.rapidMelee, C.warn, ("Rapid melee ×%.2f"):format(cfg.rapidMeleeMult) },
					{ "Instant reload", live and cfg.instantReload, C.accent2 },
					{ "Aimbot", live and cfg.aimbot, C.accent },
					{ "Silent aim", live and cfg.silentAim, C.accent },
					{ "Magic bullet", live and cfg.silentAim and cfg.magicBullet, C.accent2 },
					{ "Wallbang", live and cfg.silentAim and cfg.silentWallbang, C.accent2 },
					{ "Auto shoot", live and cfg.silentAim and cfg.autoShoot, C.accent2 },
					{ "Anti-aim", live and cfg.aaEnabled, C.warn },
					{ "Noclip", live and (cfg.noclip == true or (S.noclip and S.noclip.on == true)), C.warn, if S.noclip and S.noclip.on and not cfg.noclip then "Noclip (rage)" else "Noclip" },
					{ "Resolver", live and cfg.resolver and (cfg.silentAim or cfg.aimbot), C.accent },
					{ "ESP", cfg.esp, C.accent },
					{ "Chams", cfg.esp and cfg.espHighlight, C.accent },
					{ "Night mode", cfg.nightMode, C.accent2 },
					{ "Third person", live and cfg.thirdPerson, C.accent },
					{ "Skins", cfg.unlockCosmetics, C.ok },
				})
			end
		end
	end

	function HUD.destroy()
		for i = #logListeners, 1, -1 do
			if logListeners[i] == HUD.termAppend then
				table.remove(logListeners, i)
			end
		end
		HUD.editMode = false
		-- clearing editMode only wasn't enough: S.hudEdit gates auto shoot, the legit trigger, melee rage,
		-- defense and anti-aim, and a HUD rebuild / unload while arranging left it stuck true → those features
		-- stayed dead in the next instance
		S.hudEdit = false
		if HUD.gui then
			pcall(HUD.gui.Destroy, HUD.gui)
		end
		HUD.gui = nil
		HUD.editBar = nil
		HUD.panels = {}
		HUD.term = nil
		HUD.termList = nil
		HUD.termStatus = nil
		HUD.wm = nil
		HUD.wmStats = nil
		HUD.tags = nil
		HUD.vs = nil
		HUD.kills = nil
		HUD.killRows = nil
		HUD.indicators = nil
		HUD.indicatorLabels = {}
		HUD.binds = nil
		HUD.bindRows = {}
		S.toast = nil
	end
	function HUD.retheme()
		HUD.destroy()
		HUD.build()
	end

	-----------------------------------------------------------------------------
	-- §13b self-test · integrity · adaptive performance · intro
	-----------------------------------------------------------------------------
	local Self: any = {}
	S.self = Self

	-- a fake lock the hooks will act on (dummy part in a temp model); everything restored by release()
	local function fakeLock(): any
		local cam = workspace.CurrentCamera
		local saved = {
			part = S.silentPart, target = S.silentTarget, model = S.silentTargetModel, fighter = S.silentFighter,
			override = S.cfgOverrideSilent, firing = S.firing, caller = h.callerIsShotCode, spoof = S.spoofUntil,
			aimPoint = S.silentAimPoint, aimModel = S.silentAimModel,
		}
		local model = Instance.new("Model")
		model.Name = "CenterraSelfTest"
		local dummy = Instance.new("Part")
		dummy.Name = "HitboxHead"
		dummy.Size = Vector3.new(2, 2, 2)
		dummy.Anchored = true
		dummy.CanCollide = false
		dummy.Transparency = 1
		dummy.CFrame = (if cam then cam.CFrame else CFrame.new()) * CFrame.new(3, 1, -25)
		dummy.Parent = model
		model.PrimaryPart = dummy
		model.Parent = workspace
		-- the lock fields are written by arm(), synchronously, right before the checks — the test
		-- used to yield a Heartbeat with the fake lock live, so for one frame every hook aimed the
		-- real camera / raycast / body yaw at an invisible cube 25 studs ahead (a visible flick)
		local armed = false
		return {
			dummy = dummy,
			model = model,
			arm = function()
				armed = true
				S.silentPart, S.silentTarget, S.silentTargetModel, S.silentFighter = dummy, dummy.Position, model, nil
				-- a confirmed point of a real lock must not steer the probe off the dummy
				S.silentAimPoint, S.silentAimModel = nil, nil
				S.cfgOverrideSilent, S.firing = true, true
				h.callerIsShotCode = function()
					return true
				end
			end,
			release = function()
				if armed then
					S.silentPart, S.silentTarget, S.silentTargetModel, S.silentFighter = saved.part, saved.target, saved.model, saved.fighter
					S.silentAimPoint, S.silentAimModel = saved.aimPoint, saved.aimModel
					S.cfgOverrideSilent, S.firing, S.spoofUntil = saved.override, saved.firing, saved.spoof
					h.callerIsShotCode = saved.caller
				end
				model:Destroy()
			end,
		}
	end

	-- built-in test suite: the lobby-safe invariants that broke in the past, run after every load
	-- (4 s in) and from Debug → Live. Never fires the weapon, never moves the character.
	function Self.test(): any
		local results: { { name: string, ok: boolean, note: string } } = {}
		local function T(name: string, fn: () -> (boolean, string?))
			local ok, a, b = pcall(fn)
			local pass = ok and a == true
			table.insert(results, { name = name, ok = pass, note = if ok then tostring(b or "") else "error: " .. tostring(a):sub(1, 80) })
		end
		T("state", function()
			return genv().CenterraState == S and S.alive == true and type(S.cfg) == "table", "S on getgenv, alive"
		end)
		T("hooks", function()
			local need = { "camera", "fighter", "namecall", "cosmetics", "thirdPerson" }
			local missing = {}
			for _, k in ipairs(need) do
				local v = S.hooks.installed[k]
				if v ~= true and v ~= "n/a" then
					table.insert(missing, k)
				end
			end
			return #missing == 0, if #missing == 0 then "all core groups" else "missing " .. table.concat(missing, ",")
		end)
		T("hook logic", function()
			for _, k in ipairs({ "redirect", "camCF", "rot", "mouse", "recordShot", "isOurShotRay", "silentWanted" }) do
				if type(h[k]) ~= "function" then
					return false, "h." .. k .. " missing"
				end
			end
			return true, "S.h complete"
		end)
		local fl = fakeLock()
		local okRun, errRun = pcall(function()
			RunService.Heartbeat:Wait() -- the dummy part needs a frame to exist for raycasts
			fl.arm() -- no yield from here to release(): the lock is never live across a frame
			T("camera layer", function()
				local cf = CameraController:GetCameraCFrame()
				local want = (fl.dummy.Position - cf.Position).Unit
				local d = cf.LookVector:Dot(want)
				return d > 0.99, ("look·target %.3f"):format(d)
			end)
			T("raycast layer", function()
				-- the raycast and rotation layers stand down while the menu is open (by design)
				if S.menuOpen then
					return true, "skipped (menu open)"
				end
				local cam = workspace.CurrentCamera
				local look = h.lookVector() or cam.CFrame.LookVector
				-- an Include whitelist without the target, like the game's: the redirect must add the
				-- locked model and turn the ray onto it (map geometry can never block this one)
				local p = RaycastParams.new()
				p.FilterType = Enum.RaycastFilterType.Include
				p.FilterDescendantsInstances = {}
				local r = workspace:Raycast(cam.CFrame.Position, look * 999, p)
				return r ~= nil and r.Instance == fl.dummy, if r then "hit " .. r.Instance.Name else "no hit"
			end)
			T("rotation layer", function()
				if S.menuOpen then
					return true, "skipped (menu open)"
				end
				local lf = Game.localFighter()
				if not (lf and type(lf.GetCameraRotation) == "function") then
					return true, "no fighter (skipped)"
				end
				-- the lock-facing rotation only replaces the real one while a shot can leave
				local savedShot = S.ourShotUntil
				S.ourShotUntil = os.clock() + 0.5
				local rot = lf:GetCameraRotation()
				S.ourShotUntil = savedShot
				-- v5.0.3: the stream aims from the head (Game.shotOriginPos), the same origin the echo gate
				-- compares against — the camera sits elsewhere in third person
				local from = Game.shotOriginPos() or workspace.CurrentCamera.CFrame.Position
				local want = select(2, CFrame.lookAt(from, fl.dummy.Position):ToOrientation())
				local d = math.abs(((rot.Y - want + math.pi) % (2 * math.pi)) - math.pi)
				return d < 0.05, ("yaw error %.3f"):format(d)
			end)
			T("hitbox pick", function()
				local fake = { Entity = { Model = fl.model, Head = fl.dummy, RootPart = fl.dummy } }
				return Game.hitboxPart(fake, "Head") == fl.dummy, "HitboxHead preferred"
			end)
		end)
		fl.release()
		if not okRun then
			table.insert(results, { name = "fake lock run", ok = false, note = tostring(errRun):sub(1, 80) })
		end
		T("settle", function()
			local s = Combat.settleSec()
			return s >= 0 and s <= 0.6, ("%d ms"):format(s * 1000)
		end)
		T("trigger", function()
			local used = Input.fireMethodUsed
			Input.setFire(true, "direct")
			local held = Input.fireHeld()
			Input.setFire(false)
			Input.fireMethodUsed = used -- the probe must not show up as "last used direct"
			return held and not Input.fireHeld(), "direct rung toggles"
		end)
		T("game input path", function()
			local mc = Input.mechanics()
			return type(mc) == "table" and type(mc.EquippedItemInput) == "function", if mc then "EquippedItemInput" else "MechanicsController not loaded"
		end)
		T("ui", function()
			local n = 0
			for _ in pairs(S.ui.tabs) do
				n += 1
			end
			return Menu.gui ~= nil and n >= 9, ("%d tabs"):format(n)
		end)
		T("anti-aim", function()
			local enc = h.encodeRot(Vector2.new(-0.5081, -4.7467))
			if enc ~= utf8.char(235, 63) then
				return false, "encodeRot mismatch (want 235,63)"
			end
			if not h.rotRemote then
				return false, "UpdateCameraRotation remote not found"
			end
			return S.hooks.installed.mechanics == true, if S.hooks.installed.mechanics then "wire encoding ok · body-yaw hook on" else "body-yaw hook not installed"
		end)
		-- v5: the compressed camera-data shape must round-trip, and both encoders must agree
		T("camera data v5", function()
			local cf = CFrame.new(10, -5, 3) * CFrame.fromOrientation(0.3, -1.2, 0)
			local packed = h.encodeCFLike({ [KEY[1]] = 0 }, cf) -- table sample → compressed
			if type(packed) ~= "table" or type(packed[KEY[1]]) ~= "number" or type(packed[KEY[5]]) ~= "number" then
				return false, "encodeCFLike did not produce the 6-number table"
			end
			local back = h.decodeCF(packed)
			if not back or (back.Position - cf.Position).Magnitude > 0.01 or (back.LookVector - cf.LookVector).Magnitude > 0.01 then
				return false, "compressed CFrame does not round-trip"
			end
			if h.decodeCF(cf) ~= cf or h.encodeCFLike(cf, back) ~= back then
				return false, "real CFrames must pass through untouched"
			end
			return true, ("round-trip ok · spread claim hook %s"):format(if S.hooks.installed.spreadClaim then "on" else "OFF")
		end)
		T("bounds v5", function()
			local Bounds = S.bounds
			for _, k in ipairs({ "check", "allows", "mapFloorY", "inGeometry", "serverLos", "tick", "secondsLeft" }) do
				if type(Bounds[k]) ~= "function" then
					return false, "Bounds." .. k .. " missing"
				end
			end
			-- a synthetic volume: point-in-box + budget maths without touching the live tag cache
			local part = Instance.new("Part")
			part.Size = Vector3.new(10, 4, 10)
			part.CFrame = CFrame.new(1000, 1000, 1000)
			part:SetAttribute("WarnDelay", 1)
			part:SetAttribute("KillDelay", 2)
			local inside = Bounds.inside(part, Vector3.new(1002, 1001, 998))
			local outside = Bounds.inside(part, Vector3.new(1012, 1001, 998))
			local budget = Bounds.budget(part)
			part:SetAttribute("KillDelay", -1)
			local never = Bounds.budget(part)
			part:Destroy()
			if not (inside and not outside and budget == 3 and never == math.huge) then
				return false, ("inside=%s outside=%s budget=%s never=%s"):format(tostring(inside), tostring(outside), tostring(budget), tostring(never))
			end
			return true, ("geometry ok · %d volume(s) here · guard hook %s"):format(Bounds.n or 0, if S.hooks.installed.oob then "on" else "pending")
		end)
		T("origin planner v5", function()
			if type(Combat.origin) ~= "table" or type(Combat.origin.plan) ~= "function" or type(Combat.relocate) ~= "function" then
				return false, "Combat.origin.plan / Combat.relocate missing"
			end
			if type(Combat.noclip) ~= "table" or type(Combat.noclip.rage) ~= "function" then
				return false, "Combat.noclip missing"
			end
			local d = Combat.origin.spreadImmuneDist(nil)
			return type(d) == "number" and d > 0, ("spread-immune dist %s"):format(if d == math.huge then "∞ (claim)" else ("%.0f st"):format(d))
		end)
		T("skins", function()
			for _, k in ipairs({ "skinModelFor", "patchVmSerial", "isVmNameFor", "wrapFor", "updateHeldWrap" }) do
				if type(h[k]) ~= "function" then
					return false, "h." .. k .. " missing"
				end
			end
			-- the serial patcher on a wire-shaped table (short keys, model name by value)
			local weapon = Skins.weapons()[1]
			local skin = weapon and Skins.cosmeticsFor(weapon, "Skin")[1]
			if not (weapon and skin) then
				return true, "no skins in library (skipped)"
			end
			local charm = { Name = "charm" }
			local fake = { ["\1"] = { g = weapon, n = charm, id = "\200" } }
			local out = h.patchVmSerial(fake, weapon, skin)
			if not (out == fake and fake["\1"].g == skin and fake["\1"].n == charm and fake["\1"].id == "\200") then
				return false, "patch failed for " .. weapon
			end
			if h.patchVmSerial(fake, weapon, skin) ~= nil then
				return false, "patch is not idempotent"
			end
			if S.hooks.installed.vmCreate ~= true then
				return false, "_CreateViewModel hook not installed"
			end
			return true, ("patch ok (%s → %s), vmCreate hooked"):format(weapon, skin)
		end)
		T("config", function()
			local before = HttpService:JSONEncode(cfg)
			sanitize(cfg)
			return HttpService:JSONEncode(cfg) == before, "sanitize is a no-op"
		end)
		-- v5.2: every game contract the script relies on (pending ones are not failures)
		T("game contracts", function()
			local A = S.adapt
			local r = A.verify("self-test")
			local broken = A.brokenList()
			return r.broken == 0, if r.broken == 0 then ("%d/%d ok · %d pending · build %s"):format(r.total - r.pending, r.total, r.pending, tostring(A.build or "?")) else table.concat(broken, "; "):sub(1, 120)
		end)
		-- v5.2: the LOS whitelist cache — one build per TTL, never one per frame
		T("los cache", function()
			local lf = Game.localFighter()
			if not lf then
				return true, "no fighter (skipped)"
			end
			local before = Game.losRebuilds
			Game.frameId += 1
			Game.losParams()
			Game.frameId += 1
			Game.losParams()
			Game.frameId += 1
			local p = Game.losParams()
			local built = Game.losRebuilds - before
			return built <= 1, ("%d rebuild(s) over 3 frames · %s · ttl %.2f s"):format(built, if p then tostring(#p.FilterDescendantsInstances) .. " instances" else "no whitelist", Game.LOS_TTL)
		end)
		-- v0.9: the fast reload lives in the Gun class hook (StartReloading); the class loads with the first gun
		T("reload hook", function()
			local i = S.hooks.installed
			if i.gun == true then
				return true, "StartReloading hooked" .. (if cfg.instantReload then " · instant reload on" else "")
			end
			return i.gunWaiting == true, if i.gunWaiting then "Gun class not loaded yet (waiting)" else "Gun class hook missing"
		end)
		-- FullAuto rewrites every semi-auto's InputSpammingEnabled.StartShooting (false → 0) and puts it back
		T("full auto", function()
			local want = cfg.fullAuto == true and not (S.featuresPaused and not S.gateOverride)
			local semi, bad = 0, 0
			for name, info in pairs(ItemLibrary.Items or {}) do
				if type(info) == "table" and info.Type == "Gun" then
					local orig = S.statOriginals[name]
					local base = (orig and orig.InputSpammingEnabled) or info.InputSpammingEnabled
					if type(base) == "table" and base.StartShooting == false then
						semi += 1
						local cur = info.InputSpammingEnabled
						local on = type(cur) == "table" and cur.StartShooting == 0
						if on ~= want then
							bad += 1
						end
					end
				end
			end
			return bad == 0, ("%d semi-auto guns · full auto %s%s"):format(semi, if want then "applied" else "off", if bad > 0 then (" · %d wrong"):format(bad) else "")
		end)
		T("melee picker", function()
			if type(Combat.meleePick) ~= "function" or type(Combat.meleeValid) ~= "function" or type(Combat.meleeSpot) ~= "function" then
				return false, "meleePick / meleeValid / meleeSpot missing"
			end
			return Combat.meleePick({}, Vector3.zero) == nil, "no enemies → no target"
		end)
		T("combat bar", function()
			if cfg.combatBar == false then
				return true, "off in settings"
			end
			local vs = S.hud and S.hud.vs
			return vs ~= nil and vs.card ~= nil and vs.card.Parent ~= nil, if vs then "built" else "not built"
		end)
		T("esp renderer", function()
			local V = S.vis
			local gui = V.useGuiRenderer()
			local ok = gui or (EXEC.Drawing ~= nil and not V.drawingBroken)
			return ok, (if gui then "built-in renderer" else "Drawing") .. (if V.drawingBroken then " (Drawing failed → fallback)" else "")
		end)
		T("ping", function()
			local p = Game.pingMs()
			return type(p) == "number" and p >= 0 and p < 5000, if p > 0 then ("%d ms"):format(p) else "no reading yet"
		end)
		T("edition", function()
			local lic = genv().CenterraLicense
			if type(lic) ~= "table" or not S.served then
				return true, S.edition .. " (not served by the site: dev inject)"
			end
			if S.edition == "max" and lic.tier ~= "max" then
				return false, "Max running on a " .. tostring(lic.tier) .. " licence"
			end
			if lic.edition == "max" and S.edition ~= "max" then
				return false, "a Max load came up as Normal"
			end
			if S.edition == "max" and not (type(S.max) == "table" and type(S.max.stop) == "function") then
				return false, "Max edition without the Max module"
			end
			return true, S.edition .. " · licence " .. tostring(lic.tier or "?")
		end)
		T("desync", function()
			for _, k in ipairs({ "desyncSpot", "akDesyncStep", "buriedStand", "floorPushPoint", "underPushLimit" }) do
				if type(Combat[k]) ~= "function" then
					return false, "Combat." .. k .. " missing"
				end
			end
			if type(S.bounds.buriedTop) ~= "function" then
				return false, "Bounds.buriedTop missing"
			end
			return true, ("counter %s · autokill mode %s"):format(if cfg.antiUnder ~= false then "on" else "off", tostring(cfg.autokillMode))
		end)
		T("errors", function()
			local n = 0
			for _, c in pairs(S.errCounts or {}) do
				n += c
			end
			return n == 0, ("%d hook errors"):format(n)
		end)
		local pass, fail = 0, {}
		for _, r in ipairs(results) do
			if r.ok then
				pass += 1
			else
				table.insert(fail, r.name .. " (" .. r.note .. ")")
			end
		end
		-- a reload in the same Lua state (loader re-run after an unload) or an orphaned detour leaves hook
		-- layers dormant until they are re-armed; repair and run once more before reporting a failure
		if #fail > 0 and not Self.testRetrying then
			Self.testRetrying = true
			pcall(Hooks.repair, "self-test")
			local ok2, r2 = pcall(Self.test)
			Self.testRetrying = false
			if ok2 and type(r2) == "table" then
				return r2
			end
		end
		S.selfTestResult = { at = os.clock(), pass = pass, total = #results, failed = fail, results = results }
		if #fail == 0 then
			log("INFO", ("self-test: %d/%d ok"):format(pass, #results))
		else
			log("ERROR", ("self-test: %d/%d — FAILED: %s"):format(pass, #results, table.concat(fail, "; ")))
			notify(("self-test failed: %s"):format(table.concat(fail, ", ")), 8, "error")
		end
		return S.selfTestResult
	end
	S.selfTest = Self.test

	-- integrity: every 10 s make sure nothing replaced our state, logic or config; repair what can be
	local lastIntegrity, lastDeep = 0, 0
	function Self.integrity()
		local now = os.clock()
		if now - lastIntegrity < 10 then
			return
		end
		lastIntegrity = now
		-- anti-piracy self-unload check removed (no licence / stale heartbeat no longer unloads the script)
		local issues = {}
		if genv().CenterraState ~= S then
			table.insert(issues, "CenterraState replaced")
			genv().CenterraState = S
		end
		if genv().CenterraCfg ~= cfg then
			table.insert(issues, "CenterraCfg replaced")
			genv().CenterraCfg = cfg
		end
		for _, k in ipairs({ "redirect", "camCF", "rot", "mouse", "recordShot", "isOurShotRay", "silentWanted", "fakeInventory", "unlockable" }) do
			if type(h[k]) ~= "function" then
				table.insert(issues, "S.h." .. k .. " missing")
			end
		end
		-- the clamp check runs on the 60 s deep pass only: two JSON encodes of a ~900-key config
		-- every 10 s was a measurable hitch for a check that almost never fires
		local deep = now - lastDeep > 60
		if deep then
			-- stamp the 60 s cadence HERE, not only in the camera check below (which is skipped while a lock
			-- exists / the menu is open / autokill runs): otherwise sanitize + the clamp diff, and its toast,
			-- ran every 10 s all through a fight
			lastDeep = now
			-- scalar values before / after the clamp: the report names what moved (a bare "clamped" said nothing)
			local before = {}
			for k, v in pairs(cfg) do
				if type(v) ~= "table" then
					before[k] = v
				end
			end
			sanitize(cfg)
			local moved = {}
			for k, v in pairs(before) do
				if cfg[k] ~= v then
					table.insert(moved, ("%s %s→%s"):format(tostring(k), tostring(v), tostring(cfg[k])))
				end
			end
			if #moved > 0 then
				table.sort(moved)
				table.insert(issues, "config out of range → clamped: " .. table.concat(moved, ", ", 1, math.min(#moved, 6)))
			end
		end
		-- "fighter" needs a fighter instance to hook: between rounds / in the lobby its absence is
		-- normal, not a reason to run the whole installer every 10 s
		for _, k in ipairs({ "camera", "namecall", "cosmetics" }) do
			local v = S.hooks.installed[k]
			if v ~= true and v ~= "n/a" then
				table.insert(issues, "hook group " .. k .. " not installed → reinstall")
				pcall(Hooks.install)
				break
			end
		end
		if deep and not S.menuOpen and not S.teleported and S.autokill.state == "idle" and S.silentTarget == nil then
			-- behavioural check of the camera layer (the one a tamper would target first); the fake
			-- lock is armed and released within this frame (no yield → no visible camera flick)
			local fl = fakeLock()
			fl.arm()
			local ok, alive = pcall(function()
				local cf = CameraController:GetCameraCFrame()
				return cf.LookVector:Dot((fl.dummy.Position - cf.Position).Unit) > 0.99
			end)
			fl.release()
			if not (ok and alive) then
				-- hook() refuses to stack a second detour on a marked function: repair restores it first
				pcall(Hooks.repair, "integrity")
				-- a reload in the same Lua state (loader re-run after an unload) lands here every time and the
				-- re-arm fixes it: only a hook that is still dead afterwards is an error
				local fl2 = fakeLock()
				fl2.arm()
				local ok2, alive2 = pcall(function()
					local cf = CameraController:GetCameraCFrame()
					return cf.LookVector:Dot((fl2.dummy.Position - cf.Position).Unit) > 0.99
				end)
				fl2.release()
				if ok2 and alive2 then
					log("INFO", "integrity: camera hook re-armed")
				else
					table.insert(issues, "camera hook not answering after a reinstall")
				end
			end
		end
		S.integrityIssues = issues
		if #issues > 0 then
			log("ERROR", "integrity: " .. table.concat(issues, "; "))
			notify("integrity: " .. issues[1], 5, "error")
		end
	end

	-- adaptive performance: tiers driven by our own frame cost (EMA). Up fast (>6 / >9 / >13 ms for
	-- 1.5 s), down slow (< half the threshold for 6 s). What each tier actually cuts (v5, verified
	-- against the loop): 0 full · 1 no skeleton / 3D box · 2 perf mode — 10 ESP targets, 6 highlights,
	-- resolver + history at half rate, radar off, safestAngle 4 samples · 3 the same plus HUD text 2 Hz.
	-- ESP boxes draw every frame at every tier (the old comment claimed frame skipping that never existed).
	S.perfTier = 0
	local perfEma, perfHighSince, perfLowSince = 0, nil, nil
	local PERF_UP = { 5, 8, 12 }
	function Self.perf(frameMs: number)
		perfEma = perfEma + (frameMs - perfEma) * 0.1
		S.perfEma = perfEma
		if cfg.lowSpec then
			S.perfTier = math.max(S.perfTier or 0, 2)
			return
		end
		if not cfg.autoPerf then
			S.perfTier = 0
			return
		end
		local tier = S.perfTier
		local now = os.clock()
		local upAt = PERF_UP[tier + 1]
		if upAt and perfEma > upAt then
			perfHighSince = perfHighSince or now
			if now - perfHighSince > 1.5 then
				S.perfTier = tier + 1
				perfHighSince = nil
				-- name the three costliest steps; WARN (forwarded to the site) only the first time per session
				local top = {}
				for k, v in pairs(S.stepMs or {}) do
					table.insert(top, { k, v })
				end
				table.sort(top, function(a, b)
					return a[2] > b[2]
				end)
				local parts = {}
				for i = 1, math.min(3, #top) do
					table.insert(parts, ("%s %.1f"):format(top[i][1], top[i][2]))
				end
				log(if Self.perfWarned then "INFO" else "WARN", ("perf: %.1f ms/frame → tier %d · top: %s · %d enemies"):format(perfEma, S.perfTier, table.concat(parts, ", "), #(S.enemiesNow or {})))
				Self.perfWarned = true
			end
		else
			perfHighSince = nil
		end
		local downAt = PERF_UP[tier]
		if tier > 0 and downAt and perfEma < downAt * 0.5 then
			perfLowSince = perfLowSince or now
			if now - perfLowSince > 6 then
				S.perfTier = tier - 1
				perfLowSince = nil
				log("INFO", ("perf: %.1f ms/frame → tier %d"):format(perfEma, S.perfTier))
			end
		else
			perfLowSince = nil
		end
	end
	function Self.perfMode(): boolean
		return cfg.perfMode == true or S.perfTier >= 2
	end
	S.perfMode = Self.perfMode
	S.playIntro = function()
		Self.intro(true)
	end

	-- intro: the wordmark rises in over a soft glow, then everything fades. First inject only (20 min stamp).
	function Self.intro(force: boolean?)
		if not force then
			if not cfg.introAnim or cfg.lowSpec or genv().CenterraIntroShown then
				return
			end
			genv().CenterraIntroShown = true
			local stampFile = DATA.intro
			local last = 0
			pcall(function()
				if EXEC.isfile and EXEC.isfile(stampFile) then
					last = tonumber(EXEC.readfile(stampFile)) or 0
				end
			end)
			if os.time() - last < 1200 then
				return
			end
			pcall(function()
				EXEC.mkdirs(DATA.dir)
				EXEC.writefile(stampFile, tostring(os.time()))
			end)
		else
			local old = Game.guiParent():FindFirstChild("CenterraIntro")
			if old then
				old:Destroy()
			end
		end
		task.spawn(function()
			local gui = Instance.new("ScreenGui")
			gui.Name = "CenterraIntro"
			gui.IgnoreGuiInset = true
			gui.DisplayOrder = 2000
			gui.ResetOnSpawn = false
			if not Game.parentGui(gui) then
				return
			end
			-- tracked so an unload mid-animation removes it (the boot sweep of the NEXT inject was
			-- the only thing that ever cleaned up a half-played intro)
			S.introGui = gui
			gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
			-- the dark comes up and an accent light blooms; the face pops in (a little overshoot, out
			-- of a tilt) on a shockwave ring; the letters rise in one after another; a glowing line
			-- sweeps out under them; version and status fade in. On the way out everything drifts up
			-- and fades together (one stage frame moves, the rest only fades)
			local IN = TweenInfo.new(0.5, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
			local POP = TweenInfo.new(0.6, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
			local OUT = TweenInfo.new(0.36, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			local CY = 0.44
			local shade = frame(gui, Color3.new(0, 0, 0))
			shade.Size = UDim2.fromScale(1, 1)
			shade.BackgroundTransparency = 1
			local stage = frame(gui)
			stage.Size = UDim2.fromScale(1, 1)
			local function radial(color: Color3, size: number): ImageLabel
				local g = Instance.new("ImageLabel")
				g.BackgroundTransparency = 1
				g.Image = UI.glowRadial or UI.GLOW_IMAGE
				g.ScaleType = if UI.glowRadial then Enum.ScaleType.Stretch else Enum.ScaleType.Fit
				g.ImageColor3 = color
				g.ImageTransparency = 1
				g.AnchorPoint = Vector2.new(0.5, 0.5)
				g.Position = UDim2.new(0.5, 0, CY, -40)
				g.Size = UDim2.fromOffset(size, size)
				g.Parent = stage
				return g
			end
			local glow = radial(C.accent, 140)
			local ring = radial(C.accent2, 40)
			local markBox = frame(stage)
			markBox.AnchorPoint = Vector2.new(0.5, 0.5)
			markBox.Position = UDim2.new(0.5, 0, CY, -40)
			markBox.Size = UDim2.fromOffset(64, 64)
			local mark = UI.logoMark(markBox, 60, 90)
			local markImg = mark:IsA("ImageLabel")
			if markImg then
				local img = mark :: ImageLabel
				img.ImageTransparency = 1
				img.Size = UDim2.fromOffset(22, 22)
				img.Rotation = -18
			else
				mark.Visible = false
			end
			local wordRow = frame(stage)
			wordRow.AnchorPoint = Vector2.new(0.5, 0.5)
			wordRow.Position = UDim2.new(0.5, 0, CY, 16)
			wordRow.AutomaticSize = Enum.AutomaticSize.X
			wordRow.Size = UDim2.fromOffset(0, 42)
			local wl = vlist(wordRow, 1, true)
			wl.VerticalAlignment = Enum.VerticalAlignment.Center
			local letters: { TextLabel } = {}
			local wordFont = UI.BRAND_FONT
			for i, ch in ipairs(string.split("centerra", "")) do
				local holder = frame(wordRow)
				holder.Size = UDim2.fromOffset(UI.textW(ch, 36) + 4, 46)
				holder.LayoutOrder = i
				local l = label(holder, ch, 36, Color3.new(1, 1, 1), wordFont)
				l.Size = UDim2.fromScale(1, 1)
				l.Position = UDim2.fromOffset(0, 16)
				l.TextXAlignment = Enum.TextXAlignment.Center
				l.TextTransparency = 1
				local lg = if ch == "0" then gradient(l, C.accent, C.accent2, 90) else gradient(l, Color3.new(1, 1, 1), C.accent:Lerp(Color3.new(1, 1, 1), 0.3), 90)
				if UI.metal then
					-- metal looks: every letter is lit metal, like the wordmark
					lg.Color = ColorSequence.new({
						ColorSequenceKeypoint.new(0, UI.metal.hi),
						ColorSequenceKeypoint.new(0.4, UI.metal.lite),
						ColorSequenceKeypoint.new(0.52, UI.metal.lite:Lerp(UI.metal.mid, 0.45)),
						ColorSequenceKeypoint.new(0.62, UI.metal.hi),
						ColorSequenceKeypoint.new(1, UI.metal.lite),
					})
				end
				letters[i] = l
			end
			local under = frame(stage, Color3.new(1, 1, 1))
			under.AnchorPoint = Vector2.new(0.5, 0.5)
			under.Position = UDim2.new(0.5, 0, CY, 44)
			under.Size = UDim2.fromOffset(0, 2)
			under.BackgroundTransparency = 1
			corner(under, 1)
			do
				local ug = gradient(under, C.accent2, C.accent)
				local fx = UI.themeFx()
				if fx then
					ug.Color = UI.fxSeq(fx.flag)
				elseif UI.metal then
					ug.Color = ColorSequence.new({
						ColorSequenceKeypoint.new(0, UI.metal.mid),
						ColorSequenceKeypoint.new(0.5, UI.metal.hi),
						ColorSequenceKeypoint.new(1, UI.metal.mid),
					})
				end
			end
			local underGlow = UI.glow(under, 7, 1)
			local underGlowTo = underGlow.ImageTransparency
			underGlow.ImageTransparency = 1
			local ver = label(stage, ("v%s · %s"):format(PUBLIC_VERSION, EXECUTOR_NAME), 12, C.dim, UI.F.medium)
			ver.AnchorPoint = Vector2.new(0.5, 0)
			ver.Position = UDim2.new(0.5, 0, CY, 56)
			ver.Size = UDim2.fromOffset(400, 18)
			ver.TextXAlignment = Enum.TextXAlignment.Center
			ver.TextTransparency = 1
			local status = label(stage, "", 12, C.muted, UI.F.medium)
			status.AnchorPoint = Vector2.new(0.5, 0)
			status.Position = UDim2.new(0.5, 0, CY, 76)
			status.Size = UDim2.fromOffset(500, 16)
			status.TextXAlignment = Enum.TextXAlignment.Center
			status.TextTransparency = 1
			tween(shade, TweenInfo.new(0.35), { BackgroundTransparency = 0.42 })
			tween(glow, TweenInfo.new(1, Enum.EasingStyle.Sine, Enum.EasingDirection.Out), { ImageTransparency = 0.72, Size = UDim2.fromOffset(520, 520) })
			if markImg then
				tween(mark, POP, { Size = UDim2.fromOffset(60, 60), Rotation = 0 })
				tween(mark, TweenInfo.new(0.3), { ImageTransparency = 0 })
			end
			pcall(UI.fxIntro, stage, CY)
			task.wait(0.12)
			ring.ImageTransparency = 0.25
			tween(ring, TweenInfo.new(0.8, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), { Size = UDim2.fromOffset(420, 420), ImageTransparency = 1 })
			task.wait(0.1)
			for _, l in ipairs(letters) do
				tween(l, IN, { TextTransparency = 0, Position = UDim2.fromOffset(0, 0) })
				task.wait(0.045)
			end
			tween(under, IN, { Size = UDim2.fromOffset(220, 2), BackgroundTransparency = 0 })
			tween(underGlow, IN, { ImageTransparency = underGlowTo })
			-- Max: a band of blue light sweeps across the wordmark, then the MAX badge pops onto the face
			local maxScale: UIScale? = nil
			if S.edition == "max" then
				local sweep = frame(stage, Color3.new(1, 1, 1))
				sweep.AnchorPoint = Vector2.new(0.5, 0.5)
				sweep.Size = UDim2.fromOffset(40, 60)
				sweep.Position = UDim2.new(0.5, -150, CY, 16)
				sweep.Rotation = 14
				sweep.BackgroundTransparency = 0.25
				local sg = gradient(sweep, C.accent, Color3.new(1, 1, 1))
				sg.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.5, 0.1), NumberSequenceKeypoint.new(1, 1) })
				tween(sweep, TweenInfo.new(0.6, Enum.EasingStyle.Quad, Enum.EasingDirection.InOut), { Position = UDim2.new(0.5, 150, CY, 16), BackgroundTransparency = 0.6 })
				task.delay(0.62, function()
					if sweep.Parent then
						sweep:Destroy()
					end
				end)
				local chip = UI.maxBadge(stage, 20)
				chip.AnchorPoint = Vector2.new(0.5, 0.5)
				chip.Position = UDim2.new(0.5, 0, CY, -84)
				local sc = Instance.new("UIScale")
				sc.Scale = 0
				sc.Parent = chip
				maxScale = sc
				tween(sc, POP, { Scale = 1 })
				ver.Text = ("Max v%s  ·  %s"):format(MAX_PUBLIC_VERSION, EXECUTOR_NAME)
				ver.TextColor3 = C.accent:Lerp(Color3.new(1, 1, 1), 0.35)
			end
			tween(ver, IN, { TextTransparency = 0 })
			-- one line with what actually loaded
			local hooksOn = 0
			for _, v in pairs(S.hooks.installed) do
				if v == true then
					hooksOn += 1
				end
			end
			local nEnemies = #Game.enemies()
			status.Text = ("Ready · %d game hooks · %d enem%s · silent aim %s"):format(hooksOn, nEnemies, if nEnemies == 1 then "y" else "ies", if cfg.silentAim then "on" else "off")
			task.wait(0.15)
			tween(status, IN, { TextTransparency = 0 })
			task.wait(1.15)
			tween(stage, OUT, { Position = UDim2.fromOffset(0, -14) })
			tween(shade, OUT, { BackgroundTransparency = 1 })
			tween(glow, OUT, { ImageTransparency = 1 })
			tween(under, OUT, { BackgroundTransparency = 1 })
			tween(underGlow, OUT, { ImageTransparency = 1 })
			tween(ver, OUT, { TextTransparency = 1 })
			tween(status, OUT, { TextTransparency = 1 })
			if markImg then
				tween(mark, OUT, { ImageTransparency = 1 })
			end
			if maxScale then
				tween(maxScale, OUT, { Scale = 0 })
			end
			for _, l in ipairs(letters) do
				tween(l, OUT, { TextTransparency = 1 })
			end
			task.wait(OUT.Time + 0.05)
			gui:Destroy()
			if S.introGui == gui then
				S.introGui = nil
			end
		end)
	end

	-----------------------------------------------------------------------------
	-- §14 loop + lifecycle
	-----------------------------------------------------------------------------
	-- special bind targets (not plain cfg booleans)
	S.bindActions.autokill = function(state: any)
		local active = ak.state ~= "idle" and ak.state ~= "done"
		if state == nil then
			if active then
				Combat.stopAutokill("bind")
			elseif cfg.autokill then
				Combat.startAutokill(Game.targets())
			else
				notify("Autokill is off. Turn it on in Ragebot → Autokill.", 3, "warn")
			end
		elseif state == true and not active then
			if cfg.autokill then
				Combat.startAutokill(Game.targets())
			end
		elseif state == false and active then
			Combat.stopAutokill("bind released")
		end
	end
	-- the positioning switches are one mode: a bind on either switches the mode (or back to None)
	for key, mode in pairs({ magicBullet = "Magic bullet", autoPeek = "Peek" }) do
		S.bindActions[key] = function(state: any)
			local on = if state == nil then cfg.ragePosition ~= mode else state == true
			local want = if on then mode else "None"
			if cfg.ragePosition ~= want then
				cfg.ragePosition = want
				sanitize(cfg)
				saveConfig()
				notify("Positioning: " .. want, 2, "info")
			end
		end
	end
	S.bindActions.calibrateVoid = function(state: any)
		if state ~= false then
			task.spawn(Combat.calibrateVoid) -- retired: says so and does nothing
		end
	end

	runStep("install hooks", Hooks.install)

	-- a failed menu build must not abort the script: the key handler lives below
	do
		local okMenu, errMenu = xpcall(Menu.build, traceback)
		if okMenu then
			log("INFO", "build ui ok")
		else
			reportError("build ui", errMenu)
			pcall(Menu.panic, errMenu)
		end
		local okHud, errHud = xpcall(function()
			HUD.build()
			Menu.setHudEditHook(HUD.setEditMode)
		end, traceback)
		if okHud then
			log("INFO", "build hud ok")
		else
			reportError("build hud", errHud)
		end
	end

	track(UIS.InputBegan:Connect(function(input, processed)
		-- record the key first so Ctrl is already down when O arrives in this same handler
		local nm0 = Input.inputName(input)
		if nm0 then
			keyDown[nm0] = true
		end
		-- menu keys: the configured one (default RightShift) and always Ctrl+O. RightShift is used
		-- because Insert is swallowed by some executors and by the game ("the menu doesn't open").
		local kc = input.KeyCode
		local menuPressed = Menu.pressed(kc)
		if HUD.editMode and (kc == Enum.KeyCode.Escape or menuPressed) then
			HUD.setEditMode(false)
			return
		end
		if menuPressed then
			Menu.toggle()
			return
		end
		if input.KeyCode == Enum.KeyCode.F9 then
			HUD.setTerminal(not cfg.terminal)
			return
		end
		if S.menuOpen and input.UserInputType == Enum.UserInputType.MouseButton1 and Menu.root then
			-- click outside closes; decided from the mouse position so z-order can never misfire
			local m = UIS:GetMouseLocation()
			local inset = GuiService:GetGuiInset()
			local function inside(f: GuiObject?): boolean
				if not f or not f.Visible then
					return false
				end
				local p, s = f.AbsolutePosition, f.AbsoluteSize
				local mx, my = m.X, m.Y - inset.Y
				return mx >= p.X and mx <= p.X + s.X and my >= p.Y and my <= p.Y + s.Y
			end
			-- the docked side panel and an open dropdown count as the menu too
			if not inside(Menu.root) and not inside(Menu.panel) and not inside(HUD.term) and not (UI.popup and inside(UI.popup.frame)) then
				Menu.set(false)
			end
			return
		end
		if input.UserInputType ~= Enum.UserInputType.MouseMovement then
			Input.lastInputName = if input.KeyCode ~= Enum.KeyCode.Unknown then input.KeyCode.Name else input.UserInputType.Name
		end
		if input.UserInputType == Enum.UserInputType.MouseButton1 and not S.menuOpen then
			S.firing = true
			S.lmbDown = true
		end
	end))
	-- ContextActionService still hears the key when the game sinks UserInputService.InputBegan
	pcall(function()
		local CAS = game:GetService("ContextActionService")
		local keys = { Enum.KeyCode.RightShift, Enum.KeyCode.O }
		local mk = safeEnum(Enum.KeyCode, cfg.menuKey)
		if mk and mk ~= Enum.KeyCode.RightShift and mk ~= Enum.KeyCode.O then
			table.insert(keys, mk)
		end
		CAS:BindActionAtPriority("CenterraMenu", function(_, state, input)
			if state ~= Enum.UserInputState.Begin or not input then
				return Enum.ContextActionResult.Pass
			end
			if not Menu.pressed(input.KeyCode) then
				return Enum.ContextActionResult.Pass
			end
			if HUD.editMode then
				HUD.setEditMode(false)
				return Enum.ContextActionResult.Sink
			end
			Menu.toggle()
			return Enum.ContextActionResult.Sink
		end, false, 4000, unpack(keys))
	end)
	track(UIS.InputEnded:Connect(function(input)
		local nm = Input.inputName(input)
		if nm then
			keyDown[nm] = false
		end
		if input.UserInputType == Enum.UserInputType.MouseButton1 then
			S.firing = false
			S.lmbDown = false
		end
	end))

	-- Misc → Utility: anti-AFK, auto rejoin, rejoin / server hop. Kept on Game (the main chunk is near Luau's
	-- local limit)
	Game.util = { afkConns = nil, rejoinConn = nil, rejoining = false }
	function Game.util.teleportHere()
		local TS = game:GetService("TeleportService")
		if #Players:GetPlayers() <= 1 then
			TS:Teleport(game.PlaceId, LP) -- alone: the same job id would drop us into a closing server
		else
			TS:TeleportToPlaceInstance(game.PlaceId, game.JobId, LP)
		end
	end
	function Game.util.serverHop()
		local ok, body = pcall(function()
			return game:HttpGet(("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Desc&limit=100&excludeFullGames=true"):format(game.PlaceId))
		end)
		local data = ok and select(2, pcall(HttpService.JSONDecode, HttpService, body)) or nil
		local pick = {}
		for _, sv in ipairs(type(data) == "table" and data.data or {}) do
			if sv.id ~= game.JobId and tonumber(sv.playing) and tonumber(sv.maxPlayers) and sv.playing < sv.maxPlayers then
				table.insert(pick, sv.id)
			end
		end
		if #pick == 0 then
			notify("No other server found, rejoining a fresh one", 3, "warn")
			game:GetService("TeleportService"):Teleport(game.PlaceId, LP)
			return
		end
		notify("Hopping to another server…", 3)
		game:GetService("TeleportService"):TeleportToPlaceInstance(game.PlaceId, pick[math.random(#pick)], LP)
	end
	function Game.util.antiAfk(on: boolean)
		local u = Game.util
		if on and not u.afkConns then
			u.afkConns = {}
			-- the idle kick fires from LocalPlayer.Idled: park the game's listeners, and answer the event ourselves
			if type(getconnections) == "function" then
				pcall(function()
					for _, c in ipairs(getconnections(LP.Idled)) do
						if c.Disable then
							c:Disable()
							table.insert(u.afkConns, c)
						end
					end
				end)
			end
			u.afkIdled = LP.Idled:Connect(function()
				pcall(function()
					local vu = game:GetService("VirtualUser")
					vu:CaptureController()
					vu:ClickButton2(Vector2.new())
				end)
			end)
		elseif not on and u.afkConns then
			for _, c in ipairs(u.afkConns) do
				pcall(function()
					c:Enable()
				end)
			end
			u.afkConns = nil
			if u.afkIdled then
				u.afkIdled:Disconnect()
				u.afkIdled = nil
			end
		end
	end
	function Game.util.tick()
		local u = Game.util
		if (cfg.antiAfk == true) ~= (u.afkConns ~= nil) then
			u.antiAfk(cfg.antiAfk == true)
		end
		if cfg.autoRejoin and not u.rejoinConn then
			-- the disconnect / kick screen sets GuiService's error message; rejoin after a short delay
			u.rejoinConn = GuiService.ErrorMessageChanged:Connect(function(msg)
				if not cfg.autoRejoin or u.rejoining or type(msg) ~= "string" or msg == "" then
					return
				end
				u.rejoining = true
				log("INFO", "auto rejoin: " .. msg:sub(1, 120))
				task.delay(cfg.autoRejoinDelay, function()
					pcall(game:GetService("TeleportService").Teleport, game:GetService("TeleportService"), game.PlaceId, LP)
					task.delay(20, function()
						u.rejoining = false
					end)
				end)
			end)
		elseif not cfg.autoRejoin and u.rejoinConn then
			u.rejoinConn:Disconnect()
			u.rejoinConn = nil
		end
	end
	function Game.util.stop()
		local u = Game.util
		pcall(u.antiAfk, false)
		if u.rejoinConn then
			u.rejoinConn:Disconnect()
			u.rejoinConn = nil
		end
	end

	-- watchdog: every subsystem runs in its own guard. Ten errors inside 10 s pause that subsystem
	-- for 5 s (trigger released, autokill stopped) instead of taking the whole frame down with it.
	local stepState: { [string]: any } = {}
	S.stepState = stepState
	-- per-step timing (rolling EMA in ms) so the Debug tab / centerra_state can show what actually
	-- costs frame time instead of guessing. Two os.clock() calls per step — negligible.
	local stepMs: { [string]: number } = {}
	S.stepMs = stepMs
	local function step(name: string, fn: any, ...: any)
		local rec = stepState[name]
		if rec and rec.pausedUntil and os.clock() < rec.pausedUntil then
			return
		end
		-- S.allocProfile (off by default, set from the bridge): KB allocated per step into S.stepKb
		local kb0 = if S.allocProfile then gcKb() else nil
		local ts = os.clock()
		local ok, err = xpcall(fn, traceback, ...)
		local dt = (os.clock() - ts) * 1000
		stepMs[name] = (stepMs[name] or dt) * 0.9 + dt * 0.1
		if kb0 then
			local d = gcKb() - kb0
			if d >= 0 then
				S.stepKb = S.stepKb or {}
				S.stepKb[name] = (S.stepKb[name] or d) * 0.95 + d * 0.05
			end
		end
		if ok then
			return
		end
		rec = rec or { n = 0, windowStart = os.clock() }
		stepState[name] = rec
		local now = os.clock()
		if now - rec.windowStart > 10 then
			rec.n = 0
			rec.windowStart = now
		end
		rec.n += 1
		if err ~= rec.last then
			rec.last = err
			log("ERROR", name .. ":", err)
		end
		if cfg.watchdog and rec.n >= 10 then
			rec.n = 0
			rec.pausedUntil = now + 5
			rec.pauses = (rec.pauses or 0) + 1
			notify(name .. " keeps failing — paused 5 s (see F9)", 4, "error")
			pcall(Combat.releaseFire)
			if name == "autokill" or name == "autoShoot" or name == "magic" then
				pcall(Combat.stopAutokill, "watchdog")
			end
			-- v5.2: a paused step must not leave the body where it put it (a magic / defense / melee
			-- hold that errors ten times would otherwise park the character for the 5 s pause and beyond)
			if name == "magic" then
				pcall(Combat.magicRelease, "watchdog")
			elseif name == "defense" then
				pcall(Combat.defenseReturn, "watchdog")
			elseif name == "meleeRage" then
				pcall(Combat.meleeRageRelease, "watchdog")
			elseif name == "body" then
				pcall(Combat.body.goHome, "watchdog")
			elseif (name == "esp" or name == "radar" or name == "overlay") and not Vis.useGuiRenderer() then
				-- repeated ESP failures on the executor's Drawing objects: move to the built-in renderer and
				-- resume at once instead of drawing nothing in 5 s bursts
				pcall(Vis.markDrawingBroken, "repeated errors: " .. tostring(err):sub(1, 60))
				rec.pausedUntil = nil
			end
		end
	end
	-- the per-frame steps as named functions: the loop used to allocate eight closures per frame
	-- (each capturing enemies / gs / akActive), which showed up as steady GC churn
	Self.EMPTY = {}
	function Self.scanStep()
		local enemies = Game.enemies()
		S.enemiesNow = enemies
		-- caches for the namecall hook path (it may only read properties, never call methods)
		S.pingMs = Game.pingMs()
		-- hysteresis so rapid fire does not flip every frame around the threshold
		S.highPing = if S.highPing then S.pingMs > 360 else S.pingMs > 420
		Combat.notePing(S.pingMs)
		local char = LP.Character
		local head = char and char:FindFirstChild("Head")
		if not (head and head:IsA("BasePart")) then
			head = char and char:FindFirstChild("HumanoidRootPart")
		end
		S.myHeadPart = head
		-- the entity root (what the game's OOB machine and the server measure), for Bounds / noclip
		local lfNow = Game.localFighter()
		local ent = lfNow and rawget(lfNow, "Entity")
		local root = type(ent) == "table" and ent.RootPart or nil
		if not (typeof(root) == "Instance" and root.Parent) then
			root = char and char:FindFirstChild("HumanoidRootPart")
		end
		S.myRootPart = root
		S.bounds.tick()
		local nearest = Target.nearest(enemies)
		local nr = nearest and Game.fighterBody(nearest)
		S.nearestEnemyPos = nr and nr.Position or nil
		-- v5.2: what the __namecall hook must look at this frame (see Hooks.installNamecall) — a cast
		-- or a remote no feature wants falls straight through to the original
		S.ncCast = ((cfg.silentAim or S.cfgOverrideSilent) and (cfg.silentRaycastLayer or cfg.magicBullet) and S.h.redirect ~= nil) or S.rayTrace == true or false
		S.ncRemote = cfg.remoteSpy or cfg.oobBlock or cfg.unlockCosmetics or cfg.aaReplicate or S.deviceControls ~= nil or false
	end
	function Self.threatStep(enemies: { any })
		S.threatOnMe = Combat.threatLookingAtMe(enemies)
	end
	function Self.inputStep()
		S.aimHeld = Input.aimHeld()
		Input.runBinds()
	end
	function Self.gameStateStep()
		S.gameState = Game.state()
	end
	function Self.cameraStep()
		-- Body sets S.pinCF only while the owner holding the body asked for a pinned view
		Combat.pinCamera(S.pinCF ~= nil and Combat.body.owner ~= nil)
		-- the FOV offset is a game-side call (identity switch + method): it glides over ~0.25 s and is
		-- only called while it moves
		local fovWant = if cfg.fovChanger then cfg.fov - 80 else 0
		if cfg.stretchedRes and not S.featuresPaused then
			local s = math.clamp(cfg.stretchedResScale or 0.88, 0.6, 1)
			fovWant += (1 / s - 1) * 28 -- wider horizontal feel via extra FOV (local only)
		end
		local now = os.clock()
		local fdt = math.clamp(now - (S.fovAt or now), 0, 0.1)
		S.fovAt = now
		local fovCur = S.fovShown or 0
		if fovCur ~= fovWant then
			local n = fovCur + (fovWant - fovCur) * (1 - math.exp(-fdt / 0.08))
			if math.abs(fovWant - n) < 0.05 then
				n = fovWant
			end
			S.fovShown = n
			Game.asGame(CameraController.SetExternalFOVOffset, CameraController, "centerra", n)
		end
		-- third person stays on with the menu open; only the lobby gate turns it off
		local tpWant = cfg.thirdPerson == true and not S.featuresPaused
		if tpWant ~= S.tpApplied then
			S.tpApplied = tpWant
			Game.asGame(CameraController.SetThirdPersonOverride, CameraController, if tpWant then true else nil)
		end
		Combat.thirdPerson(tpWant)
		Combat.aaBody(not S.featuresPaused and ((cfg.aaEnabled == true and cfg.aaBody == true) or S.teleported == true))
	end
	function Self.overlayStep()
		local theme = S.themeColors
		Vis.drawOverlay(theme and theme.accent or Color3.fromRGB(0, 212, 255), theme and theme.accent2 or Color3.fromRGB(124, 92, 255))
	end
	function Self.espHideStep()
		Vis.hideAll()
	end
	function Self.aimbotStep(enemies: { any })
		local uiOpen = S.menuOpen or HUD.editMode
		if uiOpen then
			-- HUD arrange mode freezes the camera, so its cursor is written once here; the menu's cursor
			-- is the game's own (Hooks.installMenuMouse / UI.mouseTick)
			if HUD.editMode and not S.mouseUiApplied then
				S.mouseUiApplied = true
				UIS.MouseBehavior = Enum.MouseBehavior.Default
				UIS.MouseIconEnabled = true
			end
			return
		end
		S.mouseUiApplied = false
		local acq = Combat.aimAcq
		if cfg.aimbot and S.aimHeld and not S.featuresPaused and not (ak.state ~= "idle" and ak.state ~= "done") then
			local pick = Target.pick(enemies, Target.aimRadius(), cfg.targetPriority)
			if pick then
				-- a person needs a moment to react to a new target: follow it only after aimReactionMs on it
				local now = os.clock()
				if pick.fighter ~= acq.fighter then
					acq.fighter, acq.at = pick.fighter, now
				end
				if now - acq.at >= cfg.aimReactionMs / 1000 then
					-- an extension (Max Legitbot+) may move the point, slow the turn, or hold it this frame (false)
					local pos, mods = pick.pos, nil
					local lx = S.ext.legitAim
					if lx then
						local okX, p2, m2 = pcall(lx, pick, now - acq.at - cfg.aimReactionMs / 1000)
						if okX then
							if p2 == false then
								pos = nil
							elseif typeof(p2) == "Vector3" then
								pos = p2
							end
							mods = if type(m2) == "table" then m2 else nil
						end
					end
					if pos then
						Combat.aimAt(pos, true, mods)
					end
				end
			else
				acq.fighter = nil
			end
		else
			acq.fighter = nil
		end
	end
	-- the lobby gate. Paused (hub, match waiting room, between duels): every non-visual feature stops
	-- and nothing moves the body; ESP, chams, world, skins, the menu and the previews keep running. cfg
	-- is never written, so the saved toggles simply resume when the duel starts.
	function Combat.pauseAll()
		pcall(Combat.stopAutokill, "lobby")
		pcall(Combat.magicRelease, "lobby")
		pcall(Combat.defenseReturn, "lobby")
		Combat.def.vsKind = nil -- the next duel says again where voidspam parks
		pcall(Combat.meleeRageRelease, "lobby")
		pcall(Combat.updateAutoPeek)
		pcall(Combat.body.leave, "lobby")
		pcall(Combat.clearLock)
		pcall(Combat.releaseFire)
		pcall(Input.setAds, false)
		S.adsHeld = false
		pcall(Combat.restoreWeaponStats)
		pcall(Combat.thirdPerson, false)
		pcall(Combat.aaBody, false)
		-- h.rot hands back the real rotation from now on: send it once so the server drops the fake one
		pcall(Combat.sendRotation, nil)
		if Combat.deviceApply then
			pcall(Combat.deviceApply)
		end
	end
	function Combat.updateDuelGate()
		local lf = Game.localFighter()
		if lf ~= nil and lf ~= Combat.gateFighter then
			Combat.gateFighter = lf
			-- one listener for the current fighter: a new fighter every round used to add one more to
			-- the unload list (and keep the old fighter alive through it)
			if Combat.gateConn then
				pcall(function()
					Combat.gateConn:Disconnect()
				end)
			elseif not Combat.gateTracked then
				Combat.gateTracked = true
				Game.track({ Disconnect = function()
					if Combat.gateConn then
						pcall(function()
							Combat.gateConn:Disconnect()
						end)
						Combat.gateConn = nil
					end
				end } :: any)
			end
			Combat.gateConn = nil
			pcall(function()
				Combat.gateConn = lf:GetDataChangedSignal("IsInDuel"):Connect(function()
					Game.duelAt = -1
				end)
			end)
		end
		local paused = not Game.duelLive()
		if paused == S.featuresPaused and Combat.gateSeen then
			return
		end
		Combat.gateSeen = true
		S.featuresPaused = paused
		if paused then
			Combat.pauseAll()
			log("INFO", "lobby: features paused")
		else
			if Combat.deviceApply then
				pcall(Combat.deviceApply)
			end
			log("INFO", "lobby: features resumed")
		end
	end
	Game.checkpoint("build") -- a newer inject took over while the UI was building: never connect a second loop
	pcall(Combat.noclip.ensure) -- v5: the noclip Stepped/Heartbeat pair (gated on cfg / rage inside)
	track(RunService.RenderStepped:Connect(function(dt: number)
		Game.frameId += 1
		local t0 = os.clock()
		-- Weak PC mode pins the adaptive tier at 2: capped at 10 targets, no skeleton / 3D box /
		-- tracers, history at 30 Hz — the same cuts the tier system makes on its own when a frame
		-- runs long, just always on
		if cfg.lowSpec and (S.perfTier or 0) < 2 then
			S.perfTier = 2
		end
		step("scan", Self.scanStep)
		step("duelGate", Combat.updateDuelGate)
		local live = not S.featuresPaused
		local enemies = S.enemiesNow or Self.EMPTY
		-- what the combat steps may act on: nothing while the lobby gate is closed, range bots only in the
		-- hub (Game.targets, with a test override); the ESP, radar, HUD, hooks and kill tracking keep
		-- every enemy
		local targets = if live then Game.targets(enemies) else Self.EMPTY
		-- first: every step below (counters, lock, planners, ESP) reads the spot this puts a warping enemy back on
		step("warp", Resolver.warpStep, targets)
		-- set again this frame by whoever holds the body away from the next shooting spot (hide, hop)
		S.preFaceFrom, S.preFace = nil, false
		-- read by h.faceTarget inside the hooks, which may not call game methods themselves; through the
		-- round-start lock the stream already faces the lock, so the first round after it needs no re-sync
		local gsNow = S.gameState
		S.gunReadyIn = if not live then math.huge elseif gsNow and gsNow.locked then 0 else Combat.cannotFireFor(gsNow)
		S.echoLeadNow = Combat.echoLead()
		-- Track history is only needed for backtrack: skip it entirely when backtrack is off, and
		-- sample at ~30 Hz (every other frame) otherwise — 60 Hz history is overkill for lag comp
		if cfg.backtrackMode ~= "Off" and (S.perfTier < 2 or Game.frameId % 2 == 0) then
			step("track", Track.update, targets)
		end
		step("shots", Shots.tick)
		if Game.frameId % 10 == 0 then
			step("threat", Self.threatStep, targets)
		end
		if Game.frameId % 30 == 0 then
			step("net", Net.tick)
		end
		step("input", Self.inputStep)
		step("counter", S.counter.update, targets)
		step("hooks", Hooks.retryFighter, enemies)
		if S.perfTier < 2 or Game.frameId % 3 == 0 then
			step("resolver", Resolver.update, targets)
		end
		if live then
			step("autokill", Combat.updateAutokill, targets)
			step("lock", Combat.updateLock, targets)
			step("magic", Combat.updateMagic)
			step("meleeRage", Combat.updateMeleeRage, targets)
			-- the hide asks "does anyone see me / can I see my lock": the situation it reads is this frame's
			if cfg.defenseHide and cfg.defenseOnlyWhenThreat and Combat.rageOn() then
				step("situation", Combat.updateSituation, targets, S.gameState or Game._state)
			end
			step("defense", Combat.updateDefense, targets)
			step("peek", Combat.updateAutoPeek)
			step("antiMelee", Combat.updateAntiMelee, targets)
		end
		-- the one relocation of the frame: the highest-priority request above, validated by Safe
		step("body", Combat.body.commit)
		-- voidspam's clock / status after the commit (the panel shows this frame's body), lobby included
		step("voidspam", Combat.voidSpamTick, os.clock())
		if live then
			local akActive = ak.state ~= "idle" and ak.state ~= "done"
			-- our own trigger waits for the server to see the new position after a teleport; a player's
			-- manual shot is never held back (it would only be wasted)
			local magicGate = not (cfg.magicBullet and cfg.silentAim) or S.magicReady or S.targetVisible or akActive
			-- autokill judges its own settle (Body.settledFor on its spot): its hops re-armed this one every few hundred
			-- ms, and a run sat on the target with the trigger held ("it's on them but doesn't shoot")
			local settleGate = not S.teleported or Combat.settled() or (akActive and ak.firing == true)
			local ltOwns = cfg.legitTrigger and Combat.lt.fighter ~= nil
			-- a gate here used to hold the trigger with nothing on the status line ("it just doesn't shoot")
			S.autoGateWhy = if S.silentTarget == nil then nil
				elseif not magicGate then "finding a magic bullet spot"
				elseif not settleGate then "settling after a teleport"
				elseif ltOwns then "the triggerbot has this target"
				else nil
			step("autoShoot", Combat.updateAutoShoot, S.silentTarget ~= nil and magicGate and settleGate and not ltOwns)
			step("legitTrigger", Combat.updateLegitTrigger, targets)
			step("autoBlock", Combat.updateAutoBlock, targets)
			step("weaponStats", Combat.applyWeaponStats)
			step("tempo", Combat.tempoTick, dt)
		end
		if Game.frameId % 30 == 0 then
			step("itemTrack", Combat.trackItems)
			step("spreadReport", Combat.reportSpread)
		end
		step("shotConfirm", Combat.updateShotConfirm)
		step("kills", Combat.updateKills, enemies)
		step("gameState", Self.gameStateStep)
		local gs = S.gameState or Game._state
		if live and Game.frameId % (if cfg.lowSpec then 6 else 3) == 0 then
			step("situation", Combat.updateSituation, targets, gs)
			step("quickMelee", Combat.updateQuickMelee, targets)
			step("suspend", Combat.updateSuspend)
			step("utilities", Combat.updateUtilities, targets)
			step("gunAbilities", Combat.updateGunAbilities)
			local bso = Combat.backstabOwner()
			if bso == "lunge" then
				step("backstab", Combat.updateBackstab, targets)
			elseif bso == "meleeRage" and Game.weaponProfile().melee then
				Combat.backstabSkip("meleeRage", "the melee ragebot holds the spot behind them")
			end
		end
		if live then
			step("reload", Combat.updateReload, gs)
			step("instantReload", Combat.updateInstantReload, gs)
			step("movement", Combat.updateMovement, gs)
			-- the full list: calibration needs "nobody near", which the hub's empty target list would fake
			step("voidCalibrate", Combat.updateAutoCalibrate, enemies, gs)
		end
		step("camera", Self.cameraStep)
		if live then
			step("aa", Combat.updateAA)
		end
		step("world", Vis.worldApply)
		step("worldExtras", Vis.worldExtrasTick)
		step("postFx", Vis.postFxApply)
		step("worldFx", Vis.fxTick)
		step("shotFx", Vis.shotFxTick)
		if Game.frameId % 3 == 0 then
			step("viewmodel", Vis.viewmodelApply)
		end
		if Game.frameId % 6 == 3 then
			step("chams", Vis.chamsTick)
		end
		-- v5 perf: the locked-cosmetic sweep walks the customize UI — 2 Hz is plenty (it ran every frame)
		if Game.frameId % 30 == 0 then
			step("skins", Skins.sweepLocked)
		end
		if (S.menuOpen or HUD.editMode) and cfg.espHideInMenu then
			-- Drawing objects render above every GUI; keep the menu readable
			if not S.espHidden then
				S.espHidden = true
				step("esp", Self.espHideStep)
				Vis.slotsShown, Vis.arrowsShown, Vis.radarShown = 0, 0, 0
			end
		else
			S.espHidden = false
			step("overlay", Self.overlayStep)
			-- the ESP runs EVERY frame at every tier: skipping frames made the boxes trail moving
			-- players (the "laggy visuals"); the tiers drop the extras (skeleton, 3D, tracers,
			-- highlight count, half the LOS rays) inside drawEsp instead
			-- the lobby is 30 people you can't fight: no boxes, chams or radar dots there unless asked for
			-- (the shooting range counts as live, so range bots keep theirs)
			local espList = if S.featuresPaused and not cfg.espLobby then Self.EMPTY else enemies
			step("esp", Vis.drawEsp, espList)
			step("espGhosts", Vis.ghostStep, espList)
			if S.perfTier < 2 then
				step("radar", Vis.drawRadar, espList)
			end
		end
		step("hud", HUD.tick, dt, enemies, gs)
		step("menu", Menu.tick, enemies)
		if Game.frameId % 30 == 7 then
			step("util", Game.util.tick)
		end
		step("aimbot", Self.aimbotStep, targets)
		-- v5.2 slow lane (~every 5 s at 60 fps): game-contract re-checks + the daemon version poll
		if Game.frameId % 300 == 150 then
			step("adapt", Game.adapt.tick)
		elseif Game.frameId % 300 == 0 then
			step("update", Game.adapt.updateTick)
		end
		local spent = os.clock() - t0
		S.frameMs = spent * 1000
		step("perf", Self.perf, S.frameMs)
		step("integrity", Self.integrity)
	end))

	genv().CenterraUnload = function()
		S.alive = false
		pcall(Game.util.stop)
		pcall(Combat.clearLock)
		S.firing = false
		S.lmbDown = false
		table.clear(keyDown) -- a key held through the unload must not read as "down" to the next inject
		pcall(Combat.stopAutokill, "unload")
		pcall(Combat.magicRelease, "unload")
		pcall(Combat.defenseReturn, "unload")
		pcall(Combat.meleeRageRelease, "unload")
		-- the releases above are deferred to the next commit, which will never run: go home now
		pcall(Combat.body.goHome, "unload")
		pcall(Combat.padClear)
		S.autokill.state = "idle"
		S.defenseHiding = false
		pcall(Combat.releaseFire)
		pcall(Combat.pinCamera, false)
		pcall(Combat.thirdPerson, false)
		pcall(Combat.aaBody, false)
		-- the server hears the real device again: the namecall branch stops rewriting, the game re-sends
		S.deviceControls, S.deviceVR = nil, false
		if S.deviceMode ~= nil and S.deviceMode ~= "Real" then
			S.deviceMode = "Real"
			log("INFO", "device: Real")
			pcall(Game.asGame, FighterController._ReplicateControls, FighterController)
		end
		pcall(Combat.restoreWeaponStats)
		pcall(Input.setAds, false)
		pcall(Input.setRightMouse, false)
		S.adsHeld = false
		pcall(Vis.worldRestore)
		pcall(Vis.worldExtrasRestore)
		pcall(Vis.postFxRestore)
		pcall(Vis.fxRestore)
		pcall(Vis.viewmodelRestore)
		pcall(Net.uninstall)
		pcall(Shots.export)
		pcall(Vis.destroyAll)
		pcall(Menu.destroy)
		pcall(HUD.destroy)
		pcall(function()
			if Menu.openerGui then
				Menu.openerGui:Destroy()
				Menu.openerGui = nil
				Menu.openerBtn = nil
			end
		end)
		pcall(function()
			game:GetService("ContextActionService"):UnbindAction("CenterraMenu")
		end)
		table.clear(logListeners)
		pcall(function()
			-- v5.2: the whole noclip teardown — the BodyVelocity float used to survive an unload
			-- (restoreAll only put the collisions back) and kept pushing the character afterwards
			if S.noclip then
				if type(S.noclip.shutdown) == "function" then
					S.noclip.shutdown()
				else
					S.noclip.restoreAll()
				end
			end
		end)
		pcall(function()
			-- an open bind capture must not keep its InputBegan / Heartbeat listeners alive
			if type(Input.cancelCapture) == "function" then
				Input.cancelCapture()
			end
		end)
		for _, c in ipairs(connections) do
			pcall(c.Disconnect, c)
		end
		table.clear(connections)
		pcall(function()
			CameraController:Freeze(false)
			CameraController:SetThirdPersonOverride(nil)
			CameraController:SetExternalFOVOffset("centerra", 0)
			S.fovShown = 0
		end)
		-- the mouse goes back to the game by itself: S.menuOpen is false now (the camera hook stops
		-- answering for the menu) and the camera writes its own cursor state on the next render step.
		-- Forcing LockCenter here used to lock the mouse in the lobby and on the game's own pages.
		S.menuOpen = false
		pcall(RunService.UnbindFromRenderStep, RunService, "centerra_menuMouse")
		pcall(function()
			if S.introGui then
				S.introGui:Destroy()
				S.introGui = nil
			end
		end)
		pcall(function()
			local pg = LP:FindFirstChild("PlayerGui")
			if pg then
				for _, ch in ipairs(pg:GetChildren()) do
					if OUR_GUI_NAMES[ch.Name] then
						pcall(ch.Destroy, ch)
					end
				end
			end
		end)
		-- a deliberate unload is remembered across the hop (the teleport payload honours the marker)
		pcall(function()
			if EXEC.writefile then
				EXEC.mkdirs(DATA.dir)
				EXEC.writefile(DATA.unloaded, tostring(os.time()))
			end
		end)
		pcall(function()
			local blur = Lighting:FindFirstChild("CenterraBlur")
			if blur then
				blur:Destroy()
			end
		end)
		local g = genv()
		if type(g.VoltMCP_Unloaders) == "table" then
			g.VoltMCP_Unloaders.centerra = nil
		end
		g.CenterraUnload = nil
		log("INFO", "unloaded")
	end
	genv().VoltMCP_Unloaders.centerra = genv().CenterraUnload

	log("INFO", ("ready — v%s on %s | enemies: %d | Drawing: %s | hooks: %s"):format(VERSION, EXECUTOR_NAME, #Game.enemies(), tostring(EXEC.Drawing ~= nil), tostring(EXEC.hookfunction ~= nil)))
	-- executor compatibility: say what this executor cannot do, once, in plain words
	S.compat = EXEC.report()
	if #S.compat > 0 then
		for _, line in ipairs(S.compat) do
			log("WARN", "executor: " .. line)
		end
		-- v5.2: a missing namecall hook or identity control costs more combat than a missing file API
		if not EXEC.caps.hooks or not EXEC.caps.files or not EXEC.caps.namecall or (not EXEC.caps.identity and not EXEC.caps.trampoline) then
			notify(("%s: %d feature%s unavailable. Details in Config → About."):format(EXECUTOR_NAME, #S.compat, if #S.compat == 1 then "" else "s"), 6, "warn")
		end
	end
	pcall(Self.intro)
	-- v5.2: a new RIVALS build since the last verified load is announced, then every game contract is
	-- checked (again 4 s later with the self-test, and from the loop while any stays pending)
	pcall(Game.adapt.checkBuild)
	pcall(Game.adapt.verify, "load")
	task.delay(4, function()
		-- S is shared with a later inject of this Lua state (state reuse), so S.alive alone cannot
		-- tell "this instance is still the live one": the generation check can
		if S.alive and not Game.superseded() then
			pcall(Game.adapt.verify, "post-load")
			pcall(Self.test)
		end
	end)
	-- first daemon version poll after the load settled (yields; never on the render thread)
	task.delay(20, function()
		if S.alive and not Game.superseded() and cfg.autoUpdate then
			pcall(Game.adapt.checkUpdate, false)
		end
	end)
	if cfg.rapidFire and not cfg.autoShootServerSafe and not cfg.autoShootCooldownSync and cfg.rapidFireMult < 0.6 then
		-- with the item's own cooldown stamp gating every pull the cadence is capped anyway — this
		-- only bites when both server-safe and the stamp gate are off
		log("WARN", ("rapid fire ×%.2f with server-safe cadence AND cooldown-stamp gating off — auto-shot pulls faster than the server accepts"):format(cfg.rapidFireMult))
	end
	notify(("centerra %sv%s loaded · %s opens the menu"):format(if S.edition == "max" then "Max " else "", S.shownVersion, Input.keyLabel(cfg.menuKey)))
	-- the menu comes up by itself on load instead of a silent execute with the UI closed. The same
	-- path the key handler takes (rebuild if the GUI is gone, then open), a beat later so the load
	-- toasts, the intro and the camera hooks are done first.
	task.delay(1, function() end)
	if Configs.firstRun then
		-- a brand-new install starts ESP only (DEFAULTS): say where the rest is
		task.delay(3, function()
			if S.alive then
				notify("ESP is on. Everything else is set up and off — switch it on in its tab, or load a config in Config", 8, "info")
			end
		end)
	end
	-- a trigger that is silently throttled is the worst kind of "it doesn't shoot": say so at load
	if (cfg.autoShootChance or 100) < 100 then
		log("WARN", ("auto shoot: shot chance %d %% — %d of 10 cooldown windows are skipped on purpose (Silent → Auto shoot → Shot chance)"):format(cfg.autoShootChance, 10 - math.floor(cfg.autoShootChance / 10)))
		notify(("auto shoot fires only %d %% of the time (Shot chance slider)"):format(cfg.autoShootChance), 5, "warn")
	end
	if cfg.autoShootMinHitChance > 0 then
		log("INFO", ("auto shoot: minimum hit chance %d %% — pulls below it are held"):format(cfg.autoShootMinHitChance))
	end
	-- silent aim off only matters when a switch that needs it is on (a legit profile has none): no
	-- silent aim = no lock, no trigger, no rage; lock-only-while-firing + a small FOV = "it never locks"
	if (Configs.legitForced or 0) > 0 then
		log("INFO", ("[legit:lock] %d rage switch(es) from the autosave forced off (config legit)"):format(Configs.legitForced))
	end
	if Configs.warnOnLoad(cfg) then
		local dep = Configs.silentDependent(cfg)
		log("WARN", ("silent aim is OFF — %s does nothing until it is on (Silent aim → General)"):format(tostring(dep)))
		notify(("silent aim is OFF — %s won't work"):format(tostring(dep)), 6, "warn")
	elseif not cfg.silentAim then
		log("INFO", ("[legit:warn-suppressed] silent aim off, nothing needs it (config %s, rage %s)"):format(if Configs.active ~= "" then Configs.active else "none", cfg.ragePosition))
	elseif Configs.rageOn(cfg) and cfg.silentOnlyFiring then
		-- the circle no longer limits rage (it targets 360° by itself); only "while firing" still does
		log("INFO", "silent lock is limited: only while firing — rage wants lock-always")
	end
	if Configs.active ~= "" then
		log("INFO", ("config: %s%s"):format(Configs.active, if Configs.startup == Configs.active then " (loads on start)" else ""))
	end
	genv().CenterraLoadedAt = os.clock()
	genv().CenterraLoadingSince = nil
end

local initOk, initErr = pcall(genv().CenterraInit)
genv().CenterraLoadingSince = nil
if not initOk and string.find(tostring(initErr), "superseded by a newer inject", 1, true) then
	-- a later inject took over while this one was still waiting on game modules: nothing failed
	warn("[centerra] " .. tostring(initErr))
	initOk = true
end
if not initOk then
	-- rethrowing makes the executor report "injection failed" and leaves the user with nothing on screen
	warn("[centerra] " .. tostring(initErr))
	pcall(function()
		game:GetService("StarterGui"):SetCore("SendNotification", {
			Title = "centerra",
			Text = "failed to start: " .. string.sub(tostring(initErr), 1, 90),
			Duration = 10,
		})
	end)
	pcall(function()
		local lp = game:GetService("Players").LocalPlayer
		local parent = (lp and (lp:FindFirstChild("PlayerGui") or lp:FindFirstChildOfClass("PlayerGui"))) or game:GetService("CoreGui")
		local gui = Instance.new("ScreenGui")
		gui.Name = "CenterraOpener"
		gui.ResetOnSpawn = false
		gui.IgnoreGuiInset = true
		gui.DisplayOrder = 1500
		gui.Parent = parent
		local b = Instance.new("TextButton")
		b.AnchorPoint = Vector2.new(0, 1)
		b.Position = UDim2.new(0, 12, 1, -12)
		b.Size = UDim2.fromOffset(340, 84)
		b.BackgroundColor3 = Color3.fromRGB(24, 14, 14)
		b.BorderSizePixel = 0
		b.TextColor3 = Color3.fromRGB(255, 220, 220)
		b.TextSize = 14
		b.TextWrapped = true
		b.Text = "centerra failed to start\n" .. string.sub(tostring(initErr), 1, 140)
		b.Parent = gui
		local okF, font = pcall(function()
			return Enum.Font.BuilderSansBold
		end)
		b.Font = if okF and font then font else Enum.Font.GothamBold
	end)
end



task.spawn(function()
	local t0 = os.clock()
	while os.clock() - t0 < 45 do
		local g = (type(getgenv) == "function" and select(2, pcall(getgenv))) or _G
		if type(g) == "table" and type(g.CenterraState) == "table" and type(g.CenterraState.cfg) == "table" then
			if type(g._CenterraCfgFallback) == "table" then
				for k, v in pairs(g._CenterraCfgFallback) do
					g.CenterraState.cfg[k] = v
				end
				g._CenterraCfgFallback = nil
				print("[centerra] UI toggles synced into combat cfg")
			end
			print("[centerra] combat cfg online")
			return
		end
		task.wait(0.2)
	end
end)
